window.ETEC_DATA = {"examDateIso": "2026-12-04", "defaultStartIso": "2026-11-19", "areas": [{"id": "prog", "title": "💻 1. Programação, Algoritmos & Engenharia", "recommendedDay": 2}, {"id": "bd", "title": "🗄️ 2. Banco de Dados, SQL, DER & 1FN", "recommendedDay": 6}, {"id": "design", "title": "🎨 3. Design Digital, Cores, Vetor & Gestalt", "recommendedDay": 8}, {"id": "web_redes", "title": "🌐 4. Web (HTML/CSS/Cookies), Redes & Linux", "recommendedDay": 9}, {"id": "ingles_etica", "title": "🌍 5. Inglês Técnico & Ética CPS", "recommendedDay": 11}, {"id": "mtec_base", "title": "🎓 6. Base Comum M-Tec (Port, Hist, Mat, Quím, Fís)", "recommendedDay": 13}], "vfStatements": [{"id": 1, "area": "prog", "topic": "Casting Explícito", "text": "Em C/Java, fazer `(int) 8.95` arredonda automaticamente o número para 9.", "isTrue": false, "verdictTitle": "❌ É FAKE DA BANCA!", "explain": "Type casting explícito para inteiro TRUNCA (corta fora) a parte decimal! `(int) 8.95` vira `8`, nunca arredonda para `9`."}, {"id": 2, "area": "prog", "topic": "Tipo Primitivo char", "text": "O tipo primitivo `char` é indicado para armazenar exatamente um único caractere, como `'A'` ou `'S'`.", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "`char` guarda 1 caractere individual; `bool` guarda apenas `true`/`false` e `string` guarda sequências de texto."}, {"id": 3, "area": "prog", "topic": "DIV vs MOD", "text": "A expressão `17 MOD 5` resulta em 3, porque `MOD` devolve o quociente inteiro da divisão.", "isTrue": false, "verdictTitle": "❌ É FAKE DA BANCA!", "explain": "A banca inverteu! `DIV` devolve o quociente inteiro (`17 DIV 5 = 3`). `MOD` devolve o RESTO (`17 MOD 5 = 2`)."}, {"id": 4, "area": "prog", "topic": "Matriz Diagonal", "text": "Em uma matriz quadrada `M[i][j]` indexada a partir de 0, a diagonal principal é formada pelos elementos em que `i == j`.", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "Os índices da diagonal principal têm linha igual à coluna: `M[0][0]`, `M[1][1]`, `M[2][2]`. A secundária usa `i + j == N - 1`."}, {"id": 5, "area": "prog", "topic": "Pilha LIFO vs Fila", "text": "Em uma estrutura de Pilha (Stack), o primeiro elemento inserido (PUSH) é sempre o primeiro a ser removido pelo POP.", "isTrue": false, "verdictTitle": "❌ É FAKE DA BANCA!", "explain": "Pegadinha clássica! Primeiro a entrar = primeiro a sair é **FILA (FIFO)**. A **Pilha é LIFO**: o ÚLTIMO que entrou é o primeiro a sair!"}, {"id": 6, "area": "prog", "topic": "Laço do-while", "text": "Como testa a condição apenas ao final, a estrutura `do...while` garante que o bloco interno execute pelo menos uma vez.", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "Mesmo que a condição já seja falsa no começo, o `do...while` executa 1 volta inteira antes de verificar."}, {"id": 7, "area": "prog", "topic": "Frameworks", "text": "Laravel (PHP), Angular (TypeScript), React Native (Mobile) e Creative Commons são todos exemplos válidos de frameworks.", "isTrue": false, "verdictTitle": "❌ É FAKE DA BANCA!", "explain": "Intruso clássico da DS 2025! **Creative Commons** (assim como Adobe Creative Cloud) NÃO é framework — é uma licença de direitos autorais!"}, {"id": 8, "area": "prog", "topic": "Software Livre vs Freeware", "text": "Todo Software Livre permite estudar, modificar e redistribuir seu código-fonte, podendo inclusive ser comercializado.", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "Software Livre refere-se às 4 liberdades de código aberto, não necessariamente preço zero. Já Freeware é grátis com código fechado!"}, {"id": 9, "area": "prog", "topic": "Scrum Master", "text": "No Scrum, o Scrum Master atua como gerente tradicional que distribui tarefas individuais e decide sozinho o código do time.", "isTrue": false, "verdictTitle": "❌ É FAKE DA BANCA!", "explain": "O Scrum Master é um **facilitador** que protege a equipe e remove impedimentos. Quem prioriza o backlog é o Product Owner, e o time é auto-organizável."}, {"id": 10, "area": "prog", "topic": "Pilares da POO", "text": "Os quatro pilares clássicos da Programação Orientada a Objetos são Abstração, Encapsulamento, Herança e Polimorfismo.", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "Cuidado apenas quando a banca tenta misturar Classe, Objeto ou Atributo como se fossem pilares!"}, {"id": 11, "area": "bd", "topic": "SQL DDL vs DQL", "text": "Na divisão cobrada pela FAT, `CREATE`, `ALTER` e `DROP` pertencem à DQL, enquanto `SELECT` pertence à DDL.", "isTrue": false, "verdictTitle": "❌ É FAKE DA BANCA!", "explain": "Inversão clássica! **DDL** (Definição) = `CREATE, ALTER, DROP`; **DQL** (Consulta) = `SELECT`; **DML** (Dados) = `INSERT, UPDATE, DELETE`."}, {"id": 12, "area": "bd", "topic": "DROP vs DELETE", "text": "O comando `DROP TABLE alunos` remove a tabela inteira e sua estrutura do banco, diferente de `DELETE`, que apaga linhas.", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "`DROP` (DDL) destrói a estrutura; `DELETE` (DML) remove registros mantendo as colunas intactas."}, {"id": 13, "area": "bd", "topic": "SQL COUNT()", "text": "A sintaxe `SELECT * FROM pedidos WHERE COUNT(status) = 'Pago'` está correta para contar pedidos pagos.", "isTrue": false, "verdictTitle": "❌ É FAKE DA BANCA!", "explain": "`COUNT(*)` **NUNCA** vai dentro do `WHERE`! O certo é `SELECT COUNT(*) FROM pedidos WHERE status = 'Pago'`."}, {"id": 14, "area": "bd", "topic": "1ª Forma Normal (1FN)", "text": "Uma tabela com a coluna `telefones` guardando `'119999-0000, 118888-1111'` na mesma célula viola a 1ª Forma Normal (1FN).", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "A **1FN** exige exclusivamente **valores atômicos (indivisíveis)** em cada célula — múltiplos telefones pedem outra tabela com FK!"}, {"id": 15, "area": "bd", "topic": "Modelo Conceitual vs Físico", "text": "O Modelo Físico é a primeira etapa da modelagem de dados e usa retângulos e losangos no DER totalmente livres de SGBD.", "isTrue": false, "verdictTitle": "❌ É FAKE DA BANCA!", "explain": "Inversão de fases! Quem usa DER abstrato e independe de SGBD é o **Modelo Conceitual**. O **Físico** é o script `CREATE TABLE` real no SGBD."}, {"id": 16, "area": "bd", "topic": "Chave Primária e FK", "text": "Em um relacionamento `1:N` (Um para Muitos), a Chave Estrangeira (FK) sempre fica na tabela do lado `N` (Muitos).", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "Por exemplo, 1 Turma tem N Alunos -> `id_turma` (FK) vai dentro de `ALUNOS`."}, {"id": 17, "area": "bd", "topic": "Atributo Derivado", "text": "A coluna `idade`, calculada dinamicamente a partir da `data_nascimento`, é classificada no DER como um atributo derivado.", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "Atributo derivado é obtido por cálculo sobre outros atributos já armazenados (ex.: idade ou valor total)."}, {"id": 18, "area": "bd", "topic": "TCL vs DCL", "text": "Os comandos `GRANT` e `REVOKE` pertencem à TCL e servem para confirmar ou desfazer transações financeiras.", "isTrue": false, "verdictTitle": "❌ É FAKE DA BANCA!", "explain": "`GRANT` e `REVOKE` são **DCL** (controle de permissões). Quem confirma ou desfaz transações (`COMMIT`/`ROLLBACK`) é a **TCL**!"}, {"id": 19, "area": "bd", "topic": "Bancos NoSQL", "text": "Bancos NoSQL orientados a documentos (como o MongoDB) trabalham com esquema flexível (schema-less) em formato JSON/BSON.", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "NoSQL sacrifica esquema rígido de tabelas para ganhar escalabilidade horizontal e flexibilidade de documentos."}, {"id": 20, "area": "design", "topic": "RGB vs CMYK", "text": "O padrão CMYK é uma síntese aditiva de luz utilizada obrigatoriamente para telas digitais e monitores.", "isTrue": false, "verdictTitle": "❌ É FAKE DA BANCA!", "explain": "Trocaram! **RGB** é síntese aditiva de **luz** (telas/monitores). **CMYK** é síntese subtrativa de **tinta** (impressão gráfica)!"}, {"id": 21, "area": "design", "topic": "Imagem Vetorial SVG", "text": "Uma logomarca salva em `.SVG` ou `.PDF` vetorial pode ser ampliada em 800% sem perder nitidez nem pixelar.", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "Imagens vetoriais são construídas por equações matemáticas (pontos e curvas), não por grade fixa de pixels."}, {"id": 22, "area": "design", "topic": "JPEG vs Vetor", "text": "Arquivos `.JPEG`, `.PNG` e `.BMP` são formatos vetoriais puros indicados para painéis gigantes sem risco de serrilhamento.", "isTrue": false, "verdictTitle": "❌ É FAKE DA BANCA!", "explain": "JPEG, PNG e BMP são imagens **Bitmap / Raster** (formadas por pixels)! Se ampliar além da resolução original, ficam serrilhadas."}, {"id": 23, "area": "design", "topic": "Padrões de Cores", "text": "RGB, CMYK e Hexadecimal são sistemas válidos de representação de cores na computação e no design gráfico.", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "Cuidado na prova com intrusos falsos como 'CSS', 'Primária' ou 'Raster' misturados nessa lista!"}, {"id": 24, "area": "design", "topic": "Gestalt — Proximidade", "text": "Pela lei da Proximidade na Gestalt, colocar o rótulo 'E-mail' bem perto do seu campo faz o usuário entendê-los como um grupo.", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "Elementos fisicamente próximos são percebidos automaticamente como pertencentes à mesma unidade lógica."}, {"id": 25, "area": "design", "topic": "Gestalt — Fechamento vs Semelhança", "text": "Quando o cérebro completa mentalmente lacunas em uma figura com linhas interrompidas, ocorre o princípio da Semelhança.", "isTrue": false, "verdictTitle": "❌ É FAKE DA BANCA!", "explain": "Completar espaços vazios na forma chama-se **Fechamento**! **Semelhança** é agrupar itens pela mesma cor/forma/tamanho."}, {"id": 26, "area": "design", "topic": "Fontes Script", "text": "Fontes do estilo Script (que imitam letra cursiva/à mão) devem ser escolhidas para longos textos técnicos em artigos científicos.", "isTrue": false, "verdictTitle": "❌ É FAKE DA BANCA!", "explain": "Fontes **Script** cansam a vista em parágrafos longos — devem ficar restritas a títulos artísticos, logotipos e convites!"}, {"id": 27, "area": "design", "topic": "Heurística de Nielsen", "text": "Usar o ícone de um carrinho de compras num e-commerce aplica a heurística de equivalência entre o sistema e o mundo real.", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "O sistema fala a linguagem e usa metáforas familiares do cotidiano do usuário."}, {"id": 28, "area": "design", "topic": "Cores Complementares", "text": "No Círculo Cromático, cores que ficam frente a frente (em lados opostos) chamam-se complementares e geram máximo contraste.", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "Opostas = Complementares (alto contraste). Vizinhas = Análogas (harmonia suave). 3 equidistantes = Tríade."}, {"id": 29, "area": "web_redes", "topic": "Cookies — Armazenamento", "text": "Cookies Web são arquivos grandes armazenados diretamente nos servidores em nuvem da hospedagem do site.", "isTrue": false, "verdictTitle": "❌ É FAKE DA BANCA!", "explain": "A PEGADINHA Nº 1 DA DS 2025! Cookies são arquivos **pequenos (~4 KB) salvos LOCALMENTE no navegador do usuário**, JAMAIS na nuvem!"}, {"id": 30, "area": "web_redes", "topic": "Link target='_blank'", "text": "Na tag HTML `<a>`, o atributo `target=\"_blank\"` faz o link abrir em uma nova aba ou janela do navegador.", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "`_blank` abre em nova aba; `_self` (padrão) abre na própria aba atual."}, {"id": 31, "area": "web_redes", "topic": "HTML Tag <tr> vs <td>", "text": "Em tabelas HTML, `<td>` define uma linha horizontal inteira da tabela e `<tr>` define cada célula individual.", "isTrue": false, "verdictTitle": "❌ É FAKE DA BANCA!", "explain": "Inversão direta! `<tr>` = *Table Row* (LINHA); `<td>` = *Table Data* (CÉLULA comum); `<th>` = cabeçalho."}, {"id": 32, "area": "web_redes", "topic": "Formulário POST vs GET", "text": "Formulários com login e senha devem usar `method=\"POST\"` em vez de `GET` para não expor os dados na barra de URL.", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "`GET` anexa os campos direto no link após `?`; `POST` envia no corpo da requisição HTTP."}, {"id": 33, "area": "web_redes", "topic": "HTML5 Semântico", "text": "As tags `<header>`, `<nav>`, `<main>`, `<section>` e `<footer>` são semânticas, enquanto `<div>` e `<span>` são genéricas.", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "A M-Tec 2022 e a DS 2019 cobram que `<div>` e `<span>` NÃO possuem significado semântico próprio."}, {"id": 34, "area": "web_redes", "topic": "Protocolos de E-mail", "text": "O protocolo SMTP sincroniza mensagens mantendo pastas no servidor, enquanto o IMAP serve apenas para enviar e-mails.", "isTrue": false, "verdictTitle": "❌ É FAKE DA BANCA!", "explain": "Trocaram tudo! **SMTP = ENVIA** e-mail; **POP3 = baixa e apaga** do servidor; **IMAP = sincroniza pastas** no servidor!"}, {"id": 35, "area": "web_redes", "topic": "Topologia Barramento", "text": "Na topologia em Barramento (Bus), se o cabo central único (backbone) se romper, toda a rede para de se comunicar.", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "Já na topologia em **Estrela** (Switch central), romper o cabo de uma estação derruba apenas aquela estação."}, {"id": 36, "area": "web_redes", "topic": "Diretórios Linux", "text": "Na hierarquia de pastas do Linux, `/mkdir`, `/ls`, `/rm` e `/cd` são diretórios padrão obrigatórios do sistema.", "isTrue": false, "verdictTitle": "❌ É FAKE DA BANCA!", "explain": "Pegadinha da INFO 2025! `mkdir`, `ls`, `rm` e `cd` são **COMANDOS**, não pastas! Pastas reais: `/bin, /etc, /home, /lib, /usr, /var, /tmp`."}, {"id": 37, "area": "web_redes", "topic": "Contêineres vs VM", "text": "Contêineres Docker são mais leves que Máquinas Virtuais tradicionais porque compartilham o mesmo Kernel do SO hospedeiro.", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "VMs emulam hardware e carregam um Sistema Operacional convidado inteiro; contêineres isolam processos mantendo o mesmo Kernel."}, {"id": 38, "area": "web_redes", "topic": "Binário e Hexadecimal", "text": "O número decimal `250` corresponde a `F0` em Hexadecimal, enquanto `255` equivale a `11111111` em binário.", "isTrue": false, "verdictTitle": "❌ É FAKE DA BANCA!", "explain": "Cuidado na conta! `255 = 11111111₂` está certo, mas `250 ÷ 16` = `15 (F)` com resto **`10 (A)`**, logo `250₁₀ =` **`FA₁₆`** (e não `F0`)!"}, {"id": 39, "area": "web_redes", "topic": "Armazenamento SSD", "text": "Discos SSD armazenam dados em chips de memória Flash NAND sem partes móveis mecânicas, resistindo melhor a choques que HDDs.", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "Sem discos giratórios nem agulha mecânica, o SSD é mais rápido, silencioso e resistente a impactos."}, {"id": 40, "area": "ingles_etica", "topic": "Falso Cognato data", "text": "Em manuais técnicos de TI em inglês, o termo `data` significa 'datas de calendário', enquanto 'dados' traduz-se como `facts`.", "isTrue": false, "verdictTitle": "❌ É FAKE DA BANCA!", "explain": "Falso cognato clássico! **`data`** = **dados** (ex.: *Data Dictionary*, *Big Data*). Data de calendário é *date*!"}, {"id": 41, "area": "ingles_etica", "topic": "Vocabulário troubleshooting", "text": "Os termos técnicos `troubleshooting` e `outcomes` significam, respectivamente, 'resolução de problemas' e 'resultados/desfechos'.", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "Ambos caíram literalmente nos enunciados da DS 2025 e do Simulado FAT!"}, {"id": 42, "area": "ingles_etica", "topic": "Superlativo bad -> worst", "text": "Em inglês, `worse` e `worst` são formas comparativa e superlativa irregulares derivadas do adjetivo `bad` (ruim/mau).", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "Caiu na M-Tec 2022 Q7: `bad → worse → the worst` (o pior)."}, {"id": 43, "area": "ingles_etica", "topic": "Vocabulário daunting", "text": "Na frase 'Legacy bugs feel daunting', o adjetivo `daunting` é sinônimo de 'simples/divertido' (`easy`).", "isTrue": false, "verdictTitle": "❌ É FAKE DA BANCA!", "explain": "Caiu na M-Tec 2022 Q8! **`daunting`** significa **assustador / intimidador / desanimador** (*intimidating*)."}, {"id": 44, "area": "ingles_etica", "topic": "Sufixos -able / -ive", "text": "Os sufixos `-able` (ex.: `debatable`, `scalable`) e `-ive` (ex.: `positive`, `interactive`) formam adjetivos em inglês.", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "Caiu na M-Tec 2022 Q9: `-able/-ible` e `-ive` transformam verbos/raízes em adjetivos qualificativos."}, {"id": 45, "area": "ingles_etica", "topic": "Ética e Bem Comum", "text": "Na prova de Ética do CPS, ações sociais feitas exclusivamente para ganhar seguidores e vaidade em redes sociais exemplificam ética plena.", "isTrue": false, "verdictTitle": "❌ É FAKE DA BANCA!", "explain": "Ética profissional visa ao **bem comum real**, transparência e responsabilidade social — nunca interesse egoísta ou vaidade!"}, {"id": 46, "area": "ingles_etica", "topic": "Lixo Eletrônico (e-waste)", "text": "Placas eletrônicas e baterias possuem metais pesados e devem ir para coleta especializada/logística reversa, nunca ao lixo comum.", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "Chumbo, mercúrio e cádmio contaminam o solo e lençóis freáticos se descartados no lixo doméstico."}, {"id": 47, "area": "ingles_etica", "topic": "LGPD e Minimização", "text": "Pela ética e LGPD, sistemas devem coletar apenas os dados estritamente necessários à finalidade informada ao usuário.", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "Princípio da necessidade e transparência: proteção contra coleta abusiva e vazamentos."}, {"id": 48, "area": "mtec_base", "topic": "Barroco Cultismo x Conceptismo", "text": "No Barroco, o Cultismo consiste no jogo de ideias e raciocínio lógico, enquanto o Conceptismo foca no jogo rebuscado de palavras.", "isTrue": false, "verdictTitle": "❌ É FAKE DA BANCA!", "explain": "A banca inverteu na M-Tec 2022 Q1! **Cultismo** = jogo de **PALAVRAS**; **Conceptismo** = jogo de **IDEIAS e lógica**!"}, {"id": 49, "area": "mtec_base", "topic": "Paradoxo vs Antítese", "text": "Enquanto a Antítese apenas aproxima palavras opostas ('dia e noite'), o Paradoxo cria uma contradição lógica na mesma ideia.", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "Ex.: 'É ferida que dói e não se sente' une ideias logicamente incompatíveis -> Paradoxo!"}, {"id": 50, "area": "mtec_base", "topic": "Paleolítico vs Neolítico", "text": "No período Paleolítico os humanos desenvolveram a agricultura e fundaram aldeias sedentárias fixas.", "isTrue": false, "verdictTitle": "❌ É FAKE DA BANCA!", "explain": "Isso ocorreu na **Revolução Neolítica** (Pedra Polida)! No **Paleolítico**, os grupos eram **nômades** vivendo de caça, pesca e coleta."}, {"id": 51, "area": "mtec_base", "topic": "Dízima Periódica (Q)", "text": "Toda dízima periódica (como `0,333... = 1/3`) pertence ao conjunto dos Números Racionais (`ℚ`), não dos Irracionais (`𝕀`).", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "Se pode virar fração `a/b`, é Racional (`ℚ`)! Irracionais (`𝕀`) são decimais infinitos **NÃO periódicos** como `π` e `√2`."}, {"id": 52, "area": "mtec_base", "topic": "Contagem sem Zero na 1ª Casa", "text": "Com o conjunto `{0, 1, 2, 3, 4, 5}`, podemos formar `6 × 5 × 4 = 120` números naturais distintos de 3 algarismos.", "isTrue": false, "verdictTitle": "❌ É FAKE DA BANCA!", "explain": "Pegadinha da M-Tec Q23! O **`0` não pode ir na primeira casa** (centena)! Logo são **`5 × 5 × 4 = 100`** números!"}, {"id": 53, "area": "mtec_base", "topic": "Química — Condutividade Iônica", "text": "Compostos iônicos (como NaCl) não conduzem eletricidade no estado sólido, mas conduzem quando fundidos ou dissolvidos em água.", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "No sólido os íons estão presos no cristal; derretido ou em água, os íons ficam livres para conduzir!"}, {"id": 54, "area": "mtec_base", "topic": "Química — Massa Molecular", "text": "Usando C=12, H=1 e O=16, a massa molecular do etanol (`C₂H₅OH`) vale 46 u e a do ácido acético (`C₂H₄O₂`) vale 60 u.", "isTrue": true, "verdictTitle": "✅ É VERDADE!", "explain": "`2(12)+6(1)+16 = 46 u` e `2(12)+4(1)+2(16) = 60 u` — caiu na M-Tec 2022 Q17!"}, {"id": 55, "area": "mtec_base", "topic": "Física — Óptica das Cores", "text": "Um tomate maduro iluminado apenas por luz verde monocromática continua sendo enxergado vermelho pelos olhos humanos.", "isTrue": false, "verdictTitle": "❌ É FAKE DA BANCA!", "explain": "Pigmento vermelho absorve luz verde e não tem luz vermelha para refletir! Logo vemos o tomate **PRETO**!"}], "flashcards": [{"front": "Quais são os 4 moldes clássicos de questões da Fundação FAT?", "back": "1) Tabela I, II e III com inversão ou absurdo técnico. 2) Lista com um item intruso. 3) Definição direta no enunciado. 4) Micro-execução (matriz, fatorial, binário, pilha).", "tag": "00_Moldes_FAT"}, {"front": "Como identificar a pegadinha mais comum nas tabelas I, II e III da FAT?", "back": "A banca troca definições entre duas linhas vizinhas (ex: DDL com DQL, SMTP com IMAP) ou insere um absurdo disfarçado (ex: Cookie na nuvem, Notepad como IDE).", "tag": "00_Moldes_FAT"}, {"front": "O que é um Framework e quais os 4 exemplos clássicos da prova?", "back": "Estrutura reutilizável de software para acelerar projetos. Exemplos: Laravel (PHP), React Native (Mobile), Angular (JS) e Bootstrap (UI).", "tag": "01_Programacao"}, {"front": "Quais são os dois \"intrusos\" famosos que a FAT coloca no meio da lista de frameworks?", "back": "Creative Commons (licença de uso) e Adobe Creative Cloud (suíte de design/multimídia).", "tag": "01_Programacao"}, {"front": "O que é Conversão Implícita (Type Coercion)?", "back": "Transformação automática de tipo pelo compilador/interpretador quando os tipos são compatíveis e sem perda de dados (ex: int para float).", "tag": "01_Programacao"}, {"front": "O que é Conversão Explícita (Casting)?", "back": "Conversão forçada manualmente pelo programador usando funções como int(), float() ou str().", "tag": "01_Programacao"}, {"front": "Existe \"Conversão Normal\" na teoria de tipos de dados?", "back": "Não! É um termo inventado pela banca para confundir com conversão implícita e explícita.", "tag": "01_Programacao"}, {"front": "O tipo char armazena valores true ou false?", "back": "Não! char guarda 1 caractere. Quem guarda true/false é o tipo lógico boolean.", "tag": "01_Programacao"}, {"front": "Quais são os principais tipos de dados primitivos?", "back": "int (inteiro), float (ponto flutuante/decimal), char (caractere único), string (texto) e boolean (true/false).", "tag": "01_Programacao"}, {"front": "Qual é o objetivo e a ação central do Teste de Mesa?", "back": "Verificar manualmente um algoritmo sem rodá-lo no PC para achar erros lógicos. A ação central é Executar Linha a Linha anotando cada variável.", "tag": "01_Programacao"}, {"front": "Em matrizes bidimensionais (ex: 3x3), onde começa o índice e qual é a Diagonal Principal?", "back": "Índices começam em [0][0]. Diagonal Principal são os elementos onde linha == coluna: M[0][0] + M[1][1] + M[2][2].", "tag": "01_Programacao"}, {"front": "Pegadinha na matriz: qual a diferença entre Diagonal Principal e Diagonal Secundária em M 3x3?", "back": "Principal: M[0][0]+M[1][1]+M[2][2]. Secundária (pegadinha): M[0][2]+M[1][1]+M[2][0].", "tag": "01_Programacao"}, {"front": "Na Tabela Verdade, quando P AND Q (P ∧ Q) é Verdadeiro?", "back": "Somente quando P e Q forem ambos Verdadeiros (V ∧ V = V). Em todos os outros casos é Falso.", "tag": "01_Programacao"}, {"front": "Na Tabela Verdade, quando P OR Q (P ∨ Q) é Falso?", "back": "Somente quando P e Q forem ambos Falsos (F ∨ F = F). Basta um Verdadeiro para resultar em V.", "tag": "01_Programacao"}, {"front": "O que faz o operador lógico NOT (¬) na Tabela Verdade?", "back": "Inverte o valor lógico da proposição: se for Verdadeiro vira Falso, se for Falso vira Verdadeiro.", "tag": "01_Programacao"}, {"front": "O que fazem os operadores DIV e MOD no Portugol?", "back": "DIV retorna o quociente inteiro da divisão (7 DIV 2 = 3). MOD retorna o resto inteiro da divisão (7 MOD 2 = 1).", "tag": "01_Programacao"}, {"front": "Como funciona a estrutura de dados Pilha (Stack) e suas operações?", "back": "Segue LIFO (Last In, First Out - último a entrar, primeiro a sair). PUSH insere no topo e POP remove do topo.", "tag": "01_Programacao"}, {"front": "Qual a diferença entre Pilha (LIFO) e Fila (FIFO)?", "back": "Na Pilha sai primeiro o último que entrou (LIFO). Na Fila sai primeiro o primeiro que entrou (FIFO).", "tag": "01_Programacao"}, {"front": "O que é Recursividade e quanto vale o fatorial 4!?", "back": "É quando uma função chama a si mesma para resolver subproblemas menores até um caso base. 4! = 4 x 3 x 2 x 1 = 24.", "tag": "01_Programacao"}, {"front": "Qual a diferença entre Editor de Código e Editor WYSIWYG?", "back": "Editor de Código (VS Code, Sublime) tem realce de sintaxe e autocompletar. WYSIWYG (Dreamweaver, Wix) monta páginas visualmente arrastando e soltando.", "tag": "01_Programacao"}, {"front": "Notepad (Windows) e TextEdit (Mac) são IDEs?", "back": "Não! São editores de texto simples sem recursos avançados. IDEs (Eclipse, Visual Studio, NetBeans) integram editor, compilador e depurador.", "tag": "01_Programacao"}, {"front": "Qual a diferença entre ferramentas de Build e ferramentas de Bundling?", "back": "Build automatiza compilação, testes, minificação e pacotes finais. Bundling empacota vários JS/CSS/imagens em menos arquivos para reduzir requisições HTTP.", "tag": "01_Programacao"}, {"front": "Para que servem os comandos branch, diff e merge no controle de versão (Git)?", "back": "branch cria um ramo paralelo na linha de desenvolvimento, diff compara versões e merge funde versões em um caminho único.", "tag": "01_Programacao"}, {"front": "O que é Software com Licença Open Source (Código Aberto)?", "back": "Disponibiliza acesso ao código-fonte permitindo modificar e redistribuir sob condições que promovem colaboração e transparência.", "tag": "01_Programacao"}, {"front": "Software Livre significa obrigatoriamente software gratuito?", "back": "Não! \"Livre\" refere-se à liberdade de executar, estudar, modificar o código-fonte e redistribuir, mesmo que cobrado.", "tag": "01_Programacao"}, {"front": "O que é EULA (End-User License Agreement)?", "back": "Contrato de Licença de Usuário Final que define os termos de uso, restrições e responsabilidades de um software.", "tag": "01_Programacao"}, {"front": "Qual a diferença entre Licença Proprietária e Licenciamento por Assinatura?", "back": "Proprietária fecha o código e proíbe alteração/redistribuição. Assinatura cobra pagamento recorrente (mensal/anual) pelo direito de uso.", "tag": "01_Programacao"}, {"front": "Quais são os 4 Pilares da Programação Orientada a Objetos (POO)?", "back": "Abstração, Encapsulamento, Herança e Polimorfismo. (Pegadinha: Atributos e Métodos são membros da classe, NÃO pilares!).", "tag": "01_Programacao"}, {"front": "Qual a diferença entre Requisito Funcional (RF) e Requisito Não Funcional (RNF)?", "back": "RF diz O QUE o sistema deve fazer (funções/regras). RNF diz COMO ele deve operar e atributos de qualidade (desempenho, segurança, portabilidade).", "tag": "01_Programacao"}, {"front": "O que é o Requisito Não Funcional de Portabilidade?", "back": "Facilidade com que o software pode ser transferido de um ambiente ou sistema computacional para outro e permanecer executável.", "tag": "01_Programacao"}, {"front": "Quais são as 5 características de bons requisitos de software?", "back": "Clareza, Testabilidade, Consistência, Rastreabilidade e Viabilidade. (Intrusos da prova: Ambiguidade, Inconsistência, Irrelevância).", "tag": "01_Programacao"}, {"front": "Qual é a pegadinha clássica sobre Estudo de Viabilidade Legal vs Operacional?", "back": "A banca chama de Viabilidade Legal o texto que fala de infraestrutura humana e capacidade operacional. Viabilidade Legal trata de leis e normas.", "tag": "01_Programacao"}, {"front": "Qual a ordem exata das etapas do Modelo em Cascata (Waterfall)?", "back": "Requerimento -> Projeto -> Construção -> Teste/Depuração -> Instalação -> Manutenção.", "tag": "01_Programacao"}, {"front": "No Scrum, o que são Sprint, Product Backlog e Daily Scrum?", "back": "Sprint é o ciclo/iteração (time-box). Product Backlog é a lista priorizada de funcionalidades. Daily Scrum é a reunião diária curta.", "tag": "01_Programacao"}, {"front": "O que é Programação em Par (Pair Programming) no XP?", "back": "Prática em que dois programadores trabalham juntos no mesmo código alternando papéis, melhorando revisão, detecção de falhas e manutenção.", "tag": "01_Programacao"}, {"front": "O que verifica o Teste de Unidade?", "back": "Testa a menor unidade isolada de código-fonte (método, função ou classe) para garantir que atende à especificação.", "tag": "01_Programacao"}, {"front": "Na UML, para que serve o Diagrama de Casos de Uso?", "back": "Mostra as interações entre usuários (atores) e o sistema, identificando os requisitos funcionais.", "tag": "01_Programacao"}, {"front": "O que analisa a matriz SWOT?", "back": "Ambiente interno (Forças e Fraquezas) e ambiente externo (Oportunidades e Ameaças).", "tag": "01_Programacao"}, {"front": "Quais comandos pertencem à sublinguagem DDL (Data Definition Language)?", "back": "CREATE, ALTER e DROP (definem ou alteram a estrutura das tabelas e do banco).", "tag": "02_Banco_Dados"}, {"front": "Quais comandos pertencem à sublinguagem DML (Data Manipulation Language)?", "back": "INSERT, UPDATE e DELETE (inserem, atualizam e excluem registros/dados).", "tag": "02_Banco_Dados"}, {"front": "Qual comando pertence à sublinguagem DQL (Data Query Language)?", "back": "SELECT (consulta e recupera dados armazenados nas tabelas).", "tag": "02_Banco_Dados"}, {"front": "Pegadinha nº 1 de Banco de Dados na FAT: o que a banca troca na tabela de SQL?", "back": "Ela inverte DDL com DQL, dizendo que DQL usa CREATE/ALTER/DROP e DDL usa SELECT. Falso!", "tag": "02_Banco_Dados"}, {"front": "Quais comandos pertencem a DCL e TCL (DTL) em SQL?", "back": "DCL (Controle): GRANT e REVOKE. TCL (Transação): COMMIT e ROLLBACK.", "tag": "02_Banco_Dados"}, {"front": "No Modelo Relacional, o que são Tuplas e Atributos?", "back": "Em uma tabela, linhas são chamadas de Tuplas (registros) e colunas são chamadas de Atributos (campos).", "tag": "02_Banco_Dados"}, {"front": "Qual a diferença entre Chave Primária (PK) e Chave Estrangeira (FK)?", "back": "PK identifica unicamente cada linha da própria tabela. FK é uma coluna que referencia a PK de outra tabela para ligá-las.", "tag": "02_Banco_Dados"}, {"front": "O que é Chave Alternativa em Banco de Dados?", "back": "Quando existem várias chaves candidatas, uma é escolhida como Chave Primária e as candidatas restantes são chamadas de Chaves Alternativas.", "tag": "02_Banco_Dados"}, {"front": "Quais são os tipos de cardinalidade e o que é Relacionamento Recursivo?", "back": "Cardinalidades: 1:1, 1:N e N:N. Recursivo (auto-relacionamento) é quando uma entidade se relaciona consigo mesma (pode ser 1:N, N:1 ou N:N).", "tag": "02_Banco_Dados"}, {"front": "O que exige a Primeira Forma Normal (1FN / 1NF)?", "back": "Todos os atributos devem ter apenas valores atômicos (indivisíveis), sem colunas repetidas ou múltiplos valores na mesma célula (ex: dois telefones juntos).", "tag": "02_Banco_Dados"}, {"front": "O que exigem a 2ª Forma Normal (2FN) e a 3ª Forma Normal (3FN)?", "back": "2FN: estar na 1FN e não ter dependência parcial da chave composta. 3FN: estar na 2FN e eliminar dependências transitivas entre atributos não-chave.", "tag": "02_Banco_Dados"}, {"front": "Qual a sintaxe SQL correta para contar clientes de São Paulo?", "back": "SELECT COUNT(*) FROM clientes WHERE cidade = 'São Paulo'.", "tag": "02_Banco_Dados"}, {"front": "Por que \"SELECT * FROM clientes WHERE COUNT(cidade) = 'São Paulo'\" está errada?", "back": "Porque funções de agregação como COUNT(*) ficam logo após o SELECT, nunca dentro da cláusula WHERE.", "tag": "02_Banco_Dados"}, {"front": "Para que serve a cláusula WHERE na DQL?", "back": "Realiza Filtragem e Condições, restringindo as linhas retornadas por um SELECT.", "tag": "02_Banco_Dados"}, {"front": "O que é um Dicionário de Dados?", "back": "Coleção de nomes, atributos e definições sobre os elementos de dados usados no projeto do sistema.", "tag": "02_Banco_Dados"}, {"front": "Quais os exemplos clássicos de bancos Não Relacionais (NoSQL) vs Relacionais (SQL)?", "back": "NoSQL: MongoDB e Cassandra. Relacionais (SQL): MySQL, PostgreSQL, Oracle e SQL Server.", "tag": "02_Banco_Dados"}, {"front": "Quais são os 3 padrões de cores cobrados pela Fundação FAT?", "back": "CMYK (impressão/pigmento), RGB (luz/telas) e Hexadecimal (#RRGGBB na web). (Pegadinha: \"Primária\" e \"CSS\" não são padrões!).", "tag": "03_Design_Digital"}, {"front": "Quando usar RGB vs CMYK?", "back": "RGB (Red, Green, Blue) para telas e dispositivos digitais (síntese aditiva). CMYK (Cyan, Magenta, Yellow, Black) para impressão gráfica (síntese subtrativa).", "tag": "03_Design_Digital"}, {"front": "O que é o Círculo Cromático e quais as harmonias de 3 cores?", "back": "Representação circular de 12 cores (3 primárias, 3 secundárias, 6 terciárias). Harmonias de 3 cores: Análogas, Triangulação e Meio-complementares.", "tag": "03_Design_Digital"}, {"front": "Quais são os formatos de imagem Vetorial que nunca perdem qualidade ao ampliar?", "back": "SVG (Scalable Vector Graphics) e PDF (além de AI e CDR), pois são definidos por fórmulas matemáticas.", "tag": "03_Design_Digital"}, {"front": "Quais são os formatos de imagem Bitmap/Raster que perdem qualidade ao ampliar?", "back": "JPEG/JPG, PNG, BMP e GIF, pois são compostos por grade fixa de pixels.", "tag": "03_Design_Digital"}, {"front": "Qual a diferença prática entre PNG e JPEG?", "back": "PNG não perde qualidade na compressão e suporta transparência (canal alfa). JPEG usa compressão com perdas e não tem transparência.", "tag": "03_Design_Digital"}, {"front": "O que é Rasterização?", "back": "Processo de converter gráficos vetoriais (fórmulas matemáticas) em imagens compostas por pixels para exibição em dispositivos digitais.", "tag": "03_Design_Digital"}, {"front": "Quais as 3 características principais dos Bancos de Imagens segundo a FAT?", "back": "Variedade de Conteúdo, Licenciamento (gratuitas/pagas, uso comercial/pessoal) e Qualidade/Resolução (para impressão ou uso digital).", "tag": "03_Design_Digital"}, {"front": "Na Gestalt, o que define o princípio da Continuidade?", "back": "Linhas e padrões que seguem uma trajetória contínua são percebidos como pertencentes a um mesmo elemento.", "tag": "03_Design_Digital"}, {"front": "Na Gestalt, diferencie Proximidade, Semelhança, Fechamento e Figura-Fundo.", "back": "Proximidade: itens perto formam grupo. Semelhança: cor/forma parecida agrupa. Fechamento: mente completa formas abertas. Figura-Fundo: separa objeto do plano atrás.", "tag": "03_Design_Digital"}, {"front": "Na Tipografia, o que caracteriza as Fontes Script?", "back": "Reproduzem a escrita humana com aparência tradicional/elegante, muito usadas em convites formais.", "tag": "03_Design_Digital"}, {"front": "Quais exemplos de serviços de Fontes Personalizadas para Web vs fontes de sistema?", "back": "Personalizadas: Google Fonts e Adobe Fonts. Padrão de sistema (pegadinha): Times New Roman, Arial e Helvetica.", "tag": "03_Design_Digital"}, {"front": "O que diz a Heurística de Nielsen \"Equivalência entre o sistema e o mundo real\"?", "back": "Toda comunicação do sistema deve falar a linguagem e seguir o modelo mental do usuário, evitando jargões técnicos internos.", "tag": "03_Design_Digital"}, {"front": "No HTML, o que são Tags e Atributos?", "back": "Tags definem a estrutura e o tipo de conteúdo (ex: <a>, <p>). Atributos são propriedades extras adicionadas às tags (ex: href, target).", "tag": "04_Web_Redes_SO"}, {"front": "Na tag <a> do HTML, qual valor de target abre o link em uma nova aba ou janela?", "back": "target=\"_blank\". (_self abre na mesma aba, _parent no frame pai, _top na janela toda, _none não existe).", "tag": "04_Web_Redes_SO"}, {"front": "Quais são as principais tags estruturais semânticas do HTML5?", "back": "Semânticas: <nav>, <header>, <footer> e <section>. (Pegadinha: <div> e <span> NÃO são semânticas!).", "tag": "04_Web_Redes_SO"}, {"front": "O que significam <ol> e <ul>, e qual a diferença entre <div> e <span>?", "back": "ol = ordered list (ordenada), ul = unordered list (não ordenada). <div> é elemento de bloco, <span> é inline.", "tag": "04_Web_Redes_SO"}, {"front": "Quais são as duas partes principais de uma regra CSS?", "back": "Seletor (elemento/classe/id alvo) e Bloco de Declarações (chaves { propriedade: valor }).", "tag": "04_Web_Redes_SO"}, {"front": "O que fazem as transformações CSS3 scale, skew, translate e rotate?", "back": "scale: aumenta/diminui proporcionalmente. skew: inclina ângulos. translate: move nos eixos X e Y. rotate: gira pelo ângulo.", "tag": "04_Web_Redes_SO"}, {"front": "Para que servem as classes Bootstrap btn-default, form-inline, col-md-1, img-responsive e text-primary?", "back": "Respectivamente: botão, formulário, grid (coluna), imagem responsiva e texto de ajuda/destaque.", "tag": "04_Web_Redes_SO"}, {"front": "No JavaScript (DOM), o que fazem getElementById, createTextNode, documentElement e parentNode?", "back": "Buscam elemento por id, criam nó de texto, capturam a raiz <html> e retornam o nó pai, respectivamente.", "tag": "04_Web_Redes_SO"}, {"front": "Onde os Cookies são armazenados: no navegador do usuário ou na nuvem?", "back": "Sempre LOCALMENTE no navegador do usuário! Dizer que ficam \"na nuvem\" é pegadinha clássica da FAT.", "tag": "04_Web_Redes_SO"}, {"front": "Qual o limite aproximado de tamanho de um Cookie e quais seus tipos de duração?", "back": "Cerca de 4 KB por cookie. Duração: Sessão (apagado ao fechar o navegador) ou Permanente (até expirar ou ser removido).", "tag": "04_Web_Redes_SO"}, {"front": "Diferencie Hospedagem Compartilhada, Dedicada e VPS.", "back": "Compartilhada: vários sites dividem CPU/RAM de 1 servidor. Dedicada: 1 servidor inteiro só para 1 site. VPS: 1 servidor particionado em máquinas virtuais com recursos dedicados.", "tag": "04_Web_Redes_SO"}, {"front": "Qual é a principal característica dos Contêineres em relação às Máquinas Virtuais (VMs)?", "back": "Isolamento leve: cada contêiner empacota a app e dependências sem precisar virtualizar todo o hardware completo como uma VM.", "tag": "04_Web_Redes_SO"}, {"front": "Quantos bits há em 1 byte e como se representa 255 em binário?", "back": "1 byte = 8 bits (256 combinações de 0 a 255). O número 255 em binário é 11111111.", "tag": "04_Web_Redes_SO"}, {"front": "Converta 10, 100 e 250 da base decimal para binário (e 100/250 para hexadecimal).", "back": "10 = 1010(2). 100 = 01100100(2) = 64(16). 250 = 11111010(2) = FA(16).", "tag": "04_Web_Redes_SO"}, {"front": "Quais as características do SSD que o diferenciam do HD?", "back": "Usa chips de memória flash (como pendrive), não possui partes mecânicas, tem acesso rápido, menos vibração e menor consumo de bateria.", "tag": "04_Web_Redes_SO"}, {"front": "Qual função do Sistema Operacional gerencia a memória RAM?", "back": "Gerenciamento de Memória: aloca e libera espaço na RAM para programas em execução, otimizando o desempenho.", "tag": "04_Web_Redes_SO"}, {"front": "Quais são os 7 diretórios padrão do Linux cobrados na prova (e qual é a pegadinha)?", "back": "Diretórios reais: /bin, /etc, /home, /lib, /usr, /var e /tmp. Pegadinha: colocar comandos como /ls, /cd, /mkdir, /pwd ou /rm como se fossem pastas!", "tag": "04_Web_Redes_SO"}, {"front": "Para que servem os comandos Linux ls, mkdir, cp, apt, cat e shutdown?", "back": "ls: listar pasta. mkdir: criar pasta. cp: copiar. apt: gerenciar pacotes. cat: ler arquivo texto. shutdown: desligar/reiniciar.", "tag": "04_Web_Redes_SO"}, {"front": "Quais são as 4 camadas do modelo TCP/IP?", "back": "Link (Acesso à Rede), Internet, Transporte e Aplicação. (Pegadinha: \"Sessão\" e \"Física\" pertencem ao modelo OSI).", "tag": "04_Web_Redes_SO"}, {"front": "Qual é a função do protocolo fundamental TCP/IP?", "back": "Dividir os dados em pacotes, endereçá-los/roteá-los até o destino e reagrupá-los na chegada.", "tag": "04_Web_Redes_SO"}, {"front": "O que fazem os protocolos HTTP/HTTPS, FTP, DNS e RDP?", "back": "HTTP/S: páginas web. FTP: arquivos. DNS: traduz nomes de domínio em IP. RDP: acesso remoto gráfico Microsoft.", "tag": "04_Web_Redes_SO"}, {"front": "Quais as 3 funcionalidades principais do SSL/TLS?", "back": "Criptografia, Autenticação e Integridade dos Dados.", "tag": "04_Web_Redes_SO"}, {"front": "Diferencie SMTP, POP3 e IMAP (campeão de inversões da FAT!).", "back": "SMTP: ENVIO de e-mails. POP3: BAIXA para o dispositivo e geralmente apaga do servidor. IMAP: sincroniza e gerencia direto no servidor entre vários dispositivos.", "tag": "04_Web_Redes_SO"}, {"front": "Qual a diferença entre Topologia em Barramento (Bus) e Topologia em Estrela (Star)?", "back": "Barramento: cabo único central (se o cabo falhar, toda a rede cai). Estrela: ligada a unidade central inteligente (switch) que distribui o tráfego.", "tag": "04_Web_Redes_SO"}, {"front": "Quais os 3 setores clássicos de aplicação da IoT (Internet das Coisas) na prova?", "back": "Residências inteligentes (câmeras/termostatos), Cidades inteligentes (tráfego/iluminação/poluição) e Indústria/Saúde (manutenção preditiva/monitoramento).", "tag": "04_Web_Redes_SO"}, {"front": "Quais os 5 navegadores web da lista oficial da prova (e os intrusos)?", "back": "Navegadores: Chrome, Firefox, Edge, Safari e Opera. Intrusos: Telegram, Messenger, Capcut, Youtube e Truecaller.", "tag": "04_Web_Redes_SO"}, {"front": "Quais os exemplos válidos de Webmail e suas características?", "back": "Gmail, Outlook.com e iCloud Mail (acesso pelo navegador com armazenamento na nuvem). Intrusos: Canva, Splice, Norton Safe Web.", "tag": "04_Web_Redes_SO"}, {"front": "Quais as 3 características das Suítes de Produtividade (Office 365) e recursos do Word/Windows?", "back": "Integração de apps, Colaboração em tempo real e Acessibilidade na nuvem. Word: Marcadores/Numeração, Controlar Alterações. Windows: Ctrl+C copia, Ctrl+X recorta.", "tag": "04_Web_Redes_SO"}, {"front": "No inglês técnico da FAT, o que significam outcomes, data e soft skills?", "back": "outcomes = resultados (não \"saídas\"). data = dados (NUNCA \"datas\"!). soft skills = habilidades comportamentais (não \"cuidados suaves\").", "tag": "05_Ingles_Etica"}, {"front": "No inglês técnico da FAT, o que significam troubleshooting, inference, gathering e predict?", "back": "troubleshooting = solução de problemas. inference = dedução/conclusão. gathering = coleta. predict = prever/antecipar.", "tag": "05_Ingles_Etica"}, {"front": "Como acertar sempre a questão de Ética sobre \"Bem Comum\"?", "back": "Escolha a atitude solidária genuína voltada à coletividade. Elimine opções com interesse próprio (\"liberar espaço\", \"ganhar promoção\", \"postar em redes sociais\").", "tag": "05_Ingles_Etica"}, {"front": "Como acertar a questão de Ética sobre \"Relações Trabalhistas e Consumo\"?", "back": "Escolha respeito aos direitos trabalhistas, qualidade de vida dos colaboradores e consumo consciente/sustentável. Elimine corte de direitos ou propaganda enganosa.", "tag": "05_Ingles_Etica"}, {"front": "Como acertar a questão de Ética sobre \"Direito Constitucional e Meio Ambiente\"?", "back": "Escolha políticas públicas com participação das comunidades locais, estudo de impacto e preservação ambiental sustentável.", "tag": "05_Ingles_Etica"}, {"front": "Barroco: qual a diferença entre Cultismo e Conceptismo?", "back": "Cultismo = jogo de palavras, linguagem rebuscada/sensorial. Conceptismo = jogo de ideias e raciocínio lógico. (Pegadinha M-Tec Q01: a banca inverte os dois!).", "tag": "06_MTec_Base_Comum"}, {"front": "Quinhentismo: quais suas duas vertentes no século XVI?", "back": "Literatura Informativa (carta de Pero Vaz de Caminha descrevendo as novas terras) e Literatura Jesuítica/Catequética (poesias e teatro de José de Anchieta).", "tag": "06_MTec_Base_Comum"}, {"front": "Variação Linguística: diferencie Diatópica e Diacrônica.", "back": "Diatópica = varia conforme a região/lugar. Diacrônica = varia com o passar do tempo. A sociolinguística avalia adequação ao contexto, não 'certo/errado'.", "tag": "06_MTec_Base_Comum"}, {"front": "Quais são os 5 Tipos Textuais clássicos?", "back": "Injunção (ordens/conselhos no imperativo), Exposição (explica com impessoalidade), Narração (fatos no tempo/espaço), Descrição (retrata com adjetivos, sem tempo) e Dissertação (defende tese com argumentos).", "tag": "06_MTec_Base_Comum"}, {"front": "Qual a diferença entre Paradoxo e Antítese (e Hipônimo/Hiperônimo)?", "back": "Paradoxo une contradições ilógicas na mesma ideia ('quanto mais estudo, menos entendo'). Antítese aproxima opostos ('dia/noite'). Hipônimo (específico: Aristóteles) -> Hiperônimo (geral: pensador).", "tag": "06_MTec_Base_Comum"}, {"front": "Inglês M-Tec: qual é o superlativo irregular de 'Bad' e o sinônimo de 'daunting'?", "back": "Superlativo de 'Bad' = 'Worst' (o pior). 'Daunting' significa 'intimidating' (intimidador). Palavras como 'debatable' e 'positive' são adjetivos.", "tag": "06_MTec_Base_Comum"}, {"front": "Qual a ordem das etapas do Método Científico?", "back": "1) Observação -> 2) Questionamento/Hipótese -> 3) Planejamento do Experimento -> 4) Coleta/Análise de Dados -> 5) Conclusão.", "tag": "06_MTec_Base_Comum"}, {"front": "O que foi definido no Protocolo de Kyoto?", "back": "Limites de emissão de gases poluentes (efeito estufa) e as regras do sistema de créditos de carbono.", "tag": "06_MTec_Base_Comum"}, {"front": "Como calcular Massa Molecular (u) e quanto valem C2H5OH e C2H4O2?", "back": "Use C=12, H=1, O=16. Álcool etílico (C2H5OH) = 2(12)+6(1)+16 = 46 u. Ácido acético (C2H4O2) = 2(12)+4(1)+2(16) = 60 u.", "tag": "06_MTec_Base_Comum"}, {"front": "Química: como diferenciar Metal, Composto Iônico e Molecular pela condutividade?", "back": "Metal conduz eletricidade no estado SÓLIDO. Iônico NÃO conduz no sólido, mas conduz LÍQUIDO/fundido. Molecular NÃO conduz nem sólido nem líquido.", "tag": "06_MTec_Base_Comum"}, {"front": "Física (Óptica): por que enxergamos um tomate como vermelho?", "back": "Porque o tomate absorve as demais cores da luz branca e REFLETE a cor vermelha aos nossos olhos.", "tag": "06_MTec_Base_Comum"}, {"front": "Matemática (Conjuntos Numéricos): Dízimas periódicas são Racionais ou Irracionais?", "back": "RACIONAIS (Q), pois podem ser escritas como fração! Irracionais (I) são raízes não exatas e decimais infinitos NÃO periódicos (pi).", "tag": "06_MTec_Base_Comum"}, {"front": "Matemática: como resolver (A interseção B) união C?", "back": "Primeiro ache os elementos em comum entre A e B (A ∩ B). Depois junte com todos os elementos de C (∪ C) sem repetir.", "tag": "06_MTec_Base_Comum"}, {"front": "Contagem M-Tec: quantos números de 3 algarismos distintos formamos com {0,1,2,3,4,5}?", "back": "O zero (0) NÃO pode ir na 1a casa! Logo: 5 opções (1..5) x 5 opções (sobra 4 + o 0) x 4 opções = 100 números!", "tag": "06_MTec_Base_Comum"}, {"front": "Função Quadrática f(x) = ax^2 + bx + c: quando há duas raízes reais distintas?", "back": "Quando Delta = b^2 - 4ac > 0. Se a > 0, a parábola tem concavidade para cima (ponto de mínimo).", "tag": "06_MTec_Base_Comum"}, {"front": "Geometria M-Tec: qual o macete do triângulo 30-40-50?", "back": "Triângulo retângulo com catetos 30 m e 40 m tem hipotenusa 50 m (3-4-5 x 10) e área = (30 x 40)/2 = 600 m^2.", "tag": "06_MTec_Base_Comum"}, {"front": "História (Pré-História): diferencie Paleolítico de Neolítico.", "back": "Paleolítico: nômades, caça/coleta, domínio do fogo, pedra lascada. Neolítico: sedentarismo, agricultura e domesticação de animais.", "tag": "06_MTec_Base_Comum"}, {"front": "Movimentos Migratórios: o que é Nomadismo vs Sedentarismo vs Êxodo Rural?", "back": "Nomadismo: mudar de local quando acaba comida. Sedentarismo: fixar residência com agricultura. Êxodo rural: saída do campo para a cidade.", "tag": "06_MTec_Base_Comum"}, {"front": "Qual a definição oficial M-Tec para Hardware, Sistema Operacional e Software Livre?", "back": "Hardware = maquinário físico. SO = interface entre peopleware e hardware. Software Livre = permissão de alterar o código-fonte (nem sempre é gratuito!).", "tag": "06_MTec_Base_Comum"}, {"front": "O que significam Análise SWOT, UML e Dicionário de Dados?", "back": "SWOT: Forças/Fraquezas (interno) e Oportunidades/Ameaças (externo). UML: linguagem unificada de diagramas. Dicionário de Dados: nomes, atributos e definições.", "tag": "06_MTec_Base_Comum"}], "pairs": [{"term": "DDL", "def": "CREATE, ALTER e DROP (estrutura)"}, {"term": "DML", "def": "INSERT, UPDATE e DELETE (dados)"}, {"term": "DQL", "def": "SELECT (consulta e recuperação)"}, {"term": "SMTP", "def": "Envio de e-mails"}, {"term": "POP3", "def": "Baixa e exclui do servidor"}, {"term": "IMAP", "def": "Sincroniza direto no servidor"}, {"term": "SVG / PDF", "def": "Arquivos Vetoriais (não pixelam)"}, {"term": "CMYK", "def": "Padrão de cores para impressão"}, {"term": "target=\"_blank\"", "def": "Abre link em nova aba ou janela"}, {"term": "1ª Forma Normal", "def": "Valores atômicos (indivisíveis)"}, {"term": "Barramento (Bus)", "def": "Cabo central único; se falhar, cai tudo"}, {"term": "Estrela (Star)", "def": "Nó central inteligente (Switch)"}, {"term": "scale (CSS3)", "def": "Aumenta proporcionalmente o elemento"}, {"term": "branch (Git)", "def": "Cria caminho paralelo no código"}, {"term": "Portabilidade", "def": "Transferir software para outro ambiente"}, {"term": "Cookies", "def": "Texto local ~4KB no navegador"}, {"term": "Cultismo (Barroco)", "def": "Jogo de palavras / linguagem rebuscada"}, {"term": "Conceptismo (Barroco)", "def": "Jogo de ideias e raciocínio lógico"}, {"term": "Paleolítico", "def": "Nômade, caça/coleta, domínio do fogo"}, {"term": "Neolítico", "def": "Sedentarismo, agricultura e animais"}, {"term": "Metal (Química)", "def": "Conduz eletricidade no estado sólido"}, {"term": "Iônico (Química)", "def": "Só conduz quando líquido/fundido"}], "exams": {"mtec2022": {"id": "mtec2022", "title": "Prova Real M-Tec 2º Ano DS (Base Comum + Técnico)", "badge": "M-Tec Oficial • 40 Questões", "desc": "Prova oficial de Vagas Remanescentes para 2ª série M-Tec DS: Português, Inglês, Química, Física, Matemática, História + Técnico em DS.", "minutes": 240, "questions": [{"num": 1, "stemHtml": "<p>Assinale a opção incorreta quanto aos conceitos sobre literatura:</p>", "options": ["O conceptismo tem linguagem rebuscada, brinca com palavras. O cultismo é marcado pelo jogo de ideias e raciocínio lógico.", "O Barroco apresenta as contradições humanas por antíteses, paradoxos, interrogações.", "A literatura informativa do Quinhentismo cataloga descrevendo as novas terras.", "A literatura do século XVI reflete a divisão do ser humano entre matéria e espírito, vida e morte, pecado e o perdão.", "José de Anchieta escreveu poesias e teatro com intenção de converter os índios."], "answer": 0, "explain": "Incorreta é a (A): o texto inverteu os dois conceitos! O <strong>Cultismo</strong> é o jogo de palavras/linguagem rebuscada; o <strong>Conceptismo</strong> é o jogo de ideias e raciocínio lógico.", "area": "mtec_base"}, {"num": 2, "stemHtml": "<p>Assinale a alternativa correta sobre variação linguística:</p>", "options": ["“Certo” e “errado” são conceitos essenciais para essa concepção de estudo.", "Variação diatópica corresponde às mudanças que ocorrem com o passar do tempo.", "Variação diacrônica se refere às mudanças de um idioma conforme a região.", "Variação implanta a ideia de comunicação adequada ou inadequada ao contexto, sem falar sobre português bom e mau.", "As gírias não podem ser consideradas variações linguísticas dignas de estudo."], "answer": 3, "explain": "Correta (D): a variação linguística trabalha com adequação ao contexto, sem rotular português 'certo' ou 'errado'. (Diatópica = região; Diacrônica = tempo).", "area": "mtec_base"}, {"num": 3, "stemHtml": "<p>Marque a alternativa cuja ordem preenche adequadamente os parênteses abaixo: Item 1. Narração Item 2. Dissertação Item 3. Exposição Item 4. Descrição Item 5. Injunção ( ) Texto em que se dão conselhos e indicações sobre como realizar ações. Uso de verbos no imperativo. ( ) Texto em que se apresentam ideias sobre dado assunto, assim como explicações, avaliações e reflexões. Uso de linguagem clara, objetiva e impessoal. ( ) Texto em que se conta um fato, fictício ou não, acontecido num tempo e espaço, com personagens e ações. A temporalidade é fator importante nesse tipo de texto. ( ) Texto em que se retrata, de forma objetiva ou subjetiva, um lugar, uma pessoa, um objeto etc., usando adjetivos, mas sem temporalidade ( ) Texto em que há posicionamentos e exposição de ideias, para defender um ponto de vista. Sua estrutura básica é: apresentação de ideia principal, argumentos e conclusão.</p>", "options": ["5, 3, 1, 4, 2", "3, 5, 1, 2, 4", "4, 2, 3, 1, 5", "5, 3, 4, 1, 2", "2, 3, 1, 4, 5"], "answer": 0, "explain": "Ordem 5, 3, 1, 4, 2: Injunção (conselhos/imperativo), Exposição (informar com clareza), Narração (fatos no tempo), Descrição (retrato/adjetivos) e Dissertação (argumentação).", "area": "mtec_base"}, {"num": 4, "stemHtml": "<p>Indique qual das alternativas abaixo traz um paradoxo:</p>", "options": ["Você chora quando eu quero rir.", "Os finais de semana passam lentamente, mas as segundas-feiras se arrastam.", "Quanto mais eu estudo física quântica, menos entendo desse assunto.", "Seu pai é uma pessoa tranquila, enquanto o meu é mais agitado.", "Os dias são brancos, as noites escuras."], "answer": 2, "explain": "(C) Paradoxo une ideias logicamente contraditórias na mesma frase ('quanto mais estudo, menos entendo'). As demais são antíteses ou contrastes comuns.", "area": "mtec_base"}, {"num": 5, "stemHtml": "<p>Assinale a alternativa que corretamente representa a relação semântica e seu exemplo:</p>", "options": ["Amor – ódio (sinonímia).", "Menino – garoto (antonímia).", "Aristóteles – pensador (hipônimo e hiperônimo).", "Absorver – absolver (homonímia).", "Planta vegetal e planta – desenho arquitetônico (homonímia)."], "answer": 2, "explain": "(C) Aristóteles (termo específico = hipônimo) e pensador (termo geral = hiperônimo). Em (A) amor-ódio é antonímia; em (B) menino-garoto é sinonímia; em (D) absorver/absolver é paronímia.", "area": "mtec_base"}, {"num": 6, "stemHtml": "<p>Sobre a relação entre Literatura Medieval e História, assinale a alternativa correta:</p>", "options": ["Trovadorismo e Humanismo são artes da decadência da Idade Média.", "o Trovadorismo traduz valores do Feudalismo.", "o Trovadorismo e o Medievalismo nasceram na Provença.", "o Trovadorismo é típico do humanismo.", "o Trovadorismo corresponde ao Renascimento."], "answer": 1, "explain": "(B) O Trovadorismo medieval expressava valores da sociedade feudal (vassalagem amorosa, cantigas de amor/amigo).", "area": "mtec_base"}, {"num": 7, "stemHtml": "<p>“Worst” is the superlative of:</p>", "options": ["Well", "Better", "Bad", "Good", "Far"], "answer": 2, "explain": "(C) 'Worst' (o pior) é o superlativo irregular de 'Bad' (mau/ruim).", "area": "ingles_etica"}, {"num": 8, "stemHtml": "<p>Which Word below could be used to Express the meaning of athe adjective “dauting”?</p>", "options": ["easy", "intimidating", "impossible", "surreal", "exciting"], "answer": 1, "explain": "(B) 'Daunting' (intimidador/assustador) equivale a 'intimidating'.", "area": "ingles_etica"}, {"num": 9, "stemHtml": "<p>Considering parts of speech, it is possible to say that the words debatable and positive are:</p>", "options": ["both adverbs", "both adjectives", "adjective and adverb, respectively", "adverb and adjective, respectively", "both pronouns."], "answer": 1, "explain": "(B) Tanto 'debatable' (discutível) quanto 'positive' (positivo) são adjetivos.", "area": "ingles_etica"}, {"num": 10, "stemHtml": "<p>Até o século XVII, o papel dos espermatozoides na fertilização do óvulo não era reconhecido. O cientista italiano Lazaro Spallanzani, em 1785, questionou se seria o próprio sêmen, ou simplesmente o vapor dele derivado, a causa do desenvolvimento do óvulo. Do relatório que escreveu a partir de seus estudos sobre a fertilização, foi retirado o seguinte trecho: \"... para decidir a questão, é importante empregar um meio conveniente que permita separar o vapor da parte figurada do sêmen e fazê-lo de tal modo que os embriões sejam mais ou menos envolvidos pelo vapor.\" Dentre as etapas que constituem o método científico, esse trecho do relatório é um exemplo de:</p>", "options": ["análise de dados", "coleta de material", "elaboração da hipótese", "planejamento do experimento", "Todas as alternativas anteriores estão corretas."], "answer": 3, "explain": "(D) Ao propor um procedimento prático para separar o vapor da parte figurada do sêmen e testar nos embriões, Spallanzani estava na etapa de planejamento do experimento.", "area": "mtec_base"}, {"num": 11, "stemHtml": "<blockquote class='q-quote'>Texto: Sobre a importância da ciência Parece paradoxal que, no início deste milênio, durante o que chamamos com orgulho de “era da ciência”, tantos ainda acreditem em profecias de fim de mundo. Quem não se lembra do bug do milênio ou da enxurrada de absurdos ditos todos os dias sobre a previsão maia de fim de mundo no ano 2012? Existe um cinismo cada vez maior com relação à ciência, um senso de que fomos traídos, de que promessas não foram cumpridas. Afinal, lutamos para curar doenças apenas para descobrir outras novas. Criamos tecnologias que pretendem simplificar nossas vidas, mas passamos cada vez mais tempo no trabalho. Pior ainda: tem sempre tanta coisa nova e tentadora no mercado que fica impossível acompanhar o passo da tecnologia. Os mais jovens se comunicam de modo quase que incompreensível aos mais velhos, com Facebook, Twitter e textos em celulares. Podemos ir à Lua, mas a maior parte da população continua mal nutrida. Consumimos o planeta com um apetite insaciável, criando uma devastação ecológica sem precedentes. Isso tudo graças à ciência? Ao menos, é assim que pensam os descontentes, mas não é nada disso. Primeiro, a ciência não promete a redenção humana. Ela simplesmente se ocupa de compreender como funciona a natureza, ela é um corpo de conhecimento sobre o Universo e seus habitantes, vivos ou não, acumulado através de um processo constante de refinamento e testes conhecido como método científico. A prática da ciência provê um modo de interagir com o mundo, expondo a essência criativa da natureza. Disso, aprendemos que a natureza é transformação, que a vida e a morte são parte de uma cadeia de criação e destruição perpetuada por todo o cosmo, dos átomos às estrelas e à vida. Nossa existência é parte desta transformação constante da matéria, onde todo elo é igualmente importante, do que é criado ao que é destruído. A ciência pode não oferecer a salvação eterna, mas oferece a possibilidade de vivermos livres do medo irracional do desconhecido. Ao dar ao indivíduo a autonomia de pensar por si mesmo, ela oferece a liberdade da escolha informada. Ao transformar mistério em desafio, a ciência adiciona uma nova dimensão à vida, abrindo a porta para um novo tipo de espiritualidade, livre do dogmatismo das religiões organizadas. A ciência não diz o que devemos fazer com o conhecimento que acumulamos. Essa decisão é nossa, em geral tomada pelos políticos que elegemos, ao menos numa sociedade democrática. A culpa dos usos mais nefastos da ciência deve ser dividida por toda a sociedade. Inclusive, mas não exclusivamente, pelos cientistas. Afinal, devemos culpar o inventor da pólvora pelas mortes por tiros e explosivos ao longo da história? Ou o inventor do microscópio pelas armas biológicas? A ciência não contrariou nossas expectativas. Imagine um mundo sem antibióticos, TVs, aviões, carros. As pessoas vivendo no mato, sem os confortos tecnológicos modernos, caçando para comer. Quantos optariam por isso? A culpa do que fazemos com o planeta é nossa, não da ciência. Apenas uma sociedade versada na ciência pode escolher o seu destino responsavelmente. Nosso futuro depende disso. Marcelo Gleiser é professor de física teórica no Dartmouth College (EUA). Fonte: www.ufrgs.br /blogdabc/sobre-importanciada-ciencia/ (postado em 18/10/2010). Acesso em 5 de abril de 2020.</blockquote><p>Depois de ler o texto, compreende-se que a importância da ciência está, principalmente, em poder</p>", "options": ["escolher, enquanto sociedade, nosso destino de forma responsável.", "estabelecer as diferenças principais entre a ciência e o charlatanismo.", "explicar que a ciência não pode oferecer a salvação eterna, porque não prova a existência divina.", "abrir a porta para um novo tipo de espiritualidade.", "direcionar a conduta humana em relação ao conhecimento obtido"], "answer": 0, "explain": "(A) Marcelo Gleiser conclui que 'apenas uma sociedade versada na ciência pode escolher o seu destino responsavelmente'.", "area": "mtec_base"}, {"num": 12, "stemHtml": "<blockquote class='q-quote'>Texto: Sobre a importância da ciência Parece paradoxal que, no início deste milênio, durante o que chamamos com orgulho de “era da ciência”, tantos ainda acreditem em profecias de fim de mundo. Quem não se lembra do bug do milênio ou da enxurrada de absurdos ditos todos os dias sobre a previsão maia de fim de mundo no ano 2012? Existe um cinismo cada vez maior com relação à ciência, um senso de que fomos traídos, de que promessas não foram cumpridas. Afinal, lutamos para curar doenças apenas para descobrir outras novas. Criamos tecnologias que pretendem simplificar nossas vidas, mas passamos cada vez mais tempo no trabalho. Pior ainda: tem sempre tanta coisa nova e tentadora no mercado que fica impossível acompanhar o passo da tecnologia. Os mais jovens se comunicam de modo quase que incompreensível aos mais velhos, com Facebook, Twitter e textos em celulares. Podemos ir à Lua, mas a maior parte da população continua mal nutrida. Consumimos o planeta com um apetite insaciável, criando uma devastação ecológica sem precedentes. Isso tudo graças à ciência? Ao menos, é assim que pensam os descontentes, mas não é nada disso. Primeiro, a ciência não promete a redenção humana. Ela simplesmente se ocupa de compreender como funciona a natureza, ela é um corpo de conhecimento sobre o Universo e seus habitantes, vivos ou não, acumulado através de um processo constante de refinamento e testes conhecido como método científico. A prática da ciência provê um modo de interagir com o mundo, expondo a essência criativa da natureza. Disso, aprendemos que a natureza é transformação, que a vida e a morte são parte de uma cadeia de criação e destruição perpetuada por todo o cosmo, dos átomos às estrelas e à vida. Nossa existência é parte desta transformação constante da matéria, onde todo elo é igualmente importante, do que é criado ao que é destruído. A ciência pode não oferecer a salvação eterna, mas oferece a possibilidade de vivermos livres do medo irracional do desconhecido. Ao dar ao indivíduo a autonomia de pensar por si mesmo, ela oferece a liberdade da escolha informada. Ao transformar mistério em desafio, a ciência adiciona uma nova dimensão à vida, abrindo a porta para um novo tipo de espiritualidade, livre do dogmatismo das religiões organizadas. A ciência não diz o que devemos fazer com o conhecimento que acumulamos. Essa decisão é nossa, em geral tomada pelos políticos que elegemos, ao menos numa sociedade democrática. A culpa dos usos mais nefastos da ciência deve ser dividida por toda a sociedade. Inclusive, mas não exclusivamente, pelos cientistas. Afinal, devemos culpar o inventor da pólvora pelas mortes por tiros e explosivos ao longo da história? Ou o inventor do microscópio pelas armas biológicas? A ciência não contrariou nossas expectativas. Imagine um mundo sem antibióticos, TVs, aviões, carros. As pessoas vivendo no mato, sem os confortos tecnológicos modernos, caçando para comer. Quantos optariam por isso? A culpa do que fazemos com o planeta é nossa, não da ciência. Apenas uma sociedade versada na ciência pode escolher o seu destino responsavelmente. Nosso futuro depende disso. Marcelo Gleiser é professor de física teórica no Dartmouth College (EUA). Fonte: www.ufrgs.br /blogdabc/sobre-importanciada-ciencia/ (postado em 18/10/2010). Acesso em 5 de abril de 2020.</blockquote><p>Com base no texto, compreende- se que:</p>", "options": ["A ciência contrariou expectativas, uma vez que é a culpada pela destruição do planeta.", "A ciência, e suas descobertas, direciona cada uma das ações da humanidade no século XXI.", "A ciência foi capaz de acabar com crenças e com dogmatismo, uma vez que consegue tirar todo o mistério da vida humana.", "Através do uso consciente da ciência o ser humano pode ser livre da ignorância e da falta de conhecimento.", "Os estudos e conhecimentos científicos geraram a expansão do consumo desenfreado e a destruição das relações humanas."], "answer": 3, "explain": "(D) O texto mostra que a ciência liberta o indivíduo do medo irracional do desconhecido e permite escolhas informadas (livre da ignorância).", "area": "mtec_base"}, {"num": 13, "stemHtml": "<p>No presente, observa-se crescente atenção aos efeitos da atividade humana, em diferentes áreas, sobre o meio ambiente, sendo constante, nos fóruns internacionais, e nas instâncias nacionais, referência à sustentabilidade como princípio orientador de ações e propostas que deles emanam. A sustentabilidade explica-se pela:</p>", "options": ["Necessidade de satisfazer as demandas atuais impostas pelo desenvolvimento, sem comprometer a capacidade das gerações futuras atenderem as próprias necessidades nos campos econômico, social e ambiental.", "Incapacidade de se manter uma atividade econômica ao longo do tempo sem causar danos ao meio ambiente.", "Proteção da biodiversidade em face das ameaças de destruição que sofrem as florestas tropicais, devido ao avanço de atividades como a mineração, a monocultura, o tráfico de madeira e de espécies selvagens, além da pecuária", "A interação de todas as dimensões do bem-estar humano com o crescimento econômico, sem a preocupação com a conservação dos recursos naturais", "Nenhuma das alternativas anteriores"], "answer": 2, "explain": "(C) Na formulação desta questão pela banca, gabarito oficial (C): proteção da biodiversidade nas florestas tropicais contra desmatamento/mineração/tráfico.", "area": "mtec_base"}, {"num": 14, "stemHtml": "<p>Observe o quadro abaixo sobre padrões e índices da qualidade do ar disponibilizado pela Companhia de Tecnologia de Saneamento Ambiental - CETESB. http://www.cetesb.sp.gov.br. Acesso em: 22 jun. 2008. A Companhia de Tecnologia de Saneamento Ambiental do Estado de São Paulo (CETESB) divulga continuamente dados referentes à qualidade do ar na região metropolitana de São Paulo. A tabela apresentada corresponde a dados hipotéticos que poderiam ter sido obtidos pela CETESB em determinado dia. Se esses dados fossem verídicos, então, seria mais provável encontrar problemas de visibilidade</p>\n<table class=\"q-table\">\n  <thead><tr><th>ESTAÇÕES DA RMSP</th><th>QUALIDADE</th><th>ÍNDICE</th><th>POLUENTE</th></tr></thead>\n  <tbody>\n    <tr><td>Parque D. Pedro II</td><td>BOA</td><td>6</td><td>MP<sub>10</sub></td></tr>\n    <tr><td>São Caetano do Sul</td><td>REGULAR</td><td>60</td><td>NO<sub>2</sub></td></tr>\n    <tr><td>Congonhas</td><td>BOA</td><td>15</td><td>MP<sub>10</sub></td></tr>\n    <tr><td>Osasco</td><td>INADEQUADA</td><td>175</td><td>CO</td></tr>\n    <tr><td>Pinheiros</td><td>MÁ</td><td>283</td><td>SO<sub>2</sub></td></tr>\n  </tbody>\n</table>\n<p><small><strong>SO<sub>2</sub> – dióxido de enxofre:</strong> resulta principalmente da queima de combustíveis que contêm enxofre (como óleo diesel), podendo formar partículas à base de sulfato responsáveis pela <strong>redução da visibilidade na atmosfera</strong>. (Faixas: 0-50 BOA | 51-100 REGULAR | 101-199 INADEQUADA | 200-299 MÁ | &gt;299 PÉSSIMA)</small></p>\n", "options": ["no Parque Dom Pedro II.", "em São Caetano do Sul.", "em Congonhas.", "em Osasco.", "em Pinheiros"], "answer": 4, "explain": "(E) Pinheiros está com qualidade MÁ (índice 283) e poluente SO₂, cujas partículas de sulfato reduzem a visibilidade atmosférica.", "area": "mtec_base"}, {"num": 15, "stemHtml": "<p>O aquecimento do globo é um processo natural, mas que vem sendo intensificado pelas ações humanas, especialmente por meio da:</p>", "options": ["utilização de recursos renováveis.", "elevação do volume de água do mar.", "acentuação do processo de arenização.", "concentração de chuvas nas cidades.", "emissão de poluentes na atmosfera"], "answer": 4, "explain": "(E) O aquecimento global é intensificado pela emissão humana de gases poluentes na atmosfera.", "area": "mtec_base"}, {"num": 16, "stemHtml": "<p>A quantidade permitida de emissão de gases poluentes e as leis que regem o sistema de créditos de carbono foram definidas durante as negociações:</p>", "options": ["da ECO-92", "da Agenda 21", "da Rio+20", "do Protocolo de Kyoto", "da Conferência de Estocolmo"], "answer": 3, "explain": "(D) Os limites de emissão de gases e o sistema de créditos de carbono foram definidos no Protocolo de Kyoto.", "area": "mtec_base"}, {"num": 17, "stemHtml": "<p>As massas moleculares do álcool etílico (C2H5OH) e do ácido acético (C2H4O2) são respectivamente:</p>", "options": ["60 u e 46 u", "66 u e 40 u", "46 u e 66 u", "40 u e 66 u", "46 u e 60 u"], "answer": 4, "explain": "(E) C₂H₅OH = (2×12)+(6×1)+16 = 46 u; C₂H₄O₂ = (2×12)+(4×1)+(2×16) = 60 u.", "area": "mtec_base"}, {"num": 18, "stemHtml": "<p>Um químico recebeu três amostras sólidas (X, Y, Z) e, após alguns testes, obteve os seguintes resultados: I. X conduziu eletricidade no estado sólido. II. Y não conduziu eletricidade no estado sólido, mas conduziu no estado líquido. III. Z não conduziu eletricidade no estado sólido nem no estado líquido. Analisando os resultados obtidos, é correto afirmar que X, Y e Z são, respectivamente,</p>", "options": ["composto iônico, composto molecular, metal.", "metal, composto iônico, composto molecular.", "composto iônico, metal, composto molecular.", "composto molecular, metal, composto iônico.", "metal, composto molecular, composto iônico."], "answer": 1, "explain": "(B) X (conduz no sólido) = Metal; Y (só conduz quando líquido/fundido) = Composto Iônico; Z (não conduz nem sólido nem líquido) = Composto Molecular.", "area": "mtec_base"}, {"num": 19, "stemHtml": "<p>Dentre as alternativas sobre conjuntos numéricos, assinale a alternativa falsa:</p>", "options": ["o conjunto dos números naturais ℕ constituem o modelo matemático para a contagem sendo que o primeiro elemento desse conjunto é zero, o sucessor do zero é o 1, o sucessor do 1 é o 2, e assim por diante.", "Reunindo os números naturais e os números inteiros negativos, obtemos o conjunto dos números inteiros ℤ", "O conjunto ℚ dos números racionais é formado por todos os números que podem ser escritos na forma de fração com numerador e denominador inteiros e denominador diferente de zero", "O conjunto dos números irracionais I são formados pelos números incomensuráveis e pelas dízimas periódicas", "O conjunto dos números reais ℝ compreende a união dos conjuntos dos números racionais e irracionais"], "answer": 3, "explain": "(D) É FALSA porque dízimas periódicas podem ser escritas como fração, portanto pertencem aos Racionais (ℚ), NÃO aos Irracionais!", "area": "mtec_base"}, {"num": 20, "stemHtml": "<p>Considerando a função quadrática f(x)= x2 –2x – 3, podemos afirmar que:</p>", "options": ["É uma parábola com concavidade voltada para baixo", "Possui duas raízes reais", "Não tem solução", "O vértice da parábola é um ponto de máximo", "Possui duas raízes reais e iguais"], "answer": 1, "explain": "(B) Em f(x) = x² - 2x - 3, Δ = (-2)² - 4(1)(-3) = 4 + 12 = 16 > 0, logo possui duas raízes reais distintas (3 e -1) e concavidade para cima.", "area": "mtec_base"}, {"num": 21, "stemHtml": "<p>Feito o levantamento de um terreno, foram determinados os dados indicados a seguinte figura. Nessas condições, qual é a área do terreno?</p>\n<div style=\"text-align:center; margin:10px 0;\">\n  <svg width=\"260\" height=\"190\" viewBox=\"0 0 260 190\" style=\"background:#f8fafc; border:1px solid #cbd5e1; border-radius:10px;\">\n    <!-- Triangulo retangulo superior: catetos 40m e 30m, hipotenusa tracejada 50m -->\n    <polygon points=\"50,70 154,22 210,70\" fill=\"#dbeafe\" stroke=\"#1e293b\" stroke-width=\"2\"/>\n    <line x1=\"50\" y1=\"70\" x2=\"210\" y2=\"70\" stroke=\"#475569\" stroke-width=\"1.5\" stroke-dasharray=\"5,4\"/>\n    <!-- Angulo reto no vertice superior -->\n    <rect x=\"148\" y=\"25\" width=\"9\" height=\"9\" transform=\"rotate(24 154 22)\" fill=\"none\" stroke=\"#dc2626\" stroke-width=\"1.5\"/>\n    <!-- Trapezio inferior: base maior 50m, base menor 36m, altura 40m -->\n    <polygon points=\"50,70 210,70 165,162 50,162\" fill=\"#e0f2fe\" stroke=\"#1e293b\" stroke-width=\"2\"/>\n    <!-- Angulos retos a esquerda -->\n    <rect x=\"50\" y=\"70\" width=\"9\" height=\"9\" fill=\"none\" stroke=\"#1e293b\" stroke-width=\"1.5\"/>\n    <rect x=\"50\" y=\"153\" width=\"9\" height=\"9\" fill=\"none\" stroke=\"#1e293b\" stroke-width=\"1.5\"/>\n    <!-- Cotas -->\n    <text x=\"88\" y=\"38\" font-size=\"13\" font-weight=\"bold\" fill=\"#0f172a\">40 m</text>\n    <text x=\"190\" y=\"42\" font-size=\"13\" font-weight=\"bold\" fill=\"#0f172a\">30 m</text>\n    <text x=\"14\" y=\"122\" font-size=\"13\" font-weight=\"bold\" fill=\"#0f172a\">40 m</text>\n    <text x=\"94\" y=\"180\" font-size=\"13\" font-weight=\"bold\" fill=\"#0f172a\">36 m</text>\n  </svg>\n</div>\n", "options": ["2100 m²", "2250 m²", "2320 m²", "2400 m²", "2410 m²"], "answer": 2, "explain": "(C) Triângulo superior (30-40-50): área = (40×30)/2 = 600 m²; hipotenusa = 50 m. Trapézio inferior: [(50+36)×40]/2 = 1720 m². Total = 600 + 1720 = 2320 m².", "area": "mtec_base"}, {"num": 22, "stemHtml": "<p>Dados os conjuntos A = {0, 3, 4, 5, 6, 7, 8}, B = {2, 4, 5, 6, 9} e C = {0, 3, 6, 9, 10}, o conjunto que corresponde a (A ∩ B) ∪ C é:</p>", "options": ["{0, 3, 4, 5, 6, 9, 10}", "{0, 2, 3, 4, 5, 6, 7, 8, 9, 10}", "{4, 5, 6}", "{6}", "{0, 2, 3, 4, 5, 6, 7, 8, 9}"], "answer": 0, "explain": "(A) A ∩ B = {4, 5, 6}. Fazendo a união com C = {0, 3, 6, 9, 10}, obtemos {0, 3, 4, 5, 6, 9, 10}.", "area": "mtec_base"}, {"num": 23, "stemHtml": "<p>De quantas maneiras um número com 3 algarismos distintos pode ser formado utilizando 0, 1, 2, 3, 4 e 5?</p>", "options": ["200", "150", "250", "100", "300"], "answer": 3, "explain": "(D) Número de 3 algarismos com {0,1,2,3,4,5}: a 1ª posição NÃO pode ser 0 (5 opções: 1..5); a 2ª posição tem 5 opções (incluindo o 0); a 3ª tem 4 opções. Total = 5 × 5 × 4 = 100.", "area": "mtec_base"}, {"num": 24, "stemHtml": "<p>Os nossos ancestrais dedicavam-se à caça, à pesca e à coleta de frutas e vegetais, garantindo sua subsistência, porque ainda não conheciam as práticas de agricultura e pecuária. Uma vez esgotados os alimentos, viam-se obrigados a transferir o acampamento para outro lugar. HALL, P. P. Gestão ambiental. São Paulo: Pearson, 2011 (adaptado). O texto refere-se ao movimento migratório denominado</p>", "options": ["pendularismo.", "nomadismo.", "êxodo rural.", "transumância.", "sedentarismo."], "answer": 1, "explain": "(B) Mudar de acampamento constantemente após esgotar alimentos caracteriza o nomadismo.", "area": "mtec_base"}, {"num": 25, "stemHtml": "<p>A pré-história costuma ser dividida em três períodos, paleolítico, neolítico e idade dos metais. São características do período paleolítico, EXCETO:</p>", "options": ["Os homens deste período eram nômades e viviam essencialmente de caça e coletas.", "Uma descoberta essencial deste período foi a descoberta de como produzir fogo.", "Usavam ossos e pedras para confeccionar ferramentas e armas para caça, cortar e fazer suas vestes.", "Neste período domesticaram animais, juntamente com mudanças climáticas que aumentou a temperatura terrestre.", "Os homens desse período desenvolveram o código de Hamurabi."], "answer": 3, "explain": "(D) Gabarito oficial (D) — domesticação de animais e agricultura são características marcantes do Neolítico (não do Paleolítico).", "area": "mtec_base"}, {"num": 26, "stemHtml": "<p>“Perguntaram a antropóloga americana Margaret Mead o que ela considerava como primeiro sinal de civilização numa cultura. Ela disse que era um fêmur que havia quebrado e logo foi curado. No reino animal ninguém sobrevive com este osso quebrado. Um fêmur curado é a evidência que alguém foi cuidado”. Segundo a ideia de Margaret Mead, além do fêmur curado, poderíamos citar como sinal de civilização:</p>", "options": ["o sedentarismo.", "o enterro dos mortos.", "a domesticação de animais.", "a criação da roda.", "a criação da escrita."], "answer": 1, "explain": "(B) O cuidado com um membro ferido e rituais como o enterro dos mortos indicam laços sociais e início da civilização.", "area": "mtec_base"}, {"num": 27, "stemHtml": "<p>Foi uma característica do feudalismo:</p>", "options": ["Vida exclusivamente urbana.", "Valorização da liberdade religiosa.", "Diminuição do uso da moeda.", "Uso de mão de obra escravizada em larga escala.", "Poder unificado em apenas um grande reino."], "answer": 3, "explain": "(D) Gabarito oficial da prova: (D). *(Observação didática: historicamente o feudalismo baseou-se na servidão e na diminuição da moeda; no gabarito oficial desta unidade escolar foi marcada a letra D)*.", "area": "mtec_base"}, {"num": 28, "stemHtml": "<p>As principais características do empreendedor: I. Saber fixar metas e alcançá-las, ter forte intuição e comprometimento com o que faz; II. Ter iniciativa, autonomia, autoconfiança, otimismo, perseverança, ser inovador e criativo; III. Saber buscar, utilizar e controlar recursos e manter rede de relações. Estão corretas as afirmativas:</p>", "options": ["somente I.", "I, II e III", "II e III.", "I e III.", "somente II."], "answer": 1, "explain": "(B) Todas as três afirmativas (I, II e III) descrevem corretamente características do perfil empreendedor.", "area": "prog"}, {"num": 29, "stemHtml": "<p>A análise de mercado é um dos componentes do plano de negócios que está relacionado ao marketing da organização. Ela apresenta o entendimento do mercado da empresa, seus clientes, seus concorrentes e quanto a empresa conhece, em dados e informações, o mercado onde atua. A análise do mercado permite ainda que se conheça de perto o ambiente onde o produto/serviço se encontra. O mercado está composto pelo ambiente em que a empresa e o produto se localizam, pela concorrência e pelo perfil do consumidor. O conjunto das análises dos ambientes interno e externo (Pontos Fortes, Fracos, Oportunidades e Ameaças), é também conhecida como:</p>", "options": ["Plano de marketing", "Planejamento estratégico", "Análise SWOT", "Plano operacional", "Matriz BCG"], "answer": 2, "explain": "(C) Análise dos ambientes interno (Forças/Fraquezas) e externo (Oportunidades/Ameaças) = Análise SWOT.", "area": "prog"}, {"num": 30, "stemHtml": "<p>O que é UML?</p>", "options": ["É uma linguagem de diagramas unificada que habilita profissionais de TI a modelar e documentar aplicações de software.", "É uma linguagem de aplicação com uso de diagramas, que inclui atividades, componentes individuais de sistemas.", "É uma linguagem de arquitetura com interação entre os sistemas.", "Todas as repostas acima estão corretas.", "Nenhuma das respostas acima estão corretas."], "answer": 0, "explain": "(A) UML = Unified Modeling Language (linguagem unificada de diagramas para modelar e documentar sistemas).", "area": "prog"}, {"num": 31, "stemHtml": "<p>Sobre Requisitos, complete a frase. Os requisitos funcionais referem-se sobre o que sistema____, ou seja, suas ____ e informações.</p>", "options": ["deve fazer, funções", "irá planejar, entidades", "deve priorizar, entidades.", "corrigir, fases", "nomear, enviar"], "answer": 0, "explain": "(A) Requisitos funcionais definem o que o sistema deve fazer, ou seja, suas funções e informações.", "area": "prog"}, {"num": 32, "stemHtml": "<p>Escolha a alternativa que complete adequadamente a afirmação. “Um dicionário de dados é uma coleção de _____, ____ e definições sobre elementos de ____ que estão sendo usados em seu estudo”.</p>", "options": ["Objetos, atributos, entidades.", "Caraterísticas, dados, relacionamentos.", "Relacionamentos, atributos, entidades.", "Nomes, atributos, dados.", "Nenhuma das respostas acima estão corretas."], "answer": 3, "explain": "(D) Dicionário de dados é uma coleção de nomes, atributos e definições sobre elementos de dados.", "area": "bd"}, {"num": 33, "stemHtml": "<p>Quando enxergamos um tomate e este é vermelho, por que enxergamos essa cor?</p>", "options": ["Há uma refração da cor vermelha.", "O tomate possui um corante natural que projeta essa cor visualmente.", "Há uma mixagem de cores que resulta no vermelho.", "Há uma reflexão da cor vermelha.", "Há uma filtragem da cor vermelha."], "answer": 3, "explain": "(D) Enxergamos um objeto vermelho porque ele absorve as outras cores da luz e reflete a cor vermelha.", "area": "mtec_base"}, {"num": 34, "stemHtml": "<p>Hardware é:</p>", "options": ["Conjunto de programas.", "Unidade unificada.", "Maquinário.", "Linguagem de máquina.", "As alternativas B, C e D estão corretas."], "answer": 2, "explain": "(C) Hardware corresponde à parte física/maquinário do sistema computacional.", "area": "web_redes"}, {"num": 35, "stemHtml": "<p>Sistema operacional é:</p>", "options": ["Uma interface entre peopleware e hardware.", "Uma interface entre hardware e bibliotecas.", "Um conjunto de bibliotecas de hardware.", "Todas as alternativas.", "Nenhuma das alternativas."], "answer": 0, "explain": "(A) Sistema Operacional atua como interface entre o usuário/aplicações (peopleware/software) e o hardware.", "area": "web_redes"}, {"num": 36, "stemHtml": "<p>Software livre é:</p>", "options": ["Software gratuito.", "Software com permissão de alteração no código-fonte.", "A e B são verdadeiras, mas nem sempre A implica em B.", "A e B são verdadeiras, e A sempre implica em B.", "A e B são alternativas falsas."], "answer": 2, "explain": "(C) Software livre garante permissão de alterar o código-fonte, podendo ser gratuito ou pago (nem sempre A implica em B).", "area": "prog"}, {"num": 37, "stemHtml": "<p>Projeto de sistemas é melhor aproveitado com:</p>", "options": ["trabalho em equipe e divisão de tarefas e prazos", "trabalho em equipe e divisão de prazos, mas não de tarefas", "trabalho em equipe e divisão de tarefas, mas não de prazos", "as alternativas A, B e C estão corretas", "nenhuma das alternativas está correta."], "answer": 0, "explain": "(A) Trabalho em equipe com divisão clara de tarefas e prazos.", "area": "prog"}, {"num": 38, "stemHtml": "<p>div é um elemento:</p>", "options": ["inline.", "externo.", "de bloco.", "inline e externo.", "externo e de bloco."], "answer": 2, "explain": "(C) Em HTML/CSS, &lt;div&gt; é por padrão um elemento de bloco (display: block).", "area": "web_redes"}, {"num": 39, "stemHtml": "<p>ol e ul são, respectivamente:</p>", "options": ["ordered list e unofficial list.", "official list e unordered list.", "ordered list e unordered list.", "ordered link e unordered link.", "official link e unofficial link."], "answer": 2, "explain": "(C) &lt;ol&gt; = ordered list (lista ordenada); &lt;ul&gt; = unordered list (lista não ordenada).", "area": "web_redes"}, {"num": 40, "stemHtml": "<p>O elemento body refere-se ao:</p>", "options": ["cabeçalho de uma página.", "corpo finito.", "corpo da página.", "corpo da linha.", "corpo de dados."], "answer": 2, "explain": "(C) &lt;body&gt; representa o corpo visível da página HTML.", "area": "web_redes"}]}, "ds2025": {"id": "ds2025", "title": "Prova Real Fundação FAT — DS (1º SEM/2025)", "badge": "Fundação FAT • 30 Questões", "desc": "A prova oficial mais recente da Fundação FAT para Vagas Remanescentes do 2º Módulo em Desenvolvimento de Sistemas.", "minutes": 240, "questions": [{"num": 1, "stemHtml": "<p>Leia o texto para responder às questões 1 e 2.</p>\n<p>What is critical thinking? Critical thinking generally involves using logic and rationality to decide what to believe or how to act in a given situation. Employees with strong critical thinking skills tend to be reflective, independent, and competent. When practicing critical thinking, individuals can connect ideas logically, evaluate arguments, identify errors, solve complex problems, and reflect on outcomes. Critical thinkers typically use this skill to deduce facts and predict results. This can empower them to become better problem-solvers compared to those who simply memorize details. Employers often value this skill, particularly in roles that require strategic planning. While considered a soft skill, critical thinking can be developed over time. &lt;https://tinyurl.com/3ef223eh&gt; Acesso em: 23.10.2024.</p>\n<p>De acordo com o texto, as habilidades relacionadas a critical thinking caracterizam pessoas</p>", "options": ["reflexivas e críticas para a memorização de detalhes.", "independentes e reflexivas para a solução de problemas.", "intuitivas e sensíveis para a valorização de cuidados suaves.", "competentes e lógicas para a busca de soluções imediatistas.", "racionais e competentes para a resolução de cálculos primários."], "answer": 1, "explain": "- <strong>Por que está certa:</strong> O texto diz <em>\"tend to be reflective, independent, and competent\"</em> e <em>\"become better problem-solvers compared to those who simply memorize details\"</em>. - <strong>Pegadinhas:</strong> (A) inverte para <em>\"memorização de detalhes\"</em> (o texto opõe critical thinking a memorizar); (C) <em>\"cuidados suaves\"</em> traduz literalmente <em>\"soft skill\"</em> ao pé da letra; (D) <em>\"imediatistas\"</em>; (E) <em>\"cálculos primários\"</em>.", "area": "ingles_etica"}, {"num": 2, "stemHtml": "<p>Leia o texto para responder às questões 1 e 2.</p>\n<p>What is critical thinking? Critical thinking generally involves using logic and rationality to decide what to believe or how to act in a given situation. Employees with strong critical thinking skills tend to be reflective, independent, and competent. When practicing critical thinking, individuals can connect ideas logically, evaluate arguments, identify errors, solve complex problems, and reflect on outcomes. Critical thinkers typically use this skill to deduce facts and predict results. This can empower them to become better problem-solvers compared to those who simply memorize details. Employers often value this skill, particularly in roles that require strategic planning. While considered a soft skill, critical thinking can be developed over time. &lt;https://tinyurl.com/3ef223eh&gt; Acesso em: 23.10.2024.</p>\n<p>A palavra outcomes é compreendida no texto como</p>", "options": ["saídas.", "tarefas.", "exclusões.", "passagens.", "resultados."], "answer": 4, "explain": "- <strong>Por que está certa:</strong> <em>\"reflect on outcomes\"</em> = refletir sobre <strong>resultados</strong> (sinônimo de <em>results</em>, citado na frase seguinte). - <strong>Pegadinhas:</strong> (A) <em>\"saídas\"</em> confunde <em>outcomes</em> com <em>outputs/exits</em>.", "area": "ingles_etica"}, {"num": 3, "stemHtml": "<div class=\"q-infographic\">\n  <strong>Infográfico — Critical Thinking Skills:</strong>\n  <ol style=\"margin:6px 0 0 18px; padding:0;\">\n    <li><strong>Observation:</strong> The ability to notice and predict opportunities, problems and solutions.</li>\n    <li><strong>Analysis:</strong> The gathering, understanding and interpreting of data and other information.</li>\n    <li><strong>Inference:</strong> Drawing conclusions based on relevant data, information and personal knowledge and experience.</li>\n    <li><strong>Communication:</strong> Sharing and receiving information with others verbally, nonverbally and in writing.</li>\n    <li><strong>Problem solving:</strong> The process of gathering, analyzing and communicating information to identify and troubleshoot solutions.</li>\n  </ol>\n</div>\n\n<p>Leia o infográfico.</p>\n<p>&lt;https://tinyurl.com/3ef223eh&gt; Acesso em: 23.10.2024.Original colorido.</p>\n<p>De acordo com o infográfico, as habilidades relacionadas a critical thinking permeiam</p>", "options": ["a análise de datas e a antecipação de crises.", "a coleta de dados e o desenho de falsas informações.", "a comunicação de problemas e a busca por intérpretes.", "a antecipação de problemas e o compartilhamento de informações.", "a anotação de oportunidades e a identificação de pessoas inexperientes."], "answer": 3, "explain": "- <strong>Por que está certa:</strong> Item 1 (<em>Observation</em>): <em>\"predict opportunities, problems and solutions\"</em> (antecipação de problemas). Item 4 (<em>Communication</em>): <em>\"Sharing and receiving information\"</em> (compartilhamento de informações). - <strong>Pegadinha clássica:</strong> (A) <em>\"análise de datas\"</em> — falso cognato clássico traduzindo <strong>data</strong> (dados) como \"datas\"! (B) <em>\"falsa informação\"</em>; (C) <em>\"intérpretes\"</em> (confundindo com <em>interpreting</em>); (E) <em>\"anotação\" / \"inexperientes\"</em>.", "area": "ingles_etica"}, {"num": 4, "stemHtml": "<p>As ações comportamentais voltadas para a realização do bem comum define-se como comportamentos e decisões que indivíduos, grupos ou instituições tomam a fim de beneficiar a sociedade, interesses pessoais ou grupais. Essas ações são fundamentadas em valores como solidariedade, justiça, cooperação e responsabilidade social e visam criar um ambiente mais justo, seguro e próspero para todos os membros da sociedade. Nesse contexto, qual das seguintes alternativas exemplifica ação comportamental orientada para a realização do bem comum:</p>", "options": ["Maria doa seus livros antigos para a biblioteca da escola para liberar espaço em sua casa.", "João organizou uma campanha para coletar alimentos e distribuí-los para famílias em situação de vulnerabilidade em sua comunidade.", "Lucas decide comprar um carro mais caro para melhorar sua imagem perante os colegas de trabalho.", "Ana passa a trabalhar horas extras para ganhar uma promoção no trabalho, aumentando sua renda.", "João começa a participar, esporadicamente, de atividades de voluntariado, a fim de realizar postagens em redes sociais."], "answer": 1, "explain": "- <strong>Por que está certa:</strong> João coletou e distribuiu alimentos para famílias vulneráveis (benefício coletivo sem interesse próprio). - <strong>Pegadinhas:</strong> (A) Maria doou <em>\"para liberar espaço em casa\"</em>; (C) Lucas comprou carro por status; (D) Ana quer aumento próprio; (E) João faz voluntariado <em>\"para postagens em redes sociais\"</em>.", "area": "ingles_etica"}, {"num": 5, "stemHtml": "<p>No contexto das relações trabalhistas e de consumo, as ações comportamentais podem refletir tanto no compromisso com o bem-estar coletivo quanto nas atitudes que favorecem apenas os interesses pessoais. Com base nessa afirmação, qual das alternativas a seguir representa uma ação comportamental ética e responsável nas relações trabalhistas?</p>", "options": ["Realizar propaganda enganosa para aumentar o lucro de uma empresa.", "Demitir funcionários em massa para priorizar a saúde financeira da empresa, maximizando os lucros, sem considerar o impacto social.", "Negligenciar os direitos trabalhistas dos funcionários em prol da redução de custos.", "Implementar práticas de consumo consciente, buscando produtos sustentáveis ​​e de baixo impacto ambiental.", "Manter exclusivamente o foco no cliente, sem valorizar a qualidade de vida dos funcionários."], "answer": 3, "explain": "- <strong>Por que está certa:</strong> Consumo consciente, produtos sustentáveis e de baixo impacto ambiental. Todas as demais prejudicam consumidores ou funcionários (propaganda enganosa, demissão em massa sem impacto social, negligência trabalhista, ignorar qualidade de vida).", "area": "ingles_etica"}, {"num": 6, "stemHtml": "<p>A aplicação de ações éticas nos campos do direito constitucional e da legislação ambiental é fundamental para garantir os direitos fundamentais e a preservação do meio ambiente para as futuras gerações. Diante dessa afirmativa, qual das seguintes alternativas representa uma ação ética no contexto do direito constitucional e da lei?</p>", "options": ["Autorizar a exploração de áreas de proteção ambiental sem estudos de impacto.", "Implementar políticas públicas que garantam a participação das comunidades locais nas decisões sobre o uso de recursos naturais.", "Reduzir a fiscalização ambiental em regiões com alto índice de desmatamento para favorecer o desenvolvimento econômico.", "Permitir que as empresas utilizem recursos naturais sem qualquer contrapartida ambiental ou social.", "Priorizar o crescimento econômico sobre a preservação dos direitos ambientais das populações locais."], "answer": 1, "explain": "- <strong>Por que está certa:</strong> Políticas públicas garantindo participação das comunidades locais nas decisões sobre recursos naturais. Todas as outras violam leis ambientais.", "area": "ingles_etica"}, {"num": 7, "stemHtml": "<p>Um framework é uma estrutura de software reutilizável que fornece um conjunto de ferramentas, bibliotecas e diretrizes para facilitar o desenvolvimento de aplicativos. Ele define uma base padronizada que os desenvolvedores podem utilizar para construir funcionalidades de forma mais rápida e consistente, evitando a necessidade de codificar tarefas comuns desde o início.</p>\n<p>São exemplos de framework:</p>", "options": ["Laravel (PHP), React Native (Aplicativos Móveis), Angular (JavaScript) e Bootstrap (Interface de Usuário)", "Laravel (PHP), React Native (Aplicativos Móveis), Angular (JavaScript) e Adobe Creative Cloud (Interface de Usuário)", "Laravel (PHP), Creative Commons (Aplicativos Móveis), Angular (JavaScript) e Bootstrap (Interface de Usuário)", "Laravel (PHP), Creative Commons (Aplicativos Móveis), Angular (JavaScript) e Adobe Creative Cloud (Interface de Usuário)", "Laravel (PHP), React Native (Interface de Usuário), Angular (Aplicativos Móveis) e Bootstrap (JavaScript)"], "answer": 0, "explain": "- <strong>Por que está certa:</strong> <code>Laravel</code> (PHP), <code>React Native</code> (Mobile), <code>Angular</code> (JavaScript) e <code>Bootstrap</code> (UI/CSS). - <strong>Intrusos e Inversões:</strong> (B) e (D) trazem <strong>Adobe Creative Cloud</strong> (suíte de design/edição); (C) e (D) trazem <strong>Creative Commons</strong> (tipo de licença); (E) <strong>inverteu</strong> as descrições colocando React Native como UI, Angular como Mobile e Bootstrap como JS.", "area": "prog"}, {"num": 8, "stemHtml": "<p>Tipos de dados em programação são categorias que definem as características dos dados que podem ser armazenados e manipulados por um programa, como números, textos e valores booleanos. Cada tipo de dado ocupa uma quantidade específica de memória e oferece um conjunto de operações apropriadas para aquele tipo. Conversão de tipos é o processo de transformar um dado de um tipo para outro. Ela é importante para adaptar valores ao tipo necessário em uma determinada operação ou função.</p>\n<pre class='q-code'>Realizada automaticamente pelo compilador ou interpretador quando\nConversão Implícita\nI.  dois tipos são compatíveis e a conversão não envolve perda de dados\n(Type Coercion)\n(exemplo: converter int para float).</pre>\n<pre class='q-code'>Realizada automaticamente em tempos de execução de acordo com\nII.  Conversão Normal\no hardware e software do usuário.</pre>\n<pre class='q-code'>Feita manualmente pelo programador, quando uma conversão precisa\nConversão Explícita\nIII.  ser forçada, geralmente usando funções específicas, como int(), float()\n(Casting)\nou str().</pre>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente a afirmativa II está correta.", "somente as afirmativas I e III estão corretas.", "somente as afirmativas I e II estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 2, "explain": "- <strong>Item I (V):</strong> Conversão Implícita (<em>Type Coercion</em>) feita automaticamente quando compatível sem perda (ex.: <code>int</code> para <code>float</code>). - <strong>Item II (F):</strong> <em>\"Conversão Normal\"</em> <strong>não existe</strong> na teoria de tipos — nome inventado para confundir! - <strong>Item III (V):</strong> Conversão Explícita (<em>Casting</em>) forçada manualmente pelo programador (<code>int()</code>, <code>float()</code>, <code>str()</code>).", "area": "prog"}, {"num": 9, "stemHtml": "<pre class='q-code'>Teste de mesa é uma técnica de verificação manual usada em programação para analisar o comportamento\nde um algoritmo ou código, linha por linha, sem executá-lo em um computador. O objetivo é detectar\nerros lógicos, entender como as variáveis se comportam e validar se o algoritmo produz o resultado\nesperado. Durante o teste de mesa, o programador cria uma tabela para registrar o valor de cada\nvariável a cada passo do código, permitindo visualizar o fluxo e o resultado do programa.</pre>\n<p>A ação de seguir o fluxo do algoritmo, anotando as alterações de cada variável e o que acontece em cada instrução é conhecida como:</p>", "options": ["Definir o Algoritmo", "Preparar Tabelas", "Executar Linha a Linha", "Registrar Condições", "Validar o Resultado"], "answer": 2, "explain": "- <strong>Por que está certa:</strong> Seguir o fluxo anotando cada alteração de variável instrução por instrução é <strong>Executar Linha a Linha</strong> (etapa central do teste de mesa).", "area": "prog"}, {"num": 10, "stemHtml": "<p>Em programação, uma matriz é uma estrutura de dados que organiza elementos em uma grade bidimensional, ou seja, em linhas e colunas. As matrizes são frequentemente usadas para representar tabelas, gráficos, imagens e qualquer outro dado que envolva uma organização em duas dimensões.</p>\n<p>São características de uma Matriz:</p>\n<p>(1) Dimensões: Uma matriz tem duas dimensões principais (linha e coluna).</p>\n<p>(2) Índices: Cada elemento em uma matriz é acessado usando um par de índices — o índice da linha e o índice da coluna. Em muitas linguagens, os índices começam em 0, então o primeiro elemento está em [0][0].</p>\n<p>(3) Elementos: Cada posição na matriz contém um valor, que pode ser de qualquer tipo de dado, como inteiros, floats, strings, etc., dependendo do que a matriz deve representar.</p>\n<pre class='q-code'>Dada a matriz “M”, onde: Matriz “M” = [ [1, 3, 5], [2, 4, 8], [1, 1, 1] ]\na soma dos elementos da diagonal principal é representada pelo valor:</pre>", "options": ["9", "14", "3", "6", "10"], "answer": 3, "explain": "- <strong>Cálculo:</strong> Matriz <code>M = [[1, 3, 5], [2, 4, 8], [1, 1, 1]]</code>. - Diagonal principal = elementos onde <code>linha == coluna</code> (<code>M[0][0]</code>, <code>M[1][1]</code>, <code>M[2][2]</code>): - <code>M[0][0] = 1</code> - <code>M[1][1] = 4</code> - <code>M[2][2] = 1</code> - Soma: <code>1 + 4 + 1 = 6</code>. - <strong>Pegadinha:</strong> <code>5 + 4 + 1 = 10</code> (alternativa E) é a <strong>diagonal secundária</strong>! Não confunda!", "area": "prog"}, {"num": 11, "stemHtml": "<p>SQL (Structured Query Language) é uma linguagem de programação padrão usada para gerenciar e manipular bancos de dados relacionais. Ela permite executar diversas operações como consulta, inserção, atualização e exclusão de dados, além de criar e modificar a estrutura de tabelas e bancos de dados. SQL é essencial para interagir com sistemas de gerenciamento de bancos de dados relacionais (SGBDs) como MySQL, PostgreSQL, SQL Server e Oracle. Os principais componentes são:</p>\n<pre class='q-code'>DQL  Para definir a estrutura de dados, com comandos\nI.\n(Data Query Language)  como CREATE, ALTER e DROP.</pre>\n<pre class='q-code'>DML  Para modificar dados, incluindo comandos como\nII.\n(Data Manipulation Language)  INSERT, UPDATE e DELETE.</pre>\n<pre class='q-code'>DDL\nIII.  Para consultar dados, como a instrução SELECT.\n(Data Definition Language)</pre>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente a afirmativa II está correta.", "somente a afirmativa III está correta.", "somente as afirmativas II e III estão corretas.", "somente as afirmativas I e III estão corretas."], "answer": 1, "explain": "- <strong>Item I (F):</strong> Colocou a definição de <strong>DDL</strong> (<code>CREATE, ALTER, DROP</code>) no nome <strong>DQL</strong>! - <strong>Item II (V):</strong> <strong>DML</strong> (<em>Data Manipulation Language</em>) = <code>INSERT, UPDATE, DELETE</code>. - <strong>Item III (F):</strong> Colocou a definição de <strong>DQL</strong> (<code>SELECT</code>) no nome <strong>DDL</strong>!", "area": "bd"}, {"num": 12, "stemHtml": "<p>Um modelo relacional em banco de dados é uma abordagem para organizar dados em tabelas que se relacionam entre si, permitindo uma maneira eficiente de armazenar, acessar e manipular informações. Esse modelo é fundamentado na teoria dos conjuntos e utiliza a lógica matemática para garantir a integridade e a consistência dos dados. Os principais componentes do modelo relacional são:</p>\n<pre class='q-code'>Os dados são organizados em tabelas, onde cada tabela consiste em\nI.  Tabelas  linhas (tuplas) e colunas (atributos). Cada linha representa um registro\núnico, e cada coluna representa um campo de dado.</pre>\n<pre class='q-code'>Primária onde um atributo ou um conjunto de atributos identifica\nunicamente cada linha em uma tabela. Por exemplo, um número de\nidentificação (ID) pode servir como chave primária e Estrangeira onde\nII.  Chaves\num atributo em uma tabela que cria uma ligação com a chave primária\nde outra tabela estabelece uma relação entre as duas. Isso permite a\nintegridade.</pre>\n<pre class='q-code'>As tabelas podem se relacionar de várias maneiras (Um-para-Um, Um-\nIII.  Relacionamentos\npara-Muitos e Muitos-para-Muitos).</pre>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente a afirmativa II está correta.", "somente a afirmativa III está correta.", "somente as afirmativas II e III estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "- <strong>Itens I, II e III (V):</strong> Tabelas = linhas (<strong>tuplas</strong>) e colunas (<strong>atributos</strong>); Chaves = Primária (identifica unicamente) e Estrangeira (liga à PK de outra tabela); Relacionamentos = <code>1:1</code>, <code>1:N</code> e <code>N:N</code>.", "area": "bd"}, {"num": 13, "stemHtml": "<p>As formas normais são regras e diretrizes usadas no design de bancos de dados relacionais para estruturar dados de maneira a reduzir a redundância e melhorar a integridade dos dados. O processo de normalização envolve a organização dos dados em tabelas e a definição de relações entre elas, seguindo uma sequência de formas normais, cada uma com suas próprias características e requisitos. A forma normal ocorre quando todos os atributos contêm apenas valores atômicos (indivisíveis) e cada coluna é única e não deve haver grupos repetidos ou colunas que contenham conjuntos de dados com o objetivo de eliminar a duplicidade de dados em uma tabela e garantir que cada campo contenha apenas um valor.</p>\n<p>Essa afirmação refere-se:</p>", "options": ["Primeira Forma Normal (1NF)", "Segunda Forma Normal (2NF)", "Terceira Forma Normal (3NF)", "Forma Normal Boyce-Codd (BCNF)", "Quarta Forma Normal (4NF)"], "answer": 0, "explain": "- <strong>Por que está certa:</strong> Valores <strong>atômicos (indivisíveis)</strong>, sem grupos repetidos ou múltiplos valores na mesma célula = <strong>Primeira Forma Normal (1NF)</strong>.", "area": "bd"}, {"num": 14, "stemHtml": "<p>O comando SELECT do SQL é utilizado para consultar e recuperar dados de um banco de dados. Ele é um dos comandos mais importantes e frequentemente usados na linguagem SQL, permitindo que os usuários especifiquem quais colunas de quais tabelas desejam visualizar, além de aplicar filtros, ordenar resultados e realizar operações de agregação. O SELECT pode incluir funções de agregação, como COUNT(), SUM(), AVG(), entre outras, para realizar cálculos em conjuntos de dados.</p>\n<p>Com base nisso, qual instrução é adequada para contar o número total de clientes que residem em São Paulo?</p>", "options": ["SELECT * FROM clientes WHERE COUNT(cidade) = ‘São Paulo’;", "SELECT COUNT(‘São Paulo’) FROM clientes WHERE cidade;", "SELECT * FROM clientes WHERE cidade = COUNT(‘São Paulo’);", "SELECT COUNT(*) FROM clientes WHERE cidade = ‘São Paulo’;", "SELECT COUNT(*) WHERE clientes FROM cidade = ‘São Paulo’;"], "answer": 3, "explain": "- <strong>Por que está certa:</strong> <code>SELECT COUNT(*) FROM clientes WHERE cidade = 'São Paulo';</code>. - <strong>Pegadinhas:</strong> (A) e (C) usam <code>COUNT</code> dentro do <code>WHERE</code> (proibido em SQL); (B) coloca a string <code>'São Paulo'</code> dentro de <code>COUNT()</code> e deixa <code>WHERE cidade</code> incompleto; (E) inverte <code>WHERE</code> e <code>FROM</code>.", "area": "bd"}, {"num": 15, "stemHtml": "<p>Os elementos da sintaxe visual são os componentes utilizados na comunicação visual e no design gráfico, funcionando como as “ferramentas” que os designers empregam para criar composições e transmitir mensagens. Esses elementos incluem linha, que pode ser reta ou curva e ajuda a formar contornos e direções; forma, que abrange áreas bidimensionais geométricas ou orgânicas; cor, que influencia percepções e emoções; textura, que se refere à superfície visual e pode ser percebida visualmente ou de forma tátil; espaço, que organiza os elementos e cria hierarquia; tamanho, que define as dimensões relativas dos elementos; tipografia, que envolve a escolha e uso de fontes; layout, que se refere à disposição dos elementos; contraste, que destaca diferenças e cria hierarquia visual; e movimento, que pode ser sugerido por arranjos que guiam o olhar do espectador. Juntos, esses elementos formam a base para composições visuais eficazes e impactantes.</p>\n<p>São definidos como padrões de cores:</p>", "options": ["CMYK, RGB e Hexadecimal", "RGB, Hexadecimal e Primária", "CMYK, Hexadecimal e Primária", "CMYK, RGB, Hexadecimal e CSS", "CMYK, RGB, Hexadecimal, Primária e CSS"], "answer": 0, "explain": "- <strong>Por que está certa:</strong> <strong>CMYK, RGB e Hexadecimal</strong> são padrões de cores. - <strong>Intrusos:</strong> <em>\"Primária\"</em> (classificação de cor, não padrão) e <em>\"CSS\"</em> (linguagem de estilo).", "area": "design"}, {"num": 16, "stemHtml": "<p>Bancos de imagens são plataformas online que oferecem uma vasta coleção de fotografias, ilustrações, vetores, vídeos e outros tipos de conteúdos visuais, que podem ser usados por profissionais e amadores em projetos criativos. Esses bancos podem oferecer imagens gratuitas ou pagas, e as licenças variam, permitindo usos comerciais ou pessoais, dependendo dos termos de cada imagem. São características dos bancos de imagem:</p>\n<pre class='q-code'>Os bancos de imagens geralmente têm uma ampla gama\nI.  Variedade de Conteúdo  de categorias, que vão desde paisagens e retratos até imagens de\nnegócios e tecnologia.</pre>\n<pre class='q-code'>II.  Licenciamento  As imagens disponíveis podem ter diferentes tipos de licenças.</pre>\n<pre class='q-code'>As imagens são frequentemente disponíveis em diferentes\nIII.  Qualidade e Resolução\nresoluções e formatos, adequadas para impressão ou uso digital.</pre>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente a afirmativa II está correta.", "somente a afirmativa III está correta.", "somente as afirmativas II e III estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "- <strong>Itens I, II e III (V):</strong> Bancos de imagens oferecem variedade de conteúdo, tipos de licenças e múltiplas resoluções/formatos.", "area": "design"}, {"num": 17, "stemHtml": "<p>Gestalt é uma abordagem da psicologia que se concentra na compreensão da percepção humana e na maneira como as pessoas organizam e interpretam informações visuais. A palavra “Gestalt” é de origem alemã e significa “forma” ou “configuração”. O conceito central da Gestalt é que a mente humana tende a perceber objetos como um todo, em vez de como uma soma de partes isoladas. Essa abordagem é frequentemente resumida pela frase “o todo é diferente da soma das partes”. Os princípios da Gestalt são amplamente aplicados em várias áreas, como design gráfico, arquitetura, publicidade, usabilidade de interfaces e arte, pois ajudam a criar composições visuais que são mais agradáveis e eficazes na comunicação de mensagens. Os psicólogos da Gestalt identificaram vários princípios que explicam como percebemos e organizamos as informações visuais, dessa forma, o princípio segundo o qual as linhas e padrões que seguem uma trajetória contínua são percebidos como pertencentes a um mesmo elemento é definido como:</p>", "options": ["Proximidade", "Fechamento", "Figura e Fundo", "Semelhança", "Continuidade"], "answer": 4, "explain": "- <strong>Por que está certa:</strong> <em>\"linhas e padrões que seguem uma trajetória contínua\"</em> = <strong>Continuidade</strong>.", "area": "design"}, {"num": 18, "stemHtml": "<p>Imagens vetorizadas são representações gráficas criadas a partir de formas geométricas baseadas em vetores, que são definidos por pontos, linhas e curvas. Diferentemente das imagens rasterizadas (ou bitmap), que são compostas por pixels e perdem qualidade quando ampliadas, as imagens vetorizadas podem ser escaladas para qualquer tamanho sem perda de qualidade, pois os vetores são recalculados em tempo real com base nas fórmulas matemáticas que definem suas características. São exemplos de arquivos vetorizados:</p>", "options": ["SVG (Scalable Vector Graphics) e PDF (Portable Document Format)", "SVG (Scalable Vector Graphics), PDF (Portable Document Format) e JPEG (Joint Photographic Experts Group)", "SVG (Scalable Vector Graphics), PDF (Portable Document Format) e PNG (Portable Network Graphics)", "JPEG (Joint Photographic Experts Group), PNG (Portable Network Graphics) e Bitmap (BMP)", "JPEG (Joint Photographic Experts Group) e PNG (Portable Network Graphics)"], "answer": 0, "explain": "- <strong>Por que está certa:</strong> <strong>SVG</strong> e <strong>PDF</strong> suportam gráficos vetoriais. - <strong>Intrusos:</strong> <strong>JPEG</strong>, <strong>PNG</strong> e <strong>BMP</strong> são todos <strong>bitmap/raster</strong> (compostos por pixels).", "area": "design"}, {"num": 19, "stemHtml": "<p>Editores de HTML são programas ou ferramentas que permitem aos usuários criar, editar e manipular documentos HTML (Hypertext Markup Language), que são usados para construir páginas da web. Esses editores oferecem uma variedade de recursos que facilitam a escrita de código HTML e a visualização do resultado final em um navegador. São características dos editores:</p>\n<pre class='q-code'>Programas especializados, como Visual Studio Code, Sublime Text e\nEditores de\nI.  Atom, que oferecem recursos como realce de sintaxe, autocompletar, e\nCódigo\nsuporte a extensões para melhorar a experiência de desenvolvimento.</pre>\n<pre class='q-code'>Editores  Ferramentas como Adobe Dreamweaver e Wix que permitem aos\nWYSIWYG (What  usuários criar páginas da web visualmente, arrastando e soltando\nII.\nYou See Is What  elementos, enquanto o código HTML é gerado automaticamente em\nYou Get)  segundo plano.\nAmbientes de\nFerramentas básicas como o Notepad (Windows) ou TextEdit (Mac)\nIII.  Desenvolvimento\nque permitem a edição de código HTML sem recursos avançados.\nIntegrados (IDEs)</pre>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas I e III estão corretas.", "somente as afirmativas II e III estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 1, "explain": "- <strong>Item I (V):</strong> Editores de Código (VS Code, Sublime Text, Atom — realce de sintaxe, autocompletar, extensões). - <strong>Item II (V):</strong> Editores WYSIWYG (Dreamweaver, Wix — arrastar e soltar visualmente). - <strong>Item III (F):</strong> Diz que <strong>IDEs</strong> são ferramentas básicas como <em>Notepad</em> ou <em>TextEdit</em> sem recursos avançados! Na verdade, Notepad/TextEdit são <strong>editores de texto simples</strong>; IDEs (Eclipse, Visual Studio, IntelliJ) são ambientes completos com compilador/depurador.", "area": "prog"}, {"num": 20, "stemHtml": "<p>Hyperlinks (ou links) em HTML são elementos que permitem a navegação de uma página da web para outra ou para diferentes partes da mesma página. Eles são fundamentais para a estrutura da web, pois conectam informações e permitem que os usuários acessem conteúdos relacionados com facilidade. Um hyperlink é criado usando a tag “&lt;a&gt;”, que significa “ancora”. Em sua sintaxe, o “target” define onde o link será aberto, dessa forma, para abrir um link em uma nova aba ou janela, utiliza-se o parâmetro:</p>", "options": ["_self:", "_blank:", "_parent:", "_top:", "_none:"], "answer": 1, "explain": "- <strong>Por que está certa:</strong> Abrir em nova aba/janela = <code>target=\"_blank\"</code>. (<code>_self</code> abre na mesma aba; <code>_parent</code> no frame pai; <code>_top</code> na janela inteira; <code>_none</code> não existe).", "area": "web_redes"}, {"num": 21, "stemHtml": "<p>Cookies são pequenos arquivos de texto que são armazenados no navegador do usuário, quando ele visita um site. Eles desempenham um papel crucial na navegação na web, permitindo que os sites “lembrem-se” de informações sobre os usuários entre as sessões. São características dos cookies:</p>\n<pre class='q-code'>Armazenamento  Cookies são armazenados em nuvem e contêm dados que podem ser\nI.\nem nuvem  acessados pelo site que os criou.</pre>\n<pre class='q-code'>Cada cookie é limitado a cerca de 4 KB de tamanho, e um site pode\nII.  Tamanho\narmazenar um número limitado de cookies.</pre>\n<pre class='q-code'>Cookies podem ser temporários (sessão) ou permanentes. Cookies\nde sessão são excluídos quando o navegador é fechado, enquanto\nIII.  Duração\ncookies permanentes permanecem até que expirem ou sejam\nremovidos pelo usuário.</pre>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente a afirmativa II está correta.", "somente a afirmativa III está correta.", "somente as afirmativas II e III estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 3, "explain": "- <strong>Item I (F):</strong> Diz que <em>\"Cookies são armazenados em nuvem\"</em>! Falso: o próprio enunciado já entregava que ficam <strong>armazenados no navegador do usuário</strong> (armazenamento local). - <strong>Item II (V):</strong> Cada cookie tem limite de cerca de <strong>4 KB</strong>. - <strong>Item III (V):</strong> Podem ser de <strong>sessão</strong> (excluídos ao fechar o navegador) ou <strong>permanentes</strong>.", "area": "web_redes"}, {"num": 22, "stemHtml": "<p>Ferramentas de build e bundling são softwares que ajudam os desenvolvedores a automatizar o processo de compilação, empacotamento e gerenciamento de recursos em projetos de desenvolvimento de software, especialmente em aplicações web. Elas desempenham um papel importante na otimização e eficiência do desenvolvimento, garantindo que o código e os ativos sejam organizados e preparados para produção.</p>\n<pre class='q-code'>Automatizam tarefas como compilação de código-fonte, execução de\nFerramentas  testes, minificação e otimização de arquivos, e criação de pacotes finais\nI.\nde build  para distribuição. Elas ajudam a manter a consistência e a reprodutibilidade\nno processo de desenvolvimento.</pre>\n<pre class='q-code'>São usadas para empacotar múltiplos arquivos e recursos (como scripts\nJavaScript, folhas de estilo CSS e imagens) em um ou mais arquivos\nFerramentas\nII.  menores para otimizar o carregamento e a performance da aplicação.\nde bundling\nElas ajudam a reduzir o número de requisições HTTP e a melhorar o\ntempo de carregamento das páginas.</pre>\n<pre class='q-code'>Melhoria na  Muitas ferramentas de build incluem testes automatizados, o que ajuda\nIII.  Qualidade  a garantir que o código funcione corretamente, antes de ser implantado.\ndo Código</pre>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente a afirmativa II está correta.", "somente a afirmativa III está correta.", "somente as afirmativas II e III estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "- <strong>Itens I, II e III (V):</strong> Definições corretas de <em>build</em> (compilação, testes, minificação, pacotes finais), <em>bundling</em> (empacotar JS/CSS/imagens em menos arquivos para reduzir requisições HTTP) e qualidade (testes automatizados).", "area": "prog"}, {"num": 23, "stemHtml": "<p>Licenciamento de software é o processo pelo qual um desenvolvedor ou empresa concede permissão a usuários para utilizar um software específico sob determinadas condições. Esse licenciamento pode incluir restrições quanto à forma de uso, redistribuição, modificação e acesso ao código-fonte, além de especificar os direitos e responsabilidades tanto do licenciante quanto do licenciado. O software que é disponibilizado com acesso ao código-fonte, permitindo que os usuários o modifiquem e o redistribuam sob determinadas condições cujas licenças promovem a colaboração e a transparência é conhecido como:</p>", "options": ["Licenças Proprietárias", "Licenças de Código Aberto (Open Source)", "Licenças Livres", "Licenças de Uso (End-User License Agreement – EULA)", "Licenciamento por Assinatura"], "answer": 1, "explain": "- <strong>Por que está certa:</strong> A frase <em>\"cujas licenças promovem a colaboração e a transparência\"</em> e <em>\"acesso ao código-fonte, permitindo que modifiquem e redistribuam sob determinadas condições\"</em> corresponde na terminologia da banca a *<em>Licenças de Código Aberto (</em>Open Source<em>)</em><em>. </em>(Nota: na prova de 2022 M-Tec, Software Livre enfatiza a liberdade ética/permissão de alterar mesmo se pago ou gratuito; na FAT 2025, \"colaboração e transparência\" apontou especificamente para Open Source).*", "area": "prog"}, {"num": 24, "stemHtml": "<p>IoT (Internet of Things) ou Internet das Coisas é uma rede de objetos físicos, como dispositivos, veículos, eletrodomésticos e outros itens, que estão conectados à internet e são capazes de coletar e trocar dados entre si. Esses dispositivos, geralmente, incluem sensores, software e outras tecnologias que permitem a coleta e compartilhamento de informações, muitas vezes, em tempo real, para otimizar e automatizar processos, monitorar o ambiente e melhorar a experiência do usuário. A IoT é amplamente utilizada em diversos setores, incluindo:</p>\n<pre class='q-code'>Residências inteligentes com dispositivos como assistentes\nI.\nvirtuais, câmeras de segurança e termostatos conectados.</pre>\n<pre class='q-code'>Cidades inteligentes com sistemas para monitoramento de\nII.\ntráfego, iluminação pública e controle de poluição.</pre>\n<pre class='q-code'>Indústria com sensores em máquinas para manutenção preditiva\ne aumento de eficiência e na saúde por meio de dispositivos\nIII.\nmédicos que monitoram condições de saúde e enviam dados ao\nmédico em tempo real.</pre>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente a afirmativa II está correta.", "somente a afirmativa III está correta.", "somente as afirmativas II e III estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "- Aplicações reais de <strong>IoT</strong>: residências inteligentes, cidades inteligentes e indústria/saúde com sensores.", "area": "web_redes"}, {"num": 25, "stemHtml": "<p>Protocolos de rede são conjuntos de regras e padrões que definem como os dispositivos em uma rede se comunicam entre si. Eles estabelecem as diretrizes para a transmissão, recepção e processamento de dados, garantindo que todos os dispositivos na rede “falem a mesma língua”. Sem os protocolos, a comunicação entre dispositivos de diferentes fabricantes ou sistemas seria caótica e ineficaz. O protocolo básico da internet é responsável por dividir os dados em pacotes e direcioná-los até o destino correto, reagrupando-os na chegada. O protocolo fundamental para comunicação em redes e na internet é conhecido como:</p>", "options": ["TCP/IP (Transmission Control Protocol/Internet Protocol)", "HTTP/HTTPS (HyperText Transfer Protocol/Secure)", "FTP (File Transfer Protocol)", "SMTP (Simple Mail Transfer Protocol)", "DNS (Domain Name System)"], "answer": 0, "explain": "- <strong>Por que está certa:</strong> Protocolo básico da internet que divide dados em pacotes e os direciona ao destino = <strong>TCP/IP</strong>.", "area": "web_redes"}, {"num": 26, "stemHtml": "<p>Uma rede de computadores é um conjunto de dispositivos, como computadores, servidores, roteadores e outros equipamentos, que estão conectados entre si para compartilhar recursos e trocar informações. Essa conexão pode ser estabelecida por meio de cabos, como em redes Ethernet, ou de forma sem fio, como em redes Wi-Fi. Em redes de computadores, a topologia refere-se à forma como os dispositivos estão organizados e interconectados física ou logicamente. Cada tipo de topologia apresenta características específicas, influenciando fatores como desempenho, custo e complexidade de implementação e manutenção. Topologia ocorre quando todos os dispositivos são conectados a um único cabo central (o barramento), onde os dados transmitidos viajam pelo cabo e podem ser acessados por qualquer dispositivo da rede, sendo simples e barata, mas apresenta problemas de desempenho e confiabilidade, pois se o cabo principal falhar, toda a rede é afetada.</p>\n<p>Essa afirmação refere-se à topologia:</p>", "options": ["Topologia em Anel (Ring)", "Topologia em Estrela (Star)", "Topologia em Malha (Mesh)", "Topologia em Barramento (Bus)", "Topologia Híbrida"], "answer": 3, "explain": "- <strong>Por que está certa:</strong> <em>\"conectados a um único cabo central (o barramento)... se o cabo principal falhar, toda a rede é afetada\"</em> = <strong>Topologia em Barramento (Bus)</strong>.", "area": "web_redes"}, {"num": 27, "stemHtml": "<p>Um sistema operacional (SO) é o software fundamental que gerencia e controla o hardware de um computador, além de fornecer uma interface para que o usuário interaja com o sistema. Ele atua como uma ponte entre os programas e o hardware, coordenando recursos como memória, processamento, armazenamento e dispositivos de entrada e saída. Gerenciamento que visa organizar o uso da memória RAM, alocando e liberando espaço para programas em execução e otimizando o desempenho do sistema, é definido como:</p>", "options": ["Gerenciamento de Processos", "Gerenciamento de Memória", "Gerenciamento de Dispositivos de Entrada e Saída", "Gerenciamento de Arquivos", "Interface com o Usuário"], "answer": 1, "explain": "- <strong>Por que está certa:</strong> <em>\"organizar o uso da memória RAM, alocando e liberando espaço\"</em> = <strong>Gerenciamento de Memória</strong>.", "area": "web_redes"}, {"num": 28, "stemHtml": "<p>Gerenciadores de e-mail são aplicativos ou softwares projetados para facilitar o envio, recebimento, organização e gerenciamento de mensagens de e-mail. Eles oferecem uma interface que permite aos usuários acessar múltiplas contas de e-mail, categorizar mensagens, anexar arquivos, responder automaticamente, entre outras funcionalidades. Esses programas conectam-se a servidores de e-mail usando protocolos, permitindo o acesso aos e-mails armazenados online ou o download para leitura offline.</p>\n<pre class='q-code'>Permite que os usuários acessem e gerenciem\nSMTP (Simple Mail\nI.  seus e-mails diretamente no servidor, mantendo as\nTransfer Protocol)\nmensagens sincronizadas entre múltiplos dispositivos</pre>\n<pre class='q-code'>O POP3 permite que os usuários baixem e-mails do\nPOP3 (Post Office  servidor para seus dispositivos locais, geralmente\nII.\nProtocol version 3)  excluindo as mensagens do servidor após a\ntransferência.</pre>\n<pre class='q-code'>É o protocolo responsável pelo envio de e-mails\nIMAP (Internet\nde um cliente para um servidor e entre servidores,\nIII.  Message Access\ngarantindo que as mensagens sejam entregues\nProtocol)\ncorretamente.</pre>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente a afirmativa II está correta.", "somente a afirmativa III está correta.", "somente as afirmativas II e III estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 1, "explain": "- <strong>Item I (F):</strong> Colocou a definição de <strong>IMAP</strong> (acesso no servidor sincronizado entre dispositivos) no nome <strong>SMTP</strong>! - <strong>Item II (V):</strong> <strong>POP3</strong> baixa e geralmente exclui do servidor. - <strong>Item III (F):</strong> Colocou a definição de <strong>SMTP</strong> (envio de e-mails) no nome <strong>IMAP</strong>!", "area": "web_redes"}, {"num": 29, "stemHtml": "<p>Um navegador web é um software aplicativo que permite aos usuários acessar, visualizar e interagir com conteúdo na internet. Ele interpreta e exibe páginas da web, que são escritas em linguagens como HTML, CSS e JavaScript. Os navegadores fornecem uma interface gráfica que facilita a navegação por meio de links, formulários e outros elementos interativos.</p>\n<p>Exemplos de navegadores web incluem:</p>", "options": ["Google Chrome, Mozilla Firefox, Microsoft Edge, Telegram e Opera", "Google Chrome, Mozilla Firefox, Messenger, Apple Safari e Opera", "Google Chrome, Mozilla Firefox, Microsoft Edge, Apple Safari e Opera", "Google Chrome, Mozilla Firefox, Messenger, Telegram e Opera", "Google Chrome, Mozilla Firefox, Capcut, Youtube e Truecaller"], "answer": 2, "explain": "- <strong>Por que está certa:</strong> Chrome, Firefox, Edge, Safari e Opera são todos navegadores web. - <strong>Intrusos:</strong> <em>Telegram</em>, <em>Messenger</em>, <em>Capcut</em>, <em>Youtube</em> e <em>Truecaller</em>.", "area": "web_redes"}, {"num": 30, "stemHtml": "<p>Suítes de produtividade ou suítes de escritório são conjuntos integrados de aplicativos e ferramentas que facilitam a criação, edição e gerenciamento de documentos, apresentações, planilhas e outros tipos de trabalho colaborativo. Essas plataformas são projetadas para aumentar a eficiência e a produtividade dos usuários em ambientes de trabalho, acadêmicos ou pessoais. Principais características de uma suíte de produtividade incluem:</p>\n<pre class='q-code'>Normalmente  incluem  aplicativos  para\nIntegração  processamento de texto, planilhas, apresentações,\nI.\nde Aplicativos  e-mail, calendários e, em alguns casos,\ngerenciadores de tarefas e notas.</pre>\n<pre class='q-code'>Permitem que vários usuários trabalhem\nColaboração  simultaneamente em um mesmo documento\nII.\nem Tempo Real  ou projeto, facilitando a comunicação e o\ncompartilhamento de ideias.</pre>\n<pre class='q-code'>Muitas suítes oferecem armazenamento em\nAcessibilidade  nuvem, permitindo que os usuários acessem seus\nIII.\nna Nuvem  arquivos de qualquer dispositivo conectado à\ninternet, facilitando o trabalho remoto.</pre>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas I e III estão corretas.", "somente as afirmativas II e III estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "- Suítes de produtividade oferecem integração de aplicativos, colaboração em tempo real e acessibilidade na nuvem.", "area": "web_redes"}]}, "info2025": {"id": "info2025", "title": "Prova Real Irmã FAT — Info Internet (1º SEM/2025)", "badge": "Fundação FAT • 30 Questões", "desc": "Prova aplicada no mesmo dia (15/12/2024) cobrindo a outra metade das matérias do 1º ano (Binário, Linux, DOM, CSS, UML, NoSQL).", "minutes": 240, "questions": [{"num": 1, "stemHtml": "<p>Leia o texto para responder às questões 1 e 2.</p>\n<p>What is critical thinking? Critical thinking generally involves using logic and rationality to decide what to believe or how to act in a given situation. Employees with strong critical thinking skills tend to be reflective, independent, and competent. When practicing critical thinking, individuals can connect ideas logically, evaluate arguments, identify errors, solve complex problems, and reflect on outcomes. Critical thinkers typically use this skill to deduce facts and predict results. This can empower them to become better problem-solvers compared to those who simply memorize details. Employers often value this skill, particularly in roles that require strategic planning. While considered a soft skill, critical thinking can be developed over time. &lt;https://tinyurl.com/3ef223eh&gt; Acesso em: 23.10.2024.</p>\n<p>De acordo com o texto, as habilidades relacionadas a critical thinking caracterizam pessoas</p>", "options": ["reflexivas e críticas para a memorização de detalhes.", "independentes e reflexivas para a solução de problemas.", "intuitivas e sensíveis para a valorização de cuidados suaves.", "competentes e lógicas para a busca de soluções imediatistas.", "racionais e competentes para a resolução de cálculos primários."], "answer": 1, "explain": "- <strong>Por que está certa:</strong> O texto diz <em>\"tend to be reflective, independent, and competent\"</em> e <em>\"become better problem-solvers compared to those who simply memorize details\"</em>. - <strong>Pegadinhas:</strong> (A) inverte para <em>\"memorização de detalhes\"</em> (o texto opõe critical thinking a memorizar); (C) <em>\"cuidados suaves\"</em> traduz literalmente <em>\"soft skill\"</em> ao pé da letra; (D) <em>\"imediatistas\"</em>; (E) <em>\"cálculos primários\"</em>.", "area": "ingles_etica"}, {"num": 2, "stemHtml": "<p>Leia o texto para responder às questões 1 e 2.</p>\n<p>What is critical thinking? Critical thinking generally involves using logic and rationality to decide what to believe or how to act in a given situation. Employees with strong critical thinking skills tend to be reflective, independent, and competent. When practicing critical thinking, individuals can connect ideas logically, evaluate arguments, identify errors, solve complex problems, and reflect on outcomes. Critical thinkers typically use this skill to deduce facts and predict results. This can empower them to become better problem-solvers compared to those who simply memorize details. Employers often value this skill, particularly in roles that require strategic planning. While considered a soft skill, critical thinking can be developed over time. &lt;https://tinyurl.com/3ef223eh&gt; Acesso em: 23.10.2024.</p>\n<p>A palavra outcomes é compreendida no texto como</p>", "options": ["saídas.", "tarefas.", "exclusões.", "passagens.", "resultados."], "answer": 4, "explain": "- <strong>Por que está certa:</strong> <em>\"reflect on outcomes\"</em> = refletir sobre <strong>resultados</strong> (sinônimo de <em>results</em>, citado na frase seguinte). - <strong>Pegadinhas:</strong> (A) <em>\"saídas\"</em> confunde <em>outcomes</em> com <em>outputs/exits</em>.", "area": "ingles_etica"}, {"num": 3, "stemHtml": "<div class=\"q-infographic\">\n  <strong>Infográfico — Critical Thinking Skills:</strong>\n  <ol style=\"margin:6px 0 0 18px; padding:0;\">\n    <li><strong>Observation:</strong> The ability to notice and predict opportunities, problems and solutions.</li>\n    <li><strong>Analysis:</strong> The gathering, understanding and interpreting of data and other information.</li>\n    <li><strong>Inference:</strong> Drawing conclusions based on relevant data, information and personal knowledge and experience.</li>\n    <li><strong>Communication:</strong> Sharing and receiving information with others verbally, nonverbally and in writing.</li>\n    <li><strong>Problem solving:</strong> The process of gathering, analyzing and communicating information to identify and troubleshoot solutions.</li>\n  </ol>\n</div>\n\n<p>Leia o infográfico.</p>\n<p>&lt;https://tinyurl.com/3ef223eh&gt; Acesso em: 23.10.2024.Original colorido.</p>\n<p>De acordo com o infográfico, as habilidades relacionadas a critical thinking permeiam</p>", "options": ["a análise de datas e a antecipação de crises.", "a coleta de dados e o desenho de falsas informações.", "a comunicação de problemas e a busca por intérpretes.", "a antecipação de problemas e o compartilhamento de informações.", "a anotação de oportunidades e a identificação de pessoas inexperientes."], "answer": 3, "explain": "- <strong>Por que está certa:</strong> Item 1 (<em>Observation</em>): <em>\"predict opportunities, problems and solutions\"</em> (antecipação de problemas). Item 4 (<em>Communication</em>): <em>\"Sharing and receiving information\"</em> (compartilhamento de informações). - <strong>Pegadinha clássica:</strong> (A) <em>\"análise de datas\"</em> — falso cognato clássico traduzindo <strong>data</strong> (dados) como \"datas\"! (B) <em>\"falsa informação\"</em>; (C) <em>\"intérpretes\"</em> (confundindo com <em>interpreting</em>); (E) <em>\"anotação\" / \"inexperientes\"</em>.", "area": "ingles_etica"}, {"num": 4, "stemHtml": "<p>A representação binária de informações é uma forma de codificar dados, usando apenas dois símbolos: 0 e 1. Esse sistema é a base do funcionamento dos computadores e dispositivos digitais, que processam e armazenam dados por meio de circuitos eletrônicos que podem estar em um dos dois estados (ligado ou desligado). Cada dígito no sistema binário é chamado de “bit” (binary digit), e conjuntos de bits (como 8 bits formando um byte) podem representar diferentes tipos de informações, como números, letras, imagens e sons. O maior número que pode ser representado por 1 byte (8 bits) no sistema binário é 255. Isso ocorre porque, com 8 bits, temos 256 combinações possíveis (de 0 a 255).</p>\n<p>O número 255 (decimal) é representado em binário pela sequência.</p>", "options": ["10000000", "11111111", "10101010", "01010101", "10000001"], "answer": 1, "explain": "<code>255</code> em binário (8 bits ligados) = <code>11111111</code> ($128+64+32+16+8+4+2+1 = 255$).", "area": "web_redes"}, {"num": 5, "stemHtml": "<p>Virtualização é uma tecnologia que permite criar versões virtuais de recursos físicos, como servidores, sistemas operacionais, armazenamento e redes, usando software. Em vez de depender exclusivamente do hardware físico, a virtualização permite que um único dispositivo execute múltiplas “máquinas virtuais” (VMs), cada uma funcionando como se fosse um computador independente, com seu próprio sistema operacional e aplicativos. Os principais tipos de virtualização são:</p>\n<pre class='q-code'>Divide um servidor físico em várias máquinas virtuais,\nVirtualização  cada uma executando seu próprio sistema operacional e\nI.\nde Servidor  aplicativos, o que maximiza a eficiência dos recursos e\nreduz custos.\nPermite que vários sistemas operacionais sejam\nVirtualização\nexecutados no mesmo hardware, facilitando testes de\nII.  de Sistema\nsoftware, desenvolvimento e o uso de diferentes ambientes\nOperacional:\nde SO em uma única máquina.</pre>\n<pre class='q-code'>Abstrai recursos de rede, permitindo a criação de redes\nVirtualização\nIII.  virtuais independentes da infraestrutura física, melhorando\nde Rede\na flexibilidade e a segurança na administração de redes.</pre>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente a afirmativa II está correta.", "somente a afirmativa III está correta.", "somente as afirmativas I e III estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "Virtualização de Servidor (I), SO (II) e Rede (III) — todas corretas.", "area": "web_redes"}, {"num": 6, "stemHtml": "<p>O Microsoft Word (Office 365) é um software de processamento de texto desenvolvido pela Microsoft, usado para criar, editar e formatar documentos de forma profissional, oferecendo ferramentas para escrever, revisar e compartilhar conteúdos escritos. No Microsoft Word, encontramos ferramentas de formatação usadas para organizar e destacar itens em listas, onde são aplicados símbolos (como pontos ou ícones) para listas não ordenadas e números ou letras para listas ordenadas, facilitando a leitura e o entendimento de informações. Esse recurso do editor de texto é definido como:</p>", "options": ["sumários e comentários.", "marcadores e numeração.", "citações e bibliografia.", "sumários e citações.", "marcadores e comentários."], "answer": 1, "explain": "Listas com símbolos ou números no Word = <strong>marcadores e numeração</strong>.", "area": "web_redes"}, {"num": 7, "stemHtml": "<p>Webmail é um serviço de e-mail acessado por meio de um navegador da web, permitindo que os usuários enviem, recebam e gerenciem suas mensagens de e-mail online, sem a necessidade de um cliente de e-mail instalado no dispositivo (smartphone, computadores ou notebooks), com armazenamento geralmente baseado na nuvem. São exemplos de webmail.</p>", "options": ["Canva, iCloud Mail, Gmail.", "Splice, Outlook.com e iCloud Mail.", "Gmail, Canva e Splice.", "Outlook.com, iCloud Mail e Norton Safe Web", "Gmail, Outlook.com e iCloud Mail."], "answer": 4, "explain": "<em>Canva</em> (design), <em>Splice</em> (edição de vídeo), <em>Norton Safe Web</em> (segurança).", "area": "web_redes"}, {"num": 8, "stemHtml": "<p>Multimídia é a combinação de diferentes tipos de conteúdo, como texto, áudio, vídeo, imagens e animações, em uma única apresentação ou aplicação, permitindo uma experiência mais rica e interativa para o usuário. Esse conceito é utilizado em áreas como educação, entretenimento, marketing e design, pois facilita a comunicação e a transmissão de informações de maneira mais envolvente e eficaz. São exemplos de softwares para elaboração de multimídia</p>\n<pre class='q-code'>I.  Adobe Creative Cloud</pre>\n<pre class='q-code'>II.  Office 365</pre>\n<pre class='q-code'>III.  Camtasia</pre>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente a afirmativa II está correta.", "somente as afirmativas I e III estão corretas.", "somente as afirmativas II e III estão corretas.", "somente as afirmativas I e II estão corretas."], "answer": 2, "explain": "Gabarito oficial: (C).", "area": "web_redes"}, {"num": 9, "stemHtml": "<p>A Teoria das Cores é um conjunto de princípios que explora como as cores interagem, como podem ser combinadas e os efeitos que elas produzem nas percepções e emoções humanas. Ela é fundamental em várias disciplinas, como arte, design, fotografia e marketing. O conceito de organizar as cores em um formato circular, mostrando as relações entre cores primárias, secundárias e terciárias é conhecido como:</p>", "options": ["Círculo Cromático.", "Cores Primárias.", "Cores Complementares.", "Harmonia de Cores.", "Psicologia das Cores."], "answer": 0, "explain": "Organização circular de cores primárias, secundárias e terciárias = <strong>Círculo Cromático</strong>.", "area": "design"}, {"num": 10, "stemHtml": "<p>Tratamento de imagem é o processo de manipulação e modificação de fotografias ou imagens digitais para melhorar sua qualidade, alterar sua aparência ou adaptá-las a determinados requisitos estéticos ou técnicos. Isso pode incluir ajustes em cor, brilho, contraste, nitidez, remoção de imperfeições, aplicação de efeitos especiais e composição de várias imagens. O tratamento de imagem é utilizado em fotografia, design gráfico, publicidade e artes visuais para criar imagens mais atraentes e impactantes. O processo de converter gráficos vetoriais, que são baseados em fórmulas matemáticas, permitindo que a imagem seja visualizada e exibida em dispositivos digitais é conhecido como:</p>", "options": ["Vetorização.", "Digitalização.", "Composição.", "Rasterização.", "Animação."], "answer": 3, "explain": "Converter gráficos vetoriais (fórmulas matemáticas) para pixels exibíveis em telas = <strong>Rasterização</strong> (o inverso de <em>Vetorização</em>).", "area": "design"}, {"num": 11, "stemHtml": "<p>Conjunto de estratégias e práticas que utilizam canais e plataformas digitais, como redes sociais, e-mail, motores de busca e websites, para promover produtos ou serviços, engajar o público-alvo e construir relacionamentos com os consumidores. Essa abordagem permite que as empresas alcancem um público mais amplo, analisem dados em tempo real, segmentem audiências específicas e ajustem suas campanhas para melhorar a eficácia e o retorno sobre investimento (ROI). É conhecido como:</p>", "options": ["Branding.", "Marketing Digital.", "Identidade visual.", "Ilustração digital vetorial.", "Tipografia."], "answer": 1, "explain": "Estratégias digitais com análise de ROI = <strong>Marketing Digital</strong>.", "area": "design"}, {"num": 12, "stemHtml": "<p>Servidores de hospedagem web são computadores ou sistemas que armazenam e disponibilizam sites e aplicativos online, fornecendo os recursos necessários para que esses conteúdos sejam acessíveis pela Internet. Esses servidores gerenciam o armazenamento de arquivos, o processamento de dados e a conectividade à rede, permitindo que os usuários acessem sites por meio de navegadores. A hospedagem pode ser compartilhada, dedicada, em nuvem ou virtual, dependendo das necessidades de desempenho e capacidade do site. Existem vários tipos de hospedagem web, cada um atendendo a diferentes necessidades e orçamentos.</p>\n<pre class='q-code'>Vários sites são hospedados em um único servidor, compartilhando\nHospedagem\nI.  recursos como CPU e memória, o que a torna uma opção\nCompartilhada:\neconômica, mas com limitações de desempenho.</pre>\n<pre class='q-code'>Um servidor inteiro é reservado para um único site, oferecendo\nHospedagem\nII.  controle total sobre o ambiente e recursos, ideal para sites com\nDedicada\nalto tráfego ou requisitos específicos.</pre>\n<pre class='q-code'>Um único servidor é dividido em várias partes virtuais, em que\nHospedagem\ncada site tem seus próprios recursos dedicados, oferecendo mais\nIII.  VPS (Servidor\ncontrole e desempenho do que a hospedagem compartilhada,\nPrivado Virtual):\nmas a um custo menor do que a hospedagem dedicada.</pre>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas I e III estão corretas.", "somente as afirmativas II e III estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "Hospedagem Compartilhada (I), Dedicada (II) e VPS (III) — todas corretas.", "area": "web_redes"}, {"num": 13, "stemHtml": "<p>Um documento HTML (HyperText Markup Language) é um arquivo que contém código escrito em HTML, que é a linguagem padrão utilizada para criar e estruturar páginas da web. Esse tipo de documento define a estrutura do conteúdo, como texto, imagens, links e outros elementos, utilizando tags para especificar diferentes partes do conteúdo (como cabeçalhos, parágrafos, listas e tabelas). Os documentos HTML são interpretados pelos navegadores web para exibir as páginas de forma visual e interativa para os usuários. Os elementos fundamentais do HTML que definem a estrutura e o tipo de conteúdo em uma página web e as propriedades adicionais que podem ser adicionadas às tags HTML para fornecer informações extras ou modificar o comportamento de um elemento, são conhecidas, respectivamente, como:</p>", "options": ["Tags e Conteúdo.", "Atributos e Semântica.", "Tags e Atributos.", "Semântica e Tags.", "Semântica e Conteúdo."], "answer": 2, "explain": "Elementos estruturais do HTML = <strong>Tags</strong>; propriedades extras dentro das tags = <strong>Atributos</strong>.", "area": "web_redes"}, {"num": 14, "stemHtml": "<p>CSS (Cascading Style Sheets) é uma linguagem de estilo utilizada para descrever a apresentação e o layout de documentos HTML e XML. Com o CSS, é possível controlar a aparência visual de elementos web, incluindo cores, fontes, espaçamentos, margens, bordas e posicionamento, permitindo que os desenvolvedores e designers separarem o conteúdo da formatação. Essa separação facilita a manutenção e a atualização dos estilos, além de proporcionar uma maior flexibilidade e controle sobre o design responsivo e a estética geral de um site. Uma regra no CSS é a declaração que define como um ou mais elementos HTML devem ser estilizados em uma página web. Cada regra CSS consiste em duas partes principais, são elas:</p>", "options": ["Estilização de Texto e Seletor.", "Layout e Posicionamento e Bloco de Declarações.", "Estilização de Texto e Bloco de Declarações.", "Bloco de Declarações e Estilos Responsivos.", "Seletor e Bloco de Declarações."], "answer": 4, "explain": "red; }`).", "area": "web_redes"}, {"num": 15, "stemHtml": "<p>Tipografia é a arte e a técnica de organizar e apresentar texto de maneira visualmente atraente e legível, utilizando elementos como tipo de letra (fonte), tamanho, espaçamento, alinhamento e estilo (negrito, itálico, etc.). Ela envolve a escolha cuidadosa de fontes e a disposição do texto em um layout, com o objetivo de comunicar uma mensagem de forma eficaz, aprimorar a estética de um design e facilitar a leitura. A tipografia é uma parte essencial do design gráfico, web design e comunicação visual. O uso de fontes personalizadas permite uma identidade visual mais exclusiva, mas é importante garantir que sejam carregadas corretamente e que a legibilidade não seja comprometida. São exemplos de fontes personalizadas:</p>", "options": ["Times New Roman, Georgia e Garamond.", "Google Fonts e Adobe Fonts.", "Google Fonts, Times New Roman, Arial.", "Arial, Helvetica e Open Sans.", "Adobe Fonts, Times New Roman, Georgia, Helvetica e Open Sans."], "answer": 1, "explain": "Repositórios/serviços de fontes personalizadas para web = <strong>Google Fonts e Adobe Fonts</strong> (as outras opções misturam fontes de sistema como <em>Times New Roman</em> e <em>Arial</em>).", "area": "design"}, {"num": 16, "stemHtml": "<p>Em sistemas de computação, contêineres são uma tecnologia de virtualização leve que permite empacotar uma aplicação e suas dependências em um ambiente isolado, chamado de “contêiner”. Isso garante que a aplicação funcione de maneira consistente em diferentes ambientes de desenvolvimento, teste e produção. Cada contêiner opera de forma individual, permitindo que múltiplas aplicações sejam executadas em um mesmo sistema, sem interferir umas nas outras. Isso é diferente de máquinas virtuais, que virtualizam o hardware completo.</p>\n<p>Essa característica é conhecida como:</p>", "options": ["Leveza.", "Isolamento.", "Portabilidade.", "Eficiência de Recursos.", "Gerenciamento Simplificado."], "answer": 1, "explain": "Operar contêineres individualmente sem interferir uns nos outros = <strong>Isolamento</strong>.", "area": "web_redes"}, {"num": 17, "stemHtml": "<p>Acesso remoto em sistemas computacionais refere-se à capacidade de um usuário ou administrador de se conectar e interagir com um computador, servidor ou rede a partir de um local diferente, utilizando uma conexão de internet ou rede. Essa prática é amplamente utilizada em ambientes de trabalho, suporte técnico, e administração de sistemas, permitindo que as pessoas acessem recursos e dados sem estarem fisicamente presentes no local. Tecnologia desenvolvida pela Microsoft que permite que usuários se conectem a um computador remoto por meio de uma rede, utilizando uma interface gráfica de usuário, é conhecida pela sigla:</p>", "options": ["FTP.", "UTP.", "RDP.", "SSH.", "SSL."], "answer": 2, "explain": "FTP transfere arquivos, SSH é terminal texto criptografado, SSL é segurança TLS, UTP é cabo de par trançado).", "area": "web_redes"}, {"num": 18, "stemHtml": "<p>A estrutura de diretório no Linux refere-se à organização hierárquica dos arquivos e diretórios no sistema operacional Linux. Essa estrutura é fundamental para o gerenciamento de arquivos e pastas, permitindo que usuários e programas encontrem, acessem e organizem dados de forma eficiente. Alguns dos diretórios padrão mais comuns na estrutura de diretórios do Linux incluem:</p>", "options": ["/bin, /cd, /home, /lib, /pwd, /var e /tmp", "/bin, /mkdir, /home, /lib, /rm, /var e /cd", "/bin, /etc, /home, /ls, /cd, /rm e /tmp", "/bin, /etc, /home, /lib, /usr, /var e /tmp", "/bin, /ls, /home, /rm, /usr, /var e /mkdir"], "answer": 3, "explain": "Diretórios padrão do Linux = <strong><code>/bin, /etc, /home, /lib, /usr, /var e /tmp</code></strong>. As erradas colocaram comandos como se fossem pastas (<code>/cd</code>, <code>/pwd</code>, <code>/mkdir</code>, <code>/rm</code>, <code>/ls</code>)!", "area": "web_redes"}, {"num": 19, "stemHtml": "<p>Tipos de dados referem-se a categorias de dados que determinam quais valores podem ser armazenados em uma variável e quais operações podem ser realizadas sobre esses valores. Em programação e computação, a definição e utilização de tipos de dados são essenciais para garantir a integridade dos dados e a eficiência da execução de programas. Os principais tipos de dados são:</p>\n<pre class='q-code'>I.  Inteiros (int):  Números inteiros, positivos ou negativos, sem casas decimais.</pre>\n<pre class='q-code'>Ponto Flutuante\nII.  Números que contêm casas decimais.\n(float):</pre>\n<pre class='q-code'>Representa valores lógicos, que podem ser true (verdadeiro)\nIII.  Caractere (char):\nou false (falso).</pre>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente a afirmativa II está correta.", "somente a afirmativa III está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas I e III estão corretas."], "answer": 3, "explain": "Gabarito oficial: (D).", "area": "prog"}, {"num": 20, "stemHtml": "<p>Uma tabela verdade é uma ferramenta usada na lógica e na matemática para representar todas as combinações possíveis de valores (verdadeiro ou falso) para uma proposição ou conjunto de proposições. Ela é útil em lógica proposicional e na análise de circuitos lógicos, permitindo visualizar como as diferentes entradas influenciam as saídas de uma expressão lógica. São operações comuns da tabela verdade AND (∧), OR (∨) e NOT (¬). Considerando duas proposições P e Q, e a expressão lógica P∧Q, temos:</p>\n<pre class='q-code'>I.  Se P e Q são verdadeiros, então P∧Q é falso.</pre>\n<pre class='q-code'>II.  Se P é verdadeiro e Q é falso, então P∧Q é falso.</pre>\n<pre class='q-code'>III.  Se P é falso e Q é verdadeiro, então P∧Q é falso.</pre>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente a afirmativa II está correta.", "somente a afirmativa III está correta.", "somente as afirmativas II e III estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 3, "explain": "Gabarito oficial: (D).", "area": "prog"}, {"num": 21, "stemHtml": "<p>Recursividade em programação é um conceito em que uma função se chama novamente dentro de sua própria definição para resolver um problema. Em outras palavras, uma função recursiva é aquela que resolve um problema dividindo-o em subproblemas menores e chamando a si mesma para resolver esses subproblemas. O fatorial de um número n (denotado como n!) é um exemplo clássico de uma função recursiva. O fatorial é definido como:</p>\n<p>n! = n x (n−1)! para n&gt;0</p>\n<p>Qual o fatorial de número decimal 4?</p>", "options": ["2", "6", "24", "120", "720"], "answer": 2, "explain": "Fatorial recursivo <code>4! = 4 × 3 × 2 × 1 = 24</code>.", "area": "prog"}, {"num": 22, "stemHtml": "<p>Requisitos de sistemas são as condições ou capacidades que um sistema deve atender ou possuir para satisfazer as necessidades dos usuários e das partes interessadas. Eles são fundamentais para o desenvolvimento de software, pois orientam o design, a implementação e a validação do sistema. Requisitos Funcionais especificam o que o sistema deve fazer. Eles descrevem as funções, comportamentos e interações do sistema, como a capacidade de um software realizar cálculos, gerar relatórios ou integrar-se com outros sistemas. Por outro lado, requisitos Não Funcionais definem critérios que julgam a operação do sistema, em vez de comportamentos específicos. Esses requisitos podem incluir aspectos como desempenho, segurança, usabilidade e escalabilidade. São características de bons requisitos:</p>", "options": ["Clareza, Testabilidade, Consistência, Ambiguidade e Viabilidade.", "Clareza, Testabilidade, Consistência, Rastreabilidade e Viabilidade.", "Clareza, Inconsistência, Consistência, Rastreabilidade e Viabilidade.", "Irrelevância, Testabilidade, Consistência, Rastreabilidade e Viabilidade.", "Clareza, Ambiguidade, Inconsistência, Irrelevância e Viabilidade."], "answer": 1, "explain": "<em>Ambiguidade</em>, <em>Inconsistência</em>, <em>Irrelevância</em>.", "area": "prog"}, {"num": 23, "stemHtml": "<p>O estudo de viabilidade é uma análise que avalia a viabilidade de um projeto ou proposta, determinando se ele pode ser realizado com sucesso, considerando diversos fatores. Esse estudo é fundamental em qualquer fase de planejamento, pois ajuda a identificar riscos, benefícios e a viabilidade econômica de uma ideia ou investimento. Os principais aspectos avaliados no estudo de viabilidade incluem:</p>\n<pre class='q-code'>Viabilidade  Avalia se a organização tem a capacidade operacional para implementar e manter\nI.\nLegal  o projeto. Isso inclui recursos humanos, infraestrutura e processos operacionais.</pre>\n<pre class='q-code'>Avalia se a tecnologia necessária para implementar o projeto está disponível e\nViabilidade\nII.  se a equipe possui as habilidades e conhecimentos necessários. Por exemplo,\nTécnica\nse um software pode ser desenvolvido com as ferramentas e tecnologias atuais.</pre>\n<pre class='q-code'>Examina os custos envolvidos e os benefícios financeiros esperados do projeto.\nViabilidade\nIII.  Isso inclui a análise do retorno sobre o investimento (ROI), custos operacionais\nEconômica\ne a comparação entre diferentes alternativas de financiamento.</pre>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente a afirmativa II está correta.", "somente a afirmativa III está correta.", "somente as afirmativas II e III estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 3, "explain": "Gabarito oficial: (D).", "area": "prog"}, {"num": 24, "stemHtml": "<p>UML (Unified Modeling Language) é uma linguagem padrão de modelagem utilizada na engenharia de software para especificar, visualizar, construir e documentar artefatos de sistemas. A UML fornece um conjunto de notações gráficas e diagramas que ajudam na representação de diferentes aspectos de um sistema, permitindo que desenvolvedores, analistas e outras partes interessadas compreendam a estrutura e o comportamento do software de forma mais clara. A UML inclui vários tipos de diagramas. No contexto comportamental, o diagrama que mostra as interações entre usuários (atores) e o sistema, identificando os requisitos funcionais é conhecido como:</p>", "options": ["Diagrama de Classes.", "Diagrama de Estado.", "Diagrama de Atividades.", "Diagrama de Sequência.", "Diagrama de Casos de Uso."], "answer": 4, "explain": "Diagrama UML comportamental que mostra interações entre <strong>atores</strong> e o sistema = <strong>Diagrama de Casos de Uso</strong>.", "area": "prog"}, {"num": 25, "stemHtml": "<p>O modelo TCP/IP (Transmission Control Protocol/Internet Protocol) é um conjunto de protocolos de comunicação que forma a base da comunicação na internet. Ele foi desenvolvido, inicialmente, para interconectar diferentes redes de computadores e permitir a troca de dados entre elas. O modelo TCP/IP é essencial para o funcionamento da internet e é a estrutura subjacente que possibilita a comunicação entre dispositivos em rede. O modelo TCP/IP é frequentemente descrito em quatro camadas, cada uma com suas funções e protocolos associados. As camadas do TCP/IP são representadas por:</p>", "options": ["Link, Sessão, Transporte e Aplicação.", "Link, Internet, Transporte e Aplicação.", "Link, Internet, Enlace de Dados e Aplicação.", "Link, Internet, Transporte e Física.", "Link, Sessão, Enlace de Dados e Física."], "answer": 1, "explain": "<em>Sessão</em> e <em>Física</em> pertencem ao modelo OSI de 7 camadas).", "area": "web_redes"}, {"num": 26, "stemHtml": "<p>Protocolos web são conjuntos de regras e convenções que definem como os dados são transmitidos e trocados na internet, especialmente, no contexto da comunicação entre clientes (como navegadores) e servidores web. Esses protocolos garantem que as informações sejam enviadas e recebidas de maneira eficaz, segura e compreensível. O protocolo usado para enviar e-mails pela internet que é responsável pelo envio de mensagens de correio eletrônico de um servidor para outro é conhecido como:</p>", "options": ["SMTP (Simple Mail Transfer Protocol).", "FTP (File Transfer Protocol).", "POP3 (Post Office Protocol 3).", "IMAP (Internet Message Access Protocol).", "HTTP (Hypertext Transfer Protocol)."], "answer": 0, "explain": "Protocolo de envio de e-mail = <strong>SMTP</strong>.", "area": "web_redes"}, {"num": 27, "stemHtml": "<p>SSL (Secure Sockets Layer) é um protocolo de segurança que estabelece uma conexão criptografada entre um servidor web e um cliente (geralmente um navegador), garantindo que os dados trocados entre eles permaneçam privados e íntegros. Embora o SSL tenha sido amplamente utilizado, ele foi substituído pelo TLS (Transport Layer Security), que é uma versão mais segura e moderna. No entanto, o termo SSL ainda é utilizado para se referir a ambas as tecnologias. As principais funcionalidades do SSL são:</p>\n<pre class='q-code'>I.  Criptografia</pre>\n<pre class='q-code'>II.  Autenticação</pre>\n<pre class='q-code'>III.  Integridade dos Dados</pre>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas I e III estão corretas.", "somente as afirmativas II e III estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "Criptografia, Autenticação e Integridade dos Dados.", "area": "web_redes"}, {"num": 28, "stemHtml": "<p>Linguagem de Consulta de Dados (DQL) é uma subcategoria da SQL (Structured Query Language) que se concentra na recuperação e consulta de informações de um banco de dados. O principal comando da DQL é o SELECT, que permite aos usuários especificar quais dados desejam obter, bem como as condições e critérios para essa recuperação. Os usuários podem aplicar condições para restringir os resultados por meio da cláusula WHERE, permitindo a obtenção de subconjuntos de dados que atendam a critérios específicos, essa afirmação representa a característica de:</p>", "options": ["Filtragem e Condições.", "Recuperação de Dados.", "Ordenação.", "Agregação.", "Combinação de Dados."], "answer": 0, "explain": "Cláusula <code>WHERE</code> restringindo resultados = <strong>Filtragem e Condições</strong>.", "area": "bd"}, {"num": 29, "stemHtml": "<p>SGBD (Sistema de Gerenciamento de Banco de Dados) é um conjunto de software que permite a criação, manipulação e administração de bancos de dados. Ele fornece uma interface para os usuários e aplicativos interagirem com os dados armazenados, além de assegurar a integridade, segurança e eficiência no acesso às informações. SGBDs Não Relacionais (NoSQL) são projetados para trabalhar com dados não estruturados ou semi-estruturados, frequentemente utilizados em aplicações com grandes volumes de dados. São exemplos de Bancos Não relacionais (NoSQL):</p>", "options": ["MongoDB, MySQL e PostgreSQL.", "Cassandra, MySQL e PostgreSQL.", "MySQL, PostgreSQL Oracle.", "MongoDB e Cassandra.", "Oracle, MongoDB e Cassandra."], "answer": 3, "explain": "<em>MySQL, PostgreSQL, Oracle</em>.", "area": "bd"}, {"num": 30, "stemHtml": "<p>SQL (Structured Query Language) é uma linguagem de programação padrão utilizada para gerenciar e manipular bancos de dados relacionais. Com SQL, os usuários podem realizar diversas operações, como criar e modificar estruturas de banco de dados, inserir, atualizar e excluir dados, bem como consultar informações armazenadas por meio de instruções específicas. As principais funcionalidades do SQL são:</p>\n<pre class='q-code'>Consulta de Dados: Permite a recuperação de informações específicas de uma\nI.\nou mais tabelas, usando a instrução SELECT.</pre>\n<pre class='q-code'>Manipulação de Dados: Facilita a inserção (INSERT), atualização (UPDATE) e\nII.\nexclusão (DELETE) de registros em tabelas.</pre>\n<pre class='q-code'>Definição de Dados: Utiliza comandos como CREATE, ALTER e DROP para\nIII.\ndefinir e modificar a estrutura de tabelas e outros objetos no banco de dados.</pre>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente a afirmativa II está correta.", "somente a afirmativa III está correta.", "somente as afirmativas II e III estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "<strong>Mesmo quadro</strong> de DQL (<code>SELECT</code>), DML (<code>INSERT/UPDATE/DELETE</code>) e DDL (<code>CREATE/ALTER/DROP</code>) da Q11 de DS, só que desta vez <strong>todas estão certas</strong>!", "area": "bd"}]}, "ds2019": {"id": "ds2019", "title": "Prova Real Histórica FAT — DS (1º SEM/2019)", "badge": "Fundação FAT • 30 Questões", "desc": "Prova clássica com Tabela Verdade, Portugol DIV/MOD, Pilha LIFO, Cascata, Scrum, POO, Git, CSS3 transform e Bootstrap.", "minutes": 240, "questions": [{"num": 1, "stemHtml": "<p>Tabela verdade é um tipo de tabela matemática, aplicada em lógica de programação, que auxilia os matemáticos e os programadores no julgamento de proposições, permitindo encontrar possíveis erros na validação dos argumentos. Na tabela verdade, encontramos os operadores:</p>\n<p>•  “e” (conjunção – ^), o resultado será verdadeiro, quando as duas proposições forem verdadeiras. •  “ou” (disjunção – v), o resultado será verdadeiro, quando, pelo menos, uma das proposições for verdadeira. •  “negação”, inverterá a proposição; se for falsa, ela passará a ser verdadeira.</p>\n<p>A tabela verdade apresenta os valores de entradas para “p” e “q”.</p>\n<p>p  q  C (p ^ q)  D (p v q)</p>\n<p>1.  V  V</p>\n<p>2.  V  F</p>\n<p>3.  F  V</p>\n<p>4.  F  F</p>\n<p>Identifique os valores lógicos que completam as colunas identificadas como “C” conjunção (p ^ q) e “D” disjunção (p v q), respectivamente.</p>\n<p>C (p ^ q)  D (p v q)</p>\n<p>1.  2.  3.  4.  1.  2.  3.  4.</p>", "options": ["V F F F e V V V F", "F V V V e V F F V", "F V V F e V F F F", "V F F V e F V V V", "V F F F e F V V V"], "answer": 0, "explain": "<code>p ∧ q</code> = <code>V, F, F, F</code>; <code>p ∨ q</code> = <code>V, V, V, F</code>.", "area": "prog"}, {"num": 2, "stemHtml": "<pre class='q-code'>O Algoritmo é uma sequência de instruções bem definidas e finitas, e, portanto,\ndeve ser visto como uma dedução lógica controlada. O Portugol (português estruturado) é\numa pseudolinguagem que permite desenvolver algoritmos estruturados em português,\nde forma simples e intuitiva, independentemente de linguagem de programação,\npodendo apresentar expressões especiais como DIV, que representa o valor inteiro obtido\nda divisão e MOD, que representa o resto inteiro obtido da divisão. O algoritmo “calcular”\nrealiza uma sequência de instruções a partir da entrada do usuário, observe:</pre>\n<pre class='q-code'>algoritmo “calcular”\nvar\nx : caracter\ny : inteiro\ninicio\nescreva(“Entre com um número inteiro :”)\nleia(y)\nenquanto y &gt; 0 faça\nse (y mod 2) = 0 então\nx &lt;- “0” + x\nsenão\nx &lt;- “1” + x\nfim-se\ny &lt;- y div 2\nfim-enquanto\nescreva(x)\nfim-algoritmo</pre>\n<pre class='q-code'>Realizando o teste de mesa para o algoritmo “calcular”, qual o valor expresso na variável “x”, quando são\naplicadas as entradas 10 e 250 pelo usuário?</pre>", "options": ["1111 e 10101111", "1010 e 10101111", "1010 e 11111111", "1111 e 11111010", "1010 e 11111010"], "answer": 4, "explain": "Algoritmo em Portugol que converte decimal para binário usando <code>DIV 2</code> e <code>MOD 2</code> (concatenando resto à esquerda). <code>10</code> = <code>1010</code>; <code>250</code> = <code>11111010</code>.", "area": "prog"}, {"num": 3, "stemHtml": "<p>Na Ciência da Computação, uma estrutura de dados é um modo de armazenamento e organização de dados em um computador, permitindo o uso de maneira eficiente. Um exemplo de estrutura de dados é a estrutura de PILHA, que representa um tipo especial de lista linear em que todas as operações de inserção e remoção são realizadas pela mesma extremidade chamada topo, ou seja, sua estrutura é baseada no princípio LIFO (last in, first out), por meio do qual os dados que foram inseridos por último na pilha serão os primeiros a serem removidos. Existem duas funções que se aplicam a todas as pilhas: PUSH, que insere um dado no topo da pilha, e POP, que remove o item no topo da pilha. Na tabela, são representados os valores inteiros manipulados em uma PILHA (P), por meio das ações PUSH e POP.</p>\n<p>Ação  Instrução  Ação  Instrução  Ação  Instrução</p>\n<p>01  PUSP(P,10)  06  POP(P)  11  POP(P)</p>\n<p>02  PUSP(P,5)  07  PUSP(P,10)  12  POP(P)</p>\n<p>03  POP(P)  08  POP(P)  13  POP(P)</p>\n<p>04  PUSP(P,7)  09  PUSP(P,2)  14  PUSP(P,3)</p>\n<p>05  PUSP(P,3)  10  PUSP(P,7)  15  POP(P)</p>\n<p>Ao término de todas as operações (01 até 15), qual alternativa representa o valor residual na Pilha(P)?</p>", "options": ["3", "7", "10", "5", "2"], "answer": 2, "explain": "- <code>01: [10]</code> -&gt; <code>02: [10, 5]</code> -&gt; <code>03 POP: [10]</code> -&gt; <code>04: [10, 7]</code> -&gt; <code>05: [10, 7, 3]</code> -&gt; <code>06 POP: [10, 7]</code> -&gt; <code>07: [10, 7, 10]</code> -&gt; <code>08 POP: [10, 7]</code> -&gt; <code>09: [10, 7, 2]</code> -&gt; <code>10: [10, 7, 2, 7]</code> -&gt; <code>11 POP: [10, 7, 2]</code> -&gt; <code>12 POP: [10, 7]</code> -&gt; <code>13 POP: [10]</code> -&gt; <code>14: [10, 3]</code> -&gt; <code>15 POP: [10]</code>. Valor residual = <strong>10</strong>.", "area": "prog"}, {"num": 4, "stemHtml": "<p>O processo a partir do qual se aplicam regras a todas as tabelas do banco de dados com o objetivo de evitar falhas no projeto, como redundância de dados e mistura de diferentes assuntos em uma mesma tabela é conhecido como normalização. Assim, a forma normal que garante que todos os atributos de uma tabela devem ser atômicos, ou seja, a tabela não deve conter grupos repetidos e nem atributos com mais de um valor é representada pela:</p>", "options": ["3ª Forma Normal", "Forma Normal De Boyce-Codd", "2ª Forma Normal", "Forma Normal Chave-Domínio", "1ª Forma Normal"], "answer": 4, "explain": "Atributos atômicos, sem grupos repetidos = <strong>1ª Forma Normal</strong>. (Repare que caiu quase igual na Q13 de 2025!).", "area": "bd"}, {"num": 5, "stemHtml": "<p>A cardinalidade na modelagem de dados relacional, é um dos princípios fundamentais sobre relacionamento. Nela, é definido o nível de relação entre duas entidades ou tabelas. O relacionamento recursivo ou auto-relacionamento são casos especiais em que uma entidade se relaciona com si mesma e a sua utilização é muito importante, em alguns casos, dependendo do cenário de negócio. De acordo com a cardinalidade, o relacionamento recursivo pode apresentar-se na forma de:</p>\n<pre class='q-code'>I.  1:N (um-para-muitos)\nII.  N:1 (muitos-para-um)\nÉ correto afirmar que:  III.  N:N (muitos-para-muitos)</pre>", "options": ["as alternativas I, II e III estão corretas.", "somente a alternativa I está correta.", "somente a alternativa II está correta.", "somente a alternativa III está correta.", "somente as alternativas II e III estão corretas."], "answer": 0, "explain": "N` (todas corretas).", "area": "bd"}, {"num": 6, "stemHtml": "<p>É comum encontrarmos conjuntos de elementos com os valores dispostos em certa ordem, obedecendo a uma sequência como, por exemplo:</p>\n<p>O conjunto ordenado (1,3,5,7,9,11...) é a sequência de números ímpares. O conjunto ordenado (6,8,10) é a sequência de números pares &gt;=5 e &lt;=10.</p>\n<p>Para uma sequência numérica, precisamos de uma lei de formação, como, por exemplo, o conjunto (2,2,4,6,10,16,26,etc), em que os dois últimos valores são somados para gerar o próximo: 2+2=4, 2+4=6, 4+6=10. Os valores representados na tabela foram organizados por meio de uma lei de formação.</p>\n<p>2  a  4  12  10  30  28 3  9  b  21  19  57  55 4  12  10  30  c  84  82 5  15  13  39  37  d  109</p>\n<p>Qual é o valor resultante da soma dos quatro valores representados pelas letras a, b, c e d na tabela ?</p>", "options": ["150", "152", "154", "156", "158"], "answer": 1, "explain": "<code>a = 2×3 = 6</code>; <code>b = 9-2 = 7</code>; <code>c = 30-2 = 28</code>; <code>d = 37×3 = 111</code>. Soma = <code>6 + 7 + 28 + 111 = 152</code>.", "area": "prog"}, {"num": 7, "stemHtml": "<p>SQL é sigla inglesa de “Structured Query Language”. Trata-se de uma linguagem padrão de gerenciamento de dados que interage com os principais bancos de dados baseados no modelo relacional, e tem comandos representados em agrupamentos distintos conhecidos como: Data Definition Language (DDL), Data Manipulation Language (DML), Data Control Language (DCL) e Transaction Control Language (TCL).</p>\n<p>São exemplos respectivos para os grupos DDL, DML, DCL e TCL os comandos:</p>\n<p>DDL  DML  DCL  TCL</p>", "options": ["CREATE DROP GRANT COMMIT", "CREATE SELECT DELETE COMMIT", "CREATE SELECT GRANT LOCK TABLE", "CREATE SELECT GRANT COMMIT", "CREATE SELECT ROLLBACK REVOKE"], "answer": 3, "explain": "em 2019 a banca ainda agrupava DQL dentro de DML; a partir de 2025 passou a cobrar DQL separado para <code>SELECT</code> e DML para <code>INSERT/UPDATE/DELETE</code>)*, DCL=<code>GRANT</code>, TCL=<code>COMMIT</code>.", "area": "bd"}, {"num": 8, "stemHtml": "<p>Em 1970, W. W. Royce propôs o que é agora popularmente designado como modelo em cascata (Waterfall Model), um modelo de desenvolvimento de software sequencial no qual o processo é visto como um fluir constante (como uma cascata). Esse modelo foi derivado de modelos de atividade de engenharia com o fim de estabelecer ordem no desenvolvimento de grandes produtos de software. O modelo cascata, em perfeita ordem, possui as etapas de:</p>", "options": ["Requerimento Projeto Requerimento Construção Instalação Manutenção", "Projeto Construção Teste/Depuração Instalação Manutenção", "Requerimento Projeto Construção Teste/Depuração Instalação Manutenção", "Requerimento Projeto Construção Instalação Manutenção", "Requerimento Projeto Construção Requerimento Teste/Depuração Instalação Manutenção"], "answer": 2, "explain": "<strong>Requerimento → Projeto → Construção → Teste/Depuração → Instalação → Manutenção</strong>.", "area": "prog"}, {"num": 9, "stemHtml": "<p>Um banco de dados relacional é uma coleção de tabelas, que estão associadas umas as outras por meio de atributos (campos) em comum que definem a associação entre si. Para existir um relacionamento entre as entidades, temos de identificar os atributos que definem a associação. Esses atributos são as chaves das relações. Nesse contexto, podemos afirmar que:</p>\n<pre class='q-code'>É a chave candidata, que permite a identificação de ocorrências\ndentro de uma entidade, garantindo que cada linha da tabela\nI.  Chave Primária:\npossa ser endereçada de maneira única, e por esse motivo, deve\nser preenchida, obrigatoriamente.</pre>\n<pre class='q-code'>Quando há várias chaves candidatas, uma é escolhida para ser a\nII.  Chave Alternativa:\nchave primária e as restantes são chamadas de chaves alternativas.</pre>\n<pre class='q-code'>Trata-se de um atributo ou grupo de atributos de uma entidade\nIII.  Chave Estrangeira:\nque é chave primária de outra entidade.</pre>\n<p>É correto afirmar que:</p>", "options": ["somente as alternativas I e III estão corretas.", "as alternativas I, II e III estão corretas.", "somente a alternativa I está correta.", "somente a alternativa II está correta.", "somente a alternativa III está correta."], "answer": 1, "explain": "Chave Primária (I), Chave Alternativa (II — chaves candidatas não escolhidas como PK) e Chave Estrangeira (III) — todas corretas.", "area": "bd"}, {"num": 10, "stemHtml": "<p>Os requisitos abordam itens de qualidade e devem ser levados em consideração para que o software seja consistente e de boa qualidade. Portanto, devem ser definidos antecipadamente, englobando um conjunto de atributos de qualidade ou requisitos que o sistema deve suportar, os quais podem ser classificados como usabilidade, manutenibilidade, confiabilidade, desempenho, portabilidade e segurança. A facilidade com a qual o software pode ser transferido de um sistema computacional ou ambiente para outro e permanecer executável é definida como requisito de:</p>", "options": ["Usabilidade", "Segurança", "Confiabilidade", "Manutenibilidade", "Portabilidade"], "answer": 4, "explain": "Facilidade de transferir software de um ambiente/sistema para outro = <strong>Portabilidade</strong>.", "area": "prog"}, {"num": 11, "stemHtml": "<p>A Engenharia de Requisitos pode ser definida como o processo de desenvolvimento de requisitos por meio da análise de problema, da documentação, de observações, as quais contribuem para a produção de um documento de requisitos, cujo processo consiste em um conjunto estruturado de atividades para extrair, validar e manter um documento de requisitos, contemplando uma descrição de quais atividades são realizadas, qual a estruturação ou o particionamento dessas atividades, quem é responsável por elas, quais as entradas e saídas e as ferramentas usadas. Os requisitos podem apresentam-se como:</p>\n<pre class='q-code'>especifica uma função que o sistema ou componente\nde software deve ser capaz de realizar, ou seja,\nRequisito  processo ou transformação que componentes de\nI.\nfuncional:  software ou hardware efetuam sobre as entradas\npara gerar as saídas, englobando o ponto de vista\ndo usuário.</pre>\n<pre class='q-code'>descreve não o que o sistema fará, mas como ele fará.\nDessa forma, verificam-se requisitos de desempenho,\nRequisito não  da interface externa do sistema, das restrições de\nII.\nfuncional:  projeto e dos atributos da qualidade. Portanto, está\ndiretamente relacionado à funcionalidade de um\nsistema.</pre>\n<pre class='q-code'>são processos que devem ser especificados\nRequisito\ndepois do desenvolvimento do software, levando\nfuncional e\nIII.  em consideração a implantação, manutenção e\nrequisito não\nmanual do usuário, com o objetivo de atender as\nfuncional:\nnecessidades do cliente.</pre>\n<p>É correto afirmar que:</p>", "options": ["somente as alternativas I e II estão corretas.", "as alternativas I, II e III estão corretas.", "somente a alternativa I está correta.", "somente a alternativa II está correta.", "somente a alternativa III está correta."], "answer": 0, "explain": "Gabarito oficial: (A).", "area": "prog"}, {"num": 12, "stemHtml": "<p>O Scrum é uma metodologia ágil, iterativa para gestão e planejamento de projetos de software, por meio da qual os projetos são divididos em ciclos (iterações) chamados de Sprints, que representam um Time Box dentro do qual um conjunto de atividades deve ser executado. As funcionalidades a serem implementadas em um projeto são mantidas em uma lista. No início de cada Sprint, faz-se uma reunião de planejamento na qual se priorizam os itens a serem implementados e a equipe seleciona as atividades que ela será capaz de implementar durante o Sprint que se inicia.</p>\n<p>A cada dia de um Sprint, a equipe faz uma breve reunião (normalmente de manhã), denominada de:</p>", "options": ["Product Backlog", "Sprint Planning", "Sprint Planning Meeting", "Daily Scrum", "Product Owner"], "answer": 3, "explain": "Reunião diária curta do Scrum = <strong>Daily Scrum</strong>.", "area": "prog"}, {"num": 13, "stemHtml": "<p>O círculo cromático é composto por doze cores: as três primárias, as três secundárias e as seis terciárias. É uma representação simplificada das cores percebidas pelo olho humano. Esse instrumento é utilizado para compor ilustrações coloridas, sendo um guia por meio do qual podemos identificar facilmente as cores complementares, as análogas, as meio-complementares e outras combinações possíveis. Para um projeto que utiliza três cores em sua composição, podemos utilizar as combinações harmônicas:</p>", "options": ["Complementares , Análogas e Meio-complementares", "Análogas , Triangulação e Meio-complementares", "Complementares , Retângulo e Quadrado", "Triangulação , Meio-complementares e Quadrado", "Complementares , Triangulação e Meio-complementares"], "answer": 1, "explain": "Combinações harmônicas de <strong>3 cores</strong> no círculo cromático = <strong>Análogas, Triangulação e Meio-complementares</strong>. <em>(Complementares = 2 cores; Retângulo e Quadrado = 4 cores)</em>.", "area": "design"}, {"num": 14, "stemHtml": "<p>Tipografia representa a impressão dos tipos (fontes) e é também conhecida como o estudo, criação e aplicação dos caracteres, estilos, formatos e arranjos visuais das palavras na era digital. Existem classificações de estilo, nos quais a grande parte das fontes existentes se encaixam como, por exemplo, as fontes utilizadas em trabalhos gráficos, como convites, pois são tradicionais e reproduzem a escrita humana, passando uma mensagem de elegância, classe, antiguidade.</p>\n<p>As fontes que representam essa ação são classificadas como:</p>", "options": ["Fontes Serifadas", "Fontes não Serifadas", "Fontes Script", "Fontes Black Letter’s", "Fontes Modernas"], "answer": 2, "explain": "Fontes que reproduzem escrita humana, elegância, usadas em convites = <strong>Fontes Script</strong>.", "area": "design"}, {"num": 15, "stemHtml": "<p>A Heurística é um método ou processo criado com o objetivo de encontrar soluções para um problema, No contexto de UX (User Experience), uma análise heurística (ou avaliação heurística) é uma avaliação rápida e prática de um produto, interface ou serviço. Normalmente, é feita por um especialista de UX que leva em conta a experiência que possui para, rapidamente, determinar o que funciona ou não em um sistema. Um exemplo de avaliação heurísticas foi proposto por Jakob Nielsen. Essas avaliações podem ser usadas durante e após a execução do projeto como, por exemplo: “toda comunicação do produto deve falar a linguagem do usuário e não ser orientada ao sistema, ou seja, não devemos usar linguagem técnica ou termos que são de conhecimento específico. Todas as nomenclaturas devem ser contextualizadas e ser coerentes com o modelo mental do usuário. Isso também é aplicado a ícones e imagens ilustrativas”.</p>\n<p>Essa afirmação da heurística de Nielsen refere-se a:</p>", "options": ["Equivalência entre o sistema e o mundo real", "Flexibilidade e eficiência de uso", "Ajuda aos usuários para reconhecer, diagnosticar e recuperar ações erradas", "Visibilidade do estado do sistema", "Consistência e padrões"], "answer": 0, "explain": "Falar a linguagem do usuário e seguir seu modelo mental = <strong>Equivalência entre o sistema e o mundo real</strong> (Heurística de Nielsen).", "area": "design"}, {"num": 16, "stemHtml": "<p>HTML5 é a mais recente evolução do padrão que define o HTML. O termo representa os conceitos para uma nova versão da linguagem HTML com novos elementos, atributos e comportamentos, incluindo um conjunto maior de tecnologias que permite o desenvolvimento de aplicações e web sites mais diversificados. Com esse propósito, o HTML5 introduz novos elementos para representar coleções de links, para informações relacionadas ao site e para áreas de conteúdo, assim delimitando semanticamente suas áreas.</p>\n<p>Nesse contexto, as tags responsáveis por essa nova estrutura no HTML5 são representadas por:</p>", "options": ["&lt;nav&gt;&lt;header&gt;&lt;div&gt;&lt;span&gt;", "&lt;nav&gt;&lt;header&gt;&lt;div&gt;&lt;section&gt;", "&lt;body&gt;&lt;header&gt;&lt;footer&gt;&lt;section&gt;", "&lt;nav&gt;&lt;header&gt;&lt;body&gt;&lt;section&gt;", "&lt;nav&gt;&lt;header&gt;&lt;footer&gt;&lt;section&gt;"], "answer": 4, "explain": "Tags semânticas estruturais do HTML5 = <strong><code>&lt;nav&gt;&lt;header&gt;&lt;footer&gt;&lt;section&gt;</code></strong> (<code>&lt;div&gt;</code> e <code>&lt;span&gt;</code> não são semânticas; <code>&lt;body&gt;</code> já existia antes do HTML5).", "area": "web_redes"}, {"num": 17, "stemHtml": "<p>CSS3 é uma versão do Cascading Style Sheets (ou simplesmente CSS), em que se definem estilos para páginas web com efeitos de transição, imagem e outros, que dão um estilo novo às páginas Web, em todos os aspectos de design do layout. O CSS3 é extremamente capaz de construir animações que impressionam, tanto em 2 ou em 3 dimensões com os efeitos de rotação, movimento e transição.</p>\n<p>Os efeitos de aumentar proporcionalmente o tamanho do elemento, levando em consideração seu tamanho original; modificar os ângulos dos elementos; movimentar o elemento no eixo X e Y e rotacionar o elemento, levando em consideração seu ângulo, são representados, respectivamente, pelos elementos:</p>\n<p>Aumentar  Modificar  Movimentar  Rotacionar</p>", "options": ["scale skew change rotate", "scale angular translate roll", "scale skew translate roll", "scale angular translate rotate", "scale skew translate rotate"], "answer": 4, "explain": "Aumentar = <strong><code>scale</code></strong>, Modificar ângulos = <strong><code>skew</code></strong>, Movimentar X/Y = <strong><code>translate</code></strong>, Rotacionar = <strong><code>rotate</code></strong>.", "area": "web_redes"}, {"num": 18, "stemHtml": "<p>Bootstrap é um framework front-end que ajuda no desenvolvimento de sites e aplicações WEB, compreendendo uma coleção de vários elementos e funções para desenvolvimento WEB em uma única ferramenta. Uma característica do Bootstrap é que ele é responsivo, ou seja, a tela do celular, tablet ou computador é ajustada sem a necessidade de adicionar um código específico para cada layout de tela, sendo organizado por classes predefinidas para opções de layout.</p>\n<p>As classes “btn btn-default”, “form-inline”, “col-md-1”, “img-responsive” e “text-primary” do Bootstrap são representações para formatação de:</p>\n<p>“btn btn-default”  “form-inline”  “col-md-1”  “img-responsive”  “text-primary”</p>", "options": ["botão formulário grid tabela ajuda", "botão formulário grid imagem ajuda", "botão tabela grid imagem ajuda", "botão tabela formulário imagem ajuda", "botão formulário grid imagem tabela"], "answer": 1, "explain": "<code>btn btn-default</code> (<strong>botão</strong>), <code>form-inline</code> (<strong>formulário</strong>), <code>col-md-1</code> (<strong>grid</strong>), <code>img-responsive</code> (<strong>imagem</strong>), <code>text-primary</code> (<strong>ajuda/texto contextual</strong>).", "area": "prog"}, {"num": 19, "stemHtml": "<p>O Document Object Model (DOM) é utilizado pelo navegador para representar uma página Web. Quando altera-se esse modelo com o uso do Javascript altera-se também a página. Responsável por isso tudo é o objeto “document” que concede ao código Javascript todo o acesso à árvore DOM do navegador.</p>\n<p>As funções para buscar um elemento da página Web com o uso do atributo “id” do elemento; criar um nodo texto na página; capturar o elemento raiz &lt;html&gt; de um documento e retornar o nodo pai de um nodo, são representados, respectivamente, pelos comandos:</p>\n<p>Buscar  Criar  Capturar  Retornar</p>", "options": ["getElementById createElement parentNode documentElement", "getElementById createAttribute documentElement parentNode", "getElementById createTextNode documentElement parentNode", "getElementsByTagName createTextNode documentElement parentNode", "getElementsByTagName createElement parentNode documentElement"], "answer": 2, "explain": "buscar por ID (<code>getElementById</code>), criar nodo texto (<code>createTextNode</code>), elemento raiz <code>&lt;html&gt;</code> (<code>documentElement</code>), nodo pai (<code>parentNode</code>).", "area": "web_redes"}, {"num": 20, "stemHtml": "<p>Um sistema de numeração é um conjunto de números que são representados por numerais de uma forma consistente. Na computação, encontramos o sistema decimal, um sistema de numeração que utiliza a base dez; o sistema hexadecimal, um sistema de numeração posicional que representa os números em base 16, portanto, empregando símbolos; e também o sistema binário ou de base 2, que é um sistema de numeração em que todas as quantidades se representam, com base em dois números, ou seja, zero e um (0 e 1).</p>\n<p>Os números 100 e 250, na base 10, são representados, na base 2 e 16, pelos números:</p>\n<p>100  250</p>", "options": ["100(10) = 10000100(2) = 64(16 e 250(10) = 11111011(2) = FA(16)", "100(10) = 01000101(2) = 65(16) e 250(10) = 11111010(2) = FA(16)", "100(10) = 01100100(2) = 64(16) e 250((10) = 11111010(2) = FA(16)", "100(10) = 10000100(2) = 65(16) e 250(10) = 11111011(2) = FA(16)", "100(10) = 01000100(2) = 64(16) e 250(10) = 11111010(2) = FF(16)"], "answer": 2, "explain": "<code>100(10) = 01100100(2) = 64(16)</code> e <code>250(10) = 11111010(2) = FA(16)</code>.", "area": "web_redes"}, {"num": 21, "stemHtml": "<p>Uma unidade de armazenamento que aloca os dados em chips de memória flash, basicamente do mesmo modo que um pendrive faz para guardar os arquivos, cujo consumo energético pode fazer com que a bateria do notebook dure mais tempo e que não possui as partes mecânicas, reduzindo as vibrações e, com tempo de acesso reduzido, caracteriza-se como:</p>", "options": ["SSD (solid-state drive)", "HD (Hard Disk)", "SCSI (Small Computer Systems Interface)", "DDR4 (Double Data Rate 4)", "L1 Cache"], "answer": 0, "explain": "Armazenamento em chips flash, sem partes mecânicas, menor consumo e tempo de acesso = <strong>SSD</strong>.", "area": "web_redes"}, {"num": 22, "stemHtml": "<p>O Linux é um sistema operacional, assim como o Windows da Microsoft e o Mac OS da Apple, criado pelo finlandês Linus Torvalds e o seu nome é a mistura do nome do criador com Unix, um antigo sistema operacional, o qual disponibiliza uma série de comandos. No Linux, há comandos que permitem otimizar e executar tarefas básicas diárias com mais rapidez e facilidade como, por exemplo: mostrar todos os arquivos e pastas do diretório; criar uma nova pasta ou subpasta; copiar e colar, usando o terminal; instalar, remover e atualizar qualquer pacote; consultar o conteúdo de algum arquivo de texto ou script e desligar ou reiniciar o computador pelo terminal.</p>\n<p>Essas ações, na ordem, são executadas pelos comandos:</p>\n<p>Instalar, Remover  Desligar Mostrar  Criar  Copiar e Colar  Consultar e Atualizar  ou Reiniciar</p>", "options": ["ls mkdir cp cat apt shutdown", "ls rm cp apt cat shutdown", "ls mkdir cp apt cat shutdown", "ls rm cp cat apt shutdown", "ls mkdir cp apt cat sudo"], "answer": 2, "explain": "mostrar (<code>ls</code>), criar pasta (<code>mkdir</code>), copiar (<code>cp</code>), gerenciar pacotes (<code>apt</code>), ler arquivo (<code>cat</code>), desligar/reiniciar (<code>shutdown</code>).", "area": "web_redes"}, {"num": 23, "stemHtml": "<pre class='q-code'>A topologia física é a verdadeira aparência ou layout da rede, enquanto que a lógica descreve o fluxo dos\ndados através da rede. Em uma topologia de rede em que toda a informação deve passar obrigatoriamente\npor uma unidade central inteligente (switches), conectar cada estação da rede e distribuir o tráfego para que\numa estação não receba, indevidamente, dados destinados às outras estações são características de uma rede\nde tipologia:</pre>", "options": ["Ponto a ponto", "Barramento", "Anel", "Árvore", "Estrela"], "answer": 4, "explain": "Topologia com unidade central inteligente (<em>switches</em>) distribuindo tráfego = <strong>Estrela</strong>.", "area": "web_redes"}, {"num": 24, "stemHtml": "<p>Programação em par é uma prática utilizada por times que adotam o Extreme Programming (XP), em que o código como um todo deve ser produzido por um time formado por duplas. Durante a implementação, um programador age como o principal (digitando o código) e outro age como secundário (revisando, apontando problemas e pensando na solução como um todo) e a cada determinado ciclo de tempo, os profissionais invertem os papéis.</p>\n<p>São vantagens desse tipo de programação:</p>\n<pre class='q-code'>Compartilhamento\nI.  todo código produzido é visto por, pelo menos, duas pessoas\ndo conhecimento:</pre>\n<pre class='q-code'>com duas pessoas analisando o código, as falhas de lógica são\nII.  Correção de falhas:\ndetectadas e corrigidas mais rapidamente.</pre>\n<pre class='q-code'>III.  Manutenibilidade:  mais simples de se fazer manutenção.</pre>\n<p>É correto afirmar que:</p>", "options": ["as alternativas I, II e III estão corretas.", "somente a alternativa I está correta.", "somente a alternativa II está correta.", "somente a alternativa III está correta.", "somente as alternativas II e III estão corretas."], "answer": 0, "explain": "compartilhamento de conhecimento, correção rápida de falhas e manutenibilidade — todas corretas.", "area": "prog"}, {"num": 25, "stemHtml": "<p>Teste de Software é a forma de se verificar unidades individuais de código fonte, as quais podem ser métodos, classes, funcionalidades, módulos, etc. Depende muito de qual é a menor parte do Software que pode ser testada, cujo objetivo é mostrar que cada unidade atende corretamente a sua especificação, o que possibilita encontrar problemas o quanto antes, facilitando a mudança da unidade, simplificando a integração e melhorando a documentação.</p>\n<p>Essa afirmação refere-se ao:</p>", "options": ["Teste de Integridade", "Teste Funcional", "Teste de Unidade", "Teste de Configuração", "Teste de Performance"], "answer": 2, "explain": "Verificar a menor unidade individual de código (métodos/classes) = <strong>Teste de Unidade</strong>.", "area": "prog"}, {"num": 26, "stemHtml": "<p>Um sistema de controle de versões (ou versionamento), na prática, é um software que tem a finalidade de gerenciar diferentes versões no desenvolvimento de um documento qualquer. Em um sistema moderno de controle de versões, é possível quebrar a linha do desenvolvimento em mais de um caminho; comparar quaisquer versões entre si, enviadas a qualquer tempo e fundir versões por meio da comparação entre elas.</p>\n<p>Esse processo é representado pelas ações de:</p>\n<p>Quebrar  Comparar  Fundir</p>", "options": ["update diff merge", "branch diff merge", "release diff commit", "release diff merge", "branch revision merge"], "answer": 1, "explain": "quebrar linha = <strong><code>branch</code></strong>, comparar = <strong><code>diff</code></strong>, fundir = <strong><code>merge</code></strong>.", "area": "prog"}, {"num": 27, "stemHtml": "<p>O paradigma de programação é o conceito que pressupõe a forma que o programador tem sobre a programação e a execução de um programa; é a forma de estrutura que será utilizada para se programar e executar o software. Esse conceito é abordado por todas as linguagens de programação como, por exemplo, a Programação Orientada a Objetos em que o programa é composto por objetos com propriedades (atributos) e operações (métodos). Isso acontece, porque se trata de um padrão que tem evoluído em questões de segurança e reaproveitamento de código, o que é muito importante no desenvolvimento de qualquer aplicação moderna.</p>\n<p>A Programação Orientada a Objetos (POO) é representada pelos pilares:</p>", "options": ["Abstração Atributos Herança Métodos", "Abstração Atributos Herança Polimorfismo", "Abstração Encapsulamento Atributos Métodos", "Abstração Encapsulamento Herança Polimorfismo", "Atributos Encapsulamento Herança Métodos"], "answer": 3, "explain": "Os <strong>4 pilares da POO</strong> = <strong>Abstração, Encapsulamento, Herança e Polimorfismo</strong>. <em>(Atributos e Métodos são elementos da classe, não pilares!)</em>.", "area": "prog"}, {"num": 28, "stemHtml": "<p>Leia o texto para responder às questões de números 28 a 30.</p>\n<p>Apesar de todas as críticas, a Teoria Clássica é ainda a abordagem mais utilizada pelos iniciantes em Administração, pois permite uma visão simples e ordenada. Também para a execução de tarefas administrativas rotineiras, a abordagem clássica disseca o trabalho organizacional em categorias compreensíveis e úteis. Os princípios proporcionam guias gerais que permitem ao administrador manipular os deveres do cotidiano do seu trabalho com mais segurança e confiança. Contudo, em uma era de mudança e instabilidade como a que atravessamos, a abordagem clássica mostra-se rígida, inflexível e conservadora, pois ela foi concebida em uma época de estabilidade e permanência. Em resumo, a Teoria Clássica ainda tem a sua utilidade no mundo de hoje. Ela é indispensável na compreensão das bases da Administração moderna. CHIAVENATO, Idalberto. Administração geral e pública. São Paulo: Barueri (SP): Manole, 2012, p. 13. Adaptado.</p>\n<p>Assinale a alternativa correta, de acordo com o texto.</p>", "options": ["A Teoria Clássica não se mostra mais útil no mundo contemporâneo, época de mudanças e incertezas.", "Em época de instabilidade e mudança, os princípios da Teoria Clássica ainda se mostram válidos, pois permitem uma visão simples e ordenada dos fatos, além da flexibilidade.", "A Teoria Clássica só tem validade no mundo de hoje, porque fornece as bases para o entendimento da Administração moderna.", "O fato de ter sido desenvolvida em um contexto de estabilidade e permanência torna a Teoria Clássica não a mais indicada para a abordagem de fenômenos típicos do mundo de hoje, embora ainda se mostre válida sob alguns aspectos.", "O administrador encontrará, exclusivamente, na Teoria Clássica, princípios que funcionarão como guias gerais que permitirão manipular os deveres do cotidiano com mais segurança e confiança."], "answer": 3, "explain": "Interpretação do texto de Chiavenato: a Teoria Clássica foi criada em contexto de estabilidade, por isso não é a mais indicada hoje, embora ainda tenha utilidade básica.", "area": "mtec_base"}, {"num": 29, "stemHtml": "<p>Leia o texto para responder às questões de números 28 a 30.</p>\n<p>Apesar de todas as críticas, a Teoria Clássica é ainda a abordagem mais utilizada pelos iniciantes em Administração, pois permite uma visão simples e ordenada. Também para a execução de tarefas administrativas rotineiras, a abordagem clássica disseca o trabalho organizacional em categorias compreensíveis e úteis. Os princípios proporcionam guias gerais que permitem ao administrador manipular os deveres do cotidiano do seu trabalho com mais segurança e confiança. Contudo, em uma era de mudança e instabilidade como a que atravessamos, a abordagem clássica mostra-se rígida, inflexível e conservadora, pois ela foi concebida em uma época de estabilidade e permanência. Em resumo, a Teoria Clássica ainda tem a sua utilidade no mundo de hoje. Ela é indispensável na compreensão das bases da Administração moderna. CHIAVENATO, Idalberto. Administração geral e pública. São Paulo: Barueri (SP): Manole, 2012, p. 13. Adaptado.</p>\n<p>Releia a passagem.</p>\n<p>“Os princípios proporcionam guias gerais que permitem ao administrador manipular os deveres do cotidiano do seu trabalho com mais segurança e confiança.”</p>\n<p>De acordo com o texto, a expressão “Os princípios” se refere:</p>", "options": ["a fundamentos da Teoria Clássica.", "à execução de tarefas.", "ao trabalho organizacional como um todo.", "à visão simples e ordenada das funções a serem executadas.", "à função do administrador frente a mudanças e instabilidades."], "answer": 0, "explain": "A expressão 'Os princípios' retoma os fundamentos da Teoria Clássica citados no período anterior.", "area": "mtec_base"}, {"num": 30, "stemHtml": "<p>Leia o texto para responder às questões de números 28 a 30.</p>\n<p>Apesar de todas as críticas, a Teoria Clássica é ainda a abordagem mais utilizada pelos iniciantes em Administração, pois permite uma visão simples e ordenada. Também para a execução de tarefas administrativas rotineiras, a abordagem clássica disseca o trabalho organizacional em categorias compreensíveis e úteis. Os princípios proporcionam guias gerais que permitem ao administrador manipular os deveres do cotidiano do seu trabalho com mais segurança e confiança. Contudo, em uma era de mudança e instabilidade como a que atravessamos, a abordagem clássica mostra-se rígida, inflexível e conservadora, pois ela foi concebida em uma época de estabilidade e permanência. Em resumo, a Teoria Clássica ainda tem a sua utilidade no mundo de hoje. Ela é indispensável na compreensão das bases da Administração moderna. CHIAVENATO, Idalberto. Administração geral e pública. São Paulo: Barueri (SP): Manole, 2012, p. 13. Adaptado.</p>\n<p>Leia novamente a passagem.</p>\n<p>Apesar de todas as críticas, a Teoria Clássica é ainda a abordagem mais utilizada pelos iniciantes em Administração, pois permite uma visão simples e ordenada.</p>\n<p>As expressões “apesar de” e “pois” expressam, respectivamente, os sentidos de:</p>", "options": ["oposição e justificativa.", "finalidade e condição.", "oposição e conformidade.", "conformidade e contraste.", "finalidade e conclusão."], "answer": 0, "explain": "'Apesar de' expressa oposição/concessão e 'pois' expressa justificativa/explicação.", "area": "mtec_base"}]}, "apostas": {"id": "apostas", "title": "Simulado Premonição — 30 Apostas Próxima Prova", "badge": "Previsão FAT • 30 Questões", "desc": "30 questões inéditas desenhadas sobre os tópicos do Plano de Curso do 1º ano com maior chance de cair na próxima prova.", "minutes": 120, "questions": [{"num": 1, "stemHtml": "<blockquote class='q-quote'><strong>Why Teamwork and Problem-Solving Drive Software Quality</strong><br><br>Building reliable software rarely happens in isolation. Effective developers combine strong technical skills with clear communication and collaborative troubleshooting. When teams analyze system data together, share feedback early, and verify expected outcomes, they prevent costly bugs in production. Employers consistently look for professionals who take ownership of errors and adapt quickly to changing project requirements.</blockquote>\n<p>De acordo com o texto, o desenvolvimento de software confiável (<em>reliable software</em>) depende principalmente da combinação entre</p>", "options": ["trabalho isolado e memorização rígida de códigos antigos.", "habilidades técnicas, comunicação clara e solução colaborativa de problemas.", "ocultação de erros para evitar atrasos nas entregas ao cliente.", "substituição completa de testes de qualidade por reuniões informais.", "redução da equipe para eliminar a troca de feedback."], "answer": 1, "explain": "<strong>Molde 3:</strong> O texto liga <em>reliable software</em> a <em>technical skills + clear communication + collaborative troubleshooting</em>.", "area": "ingles_etica"}, {"num": 2, "stemHtml": "<blockquote class='q-quote'><strong>Why Teamwork and Problem-Solving Drive Software Quality</strong><br><br>Building reliable software rarely happens in isolation. Effective developers combine strong technical skills with clear communication and collaborative troubleshooting. When teams analyze system data together, share feedback early, and verify expected outcomes, they prevent costly bugs in production. Employers consistently look for professionals who take ownership of errors and adapt quickly to changing project requirements.</blockquote>\n<p>No texto, os termos <em>reliable</em>, <em>data</em> e <em>outcomes</em> são compreendidos, respectivamente, como</p>", "options": ["relativo, datas e saídas de emergência.", "confiável, dados e resultados.", "rápido, prazos e exclusões.", "repetitivo, datas e tarefas.", "rígido, arquivos e comandos."], "answer": 1, "explain": "<strong>Molde 3:</strong> <em>reliable</em> = confiável; <em>data</em> = dados (não \"datas\"); <em>outcomes</em> = resultados.", "area": "ingles_etica"}, {"num": 3, "stemHtml": "<p>Em um infográfico em inglês intitulado <strong>\"Agile Development Cycle\"</strong>, estão listadas cinco etapas: <code>1. Requirement Gathering</code> &rarr; <code>2. Design &amp; Prototyping</code> &rarr; <code>3. Coding &amp; Pair Review</code> &rarr; <code>4. Automated Testing</code> &rarr; <code>5. Deployment &amp; Monitoring</code>. Com base nessas etapas, o ciclo ágil descrito contempla, respectivamente,</p>", "options": ["a coleta de requisitos e a implantação com monitoramento contínuo.", "a dispensa de prototipagem e a eliminação de testes automatizados.", "a análise de datas de entrega e o descarte do código após a revisão.", "o isolamento do programador e a execução exclusivamente manual de testes.", "a entrega sem planejamento prévio e a remoção de registros de erro."], "answer": 0, "explain": "<strong>Molde 3:</strong> Etapa 1 (<em>Requirement Gathering</em> = coleta de requisitos) e Etapa 5 (<em>Deployment &amp; Monitoring</em> = implantação e monitoramento).", "area": "ingles_etica"}, {"num": 4, "stemHtml": "<p>As ações comportamentais voltadas para o bem comum refletem valores de solidariedade e responsabilidade social. Qual das atitudes abaixo exemplifica uma ação ética orientada para o bem comum na área de tecnologia?</p>", "options": ["Um programador desenvolve um aplicativo acessível para auxiliar idosos do bairro a agendar consultas públicas gratuitas, sem fins lucrativos ou autopromoção.", "Um estudante cria um site comunitário apenas para anexar links de apostas patrocinadas e lucrar sobre os visitantes.", "Uma empresa doa computadores quebrados e sem conserto para uma escola apenas para evitar pagar a taxa de descarte de lixo eletrônico.", "Um técnico participa de um mutirão de inclusão digital somente para gravar vídeos curtos buscando engajamento pessoal.", "Um funcionário altera dados de presença no sistema interno para favorecer um amigo próximo."], "answer": 0, "explain": "<strong>Molde 3:</strong> Única ação solidária genuína para a comunidade sem autopromoção, lucro oculto, fraude ou descarte irregular disfarçado.", "area": "ingles_etica"}, {"num": 5, "stemHtml": "<p>No contexto das relações trabalhistas, proteção de dados e consumo consciente em sistemas digitais, representa uma conduta ética e responsável:</p>", "options": ["Vender cadastros de clientes sem consentimento para recuperar prejuízos financeiros da empresa.", "Coletar apenas os dados estritamente necessários com transparência ao usuário, garantindo acessibilidade e respeitando os direitos trabalhistas da equipe de TI.", "Exigir horas extras não registradas dos desenvolvedores para cumprir prazos comerciais irreais.", "Inserir cobranças automáticas ocultas em assinaturas digitais para aumentar a receita recorrente.", "Ignorar falhas graves de segurança em aplicativos móveis por falta de reclamações imediatas."], "answer": 1, "explain": "<strong>Molde 3:</strong> Coleta mínima transparente + acessibilidade + respeito às leis trabalhistas.", "area": "ingles_etica"}, {"num": 6, "stemHtml": "<p>Considerando os princípios constitucionais e a legislação ambiental aplicados a projetos tecnológicos, assinale a alternativa que apresenta uma ação ética:</p>", "options": ["Instalar um data center consumindo mananciais protegidos sem estudo prévio de impacto ambiental.", "Garantir transparência, participação das comunidades afetadas e destinação sustentável de resíduos eletrônicos conforme as normas ambientais.", "Descartar baterias e placas eletrônicas em terrenos baldios periféricos para reduzir custos operacionais.", "Flexibilizar a fiscalização ambiental em regiões críticas para atrair investimentos de mineração de dados.", "Priorizar exclusivamente a redução de impostos acima da preservação dos recursos hídricos locais."], "answer": 1, "explain": "<strong>Molde 3:</strong> Participação comunitária + descarte sustentável conforme legislação ambiental.", "area": "ingles_etica"}, {"num": 7, "stemHtml": "<p>Fluxogramas representam visualmente o fluxo lógico de algoritmos por meio de símbolos padronizados. Analise a tabela abaixo:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Símbolo do Fluxograma</th><th>Função no Algoritmo</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>Oval / Cápsula (Terminal)</strong></td><td>Indica o ponto de <strong>Início</strong> e o ponto de <strong>Fim</strong> do fluxo do algoritmo.</td></tr><tr><td><strong>II.</strong></td><td><strong>Retângulo</strong></td><td>Representa uma <strong>decisão condicional</strong> (<code>Sim</code> / <code>Não</code>), desviando o fluxo conforme uma condição lógica.</td></tr><tr><td><strong>III.</strong></td><td><strong>Losango</strong></td><td>Representa uma instrução de <strong>processamento ou cálculo</strong> matemático, como atribuições de variáveis.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente a afirmativa II está correta.", "somente a afirmativa III está correta.", "somente as afirmativas I e II estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 0, "explain": "<strong>Molde 1:</strong> <strong>Inversão clássica:</strong> II atribuiu decisão ao Retângulo (errado: Retângulo é processamento) e III atribuiu cálculo ao Losango (errado: Losango é decisão). Apenas I está correta.", "area": "prog"}, {"num": 8, "stemHtml": "<p>No processo de desenvolvimento e compilação de programas em linguagens como C, C++ ou Java, analise as definições:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Etapa / Artefato</th><th>Descrição</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>Código-Fonte</strong></td><td>Texto original escrito pelo programador em uma linguagem de programação de alto nível legível por humanos.</td></tr><tr><td><strong>II.</strong></td><td><strong>Código Objeto</strong></td><td>Código intermediário gerado pelo compilador após traduzir o código-fonte, antes da ligação final com bibliotecas externas.</td></tr><tr><td><strong>III.</strong></td><td><strong>Código Executável</strong></td><td>Arquivo final pronto para ser carregado e executado diretamente pelo sistema operacional.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas II e III estão corretas.", "somente a afirmativa III está correta.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "<strong>Molde 1:</strong> Todas corretas: Código-Fonte (humano) &rarr; Código Objeto (intermediário) &rarr; Executável (final).", "area": "prog"}, {"num": 9, "stemHtml": "<p>Estruturas de repetição (laços) permitem executar um bloco de instruções múltiplas vezes enquanto uma condição for atendida. A estrutura de repetição que avalia a condição lógica apenas <strong>ao final</strong> do bloco, garantindo que as instruções sejam executadas <strong>pelo menos uma vez</strong> mesmo que a condição já seja inicialmente falsa, é conhecida como:</p>", "options": ["<code>while</code> (Enquanto com teste no início).", "<code>if / else</code> (Desvio condicional simples).", "<code>do-while</code> (Faça-Enquanto / Repita-Até).", "<code>switch / case</code> (Seleção múltipla).", "<code>try / catch</code> (Tratamento de exceções)."], "answer": 2, "explain": "<strong>Molde 3:</strong> <code>do-while</code> (repita-até) testa a condição <strong>no final</strong>, garantindo no mínimo 1 execução (diferente do <code>while</code>, que testa no início).", "area": "prog"}, {"num": 10, "stemHtml": "<p>Observe o algoritmo em pseudocódigo abaixo envolvendo o vetor <code>V = [2, 5, 8, 3, 6]</code> (com índices iniciando em <code>0</code>) e o operador <code>MOD</code> (resto da divisão inteira):</p>\n<pre class='q-code'>soma &lt;- 0\npara i de 0 até 4 faça\n    se (V[i] MOD 2) = 0 então\n        soma &lt;- soma + V[i]\n    fim-se\nfim-para\nescreva(soma)</pre>\n<p>Realizando o teste de mesa linha a linha, qual valor será exibido ao final da execução?</p>", "options": ["8", "10", "14", "16", "24"], "answer": 3, "explain": "<strong>Molde 4:</strong> Apenas os elementos pares (<code>MOD 2 == 0</code>) entram na soma: <code>V[0]=2</code>, <code>V[2]=8</code>, <code>V[4]=6</code> &rarr; <code>2 + 8 + 6 = 16</code>. <em>(Pegadinha: somar todos dá 24; somar os índices pares errado dá outro valor).</em>", "area": "prog"}, {"num": 11, "stemHtml": "<p>A Programação Orientada a Objetos (POO) estrutura o software por meio de classes e objetos visando segurança e reaproveitamento de código. Assinale a alternativa que apresenta <strong>exclusivamente</strong> os <strong>4 pilares da POO</strong>:</p>", "options": ["Abstração, Atributos, Herança e Polimorfismo.", "Abstração, Encapsulamento, Herança e Polimorfismo.", "Encapsulamento, Métodos, Atributos e Compilação.", "Herança, Polimorfismo, Fluxograma e Instanciação.", "Abstração, Normalização, Encapsulamento e Herança."], "answer": 1, "explain": "<strong>Molde 2:</strong> Os 4 pilares da POO são <strong>Abstração, Encapsulamento, Herança e Polimorfismo</strong>. Intrusos: <em>Atributos, Métodos, Compilação, Fluxograma, Normalização</em>.", "area": "prog"}, {"num": 12, "stemHtml": "<p>Sobre Engenharia de Requisitos e Estudo de Viabilidade no desenvolvimento de sistemas, analise a tabela:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Conceito</th><th>Afirmação</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>Requisito Funcional</strong></td><td>Descreve as funções e serviços que o sistema <strong>deve realizar</strong>, como cadastrar alunos ou emitir boletins.</td></tr><tr><td><strong>II.</strong></td><td><strong>Requisito Não Funcional</strong></td><td>Especifica critérios de qualidade e restrições de operação, como desempenho, segurança e <strong>portabilidade</strong>.</td></tr><tr><td><strong>III.</strong></td><td><strong>Viabilidade Técnica</strong></td><td>Avalia se há tecnologia, infraestrutura e conhecimento técnico disponíveis na equipe para construir o sistema proposto.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas II e III estão corretas.", "somente a afirmativa III está correta.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "<strong>Molde 1:</strong> Todas corretas: Requisito Funcional (o que faz), Não Funcional (portabilidade/como faz) e Viabilidade Técnica.", "area": "prog"}, {"num": 13, "stemHtml": "<p>No framework ágil <strong>Scrum</strong>, os papéis e eventos organizam o ciclo iterativo de entregas (<em>Sprints</em>). Analise as afirmações:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Papel / Evento</th><th>Responsabilidade</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td>**<em>Product Owner</em> (PO)**</td><td>Atua como facilitador técnico focado exclusivamente em remover impedimentos do time, sem contato com prioridades de negócio.</td></tr><tr><td><strong>II.</strong></td><td><strong><em>Scrum Master</em></strong></td><td>Define e prioriza o <em>Product Backlog</em> decidindo quais funcionalidades geram maior retorno financeiro ao cliente.</td></tr><tr><td><strong>III.</strong></td><td><strong><em>Daily Scrum</em></strong></td><td>Reunião diária curta realizada durante a <em>Sprint</em> para sincronizar o trabalho da equipe e identificar bloqueios.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente a afirmativa II está correta.", "somente a afirmativa III está correta.", "somente as afirmativas I e II estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 2, "explain": "<strong>Molde 1:</strong> <strong>Inversão clássica:</strong> I deu a definição do <em>Scrum Master</em> ao PO, e II deu a definição do PO ao <em>Scrum Master</em>. Apenas III (<em>Daily Scrum</em>) está correta.", "area": "prog"}, {"num": 14, "stemHtml": "<p>O projeto de um banco de dados relacional passa por três níveis clássicos de abstração antes de entrar em produção. Analise a tabela abaixo:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Nível de Modelagem</th><th>Descrição</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>Modelo Conceitual</strong></td><td>Implementação final com comandos SQL <code>CREATE TABLE</code>, definição de índices e tipos físicos específicos do SGBD MySQL.</td></tr><tr><td><strong>II.</strong></td><td><strong>Modelo Lógico</strong></td><td>Estruturação em tabelas, colunas, chaves primárias (PK) e estrangeiras (FK), sem amarras físicas de armazenamento em disco.</td></tr><tr><td><strong>III.</strong></td><td><strong>Modelo Físico</strong></td><td>Representação abstrata de alto nível feita exclusivamente por Diagrama Entidade-Relacionamento (DER), independente de SGBD.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente a afirmativa II está correta.", "somente a afirmativa III está correta.", "somente as afirmativas I e III estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 1, "explain": "<strong>Molde 1:</strong> <strong>Inversão clássica:</strong> I pôs a definição de Modelo <strong>Físico</strong> no Conceitual, e III pôs a definição de Modelo <strong>Conceitual</strong> no Físico! Apenas II (Lógico) está certa.", "area": "bd"}, {"num": 15, "stemHtml": "<p>Em um Diagrama Entidade-Relacionamento (DER), a entidade <code>Funcionario</code> possui os atributos <code>cpf</code>, <code>endereco</code> (dividido em rua, número e CEP), <code>telefones</code> (vários números para a mesma pessoa) e <code>idade</code> (calculada automaticamente a partir da <code>data_nascimento</code>). Nesse contexto, o atributo <code>idade</code> é classificado como:</p>", "options": ["Atributo Simples (Atômico).", "Atributo Composto.", "Atributo Multivalorado.", "Atributo Derivado.", "Atributo Estrangeiro."], "answer": 3, "explain": "<strong>Molde 3:</strong> <code>idade</code> é <strong>Atributo Derivado</strong> pois é calculado a partir de <code>data_nascimento</code>. (<code>endereco</code> é composto; <code>telefones</code> é multivalorado; <code>cpf</code> é simples/identificador).", "area": "bd"}, {"num": 16, "stemHtml": "<p>Sobre as cinco sublinguagens da SQL (<em>Structured Query Language</em>), analise a tabela:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Sublinguagem</th><th>Comandos e Função</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>DDL e DQL</strong></td><td>DDL (<code>CREATE</code>, <code>ALTER</code>, <code>DROP</code>) define a estrutura das tabelas; DQL (<code>SELECT</code>) realiza consultas de dados.</td></tr><tr><td><strong>II.</strong></td><td><strong>DML</strong></td><td><code>INSERT</code>, <code>UPDATE</code> e <code>DELETE</code> manipulam os registros armazenados nas tabelas.</td></tr><tr><td><strong>III.</strong></td><td><strong>DCL e TCL</strong></td><td>DCL (<code>GRANT</code>, <code>REVOKE</code>) controla permissões de acesso; TCL (<code>COMMIT</code>, <code>ROLLBACK</code>) gerencia transações.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas II e III estão corretas.", "somente a afirmativa III está correta.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "<strong>Molde 1:</strong> Todos os 5 grupos SQL (<code>DDL</code>, <code>DQL</code>, <code>DML</code>, <code>DCL</code>, <code>TCL</code>) estão descritos corretamente.", "area": "bd"}, {"num": 17, "stemHtml": "<p>Um analista encontrou uma tabela <code>Pedidos</code> com dois problemas: (1) o campo <code>produtos</code> guardava <code>\"Teclado, Mouse\"</code> na mesma célula; e (2) precisava contar quantos pedidos tinham status <code>'Entregue'</code>. A forma normal que exige <strong>valores atômicos</strong> para corrigir o problema (1) e a instrução SQL correta para o item (2) são, respectivamente:</p>", "options": ["2ª Forma Normal (2FN) e <code>SELECT * FROM Pedidos WHERE COUNT(status) = 'Entregue';</code>", "1ª Forma Normal (1FN) e <code>SELECT COUNT(*) FROM Pedidos WHERE status = 'Entregue';</code>", "3ª Forma Normal (3FN) e <code>SELECT COUNT('Entregue') FROM Pedidos WHERE status;</code>", "1ª Forma Normal (1FN) e <code>SELECT COUNT(*) WHERE Pedidos FROM status = 'Entregue';</code>", "Forma Normal BCNF e <code>SELECT status FROM Pedidos WHERE COUNT(*);</code>"], "answer": 1, "explain": "<strong>Molde 3/4:</strong> Valores atômicos = <strong>1FN</strong>; consulta correta = <code>SELECT COUNT(*) FROM Pedidos WHERE status = 'Entregue';</code>.", "area": "bd"}, {"num": 18, "stemHtml": "<p>Bancos de dados podem ser relacionais (SQL) ou não relacionais (NoSQL), escolhidos conforme o volume e a estrutura dos dados. Assinale a alternativa que apresenta <strong>exclusivamente</strong> exemplos de bancos <strong>Não Relacionais (NoSQL)</strong>:</p>", "options": ["MongoDB, PostgreSQL e Cassandra.", "MySQL, Oracle e SQL Server.", "MongoDB e Cassandra.", "Cassandra, MariaDB e MongoDB.", "SQLite, MongoDB e Oracle."], "answer": 2, "explain": "<strong>Molde 2:</strong> <strong>MongoDB</strong> e <strong>Cassandra</strong> são NoSQL. Intrusos relacionais (SQL): <em>PostgreSQL, MySQL, Oracle, SQL Server, MariaDB, SQLite</em>.", "area": "bd"}, {"num": 19, "stemHtml": "<p>Sobre Teoria e Padrões de Cores no Design Digital, analise as afirmações:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Conceito</th><th>Afirmação</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>Padrão RGB</strong></td><td>Baseado em síntese aditiva (luz: Vermelho, Verde, Azul), indicado para monitores, celulares e interfaces web.</td></tr><tr><td><strong>II.</strong></td><td><strong>Padrão CMYK</strong></td><td>Baseado em síntese subtrativa (pigmento: Ciano, Magenta, Amarelo, Preto), indicado para materiais gráficos impressos.</td></tr><tr><td><strong>III.</strong></td><td><strong>Círculo Cromático</strong></td><td>Organiza em formato circular 12 cores (3 primárias, 3 secundárias e 6 terciárias) para orientar combinações harmônicas.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas II e III estão corretas.", "somente a afirmativa III está correta.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "<strong>Molde 1:</strong> Todas corretas: RGB (luz/telas), CMYK (pigmento/impressão) e Círculo Cromático (12 cores).", "area": "design"}, {"num": 20, "stemHtml": "<p>Sobre formatos de imagens digitais e tratamento gráfico, analise o quadro:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Tema</th><th>Descrição</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>Imagens Vetoriais</strong></td><td>Formatos como SVG e PDF são definidos por fórmulas matemáticas e podem ser ampliados sem perda de nitidez.</td></tr><tr><td><strong>II.</strong></td><td><strong>Rasterização</strong></td><td>Processo de converter gráficos vetoriais em imagens compostas por pixels para exibição em telas ou impressão.</td></tr><tr><td><strong>III.</strong></td><td><strong>PNG vs. JPEG</strong></td><td>O formato PNG suporta fundo transparente (canal alfa) e compressão sem perdas, enquanto o JPEG usa compressão com perdas e não suporta transparência.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas II e III estão corretas.", "somente a afirmativa III está correta.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "<strong>Molde 1:</strong> Todas corretas: SVG/PDF vetoriais, Rasterização e PNG (canal alfa sem perda) vs. JPEG.", "area": "design"}, {"num": 21, "stemHtml": "<p>Na aplicação dos princípios da <strong>Gestalt</strong> em interfaces digitais, quando botões ou cartões de informação são posicionados <strong>perto uns dos outros</strong> com um espaço maior separando-os de outros blocos, o usuário os percebe automaticamente como pertencentes ao mesmo grupo funcional. Esse princípio é denominado:</p>", "options": ["Fechamento.", "Proximidade.", "Continuidade.", "Figura e Fundo.", "Contraste Cromático."], "answer": 1, "explain": "<strong>Molde 3:</strong> Elementos posicionados <strong>perto uns dos outros</strong> são agrupados pelo princípio da <strong>Proximidade</strong>.", "area": "design"}, {"num": 22, "stemHtml": "<p>Sobre Tipografia e Experiência do Usuário (UX), analise as afirmativas:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Conceito</th><th>Afirmação</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>Fontes Script</strong></td><td>Reproduzem a escrita manual humana com traço elegante e tradicional, muito usadas em convites formais.</td></tr><tr><td><strong>II.</strong></td><td><strong>Serviços de Fontes Web</strong></td><td>Google Fonts e Adobe Fonts permitem incorporar fontes personalizadas em sites e aplicativos.</td></tr><tr><td><strong>III.</strong></td><td><strong>Equivalência com o Mundo Real</strong></td><td>Heurística de Nielsen que orienta o sistema a falar a linguagem e seguir o modelo mental do usuário em vez de jargões técnicos internos.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas II e III estão corretas.", "somente a afirmativa III está correta.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "<strong>Molde 1:</strong> Todas corretas: Fontes Script, Google/Adobe Fonts e Equivalência com o mundo real (Nielsen).", "area": "design"}, {"num": 23, "stemHtml": "<p>Sobre as tecnologias fundamentais da Web e a semântica no HTML5, analise as afirmativas:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Tecnologia</th><th>Função</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>HTML5, CSS3 e JavaScript</strong></td><td>HTML define a estrutura/conteúdo; CSS define a estilização visual; JavaScript adiciona comportamento e interatividade via DOM.</td></tr><tr><td><strong>II.</strong></td><td><strong>Tags Semânticas HTML5</strong></td><td>Elementos como <code>&lt;nav&gt;</code>, <code>&lt;header&gt;</code>, <code>&lt;footer&gt;</code> e <code>&lt;section&gt;</code> delimitam semanticamente áreas da página web.</td></tr><tr><td><strong>III.</strong></td><td><strong>Atributo <code>target=\"_blank\"</code></strong></td><td>Quando usado na tag <code>&lt;a&gt;</code>, força o fechamento imediato do navegador e envia um cookie para a nuvem.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas II e III estão corretas.", "somente a afirmativa III está correta.", "as afirmativas I, II e III estão corretas."], "answer": 1, "explain": "<strong>Molde 1:</strong> I e II corretas. <strong>III é falsa</strong> (<code>_blank</code> apenas abre o link em nova aba; não fecha navegador nem envia cookie para nuvem!).", "area": "web_redes"}, {"num": 24, "stemHtml": "<p>Na construção de tabelas e formulários em HTML5, analise a tabela a seguir:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Elemento / Método</th><th>Descrição</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>Tag <code>&lt;tr&gt;</code> em Tabelas</strong></td><td>Representa uma célula de dado individual dentro de uma tabela, equivalente à coluna de um registro.</td></tr><tr><td><strong>II.</strong></td><td><strong>Método <code>GET</code> em Formulários</strong></td><td>Envia os dados preenchidos anexados de forma visível na URL (<em>QueryString</em>), sendo comum em formulários de busca.</td></tr><tr><td><strong>III.</strong></td><td><strong>Método <code>POST</code> em Formulários</strong></td><td>Envia os dados no corpo da requisição HTTP, sem expô-los diretamente na barra de endereço, indicado para cadastros e senhas.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente a afirmativa II está correta.", "somente as afirmativas II e III estão corretas.", "somente as afirmativas I e III estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 2, "explain": "<strong>Molde 1:</strong> II (<code>GET</code> na URL) e III (<code>POST</code> no corpo) corretas. <strong>I é falsa:</strong> <code>&lt;tr&gt;</code> é <strong>linha</strong> (<em>table row</em>), enquanto célula de dado é <code>&lt;td&gt;</code> (<em>table data</em>)!", "area": "web_redes"}, {"num": 25, "stemHtml": "<p>No modelo de caixas (<em>Box Model</em>) do CSS3, toda caixa HTML é composta, de dentro para fora, por conteúdo, preenchimento interno, borda e margem externa. As propriedades CSS que definem, respectivamente, o <strong>espaçamento interno</strong> (entre o texto/conteúdo e a borda) e o <strong>espaçamento externo</strong> (entre a borda do elemento e os elementos vizinhos) são:</p>", "options": ["<code>margin</code> e <code>padding</code>.", "<code>padding</code> e <code>margin</code>.", "<code>border</code> e <code>outline</code>.", "<code>float</code> e <code>display</code>.", "<code>scale</code> e <code>translate</code>."], "answer": 1, "explain": "<strong>Molde 3:</strong> Espaçamento interno = <strong><code>padding</code></strong>; espaçamento externo = <strong><code>margin</code></strong>.", "area": "web_redes"}, {"num": 26, "stemHtml": "<p>Sobre Computação em Nuvem (<em>Cloud Computing</em>) e Contêineres, analise os itens:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Modelo / Tecnologia</th><th>Definição</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td>*<em>IaaS (</em>Infraestrutura como Serviço<em>)</em>*</td><td>Disponibiliza máquinas virtuais, armazenamento e redes virtuais, cabendo ao cliente gerenciar sistema operacional e aplicações.</td></tr><tr><td><strong>II.</strong></td><td>*<em>SaaS (</em>Software como Serviço<em>)</em>*</td><td>Entrega aplicativos prontos para uso final direto pelo navegador (como webmails e suítes online), sem exigir instalação ou gestão de servidores pelo usuário.</td></tr><tr><td><strong>III.</strong></td><td><strong>Contêineres</strong></td><td>Empacotam aplicações e dependências garantindo <strong>isolamento</strong> e portabilidade entre ambientes de desenvolvimento e produção.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas II e III estão corretas.", "somente a afirmativa III está correta.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "<strong>Molde 1:</strong> Todas corretas: IaaS, SaaS e isolamento em Contêineres.", "area": "web_redes"}, {"num": 27, "stemHtml": "<p>Um notebook moderno utiliza <code>16 GB</code> de memória <strong>RAM DDR4</strong> e um <strong>SSD de 512 GB</strong> para armazenar arquivos. Sabendo que 1 byte tem 8 bits e o maior número representável em 1 byte sem sinal é <code>255</code>, assinale a alternativa correta sobre hardware e sistema binário:</p>", "options": ["A memória RAM é não-volátil e <code>255</code> em binário vale <code>10000001</code>.", "O SSD utiliza chips de memória flash sem partes mecânicas (não-volátil), a RAM é volátil e <code>255</code> em binário vale <code>11111111</code>.", "O SSD usa discos magnéticos giratórios mais lentos e <code>255</code> em binário vale <code>10101010</code>.", "A memória RAM preserva todos os programas abertos mesmo após desligar a tomada, e <code>1 byte</code> possui <code>4 bits</code>.", "O sistema operacional usa o Gerenciamento de Arquivos para alocar diretamente os bits na memória Cache L1."], "answer": 1, "explain": "<strong>Molde 3/4:</strong> SSD usa chips flash não-voláteis sem partes mecânicas; RAM é volátil; <code>255</code> = <code>11111111</code> (8 bits).", "area": "web_redes"}, {"num": 28, "stemHtml": "<p>Um estudante precisa identificar os diretórios padrão reais da hierarquia de arquivos do sistema operacional <strong>Linux</strong> sem confundir com comandos executados no terminal. Assinale a alternativa que apresenta <strong>apenas</strong> diretórios padrão válidos do Linux:</p>", "options": ["<code>/bin</code>, <code>/etc</code>, <code>/mkdir</code>, <code>/lib</code>, <code>/usr</code>, <code>/var</code> e <code>/tmp</code>.", "<code>/bin</code>, <code>/etc</code>, <code>/home</code>, <code>/ls</code>, <code>/usr</code>, <code>/var</code> e <code>/cat</code>.", "<code>/bin</code>, <code>/etc</code>, <code>/home</code>, <code>/lib</code>, <code>/usr</code>, <code>/var</code> e <code>/tmp</code>.", "<code>/apt</code>, <code>/etc</code>, <code>/home</code>, <code>/lib</code>, <code>/usr</code>, <code>/cp</code> e <code>/tmp</code>.", "<code>/bin</code>, <code>/shutdown</code>, <code>/home</code>, <code>/lib</code>, <code>/pwd</code>, <code>/var</code> e <code>/tmp</code>."], "answer": 2, "explain": "<strong>Molde 2:</strong> Diretórios reais do Linux: <code>/bin, /etc, /home, /lib, /usr, /var, /tmp</code>. Intrusos (comandos): <code>/mkdir</code>, <code>/ls</code>, <code>/cat</code>, <code>/apt</code>, <code>/cp</code>, <code>/shutdown</code>, <code>/pwd</code>.", "area": "web_redes"}, {"num": 29, "stemHtml": "<p>Sobre redes de computadores, topologias e protocolos de comunicação, analise os itens:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Conceito</th><th>Afirmação</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>Camadas do TCP/IP</strong></td><td>O modelo TCP/IP possui quatro camadas: Link (Acesso à Rede), Internet, Transporte e Aplicação.</td></tr><tr><td><strong>II.</strong></td><td>*<em>Topologia em Estrela (</em>Star<em>)</em>*</td><td>Todas as estações conectam-se a uma unidade central inteligente (<em>switch</em>) que distribui o tráfego com eficiência.</td></tr><tr><td><strong>III.</strong></td><td><strong>Protocolo SMTP vs. IMAP</strong></td><td>SMTP envia mensagens de e-mail; IMAP permite acessar e sincronizar mensagens diretamente no servidor entre múltiplos dispositivos.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas II e III estão corretas.", "somente a afirmativa III está correta.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "<strong>Molde 1:</strong> Todas corretas: 4 camadas TCP/IP, Topologia Estrela (<em>switch</em>) e SMTP (envio) vs. IMAP (sincronização no servidor).", "area": "web_redes"}, {"num": 30, "stemHtml": "<p><em>(Inspirada diretamente nas questões comuns aplicadas pela Fundação FAT em outros cursos no mesmo dia!)</em> No uso cotidiano do Windows e de processadores de texto como o Microsoft Word (Office 365), analise os recursos de produtividade:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Recurso</th><th>Descrição</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>Área de Transferência (<code>Ctrl+C</code> / <code>Ctrl+X</code> / <code>Ctrl+V</code>)</strong></td><td>Armazena temporariamente textos, imagens ou arquivos copiados (<code>Ctrl+C</code>) ou recortados (<code>Ctrl+X</code>) para serem colados (<code>Ctrl+V</code>) em outro local.</td></tr><tr><td><strong>II.</strong></td><td><strong>Comentários e Controlar Alterações (Word)</strong></td><td>Permitem adicionar observações de revisão no texto e registrar todas as modificações para que sejam aceitas ou rejeitadas posteriormente.</td></tr><tr><td><strong>III.</strong></td><td><strong>Marcadores e Numeração (Word)</strong></td><td>Ferramentas usadas para organizar listas não ordenadas com símbolos e listas ordenadas com números ou letras.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas II e III estão corretas.", "somente a afirmativa III está correta.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "<strong>Molde 1:</strong> Todas corretas (combinando questões reais de Windows e Word aplicadas pela própria FAT em Dez/2024!).", "area": "web_redes"}]}, "sim1": {"id": "sim1", "title": "Simulado Inédito FAT #1 — Núcleo Principal", "badge": "Inédito • 30 Questões", "desc": "Simulado completo no padrão exato da prova 2025 com tabelas I, II, III e listas com intruso.", "minutes": 120, "questions": [{"num": 1, "stemHtml": "<blockquote class='q-quote'><strong>Why Troubleshooting Matters in Software Teams</strong><br><br>In modern IT teams, troubleshooting is more than simply restarting a server. It requires systematic analysis, checking logs, reproducing bugs, and isolating root causes before deploying a fix. Junior developers who document their findings help reduce downtime and improve team outcomes. Rather than guessing randomly, effective professionals rely on evidence and clear communication with peers to prevent recurring failures.</blockquote>\n<p>De acordo com o texto, a prática eficaz de <em>troubleshooting</em> em equipes de TI baseia-se em</p>", "options": ["reiniciar servidores aleatoriamente até que o sistema volte a responder.", "análise sistemática, isolamento da causa raiz e uso de evidências.", "evitar a documentação de descobertas para acelerar entregas imediatas.", "adivinhação intuitiva sem comunicação com os colegas de equipe.", "substituição definitiva de desenvolvedores juniores por sistemas automáticos."], "answer": 1, "explain": "O texto diz que <em>troubleshooting</em> requer <em>systematic analysis, checking logs, reproducing bugs, and isolating root causes</em> além de <em>rely on evidence</em>. (A), (C), (D) e (E) contradizem o texto.", "area": "ingles_etica"}, {"num": 2, "stemHtml": "<blockquote class='q-quote'><strong>Why Troubleshooting Matters in Software Teams</strong><br><br>In modern IT teams, troubleshooting is more than simply restarting a server. It requires systematic analysis, checking logs, reproducing bugs, and isolating root causes before deploying a fix. Junior developers who document their findings help reduce downtime and improve team outcomes. Rather than guessing randomly, effective professionals rely on evidence and clear communication with peers to prevent recurring failures.</blockquote>\n<p>No texto, a expressão <em>relying on evidence</em> e o termo <em>downtime</em> podem ser compreendidos, respectivamente, como</p>", "options": ["descartar provas e tempo de subida de código.", "criar suposições e aumento de produtividade.", "basear-se em evidências e tempo de inatividade do sistema.", "ignorar dados históricos e manutenção preventiva.", "memorizar comandos e velocidade de processamento."], "answer": 2, "explain": "<em>Relying on evidence</em> = baseando-se em evidências; <em>downtime</em> = tempo em que o sistema fica fora do ar (inatividade).", "area": "ingles_etica"}, {"num": 3, "stemHtml": "<p>Em um diagrama técnico em inglês sobre engenharia de software, aparecem os seguintes passos: 1. <em>Gathering user requirements</em>; 2. <em>Analyzing data flows</em>; 3. <em>Inference of bottlenecks</em>; 4. <em>Testing expected outcomes</em>. A tradução correta dos termos destacados em <strong>data</strong>, <strong>inference</strong> e <strong>outcomes</strong> é, respectivamente:</p>", "options": ["datas, interferência e saídas de áudio.", "dados, inferência e resultados.", "datas, conclusão e exclusões.", "algoritmos, interface e entradas.", "arquivos, interferência e tarefas."], "answer": 1, "explain": "<em>Data</em> é falso cognato — significa <strong>dados</strong> (nunca \"datas\"); <em>inference</em> = inferência/conclusão; <em>outcomes</em> = resultados.", "area": "ingles_etica"}, {"num": 4, "stemHtml": "<p>A atuação ética voltada para o bem comum exige que decisões individuais ou organizacionais priorizem benefícios coletivos legítimos acima de interesses puramente egoístas ou promocionais. Qual situação representa uma ação orientada para o bem comum?</p>", "options": ["Um estudante compartilha apostilas gratuitas da escola apenas para conseguir seguidores e monetizar seu perfil.", "Uma empresa cria um ponto de coleta e reciclagem de lixo eletrônico aberto à comunidade do bairro, sem exigir compra de produtos.", "Um colaborador entrega o projeto do colega como se fosse seu para conquistar uma bonificação salarial.", "Um técnico instala softwares piratas em computadores públicos para reduzir os gastos pessoais de sua oficina.", "Uma loja divulga uma campanha social fictícia para atrair clientes durante a semana de liquidação."], "answer": 1, "explain": "Coleta gratuita de lixo eletrônico para a comunidade sem ganho próprio. As demais envolvem vaidade em rede social (A), fraude/plágio (C), pirataria (D) ou propaganda enganosa (E).", "area": "ingles_etica"}, {"num": 5, "stemHtml": "<p>Nas relações trabalhistas e de consumo no setor de tecnologia, qual conduta reflete responsabilidade ética e socioambiental?</p>", "options": ["Coletar dados biométricos de clientes sem autorização para vendê-los a corretoras de anúncios.", "Exigir jornadas diárias não remuneradas de estagiários sob ameaça de desligamento imediato.", "Projetar sistemas acessíveis a pessoas com deficiência e respeitar os direitos trabalhistas e a jornada legal da equipe.", "Ocultar defeitos conhecidos de hardware durante a garantia para evitar custos de substituição.", "Incentivar a obsolescência programada descartando equipamentos funcionais em aterros comuns."], "answer": 2, "explain": "Acessibilidade e respeito às leis trabalhistas. As outras violam privacidade (A), direitos trabalhistas (B), defesa do consumidor (D) e meio ambiente (E).", "area": "ingles_etica"}, {"num": 6, "stemHtml": "<p>No âmbito do direito constitucional e da legislação ambiental aplicados à infraestrutura de TI, representa uma prática ética e legal:</p>", "options": ["Instalar servidores em área de preservação permanente sem licenciamento ambiental para economizar energia de refrigeração.", "Despejar baterias de nobreaks usados diretamente na rede de esgoto municipal para agilizar a limpeza do data center.", "Realizar estudo prévio de impacto ambiental e garantir destinação correta de resíduos eletrônicos conforme a legislação vigente.", "Reduzir a transparência pública impedindo moradores locais de opinar sobre obras de torres de telecomunicação.", "Contratar fornecedores sem exigência de conformidade legal trabalhista ou ambiental para baratear o projeto."], "answer": 2, "explain": "Estudo de impacto ambiental + descarte legal. As demais agridem leis ambientais e participação comunitária.", "area": "ingles_etica"}, {"num": 7, "stemHtml": "<p>Frameworks aceleram o desenvolvimento de aplicações web e móveis ao fornecer estruturas padronizadas e bibliotecas prontas. Assinale a alternativa que apresenta <strong>apenas</strong> exemplos válidos de <em>frameworks</em>:</p>", "options": ["Laravel (PHP), Bootstrap (Interface de Usuário), Creative Commons (Licenciamento) e Angular (JavaScript).", "Django (Python), React Native (Aplicativos Móveis), Spring Boot (Java) e Bootstrap (Interface de Usuário).", "Laravel (PHP), Notepad++ (Editor de Texto), Angular (JavaScript) e Adobe Creative Cloud (Multimídia).", "React Native (Interface de Usuário), Bootstrap (Aplicativos Móveis), Laravel (Banco de Dados) e Angular (PHP).", "Express (Node.js), MySQL Workbench (SGBD), Django (Python) e MongoDB (NoSQL)."], "answer": 1, "explain": "Django, React Native, Spring Boot e Bootstrap são frameworks. Intrusos nas demais: <em>Creative Commons</em> (licença) em A; <em>Notepad++</em> (editor) e <em>Adobe Creative Cloud</em> (design) em C; descrições trocadas em D; <em>MySQL Workbench</em> e <em>MongoDB</em> em E.", "area": "prog"}, {"num": 8, "stemHtml": "<p>Sobre conversão de tipos de dados (<em>Type Conversion</em>) em linguagens de programação, analise as afirmativas:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Conceito</th><th>Descrição</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td>*<em>Conversão Implícita (</em>Type Coercion<em>)</em>*</td><td>Ocorre automaticamente pelo compilador ou interpretador quando os tipos são compatíveis e não há perda de informação, como passar de <code>int</code> para <code>float</code>.</td></tr><tr><td><strong>II.</strong></td><td><strong>Conversão Estrutural</strong></td><td>Realizada automaticamente pelo hardware da placa-mãe sempre que um algoritmo possui matrizes bidimensionais.</td></tr><tr><td><strong>III.</strong></td><td>*<em>Conversão Explícita (</em>Casting<em>)</em>*</td><td>Forçada manualmente pelo programador por meio de funções ou operadores de conversão, como <code>int(\"42\")</code> ou <code>str(10)</code>.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente a afirmativa II está correta.", "somente as afirmativas I e III estão corretas.", "somente as afirmativas II e III estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 2, "explain": "I (Implícita) e III (Explícita/Casting) verdadeiras. II é falsa porque <em>\"Conversão Normal\"</em> / <em>\"Conversão Estrutural\"</em> automática por placa-mãe não existe.", "area": "prog"}, {"num": 9, "stemHtml": "<p>Durante a verificação manual de um algoritmo sem o auxílio do computador, o programador monta uma grade com os nomes das variáveis nas colunas e acompanha cada comando do código registrando as mudanças de estado. A técnica e a ação central descritas são, respectivamente:</p>", "options": ["Compilação e Otimização de Memória.", "Teste de Mesa e Executar Linha a Linha.", "Bundling e Minificação de Código.", "Normalização e Derivação Lógica.", "Rasterização e Vetorização de Fluxo."], "answer": 1, "explain": "A técnica é <strong>Teste de Mesa</strong> e o ato de percorrer o código anotando cada variável é <strong>Executar Linha a Linha</strong>.", "area": "prog"}, {"num": 10, "stemHtml": "<p>Observe o algoritmo abaixo e a matriz bidimensional <code>A</code> de 3 linhas e 3 colunas (índices iniciando em <code>0</code>):</p>\n<pre class='q-code'>A = [ [4, 2, 9],\n      [7, 5, 1],\n      [3, 8, 6] ]\nsoma = A[0][0] + A[1][1] + A[2][2]</pre>\n<p>Qual o valor final da variável <code>soma</code>, que representa a <strong>diagonal principal</strong> da matriz <code>A</code>, e qual seria o valor caso alguém somasse por engano a <strong>diagonal secundária</strong> (<code>A[0][2] + A[1][1] + A[2][0]</code>)?</p>", "options": ["Diagonal principal = 15; Diagonal secundária = 17.", "Diagonal principal = 17; Diagonal secundária = 15.", "Diagonal principal = 12; Diagonal secundária = 15.", "Diagonal principal = 15; Diagonal secundária = 12.", "Diagonal principal = 14; Diagonal secundária = 16."], "answer": 0, "explain": "Diagonal principal: <code>A[0][0] + A[1][1] + A[2][2] = 4 + 5 + 6 = 15</code>. Diagonal secundária: <code>A[0][2] + A[1][1] + A[2][0] = 9 + 5 + 3 = 17</code>.", "area": "prog"}, {"num": 11, "stemHtml": "<p>Analise a tabela com ferramentas utilizadas na construção de páginas Web e sistemas:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Categoria</th><th>Características</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>Editores de Código</strong></td><td>Ferramentas como Visual Studio Code e Sublime Text que oferecem destaque de sintaxe, autocompletar e extensões.</td></tr><tr><td><strong>II.</strong></td><td><strong>Editores WYSIWYG</strong></td><td>Ambientes visuais como Wix e Dreamweaver nos quais o usuário monta a tela arrastando e soltando elementos visuais.</td></tr><tr><td><strong>III.</strong></td><td><strong>IDEs (Ambientes Integrados)</strong></td><td>Editores simples de texto puro sem recursos avançados, como o Bloco de Notas (Notepad) do Windows e o TextEdit do Mac.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas I e III estão corretas.", "somente as afirmativas II e III estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 1, "explain": "I e II corretas. <strong>III é falsa:</strong> Notepad e TextEdit são editores de texto básicos sem recursos avançados, <strong>não</strong> são IDEs.", "area": "prog"}, {"num": 12, "stemHtml": "<p>Sobre ferramentas de <em>build</em>, <em>bundling</em> e licenciamento de software, analise as afirmativas:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Tema</th><th>Afirmação</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td>*<em>Ferramentas de </em>Build***</td><td>Automatizam compilação, execução de testes automatizados e preparação de pacotes para produção.</td></tr><tr><td><strong>II.</strong></td><td>*<em>Ferramentas de </em>Bundling***</td><td>Empacotam múltiplos arquivos (JS, CSS, imagens) em menos pacotes para reduzir requisições HTTP e acelerar o carregamento.</td></tr><tr><td><strong>III.</strong></td><td>*<em>Licença </em>Open Source***</td><td>Disponibiliza o código-fonte permitindo modificação e redistribuição sob condições que promovem colaboração e transparência.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente a afirmativa II está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas II e III estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "I, II e III estão rigorosamente corretas conforme definições oficiais.", "area": "prog"}, {"num": 13, "stemHtml": "<p>Um candidato analisou o seguinte quadro sobre sublinguagens SQL:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Sublinguagem</th><th>Função e Comandos</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td>*<em>DDL (</em>Data Definition Language<em>)</em>*</td><td>Responsável por consultar e recuperar registros armazenados nas tabelas usando a instrução <code>SELECT</code>.</td></tr><tr><td><strong>II.</strong></td><td>*<em>DML (</em>Data Manipulation Language<em>)</em>*</td><td>Responsável por inserir, atualizar e apagar dados nas tabelas por meio de <code>INSERT</code>, <code>UPDATE</code> e <code>DELETE</code>.</td></tr><tr><td><strong>III.</strong></td><td>*<em>DQL (</em>Data Query Language<em>)</em>*</td><td>Responsável por criar, alterar e excluir a estrutura de tabelas e bancos usando <code>CREATE</code>, <code>ALTER</code> e <code>DROP</code>.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente a afirmativa II está correta.", "somente a afirmativa III está correta.", "somente as afirmativas I e III estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 1, "explain": "<strong>Pegadinha clássica de inversão!</strong> O item I atribuiu <code>SELECT</code> a DDL (falso, isso é DQL) e o item III atribuiu <code>CREATE/ALTER/DROP</code> a DQL (falso, isso é DDL). Apenas II (DML) está certa.", "area": "bd"}, {"num": 14, "stemHtml": "<p>Sobre os componentes fundamentais do Modelo Relacional em bancos de dados, analise os itens:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Elemento</th><th>Definição</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>Tuplas e Atributos</strong></td><td>Em uma tabela relacional, cada linha é chamada de tupla (registro) e cada coluna representa um atributo (campo).</td></tr><tr><td><strong>II.</strong></td><td><strong>Chave Primária (PK)</strong></td><td>Atributo ou conjunto de atributos que identifica unicamente cada registro de uma tabela.</td></tr><tr><td><strong>III.</strong></td><td><strong>Chave Estrangeira (FK)</strong></td><td>Coluna que referencia a chave primária de outra tabela para garantir integridade referencial entre relacionamentos.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas II e III estão corretas.", "somente as afirmativas I e III estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "Tuplas (linhas) / atributos (colunas), PK e FK estão todos corretos.", "area": "bd"}, {"num": 15, "stemHtml": "<p>Uma tabela <code>Alunos</code> possui uma coluna chamada <code>telefones</code> onde foi gravado <code>\"1199999-1111, 1198888-2222\"</code> em uma mesma célula para o aluno Carlos. Ao aplicar o processo de normalização para garantir que todos os atributos contenham <strong>apenas valores atômicos (indivisíveis)</strong> e eliminar colunas com conjuntos repetidos de dados, aplica-se a:</p>", "options": ["Primeira Forma Normal (1FN).", "Segunda Forma Normal (2FN).", "Terceira Forma Normal (3FN).", "Quarta Forma Normal (4FN).", "Forma Normal de Boyce-Codd (BCNF)."], "answer": 0, "explain": "Garantir valores <strong>atômicos (indivisíveis)</strong> e sem múltiplos telefones na mesma célula é a regra da <strong>1ª Forma Normal (1FN)</strong>.", "area": "bd"}, {"num": 16, "stemHtml": "<p>Em um sistema escolar com uma tabela <code>alunos</code> contendo as colunas <code>id</code>, <code>nome</code>, <code>curso</code> e <code>turno</code>, qual instrução SQL DQL retorna corretamente a quantidade total de alunos matriculados no turno <code>'Noturno'</code>?</p>", "options": ["<code>SELECT * FROM alunos WHERE COUNT(turno) = 'Noturno';</code>", "<code>SELECT COUNT(*) WHERE alunos FROM turno = 'Noturno';</code>", "<code>SELECT COUNT('Noturno') FROM alunos WHERE turno;</code>", "<code>SELECT COUNT(*) FROM alunos WHERE turno = 'Noturno';</code>", "<code>SELECT alunos FROM COUNT(*) WHERE turno = 'Noturno';</code>"], "answer": 3, "explain": "<code>SELECT COUNT(*) FROM alunos WHERE turno = 'Noturno';</code>. As opções A e E usam <code>COUNT</code> no lugar errado; B inverte <code>WHERE</code> e <code>FROM</code>; C passa texto fixo no <code>COUNT</code> e deixa o <code>WHERE</code> incompleto.", "area": "bd"}, {"num": 17, "stemHtml": "<p>Analise as afirmações sobre linguagens e ferramentas de Banco de Dados:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Tema</th><th>Afirmação</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>Cardinalidades</strong></td><td>Tabelas relacionais podem relacionar-se nas formas Um-para-Um (<code>1:1</code>), Um-para-Muitos (<code>1:N</code>) e Muitos-para-Muitos (<code>N:N</code>).</td></tr><tr><td><strong>II.</strong></td><td><strong>Cláusula <code>WHERE</code></strong></td><td>No comando <code>SELECT</code>, permite filtrar os resultados de acordo com condições lógicas específicas.</td></tr><tr><td><strong>III.</strong></td><td><strong>Bancos NoSQL</strong></td><td>Sistemas como MongoDB e Cassandra são projetados para dados não estruturados ou semiestruturados.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente a afirmativa II está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas II e III estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "Cardinalidades (1:1, 1:N, N:N), cláusula <code>WHERE</code> e bancos NoSQL (MongoDB e Cassandra) — todas corretas.", "area": "bd"}, {"num": 18, "stemHtml": "<p>Assinale a alternativa que contém <strong>exclusivamente</strong> padrões de representação de cores válidos no Design Digital e Desenvolvimento Web:</p>", "options": ["RGB, CMYK e CSS.", "CMYK, Hexadecimal e Primária.", "RGB, CMYK e Hexadecimal.", "RGB, Hexadecimal e PNG.", "SVG, CMYK e RGB."], "answer": 2, "explain": "Padrões de cores válidos: <strong>RGB, CMYK e Hexadecimal</strong>. Intrusos nas outras: <em>CSS</em>, <em>Primária</em>, <em>PNG</em>, <em>SVG</em>.", "area": "design"}, {"num": 19, "stemHtml": "<p>Um logotipo criado no formato <strong>SVG</strong> foi ampliado em <code>800%</code> para um painel de eventos e permaneceu perfeitamente nítido, enquanto uma foto <strong>JPEG</strong> sofreu serrilhamento visível nos pixels. Assinale a alternativa que apresenta <strong>apenas</strong> formatos de imagem <strong>vetoriais</strong>:</p>", "options": ["SVG e PNG.", "PDF e JPEG.", "BMP e PNG.", "SVG e PDF.", "JPEG, PNG e BMP."], "answer": 3, "explain": "<strong>SVG</strong> e <strong>PDF</strong> suportam vetores. <strong>PNG, JPEG e BMP</strong> são formatos bitmap/raster (pixels).", "area": "design"}, {"num": 20, "stemHtml": "<p>Sobre o uso de Bancos de Imagens em projetos digitais, analise os itens:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Aspecto</th><th>Descrição</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>Licenciamento</strong></td><td>Define permissões de uso comercial ou pessoal, gratuitos ou pagos, conforme os termos de cada obra.</td></tr><tr><td><strong>II.</strong></td><td><strong>Qualidade e Resolução</strong></td><td>Permite escolher arquivos adequados tanto para exibição digital em telas quanto para impressão gráfica.</td></tr><tr><td><strong>III.</strong></td><td><strong>Rasterização Automática</strong></td><td>Obriga que todas as imagens baixadas sejam convertidas exclusivamente em código-fonte HTML antes do download.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas II e III estão corretas.", "somente a afirmativa III está correta.", "as afirmativas I, II e III estão corretas."], "answer": 1, "explain": "I e II corretas. <strong>III é falsa:</strong> bancos de imagens não convertem imagens em código HTML antes do download.", "area": "design"}, {"num": 21, "stemHtml": "<p>Na psicologia da percepção aplicada ao design (<em>Gestalt</em>), quando o cérebro humano completa mentalmente linhas interrompidas ou espaços vazios para enxergar uma figura inteira (como um círculo desenhado com traços pontilhados), manifesta-se o princípio do(a):</p>", "options": ["Proximidade.", "Semelhança.", "Continuidade.", "Fechamento.", "Figura e Fundo."], "answer": 3, "explain": "Completar mentalmente formas com lacunas abertas é o princípio do <strong>Fechamento</strong>.", "area": "design"}, {"num": 22, "stemHtml": "<p>Em uma página HTML, o desenvolvedor inseriu o código <code>&lt;a href=\"https://etec.sp.gov.br\" target=\"___\"&gt;Site da Etec&lt;/a&gt;</code> desejando que o portal abra em uma <strong>nova aba</strong> sem fechar a página atual. Qual valor deve substituir <code>___</code>?</p>", "options": ["<code>_self</code>", "<code>_top</code>", "<code>_blank</code>", "<code>_parent</code>", "<code>_none</code>"], "answer": 2, "explain": "Para abrir em nova aba ou janela usa-se <code>target=\"_blank\"</code>. (<code>_self</code> abre na mesma aba; <code>_none</code> não existe).", "area": "web_redes"}, {"num": 23, "stemHtml": "<p>Um estudante avaliou três afirmações sobre o funcionamento de <strong>Cookies</strong> em navegadores Web:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Propriedade</th><th>Afirmação</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>Local de Armazenamento</strong></td><td>Cookies são arquivos armazenados exclusivamente na nuvem do provedor de hospedagem, nunca no computador do usuário.</td></tr><tr><td><strong>II.</strong></td><td><strong>Tamanho Máximo</strong></td><td>Cada cookie tem tamanho reduzido, limitado a cerca de 4 KB.</td></tr><tr><td><strong>III.</strong></td><td><strong>Tempo de Vida</strong></td><td>Podem ser de sessão (excluídos ao fechar o navegador) ou permanentes (expiram em data definida ou quando removidos).</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas II e III estão corretas.", "somente a afirmativa III está correta.", "as afirmativas I, II e III estão corretas."], "answer": 2, "explain": "II e III corretas. <strong>I é falsa:</strong> cookies são armazenados localmente <strong>no navegador do usuário</strong>, jamais na nuvem.", "area": "web_redes"}, {"num": 24, "stemHtml": "<p>Sobre os protocolos de correio eletrônico (e-mail), analise o quadro a seguir:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Protocolo</th><th>Função</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>SMTP</strong></td><td>Responsável por baixar os e-mails para leitura local, excluindo as mensagens do servidor após a transferência.</td></tr><tr><td><strong>II.</strong></td><td><strong>POP3</strong></td><td>Responsável pelo envio de mensagens de e-mail de um cliente para o servidor e entre servidores.</td></tr><tr><td><strong>III.</strong></td><td><strong>IMAP</strong></td><td>Permite acessar e gerenciar os e-mails diretamente no servidor, mantendo as caixas sincronizadas entre vários dispositivos.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente a afirmativa II está correta.", "somente a afirmativa III está correta.", "somente as afirmativas I e II estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 2, "explain": "<strong>Inversão clássica:</strong> I colocou a definição do POP3 no SMTP; II colocou a definição do SMTP no POP3. Apenas III (IMAP sincronizando no servidor) está correta.", "area": "web_redes"}, {"num": 25, "stemHtml": "<p>Um laboratório de informática montou uma rede local ligando 20 computadores em série a um <strong>único cabo coaxial central</strong>. O custo inicial foi baixo, porém, quando esse cabo principal se rompeu no meio da sala, todos os 20 computadores perderam comunicação imediatamente. A topologia descrita é:</p>", "options": ["Topologia em Estrela (<em>Star</em>).", "Topologia em Anel (<em>Ring</em>).", "Topologia em Malha (<em>Mesh</em>).", "Topologia em Barramento (<em>Bus</em>).", "Topologia Híbrida."], "answer": 3, "explain": "Cabo único central compartilhado cuja ruptura derruba toda a rede = *<em>Topologia em Barramento (</em>Bus<em>)</em>*.", "area": "web_redes"}, {"num": 26, "stemHtml": "<p>No modelo de comunicação de dados da Internet, qual protocolo fundamental encarrega-se de fragmentar os dados em pacotes na origem, roteá-los pela rede e reagrupá-los corretamente no destino?</p>", "options": ["HTTP", "DNS", "FTP", "TCP/IP", "SMTP"], "answer": 3, "explain": "Dividir em pacotes e rotear até o destino é o papel do <strong>TCP/IP</strong>.", "area": "web_redes"}, {"num": 27, "stemHtml": "<p>No funcionamento de um Sistema Operacional moderno, o módulo responsável por controlar a alocação e a liberação da memória RAM entre os diversos processos abertos simultaneamente denomina-se:</p>", "options": ["Gerenciamento de Arquivos.", "Gerenciamento de Memória.", "Gerenciamento de Entrada e Saída.", "Gerenciamento de Topologia.", "Interface de Linha de Comando."], "answer": 1, "explain": "Alocar e liberar memória RAM para programas = <strong>Gerenciamento de Memória</strong>.", "area": "web_redes"}, {"num": 28, "stemHtml": "<p>Assinale a alternativa que lista <strong>exclusivamente</strong> exemplos de navegadores (<em>browsers</em>) Web:</p>", "options": ["Google Chrome, Mozilla Firefox, Microsoft Edge e Telegram.", "Google Chrome, Apple Safari, Opera e Microsoft Edge.", "Mozilla Firefox, Messenger, Apple Safari e Opera.", "Capcut, Google Chrome, Microsoft Edge e Mozilla Firefox.", "Opera, Truecaller, Mozilla Firefox e Apple Safari."], "answer": 1, "explain": "Chrome, Safari, Opera e Edge são todos navegadores. Intrusos: <em>Telegram</em> (A), <em>Messenger</em> (C), <em>Capcut</em> (D), <em>Truecaller</em> (E).", "area": "web_redes"}, {"num": 29, "stemHtml": "<p>Sobre Internet das Coisas (<em>IoT</em>) e Suítes de Produtividade, analise as afirmativas:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Tema</th><th>Afirmação</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>IoT na Saúde e Indústria</strong></td><td>Utiliza sensores conectados em tempo real para manutenção preditiva de máquinas e monitoramento de pacientes.</td></tr><tr><td><strong>II.</strong></td><td><strong>IoT em Cidades Inteligentes</strong></td><td>Emprega dispositivos conectados para gerenciar tráfego urbano, iluminação pública e qualidade do ar.</td></tr><tr><td><strong>III.</strong></td><td><strong>Suítes de Produtividade</strong></td><td>Integram editor de texto, planilhas e apresentações permitindo colaboração em tempo real e acesso pela nuvem.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas II e III estão corretas.", "somente a afirmativa III está correta.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "Todas as três afirmativas sobre IoT e Suítes de Produtividade estão corretas.", "area": "web_redes"}, {"num": 30, "stemHtml": "<p>Para um projeto de design que exige o posicionamento visual de itens semelhantes em cor e formato para que o usuário perceba que pertencem ao mesmo menu de navegação, o designer aplica principalmente o princípio da Gestalt chamado:</p>", "options": ["Fechamento.", "Figura e Fundo.", "Semelhança.", "Continuidade.", "Simetria Oculta."], "answer": 2, "explain": "Agrupar elementos visualmente parecidos em cor/formato é o princípio da <strong>Semelhança</strong> (Gestalt).", "area": "design"}]}, "sim2": {"id": "sim2", "title": "Simulado Inédito FAT #2 — Tópicos Irmãos", "badge": "Inédito • 30 Questões", "desc": "Simulado cobrindo os tópicos irmãos de todo o 1º Módulo da Etec.", "minutes": 120, "questions": [{"num": 1, "stemHtml": "<p>Dadas as proposições lógicas <code>P = Verdadeiro</code> e <code>Q = Falso</code>, considere a tabela verdade dos operadores lógicos e analise as afirmações:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Expressão</th><th>Resultado Afirmado</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><code>P ∧ Q</code> (Conjunção / <code>AND</code>)</td><td>O resultado é <strong>Falso</strong>, pois na conjunção ambas as proposições precisam ser verdadeiras para retornar Verdadeiro.</td></tr><tr><td><strong>II.</strong></td><td><code>P ∨ Q</code> (Disjunção / <code>OR</code>)</td><td>O resultado é <strong>Verdadeiro</strong>, pois na disjunção basta que pelo menos uma proposição seja verdadeira.</td></tr><tr><td><strong>III.</strong></td><td><code>¬Q</code> (Negação / <code>NOT</code>)</td><td>O resultado é <strong>Falso</strong>, pois a negação mantém inalterado o valor lógico original de <code>Q</code>.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas II e III estão corretas.", "somente a afirmativa III está correta.", "as afirmativas I, II e III estão corretas."], "answer": 1, "explain": "I (<code>V ∧ F = F</code>) e II (<code>V ∨ F = V</code>) estão corretas. <strong>III é falsa</strong> porque a negação (<code>NOT / ¬</code>) <strong>inverte</strong> o valor (<code>¬F = V</code>), não o mantém inalterado.", "area": "prog"}, {"num": 2, "stemHtml": "<p>Considere o trecho em Portugol sabendo que <code>DIV</code> retorna o quociente inteiro da divisão e <code>MOD</code> retorna o resto inteiro:</p>\n<pre class='q-code'>a &lt;- 17\nb &lt;- a DIV 5\nc &lt;- a MOD 5\nr &lt;- (b * 10) + c</pre>\n<p>Ao realizar o teste de mesa linha a linha, quais são os valores finais de <code>b</code>, <code>c</code> e <code>r</code>, respectivamente?</p>", "options": ["<code>3</code>, <code>2</code> e <code>32</code>", "<code>2</code>, <code>3</code> e <code>23</code>", "<code>3</code>, <code>4</code> e <code>34</code>", "<code>3</code>, <code>5</code> e <code>35</code>", "<code>5</code>, <code>2</code> e <code>52</code>"], "answer": 0, "explain": "<code>b = 17 DIV 5 = 3</code> (quociente inteiro); <code>c = 17 MOD 5 = 2</code> (resto); <code>r = (3 * 10) + 2 = 32</code>.", "area": "prog"}, {"num": 3, "stemHtml": "<p>Em uma estrutura de dados do tipo *<em>Pilha (</em>Stack<em>)<strong>, baseada no princípio </strong>LIFO</em><em> (</em>Last In, First Out*), executa-se a seguinte sequência em uma pilha inicialmente vazia: <code>PUSH(12)</code> &rarr; <code>PUSH(8)</code> &rarr; <code>POP()</code> &rarr; <code>PUSH(25)</code> &rarr; <code>PUSH(4)</code> &rarr; <code>POP()</code> &rarr; <code>POP()</code>. Qual elemento permanece no topo da pilha após a última operação?</p>", "options": ["4", "25", "8", "12", "A pilha fica vazia."], "answer": 3, "explain": "Rastreando a Pilha: <code>[12]</code> &rarr; <code>[12, 8]</code> &rarr; POP <code>[12]</code> &rarr; <code>[12, 25]</code> &rarr; <code>[12, 25, 4]</code> &rarr; POP <code>[12, 25]</code> &rarr; POP <code>[12]</code>. Resta <strong>12</strong>.", "area": "prog"}, {"num": 4, "stemHtml": "<p>Uma função recursiva foi definida para calcular o fatorial de um número inteiro positivo <code>n</code> por meio da regra <code>fat(n) = n * fat(n - 1)</code>, com caso base <code>fat(0) = 1</code>. Qual valor será retornado pela chamada <code>fat(5)</code>?</p>", "options": ["24", "60", "120", "25", "720"], "answer": 2, "explain": "<code>5! = 5 × 4 × 3 × 2 × 1 = 120</code>.", "area": "prog"}, {"num": 5, "stemHtml": "<p>Analise as afirmações sobre tipos de dados primitivos e orientação a objetos:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Conceito</th><th>Afirmação</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>Tipo <code>boolean</code></strong></td><td>Armazena valores lógicos binários de verdadeiro (<code>true</code>) ou falso (<code>false</code>).</td></tr><tr><td><strong>II.</strong></td><td><strong>Tipo <code>char</code></strong></td><td>Armazena exclusivamente valores decimais com casas fracionárias, como <code>9.85</code>.</td></tr><tr><td><strong>III.</strong></td><td><strong>Pilares da POO</strong></td><td>Os quatro pilares da Programação Orientada a Objetos são Abstração, Encapsulamento, Herança e Polimorfismo.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas I e III estão corretas.", "somente as afirmativas II e III estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 2, "explain": "I (<code>boolean</code>) e III (4 pilares da POO: Abstração, Encapsulamento, Herança e Polimorfismo) corretas. <strong>II é falsa:</strong> <code>char</code> armazena um caractere, não números decimais (que são <code>float</code>/<code>double</code>).", "area": "prog"}, {"num": 6, "stemHtml": "<p>Em um sistema de controle de versões como o <strong>Git</strong>, as ações de <strong>(1) criar um caminho paralelo de desenvolvimento</strong>, <strong>(2) comparar diferenças entre versões</strong> e <strong>(3) unir alterações de um ramo em outro</strong> correspondem, respectivamente, aos termos:</p>", "options": ["<code>commit</code>, <code>push</code> e <code>clone</code>.", "<code>branch</code>, <code>diff</code> e <code>merge</code>.", "<code>merge</code>, <code>diff</code> e <code>branch</code>.", "<code>update</code>, <code>release</code> e <code>commit</code>.", "<code>fork</code>, <code>log</code> e <code>reset</code>."], "answer": 1, "explain": "Quebrar em ramo paralelo (<code>branch</code>), comparar diferenças (<code>diff</code>) e unir ramos (<code>merge</code>).", "area": "prog"}, {"num": 7, "stemHtml": "<p>Sobre Engenharia de Requisitos e Testes de Software, analise a tabela:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Conceito</th><th>Descrição</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>Requisito Funcional</strong></td><td>Define <strong>o que</strong> o sistema deve fazer, especificando funcionalidades, cálculos e serviços oferecidos ao usuário.</td></tr><tr><td><strong>II.</strong></td><td><strong>Requisito Não Funcional de Portabilidade</strong></td><td>Mede a facilidade com que o software pode ser transferido de um sistema computacional ou ambiente para outro permanecendo executável.</td></tr><tr><td><strong>III.</strong></td><td><strong>Teste de Unidade</strong></td><td>Verifica a menor unidade isolada de código-fonte (como uma função, método ou classe) para garantir que atende à especificação.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas II e III estão corretas.", "somente as afirmativas I e III estão corretas.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "Todas as três definições (RF, RNF de Portabilidade e Teste de Unidade) estão corretas.", "area": "prog"}, {"num": 8, "stemHtml": "<p>Assinale a alternativa que apresenta <strong>exclusivamente</strong> características desejáveis de <strong>bons requisitos</strong> de software:</p>", "options": ["Clareza, Ambiguidade, Consistência e Viabilidade.", "Clareza, Testabilidade, Consistência, Rastreabilidade e Viabilidade.", "Testabilidade, Inconsistência, Rastreabilidade e Clareza.", "Irrelevância, Viabilidade, Clareza e Testabilidade.", "Ambiguidade, Irrelevância, Inconsistência e Complexidade."], "answer": 1, "explain": "Bons requisitos devem ter Clareza, Testabilidade, Consistência, Rastreabilidade e Viabilidade. As demais incluem defeitos (<em>Ambiguidade, Inconsistência, Irrelevância</em>).", "area": "prog"}, {"num": 9, "stemHtml": "<p>Na gestão e modelagem de projetos de software, analise os itens:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Tema</th><th>Afirmação</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td>*<em>Modelo Cascata (</em>Waterfall<em>)</em>*</td><td>Segue as etapas sequenciais: Requerimento &rarr; Projeto &rarr; Construção &rarr; Teste/Depuração &rarr; Instalação &rarr; Manutenção.</td></tr><tr><td><strong>II.</strong></td><td><strong><em>Daily Scrum</em></strong></td><td>Reunião diária curta realizada dentro de uma <em>Sprint</em> para alinhar o progresso e identificar impedimentos da equipe.</td></tr><tr><td><strong>III.</strong></td><td><strong>Diagrama de Casos de Uso (UML)</strong></td><td>Representa graficamente as interações entre usuários (atores) e o sistema, evidenciando os requisitos funcionais.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas II e III estão corretas.", "somente a afirmativa III está correta.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "Cascata em ordem correta, <em>Daily Scrum</em> e Diagrama de Casos de Uso UML — todas corretas.", "area": "prog"}, {"num": 10, "stemHtml": "<p>No estudo de viabilidade de um sistema e na prática de <em>Extreme Programming</em> (XP), observe os itens abaixo:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Tema</th><th>Afirmação</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>Viabilidade Legal</strong></td><td>Analisa exclusivamente se os computadores atuais do cliente possuem memória RAM suficiente e se a equipe domina a linguagem escolhida.</td></tr><tr><td><strong>II.</strong></td><td><strong>Viabilidade Econômica</strong></td><td>Avalia custos operacionais, investimentos necessários e o retorno financeiro esperado (ROI) do projeto.</td></tr><tr><td><strong>III.</strong></td><td>*<em>Programação em Par (</em>Pair Programming<em>)</em>*</td><td>Duas pessoas programam juntas no mesmo código, alternando papéis e favorecendo o compartilhamento de conhecimento e detecção rápida de falhas.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas II e III estão corretas.", "somente a afirmativa III está correta.", "as afirmativas I, II e III estão corretas."], "answer": 2, "explain": "II e III corretas. <strong>I é falsa:</strong> hardware/RAM e domínio da linguagem pertencem à <strong>Viabilidade Técnica</strong>, não Legal!", "area": "prog"}, {"num": 11, "stemHtml": "<p>Assinale a alternativa que apresenta os comandos SQL correspondentes, na ordem exata, aos grupos <strong>DDL</strong>, <strong>DML</strong>, <strong>DQL</strong>, <strong>DCL</strong> e <strong>TCL</strong>:</p>", "options": ["<code>SELECT</code>, <code>CREATE</code>, <code>INSERT</code>, <code>COMMIT</code>, <code>GRANT</code>.", "<code>CREATE</code>, <code>INSERT</code>, <code>SELECT</code>, <code>GRANT</code>, <code>COMMIT</code>.", "<code>CREATE</code>, <code>SELECT</code>, <code>GRANT</code>, <code>INSERT</code>, <code>ROLLBACK</code>.", "<code>ALTER</code>, <code>DROP</code>, <code>UPDATE</code>, <code>REVOKE</code>, <code>SELECT</code>.", "<code>INSERT</code>, <code>CREATE</code>, <code>SELECT</code>, <code>REVOKE</code>, <code>COMMIT</code>."], "answer": 1, "explain": "DDL=<code>CREATE</code>, DML=<code>INSERT</code>, DQL=<code>SELECT</code>, DCL=<code>GRANT</code>, TCL=<code>COMMIT</code>.", "area": "bd"}, {"num": 12, "stemHtml": "<p>Sobre chaves, relacionamentos e formas normais em Bancos de Dados Relacionais, analise os itens:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Conceito</th><th>Afirmação</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>Chave Alternativa</strong></td><td>Quando existem várias chaves candidatas em uma tabela, uma é escolhida como chave primária e as demais são chamadas de chaves alternativas.</td></tr><tr><td><strong>II.</strong></td><td><strong>Relacionamento Recursivo</strong></td><td>Ocorre quando uma entidade se relaciona com ela mesma, podendo assumir cardinalidades como <code>1:N</code>, <code>N:1</code> ou <code>N:N</code>.</td></tr><tr><td><strong>III.</strong></td><td><strong>3ª Forma Normal (3FN)</strong></td><td>Garante que não existam dependências transitivas entre atributos não-chave em uma tabela já na 2FN.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas II e III estão corretas.", "somente a afirmativa III está correta.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "Chave Alternativa, Relacionamento Recursivo (1:N, N:1, N:N) e 3FN (elimina dependência transitiva) — todas corretas.", "area": "bd"}, {"num": 13, "stemHtml": "<p>Assinale a alternativa que contém <strong>apenas</strong> Sistemas Gerenciadores de Banco de Dados <strong>Não Relacionais (NoSQL)</strong>:</p>", "options": ["MongoDB, MySQL e Cassandra.", "PostgreSQL, Oracle e MongoDB.", "MongoDB e Cassandra.", "MySQL, PostgreSQL e SQL Server.", "Oracle, Cassandra e SQL Server."], "answer": 2, "explain": "<strong>MongoDB</strong> e <strong>Cassandra</strong> são NoSQL. Intrusos relacionais nas demais: <em>MySQL, PostgreSQL, Oracle, SQL Server</em>.", "area": "bd"}, {"num": 14, "stemHtml": "<p>No Design Digital, sobre o Círculo Cromático e o processo de conversão de imagens, analise os itens:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Tema</th><th>Afirmação</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>Círculo Cromático</strong></td><td>Organização circular de 12 cores (3 primárias, 3 secundárias e 6 terciárias) que auxilia na criação de combinações harmônicas como análogas e triangulação.</td></tr><tr><td><strong>II.</strong></td><td><strong>Rasterização</strong></td><td>Processo de converter gráficos vetoriais (baseados em fórmulas matemáticas) em imagens formadas por pixels para exibição em telas ou impressão.</td></tr><tr><td><strong>III.</strong></td><td><strong>Canal Alfa (Transparência)</strong></td><td>O formato JPEG é o padrão ideal para logotipos com fundo transparente, pois não utiliza compressão com perdas.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas II e III estão corretas.", "somente a afirmativa III está correta.", "as afirmativas I, II e III estão corretas."], "answer": 1, "explain": "I e II corretas. <strong>III é falsa:</strong> JPEG usa compressão <em>com perdas</em> e <strong>não suporta</strong> transparência (quem suporta canal alfa sem perdas é <strong>PNG</strong>).", "area": "design"}, {"num": 15, "stemHtml": "<p>Assinale a alternativa que apresenta <strong>apenas</strong> serviços/plataformas de <strong>fontes personalizadas para Web</strong>, sem misturar fontes padrão instaladas nativamente nos sistemas operacionais:</p>", "options": ["Google Fonts e Times New Roman.", "Arial, Helvetica e Adobe Fonts.", "Google Fonts e Adobe Fonts.", "Times New Roman, Georgia e Arial.", "Adobe Fonts, Garamond e Open Sans."], "answer": 2, "explain": "<strong>Google Fonts</strong> e <strong>Adobe Fonts</strong> são serviços de fontes personalizadas. As outras opções misturam fontes padrão de sistema (<em>Times New Roman, Arial, Helvetica, Georgia, Garamond</em>).", "area": "design"}, {"num": 16, "stemHtml": "<p>Na área de Experiência do Usuário (UX) e Tipografia: I. Quando um designer escolhe fontes tradicionais que imitam a caligrafia humana elegante para um convite formal, utiliza <strong>Fontes Script</strong>. II. A heurística de Jakob Nielsen chamada <strong>Equivalência entre o sistema e o mundo real</strong> recomenda usar termos compreensíveis ao modelo mental do usuário em vez de códigos técnicos internos. É correto afirmar que:</p>", "options": ["Apenas a afirmação I está correta.", "Apenas a afirmação II está correta.", "Ambas as afirmações I e II estão corretas.", "Ambas as afirmações estão incorretas.", "Fontes Script são idênticas às fontes Sem Serifa em telas de terminal."], "answer": 2, "explain": "Ambas estão corretas: Fontes Script imitam escrita manual elegante; Equivalência com o mundo real evita jargão técnico.", "area": "design"}, {"num": 17, "stemHtml": "<p>Assinale a alternativa que contém <strong>apenas</strong> tags estruturais <strong>semânticas</strong> introduzidas no HTML5 para delimitar áreas de navegação, cabeçalho, rodapé e seção de conteúdo:</p>", "options": ["<code>&lt;div&gt;</code>, <code>&lt;span&gt;</code>, <code>&lt;header&gt;</code> e <code>&lt;footer&gt;</code>", "<code>&lt;nav&gt;</code>, <code>&lt;header&gt;</code>, <code>&lt;footer&gt;</code> e <code>&lt;section&gt;</code>", "<code>&lt;nav&gt;</code>, <code>&lt;div&gt;</code>, <code>&lt;body&gt;</code> e <code>&lt;section&gt;</code>", "<code>&lt;span&gt;</code>, <code>&lt;section&gt;</code>, <code>&lt;ol&gt;</code> e <code>&lt;ul&gt;</code>", "<code>&lt;body&gt;</code>, <code>&lt;div&gt;</code>, <code>&lt;header&gt;</code> e <code>&lt;span&gt;</code>"], "answer": 1, "explain": "<code>&lt;nav&gt;</code>, <code>&lt;header&gt;</code>, <code>&lt;footer&gt;</code> e <code>&lt;section&gt;</code> são tags semânticas do HTML5. <code>&lt;div&gt;</code> e <code>&lt;span&gt;</code> não possuem valor semântico; <code>&lt;body&gt;</code> já existia antes do HTML5.", "area": "web_redes"}, {"num": 18, "stemHtml": "<p>Analise o quadro sobre HTML5, CSS3 e Árvore DOM em JavaScript:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Tecnologia</th><th>Afirmação</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>Listas HTML</strong></td><td>A tag <code>&lt;ol&gt;</code> cria uma <em>ordered list</em> (lista ordenada/numerada) e <code>&lt;ul&gt;</code> cria uma <em>unordered list</em> (lista com marcadores).</td></tr><tr><td><strong>II.</strong></td><td><strong>Regra CSS</strong></td><td>Toda regra CSS é formada por duas partes principais: um <strong>Seletor</strong> e um <strong>Bloco de Declarações</strong>.</td></tr><tr><td><strong>III.</strong></td><td><strong>Elemento <code>&lt;div&gt;</code></strong></td><td>É classificado por padrão como um elemento de <strong>bloco</strong> (diferente de <code>&lt;span&gt;</code>, que é <em>inline</em>).</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas II e III estão corretas.", "somente a afirmativa III está correta.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "Listas <code>&lt;ol&gt;</code>/<code>&lt;ul&gt;</code>, partes da regra CSS (Seletor + Bloco de Declarações) e <code>&lt;div&gt;</code> como elemento de bloco — todas corretas.", "area": "web_redes"}, {"num": 19, "stemHtml": "<p>Em CSS3, para <strong>(1) aumentar proporcionalmente um elemento</strong>, <strong>(2) inclinar/modificar seus ângulos</strong>, <strong>(3) deslocar nos eixos X e Y</strong> e <strong>(4) girar em torno de um ângulo</strong>, utilizam-se, respectivamente, as funções de transformação:</p>", "options": ["<code>scale</code>, <code>skew</code>, <code>translate</code> e <code>rotate</code>.", "<code>resize</code>, <code>angle</code>, <code>move</code> e <code>roll</code>.", "<code>scale</code>, <code>translate</code>, <code>skew</code> e <code>rotate</code>.", "<code>zoom</code>, <code>skew</code>, <code>translate</code> e <code>turn</code>.", "<code>rotate</code>, <code>skew</code>, <code>scale</code> e <code>translate</code>."], "answer": 0, "explain": "CSS3 <code>transform</code>: <code>scale</code> (escalar), <code>skew</code> (inclinar ângulos), <code>translate</code> (movimentar X/Y) e <code>rotate</code> (rotacionar).", "area": "web_redes"}, {"num": 20, "stemHtml": "<p>No JavaScript manipulando a árvore DOM, os comandos para <strong>(1) buscar um elemento pelo <code>id</code></strong>, <strong>(2) criar um nó de texto</strong>, <strong>(3) obter a raiz <code>&lt;html&gt;</code> do documento</strong> e <strong>(4) acessar o nó pai de um elemento</strong> são, respectivamente:</p>", "options": ["<code>getElementsByTagName</code>, <code>createElement</code>, <code>parentNode</code>, <code>documentElement</code>.", "<code>getElementById</code>, <code>createTextNode</code>, <code>documentElement</code>, <code>parentNode</code>.", "<code>getElementById</code>, <code>createAttribute</code>, <code>documentElement</code>, <code>childNodes</code>.", "<code>querySelectorAll</code>, <code>createTextNode</code>, <code>parentNode</code>, <code>documentElement</code>.", "<code>getElementById</code>, <code>createTextNode</code>, <code>parentNode</code>, <code>documentElement</code>."], "answer": 1, "explain": "Métodos DOM: <code>getElementById</code>, <code>createTextNode</code>, <code>documentElement</code>, <code>parentNode</code>.", "area": "web_redes"}, {"num": 21, "stemHtml": "<p>Um desenvolvedor utiliza classes do framework <strong>Bootstrap</strong>: <code>btn btn-default</code>, <code>form-inline</code>, <code>col-md-1</code>, <code>img-responsive</code> e <code>text-primary</code>. Elas aplicam formatação, respectivamente, a:</p>", "options": ["botão, tabela, imagem, grid e texto de ajuda/destaque.", "formulário, botão, grid, imagem e tabela.", "botão, formulário, grid, imagem e texto de ajuda/destaque.", "tabela, formulário, grid, botão e imagem.", "botão, formulário, imagem, grid e tabela."], "answer": 2, "explain": "<code>btn</code> (botão), <code>form-inline</code> (formulário), <code>col-md-1</code> (grid), <code>img-responsive</code> (imagem), <code>text-primary</code> (texto contextual/ajuda).", "area": "prog"}, {"num": 22, "stemHtml": "<p>No sistema binário (base 2) e hexadecimal (base 16), um byte possui 8 bits. Qual é a representação binária de <code>255(10)</code> e quais são as representações em binário e hexadecimal de <code>100(10)</code>?</p>", "options": ["<code>255 = 10000001(2)</code>; <code>100 = 01000100(2) = 65(16)</code>.", "<code>255 = 11111111(2)</code>; <code>100 = 01100100(2) = 64(16)</code>.", "<code>255 = 11111110(2)</code>; <code>100 = 01100100(2) = FA(16)</code>.", "<code>255 = 11111111(2)</code>; <code>100 = 10000100(2) = 64(16)</code>.", "<code>255 = 10101010(2)</code>; <code>100 = 01100100(2) = 46(16)</code>."], "answer": 1, "explain": "<code>255 = 11111111(2)</code>. Para <code>100</code>: <code>64 + 32 + 4 = 100</code> &rarr; <code>01100100(2)</code>. Agrupando de 4 em 4 bits: <code>0110 = 6</code> e <code>0100 = 4</code> &rarr; <code>64(16)</code>.", "area": "web_redes"}, {"num": 23, "stemHtml": "<p>Sobre hardware de armazenamento e tecnologias de virtualização, analise a tabela:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Tecnologia</th><th>Afirmação</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td>*<em>SSD (</em>Solid-State Drive<em>)</em>*</td><td>Armazena dados em chips de memória flash sem partes mecânicas móveis, oferecendo menor tempo de acesso e menor consumo energético que HDs tradicionais.</td></tr><tr><td><strong>II.</strong></td><td><strong>Contêineres</strong></td><td>Garantem <strong>isolamento</strong> empacotando a aplicação e suas dependências em ambientes leves sem precisar virtualizar todo o hardware completo como uma VM.</td></tr><tr><td><strong>III.</strong></td><td><strong>Hospedagem Dedicada</strong></td><td>Vários sites diferentes dividem obrigatoriamente a mesma fatia de memória RAM e CPU sem controle algum sobre o servidor.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas II e III estão corretas.", "somente a afirmativa III está correta.", "as afirmativas I, II e III estão corretas."], "answer": 1, "explain": "I (SSD flash sem partes mecânicas) e II (Isolamento em contêineres) corretas. <strong>III é falsa:</strong> a descrição dada pertence à <strong>Hospedagem Compartilhada</strong>, não à Dedicada!", "area": "web_redes"}, {"num": 24, "stemHtml": "<p>Assinale a alternativa que apresenta <strong>exclusivamente</strong> diretórios padrão da hierarquia do sistema operacional <strong>Linux</strong>:</p>", "options": ["<code>/bin</code>, <code>/ls</code>, <code>/home</code>, <code>/lib</code>, <code>/usr</code>, <code>/var</code> e <code>/tmp</code>.", "<code>/bin</code>, <code>/etc</code>, <code>/home</code>, <code>/mkdir</code>, <code>/usr</code>, <code>/var</code> e <code>/rm</code>.", "<code>/bin</code>, <code>/etc</code>, <code>/home</code>, <code>/lib</code>, <code>/usr</code>, <code>/var</code> e <code>/tmp</code>.", "<code>/cd</code>, <code>/etc</code>, <code>/home</code>, <code>/lib</code>, <code>/pwd</code>, <code>/var</code> e <code>/tmp</code>.", "<code>/bin</code>, <code>/etc</code>, <code>/cat</code>, <code>/apt</code>, <code>/usr</code>, <code>/var</code> e <code>/tmp</code>."], "answer": 2, "explain": "<code>/bin, /etc, /home, /lib, /usr, /var, /tmp</code> são diretórios reais do Linux. As demais colocam comandos (<code>/ls, /mkdir, /rm, /cd, /pwd, /cat, /apt</code>) disfarçados de pastas!", "area": "web_redes"}, {"num": 25, "stemHtml": "<p>No terminal do sistema operacional <strong>Linux</strong>, os comandos para <strong>(1) listar arquivos da pasta</strong>, <strong>(2) criar uma pasta</strong>, <strong>(3) copiar arquivos</strong>, <strong>(4) gerenciar pacotes</strong>, <strong>(5) exibir o conteúdo de um arquivo de texto</strong> e <strong>(6) desligar o computador</strong> são, respectivamente:</p>", "options": ["<code>ls</code>, <code>rm</code>, <code>cp</code>, <code>apt</code>, <code>cat</code> e <code>shutdown</code>.", "<code>ls</code>, <code>mkdir</code>, <code>cp</code>, <code>cat</code>, <code>apt</code> e <code>shutdown</code>.", "<code>ls</code>, <code>mkdir</code>, <code>cp</code>, <code>apt</code>, <code>cat</code> e <code>shutdown</code>.", "<code>dir</code>, <code>mkdir</code>, <code>mv</code>, <code>apt</code>, <code>cat</code> e <code>sudo</code>.", "<code>ls</code>, <code>mkdir</code>, <code>cp</code>, <code>apt</code>, <code>echo</code> e <code>ping</code>."], "answer": 2, "explain": "Listar (<code>ls</code>), criar pasta (<code>mkdir</code>), copiar (<code>cp</code>), pacotes (<code>apt</code>), ler arquivo (<code>cat</code>), desligar (<code>shutdown</code>).", "area": "web_redes"}, {"num": 26, "stemHtml": "<p>Sobre o modelo de camadas <strong>TCP/IP</strong> e segurança web (<strong>SSL/TLS</strong>), analise os itens:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Tema</th><th>Afirmação</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>Camadas do TCP/IP</strong></td><td>É estruturado em quatro camadas: Link (Acesso à Rede), Internet, Transporte e Aplicação.</td></tr><tr><td><strong>II.</strong></td><td><strong>Protocolo SSL/TLS</strong></td><td>Fornece criptografia, autenticação e integridade dos dados na comunicação entre navegador e servidor web.</td></tr><tr><td><strong>III.</strong></td><td><strong>Protocolo RDP</strong></td><td>Tecnologia criada pela Microsoft para acesso remoto a um computador usando interface gráfica de usuário pela rede.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas II e III estão corretas.", "somente a afirmativa III está correta.", "as afirmativas I, II e III estão corretas."], "answer": 4, "explain": "4 camadas do TCP/IP (Link, Internet, Transporte, Aplicação), SSL/TLS (Criptografia, Autenticação, Integridade) e RDP (acesso remoto gráfico Microsoft) — todas corretas.", "area": "web_redes"}, {"num": 27, "stemHtml": "<p>Em uma rede corporativa, todas as estações de trabalho conectam-se diretamente a uma *<em>unidade central inteligente (</em>switch<em>)</em>*, que recebe os quadros e os encaminha apenas para a estação de destino correta. Esse layout físico corresponde à:</p>", "options": ["Topologia em Barramento (<em>Bus</em>).", "Topologia em Anel (<em>Ring</em>).", "Topologia em Estrela (<em>Star</em>).", "Topologia em Malha Completa (<em>Mesh</em>).", "Topologia Ponto a Ponto Simples."], "answer": 2, "explain": "Unidade central inteligente (<em>switch</em>) distribuindo tráfego = *<em>Topologia em Estrela (</em>Star<em>)</em>*.", "area": "web_redes"}, {"num": 28, "stemHtml": "<p>Assinale a alternativa que apresenta <strong>apenas</strong> serviços de <strong>Webmail</strong> (acesso ao e-mail diretamente pelo navegador com armazenamento na nuvem):</p>", "options": ["Gmail, Canva e Outlook.com.", "Gmail, Outlook.com e iCloud Mail.", "Splice, iCloud Mail e Gmail.", "Outlook.com, Norton Safe Web e iCloud Mail.", "Gmail, Mozilla Firefox e Microsoft Word."], "answer": 1, "explain": "Gmail, Outlook.com e iCloud Mail são webmails. Intrusos: <em>Canva</em>, <em>Splice</em>, <em>Norton Safe Web</em>, <em>Firefox</em>, <em>Word</em>.", "area": "web_redes"}, {"num": 29, "stemHtml": "<p>No Microsoft Word e no sistema Windows, analise as afirmativas sobre ferramentas de produtividade:</p>\n<table class='q-table'><thead><tr><th>Item</th><th>Recurso</th><th>Afirmação</th></tr></thead><tbody><tr><td><strong>I.</strong></td><td><strong>Marcadores e Numeração</strong></td><td>Ferramenta do Word usada para organizar listas não ordenadas com símbolos e listas ordenadas com números ou letras.</td></tr><tr><td><strong>II.</strong></td><td><strong>Controlar Alterações</strong></td><td>Recurso do Word que registra modificações feitas em um documento para que possam ser aceitas ou rejeitadas na revisão.</td></tr><tr><td><strong>III.</strong></td><td><strong>Área de Transferência</strong></td><td>No Windows, <code>Ctrl+C</code> recorta o conteúdo removendo-o da origem e <code>Ctrl+X</code> copia mantendo o original intacto.</td></tr></tbody></table>\n<p>É correto afirmar que</p>", "options": ["somente a afirmativa I está correta.", "somente as afirmativas I e II estão corretas.", "somente as afirmativas II e III estão corretas.", "somente a afirmativa III está correta.", "as afirmativas I, II e III estão corretas."], "answer": 1, "explain": "I e II corretas. <strong>III é falsa:</strong> houve inversão dos atalhos! <code>Ctrl+C</code> <strong>copia</strong> mantendo o original, e <code>Ctrl+X</code> <strong>recorta</strong> removendo da origem.", "area": "web_redes"}, {"num": 30, "stemHtml": "<p>Uma empresa realizou uma análise estratégica mapeando internamente suas <strong>Forças e Fraquezas</strong> e externamente suas <strong>Oportunidades e Ameaças</strong> no mercado de software. Essa ferramenta de planejamento denomina-se:</p>", "options": ["Diagrama de Casos de Uso.", "Análise SWOT.", "Modelo Cascata.", "Primeira Forma Normal.", "Protocolo POP3."], "answer": 1, "explain": "Análise de forças/fraquezas internas e oportunidades/ameaças externas = <strong>Análise SWOT</strong>.", "area": "prog"}]}}, "apostilaSections": [{"id": "cola", "title": "⚡ Cola de Bolso (1 Página • 04/12)", "html": "\n<div class=\"callout callout-note\">\n  <strong>⚡ COLA DE BOLSO DE 1 PÁGINA — REVISÃO FINAL PARA O DIA 04/12</strong><br>\n  Leia estes 16 pontos rápidos antes de entrar na sala de prova!\n</div>\n<table class=\"q-table\">\n  <thead><tr><th>Tema na Prova</th><th>Verdade Oficial (Marque sem medo)</th><th>Pegadinha Clássica (Fuja disso!)</th></tr></thead>\n  <tbody>\n    <tr><td><strong>SQL Sublinguagens</strong></td><td><strong>DDL:</strong> CREATE, ALTER, DROP<br><strong>DML:</strong> INSERT, UPDATE, DELETE<br><strong>DQL:</strong> SELECT | <strong>DCL:</strong> GRANT/REVOKE | <strong>TCL:</strong> COMMIT/ROLLBACK</td><td>Inverter DDL com DQL ou pôr <code>COUNT()</code> dentro do <code>WHERE</code>.</td></tr>\n    <tr><td><strong>Normalização &amp; DER</strong></td><td><strong>1FN:</strong> Valores atômicos (indivisíveis).<br><strong>Atributo Derivado:</strong> calculado (ex: Idade).<br><strong>Conceitual:</strong> DER | <strong>Físico:</strong> SQL no SGBD.</td><td>Pôr dois telefones na mesma célula; inverter Conceitual com Físico.</td></tr>\n    <tr><td><strong>Protocolos E-mail</strong></td><td><strong>SMTP:</strong> Envia | <strong>POP3:</strong> Baixa e apaga | <strong>IMAP:</strong> Sincroniza no servidor.</td><td>Inverter SMTP com IMAP!</td></tr>\n    <tr><td><strong>Cookies &amp; HTML</strong></td><td><strong>Cookies:</strong> NO NAVEGADOR (~4 KB), sessão ou permanente.<br><strong>Nova aba:</strong> <code>target=\"_blank\"</code>.</td><td>Dizer que Cookie fica <em>\"na nuvem\"</em>!</td></tr>\n    <tr><td><strong>Web &amp; CSS3</strong></td><td><strong>Semânticas:</strong> <code>&lt;nav&gt;&lt;header&gt;&lt;footer&gt;&lt;section&gt;</code>.<br><strong>Box Model:</strong> <code>padding</code> (interno) vs <code>margin</code> (externo).<br><strong>Transform:</strong> <code>scale, skew, translate, rotate</code>.</td><td>Dizer que <code>&lt;div&gt;</code>/<code>&lt;span&gt;</code> são semânticas ou que <code>&lt;tr&gt;</code> é célula (<code>&lt;td&gt;</code> é célula; <code>&lt;tr&gt;</code> é linha!).</td></tr>\n    <tr><td><strong>Programação &amp; POO</strong></td><td><strong>Matriz 3x3:</strong> índice <code>[0][0]</code>; Diag. Principal <code>i==j</code>.<br><strong>Casting:</strong> explícito vs Implícito (<em>coercion</em>).<br><strong>4 Pilares POO:</strong> Abstração, Encapsulamento, Herança, Polimorfismo.</td><td>Somar diagonal secundária; inventar <em>\"Conversão Normal\"</em>; dizer que <code>char</code> é <code>true/false</code>; pôr Atributos/Métodos como pilares.</td></tr>\n    <tr><td><strong>Editores, Cloud &amp; Git</strong></td><td><strong>Editor Código:</strong> VS Code/Sublime | <strong>WYSIWYG:</strong> Wix/Dreamweaver.<br><strong>Git:</strong> <code>branch</code> (quebrar), <code>diff</code> (comparar), <code>merge</code> (fundir).<br><strong>Nuvem:</strong> IaaS (VM), PaaS (App), SaaS (Gmail/Office).</td><td>Chamar <em>Notepad/TextEdit</em> de IDE; pôr <em>Adobe CC / Creative Commons</em> como framework.</td></tr>\n    <tr><td><strong>Redes, Linux &amp; Binário</strong></td><td><strong>Barramento:</strong> cabo único central | <strong>Estrela:</strong> Switch central.<br><strong>TCP/IP:</strong> Link, Internet, Transporte, Aplicação.<br><strong>Linux Pastas:</strong> <code>/bin,/etc,/home,/lib,/usr,/var,/tmp</code>.<br><strong>Byte:</strong> <code>255 = 11111111</code> | <code>100 = 01100100 = 64(16)</code>.</td><td>Misturar comandos (<code>/ls, /mkdir, /rm</code>) como se fossem pastas do Linux!</td></tr>\n    <tr><td><strong>Design &amp; Gestalt</strong></td><td><strong>Cores:</strong> RGB (telas), CMYK (impressão), Hex.<br><strong>Vetor:</strong> SVG, PDF | <strong>Bitmap:</strong> JPEG, PNG (transp.), BMP.<br><strong>Gestalt:</strong> Continuidade, Proximidade, Fechamento, Semelhança.</td><td>Chamar <em>\"Primária\"</em> ou <em>\"CSS\"</em> de padrão de cor; pôr JPEG/PNG como vetorial.</td></tr>\n    <tr><td><strong>Inglês &amp; Ética FAT</strong></td><td><code>outcomes</code> = resultados | <code>data</code> = dados | <code>troubleshooting</code> = solução.<br><strong>Ética:</strong> bem comum real, direitos trabalhistas, participação comunitária ambiental.</td><td>Traduzir <code>data</code> como \"datas\" ou marcar doação por vaidade/redes sociais!</td></tr>\n    <tr><td><strong>M-Tec Base Comum (1º Ano)</strong></td><td><strong>Barroco:</strong> Cultismo (palavras) x Conceptismo (ideias).<br><strong>Química:</strong> Metal conduz sólido; Iônico só líquido.<br><strong>Matemática:</strong> Dízima periódica é Racional ($\\mathbb{Q}$); 0 não inicia número.<br><strong>História:</strong> Paleolítico (nômade/fogo) x Neolítico (sedentário/agricultura).</td><td>Inverter Cultismo/Conceptismo; pôr dízima nos Irracionais; começar número de 3 dígitos com 0!</td></tr>\n  </tbody>\n</table>\n"}, {"id": "mod0", "title": "Módulo 0 • Moldes FAT, Tipos, Casting & Lógica (Dia 1)", "html": "<h2 id=\"dia-1--raio-x-da-banca-fundação-fat-memória-ram-tipos-primitivos-casting-divmod-e-lógica-proposicional\">Dia 1 — Raio-X da Banca Fundação FAT, Memória RAM, Tipos Primitivos, Casting, DIV/MOD e Lógica Proposicional</h2>\n<h3 id=\"-contexto-no-mundo-real-por-que-você-precisa-dominar-isso\">🎯 Contexto no Mundo Real: Por que você precisa dominar isso?</h3>\n<p>Imagine que você abre o sistema <strong>NSA da Etec</strong> ou faz um <strong>Pix</strong> no aplicativo do banco. Na tela do Pix aparece: nome do recebedor (<code>\"Maria Oliveira\"</code>), valor (<code>R$ 150.75</code>), chave (<code>11988887777</code>), tipo de conta (<code>'C'</code> para Corrente) e uma pergunta de confirmação (<code>temSaldoSuficiente = verdadeiro</code>).</p>\n<p>Por trás dos panos, o computador <strong>não enxerga \"um recibo de Pix\"</strong> como um humano enxerga. Ele enxerga bilhões de interruptores microscópicos (<code>0</code> e <code>1</code>) na <strong>memória RAM</strong>. Para que o celular não tente \"multiplicar o nome da Maria por 2\" nem apague os centavos <code>0.75</code> na hora de transferir o dinheiro, o programador precisa ensinar à máquina <strong>qual é o formato exato de cada informação</strong> e <strong>como tomar decisões lógicas</strong> com segurança. É exatamente isso que a <strong>Fundação FAT</strong> cobra na abertura das provas de Desenvolvimento de Sistemas!</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Se você já jogou algo online, olhou uma HUD no cantinho da tela ou configurou um bot no Discord, você já usou tudo o que cai no Dia 1 sem nem perceber:</p>\n<ul>\n<li><strong>Os 5 Tipos Primitivos na HUD de um Jogo:</strong>\n<ul>\n<li><code>hp = 100</code> → <strong><code>int</code></strong> (vida inteira, sem vírgula).</li>\n<li><code>kda = 2.45</code> → <strong><code>float</code> / <code>double</code></strong> (taxa de abates/mortes ou precisão com casas decimais).</li>\n<li><code>nick = \"Henrique_BR\"</code> → <strong><code>string</code></strong> (texto completo; se colocar <code>\"100\"</code> entre aspas, vira texto e <strong>não</strong> soma dano!).</li>\n<li><code>rank = 'S'</code> ou <code>time = 'A'</code> → <strong><code>char</code></strong> (uma única letra/símbolo sozinho).</li>\n<li><code>estaVivo = true</code> / <code>mutadoNoDiscord = false</code> → <strong><code>bool</code></strong> (liga/desliga: verdadeiro ou falso).</li>\n</ul></li>\n<li><strong>Casting no XP / Dano (<code>(int) 99.9</code>):</strong> Se o jogo calcula dano crítico <code>99.9</code> e faz <code>(int) dano</code> para exibir na barra inteira, ele <strong>corta o <code>.9</code> fora e mostra <code>99</code></strong> (trunca, não arredonda pra 100!).</li>\n<li><strong><code>DIV</code> e <code>MOD</code> no Minecraft:</strong> Você tem <strong>150 blocos de ferro</strong> e um pack fecha em <strong>64</strong>. Quantos packs cheios dá? <code>150 DIV 64 =</code> <strong><code>2 packs</code></strong>! E quantos blocos ficam soltos no último slot? <code>150 MOD 64 =</code> <strong><code>22 itens</code></strong>!</li>\n<li><strong>Tabela Verdade na Fila Ranqueada:</strong> Regra do servidor para puxar Ranked: <code>(nivel &gt;= 20) E (ping &lt; 60 OU servidor == \"BR\") E NAO estaBanido</code>. Basta você estar banido (<code>NAO true = false</code>) para o <strong><code>E</code></strong> bloquear sua entrada na partida inteira!</li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--os-4-moldes-secretos-da-banca-fundação-fat\">📚 Parte 1 — Os 4 Moldes Secretos da Banca Fundação FAT</h3>\n<p>Antes de estudar os conteúdos técnicos, você precisa conhecer o <strong>estilo da banca examinadora</strong> (Fundação FAT / CPS). Analisando provas oficiais anteriores (DS 2025, Info 2025, DS 2019 e M-Tec 2022), praticamente 100% das questões técnicas caem em apenas <strong>4 moldes previsíveis</strong>:</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Molde da Banca</th>\n<th style=\"text-align: left;\">Como a Questão Aparece</th>\n<th style=\"text-align: left;\">Estratégia de Resolução em Segundos</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Molde 1 — Afirmativas I, II e III</strong></td>\n<td style=\"text-align: left;\">Apresenta 3 frases (frequentemente ligadas a uma tabela de termos) e pergunta quais estão corretas.</td>\n<td style=\"text-align: left;\"><strong>9 em cada 10 vezes</strong>, a banca pega duas definições e <strong>troca uma pela outra</strong> (ex.: diz que DDL faz <code>SELECT</code> e DQL faz <code>CREATE</code>, ou diz que Cookie fica na nuvem). Ache uma falsa e elimine 2 ou 3 alternativas (A–E) logo de cara!</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Molde 2 — Lista com Intruso</strong></td>\n<td style=\"text-align: left;\"><em>\"Assinale a alternativa que apresenta APENAS [frameworks / navegadores / pastas Linux / padrões de cores].\"</em></td>\n<td style=\"text-align: left;\">Todas as 4 alternativas erradas têm <strong>1 único item intruso</strong> escondido no meio de itens verdadeiros (ex.: pôr <code>Creative Commons</code> entre frameworks, ou <code>/mkdir</code> entre diretórios Linux).</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Molde 3 — Definição Direta / Cenário</strong></td>\n<td style=\"text-align: left;\">Descreve um problema real de projeto e pede o termo oficial da engenharia/SQL/rede.</td>\n<td style=\"text-align: left;\">Busque palavras-gatilho no enunciado: <em>\"sem perder nitidez no zoom\"</em> = SVG/Vetor; <em>\"forçada manualmente pelo dev\"</em> = Casting explícito; <em>\"sincroniza no servidor\"</em> = IMAP.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Molde 4 — Micro-Execução (Na Mão)</strong></td>\n<td style=\"text-align: left;\">Mostra 5 a 10 linhas de Portugol/JS/SQL/Binário ou uma Matriz 3×3 e pede a saída final.</td>\n<td style=\"text-align: left;\">Nunca tente fazer de cabeça! Desenhe a tabela de <strong>teste de mesa</strong> no rascunho e acompanhe linha por linha até o fim do laço.</td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h3 id=\"-parte-2--como-variáveis-vivem-na-memória-ram-e-os-5-tipos-primitivos\">📚 Parte 2 — Como Variáveis Vivem na Memória RAM e os 5 Tipos Primitivos</h3>\n<p>Quando um programa está rodando, a <strong>Memória RAM (<em>Random Access Memory</em>)</strong> funciona como um armário gigante cheio de gavetas numeradas (endereços de memória). Criar uma <strong>variável</strong> significa <strong>reservar uma gaveta</strong>, dar a ela um <strong>rótulo (identificador)</strong> — por exemplo <code>idade</code> — e colar nela uma <strong>etiqueta de tipo</strong>.</p>\n<p><strong>Por que a etiqueta de tipo existe?</strong></p>\n<ol>\n<li><strong>Tamanho em bytes:</strong> Um número inteiro comum costuma ocupar 4 bytes (32 bits), enquanto um número decimal de dupla precisão (<code>double</code>) ocupa 8 bytes (64 bits), e um único caractere (<code>char</code>) ocupa apenas 1 ou 2 bytes.</li>\n<li><strong>Significado dos zeros e uns:</strong> A mesma sequência binária na RAM pode significar o número <code>65</code> (se a etiqueta for <code>int</code>) ou a letra <code>'A'</code> na tabela <strong>ASCII</strong> (se a etiqueta for <code>char</code>)!</li>\n<li><strong>Operações permitidas:</strong> Só faz sentido calcular raiz quadrada em números, e só faz sentido transformar em maiúsculas em textos.</li>\n</ol>\n<p>Conheça os <strong>5 Tipos Primitivos Oficiais</strong> exigidos pela Etec:</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Tipo Técnico</th>\n<th style=\"text-align: left;\">Outros nomes na prova</th>\n<th style=\"text-align: left;\">O que armazena na memória</th>\n<th style=\"text-align: left;\">Exemplos válidos</th>\n<th style=\"text-align: left;\">Armadilha comum</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Inteiro (<code>int</code>)</strong></td>\n<td style=\"text-align: left;\"><code>integer</code>, <code>Inteiro</code> (Portugol)</td>\n<td style=\"text-align: left;\">Apenas números sem parte fracionária (positivos, negativos ou <code>0</code>).</td>\n<td style=\"text-align: left;\"><code>0</code>, <code>16</code>, <code>-2026</code>, <code>4096</code></td>\n<td style=\"text-align: left;\">Divisão inteira entre dois <code>int</code> em C/Java (<code>5 / 2</code>) resulta em <strong><code>2</code></strong>, descartando o <code>.5</code>!</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Real (<code>float</code> / <code>double</code>)</strong></td>\n<td style=\"text-align: left;\">Ponto Flutuante, <code>Real</code> (Portugol)</td>\n<td style=\"text-align: left;\">Números com casas decimais (precisão simples <code>float</code> ou dupla <code>double</code>).</td>\n<td style=\"text-align: left;\"><code>3.14</code>, <code>7.5</code>, <code>-0.001</code>, <code>10.0</code></td>\n<td style=\"text-align: left;\">Em programação usa-se <strong>ponto (<code>.</code>)</strong>, nunca vírgula (<code>,</code>). <code>10.0</code> ocupa memória como decimal, mesmo sendo redondo!</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Caractere (<code>char</code>)</strong></td>\n<td style=\"text-align: left;\"><code>Caractere</code> (um único símbolo)</td>\n<td style=\"text-align: left;\"><strong>Exatamente 1 único caractere</strong> (uma letra, um dígito isolado ou um símbolo de pontuação).</td>\n<td style=\"text-align: left;\"><code>'A'</code>, <code>'m'</code>, <code>'7'</code>, <code>'@'</code>, <code>' '</code></td>\n<td style=\"text-align: left;\">Em C/Java vem entre <strong>aspas simples (<code>'A'</code>)</strong>. A banca FAT adora perguntar qual tipo guarda uma alternativa <code>'A'</code>–<code>'E'</code> ou <code>'M'</code>/<code>'F'</code>!</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Texto (<code>string</code>)</strong></td>\n<td style=\"text-align: left;\"><code>Cadeia</code>, <code>Literal</code>, <code>varchar</code> (SQL)</td>\n<td style=\"text-align: left;\">Sequência de <strong>0, 1 ou muitos caracteres</strong> juntos em cadeia.</td>\n<td style=\"text-align: left;\"><code>\"Etec DS\"</code>, <code>\"12345\"</code>, <code>\"\"</code> (vazia)</td>\n<td style=\"text-align: left;\"><code>\"123\"</code> entre aspas é <strong>TEXTO (<code>string</code>)</strong>, NÃO número! Se somar <code>\"10\" + \"20\"</code>, vira <code>\"1020\"</code> (<strong>concatenação</strong>).</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Booleano (<code>bool</code>)</strong></td>\n<td style=\"text-align: left;\"><code>Lógico</code> (Portugol), <code>boolean</code></td>\n<td style=\"text-align: left;\">Exclusivamente dois estados lógicos binários.</td>\n<td style=\"text-align: left;\"><code>true</code> (<code>Verdadeiro</code>) ou <code>false</code> (<code>Falso</code>)</td>\n<td style=\"text-align: left;\">Não usa aspas! <code>\"true\"</code> entre aspas é uma <code>string</code> de 4 letras, não um booleano!</td>\n</tr>\n</tbody>\n</table>\n<div class=\"callout callout-warning\">\n\n<p><strong>Pegadinha clássica da FAT (INFO 2025 Q19):</strong> A questão pergunta qual tipo primitivo armazena adequadamente um caractere isolado (como <code>'S'</code> ou <code>'N'</code>, ou uma letra <code>'B'</code>). Resposta oficial: <strong><code>char</code> / Caractere</strong> (e <strong>NUNCA</strong> <code>boolean</code>, que só guarda <code>true</code>/<code>false</code>, nem <code>float</code>, que guarda decimais!).</p>\n</div>\n\n<hr />\n<h3 id=\"-parte-3--conversão-implícita-coerção-vs-conversão-explícita-type-casting\">📚 Parte 3 — Conversão Implícita (<em>Coerção</em>) vs. Conversão Explícita (<em>Type Casting</em>)</h3>\n<p>Na vida real de um sistema, frequentemente temos um dado em um tipo e precisamos dele em outro. Por exemplo: o usuário digita a idade no formulário HTML (tudo que vem do teclado na web chega como <strong>texto <code>string</code></strong> <code>\"16\"</code>), mas o sistema precisa somar <code>+ 1</code> matematicamente. Como os tipos são convertidos? Existem <strong>dois mecanismos oficiais</strong>:</p>\n<h4 id=\"1-conversão-implícita-coerção-automática\">1. Conversão Implícita (<em>Coerção Automática</em>)</h4>\n<p>Acontece <strong>sozinha nos bastidores</strong>, feita automaticamente pelo compilador ou interpretador <strong>sem que o programador escreva comando de conversão</strong>.</p>\n<ul>\n<li><strong>Regra em linguagens tipadas (C, Java, C#):</strong> Ocorre na <strong>promoção de um tipo menor para um tipo maior</strong>, onde <strong>não existe risco de perder dados</strong>. Um <code>int</code> cabe confortavelmente dentro de um <code>double</code>.\n<ul>\n<li><code>int pontos = 10;</code></li>\n<li><code>double bonus = pontos;</code> → O computador converte <code>10</code> para <code>10.0</code> automaticamente! Ninguém precisou mandar.</li>\n</ul></li>\n<li><strong>Em linguagens dinâmicas (JavaScript):</strong> Se você soma número com string (<code>\"Nota: \" + 9</code>), o JS converte <code>9</code> em <code>\"9\"</code> implicitamente e junta tudo em <code>\"Nota: 9\"</code>.</li>\n</ul>\n<h4 id=\"2-conversão-explícita-type-casting\">2. Conversão Explícita (<em>Type Casting</em>)</h4>\n<p>Acontece quando <strong>o programador escreve explicitamente uma instrução no código forçando a mudança de tipo</strong>. Ela é obrigatória sempre que houver <strong>risco de perda de informação</strong> (por exemplo, transformar um número com casas decimais em inteiro) ou conversão texto ↔︎ número.</p>\n<ul>\n<li><strong>Em C / Java / C#:</strong> Coloca-se o tipo desejado entre parênteses antes da variável: <code>(int) valor</code>.</li>\n<li><strong>Em Python / JavaScript:</strong> Usam-se funções de conversão explícita como <code>int(\"16\")</code>, <code>float(\"7.5\")</code>, <code>Number(\"42\")</code>, <code>parseInt(\"42\")</code>, <code>String(100)</code>.</li>\n</ul>\n<h4 id=\"-exemplo-real-comentado-linha-a-linha-o-perigo-do-truncamento\">💻 Exemplo Real Comentado Linha a Linha (O Perigo do Truncamento!)</h4>\n<p>Veja este trecho clássico estilo prova em C/Java:</p>\n<div class=\"sourceCode\" id=\"cb1\"><pre class=\"sourceCode java\"><code class=\"sourceCode java\"><span id=\"cb1-1\"><a href=\"#cb1-1\" aria-hidden=\"true\"></a><span class=\"dt\">double</span> mediaOriginal = <span class=\"fl\">8.</span><span class=\"dv\">95</span>;          <span class=\"co\">// Linha 1: guarda exatamente 8.95 na RAM (8 bytes)</span></span>\n<span id=\"cb1-2\"><a href=\"#cb1-2\" aria-hidden=\"true\"></a><span class=\"dt\">int</span> notaInteira = (<span class=\"dt\">int</span>) mediaOriginal;<span class=\"co\">// Linha 2: CASTING EXPLÍCITO! O dev forçou virar int</span></span>\n<span id=\"cb1-3\"><a href=\"#cb1-3\" aria-hidden=\"true\"></a><span class=\"dt\">double</span> notaPromovida = notaInteira;   <span class=\"co\">// Linha 3: CONVERSÃO IMPLÍCITA! int -&gt; double automático</span></span>\n<span id=\"cb1-4\"><a href=\"#cb1-4\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-5\"><a href=\"#cb1-5\" aria-hidden=\"true\"></a><span class=\"bu\">System</span>.<span class=\"fu\">out</span>.<span class=\"fu\">println</span>(notaInteira);      <span class=\"co\">// Imprime: 8</span></span>\n<span id=\"cb1-6\"><a href=\"#cb1-6\" aria-hidden=\"true\"></a><span class=\"bu\">System</span>.<span class=\"fu\">out</span>.<span class=\"fu\">println</span>(notaPromovida);    <span class=\"co\">// Imprime: 8.0</span></span></code></pre></div>\n<div class=\"callout callout-caution\">\n\n<p><strong>PEGADINHA MORTAL DA PROVA (DS 2025 Q8):</strong></p>\n<ol>\n<li><code>(int) 8.95</code> <strong>TRUNCA (corta fora)</strong> a parte decimal <code>.95</code>, resultando em <strong><code>8</code></strong>, e <strong>JAMAIS arredonda para <code>9</code></strong>! Mesmo que seja <code>9.999</code>, <code>(int) 9.999</code> vira <strong><code>9</code></strong>.</li>\n<li>A banca inventa nomes falsos como <em>\"Conversão Normal\"</em>, <em>\"Conversão Indireta\"</em> ou <em>\"Conversão Manual Automática\"</em>. Os únicos nomes oficiais são <strong>Implícita</strong> (feita pelo compilador sem perda) e <strong>Explícita / Casting</strong> (forçada pelo programador)!</li>\n</ol>\n</div>\n\n<hr />\n<h3 id=\"-parte-4--operadores-aritméticos-div-quociente-e-mod-resto\">📚 Parte 4 — Operadores Aritméticos, <code>DIV</code> (Quociente) e <code>MOD</code> (Resto)</h3>\n<p>Além das 4 operações tradicionais (<code>+</code>, <code>-</code>, <code>*</code>, <code>/</code>), provas técnicas adoram testar dois irmãos inseparáveis da divisão inteira:</p>\n<ul>\n<li><strong><code>DIV</code> (em Portugol/Pascal) ou <code>//</code> (em Python):</strong> Devolve <strong>apenas a parte inteira do quociente</strong> (quantas vezes o divisor cabe inteiro dentro do dividendo).</li>\n<li><strong><code>MOD</code> (em Portugol/SQL) ou <code>%</code> (em C/Java/JS/Python):</strong> Devolve <strong>apenas o resto inteiro</strong> da divisão que sobrou sem conseguir formar mais um grupo inteiro.</li>\n</ul>\n<h4 id=\"-exemplo-real-1-caixa-eletrônico-distribuindo-notas\">💻 Exemplo Real #1: Caixa Eletrônico Distribuindo Notas</h4>\n<p>Suponha que um estudante saque <strong><code>R$ 137</code></strong> e o caixa tenha notas de <code>R$ 50</code>, <code>R$ 20</code> e moedas de <code>R$ 1</code>:</p>\n<pre class=\"portugol\"><code>valor &lt;- 137\nnotas50 &lt;- valor DIV 50      // 137 / 50 dá 2 e sobra 37 -&gt; notas50 = 2\nsobra   &lt;- valor MOD 50      // O que sobrou após tirar as notas de 50 -&gt; sobra = 37\n\nnotas20 &lt;- sobra DIV 20      // 37 / 20 dá 1 e sobra 17 -&gt; notas20 = 1\nsobra   &lt;- sobra MOD 20      // O resto agora é 17 -&gt; sobra = 17\n</code></pre>\n<h4 id=\"-exemplo-real-2-convertendo-segundos-em-horas-e-minutos-3665-segundos\">💻 Exemplo Real #2: Convertendo Segundos em Horas e Minutos (<code>3665</code> segundos)</h4>\n<ul>\n<li><code>horas &lt;- 3665 DIV 3600</code> → <strong><code>1</code> hora</strong> (<code>1 × 3600 = 3600</code>).</li>\n<li><code>restoSeg &lt;- 3665 MOD 3600</code> → sobram <strong><code>65</code> segundos</strong>.</li>\n<li><code>minutos &lt;- 65 DIV 60</code> → <strong><code>1</code> minuto</strong>.</li>\n<li><code>segFinais &lt;- 65 MOD 60</code> → <strong><code>5</code> segundos</strong>! (<code>01h 01m 05s</code>).</li>\n</ul>\n<h4 id=\"aplicações-favoritas-da-banca-fat-com-mod\">Aplicações Favoritas da Banca FAT com <code>MOD</code>:</h4>\n<ol>\n<li><strong>Teste de Par ou Ímpar:</strong> Todo número par dividido por <code>2</code> deixa resto <code>0</code> (<code>N MOD 2 == 0</code>). Todo ímpar deixa resto <code>1</code> (<code>N MOD 2 == 1</code>).</li>\n<li><strong>Teste de Múltiplo / Ano Bissexto:</strong> <code>numero MOD 5 == 0</code> verifica se é múltiplo de 5.</li>\n<li><strong>Conversão Decimal → Binário (DS 2019 Q2):</strong> Dividir sucessivamente por <code>2</code> pegando <code>n MOD 2</code> (o dígito binário <code>0</code> ou <code>1</code>) e atualizando <code>n &lt;- n DIV 2</code> até <code>n</code> chegar a <code>0</code>!</li>\n</ol>\n<p><strong>Ordem de Precedência Matemática (quem calcula antes de quem):</strong> 1º Parênteses <code>()</code> (de dentro para fora) → 2º Potenciação/Raiz → 3º Multiplicação (<code>*</code>), Divisão (<code>/</code>), <code>DIV</code> e <code>MOD</code> (da esquerda para a direita) → 4º Soma (<code>+</code>) e Subtração (<code>-</code>) → 5º Relacionais (<code>&gt;</code>, <code>&gt;=</code>, <code>&lt;</code>, <code>&lt;=</code>, <code>==</code>, <code>!=</code>) → 6º Lógicos (<code>NÃO</code> → <code>E</code> → <code>OU</code>).</p>\n<hr />\n<h3 id=\"-parte-5--lógica-proposicional-operadores-lógicos-e-tabela-verdade\">📚 Parte 5 — Lógica Proposicional, Operadores Lógicos e Tabela Verdade</h3>\n<p>Uma <strong>proposição lógica</strong> é uma afirmação que pode ser julgada exclusivamente como <strong>Verdadeira (<code>V</code> / <code>true</code>)</strong> ou <strong>Falsa (<code>F</code> / <code>false</code>)</strong>. Conectamos proposições com 3 operadores fundamentais:</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Operador</th>\n<th style=\"text-align: center;\">Símbolo Matemático</th>\n<th style=\"text-align: center;\">Símbolo em Código (C/Java/JS)</th>\n<th style=\"text-align: left;\">Regra de Funcionamento Real</th>\n<th style=\"text-align: left;\">Analogia Prática</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>NÃO (Negação)</strong></td>\n<td style=\"text-align: center;\"><code>¬P</code></td>\n<td style=\"text-align: center;\"><code>!P</code> / <code>not P</code></td>\n<td style=\"text-align: left;\"><strong>Inverte</strong> o valor lógico (<code>V</code> vira <code>F</code>; <code>F</code> vira <code>V</code>).</td>\n<td style=\"text-align: left;\">Interruptor inversor</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>E (Conjunção)</strong></td>\n<td style=\"text-align: center;\"><code>P ∧ Q</code></td>\n<td style=\"text-align: center;\"><code>P &amp;&amp; Q</code> / <code>and</code></td>\n<td style=\"text-align: left;\"><strong>Exigente:</strong> Só resulta em <strong><code>V</code></strong> se <strong>AMBOS</strong> forem <strong><code>V</code></strong>. Um único <code>F</code> derruba tudo para <code>F</code>!</td>\n<td style=\"text-align: left;\"><strong>Porta com 2 cadeados em série:</strong> precisa das <strong>2 chaves</strong> para abrir</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>OU (Disjunção)</strong></td>\n<td style=\"text-align: center;\"><code>P ∨ Q</code></td>\n<td style=\"text-align: center;\"><code>P || Q</code> / <code>or</code></td>\n<td style=\"text-align: left;\"><strong>Flexível:</strong> Resulta em <strong><code>V</code></strong> se <strong>PELO MENOS UM</strong> for <strong><code>V</code></strong>. Só dá <code>F</code> se <strong>TODOS</strong> forem <code>F</code>!</td>\n<td style=\"text-align: left;\"><strong>Casa com 2 portas (frente e fundos):</strong> se pelo menos 1 destrancar, você entra</td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"tabela-verdade-completa-memorize-visualmente\">Tabela Verdade Completa (Memorize visualmente!)</h4>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: center;\"><code>P</code></th>\n<th style=\"text-align: center;\"><code>Q</code></th>\n<th style=\"text-align: center;\"><code>¬P</code> (<code>NÃO P</code>)</th>\n<th style=\"text-align: center;\"><code>P ∧ Q</code> (<code>P E Q</code>)</th>\n<th style=\"text-align: center;\"><code>P ∨ Q</code> (<code>P OU Q</code>)</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>V</strong></td>\n<td style=\"text-align: center;\"><strong>V</strong></td>\n<td style=\"text-align: center;\">F</td>\n<td style=\"text-align: center;\"><strong>V</strong></td>\n<td style=\"text-align: center;\"><strong>V</strong></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>V</strong></td>\n<td style=\"text-align: center;\"><strong>F</strong></td>\n<td style=\"text-align: center;\">F</td>\n<td style=\"text-align: center;\"><strong>F</strong></td>\n<td style=\"text-align: center;\"><strong>V</strong></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>F</strong></td>\n<td style=\"text-align: center;\"><strong>V</strong></td>\n<td style=\"text-align: center;\">V</td>\n<td style=\"text-align: center;\"><strong>F</strong></td>\n<td style=\"text-align: center;\"><strong>V</strong></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>F</strong></td>\n<td style=\"text-align: center;\"><strong>F</strong></td>\n<td style=\"text-align: center;\">V</td>\n<td style=\"text-align: center;\"><strong>F</strong></td>\n<td style=\"text-align: center;\"><strong>F</strong></td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"-exemplo-real-de-regra-de-negócio-na-etec\">💻 Exemplo Real de Regra de Negócio na Etec</h4>\n<p>Para passar direto de ano na Etec sem recuperação, o aluno precisa ter <strong>nota maior ou igual a 6</strong> <strong>E</strong> <strong>não</strong> ter mais que 25% de faltas (<code>faltas &lt;= 25</code>), <strong>OU</strong> ganhar aprovação especial do conselho (<code>conselho == true</code>). Suponha um aluno com <code>nota = 7.5</code>, <code>faltas = 30</code>, <code>conselho = false</code>: Expressão: <code>((nota &gt;= 6) E NAO (faltas &gt; 25)) OU conselho</code></p>\n<ol>\n<li><code>nota &gt;= 6</code> → <code>7.5 &gt;= 6</code> → <strong><code>V</code></strong></li>\n<li><code>faltas &gt; 25</code> → <code>30 &gt; 25</code> → <strong><code>V</code></strong></li>\n<li><code>NAO (faltas &gt; 25)</code> → <code>NAO V</code> → <strong><code>F</code></strong> <em>(lembre: <code>NÃO</code> executa antes do <code>E</code>!)</em></li>\n<li><code>V E F</code> → <strong><code>F</code></strong> <em>(reprovou no critério principal por causa das faltas!)</em></li>\n<li><code>F OU conselho</code> → <code>F OU F</code> → <strong><code>F</code></strong> (Reprovado).</li>\n</ol>\n<div class=\"callout callout-tip\">\n\n<p><strong>Leis de De Morgan (bônus para pegadinhas de negação):</strong></p>\n<ul>\n<li>Negar \"<code>P E Q</code>\" não é \"<code>não P E não Q</code>\"! É <strong><code>(não P) OU (não Q)</code></strong>! <em>(Ex.: negar \"fui à escola E fiz a prova\" significa \"NÃO fui à escola OU NÃO fiz a prova\")</em>.</li>\n<li>Negar \"<code>P OU Q</code>\" resulta em <strong><code>(não P) E (não Q)</code></strong>.</li>\n</ul>\n</div>\n\n<hr />\n<h3 id=\"️️-dissecando-questões-no-estilo-exato-da-prova\">🕵️‍♂️ Dissecando Questões no Estilo Exato da Prova</h3>\n<h4 id=\"questão-resolvida-1-baseada-em-ds-2025-q8--conversão-de-tipos\">Questão Resolvida 1 (Baseada em DS 2025 Q8 — Conversão de Tipos)</h4>\n<p><em>Um desenvolvedor Java escreveu <code>double preco = 49.99; int inteiro = (int) preco;</code> e, em seguida, <code>double copia = inteiro;</code>. Sobre essas operações, avalie:</em></p>\n<ul>\n<li><em>I. Na segunda instrução ocorreu uma conversão implícita com arredondamento para 50.</em></li>\n<li><em>II. Na segunda instrução ocorreu um type casting explícito que truncou o valor para 49.</em></li>\n<li><em>III. Na terceira instrução (<code>double copia = inteiro;</code>) o compilador realizou conversão implícita sem perda de dados.</em></li>\n</ul>\n<p><strong>Análise:</strong></p>\n<ul>\n<li><strong>Item I é FALSO:</strong> Há duas inverdades! Primeiro, <code>(int) preco</code> não é implícita (o dev escreveu <code>(int)</code>, logo é explícita/casting); segundo, <em>casting</em> <strong>trunca</strong> para <code>49</code>, nunca arredonda para <code>50</code>.</li>\n<li><strong>Item II é VERDADEIRO:</strong> <code>(int) preco</code> é explícito (<em>type casting</em>) e descarta a fração <code>.99</code>, deixando <code>49</code>.</li>\n<li><strong>Item III é VERDADEIRO:</strong> Passar <code>int</code> para <code>double</code> amplia a capacidade sem perda; o compilador converte <code>49</code> para <code>49.0</code> automaticamente (implícita). <strong>Resposta:</strong> Apenas <strong>II e III</strong> estão corretas.</li>\n</ul>\n<h4 id=\"questão-resolvida-2-baseada-em-info-2025-q20--ds-2019-q1--tabela-verdade\">Questão Resolvida 2 (Baseada em INFO 2025 Q20 &amp; DS 2019 Q1 — Tabela Verdade)</h4>\n<p><em>Considere <code>P = Verdadeiro</code>, <code>Q = Falso</code> e <code>R = Verdadeiro</code>. Qual é o resultado lógico da expressão <code>(P E Q) OU (NAO Q E R)</code>?</em></p>\n<p><strong>Passo a passo:</strong></p>\n<ol>\n<li>Primeiro os parênteses da esquerda: <code>P E Q</code> = <code>V E F</code> = <strong><code>F</code></strong>.</li>\n<li>Agora o parêntese da direita: <code>NAO Q</code> = <code>NAO F</code> = <strong><code>V</code></strong>. Em seguida <code>V E R</code> = <code>V E V</code> = <strong><code>V</code></strong>.</li>\n<li>Por último o <code>OU</code> externo ligando os dois resultados: <code>F OU V</code> = <strong><code>V</code> (Verdadeiro)</strong>!</li>\n</ol>\n"}, {"id": "mod1a", "title": "Módulo 1A • Algoritmos, Fluxogramas, Teste de Mesa & Matrizes (Dias 2–3)", "html": "<h2 id=\"dia-2--algoritmos-fluxogramas-oficiais-decisão-encadeada-laços-de-repetição-e-teste-de-mesa\">Dia 2 — Algoritmos, Fluxogramas Oficiais, Decisão Encadeada, Laços de Repetição e Teste de Mesa</h2>\n<h3 id=\"-contexto-no-mundo-real-o-raciocínio-antes-do-código\">🎯 Contexto no Mundo Real: O Raciocínio Antes do Código</h3>\n<p>Antes de um arquiteto erguer um prédio de 20 andares, ele desenha a planta baixa. Na computação, antes de escrever centenas de linhas de Python, JavaScript ou C#, nós desenhamos a lógica da solução usando um <strong>Algoritmo</strong>.</p>\n<p>Pense no GPS do celular calculando uma rota até a Etec, ou no aplicativo do iFood conferindo se há entregador disponível, aplicando cupom de desconto, somando o frete e repetindo a verificação de estoque para cada item do carrinho. Tudo isso é formado por <strong>sequência, decisão (\"se/senão\") e repetição (\"enquanto houver itens\")</strong>. Se você não dominar a ordem em que a CPU percorre essas linhas, vai cair nas armadilhas do <strong>Teste de Mesa</strong>, que sempre aparece nas provas da Fundação FAT!</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Todo jogo que você abre roda um laço de repetição gigante nos bastidores (o famoso <em><strong>Game Loop</strong></em>):</p>\n<ul>\n<li><strong>Fluxograma = Árvore de Diálogo de RPG / Missão:</strong> O Losango ◇ é aquela encruzilhada de diálogo (<em>\"Você tem a chave da masmorra? Sim → abre o baú / Não → volta para o NPC\"</em>); o Retângulo ▭ é o cálculo de dano; o Paralelogramo ▱ é ler sua tecla <code>WASD</code> e desenhar os frames na tela.</li>\n<li><strong><code>while</code> (Pré-teste) = <code>while (hp &gt; 0)</code>:</strong> Enquanto tiver vida, você continua jogando. Se já entrar na arena com <code>hp == 0</code>, o laço roda <strong>0 vezes</strong> (nem começa!).</li>\n<li><strong><code>do...while</code> (Pós-teste) = Tela de <em>Respawn / Continue?</em>:</strong> Primeiro você vê o menu <em>\"Jogar Novamente? (S/N)\"</em> <strong>pelo menos 1 vez garantida</strong>, e só no final o programa checa se você clicou em Não para sair.</li>\n<li><strong><code>for</code> = Varrer os <em>slots</em> da mochila:</strong> Quando você sabe que o inventário tem exatamente <code>10</code> espaços (<code>i</code> de <code>0</code> até <code>9</code>), usa o <code>para/for</code> para checar item por item.</li>\n<li><strong>Teste de Mesa = Reconstruir uma luta de Boss turno a turno:</strong> Em vez de tentar adivinhar quanto de HP sobrou de cabeça, você anota <code>turno 1</code>, <code>turno 2</code>, <code>turno 3</code> numa tabelinha no papel até o boss cair — impossível errar conta simples assim!</li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--o-que-é-um-algoritmo-e-os-símbolos-do-fluxograma\">📚 Parte 1 — O que é um Algoritmo e os Símbolos do Fluxograma</h3>\n<p>Um <strong>algoritmo</strong> é uma sequência <strong>finita, ordenada e não ambígua</strong> de instruções lógicas para transformar entradas em saídas esperadas. Todo programa segue a tríade clássica <strong>E → P → S</strong>:</p>\n<ol>\n<li><strong>Entrada (<em>Input</em>):</strong> Receber dados externos (teclado, mouse, sensor, banco de dados).</li>\n<li><strong>Processamento (<em>Processing</em>):</strong> Calcular, comparar, ordenar e transformar dados na CPU/RAM.</li>\n<li><strong>Saída (<em>Output</em>):</strong> Devolver o resultado ao usuário ou a outro sistema (tela, impressora, arquivo).</li>\n</ol>\n<p>Podemos escrever um algoritmo de três formas: <strong>Descrição Narrativa</strong> (português comum), <strong>Pseudocódigo / Portugol</strong> (parecido com código) e <strong>Fluxograma</strong> (diagrama gráfico padrão ANSI/ISO).</p>\n<h4 id=\"os-4-símbolos-geométricos-que-a-banca-cobra-literalmente\">Os 4 Símbolos Geométricos que a Banca Cobra Literalmente</h4>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Desenho / Símbolo</th>\n<th style=\"text-align: left;\">Nome Oficial</th>\n<th style=\"text-align: left;\">Função Exata no Fluxograma</th>\n<th style=\"text-align: left;\">Exemplo Real dentro da Caixa</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>⬭ Oval / Elipse / Cápsula</strong></td>\n<td style=\"text-align: left;\"><strong>Terminal</strong></td>\n<td style=\"text-align: left;\">Marca obrigatoriamente apenas o <strong><code>Início</code></strong> e o <strong><code>Fim</code></strong> do algoritmo.</td>\n<td style=\"text-align: left;\"><code>Início</code> ou <code>Fim</code></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>▱ Paralelogramo</strong></td>\n<td style=\"text-align: left;\"><strong>Entrada / Saída (E/S)</strong></td>\n<td style=\"text-align: left;\">Interação externa: <strong>ler</strong> dados do teclado ou <strong>exibir</strong> resultados na tela.</td>\n<td style=\"text-align: left;\"><code>Ler nota1, nota2</code> / <code>Escrever media</code></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>▭ Retângulo</strong></td>\n<td style=\"text-align: left;\"><strong>Processamento</strong></td>\n<td style=\"text-align: left;\"><strong>Contas matemáticas, atribuições de variáveis</strong> e ações internas da máquina.</td>\n<td style=\"text-align: left;\"><code>media &lt;- (nota1 + nota2) / 2</code></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>◇ Losango</strong></td>\n<td style=\"text-align: left;\"><strong>Decisão / Condicional</strong></td>\n<td style=\"text-align: left;\">Avalia uma condição booleana (<code>V</code> ou <code>F</code>). <strong>Sempre tem 1 seta entrando e 2 setas saindo (<code>Sim</code> / <code>Não</code>).</strong></td>\n<td style=\"text-align: left;\"><code>media &gt;= 6.0?</code></td>\n</tr>\n</tbody>\n</table>\n<p><em>(Obs.: Pequenos círculos chamam-se <strong>conectores</strong> e setas indicam o <strong>fluxo de execução</strong>).</em></p>\n<h4 id=\"-exemplo-real-de-fluxograma-completo-aprovação-de-empréstimo\">💻 Exemplo Real de Fluxograma Completo (Aprovação de Empréstimo)</h4>\n<pre class=\"text\"><code>[ ⬭ Início ]\n     ↓\n[ ▱ Ler renda, parcela ]\n     ↓\n[ ▭ limite &lt;- renda * 0.30 ]\n     ↓\n[ ◇ parcela &lt;= limite? ] ──(NÃO)──→ [ ▱ Escrever &quot;Crédito Negado&quot; ] ──┐\n     │ (SIM)                                                           │\n     ↓                                                                 ↓\n[ ▱ Escrever &quot;Crédito Aprovado&quot; ] ────────────────────────────────→ [ ⬭ Fim ]\n</code></pre>\n<div class=\"callout callout-warning\">\n\n<p><strong>Pegadinha clássica:</strong> Nunca marque que <strong>Retângulo</strong> serve para decidir (<code>se/senão</code>), nem que <strong>Losango</strong> faz cálculos (<code>soma = a + b</code>). <strong>Processamento/Atribuição = Retângulo</strong>; <strong>Condicional/Decisão = Losango</strong>; <strong>Ler/Imprimir = Paralelogramo</strong>.</p>\n</div>\n\n<hr />\n<h3 id=\"-parte-2--estruturas-de-decisão-simples-composta-e-encadeada\">📚 Parte 2 — Estruturas de Decisão: Simples, Composta e Encadeada</h3>\n<h4 id=\"1-decisão-simples-se-vs-composta-se--senao\">1. Decisão Simples (<code>se</code>) vs. Composta (<code>se ... senao</code>)</h4>\n<ul>\n<li><strong>Simples:</strong> Executa um bloco apenas se for verdadeiro; se falso, não faz nada e segue em frente (<code>se saldo &lt; 0 entao avisar()</code>).</li>\n<li><strong>Composta:</strong> Oferece dois caminhos excludentes: se <code>V</code>, executa o bloco do <code>se</code>; se <code>F</code>, obrigatoriamente executa o bloco do <code>senao</code>. <strong>Nunca os dois juntos!</strong></li>\n</ul>\n<h4 id=\"2-a-pegadinha-do-encadeamento-se--senao-se-vs-vários-se-seguidos\">2. A Pegadinha do Encadeamento (<code>se ... senao se</code> vs. Vários <code>se</code> Seguidos!)</h4>\n<p>Compare estes dois códigos reais supondo <code>nota = 9.0</code>:</p>\n<p><strong>Código A — Condicional Encadeado (<code>else if</code>):</strong></p>\n<div class=\"sourceCode\" id=\"cb2\"><pre class=\"sourceCode javascript\"><code class=\"sourceCode javascript\"><span id=\"cb2-1\"><a href=\"#cb2-1\" aria-hidden=\"true\"></a><span class=\"cf\">if</span> (nota <span class=\"op\">&gt;=</span> <span class=\"fl\">9.0</span>) {</span>\n<span id=\"cb2-2\"><a href=\"#cb2-2\" aria-hidden=\"true\"></a>    conceito <span class=\"op\">=</span> <span class=\"st\">&quot;MB (Muito Bom)&quot;</span><span class=\"op\">;</span></span>\n<span id=\"cb2-3\"><a href=\"#cb2-3\" aria-hidden=\"true\"></a>} <span class=\"cf\">else</span> <span class=\"cf\">if</span> (nota <span class=\"op\">&gt;=</span> <span class=\"fl\">7.0</span>) {</span>\n<span id=\"cb2-4\"><a href=\"#cb2-4\" aria-hidden=\"true\"></a>    conceito <span class=\"op\">=</span> <span class=\"st\">&quot;B (Bom)&quot;</span><span class=\"op\">;</span></span>\n<span id=\"cb2-5\"><a href=\"#cb2-5\" aria-hidden=\"true\"></a>} <span class=\"cf\">else</span> <span class=\"cf\">if</span> (nota <span class=\"op\">&gt;=</span> <span class=\"fl\">5.0</span>) {</span>\n<span id=\"cb2-6\"><a href=\"#cb2-6\" aria-hidden=\"true\"></a>    conceito <span class=\"op\">=</span> <span class=\"st\">&quot;R (Regular)&quot;</span><span class=\"op\">;</span></span>\n<span id=\"cb2-7\"><a href=\"#cb2-7\" aria-hidden=\"true\"></a>} <span class=\"cf\">else</span> {</span>\n<span id=\"cb2-8\"><a href=\"#cb2-8\" aria-hidden=\"true\"></a>    conceito <span class=\"op\">=</span> <span class=\"st\">&quot;I (Insatisfatório)&quot;</span><span class=\"op\">;</span></span>\n<span id=\"cb2-9\"><a href=\"#cb2-9\" aria-hidden=\"true\"></a>}</span></code></pre></div>\n<p>Como <code>9.0 &gt;= 9.0</code> dá <strong>Verdadeiro</strong> no primeiro <code>if</code>, <code>conceito</code> vira <strong><code>\"MB\"</code></strong> e o programa <strong>PULA</strong> todos os <code>else if</code> abaixo! Mesmo <code>9.0</code> sendo <code>&gt;= 7.0</code> e <code>&gt;= 5.0</code>, eles nem são testados!</p>\n<p><strong>Código B — Múltiplos <code>if</code> Independentes (Erro clássico de iniciante!):</strong></p>\n<div class=\"sourceCode\" id=\"cb3\"><pre class=\"sourceCode javascript\"><code class=\"sourceCode javascript\"><span id=\"cb3-1\"><a href=\"#cb3-1\" aria-hidden=\"true\"></a><span class=\"cf\">if</span> (nota <span class=\"op\">&gt;=</span> <span class=\"fl\">9.0</span>) { conceito <span class=\"op\">=</span> <span class=\"st\">&quot;MB&quot;</span><span class=\"op\">;</span> }   <span class=\"co\">// Testa -&gt; V! conceito = &quot;MB&quot;</span></span>\n<span id=\"cb3-2\"><a href=\"#cb3-2\" aria-hidden=\"true\"></a><span class=\"cf\">if</span> (nota <span class=\"op\">&gt;=</span> <span class=\"fl\">7.0</span>) { conceito <span class=\"op\">=</span> <span class=\"st\">&quot;B&quot;</span><span class=\"op\">;</span> }    <span class=\"co\">// Testa de novo -&gt; V! SOBRESCREVE para &quot;B&quot;!</span></span>\n<span id=\"cb3-3\"><a href=\"#cb3-3\" aria-hidden=\"true\"></a><span class=\"cf\">if</span> (nota <span class=\"op\">&gt;=</span> <span class=\"fl\">5.0</span>) { conceito <span class=\"op\">=</span> <span class=\"st\">&quot;R&quot;</span><span class=\"op\">;</span> }    <span class=\"co\">// Testa de novo -&gt; V! SOBRESCREVE para &quot;R&quot;!</span></span></code></pre></div>\n<p>No Código B, um aluno nota 9 receberia <code>\"R\"</code> porque os três <code>if</code> são independentes e cada um foi apagando a variável! <strong>A banca adora colocar dois ou três <code>if</code> sem <code>else</code> em questões de saída na tela!</strong></p>\n<hr />\n<h3 id=\"-parte-3--estruturas-de-repetição-laços--loops-sem-confusão\">📚 Parte 3 — Estruturas de Repetição (Laços / <em>Loops</em>) Sem Confusão</h3>\n<p>Quase todo laço funcional precisa de <strong>3 pilares</strong> (se esquecer o 3º, o programa trava em <strong>loop infinito</strong>!):</p>\n<ol>\n<li><strong>Inicialização</strong> da variável de controle antes ou no cabeçalho (<code>i &lt;- 1</code>);</li>\n<li><strong>Condição de continuação ou parada</strong> (<code>enquanto i &lt;= 5</code>);</li>\n<li><strong>Atualização / Incremento</strong> dentro do corpo (<code>i &lt;- i + 1</code>).</li>\n</ol>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Estrutura</th>\n<th style=\"text-align: left;\">Momento do Teste</th>\n<th style=\"text-align: center;\">Mínimo de Execuções</th>\n<th style=\"text-align: left;\">Regra Lógica / Idioma</th>\n<th style=\"text-align: left;\">Caso de uso real</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong><code>enquanto ... faca</code> / <code>while</code></strong></td>\n<td style=\"text-align: left;\"><strong>Pré-teste</strong> (testa <strong>antes</strong> de entrar)</td>\n<td style=\"text-align: center;\"><strong>0 vezes</strong> (se já começar falsa, nem entra no bloco!)</td>\n<td style=\"text-align: left;\">Repete <strong>ENQUANTO</strong> a condição for <strong>VERDADEIRA</strong>.</td>\n<td style=\"text-align: left;\">Ler registros enquanto não chegar ao fim do arquivo; validar senha.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong><code>do ... while</code></strong> (C, Java, JS, PHP)</td>\n<td style=\"text-align: left;\"><strong>Pós-teste</strong> (executa primeiro, testa <strong>no final</strong>)</td>\n<td style=\"text-align: center;\"><strong>Pelo menos 1 vez garantida!</strong></td>\n<td style=\"text-align: left;\">Repete <strong>ENQUANTO</strong> a condição final for <strong>VERDADEIRA</strong>.</td>\n<td style=\"text-align: left;\">Menu interativo que precisa aparecer ao menos 1 vez na tela.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong><code>repita ... ate</code></strong> (Portugol / Pascal)</td>\n<td style=\"text-align: left;\"><strong>Pós-teste</strong> (executa primeiro, testa <strong>no final</strong>)</td>\n<td style=\"text-align: center;\"><strong>Pelo menos 1 vez garantida!</strong></td>\n<td style=\"text-align: left;\"><strong>Atenção:</strong> Repete <strong>ATÉ QUE</strong> a condição fique <strong>VERDADEIRA</strong> (ou seja, <strong>repete enquanto for FALSA e PARA quando der <code>V</code></strong>!).</td>\n<td style=\"text-align: left;\">Pedir idade até que digite um valor <code>&gt; 0</code>.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong><code>para ... de ... ate ... faca</code> / <code>for</code></strong></td>\n<td style=\"text-align: left;\"><strong>Pré-teste contado</strong></td>\n<td style=\"text-align: center;\"><strong>0 ou N vezes</strong></td>\n<td style=\"text-align: left;\">Contador automático (<code>inicio</code>, <code>fim</code>, <code>passo</code>).</td>\n<td style=\"text-align: left;\">Percorrer vetores e matrizes de tamanho conhecido.</td>\n</tr>\n</tbody>\n</table>\n<div class=\"callout callout-caution\">\n\n<p><strong>Pegadinha de Ouro (Apostas Q9 &amp; Portugol):</strong></p>\n<ul>\n<li>No <code>while (x &lt; 0)</code>, se <code>x = 5</code>, o bloco roda <strong>0 vezes</strong>.</li>\n<li>No <code>do { ... } while (x &lt; 0)</code>, se <code>x = 5</code>, o bloco roda <strong>1 vez inteira</strong> antes de testar <code>5 &lt; 0</code> e parar!</li>\n<li>E no Portugol <strong><code>repita ... ate (x == 5)</code></strong>: ele <strong>continua</strong> quando <code>x != 5</code> e <strong>sai</strong> quando <code>x</code> vira <code>5</code> (exatamente o inverso do <code>do...while</code>!).</li>\n</ul>\n</div>\n\n<hr />\n<h3 id=\"-parte-4--teste-de-mesa-passo-a-passo-o-método-anti-erro\">📚 Parte 4 — Teste de Mesa Passo a Passo (O Método Anti-Erro)</h3>\n<p><strong>Teste de Mesa</strong> (<em>Trace</em> ou <em>Dry Run</em>) é a técnica de simular o processador manualmente executando cada instrução e preenchendo uma tabela com uma coluna para cada variável e uma coluna para a condição/saída.</p>\n<p><strong>Regras sagradas para fazer no rascunho da prova:</strong></p>\n<ol>\n<li>Nunca confie na memória: <strong>risque</strong> o valor antigo quando uma variável for atualizada (<code>x &lt;- 2</code> → risca o <code>2</code> e escreve <code>4</code>).</li>\n<li>Na troca de valores entre duas variáveis (<code>A</code> e <code>B</code>), é <strong>obrigatório</strong> usar uma 3ª variável auxiliar:\n<ul>\n<li><code>aux &lt;- A; A &lt;- B; B &lt;- aux;</code></li>\n<li>Se fizer <code>A &lt;- B; B &lt;- A;</code> sem <code>aux</code>, o valor original de <code>A</code> é perdido para sempre e ambos ficam iguais a <code>B</code>!</li>\n</ul></li>\n<li>Fique atento ao <strong>último incremento</strong> antes de o laço terminar!</li>\n</ol>\n<h4 id=\"-exemplo-real-comentado-1-acumulador--filtro--contador\">💻 Exemplo Real Comentado #1: Acumulador + Filtro + Contador</h4>\n<p>Veja o algoritmo em Portugol que calcula a soma dos múltiplos de 3 entre 1 e 10 e conta quantos laços foram rodados:</p>\n<pre class=\"portugol\"><code>cont &lt;- 1\nsoma &lt;- 0\nachados &lt;- 0\nenquanto (cont &lt;= 7) faca\n    se (cont MOD 3 == 0) entao\n        soma &lt;- soma + cont\n        achados &lt;- achados + 1\n    fimse\n    cont &lt;- cont + 2\nfimenquanto\nescreva(soma, achados, cont)\n</code></pre>\n<p><strong>Tabela do Teste de Mesa Linha por Linha:</strong></p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Momento / Passo</th>\n<th style=\"text-align: center;\">Teste <code>cont &lt;= 7</code>?</th>\n<th style=\"text-align: center;\">Teste <code>cont MOD 3 == 0</code>?</th>\n<th style=\"text-align: center;\"><code>soma</code></th>\n<th style=\"text-align: center;\"><code>achados</code></th>\n<th style=\"text-align: center;\"><code>cont</code> (após <code>cont + 2</code>)</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Inicialização</strong></td>\n<td style=\"text-align: center;\">—</td>\n<td style=\"text-align: center;\">—</td>\n<td style=\"text-align: center;\"><code>0</code></td>\n<td style=\"text-align: center;\"><code>0</code></td>\n<td style=\"text-align: center;\"><code>1</code></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Volta 1 (<code>cont=1</code>)</strong></td>\n<td style=\"text-align: center;\"><code>1 &lt;= 7</code> (<strong>V</strong> entra)</td>\n<td style=\"text-align: center;\"><code>1 % 3 = 1</code> (<strong>F</strong> pula <code>se</code>)</td>\n<td style=\"text-align: center;\"><code>0</code></td>\n<td style=\"text-align: center;\"><code>0</code></td>\n<td style=\"text-align: center;\"><code>1 + 2 = 3</code></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Volta 2 (<code>cont=3</code>)</strong></td>\n<td style=\"text-align: center;\"><code>3 &lt;= 7</code> (<strong>V</strong> entra)</td>\n<td style=\"text-align: center;\"><code>3 % 3 = 0</code> (<strong>V</strong> entra <code>se</code>!)</td>\n<td style=\"text-align: center;\"><code>0 + 3 = 3</code></td>\n<td style=\"text-align: center;\"><code>1</code></td>\n<td style=\"text-align: center;\"><code>3 + 2 = 5</code></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Volta 3 (<code>cont=5</code>)</strong></td>\n<td style=\"text-align: center;\"><code>5 &lt;= 7</code> (<strong>V</strong> entra)</td>\n<td style=\"text-align: center;\"><code>5 % 3 = 2</code> (<strong>F</strong> pula <code>se</code>)</td>\n<td style=\"text-align: center;\"><code>3</code></td>\n<td style=\"text-align: center;\"><code>1</code></td>\n<td style=\"text-align: center;\"><code>5 + 2 = 7</code></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Volta 4 (<code>cont=7</code>)</strong></td>\n<td style=\"text-align: center;\"><code>7 &lt;= 7</code> (<strong>V</strong> entra)</td>\n<td style=\"text-align: center;\"><code>7 % 3 = 1</code> (<strong>F</strong> pula <code>se</code>)</td>\n<td style=\"text-align: center;\"><code>3</code></td>\n<td style=\"text-align: center;\"><code>1</code></td>\n<td style=\"text-align: center;\"><code>7 + 2 = 9</code></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Volta 5 (<code>cont=9</code>)</strong></td>\n<td style=\"text-align: center;\"><code>9 &lt;= 7</code> (<strong>F</strong> SAI!)</td>\n<td style=\"text-align: center;\"><em>(não executa)</em></td>\n<td style=\"text-align: center;\"><strong><code>3</code></strong></td>\n<td style=\"text-align: center;\"><strong><code>1</code></strong></td>\n<td style=\"text-align: center;\"><strong><code>9</code></strong></td>\n</tr>\n</tbody>\n</table>\n<p><strong>Saída impressa:</strong> <code>soma = 3</code>, <code>achados = 1</code>, <strong><code>cont = 9</code></strong>! Perceba como <code>cont</code> virou <strong><code>9</code></strong> no final da Volta 4 antes de falhar no teste <code>9 &lt;= 7</code>. Quem para no <code>7</code> cai no distrator clássico da banca!</p>\n<h4 id=\"-exemplo-real-comentado-2-teste-de-mesa-com-para-for--variável-auxiliar\">💻 Exemplo Real Comentado #2: Teste de Mesa com <code>para</code> (<em>for</em>) + Variável Auxiliar</h4>\n<div class=\"sourceCode\" id=\"cb5\"><pre class=\"sourceCode javascript\"><code class=\"sourceCode javascript\"><span id=\"cb5-1\"><a href=\"#cb5-1\" aria-hidden=\"true\"></a><span class=\"kw\">let</span> a <span class=\"op\">=</span> <span class=\"dv\">1</span><span class=\"op\">,</span> b <span class=\"op\">=</span> <span class=\"dv\">1</span><span class=\"op\">;</span></span>\n<span id=\"cb5-2\"><a href=\"#cb5-2\" aria-hidden=\"true\"></a><span class=\"cf\">for</span> (<span class=\"kw\">let</span> i <span class=\"op\">=</span> <span class=\"dv\">1</span><span class=\"op\">;</span> i <span class=\"op\">&lt;=</span> <span class=\"dv\">4</span><span class=\"op\">;</span> i<span class=\"op\">++</span>) {</span>\n<span id=\"cb5-3\"><a href=\"#cb5-3\" aria-hidden=\"true\"></a>    <span class=\"kw\">let</span> prox <span class=\"op\">=</span> a <span class=\"op\">+</span> b<span class=\"op\">;</span></span>\n<span id=\"cb5-4\"><a href=\"#cb5-4\" aria-hidden=\"true\"></a>    a <span class=\"op\">=</span> b<span class=\"op\">;</span></span>\n<span id=\"cb5-5\"><a href=\"#cb5-5\" aria-hidden=\"true\"></a>    b <span class=\"op\">=</span> prox<span class=\"op\">;</span></span>\n<span id=\"cb5-6\"><a href=\"#cb5-6\" aria-hidden=\"true\"></a>}</span>\n<span id=\"cb5-7\"><a href=\"#cb5-7\" aria-hidden=\"true\"></a><span class=\"bu\">console</span><span class=\"op\">.</span><span class=\"fu\">log</span>(a<span class=\"op\">,</span> b)<span class=\"op\">;</span></span></code></pre></div>\n<ul>\n<li><strong>Início:</strong> <code>a = 1</code>, <code>b = 1</code></li>\n<li><strong><code>i = 1</code> (<code>1 &lt;= 4</code> V):</strong> <code>prox = 2</code>, <code>a = 1</code>, <code>b = 2</code> → depois <code>i</code> vira <code>2</code></li>\n<li><strong><code>i = 2</code> (<code>2 &lt;= 4</code> V):</strong> <code>prox = 1 + 2 = 3</code>, <code>a = 2</code>, <code>b = 3</code> → <code>i</code> vira <code>3</code></li>\n<li><strong><code>i = 3</code> (<code>3 &lt;= 4</code> V):</strong> <code>prox = 2 + 3 = 5</code>, <code>a = 3</code>, <code>b = 5</code> → <code>i</code> vira <code>4</code></li>\n<li><strong><code>i = 4</code> (<code>4 &lt;= 4</code> V):</strong> <code>prox = 3 + 5 = 8</code>, <code>a = 5</code>, <code>b = 8</code> → <code>i</code> vira <code>5</code> (sai!)</li>\n<li><strong>Saída:</strong> <code>a = 5</code>, <code>b = 8</code> (sequência de Fibonacci!).</li>\n</ul>\n<hr />\n<h3 id=\"️️-dissecando-questões-no-estilo-exato-da-prova\">🕵️‍♂️ Dissecando Questões no Estilo Exato da Prova</h3>\n<h4 id=\"questão-resolvida-1-estilo-molde-4--teste-de-mesa-com-ds-2025-q9\">Questão Resolvida 1 (Estilo Molde 4 — Teste de Mesa com <code>DS 2025 Q9</code>)</h4>\n<p><em>Analise o algoritmo:</em> <code>x &lt;- 10; y &lt;- 4; enquanto (x &gt; y) faca { x &lt;- x - 2; y &lt;- y + 1; } escreva(x, y);</code> <em>Quais valores serão impressos?</em></p>\n<p><strong>Tabela rápida:</strong></p>\n<ul>\n<li>Início: <code>x = 10</code>, <code>y = 4</code>.</li>\n<li>Volta 1: <code>10 &gt; 4</code> (V) → <code>x</code> vira <code>8</code>, <code>y</code> vira <code>5</code>.</li>\n<li>Volta 2: <code>8 &gt; 5</code> (V) → <code>x</code> vira <code>6</code>, <code>y</code> vira <code>6</code>.</li>\n<li>Volta 3: <code>6 &gt; 6</code> (<strong>F!</strong> Pois é estritamente <code>&gt;</code>, não <code>&gt;=</code>!) → <strong>SAI DO LAÇO!</strong> <strong>Gabarito:</strong> Imprime <strong><code>x = 6</code> e <code>y = 6</code></strong>. <em>(Pegadinha: muita gente acha que <code>6 &gt; 6</code> ainda entra e marca <code>x = 4, y = 7</code>!).</em></li>\n</ul>\n<h4 id=\"questão-resolvida-2-estilo-molde-1--símbolos-de-fluxograma--laços\">Questão Resolvida 2 (Estilo Molde 1 — Símbolos de Fluxograma &amp; Laços)</h4>\n<p><em>Julgue os itens:</em></p>\n<ul>\n<li><em>I. No fluxograma padrão, o retângulo representa entrada e saída de dados via teclado/tela.</em></li>\n<li><em>II. A estrutura <code>do...while</code> garante que o bloco interno será executado pelo menos uma vez, pois o teste ocorre ao final.</em></li>\n<li><em>III. Se a condição inicial de um laço <code>while</code> for falsa desde a primeira leitura, suas instruções internas nunca serão executadas.</em></li>\n</ul>\n<p><strong>Análise:</strong></p>\n<ul>\n<li><strong>Item I é FALSO:</strong> Entrada e saída usam o <strong>paralelogramo</strong>; o retângulo representa <strong>processamento/atribuições</strong>.</li>\n<li><strong>Item II é VERDADEIRO:</strong> Pós-teste sempre roda ao menos 1 vez.</li>\n<li><strong>Item III é VERDADEIRO:</strong> Pré-teste barra na entrada se já nascer falso. <strong>Gabarito:</strong> Apenas <strong>II e III</strong>.</li>\n</ul>\n<hr><h2 id=\"dia-3--vetores-1d-matrizes-bidimensionais-ij-pilha-lifo-fila-fifo-e-recursividade\">Dia 3 — Vetores (1D), Matrizes Bidimensionais <code>[i][j]</code>, Pilha (LIFO), Fila (FIFO) e Recursividade</h2>\n<h3 id=\"-contexto-no-mundo-real-tabuleiros-carrinhos-e-a-pilha-do-ctrlz\">🎯 Contexto no Mundo Real: Tabuleiros, Carrinhos e a Pilha do \"Ctrl+Z\"</h3>\n<p>Imagine fazer um sistema para guardar as 40 notas de uma turma da Etec criando 40 variáveis chamadas <code>nota1</code>, <code>nota2</code>, ..., <code>nota40</code>. Além de trabalhoso, seria impossível usar um laço <code>for</code> para calcular a média! Ou imagine representar uma planilha do Excel, uma imagem digital em pixels ou o tabuleiro de um jogo da velha <code>3 × 3</code>. Para isso existem as <strong>estruturas de dados indexadas homogêneas</strong> (Vetores e Matrizes), capazes de armazenar dezenas ou milhões de valores sob um único nome na memória.</p>\n<p>Além delas, softwares reais dependem de regras rígidas sobre <strong>quem sai primeiro</strong>: quando você aperta <strong><code>Ctrl+Z</code></strong> no VS Code ou clica em <strong>Voltar</strong> no navegador, o sistema desfaz a <strong>última</strong> ação que você fez (uma <strong>Pilha</strong>). Já quando cinco pessoas mandam imprimir PDFs na impressora da escola, quem enviou <strong>primeiro</strong> imprime <strong>primeiro</strong> (uma <strong>Fila</strong>). Ambas caem com enorme frequência nas provas da FAT!</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Você já usa vetores, matrizes, filas e pilhas toda vez que abre o PC:</p>\n<ul>\n<li><strong>Vetor 1D (Base <code>0</code>) = Barra de Atalhos (<em>Hotbar</em>) numerada no inventário:</strong> Imagine 5 slots chamados <code>hotbar</code>: em programação, o primeiro slot é <code>hotbar[0]</code> (Espada), depois <code>[1]</code> (Arco), <code>[2]</code> (Picareta), <code>[3]</code> (Bloco) e o último é <code>hotbar[4]</code> (Poção). Se tentar acessar <code>hotbar[5]</code>, dá erro porque foi de <code>0</code> a <code>N-1</code>!</li>\n<li><strong>Matriz 2D <code>M[linha][coluna]</code> = Minimapa / Tabuleiro / Inventário em Grade:</strong> Cada quadradinho tem 2 coordenadas: primeiro qual <strong>fileira de cima pra baixo (<code>i</code>)</strong>, depois qual <strong>coluna da esquerda pra direita (<code>j</code>)</strong>. Na <strong>Diagonal Principal (<code>i == j</code>)</strong>, você anda na diagonal certinha <code>[0][0] → [1][1] → [2][2]</code>.</li>\n<li><strong>Fila (<code>FIFO</code>) vs. Pilha (<code>LIFO</code>) no Discord e no Matchmaking:</strong>\n<ul>\n<li><strong>Fila (<code>FIFO</code> — <em>First In, First Out</em>):</strong> É a <strong>fila do Matchmaking</strong> no Valorant/LoL/CS2 — o primeiro squad que clicou em \"Jogar\" é o primeiro que o servidor coloca na sala.</li>\n<li><strong>Pilha (<code>LIFO</code> — <em>Last In, First Out</em>):</strong> É o <strong><code>Ctrl+Z</code></strong> ou a pilha de <em>buffs/menus</em> abertos — se você abriu <code>Configurações → Áudio → Microfone</code>, ao apertar <code>ESC</code> você fecha <strong>o último menu que abriu (<code>Microfone</code>)</strong> primeiro!</li>\n</ul></li>\n<li><strong>Recursividade = Boneca Russa / <em>Call Stack</em>:</strong> Uma função que chama uma versão menor dela mesma até bater no <strong>Caso Base</strong> (o momento em que ela para de chamar e devolve os resultados de volta!).</li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--vetores-arrays-1d-e-indexação-base-zero\">📚 Parte 1 — Vetores (Arrays 1D) e Indexação Base Zero</h3>\n<p>Um <strong>vetor</strong> (<em>array</em> unidimensional) é uma estrutura composta <strong>homogênea</strong> — todas as posições guardam dados do <strong>mesmo tipo</strong> (ex.: só inteiros ou só strings) — disposta em posições contíguas na memória RAM e acessada por um <strong>índice numérico</strong>.</p>\n<h4 id=\"a-regra-de-ouro-dos-índices-base-0\">A Regra de Ouro dos Índices (Base <code>0</code>)</h4>\n<p>Em C, C++, Java, JavaScript, Python e PHP, a contagem das gavetas <strong>começa no índice <code>0</code></strong>, e <strong>NÃO no <code>1</code>!</strong> Logo, um vetor <code>notas</code> de tamanho <code>N = 5</code>:</p>\n<ul>\n<li>Possui índices válidos <strong><code>0, 1, 2, 3, 4</code></strong> (isto é, de <strong><code>0</code> até <code>N - 1</code></strong>!).</li>\n<li>Visualização na memória:</li>\n</ul>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Índice</th>\n<th style=\"text-align: center;\"><code>notas[0]</code></th>\n<th style=\"text-align: center;\"><code>notas[1]</code></th>\n<th style=\"text-align: center;\"><code>notas[2]</code></th>\n<th style=\"text-align: center;\"><code>notas[3]</code></th>\n<th style=\"text-align: center;\"><code>notas[4]</code></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Valor armazenado</strong></td>\n<td style=\"text-align: center;\"><code>8.5</code></td>\n<td style=\"text-align: center;\"><code>6.0</code></td>\n<td style=\"text-align: center;\"><code>9.0</code></td>\n<td style=\"text-align: center;\"><code>7.5</code></td>\n<td style=\"text-align: center;\"><code>10.0</code></td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li>Quanto vale <code>notas[2]</code>? Vale <strong><code>9.0</code></strong> (é o <strong>3º</strong> elemento, não o 2º!).</li>\n<li>O que acontece se você tentar acessar <code>notas[5]</code>? <strong>Erro fatal (<em>Index Out of Bounds</em> / estouro de limite)</strong> porque só vai até <code>4</code>!</li>\n</ul>\n<h4 id=\"-exemplo-real-comentado-varredura-com-laço-for-apostas-q10\">💻 Exemplo Real Comentado: Varredura com Laço <code>for</code> (Apostas Q10)</h4>\n<div class=\"sourceCode\" id=\"cb1\"><pre class=\"sourceCode javascript\"><code class=\"sourceCode javascript\"><span id=\"cb1-1\"><a href=\"#cb1-1\" aria-hidden=\"true\"></a><span class=\"kw\">let</span> v <span class=\"op\">=</span> [<span class=\"dv\">10</span><span class=\"op\">,</span> <span class=\"dv\">15</span><span class=\"op\">,</span> <span class=\"dv\">20</span><span class=\"op\">,</span> <span class=\"dv\">25</span>]<span class=\"op\">;</span></span>\n<span id=\"cb1-2\"><a href=\"#cb1-2\" aria-hidden=\"true\"></a><span class=\"kw\">let</span> soma <span class=\"op\">=</span> <span class=\"dv\">0</span><span class=\"op\">;</span></span>\n<span id=\"cb1-3\"><a href=\"#cb1-3\" aria-hidden=\"true\"></a><span class=\"cf\">for</span> (<span class=\"kw\">let</span> i <span class=\"op\">=</span> <span class=\"dv\">0</span><span class=\"op\">;</span> i <span class=\"op\">&lt;</span> v<span class=\"op\">.</span><span class=\"at\">length</span><span class=\"op\">;</span> i<span class=\"op\">++</span>) {</span>\n<span id=\"cb1-4\"><a href=\"#cb1-4\" aria-hidden=\"true\"></a>    <span class=\"cf\">if</span> (v[i] <span class=\"op\">%</span> <span class=\"dv\">2</span> <span class=\"op\">===</span> <span class=\"dv\">0</span>) {</span>\n<span id=\"cb1-5\"><a href=\"#cb1-5\" aria-hidden=\"true\"></a>        soma <span class=\"op\">=</span> soma <span class=\"op\">+</span> v[i]<span class=\"op\">;</span></span>\n<span id=\"cb1-6\"><a href=\"#cb1-6\" aria-hidden=\"true\"></a>    }</span>\n<span id=\"cb1-7\"><a href=\"#cb1-7\" aria-hidden=\"true\"></a>}</span>\n<span id=\"cb1-8\"><a href=\"#cb1-8\" aria-hidden=\"true\"></a><span class=\"co\">// i=0: v[0]=10 (par!) -&gt; soma = 10</span></span>\n<span id=\"cb1-9\"><a href=\"#cb1-9\" aria-hidden=\"true\"></a><span class=\"co\">// i=1: v[1]=15 (ímpar, ignora)</span></span>\n<span id=\"cb1-10\"><a href=\"#cb1-10\" aria-hidden=\"true\"></a><span class=\"co\">// i=2: v[2]=20 (par!) -&gt; soma = 30</span></span>\n<span id=\"cb1-11\"><a href=\"#cb1-11\" aria-hidden=\"true\"></a><span class=\"co\">// i=3: v[3]=25 (ímpar, ignora)</span></span>\n<span id=\"cb1-12\"><a href=\"#cb1-12\" aria-hidden=\"true\"></a><span class=\"co\">// Resultado final: soma = 30</span></span></code></pre></div>\n<div class=\"callout callout-warning\">\n\n<p><strong>Pegadinha de linguagem:</strong> Algumas provas em <strong>Portugol acadêmico (VisuAlg)</strong> declaram explicitamente <code>vetor[1..5] de inteiro</code> (começando em <code>1</code>). Leia sempre o cabeçalho da questão! Se estiver em JS, C, Java, Python ou PHP — ou se não disser <code>1..N</code> — a indexação começa obrigatoriamente em <strong><code>0</code></strong>.</p>\n</div>\n\n<hr />\n<h3 id=\"-parte-2--matrizes-bidimensionais-mij-e-diagonais\">📚 Parte 2 — Matrizes Bidimensionais (<code>M[i][j]</code>) e Diagonais</h3>\n<p>Uma <strong>matriz bidimensional</strong> é um \"vetor de vetores\" organizado como uma tabela de <strong>linhas (<code>i</code>)</strong> e <strong>colunas (<code>j</code>)</strong>. Convenção universal em computação: <strong><code>M[i][j]</code></strong> lê-se <strong>PRIMEIRO a linha <code>i</code></strong>, <strong>DEPOIS a coluna <code>j</code></strong>!</p>\n<p>Considere esta <strong>Matriz <code>M</code> de ordem <code>3 × 3</code></strong> (3 linhas e 3 colunas, base <code>0</code>):</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: center;\"><code>Linha (i) \\ Coluna (j)</code></th>\n<th style=\"text-align: center;\">Coluna <code>j = 0</code></th>\n<th style=\"text-align: center;\">Coluna <code>j = 1</code></th>\n<th style=\"text-align: center;\">Coluna <code>j = 2</code></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>Linha <code>i = 0</code></strong></td>\n<td style=\"text-align: center;\"><strong><code>5</code></strong> (<code>[0][0]</code>)</td>\n<td style=\"text-align: center;\"><code>8</code> (<code>[0][1]</code>)</td>\n<td style=\"text-align: center;\"><strong><code>2</code></strong> (<code>[0][2]</code>)</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>Linha <code>i = 1</code></strong></td>\n<td style=\"text-align: center;\"><code>4</code> (<code>[1][0]</code>)</td>\n<td style=\"text-align: center;\"><strong><code>7</code></strong> (<code>[1][1]</code>)</td>\n<td style=\"text-align: center;\"><code>9</code> (<code>[1][2]</code>)</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>Linha <code>i = 2</code></strong></td>\n<td style=\"text-align: center;\"><strong><code>6</code></strong> (<code>[2][0]</code>)</td>\n<td style=\"text-align: center;\"><code>1</code> (<code>[2][1]</code>)</td>\n<td style=\"text-align: center;\"><strong><code>3</code></strong> (<code>[2][2]</code>)</td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"as-4-regiões-clássicas-da-matriz-quadrada-de-ordem-n-aqui-n--3\">As 4 Regiões Clássicas da Matriz Quadrada de Ordem <code>N</code> (aqui <code>N = 3</code>)</h4>\n<ol>\n<li><strong>Diagonal Principal:</strong> Formada pelos elementos que descem do <strong>canto superior esquerdo ao canto inferior direito</strong>.\n<ul>\n<li><strong>Condição matemática exata:</strong> <strong><code>i == j</code></strong> (índice da linha igual ao da coluna!).</li>\n<li>Na matriz acima: <code>M[0][0] = 5</code>, <code>M[1][1] = 7</code>, <code>M[2][2] = 3</code>.</li>\n<li><strong>Soma da Diagonal Principal</strong> = <code>5 + 7 + 3 =</code> <strong><code>15</code></strong>.</li>\n</ul></li>\n<li><strong>Diagonal Secundária:</strong> Formada pelos elementos que descem do <strong>canto superior direito ao canto inferior esquerdo</strong>.\n<ul>\n<li><strong>Condição matemática exata:</strong> <strong><code>i + j == N - 1</code></strong> (aqui <code>i + j == 2</code>!).</li>\n<li>Na matriz acima: <code>M[0][2] = 2</code> (<code>0+2=2</code>), <code>M[1][1] = 7</code> (<code>1+1=2</code>), <code>M[2][0] = 6</code> (<code>2+0=2</code>).</li>\n<li><strong>Soma da Diagonal Secundária</strong> = <code>2 + 7 + 6 = 15</code>. <em>(Note que em DS 2025 Q10 a matriz tinha diagonais com valores diferentes justamente para pegar quem confundiu principal com secundária!)</em></li>\n</ul></li>\n<li><strong>Acima da Diagonal Principal:</strong> <code>j &gt; i</code> (<code>M[0][1], M[0][2], M[1][2]</code>).</li>\n<li><strong>Abaixo da Diagonal Principal:</strong> <code>i &gt; j</code> (<code>M[1][0], M[2][0], M[2][1]</code>).</li>\n</ol>\n<h4 id=\"-exemplo-real-comentado-laço-aninhado-for-dentro-de-for\">💻 Exemplo Real Comentado: Laço Aninhado (<code>for</code> dentro de <code>for</code>)</h4>\n<p>Observe como dois laços percorrem uma matriz inteira somando <strong>apenas</strong> a diagonal principal:</p>\n<div class=\"sourceCode\" id=\"cb2\"><pre class=\"sourceCode python\"><code class=\"sourceCode python\"><span id=\"cb2-1\"><a href=\"#cb2-1\" aria-hidden=\"true\"></a>M <span class=\"op\">=</span> [</span>\n<span id=\"cb2-2\"><a href=\"#cb2-2\" aria-hidden=\"true\"></a>    [<span class=\"dv\">1</span>, <span class=\"dv\">3</span>, <span class=\"dv\">5</span>],   <span class=\"co\"># linha i = 0</span></span>\n<span id=\"cb2-3\"><a href=\"#cb2-3\" aria-hidden=\"true\"></a>    [<span class=\"dv\">2</span>, <span class=\"dv\">4</span>, <span class=\"dv\">8</span>],   <span class=\"co\"># linha i = 1</span></span>\n<span id=\"cb2-4\"><a href=\"#cb2-4\" aria-hidden=\"true\"></a>    [<span class=\"dv\">1</span>, <span class=\"dv\">1</span>, <span class=\"dv\">1</span>]    <span class=\"co\"># linha i = 2</span></span>\n<span id=\"cb2-5\"><a href=\"#cb2-5\" aria-hidden=\"true\"></a>]</span>\n<span id=\"cb2-6\"><a href=\"#cb2-6\" aria-hidden=\"true\"></a>soma_dp <span class=\"op\">=</span> <span class=\"dv\">0</span></span>\n<span id=\"cb2-7\"><a href=\"#cb2-7\" aria-hidden=\"true\"></a><span class=\"cf\">for</span> i <span class=\"kw\">in</span> <span class=\"bu\">range</span>(<span class=\"dv\">3</span>):          <span class=\"co\"># i assume 0, 1, 2</span></span>\n<span id=\"cb2-8\"><a href=\"#cb2-8\" aria-hidden=\"true\"></a>    <span class=\"cf\">for</span> j <span class=\"kw\">in</span> <span class=\"bu\">range</span>(<span class=\"dv\">3</span>):      <span class=\"co\"># para cada i, j assume 0, 1, 2</span></span>\n<span id=\"cb2-9\"><a href=\"#cb2-9\" aria-hidden=\"true\"></a>        <span class=\"cf\">if</span> i <span class=\"op\">==</span> j:          <span class=\"co\"># só entra em [0][0], [1][1], [2][2]</span></span>\n<span id=\"cb2-10\"><a href=\"#cb2-10\" aria-hidden=\"true\"></a>            soma_dp <span class=\"op\">+=</span> M[i][j]</span>\n<span id=\"cb2-11\"><a href=\"#cb2-11\" aria-hidden=\"true\"></a></span>\n<span id=\"cb2-12\"><a href=\"#cb2-12\" aria-hidden=\"true\"></a><span class=\"bu\">print</span>(soma_dp)  <span class=\"co\"># 1 + 4 + 1 = 6!</span></span></code></pre></div>\n<div class=\"callout callout-caution\">\n\n<p><strong>Pegadinha da DS 2025 Q10:</strong> A banca perguntou a soma da <strong>diagonal principal</strong> da matriz <code>[[1,3,5],[2,4,8],[1,1,1]]</code> e colocou <strong><code>10</code></strong> nas alternativas (que é a soma da diagonal <strong>secundária</strong>: <code>5 + 4 + 1 = 10</code>). Desenhe sempre os índices <code>[0][0]</code>, <code>[1][1]</code>, <code>[2][2]</code> no rascunho antes de somar!</p>\n</div>\n\n<hr />\n<h3 id=\"-parte-3--estruturas-lineares-pilha-lifo-vs-fila-fifo\">📚 Parte 3 — Estruturas Lineares: Pilha (LIFO) vs. Fila (FIFO)</h3>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Critério</th>\n<th style=\"text-align: left;\">Pilha (<em>Stack</em>)</th>\n<th style=\"text-align: left;\">Fila (<em>Queue</em>)</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Princípio Oficial</strong></td>\n<td style=\"text-align: left;\"><strong>LIFO</strong> (<em>Last In, First Out</em> — <strong>Último</strong> a entrar, <strong>Primeiro</strong> a sair) ou <strong>FILO</strong></td>\n<td style=\"text-align: left;\"><strong>FIFO</strong> (<em>First In, First Out</em> — <strong>Primeiro</strong> a entrar, <strong>Primeiro</strong> a sair)</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Operação de Inserção</strong></td>\n<td style=\"text-align: left;\"><strong><code>PUSH</code></strong> (empilha no <strong>topo</strong>)</td>\n<td style=\"text-align: left;\"><strong><code>Enqueue</code></strong> / Inserir (entra no <strong>fim/cauda</strong>)</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Operação de Remoção</strong></td>\n<td style=\"text-align: left;\"><strong><code>POP</code></strong> (remove sempre do <strong>topo</strong>)</td>\n<td style=\"text-align: left;\"><strong><code>Dequeue</code></strong> / Remover (sai sempre da <strong>frente/cabeça</strong>)</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Exemplos Reais em TI</strong></td>\n<td style=\"text-align: left;\">Botão <strong>Voltar</strong> do navegador, <strong>Desfazer (<code>Ctrl+Z</code>)</strong>, <strong>Pilha de Chamadas (<em>Call Stack</em>)</strong> de funções</td>\n<td style=\"text-align: left;\"><strong>Fila de impressão (<em>Spooler</em>)</strong>, <strong>fila de mensagens/tickets</strong>, buffer de teclado</td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"-rastreamento-completo-de-pilha-baseado-em-ds-2019-q3\">💻 Rastreamento Completo de Pilha (Baseado em DS 2019 Q3)</h4>\n<p>Partindo de uma pilha vazia, execute:</p>\n<ol>\n<li><code>push(\"A\")</code> → Pilha: <code>[\"A\"]</code> <em>(Topo = A)</em></li>\n<li><code>push(\"B\")</code> → Pilha: <code>[\"A\", \"B\"]</code> <em>(Topo = B)</em></li>\n<li><code>push(\"C\")</code> → Pilha: <code>[\"A\", \"B\", \"C\"]</code> <em>(Topo = C)</em></li>\n<li><code>pop()</code> → Remove o <strong>último que entrou (<code>C</code>)</strong>! Sobra <code>[\"A\", \"B\"]</code> <em>(Topo = B)</em></li>\n<li><code>push(\"D\")</code> → Entra no topo: <code>[\"A\", \"B\", \"D\"]</code> <em>(Topo = D)</em></li>\n<li><code>pop()</code> → Remove o topo (<code>D</code>): Sobra <code>[\"A\", \"B\"]</code> <em>(Topo = B, Base = A)</em>.</li>\n</ol>\n<hr />\n<h3 id=\"-parte-4--funções-parâmetros-e-recursividade\">📚 Parte 4 — Funções, Parâmetros e Recursividade</h3>\n<p>Uma <strong>função</strong> (ou sub-rotina) é um bloco de código reutilizável com um nome que recebe <strong>parâmetros</strong> de entrada e devolve um valor (<code>return</code>). Uma função é chamada <strong>recursiva</strong> quando ela <strong>chama a si mesma dentro do próprio corpo</strong>, reduzindo um problema grande a versões menores dele mesmo.</p>\n<p>Toda função recursiva bem escrita possui <strong>duas partes obrigatórias</strong>:</p>\n<ol>\n<li><strong>Caso Base (Critério de Parada):</strong> A versão mais simples que tem resposta direta sem chamar a função novamente. <em>(Sem caso base, ocorre recursão infinita até estourar a memória RAM: erro <strong><code>Stack Overflow</code></strong>!)</em></li>\n<li><strong>Passo Recursivo:</strong> A função chama a si mesma aproximando o argumento do Caso Base.</li>\n</ol>\n<h4 id=\"-exemplo-real-comentado-fatorial-recursivo-fatorial4-info-2025-q21\">💻 Exemplo Real Comentado: Fatorial Recursivo <code>fatorial(4)</code> (INFO 2025 Q21)</h4>\n<p>Definição matemática: <strong><code>0! = 1</code></strong> e <strong><code>n! = n × (n - 1)!</code></strong>.</p>\n<div class=\"sourceCode\" id=\"cb3\"><pre class=\"sourceCode javascript\"><code class=\"sourceCode javascript\"><span id=\"cb3-1\"><a href=\"#cb3-1\" aria-hidden=\"true\"></a><span class=\"kw\">function</span> <span class=\"fu\">fat</span>(n) {</span>\n<span id=\"cb3-2\"><a href=\"#cb3-2\" aria-hidden=\"true\"></a>    <span class=\"cf\">if</span> (n <span class=\"op\">&lt;=</span> <span class=\"dv\">1</span>) <span class=\"cf\">return</span> <span class=\"dv\">1</span><span class=\"op\">;</span>        <span class=\"co\">// CASO BASE (0! = 1 e 1! = 1)</span></span>\n<span id=\"cb3-3\"><a href=\"#cb3-3\" aria-hidden=\"true\"></a>    <span class=\"cf\">return</span> n <span class=\"op\">*</span> <span class=\"fu\">fat</span>(n <span class=\"op\">-</span> <span class=\"dv\">1</span>)<span class=\"op\">;</span>       <span class=\"co\">// PASSO RECURSIVO (empilha chamadas na Call Stack!)</span></span>\n<span id=\"cb3-4\"><a href=\"#cb3-4\" aria-hidden=\"true\"></a>}</span>\n<span id=\"cb3-5\"><a href=\"#cb3-5\" aria-hidden=\"true\"></a><span class=\"bu\">console</span><span class=\"op\">.</span><span class=\"fu\">log</span>(<span class=\"fu\">fat</span>(<span class=\"dv\">4</span>))<span class=\"op\">;</span></span></code></pre></div>\n<p><strong>Como a Pilha de Chamadas (<em>Call Stack</em>) da CPU executa <code>fat(4)</code> (LIFO na veia!):</strong></p>\n<ul>\n<li><strong>Descida (empilhando <em>PUSH</em>):</strong>\n<ol>\n<li><code>fat(4)</code> precisa saber <code>4 * fat(3)</code> → pausa e chama <code>fat(3)</code></li>\n<li><code>fat(3)</code> precisa saber <code>3 * fat(2)</code> → pausa e chama <code>fat(2)</code></li>\n<li><code>fat(2)</code> precisa saber <code>2 * fat(1)</code> → pausa e chama <code>fat(1)</code></li>\n<li><code>fat(1)</code> bate no <strong>Caso Base</strong> → retorna <strong><code>1</code></strong>!</li>\n</ol></li>\n<li><strong>Subida (desempilhando <em>POP</em> e calculando):</strong> 5. <code>fat(2)</code> calcula <code>2 * 1 =</code> <strong><code>2</code></strong> 6. <code>fat(3)</code> calcula <code>3 * 2 =</code> <strong><code>6</code></strong> 7. <code>fat(4)</code> calcula <code>4 * 6 =</code> <strong><code>24</code></strong>!</li>\n</ul>\n<div class=\"callout callout-tip\">\n\n<p><strong>Lembrete matemático importante:</strong> <strong><code>0! = 1</code></strong> (por definição combinatória, existe 1 forma de organizar zero elementos) e acumulador de multiplicação/fatorial em laço deve começar com <strong><code>1</code></strong>, nunca <code>0</code>!</p>\n</div>\n\n<hr />\n<h3 id=\"️️-dissecando-questões-no-estilo-exato-da-prova\">🕵️‍♂️ Dissecando Questões no Estilo Exato da Prova</h3>\n<h4 id=\"questão-resolvida-1-baseada-em-ds-2019-q3--pilha-lifo\">Questão Resolvida 1 (Baseada em DS 2019 Q3 — Pilha LIFO)</h4>\n<p><em>Em uma estrutura do tipo Pilha vazia, inseriram-se os números 5, 10 e 15 (nessa ordem). Em seguida, aplicou-se uma operação de remoção (POP), inseriu-se o 20 e aplicou-se outro POP. Qual o elemento no TOPO e qual é a BASE restante?</em></p>\n<ul>\n<li>Passo a passo: <code>[]</code> → <code>[5]</code> → <code>[5,10]</code> → <code>[5,10,15]</code> → <code>POP</code> tira <code>15</code> (<code>[5,10]</code>) → <code>PUSH 20</code> (<code>[5,10,20]</code>) → <code>POP</code> tira <code>20</code> (<strong><code>[5,10]</code></strong>).</li>\n<li><strong>Resposta:</strong> Base = <strong><code>5</code></strong>, Topo = <strong><code>10</code></strong>. <em>(Se fosse uma <strong>Fila FIFO</strong>, o 1º <code>Dequeue</code> teria tirado o <code>5</code> em vez do <code>15</code>!)</em></li>\n</ul>\n<h4 id=\"questão-resolvida-2-baseada-em-matriz--índices\">Questão Resolvida 2 (Baseada em Matriz + Índices)</h4>\n<p><em>Considere a matriz quadrada <code>A</code> 3×3 preenchida pela regra <code>se (i + j == 2) entao A[i][j] &lt;- 10 senao A[i][j] &lt;- i * 2</code>. Qual o valor de <code>A[2][1]</code> e qual diagonal recebeu o valor 10?</em></p>\n<ul>\n<li>Em <code>A[2][1]</code>: <code>i = 2, j = 1</code>. Soma <code>2 + 1 = 3 != 2</code> (cai no <code>senao</code>!). Logo <code>A[2][1] = 2 * 2 =</code> <strong><code>4</code></strong>.</li>\n<li>Como <code>N = 3</code>, <code>i + j == N - 1</code> (<code>i + j == 2</code>) é exatamente a <strong>Diagonal Secundária</strong>!</li>\n</ul>\n"}, {"id": "mod1b", "title": "Módulo 1B • Frameworks, Git, Licenças, Engenharia, Scrum & POO (Dias 4–5)", "html": "<h2 id=\"dia-4--ecossistema-de-desenvolvimento-frameworks-editoresideswysiwyg-compilaçãobuildbundling-git-e-licenças\">Dia 4 — Ecossistema de Desenvolvimento: Frameworks, Editores/IDEs/WYSIWYG, Compilação/Build/Bundling, Git e Licenças</h2>\n<h3 id=\"-contexto-no-mundo-real-construindo-uma-casa-sem-fabricar-tijolo-por-tijolo\">🎯 Contexto no Mundo Real: Construindo uma Casa sem Fabricar Tijolo por Tijolo</h3>\n<p>Se uma equipe precisasse inventar toda vez o sistema de rotas URL, autenticação de login, layout responsivo de botões para celular e minificação de scripts do zero, criar um simples site de escola levaria meses. Por isso existem os <strong>frameworks</strong>, as <strong>IDEs</strong>, as ferramentas de <strong>build/bundling</strong>, o controle de versão <strong>Git</strong> e as <strong>licenças legais</strong> que dizem o que uma empresa pode ou não usar comercialmente sem ser processada. Esse módulo é puro <strong>Molde 1 (I, II, III)</strong> e <strong>Molde 2 (Lista com Intruso)</strong> na prova!</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Para conectar esse módulo técnico com o mundo de jogos, mods e Discord:</p>\n<ul>\n<li><strong>Framework vs. Biblioteca = Game Engine / Mod Loader:</strong> Uma biblioteca é igual baixar só um pacote de texturas — você usa se quiser. Um <strong>Framework</strong> (Laravel, Angular, React Native, Bootstrap) é tipo usar uma <strong>Engine</strong> (ou Forge/Fabric no Minecraft): já vem com o esqueleto pronto e você só encaixa o seu código nos lugares certos!</li>\n<li><strong>Compilação + <em>Build</em> + <em>Bundling</em>:</strong> Quando você cria mods ou um jogo, são dezenas de arquivos separados <code>.js</code>/<code>.cs</code> + texturas. O <em><strong>Build / Bundling</strong></em> empacota tudo num <code>.exe</code> ou <code>.pak</code> otimizado e minificado para abrir rápido sem fazer 200 carregamentos na internet.</li>\n<li><strong>Git (<code>branch</code>, <code>diff</code>, <code>merge</code>) = Save Slots antes de testar Mod arriscado:</strong> Em vez de editar o save oficial (<code>main</code>) e correr o risco de corromper tudo, você cria uma cópia paralela (<strong><code>git branch</code></strong>), compara exatamente o que mudou linha por linha (<strong><code>git diff</code></strong>) e, só quando tiver certeza de que não deu bug, junta de volta no save oficial (<strong><code>git merge</code></strong>)!</li>\n<li><strong>Licenças na vida real:</strong>\n<ul>\n<li><strong>Discord / Valorant / Spotify:</strong> São <em><strong>Freeware</strong></em> (grátis para baixar e usar, mas <strong>código-fonte 100% fechado</strong>, NÃO são Software Livre!).</li>\n<li><strong>OBS Studio / Godot Engine / Linux:</strong> São <strong>Software Livre / Open Source</strong> — você pode baixar o código no GitHub, estudar, modificar e recompilar legalmente!</li>\n<li><strong>EULA:</strong> Aquele textão jurídico de contrato que todo mundo aceita na Steam/Windows dizendo <em>\"não tente piratear, fazer engenharia reversa ou revender este jogo\"</em>.</li>\n</ul></li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--frameworks-web--mobile-o-que-são-e-onde-cada-um-atua\">📚 Parte 1 — Frameworks Web &amp; Mobile (O que São e Onde Cada Um Atua)</h3>\n<h4 id=\"biblioteca-vs-framework-qual-a-diferença-conceitual\">Biblioteca vs. Framework (Qual a diferença conceitual?)</h4>\n<ul>\n<li><strong>Biblioteca (<em>Library</em>):</strong> Uma caixa de ferramentas — <strong>você chama</strong> a função dela quando quiser (ex.: uma biblioteca de PDF ou matemática).</li>\n<li><strong>Framework:</strong> Um <strong>esqueleto arquitetural completo</strong> com regras prontas — ele segue a <strong>Inversão de Controle</strong> (o framework organiza o ciclo do app e chama o seu código nos pontos certos).</li>\n</ul>\n<p>Os <strong>4 Frameworks campeões</strong> nas provas da Fundação FAT:</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Tecnologia</th>\n<th style=\"text-align: left;\">Linguagem / Stack</th>\n<th style=\"text-align: left;\">Camada / Finalidade Oficial</th>\n<th style=\"text-align: left;\">Arquitetura &amp; Detalhes que Caem</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Bootstrap</strong></td>\n<td style=\"text-align: left;\">HTML + CSS + JS</td>\n<td style=\"text-align: left;\"><strong>Front-end Web Responsivo</strong> (<em>mobile-first</em>)</td>\n<td style=\"text-align: left;\">Sistema de <strong>Grid de 12 colunas</strong> (<code>container</code>, <code>row</code>, <code>col-md-6</code>), botões prontos (<code>btn btn-primary</code>), alertas (<code>alert alert-success</code>), navbar adaptável ao celular. <em>(DS 2019 Q18)</em></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Angular</strong></td>\n<td style=\"text-align: left;\"><strong>TypeScript</strong> / JS (Google)</td>\n<td style=\"text-align: left;\"><strong>Front-end Web SPA</strong> (<em>Single Page Application</em>)</td>\n<td style=\"text-align: left;\">Interfaces dinâmicas modulares baseadas em componentes, <em>data-binding</em> bidirecional e injeção de dependência.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Laravel</strong></td>\n<td style=\"text-align: left;\"><strong>PHP</strong></td>\n<td style=\"text-align: left;\"><strong>Back-end Web (Servidor)</strong></td>\n<td style=\"text-align: left;\">Segue o padrão <strong>MVC</strong> (<em>Model-View-Controller</em>): <code>Model</code> cuida dos dados/banco (ORM Eloquent), <code>View</code> exibe as telas (Blade), <code>Controller</code> recebe requisições HTTP e decide regras de negócio.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>React Native</strong></td>\n<td style=\"text-align: left;\">JavaScript / React (Meta)</td>\n<td style=\"text-align: left;\"><strong>Aplicativos Mobile Nativos (Android + iOS)</strong></td>\n<td style=\"text-align: left;\">Você escreve uma única base em JS/React e ele <strong>renderiza componentes nativos reais</strong> do Android/iOS (não é só um site dentro de navegador!).</td>\n</tr>\n</tbody>\n</table>\n<div class=\"callout callout-caution\">\n\n<p><strong>Pegadinha da DS 2025 Q7 (Molde 2 — Lista com Intruso):</strong> A banca listou frameworks válidos e misturou intrusos como <strong>Creative Commons</strong> (que é uma <strong>licença</strong> de direitos autorais!) e <strong>Adobe Creative Cloud</strong> (suíte de edição de imagem/vídeo como Photoshop/Illustrator). Também costuma inverter <strong>Laravel (back-end PHP)</strong> dizendo que é \"para interfaces móveis\".</p>\n</div>\n\n<hr />\n<h3 id=\"-parte-2--bloco-de-notas-vs-editor-de-código-vs-ide-vs-wysiwyg\">📚 Parte 2 — Bloco de Notas vs. Editor de Código vs. IDE vs. WYSIWYG</h3>\n<p>A Fundação FAT cobra literalmente a distinção entre as ferramentas onde programadores digitam e montam interfaces:</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Categoria</th>\n<th style=\"text-align: left;\">Recursos Incluídos</th>\n<th style=\"text-align: left;\">Exemplos Oficiais da Prova</th>\n<th style=\"text-align: left;\">NÃO confunda!</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Editor de Texto Simples</strong></td>\n<td style=\"text-align: left;\">Digita texto puro sem formatação (<code>UTF-8</code>), <strong>SEM</strong> destaque de sintaxe, autocompletar ou compilador.</td>\n<td style=\"text-align: left;\"><strong>Bloco de Notas (Notepad)</strong> do Windows, <code>TextEdit</code> simples</td>\n<td style=\"text-align: left;\">Embora dê para digitar HTML nele e salvar como <code>.html</code>, <strong>ele NÃO é uma IDE nem editor de código avançado</strong>!</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Editor de Código-Fonte</strong></td>\n<td style=\"text-align: left;\">Leve, rápido, oferece <strong>realce de sintaxe</strong> (colorir tags/comandos), numeração de linhas, indentação automática e <strong>extensões/plugins</strong>.</td>\n<td style=\"text-align: left;\"><strong>VS Code</strong> (<em>Visual Studio Code</em>), Sublime Text, Notepad++, Atom</td>\n<td style=\"text-align: left;\">VS Code puro, recém-instalado, é oficialmente classificado como <strong>Editor de Código</strong> (embora com plugins chegue perto de uma IDE).</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>IDE</strong> (<em>Integrated Development Environment</em>)</td>\n<td style=\"text-align: left;\"><strong>Ambiente Integrado de Desenvolvimento:</strong> junta em um só software Editor + <strong>Compilador/Interpretador + Depurador (<em>Debugger</em> c/ breakpoints) + Gerenciador de Projeto</strong>.</td>\n<td style=\"text-align: left;\"><strong>Visual Studio</strong> (Microsoft), <strong>Eclipse</strong>, <strong>IntelliJ IDEA</strong>, <strong>NetBeans</strong>, <strong>PyCharm</strong>, <strong>Android Studio</strong></td>\n<td style=\"text-align: left;\">Não confunda <em>Visual Studio</em> (IDE completa pesada) com <em>Visual Studio Code</em> (editor leve)!</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Editor WYSIWYG</strong> (<em>What You See Is What You Get</em>)</td>\n<td style=\"text-align: left;\"><em>\"O que você vê é o que você obtém\"</em>: criação visual <strong>arrastar-e-soltar</strong> que mostra o layout pronto ao vivo enquanto gera HTML/CSS nos bastidores.</td>\n<td style=\"text-align: left;\"><strong>Adobe Dreamweaver</strong> (modo Design), <strong>Wix</strong>, <strong>WordPress Gutenberg/Elementor</strong>, Google Sites</td>\n<td style=\"text-align: left;\">Foca em design visual sem precisar digitar toda tag HTML na mão.</td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h3 id=\"-parte-3--compilação-interpretação-build-e-bundling-ds-2025-q22--apostas-q8\">📚 Parte 3 — Compilação, Interpretação, <em>Build</em> e <em>Bundling</em> (DS 2025 Q22 &amp; Apostas Q8)</h3>\n<h4 id=\"1-compilador-vs-interpretador-vs-híbrido\">1. Compilador vs. Interpretador vs. Híbrido</h4>\n<ul>\n<li><strong>Compilador (ex.: C, C++, Go, Rust):</strong> Traduz <strong>todo o código-fonte de uma só vez</strong> antes da execução: <code>Código-Fonte (.c)</code> → <strong>Compilador</strong> → <code>Código-Objeto (.o/.obj, binário parcial)</code> → <strong>Linker (Ligador)</strong> (junta bibliotecas do sistema) → <code>Arquivo Executável (.exe / ELF)</code>.\n<ul>\n<li>Resultado: executa muito rápido sem precisar do código-fonte original no PC do cliente.</li>\n</ul></li>\n<li><strong>Interpretador (ex.: Python, JavaScript, PHP):</strong> Lê, traduz e executa o código <strong>linha por linha em tempo de execução</strong>. Mais portável e rápido de testar, porém exige o interpretador instalado.</li>\n<li><strong>Modelo Híbrido (Java / C#):</strong> Compila o fonte para um código intermediário chamado <em><strong>Bytecode</strong></em> (<code>.class</code> em Java), que depois roda na <strong>JVM (<em>Java Virtual Machine</em>)</strong>, garantindo alta portabilidade (<em>\"Write Once, Run Anywhere\"</em>).</li>\n</ul>\n<h4 id=\"2-o-que-são-build-bundling-minificação-e-tree-shaking-na-web-moderna\">2. O que são <em>Build</em>, <em>Bundling</em>, <em>Minificação</em> e <em>Tree Shaking</em> na Web Moderna?</h4>\n<p>Quando você faz um site grande em React ou Angular, você tem <strong>150 arquivos <code>.js</code> e <code>.css</code> separados</strong>. Se o navegador do usuário tivesse que fazer 150 downloads separados ao abrir a página, o site ficaria lentíssimo!</p>\n<ul>\n<li><strong><em>Build</em> (Construção):</strong> Processo automatizado completo que prepara o projeto para entrar no ar (produção): compila/transpila código moderno (ex.: TypeScript → JS), roda testes, otimiza imagens e gera a pasta final de distribuição (<code>dist/</code>).</li>\n<li><strong><em>Bundling</em> (Empacotamento):</strong> Realizado por <em>bundlers</em> (<strong>Webpack, Vite, Parcel</strong>). Consiste em <strong>agrupar dezenas de módulos/arquivos JS e CSS espalhados em poucos arquivos consolidados (<em>bundles</em>)</strong> para reduzir requisições HTTP na rede.</li>\n<li><strong>Minificação (<em>Minification</em>):</strong> Remove comentários, espaços em branco, quebras de linha e encurta nomes de variáveis internas (<code>contadorDeAlunos</code> vira <code>a</code>) apenas para o arquivo pesar menos KB na internet.</li>\n<li><strong><em>Tree Shaking</em>:</strong> Técnica em que o <em>bundler</em> detecta funções importadas que <strong>nunca foram usadas</strong> no projeto e as <strong>exclui do bundle final</strong> para economizar tamanho.</li>\n</ul>\n<hr />\n<h3 id=\"-parte-4--controle-de-versão-git-em-equipe-ds-2019-q26\">📚 Parte 4 — Controle de Versão Git em Equipe (DS 2019 Q26)</h3>\n<p>Imagine dois desenvolvedores editando <code>sistema.js</code> ao mesmo tempo: sem controle de versão, um sobrescreve o trabalho do outro ou perde tudo num erro! O <strong>Git</strong> é um <strong>sistema de controle de versão distribuído</strong> (cada dev tem o histórico completo na sua máquina; o <strong>GitHub/GitLab/Azure DevOps</strong> é a nuvem que hospeda repositórios Git).</p>\n<p><strong>Ciclo real e comandos obrigatórios para a prova:</strong></p>\n<ul>\n<li><code>git init</code> / <code>git clone &lt;url&gt;</code>: Inicia repositório novo na pasta / Baixa cópia completa de um remoto.</li>\n<li><code>git status</code>: Mostra em tempo real quais arquivos foram modificados ou estão aguardando <em>commit</em>.</li>\n<li><code>git add arquivo.js</code> (ou <code>git add .</code>): Envia as mudanças selecionadas para a <strong>Staging Area</strong> (área de preparação).</li>\n<li><code>git commit -m \"Corrige cálculo de média\"</code>: Grava um ponto definitivo no histórico (<strong>snapshot</strong>) com identificador único (hash).</li>\n<li><strong><code>git branch nova-tela</code></strong>: Cria uma <strong>ramificação paralela e isolada</strong> do código principal (<code>main</code>) para desenvolver uma novidade sem quebrar o sistema em produção! <em>(DS 2019 Q26)</em></li>\n<li><strong><code>git diff</code></strong>: <strong>Compara</strong> e exibe linha por linha as <strong>diferenças</strong> entre arquivos, commits ou branches.</li>\n<li><strong><code>git merge nova-tela</code></strong>: <strong>Funde (mescla)</strong> o trabalho pronto de uma <em>branch</em> dentro de outra (ex.: traz <code>nova-tela</code> para dentro da <code>main</code>).</li>\n<li><code>git push</code> / <code>git pull</code>: <strong>Envia</strong> seus commits para o servidor remoto / <strong>Baixa e mescla</strong> commits dos colegas do remoto para o seu PC.</li>\n</ul>\n<hr />\n<h3 id=\"-parte-5--licenças-de-software-software-livre-open-source-proprietário-freeware-eula\">📚 Parte 5 — Licenças de Software (Software Livre, Open Source, Proprietário, Freeware, EULA)</h3>\n<p>A Fundação FAT e o M-Tec cobram esse tema quase todo ano (<strong>DS 2025 Q23</strong>, <strong>M-Tec 2022 Q36</strong>)! Entenda a diferença jurídica real:</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Licença / Modelo</th>\n<th style=\"text-align: center;\">Código-Fonte é Aberto?</th>\n<th style=\"text-align: center;\">Pode Alterar e Redistribuir?</th>\n<th style=\"text-align: center;\">Precisa ser Grátis (<code>R$ 0</code>)?</th>\n<th style=\"text-align: left;\">Essência e Exemplos</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Software Livre (<em>Free Software</em> — FSF)</strong></td>\n<td style=\"text-align: center;\"><strong>SIM</strong></td>\n<td style=\"text-align: center;\"><strong>SIM</strong></td>\n<td style=\"text-align: center;\"><strong>NÃO obrigatoriamente!</strong> (<em>\"Free as in freedom, not free beer\"</em>)</td>\n<td style=\"text-align: left;\">Defende <strong>4 Liberdades Fundamentais</strong> (usar p/ qualquer fim, estudar/modificar, redistribuir cópias, distribuir modificações). Pode ser vendido por mídia ou suporte! Ex.: Linux (GPL), LibreOffice, GIMP.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Open Source (Código Aberto — OSI)</strong></td>\n<td style=\"text-align: center;\"><strong>SIM</strong></td>\n<td style=\"text-align: center;\"><strong>SIM</strong></td>\n<td style=\"text-align: center;\">Geralmente sim (alguns com modelo comercial em cima)</td>\n<td style=\"text-align: left;\">Foco prático/empresarial em desenvolvimento colaborativo, transparência e qualidade técnica. Principais licenças: <strong>MIT, Apache 2.0, BSD</strong> (permissivas) e <strong>GPL</strong> (<em>copyleft</em> — exige que derivados continuem livres).</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Proprietário / Comercial</strong></td>\n<td style=\"text-align: center;\"><strong>NÃO (Fechado)</strong></td>\n<td style=\"text-align: center;\"><strong>PROIBIDO</strong> (restringido por lei)</td>\n<td style=\"text-align: center;\">Pago (ou assinatura)</td>\n<td style=\"text-align: left;\">O dono retém todos os direitos autorais e entrega só o binário executável. O usuário aceita um <strong>EULA (<em>End User License Agreement</em>)</strong> proibindo engenharia reversa e cópia. Ex.: Windows, Photoshop, MS Office.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><em><strong>Freeware</strong></em></td>\n<td style=\"text-align: center;\"><strong>NÃO (Fechado)</strong></td>\n<td style=\"text-align: center;\"><strong>PROIBIDO modificar</strong></td>\n<td style=\"text-align: center;\"><strong>SIM (<code>R$ 0</code>)</strong></td>\n<td style=\"text-align: left;\">Distribui gratuitamente o executável, <strong>mas esconde o código-fonte</strong>! Ex.: Skype, WinRAR antigo/Adobe Reader. <strong>NÃO é Software Livre!</strong></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong><em>Shareware</em> / Trial</strong></td>\n<td style=\"text-align: center;\"><strong>NÃO</strong></td>\n<td style=\"text-align: center;\"><strong>PROIBIDO</strong></td>\n<td style=\"text-align: center;\">Grátis por tempo limitado (ex.: 30 dias)</td>\n<td style=\"text-align: left;\">Teste temporário antes de exigir compra da licença.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Assinatura / SaaS</strong></td>\n<td style=\"text-align: center;\">Geralmente fechado</td>\n<td style=\"text-align: center;\"><strong>PROIBIDO</strong></td>\n<td style=\"text-align: center;\">Mensalidade/anuidade contínua</td>\n<td style=\"text-align: left;\">Acesso ao software e atualizações enquanto pagar (ex.: Microsoft 365, Adobe Creative Cloud, Netflix).</td>\n</tr>\n</tbody>\n</table>\n<div class=\"callout callout-caution\">\n\n<p><strong>Pegadinha clássica (DS 2025 Q23 &amp; M-Tec 2022 Q36):</strong></p>\n<ol>\n<li><em>\"Todo Software Livre é necessariamente gratuito e nunca pode ser comercializado.\"</em> → <strong>FALSO!</strong> Você pode vender distribuição ou suporte de Software Livre; a liberdade é sobre <strong>acessar e modificar o código-fonte</strong>.</li>\n<li><em>\"Todo software gratuito (Freeware) é Open Source.\"</em> → <strong>FALSO!</strong> Se o código é fechado, é proprietário gratuito (<em>Freeware</em>), jamais Open Source ou Software Livre!</li>\n<li><strong>EULA</strong> (<em>End User License Agreement</em>) é o contrato de usuário final típico de software <strong>proprietário</strong>, definindo limites de instalação e proibindo redistribuição.</li>\n</ol>\n</div>\n\n<hr />\n<h3 id=\"️️-dissecando-questões-no-estilo-exato-da-prova\">🕵️‍♂️ Dissecando Questões no Estilo Exato da Prova</h3>\n<h4 id=\"questão-resolvida-1-baseada-em-ds-2019-q26--ds-2025-q19--git-e-editores\">Questão Resolvida 1 (Baseada em DS 2019 Q26 &amp; DS 2025 Q19 — Git e Editores)</h4>\n<p><em>Analise: I. O Bloco de Notas (Notepad) é classificado como IDE por permitir salvar arquivos <code>.html</code>. II. No Git, <code>git branch</code> cria linha paralela de desenvolvimento, <code>git diff</code> mostra diferenças entre versões e <code>git merge</code> une ramificações. III. Bundlers como Webpack agrupam vários módulos JS/CSS para diminuir requisições HTTP.</em></p>\n<ul>\n<li><strong>Item I é FALSO:</strong> Bloco de Notas é editor de texto simples (não possui compilador/depurador integrados).</li>\n<li><strong>Item II é VERDADEIRO:</strong> Definições exatas dos três comandos Git.</li>\n<li><strong>Item III é VERDADEIRO:</strong> Função exata de <em>bundling</em>. <strong>Gabarito:</strong> <strong>II e III corretas</strong>.</li>\n</ul>\n<h4 id=\"questão-resolvida-2-baseada-em-ds-2025-q23--licenças\">Questão Resolvida 2 (Baseada em DS 2025 Q23 — Licenças)</h4>\n<p><em>Qual alternativa está INCORRETA sobre licenciamento de software?</em></p>\n<ul>\n<li><em>A) Open Source exige acesso ao código-fonte para inspeção e melhoria.</em> (Verdadeira)</li>\n<li><em>B) Um software proprietário costuma ser distribuído sob um EULA restringindo cópia e modificação.</em> (Verdadeira)</li>\n<li><em>C) Software Livre proíbe cobrança financeira e exige distribuição de binários sem código-fonte.</em> (<strong>FALSA!</strong> Tanto permite venda quanto <strong>exige</strong> acesso ao código-fonte!). <strong>Gabarito:</strong> <strong>C</strong>.</li>\n</ul>\n<hr><h2 id=\"dia-5--engenharia-de-software-ciclos-de-vida-requisitos-swot-uml-scrumxp-testes-e-poo\">Dia 5 — Engenharia de Software, Ciclos de Vida, Requisitos, SWOT, UML, Scrum/XP, Testes e POO</h2>\n<h3 id=\"-contexto-no-mundo-real-por-que-só-sair-digitando-código-quebra-empresas\">🎯 Contexto no Mundo Real: Por que \"Só Sair Digitando Código\" Quebra Empresas?</h3>\n<p>Imagine construir um prédio de 15 andares sem engenheiro: você começa a empilhar tijolos no primeiro dia e, no quinto andar, descobre que esqueceu o poço do elevador e que o solo não aguenta o peso. Na década de 1960 ocorreu a chamada <strong>Crise do Software</strong> — projetos estouravam orçamentos em 300%, entregavam atrasados e cheios de falhas críticas porque programadores escreviam código direto sem planejar requisitos, arquitetura ou testes.</p>\n<p>É daí que nasce a <strong>Engenharia de Software</strong>: um conjunto sistemático de métodos, processos e boas práticas para entregar sistemas como <strong>Spotify, Nubank ou o NSA da Etec</strong> no prazo, dentro do orçamento, fáceis de manter e fiéis ao que o cliente realmente precisa.</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Você já viu na prática por que grandes estúdios de games falham ou acertam dependendo do jeito que desenvolvem o software:</p>\n<ul>\n<li><strong>Cascata vs. Ágil/Scrum (Atualizações de Jogos):</strong>\n<ul>\n<li>Fazer um jogo em <strong>Cascata</strong> é passar 5 anos desenvolvendo escondido sem testar com ninguém e lançar tudo de uma vez (e se os jogadores odiarem a mecânica, já era!).</li>\n<li>Usar <strong>Scrum (Ágil)</strong> é lançar uma base jogável rápido e ir soltando <em>Patches / Seasons</em> a cada <strong>Sprint</strong> de 2 semanas, fazendo a <strong>Daily de 15 min</strong> na call do Discord só para alinhar quem tá fazendo o quê e tirar bloqueios (<em>Scrum Master</em>) enquanto o <em>Product Owner</em> prioriza o que dá mais valor pro jogador!</li>\n</ul></li>\n<li><strong>Requisitos Funcionais (RF) vs. Não Funcionais (RNF) num Jogo Online:</strong>\n<ul>\n<li><strong>RF (\"O QUÊ faz\"):</strong> <em>\"O personagem pula, atira, recarrega e abre loja de skins.\"</em></li>\n<li><strong>RNF (\"COMO se comporta\"):</strong> <em>\"Rodar a <strong>120 FPS</strong>, ping abaixo de <strong>30 ms</strong>, anti-cheat ativo e ter <strong>Portabilidade</strong> para rodar tanto no Windows 11 quanto no Steam Deck (Linux)!\"</em></li>\n</ul></li>\n<li><strong>Os 4 Pilares da POO na Prática:</strong> Você cria um molde geral chamado classe <strong><code>Personagem</code> (Abstração)</strong>. Dele nascem <code>Mago</code> e <code>Guerreiro</code> aproveitando vida/nome/mover (<strong>Herança</strong>). A variável interna <code>hp</code> fica bloqueada como <code>private</code> pra ninguém editar com cheat (<strong>Encapsulamento</strong>). E quando os dois apertam <code>Q</code> (<code>usarHabilidade()</code>), cada classe solta um poder diferente com o mesmo comando (<strong>Polimorfismo</strong>)!</li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--modelos-de-ciclo-de-vida-cascata-vs-prototipação-vs-espiral-vs-ágil\">📚 Parte 1 — Modelos de Ciclo de Vida: Cascata vs. Prototipação vs. Espiral vs. Ágil</h3>\n<p>Todo software passa por fases: <strong>Levantamento de Requisitos → Projeto/Arquitetura → Implementação (Código) → Testes/Validação → Implantação → Manutenção</strong>. A forma como organizamos essas fases define o <strong>Modelo de Processo</strong>:</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Modelo</th>\n<th style=\"text-align: left;\">Como funciona passo a passo</th>\n<th style=\"text-align: left;\">Quando brilha</th>\n<th style=\"text-align: left;\">Onde costuma falhar</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Cascata (<em>Waterfall</em>)</strong> <em>(DS 2019 Q8)</em></td>\n<td style=\"text-align: left;\"><strong>Sequencial e rígido:</strong> uma fase só inicia quando a anterior for 100% encerrada e assinada (<em>Requisitos → Design → Código → Testes → Uso</em>).</td>\n<td style=\"text-align: left;\">Requisitos totalmente estáveis desde o dia 1 (ex.: software médico/aviação regulado).</td>\n<td style=\"text-align: left;\">Se o cliente mudar de ideia na metade, voltar fases é caríssimo; <strong>cliente só vê software pronto no final!</strong></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Prototipação</strong></td>\n<td style=\"text-align: left;\">Constrói rapidamente um <strong>protótipo</strong> (tela simulada ou rascunho) para o cliente testar, validar a ideia e corrigir cedo.</td>\n<td style=\"text-align: left;\">Quando o cliente não sabe explicar direito o que quer.</td>\n<td style=\"text-align: left;\">Risco de o cliente achar que o rascunho já é o sistema pronto.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Espiral (Boehm)</strong></td>\n<td style=\"text-align: left;\">Ciclos repetidos (<em>espiral</em>) onde <strong>cada volta começa com Análise de Riscos</strong>, protótipo, engenharia e avaliação.</td>\n<td style=\"text-align: left;\">Sistemas gigantes de alto risco financeiro ou técnico.</td>\n<td style=\"text-align: left;\">Complexo e caro gerenciar a análise de riscos em projetos pequenos.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Metodologias Ágeis</strong> <em>(Scrum, Kanban, XP)</em></td>\n<td style=\"text-align: left;\">Desenvolvimento <strong>iterativo e incremental</strong> em ciclos curtos (<em>Sprints</em> de 1–4 semanas). Entrega software funcionando rápido e <strong>abraça mudanças</strong>.</td>\n<td style=\"text-align: left;\">90% dos projetos modernos (apps, web, startups) onde o mercado muda toda hora.</td>\n<td style=\"text-align: left;\">Exige participação próxima do cliente e equipe madura/auto-organizável.</td>\n</tr>\n</tbody>\n</table>\n<div class=\"callout callout-warning\">\n\n<p><strong>Pegadinha clássica (DS 2019 Q8):</strong> No <strong>Modelo em Cascata</strong>, as fases avançam de forma <strong>sequencial descendente</strong> e cada etapa deve ser concluída antes de passar para a próxima — o erro nas alternativas é afirmar que <em>\"o modelo Cascata entrega incrementos semanais ao cliente sem documentação prévia\"</em> (isso é Ágil!).</p>\n</div>\n\n<hr />\n<h3 id=\"-parte-2--engenharia-de-requisitos-estudo-de-viabilidade-e-análise-swot\">📚 Parte 2 — Engenharia de Requisitos, Estudo de Viabilidade e Análise SWOT</h3>\n<p>Antes de escrever código, o Analista de Sistemas conversa com os <em>stakeholders</em> (partes interessadas: clientes, usuários, diretoria) para levantar os <strong>Requisitos</strong> e realizar o <strong>Estudo de Viabilidade</strong>.</p>\n<h4 id=\"1-estudo-de-viabilidade-info-2025-q23--apostas-q12\">1. Estudo de Viabilidade (<em>INFO 2025 Q23 &amp; Apostas Q12</em>)</h4>\n<p>Responde à pergunta: <em>\"Vale a pena e é possível fazer este sistema?\"</em> Analisa 3 frentes:</p>\n<ul>\n<li><strong>Viabilidade Técnica:</strong> Temos tecnologia, servidores, APIs e equipe capaz de construir?</li>\n<li><strong>Viabilidade Econômica / Financeira:</strong> O benefício/lucro (<em>ROI</em>) compensa o custo de desenvolvimento e manutenção?</li>\n<li><strong>Viabilidade Operacional:</strong> Os funcionários e usuários reais vão conseguir e querer operar o sistema no dia a dia?</li>\n</ul>\n<h4 id=\"2-requisitos-funcionais-rf-vs-requisitos-não-funcionais-rnf\">2. Requisitos Funcionais (RF) vs. Requisitos Não Funcionais (RNF)</h4>\n<p>Vamos aplicar ao exemplo real de um <strong>aplicativo de delivery (tipo iFood)</strong>:</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Tipo</th>\n<th style=\"text-align: left;\">O que descreve</th>\n<th style=\"text-align: left;\">Exemplos reais no App de Delivery</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Requisito Funcional (RF)</strong></td>\n<td style=\"text-align: left;\"><strong>O QUE</strong> o sistema faz — ações, serviços, regras de cálculo e telas visíveis.</td>\n<td style=\"text-align: left;\"><strong>RF01:</strong> Permitir cadastro de cliente com CPF.<br><strong>RF02:</strong> Calcular taxa de entrega por distância.<br><strong>RF03:</strong> Permitir pagamento via Pix ou cartão.<br><strong>RF04:</strong> Cancelar pedido em até 2 minutos.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Requisito Não Funcional (RNF)</strong></td>\n<td style=\"text-align: left;\"><strong>COMO</strong> o sistema se comporta — restrições de qualidade, desempenho, segurança, <strong>portabilidade</strong>, usabilidade e normas.</td>\n<td style=\"text-align: left;\"><strong>RNF01 (Desempenho):</strong> Carregar cardápio em <strong>menos de 2 segundos</strong>.<br><strong>RNF02 (Segurança):</strong> Senhas criptografadas com BCrypt e tráfego <strong>HTTPS</strong>.<br><strong>RNF03 (Disponibilidade):</strong> Funcionar 99,9% do tempo na Black Friday.<br><strong>RNF04 (Portabilidade):</strong> <em>(DS 2019 Q10)</em> Poder ser instalado/transferido entre <strong>Android, iOS e Windows/Linux</strong> facilmente!</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Critérios de um Bom Requisito <em>(INFO 2025 Q22)</em>:</strong> Um requisito bem escrito nunca pode dizer <em>\"O sistema deve ser rápido e bonito\"</em> (vago!). Ele deve ser <strong>Claro, Não Ambíguo, Verificável/Testável</strong> (<em>\"responder em até 2 segundos\"</em>), <strong>Consistente</strong> (não contradizer outro RF) e <strong>Rastreável</strong>.</p>\n<h4 id=\"3-análise-swot--fofa-m-tec-2022-q29--sim2-q30\">3. Análise SWOT / FOFA <em>(M-Tec 2022 Q29 &amp; Sim2 Q30)</em></h4>\n<p>Ferramenta de planejamento estratégico para avaliar negócios/projetos em 4 quadrantes:</p>\n<ul>\n<li><strong>Ambiente Interno (controlável pela empresa):</strong>\n<ul>\n<li><strong>S — <em>Strengths</em> (Forças):</strong> Vantagens internas (ex.: equipe sênior experiente, marca forte).</li>\n<li><strong>W — <em>Weaknesses</em> (Fraquezas):</strong> Pontos fracos internos (ex.: servidor antigo, falta de suporte 24h).</li>\n</ul></li>\n<li><strong>Ambiente Externo (mercado/governo — fora do controle direto):</strong>\n<ul>\n<li><strong>O — <em>Opportunities</em> (Oportunidades):</strong> Cenários externos favoráveis (ex.: lei incentivando digitalização, concorrente faliu).</li>\n<li><strong>T — <em>Threats</em> (Ameaças):</strong> Riscos externos (ex.: entrada de gigante estrangeiro no mercado, alta do dólar).</li>\n</ul></li>\n</ul>\n<hr />\n<h3 id=\"-parte-3--uml-linguagem-de-modelagem-unificada-e-dicionário-de-dados\">📚 Parte 3 — UML (Linguagem de Modelagem Unificada) e Dicionário de Dados</h3>\n<p>A <strong>UML</strong> não é uma linguagem de programação — é a <strong>notação visual padrão</strong> usada mundialmente para desenhar sistemas orientados a objetos <em>(M-Tec 2022 Q30 &amp; INFO 2025 Q24)</em>.</p>\n<ol>\n<li><strong>Diagrama de Casos de Uso (<em>Use Case Diagram</em> — Comportamental):</strong>\n<ul>\n<li>Mostra <strong>quem</strong> usa o sistema e <strong>o que</strong> faz, visto pelo olhar do usuário externo.</li>\n<li><strong>Elementos principais:</strong> <strong>Ator</strong> (bonequinho — pode ser humano <em>Aluno</em> ou outro sistema externo <em>Banco</em>), <strong>Caso de Uso</strong> (elipse com verbo no infinitivo: <em>\"Realizar Matrícula\"</em>) e linhas de associação.</li>\n<li><strong>Relacionamentos especiais:</strong> <code>&lt;&lt;include&gt;&gt;</code> (obrigatório sempre, ex.: <em>Fazer Transferência</em> sempre inclui <em>Validar Senha</em>) e <code>&lt;&lt;extend&gt;&gt;</code> (opcional sob condição, ex.: <em>Solicitar Comprovante PDF</em>).</li>\n</ul></li>\n<li><strong>Diagrama de Classes (Estrutural / Estático):</strong>\n<ul>\n<li>Cada classe é um retângulo com 3 partes: <strong>Nome da Classe</strong> (ex.: <code>Aluno</code>), <strong>Atributos</strong> (<code>- nome: string</code>, <code>+ ra: int</code>) e <strong>Métodos</strong> (<code>+ calcularMedia(): float</code>).</li>\n<li>Símbolos de visibilidade: <strong><code>+</code> Público (<code>public</code>)</strong>, <strong><code>-</code> Privado (<code>private</code>)</strong>, <strong><code>#</code> Protegido (<code>protected</code>)</strong>.</li>\n</ul></li>\n<li><strong>Dicionário de Dados <em>(M-Tec 2022 Q32)</em>:</strong>\n<ul>\n<li>Documento/catálogo complementar onde cada dado do sistema é detalhado com precisão:</li>\n</ul></li>\n</ol>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Nome do Campo</th>\n<th style=\"text-align: left;\">Tipo &amp; Tamanho</th>\n<th style=\"text-align: center;\">Obrigatório?</th>\n<th style=\"text-align: left;\">Domínio / Regra de Validação</th>\n<th style=\"text-align: left;\">Descrição</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><code>cpf_aluno</code></td>\n<td style=\"text-align: left;\"><code>CHAR(11)</code></td>\n<td style=\"text-align: center;\">Sim (<code>NOT NULL</code>)</td>\n<td style=\"text-align: left;\">Apenas dígitos <code>0–9</code>, único (<code>UNIQUE</code>)</td>\n<td style=\"text-align: left;\">CPF do estudante sem pontos/traços</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><code>nota_final</code></td>\n<td style=\"text-align: left;\"><code>DECIMAL(4,2)</code></td>\n<td style=\"text-align: center;\">Não</td>\n<td style=\"text-align: left;\">De <code>0.00</code> até <code>10.00</code></td>\n<td style=\"text-align: left;\">Média calculada do módulo</td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h3 id=\"-parte-4--scrum-kanban-xp-extreme-programming-e-pirâmide-de-testes\">📚 Parte 4 — Scrum, Kanban, XP (<em>Extreme Programming</em>) e Pirâmide de Testes</h3>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Framework / Prática</th>\n<th style=\"text-align: left;\">Componentes e Definições Exatas para a Prova</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Scrum — Os 3 Papéis</strong></td>\n<td style=\"text-align: left;\"><strong>Product Owner (PO):</strong> Representa cliente/negócio; <strong>dono do <em>Product Backlog</em></strong>; define <strong>O QUÊ</strong> construir e em que ordem de prioridade de valor.<br><strong>Scrum Master (SM):</strong> <strong>Líder servidor/facilitador</strong>; garante o uso correto do Scrum e <strong>remove impedimentos</strong> do time. <em>(NÃO é chefe tradicional que distribui ordens nem arquiteto de código!)</em><br><strong>Time de Desenvolvimento (<em>Developers</em>):</strong> Equipe técnica multidisciplinar e <strong>auto-organizável</strong> que decide <strong>COMO</strong> implementar e estima as tarefas.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Scrum — Eventos (<em>Timeboxes</em>)</strong></td>\n<td style=\"text-align: left;\"><strong>Sprint:</strong> Ciclo curto e fixo (geralmente 1 a 4 semanas) que entrega Incremento pronto.<br><strong>Daily Scrum:</strong> Reunião diária curta de <strong>no máximo 15 minutos</strong>, em pé, para sincronizar o trabalho das próximas 24h e apontar impedimentos. <em>(DS 2019 Q12)</em><br><strong>Sprint Review</strong> (mostra software funcionando aos clientes) e <strong>Sprint Retrospective</strong> (melhoria interna do processo do time).</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Kanban</strong></td>\n<td style=\"text-align: left;\">Sistema visual com <strong>quadro de cartões e colunas</strong> (<em>Backlog → Fazendo → Em Teste → Feito</em>) focado em fluxo contínuo e <strong>limitação do trabalho em progresso (WIP — <em>Work In Progress</em>)</strong> para evitar gargalos.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>XP — <em>Pair Programming</em></strong> <em>(DS 2019 Q24)</em></td>\n<td style=\"text-align: left;\"><strong>Programação em Par:</strong> <strong>Dois programadores compartilham o mesmo computador</strong> — o <strong>Piloto (<em>Driver</em>)</strong> digita o código focado na linha atual, enquanto o <strong>Copiloto (<em>Navigator</em>)</strong> revisa erros em tempo real e pensa na estratégia/arquitetura, alternando papéis!</td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"os-4-níveis-oficiais-de-teste-de-software-ds-2019-q25\">Os 4 Níveis Oficiais de Teste de Software <em>(DS 2019 Q25)</em></h4>\n<ol>\n<li><strong>Teste de Unidade (Unitário):</strong> Verifica a <strong>menor unidade isolada</strong> do software (uma única função ou método, ex.: testar <code>calcularFrete(10)</code> sem acessar banco de dados real).</li>\n<li><strong>Teste de Integração:</strong> Verifica se <strong>módulos combinados</strong> conversam corretamente (ex.: Controller + Banco MySQL + Gateway de pagamento).</li>\n<li><strong>Teste de Sistema:</strong> Testa a aplicação inteira integrada de ponta a ponta simulando um ambiente de produção.</li>\n<li><strong>Teste de Aceitação (UAT):</strong> Validação final junto ao cliente/PO confirmando se os requisitos do contrato foram atendidos.</li>\n</ol>\n<hr />\n<h3 id=\"-parte-5--programação-orientada-a-objetos-poo-classes-objetos-e-os-4-pilares\">📚 Parte 5 — Programação Orientada a Objetos (POO): Classes, Objetos e os 4 Pilares</h3>\n<p>Na POO, trazemos coisas do mundo real para dentro do código usando dois conceitos base:</p>\n<ul>\n<li><strong>Classe:</strong> É o <strong>molde / projeto</strong> (ex.: a planta de um carro ou o formulário em branco de <code>ContaBancaria</code>, definindo <strong>Atributos</strong> = características/dados e <strong>Métodos</strong> = ações/comportamentos).</li>\n<li><strong>Objeto:</strong> É uma <strong>instância concreta criada em memória RAM</strong> a partir da classe (ex.: a conta real nº <code>1020-5</code> da <code>Ana</code>, com saldo <code>R$ 500</code>, e outra conta <code>9988-1</code> do <code>João</code>, com saldo <code>R$ 1200</code>).</li>\n</ul>\n<h4 id=\"-exemplo-real-comentado-com-os-4-pilares-da-poo-ds-2019-q27\">💻 Exemplo Real Comentado com os 4 Pilares da POO <em>(DS 2019 Q27)</em></h4>\n<div class=\"sourceCode\" id=\"cb1\"><pre class=\"sourceCode python\"><code class=\"sourceCode python\"><span id=\"cb1-1\"><a href=\"#cb1-1\" aria-hidden=\"true\"></a><span class=\"kw\">class</span> Animal:                           <span class=\"co\"># ABSTRAÇÃO: só atributos/métodos essenciais ao sistema</span></span>\n<span id=\"cb1-2\"><a href=\"#cb1-2\" aria-hidden=\"true\"></a>    <span class=\"kw\">def</span> <span class=\"fu\">__init__</span>(<span class=\"va\">self</span>, nome, peso):</span>\n<span id=\"cb1-3\"><a href=\"#cb1-3\" aria-hidden=\"true\"></a>        <span class=\"va\">self</span>.__nome <span class=\"op\">=</span> nome              <span class=\"co\"># ENCAPSULAMENTO: __ privado! Protegido de acesso direto externo</span></span>\n<span id=\"cb1-4\"><a href=\"#cb1-4\" aria-hidden=\"true\"></a>        <span class=\"va\">self</span>.__peso <span class=\"op\">=</span> peso</span>\n<span id=\"cb1-5\"><a href=\"#cb1-5\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-6\"><a href=\"#cb1-6\" aria-hidden=\"true\"></a>    <span class=\"kw\">def</span> get_nome(<span class=\"va\">self</span>):                 <span class=\"co\"># Interface pública segura para leitura controlada</span></span>\n<span id=\"cb1-7\"><a href=\"#cb1-7\" aria-hidden=\"true\"></a>        <span class=\"cf\">return</span> <span class=\"va\">self</span>.__nome</span>\n<span id=\"cb1-8\"><a href=\"#cb1-8\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-9\"><a href=\"#cb1-9\" aria-hidden=\"true\"></a>    <span class=\"kw\">def</span> emitir_som(<span class=\"va\">self</span>):               <span class=\"co\"># Método base</span></span>\n<span id=\"cb1-10\"><a href=\"#cb1-10\" aria-hidden=\"true\"></a>        <span class=\"cf\">return</span> <span class=\"st\">&quot;...&quot;</span></span>\n<span id=\"cb1-11\"><a href=\"#cb1-11\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-12\"><a href=\"#cb1-12\" aria-hidden=\"true\"></a><span class=\"kw\">class</span> Cachorro(Animal):                 <span class=\"co\"># HERANÇA: Cachorro herda nome, peso e get_nome() de Animal!</span></span>\n<span id=\"cb1-13\"><a href=\"#cb1-13\" aria-hidden=\"true\"></a>    <span class=\"kw\">def</span> emitir_som(<span class=\"va\">self</span>):               <span class=\"co\"># POLIMORFISMO: sobrescreve emitir_som() com comportamento próprio!</span></span>\n<span id=\"cb1-14\"><a href=\"#cb1-14\" aria-hidden=\"true\"></a>        <span class=\"cf\">return</span> <span class=\"st\">&quot;Au au!&quot;</span></span>\n<span id=\"cb1-15\"><a href=\"#cb1-15\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-16\"><a href=\"#cb1-16\" aria-hidden=\"true\"></a><span class=\"kw\">class</span> Gato(Animal):                     <span class=\"co\"># HERANÇA</span></span>\n<span id=\"cb1-17\"><a href=\"#cb1-17\" aria-hidden=\"true\"></a>    <span class=\"kw\">def</span> emitir_som(<span class=\"va\">self</span>):               <span class=\"co\"># POLIMORFISMO: mesmo nome de método, resposta diferente!</span></span>\n<span id=\"cb1-18\"><a href=\"#cb1-18\" aria-hidden=\"true\"></a>        <span class=\"cf\">return</span> <span class=\"st\">&quot;Miau!&quot;</span></span></code></pre></div>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Os 4 Pilares Oficiais da POO</th>\n<th style=\"text-align: left;\">Significado exato que cai na prova</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>1. Abstração</strong></td>\n<td style=\"text-align: left;\">Focar apenas nos atributos e comportamentos essenciais do problema real, ignorando detalhes irrelevantes.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>2. Encapsulamento</strong></td>\n<td style=\"text-align: left;\"><strong>Ocultar e proteger dados internos</strong> (<code>private</code>) para evitar alterações inválidas (ex.: <code>saldo = -99999</code>), liberando acesso controlado via métodos públicos (<code>depositar()</code>, <code>getSaldo()</code>).</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>3. Herança</strong></td>\n<td style=\"text-align: left;\">Uma classe filha (<strong>subclasse</strong>) reaproveita atributos e métodos de uma classe mãe (<strong>superclasse</strong>), criando especializações (<code>Gerente</code> herda de <code>Funcionario</code>).</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>4. Polimorfismo</strong></td>\n<td style=\"text-align: left;\"><em>\"Muitas formas\"</em>: objetos de classes diferentes respondem de maneira própria à mesma chamada de método (<code>emitir_som()</code> ou <code>calcularSalario()</code>).</td>\n</tr>\n</tbody>\n</table>\n<div class=\"callout callout-caution\">\n\n<p><strong>Pegadinha clássica (DS 2019 Q27):</strong> A banca pergunta quais são os <strong>4 Pilares da POO</strong> e coloca no meio palavras como <em>\"Atributo, Método, Classe, Compilação, Recursividade\"</em>. <strong>Classe, Objeto, Atributo e Método são ELEMENTOS básicos</strong>, mas os <strong>4 PILARES</strong> são exclusivamente <strong>Abstração, Encapsulamento, Herança e Polimorfismo</strong>!</p>\n</div>\n\n<hr />\n<h3 id=\"️️-dissecando-questões-no-estilo-exato-da-prova\">🕵️‍♂️ Dissecando Questões no Estilo Exato da Prova</h3>\n<h4 id=\"questão-resolvida-1-baseada-em-ds-2019-q12--apostas-q13--scrum\">Questão Resolvida 1 (Baseada em DS 2019 Q12 &amp; Apostas Q13 — Scrum)</h4>\n<p><em>Sobre o framework Scrum, julgue:</em></p>\n<ul>\n<li><em>I. O Scrum Master atua como gerente tradicional que atribui linhas de código e impõe prazos diários ao time.</em></li>\n<li><em>II. O Product Owner é o responsável por maximizar o valor do produto e priorizar o Product Backlog.</em></li>\n<li><em>III. A Daily Scrum é uma reunião diária de sincronização limitada a no máximo 15 minutos.</em> <strong>Análise:</strong> <strong>I é FALSO</strong> (Scrum Master é facilitador que remove impedimentos; o time é auto-organizável). <strong>II e III são VERDADEIROS</strong>.</li>\n</ul>\n<h4 id=\"questão-resolvida-2-baseada-em-ds-2019-q10--info-2025-q22--requisitos\">Questão Resolvida 2 (Baseada em DS 2019 Q10 &amp; INFO 2025 Q22 — Requisitos)</h4>\n<p><em>Um cliente exige que o sistema funcione sem modificações nos navegadores Chrome, Edge e Safari, e que responda em até 1,5 segundo com 1.000 usuários simultâneos. Essas exigências classificam-se, respectivamente, como:</em> <strong>Análise:</strong> Compatibilidade entre diferentes ambientes/plataformas é <strong>Portabilidade</strong>; limite de 1,5s é <strong>Desempenho</strong>. Ambos descrevem <em>como</em> o sistema se comporta, portanto são <strong>Requisitos Não Funcionais</strong>!</p>\n"}, {"id": "mod2", "title": "Módulo 2 • Banco de Dados, SQL, NoSQL, DER & 1FN–3FN (Dias 6–7)", "html": "<h2 id=\"dia-6--banco-de-dados-relacional-sgbds-as-5-sublinguagens-sql-e-bancos-nosql\">Dia 6 — Banco de Dados Relacional, SGBDs, as 5 Sublinguagens SQL e Bancos NoSQL</h2>\n<h3 id=\"-contexto-no-mundo-real-por-que-sistemas-sérios-não-salvam-dados-em-arquivos-de-texto-ou-planilhas\">🎯 Contexto no Mundo Real: Por que Sistemas Sérios Não Salvam Dados em Arquivos de Texto ou Planilhas?</h3>\n<p>Imagine uma loja virtual vendendo o <strong>último iPhone do estoque</strong> para duas pessoas clicando em \"Comprar\" no mesmo milissegundo em São Paulo e em Campinas. Se os dados ficassem numa planilha do Excel compartilhada, os dois pedidos poderiam gravar \"estoque = 0\" vendendo 2 aparelhos onde só havia 1, sem falar na lentidão com 5 milhões de clientes cadastrados ou no risco de alguém abrir o arquivo e apagar tudo!</p>\n<p>Para resolver concorrência, velocidade de busca, permissões de usuários e integridade financeira, usamos um <strong>SGBD (<em>Sistema Gerenciador de Banco de Dados</em>)</strong> — como <strong>MySQL, PostgreSQL, Oracle Database, Microsoft SQL Server ou SQLite</strong> — conversando através da linguagem padrão <strong>SQL (<em>Structured Query Language</em>)</strong>. E quando precisamos armazenar catálogos gigantes e flexíveis estilo JSON de redes sociais ou cache em milissegundos, entra em cena o universo <strong>NoSQL</strong>.</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Onde ficam salvas todas as mensagens de um servidor do Discord, sua lista de amigos da Steam ou o ranking mundial do Fortnite? Dentro de <strong>Bancos de Dados (SQL e NoSQL)</strong>! Olha como as <strong>5 sublinguagens SQL</strong> aparecem nisso:</p>\n<ul>\n<li><strong>DDL (<code>CREATE</code>, <code>ALTER</code>, <code>DROP</code>):</strong> Mexe na <strong>estrutura</strong> — cria a tabela <code>jogadores</code>, adiciona a coluna <code>elo</code>, ou apaga a tabela inteira!</li>\n<li><strong>DML (<code>INSERT</code>, <code>UPDATE</code>, <code>DELETE</code>):</strong> Mexe nos <strong>registros dentro da tabela</strong> — grava uma nova partida (<code>INSERT</code>), sobe seu XP (<code>UPDATE</code>) ou apaga uma mensagem enviada no chat (<code>DELETE</code>).</li>\n<li><strong>DQL (<code>SELECT</code> + <code>COUNT(*)</code>):</strong> Faz a <strong>consulta</strong> — <em>\"Quantos jogadores têm elo Diamante (<code>SELECT COUNT(*) WHERE elo = 'Diamante'</code>)?\"</em>.</li>\n<li><strong>DCL (<code>GRANT</code>, <code>REVOKE</code>):</strong> É exatamente <strong>dar ou tirar cargo de Admin / Moderador</strong> no Discord para um usuário poder ler ou mexer nos registros!</li>\n<li><strong>TCL (<code>COMMIT</code>, <code>ROLLBACK</code>):</strong> É o sistema anti-golpe de <strong>Trade de Skins na Steam</strong>! Quando você troca uma faca por 3 skins com outro player, ou os dois itens trocam de dono ao mesmo tempo (<strong><code>COMMIT</code></strong>), ou se a internet cair no meio o banco desfaz tudo e ninguém é roubado (<strong><code>ROLLBACK</code></strong>)!</li>\n<li><strong>NoSQL (MongoDB / Redis):</strong> Guarda coisas flexíveis em JSON (cada personagem tem atributos diferentes no inventário sem coluna fixa) e status instantâneo na RAM (<em>\"Fulano está online jogando Valorant\"</em>).</li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--o-papel-do-sgbd-e-transações-acid\">📚 Parte 1 — O Papel do SGBD e Transações ACID</h3>\n<p>Um <strong>SGBD</strong> fica entre o seu programa (back-end PHP/Node/Java/Python) e os arquivos físicos no SSD/HD. Ele garante as propriedades <strong>ACID</strong> em transações bancárias e comerciais:</p>\n<ul>\n<li><strong>A — Atomicidade:</strong> \"Tudo ou nada\" (num Pix, ou tira do saldo de João <strong>e</strong> entra no saldo de Maria, ou desfaz ambos — nunca some no meio!).</li>\n<li><strong>C — Consistência:</strong> O banco nunca viola regras/chaves (<code>NOT NULL</code>, chaves estrangeiras).</li>\n<li><strong>I — Isolamento:</strong> Milhares de usuários consultando e comprando simultaneamente não corrompem uns aos outros.</li>\n<li><strong>D — Durabilidade:</strong> Confirmado com <code>COMMIT</code>, os dados sobrevivem mesmo se faltar energia elétrica 1 segundo depois.</li>\n</ul>\n<hr />\n<h3 id=\"-parte-2--as-5-sublinguagens-oficiais-da-sql-questão-garantida-na-prova\">📚 Parte 2 — As 5 Sublinguagens Oficiais da SQL (Questão Garantida na Prova!)</h3>\n<p>A <strong>SQL</strong> é dividida em <strong>5 subconjuntos especializados de comandos</strong>. A Fundação FAT adora criar tabelas misturando <strong>DDL</strong>, <strong>DML</strong> e <strong>DQL</strong> para confundir o candidato (<strong>DS 2025 Q11</strong>, <strong>DS 2019 Q7</strong>, <strong>Apostas Q16</strong>):</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: center;\">Sublinguagem</th>\n<th style=\"text-align: left;\">Sigla em Inglês</th>\n<th style=\"text-align: left;\">Comandos Principais</th>\n<th style=\"text-align: left;\">Onde atua? (Macete definitivo)</th>\n<th style=\"text-align: left;\">Analogia de uma Pasta/Tabela Excel</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>DDL</strong></td>\n<td style=\"text-align: left;\"><em>Data Definition Language</em> (Definição)</td>\n<td style=\"text-align: left;\"><strong><code>CREATE</code></strong>, <strong><code>ALTER</code></strong>, <strong><code>DROP</code></strong>, <code>TRUNCATE</code></td>\n<td style=\"text-align: left;\">Atua na <strong>ESTRUTURA (esqueleto)</strong> do banco: cria tabela, adiciona coluna, muda tipo de coluna, apaga a tabela inteira!</td>\n<td style=\"text-align: left;\"><strong>Construir, reformar ou demolir</strong> a estante de aço.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>DML</strong></td>\n<td style=\"text-align: left;\"><em>Data Manipulation Language</em> (Manipulação)</td>\n<td style=\"text-align: left;\"><strong><code>INSERT</code></strong>, <strong><code>UPDATE</code></strong>, <strong><code>DELETE</code></strong></td>\n<td style=\"text-align: left;\">Atua nos <strong>DADOS (linhas/registros)</strong> dentro da tabela já existente.</td>\n<td style=\"text-align: left;\"><strong>Colocar, trocar ou retirar</strong> pastas de dentro da estante.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>DQL</strong></td>\n<td style=\"text-align: left;\"><em>Data Query Language</em> (Consulta)</td>\n<td style=\"text-align: left;\"><strong><code>SELECT</code></strong> <em>(com <code>FROM</code>, <code>WHERE</code>, <code>JOIN</code>, <code>ORDER BY</code>)</em></td>\n<td style=\"text-align: left;\">Apenas <strong>CONSULTA / LÊ</strong> os dados sem alterá-los. <em>(Nota: alguns autores antigos põem dentro de DML, mas a <strong>FAT cobra separadamente como DQL</strong>!)</em></td>\n<td style=\"text-align: left;\"><strong>Procurar e ler</strong> uma pasta sem modificá-la.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>DCL</strong></td>\n<td style=\"text-align: left;\"><em>Data Control Language</em> (Controle)</td>\n<td style=\"text-align: left;\"><strong><code>GRANT</code></strong>, <strong><code>REVOKE</code></strong></td>\n<td style=\"text-align: left;\">Gerencia <strong>PERMISSÕES e SEGURANÇA</strong> de acesso de usuários.</td>\n<td style=\"text-align: left;\"><strong>Dar ou tomar a chave</strong> do arquivo de um funcionário.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>TCL</strong></td>\n<td style=\"text-align: left;\"><em>Transaction Control Language</em> (Transação)</td>\n<td style=\"text-align: left;\"><strong><code>BEGIN</code></strong>, <strong><code>COMMIT</code></strong>, <strong><code>ROLLBACK</code></strong>, <code>SAVEPOINT</code></td>\n<td style=\"text-align: left;\">Controla <strong>TRANSAÇÕES</strong>: confirma definitivamente (<code>COMMIT</code>) ou desfaz alterações (<code>ROLLBACK</code>) em caso de erro.</td>\n<td style=\"text-align: left;\"><strong>Carimbar \"Aprovado\"</strong> no Pix ou <strong>cancelar tudo</strong> se falhou.</td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"-script-sql-completo-comentado-linha-por-linha-do-zero-até-consultas-e-transações\">💻 Script SQL Completo Comentado Linha por Linha (Do Zero até Consultas e Transações)</h4>\n<div class=\"sourceCode\" id=\"cb1\"><pre class=\"sourceCode sql\"><code class=\"sourceCode sql\"><span id=\"cb1-1\"><a href=\"#cb1-1\" aria-hidden=\"true\"></a><span class=\"co\">-- ==================== 1. DDL (ESTRUTURA) ====================</span></span>\n<span id=\"cb1-2\"><a href=\"#cb1-2\" aria-hidden=\"true\"></a><span class=\"kw\">CREATE</span> <span class=\"kw\">TABLE</span> alunos (</span>\n<span id=\"cb1-3\"><a href=\"#cb1-3\" aria-hidden=\"true\"></a>    <span class=\"kw\">id</span> <span class=\"dt\">INT</span> <span class=\"kw\">PRIMARY</span> <span class=\"kw\">KEY</span> AUTO_INCREMENT,   <span class=\"co\">-- Identificador único obrigatório</span></span>\n<span id=\"cb1-4\"><a href=\"#cb1-4\" aria-hidden=\"true\"></a>    nome <span class=\"dt\">VARCHAR</span>(<span class=\"dv\">100</span>) <span class=\"kw\">NOT</span> <span class=\"kw\">NULL</span>,          <span class=\"co\">-- Texto variável até 100 letras</span></span>\n<span id=\"cb1-5\"><a href=\"#cb1-5\" aria-hidden=\"true\"></a>    turma <span class=\"dt\">VARCHAR</span>(<span class=\"dv\">10</span>),</span>\n<span id=\"cb1-6\"><a href=\"#cb1-6\" aria-hidden=\"true\"></a>    nota <span class=\"dt\">DECIMAL</span>(<span class=\"dv\">4</span>,<span class=\"dv\">2</span>)</span>\n<span id=\"cb1-7\"><a href=\"#cb1-7\" aria-hidden=\"true\"></a>);</span>\n<span id=\"cb1-8\"><a href=\"#cb1-8\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-9\"><a href=\"#cb1-9\" aria-hidden=\"true\"></a><span class=\"co\">-- Esqueci a coluna de email! Uso ALTER TABLE (DDL) para modificar a estrutura:</span></span>\n<span id=\"cb1-10\"><a href=\"#cb1-10\" aria-hidden=\"true\"></a><span class=\"kw\">ALTER</span> <span class=\"kw\">TABLE</span> alunos <span class=\"kw\">ADD</span> email <span class=\"dt\">VARCHAR</span>(<span class=\"dv\">120</span>);</span>\n<span id=\"cb1-11\"><a href=\"#cb1-11\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-12\"><a href=\"#cb1-12\" aria-hidden=\"true\"></a><span class=\"co\">-- ==================== 2. DML (REGISTROS / LINHAS) ====================</span></span>\n<span id=\"cb1-13\"><a href=\"#cb1-13\" aria-hidden=\"true\"></a><span class=\"kw\">INSERT</span> <span class=\"kw\">INTO</span> alunos (nome, turma, nota, email)</span>\n<span id=\"cb1-14\"><a href=\"#cb1-14\" aria-hidden=\"true\"></a><span class=\"kw\">VALUES</span></span>\n<span id=\"cb1-15\"><a href=\"#cb1-15\" aria-hidden=\"true\"></a>    (<span class=\"st\">&#39;Lucas Ferreira&#39;</span>, <span class=\"st\">&#39;2MTEC&#39;</span>, <span class=\"fl\">8.50</span>, <span class=\"st\">&#39;lucas@etec.sp.gov.br&#39;</span>),</span>\n<span id=\"cb1-16\"><a href=\"#cb1-16\" aria-hidden=\"true\"></a>    (<span class=\"st\">&#39;Ana Beatriz&#39;</span>,    <span class=\"st\">&#39;2MTEC&#39;</span>, <span class=\"fl\">9.20</span>, <span class=\"st\">&#39;ana@etec.sp.gov.br&#39;</span>),</span>\n<span id=\"cb1-17\"><a href=\"#cb1-17\" aria-hidden=\"true\"></a>    (<span class=\"st\">&#39;Bruno Costa&#39;</span>,    <span class=\"st\">&#39;1MTEC&#39;</span>, <span class=\"fl\">5.80</span>, <span class=\"st\">&#39;bruno@etec.sp.gov.br&#39;</span>),</span>\n<span id=\"cb1-18\"><a href=\"#cb1-18\" aria-hidden=\"true\"></a>    (<span class=\"st\">&#39;Carla Dias&#39;</span>,     <span class=\"st\">&#39;2MTEC&#39;</span>, <span class=\"fl\">7.00</span>, <span class=\"st\">&#39;carla@etec.sp.gov.br&#39;</span>);</span>\n<span id=\"cb1-19\"><a href=\"#cb1-19\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-20\"><a href=\"#cb1-20\" aria-hidden=\"true\"></a><span class=\"co\">-- Bruno fez recuperação e foi para 6.50. ATENÇÃO AO WHERE!!</span></span>\n<span id=\"cb1-21\"><a href=\"#cb1-21\" aria-hidden=\"true\"></a><span class=\"kw\">UPDATE</span> alunos <span class=\"kw\">SET</span> nota <span class=\"op\">=</span> <span class=\"fl\">6.50</span> <span class=\"kw\">WHERE</span> <span class=\"kw\">id</span> <span class=\"op\">=</span> <span class=\"dv\">3</span>;</span>\n<span id=\"cb1-22\"><a href=\"#cb1-22\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-23\"><a href=\"#cb1-23\" aria-hidden=\"true\"></a><span class=\"co\">-- Se quiser remover apenas o aluno de id = 3 (tabela continua existindo!):</span></span>\n<span id=\"cb1-24\"><a href=\"#cb1-24\" aria-hidden=\"true\"></a><span class=\"kw\">DELETE</span> <span class=\"kw\">FROM</span> alunos <span class=\"kw\">WHERE</span> <span class=\"kw\">id</span> <span class=\"op\">=</span> <span class=\"dv\">3</span>;</span>\n<span id=\"cb1-25\"><a href=\"#cb1-25\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-26\"><a href=\"#cb1-26\" aria-hidden=\"true\"></a><span class=\"co\">-- ==================== 3. DQL (CONSULTAS / LEITURA) ====================</span></span>\n<span id=\"cb1-27\"><a href=\"#cb1-27\" aria-hidden=\"true\"></a><span class=\"co\">-- Listar nome e nota dos aprovados do 2MTEC ordenados da maior nota para a menor:</span></span>\n<span id=\"cb1-28\"><a href=\"#cb1-28\" aria-hidden=\"true\"></a><span class=\"kw\">SELECT</span> nome, nota</span>\n<span id=\"cb1-29\"><a href=\"#cb1-29\" aria-hidden=\"true\"></a><span class=\"kw\">FROM</span> alunos</span>\n<span id=\"cb1-30\"><a href=\"#cb1-30\" aria-hidden=\"true\"></a><span class=\"kw\">WHERE</span> turma <span class=\"op\">=</span> <span class=\"st\">&#39;2MTEC&#39;</span> <span class=\"kw\">AND</span> nota <span class=\"op\">&gt;=</span> <span class=\"fl\">6.0</span></span>\n<span id=\"cb1-31\"><a href=\"#cb1-31\" aria-hidden=\"true\"></a><span class=\"kw\">ORDER</span> <span class=\"kw\">BY</span> nota <span class=\"kw\">DESC</span>;</span>\n<span id=\"cb1-32\"><a href=\"#cb1-32\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-33\"><a href=\"#cb1-33\" aria-hidden=\"true\"></a><span class=\"co\">-- ==================== 4. DCL &amp; 5. TCL ====================</span></span>\n<span id=\"cb1-34\"><a href=\"#cb1-34\" aria-hidden=\"true\"></a><span class=\"kw\">GRANT</span> <span class=\"kw\">SELECT</span> <span class=\"kw\">ON</span> alunos <span class=\"kw\">TO</span> professor_estagiario;  <span class=\"co\">-- DCL: dá permissão apenas de leitura</span></span>\n<span id=\"cb1-35\"><a href=\"#cb1-35\" aria-hidden=\"true\"></a><span class=\"kw\">REVOKE</span> <span class=\"kw\">SELECT</span> <span class=\"kw\">ON</span> alunos <span class=\"kw\">FROM</span> professor_estagiario; <span class=\"co\">-- DCL: retira a permissão</span></span>\n<span id=\"cb1-36\"><a href=\"#cb1-36\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-37\"><a href=\"#cb1-37\" aria-hidden=\"true\"></a><span class=\"cf\">BEGIN</span>;                                           <span class=\"co\">-- TCL: inicia bloco transacional seguro</span></span>\n<span id=\"cb1-38\"><a href=\"#cb1-38\" aria-hidden=\"true\"></a><span class=\"kw\">UPDATE</span> contas <span class=\"kw\">SET</span> saldo <span class=\"op\">=</span> saldo <span class=\"op\">-</span> <span class=\"dv\">100</span> <span class=\"kw\">WHERE</span> <span class=\"kw\">id</span> <span class=\"op\">=</span> <span class=\"dv\">1</span>;</span>\n<span id=\"cb1-39\"><a href=\"#cb1-39\" aria-hidden=\"true\"></a><span class=\"kw\">UPDATE</span> contas <span class=\"kw\">SET</span> saldo <span class=\"op\">=</span> saldo <span class=\"op\">+</span> <span class=\"dv\">100</span> <span class=\"kw\">WHERE</span> <span class=\"kw\">id</span> <span class=\"op\">=</span> <span class=\"dv\">2</span>;</span>\n<span id=\"cb1-40\"><a href=\"#cb1-40\" aria-hidden=\"true\"></a><span class=\"kw\">COMMIT</span>;                                          <span class=\"co\">-- TCL: grava os dois juntos! (Se desse erro, usaria ROLLBACK)</span></span></code></pre></div>\n<div class=\"callout callout-caution\">\n\n<p><strong>PEGADINHA Nº 1 (<code>DROP</code> vs <code>DELETE</code> — DS 2025 Q11):</strong></p>\n<ul>\n<li><code>DROP TABLE alunos;</code> é <strong>DDL</strong>: <strong>destrói a tabela inteira e seu desenho</strong>. Se rodar <code>SELECT * FROM alunos</code> depois, dá erro <em>\"Tabela não existe\"</em>.</li>\n<li><code>DELETE FROM alunos WHERE ...;</code> é <strong>DML</strong>: apaga <strong>linhas/registros</strong>, mas a estrutura da tabela continua viva!</li>\n<li>E <strong>esquecer o <code>WHERE</code></strong> num <code>UPDATE</code> ou <code>DELETE</code> altera ou apaga <strong>TODAS as linhas da tabela</strong>!</li>\n</ul>\n</div>\n\n<hr />\n<h3 id=\"-parte-3--dominando-where-operadores-lógicos-e-funções-de-agregação-count\">📚 Parte 3 — Dominando <code>WHERE</code>, Operadores Lógicos e Funções de Agregação (<code>COUNT(*)</code>)</h3>\n<h4 id=\"1-ordem-mental-de-execução-do-select-info-2025-q28\">1. Ordem Mental de Execução do <code>SELECT</code> <em>(INFO 2025 Q28)</em></h4>\n<p>A cláusula <strong><code>WHERE</code></strong> serve exclusivamente para <strong>filtrar registros</strong> segundo condições verdadeiras ou falsas:</p>\n<ul>\n<li><code>WHERE cidade = 'São Paulo' AND idade &gt;= 18</code>: só traz se <strong>ambas</strong> forem verdadeiras.</li>\n<li><code>WHERE turma = 'A' OR turma = 'B'</code>: basta <strong>uma</strong> ser verdadeira.</li>\n<li><code>WHERE nome LIKE 'An%'</code>: começa com <code>\"An\"</code> (<code>%</code> substitui qualquer sequência de caracteres).</li>\n<li><code>WHERE nota BETWEEN 6 AND 10</code>: intervalo fechado de 6 a 10.</li>\n<li><code>ORDER BY nome ASC</code> (crescente A–Z, padrão) ou <code>DESC</code> (decrescente Z–A / maior para menor).</li>\n</ul>\n<h4 id=\"2-count-sum-avg-max-e-min-ds-2025-q14\">2. <code>COUNT(*)</code>, <code>SUM()</code>, <code>AVG()</code>, <code>MAX()</code> e <code>MIN()</code> <em>(DS 2025 Q14)</em></h4>\n<p>Observe a diferença entre <strong>contar linhas</strong> e <strong>somar valores</strong> na tabela <code>vendas</code>:</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: center;\"><code>id_venda</code></th>\n<th style=\"text-align: left;\"><code>vendedor</code></th>\n<th style=\"text-align: left;\"><code>cidade</code></th>\n<th style=\"text-align: center;\"><code>valor</code></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><code>1</code></td>\n<td style=\"text-align: left;\">João</td>\n<td style=\"text-align: left;\">São Paulo</td>\n<td style=\"text-align: center;\"><code>200</code></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><code>2</code></td>\n<td style=\"text-align: left;\">Maria</td>\n<td style=\"text-align: left;\">Campinas</td>\n<td style=\"text-align: center;\"><code>500</code></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><code>3</code></td>\n<td style=\"text-align: left;\">Pedro</td>\n<td style=\"text-align: left;\">São Paulo</td>\n<td style=\"text-align: center;\"><code>150</code></td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li><code>SELECT COUNT(*) FROM vendas WHERE cidade = 'São Paulo';</code> → Retorna <strong><code>2</code></strong>! <em>(Existem <strong>2 linhas/vendas</strong> em São Paulo — <code>COUNT(*)</code> conta linhas, <strong>NÃO</strong> soma <code>200 + 150</code>!)</em></li>\n<li><code>SELECT SUM(valor) FROM vendas WHERE cidade = 'São Paulo';</code> → Retorna <strong><code>350</code></strong> (<code>200 + 150</code>, soma valores numéricos).</li>\n<li><code>SELECT AVG(valor) FROM vendas WHERE cidade = 'São Paulo';</code> → Retorna <strong><code>175</code></strong> (média aritmética: <code>350 / 2</code>).</li>\n<li><code>SELECT MAX(valor) FROM vendas;</code> → Retorna <strong><code>500</code></strong> | <code>MIN(valor)</code> → <strong><code>150</code></strong>.</li>\n</ul>\n<div class=\"callout callout-caution\">\n\n<p><strong>Pegadinha clássica da DS 2025 Q14:</strong> A banca escreve comandos SQL errados como <code>SELECT * FROM clientes WHERE COUNT(cidade) = 'São Paulo';</code> ou coloca <code>FROM</code> depois do <code>WHERE</code>. <strong>Regra inviolável da sintaxe SQL:</strong> <strong><code>COUNT(*)</code> fica SEMPRE na cláusula <code>SELECT</code></strong> (entre <code>SELECT</code> e <code>FROM</code>), e <strong>JAMAIS</strong> dentro do <code>WHERE</code>! A ordem fixa sempre é <strong><code>SELECT ... FROM ... WHERE ... ORDER BY ...</code></strong>.</p>\n</div>\n\n<hr />\n<h3 id=\"-parte-4--bancos-nosql-not-only-sql--info-2025-q29--apostas-q18\">📚 Parte 4 — Bancos NoSQL (<em>Not Only SQL</em> — INFO 2025 Q29 &amp; Apostas Q18)</h3>\n<p>O modelo relacional (SQL) exige tabelas rígidas com colunas pré-definidas (<em>schema</em> fixo) e cresce principalmente <strong>verticalmente</strong> (colocando um servidor mais caro/potente). Quando empresas como Netflix, Instagram e Amazon passaram a lidar com <strong>terabytes por dia de dados variados (Big Data)</strong> espalhados em milhares de servidores comuns (<strong>escalabilidade horizontal</strong>), popularizaram-se os bancos <strong>NoSQL</strong> (<em>\"Não Apenas SQL\"</em>).</p>\n<h4 id=\"características-centrais-do-nosql\">Características Centrais do NoSQL</h4>\n<ol>\n<li><strong>Esquema Flexível (<em>Schema-less</em>):</strong> Na mesma coleção de produtos, o tênis pode ter campo <code>numeracao: 41</code> e o notebook pode ter <code>ram_gb: 16</code>, sem precisar de <code>ALTER TABLE</code> nem deixar colunas cheias de <code>NULL</code>!</li>\n<li><strong>Escalabilidade Horizontal (<em>Sharding</em>):</strong> Fácil de dividir os dados entre dezenas/centenas de máquinas em rede.</li>\n<li><strong>Sem JOINs complexos:</strong> Prioriza velocidade de leitura armazenando objetos relacionados já aninhados juntos.</li>\n</ol>\n<h4 id=\"as-4-famílias-famosas-de-nosql\">As 4 Famílias Famosas de NoSQL</h4>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Família NoSQL</th>\n<th style=\"text-align: left;\">Como guarda os dados</th>\n<th style=\"text-align: left;\">Exemplos famosos</th>\n<th style=\"text-align: left;\">Caso de uso real</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>1. Documentos</strong></td>\n<td style=\"text-align: left;\">Objetos <strong>JSON / BSON</strong> flexíveis agrupados em coleções</td>\n<td style=\"text-align: left;\"><strong>MongoDB</strong>, CouchDB, Firebase Firestore</td>\n<td style=\"text-align: left;\">Catálogos de e-commerce, perfis de usuários, apps móveis</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>2. Chave-Valor (<em>Key-Value</em>)</strong></td>\n<td style=\"text-align: left;\">Dicionário gigante ultrarrápido na memória RAM (<code>chave -&gt; valor</code>)</td>\n<td style=\"text-align: left;\"><strong>Redis</strong>, Amazon DynamoDB</td>\n<td style=\"text-align: left;\">Cache de páginas, carrinhos temporários, tokens de sessão</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>3. Colunar (<em>Wide-Column</em>)</strong></td>\n<td style=\"text-align: left;\">Famílias de colunas esparsas otimizadas para escrita massiva</td>\n<td style=\"text-align: left;\">Apache <strong>Cassandra</strong>, HBase</td>\n<td style=\"text-align: left;\">Telemetria IoT de milhões de sensores, histórico de logs</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>4. Grafos (<em>Graph</em>)</strong></td>\n<td style=\"text-align: left;\">Nós (entidades) e arestas (conexões diretas)</td>\n<td style=\"text-align: left;\"><strong>Neo4j</strong></td>\n<td style=\"text-align: left;\">Redes sociais (<em>\"amigos de amigos\"</em>), detecção de fraudes, recomendações</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Exemplo real de Documento JSON no MongoDB (note como telefones e endereço moram aninhados sem precisar de JOIN!):</strong></p>\n<div class=\"sourceCode\" id=\"cb2\"><pre class=\"sourceCode json\"><code class=\"sourceCode json\"><span id=\"cb2-1\"><a href=\"#cb2-1\" aria-hidden=\"true\"></a><span class=\"fu\">{</span></span>\n<span id=\"cb2-2\"><a href=\"#cb2-2\" aria-hidden=\"true\"></a>  <span class=\"dt\">&quot;_id&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;user_901&quot;</span><span class=\"fu\">,</span></span>\n<span id=\"cb2-3\"><a href=\"#cb2-3\" aria-hidden=\"true\"></a>  <span class=\"dt\">&quot;nome&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;Henrique Silva&quot;</span><span class=\"fu\">,</span></span>\n<span id=\"cb2-4\"><a href=\"#cb2-4\" aria-hidden=\"true\"></a>  <span class=\"dt\">&quot;curso&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;DS M-Tec&quot;</span><span class=\"fu\">,</span></span>\n<span id=\"cb2-5\"><a href=\"#cb2-5\" aria-hidden=\"true\"></a>  <span class=\"dt\">&quot;telefones&quot;</span><span class=\"fu\">:</span> <span class=\"ot\">[</span><span class=\"st\">&quot;1199999-0001&quot;</span><span class=\"ot\">,</span> <span class=\"st\">&quot;1198888-0002&quot;</span><span class=\"ot\">]</span><span class=\"fu\">,</span></span>\n<span id=\"cb2-6\"><a href=\"#cb2-6\" aria-hidden=\"true\"></a>  <span class=\"dt\">&quot;endereco&quot;</span><span class=\"fu\">:</span> <span class=\"fu\">{</span> <span class=\"dt\">&quot;cidade&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;São Paulo&quot;</span><span class=\"fu\">,</span> <span class=\"dt\">&quot;uf&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;SP&quot;</span> <span class=\"fu\">}</span></span>\n<span id=\"cb2-7\"><a href=\"#cb2-7\" aria-hidden=\"true\"></a><span class=\"fu\">}</span></span></code></pre></div>\n<hr />\n<h3 id=\"️️-dissecando-questões-no-estilo-exato-da-prova\">🕵️‍♂️ Dissecando Questões no Estilo Exato da Prova</h3>\n<h4 id=\"questão-resolvida-1-baseada-em-ds-2025-q11--ds-2019-q7--sublinguagens-sql\">Questão Resolvida 1 (Baseada em DS 2025 Q11 &amp; DS 2019 Q7 — Sublinguagens SQL)</h4>\n<p><em>Considere as afirmações: I. Os comandos <code>CREATE</code>, <code>ALTER</code> e <code>DROP</code> fazem parte da DDL, responsável pela estrutura do banco. II. <code>SELECT</code> pertence à DQL, permitindo consultar registros sem modificar tabelas. III. <code>INSERT</code>, <code>UPDATE</code> e <code>DELETE</code> pertencem à TCL, pois salvam ou desfazem transações.</em></p>\n<ul>\n<li><strong>Item I:</strong> VERDADEIRO.</li>\n<li><strong>Item II:</strong> VERDADEIRO.</li>\n<li><strong>Item III:</strong> <strong>FALSO</strong>! <code>INSERT</code>, <code>UPDATE</code> e <code>DELETE</code> são <strong>DML</strong> (manipulação de dados). Quem pertence à <strong>TCL</strong> são <code>COMMIT</code>, <code>ROLLBACK</code> e <code>SAVEPOINT</code>.</li>\n</ul>\n<h4 id=\"questão-resolvida-2-baseada-em-ds-2025-q14--info-2025-q28\">Questão Resolvida 2 (Baseada em DS 2025 Q14 &amp; INFO 2025 Q28)</h4>\n<p><em>Para descobrir quantos alunos têm nota maior ou igual a 7 na tabela <code>notas</code>, qual comando SQL é sintaticamente e logicamente correto?</em></p>\n<ul>\n<li><code>A) SELECT COUNT(*) FROM notas WHERE nota &gt;= 7;</code> → <strong>CORRETA!</strong> Ordem exata <code>SELECT ... FROM ... WHERE ...</code> e <code>COUNT(*)</code> contando as linhas filtradas.</li>\n<li><em>B) SELECT * FROM notas WHERE COUNT(nota) &gt;= 7;</em> → <strong>ERRADA!</strong> <code>COUNT</code> jamais entra direto dentro do <code>WHERE</code>.</li>\n</ul>\n<hr><h2 id=\"dia-7--modelagem-de-dados-conceitual-lógico-físico-der-chaves-cardinalidades-e-normalização-1fn3fn\">Dia 7 — Modelagem de Dados (Conceitual, Lógico, Físico), DER, Chaves, Cardinalidades e Normalização (1FN–3FN)</h2>\n<h3 id=\"-contexto-no-mundo-real-por-que-bancos-mal-projetados-perdem-dados\">🎯 Contexto no Mundo Real: Por que Bancos Mal Projetados Perdem Dados?</h3>\n<p>Imagine uma escola que cria uma única planilhona gigante chamada <code>MATRICULAS</code> onde cada linha repete: nome do aluno, CPF, três telefones colados juntos na mesma célula (<code>\"11999-1111, 11888-2222\"</code>), nome do curso e telefone da coordenação do curso. Veja os <strong>3 pesadelos</strong> que acontecem nessa tabela não normalizada:</p>\n<ol>\n<li>Se 500 alunos cursarem <em>Desenvolvimento de Sistemas</em> e o telefone da coordenação mudar, você terá que atualizar 500 linhas (e se esquecer 1 linha, o banco fica inconsistente!).</li>\n<li>Se um professor criar um curso novo que ainda não tem nenhum aluno matriculado, você <strong>nem consegue cadastrar o curso</strong> porque precisa inventar um aluno para preencher a linha (<strong>anomalia de inserção</strong>)!</li>\n<li>Se o único aluno de um curso trancar a matrícula e for deletado, você <strong>perde para sempre o cadastro do curso</strong> (<strong>anomalia de exclusão</strong>)!</li>\n</ol>\n<p>Para evitar esses desastres reais, usamos a <strong>Modelagem em 3 Níveis</strong> e a <strong>Normalização (1FN, 2FN e 3FN)</strong>!</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Pensa no <strong>Discord</strong>: você pode mudar seu <em>username</em> e apelido no servidor toda semana, mas por trás existe um <strong><code>User ID</code> numérico único</strong> (<code>18 dígitos</code>) que <strong>nunca muda e nunca se repete</strong> — essa é sua <strong>Chave Primária (PK)</strong>!</p>\n<ul>\n<li><strong>Chave Estrangeira (FK) e <code>1:N</code>:</strong> Um servidor tem <strong>muitos</strong> canais de texto, mas cada canal pertence a <strong>um único</strong> servidor. A FK <code>id_servidor</code> sempre vai dentro da tabela <code>CANAIS</code> (lado <code>N</code>!).</li>\n<li><strong><code>N:N</code> (Muitos para Muitos):</strong> Um usuário entra em <strong>vários</strong> servidores do Discord, e um servidor tem <strong>vários</strong> usuários. Para ligar os dois no banco relacional, cria-se a <strong>3ª Tabela Associativa <code>MEMBROS_SERVIDOR</code></strong> (guardando <code>id_usuario FK</code> + <code>id_servidor FK</code> + cargos!).</li>\n<li><strong>Atributo Derivado:</strong> O texto <em>\"Conta criada há 3 anos\"</em> ou <em>\"Winrate: 58%\"</em> não precisa ficar salvo fixo — o sistema calcula na hora usando <code>data_criacao</code> ou <code>vitorias / partidas</code>!</li>\n<li><strong>1ª Forma Normal (1FN):</strong> Imagina salvar o inventário inteiro num texto só: <code>itens = \"Espada, Escudo, Poção\"</code>! Fica horrível para buscar ou dropar só a poção. Colocar na <strong>1FN</strong> significa ter <strong>apenas 1 valor atômico por célula</strong> (uma tabela separada <code>INVENTARIO</code> com 1 linha para cada item)!</li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--as-3-etapas-da-modelagem-de-dados-apostas-q14\">📚 Parte 1 — As 3 Etapas da Modelagem de Dados <em>(Apostas Q14)</em></h3>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Etapa</th>\n<th style=\"text-align: left;\">Nível de Abstração</th>\n<th style=\"text-align: left;\">Como é representada e para que serve</th>\n<th style=\"text-align: left;\">Exemplo na Etec</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>1. Modelo Conceitual</strong></td>\n<td style=\"text-align: left;\">Mais alto nível (próximo ao usuário/negócio)</td>\n<td style=\"text-align: left;\">Feito com <strong>DER (Diagrama Entidade-Relacionamento, notação de Peter Chen)</strong>. Mostra entidades, relacionamentos e atributos principais, <strong>100% independente de software/SGBD</strong>.</td>\n<td style=\"text-align: left;\">Retângulo <code>ALUNO</code> conectado pelo losango <code>CURSA</code> ao retângulo <code>DISCIPLINA</code> (<code>N:N</code>).</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>2. Modelo Lógico</strong></td>\n<td style=\"text-align: left;\">Intermediário (estrutural)</td>\n<td style=\"text-align: left;\">Converte o DER em <strong>Tabelas do Modelo Relacional</strong>, define <strong>Chaves Primárias (PK)</strong>, <strong>Chaves Estrangeiras (FK)</strong> e resolve relacionamentos <code>N:N</code> criando tabelas intermediárias. Ainda independe do fornecedor específico.</td>\n<td style=\"text-align: left;\"><code>ALUNO(id_aluno PK, nome)</code> / <code>DISCIPLINA(id_disc PK, titulo)</code> / <code>MATRICULA(id_aluno FK, id_disc FK, ano)</code>.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>3. Modelo Físico</strong></td>\n<td style=\"text-align: left;\">Mais próximo da máquina (implementação real)</td>\n<td style=\"text-align: left;\">Script <strong><code>CREATE TABLE</code></strong> escrito no dialeto exato do SGBD escolhido (MySQL, PostgreSQL, SQL Server), definindo tipos exatos (<code>INT</code>, <code>VARCHAR(80)</code>), índices, <em>constraints</em> e armazenamento.</td>\n<td style=\"text-align: left;\"><code>CREATE TABLE aluno (id_aluno INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(80) NOT NULL);</code></td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h3 id=\"-parte-2--vocabulário-formal-relacional--tipos-de-atributos-no-der\">📚 Parte 2 — Vocabulário Formal Relacional &amp; Tipos de Atributos no DER</h3>\n<p>Na prova teórica, a Fundação FAT exige a correspondência entre os nomes acadêmicos do <strong>Modelo Relacional (Edgar Codd)</strong> e os nomes práticos <em>(DS 2025 Q12)</em>:</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Nome Formal na Prova</th>\n<th style=\"text-align: left;\">Equivalente Prático</th>\n<th style=\"text-align: left;\">Exemplo</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Relação (<em>Relation</em>)</strong></td>\n<td style=\"text-align: left;\"><strong>Tabela</strong></td>\n<td style=\"text-align: left;\">A grade inteira <code>ALUNOS</code></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Tupla (<em>Tuple</em>)</strong></td>\n<td style=\"text-align: left;\"><strong>Linha / Registro</strong></td>\n<td style=\"text-align: left;\"><code>(1, 'Henrique', '2DS', '2010-05-14')</code> — representa um objeto/aluno completo</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Atributo (<em>Attribute</em>)</strong></td>\n<td style=\"text-align: left;\"><strong>Coluna / Campo</strong></td>\n<td style=\"text-align: left;\">A coluna <code>nome</code> ou <code>data_nascimento</code></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Domínio (<em>Domain</em>)</strong></td>\n<td style=\"text-align: left;\"><strong>Tipo e faixa de valores válidos</strong></td>\n<td style=\"text-align: left;\">Para <code>nota</code>, apenas decimais de <code>0.0</code> a <code>10.0</code></td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"os-4-tipos-de-atributos-no-der-apostas-q15\">Os 4 Tipos de Atributos no DER <em>(Apostas Q15)</em></h4>\n<ul>\n<li><strong>Atributo Simples (Atômico):</strong> Indivisível em partes menores com sentido próprio (ex.: <code>cpf</code>, <code>sexo</code>, <code>nota</code>).</li>\n<li><strong>Atributo Composto:</strong> Pode ser subdividido em vários sub-atributos menores (ex.: <code>Endereco</code> se divide em <code>logradouro</code>, <code>numero</code>, <code>bairro</code>, <code>cidade</code>, <code>cep</code>).</li>\n<li><strong>Atributo Multivalorado:</strong> Pode armazenar <strong>vários valores para uma mesma ocorrência</strong> da entidade (ex.: uma pessoa pode ter vários <code>telefones</code> ou vários <code>idiomas</code>; desenhado com elipse dupla no DER — na hora de ir para a 1FN no banco relacional, vira uma nova tabela!).</li>\n<li><strong>Atributo Derivado (Calculado):</strong> Seu valor <strong>não precisa ser armazenado fisicamente</strong>, pois é <strong>calculado em tempo real</strong> a partir de outros atributos guardados (ex.: <strong><code>idade</code></strong> calculada a partir da <code>data_nascimento</code>; <strong><code>valor_total</code></strong> = <code>quantidade * preco_unitario</code>; <strong><code>tempo_de_casa</code></strong> a partir de <code>data_admissao</code>). Desenhado com <strong>elipse pontilhada/tracejada</strong> no DER!</li>\n</ul>\n<hr />\n<h3 id=\"-parte-3--chaves-pk-fk-candidataalternativa-e-cardinalidades-ds-2019-q5-e-q9\">📚 Parte 3 — Chaves (<code>PK</code>, <code>FK</code>, Candidata/Alternativa) e Cardinalidades (<code>DS 2019 Q5 e Q9</code>)</h3>\n<h4 id=\"1-os-tipos-de-chaves\">1. Os Tipos de Chaves</h4>\n<ul>\n<li><strong>Chave Primária (<em>Primary Key</em> — <code>PK</code>):</strong> Atributo (ou conjunto mínimo de atributos — <em>PK Composta</em>) escolhido para <strong>identificar de forma única cada linha</strong> da tabela.\n<ul>\n<li><strong>Duas regras sagradas da PK:</strong> <strong>NUNCA pode ter valor repetido</strong> e <strong>NUNCA pode ser nula (<code>NULL</code>)</strong>!</li>\n</ul></li>\n<li><strong>Chave Candidata &amp; Chave Alternativa <em>(DS 2019 Q9)</em>:</strong> Suponha a tabela <code>FUNCIONARIO(id_func, cpf, rg, email, nome)</code>. Tanto <code>id_func</code>, quanto <code>cpf</code> e <code>email</code> identificam uma pessoa sem repetir — logo, todos são <strong>Chaves Candidatas</strong>. Escolhemos <code>id_func</code> como <strong>Chave Primária (PK)</strong>. Os outros candidatos únicos que sobraram (<code>cpf</code>, <code>email</code>) chamam-se <strong>Chaves Alternativas (<em>Alternate Keys</em>)</strong>!</li>\n<li><strong>Chave Estrangeira (<em>Foreign Key</em> — <code>FK</code>):</strong> É uma coluna em uma tabela B que armazena o valor da <strong>Chave Primária da tabela A</strong>, criando o vínculo entre as duas.\n<ul>\n<li><strong>Integridade Referencial:</strong> O SGBD impede gravar um <code>id_aluno = 999</code> numa tabela de <code>NOTAS</code> se não existir aluno <code>999</code> na tabela <code>ALUNOS</code>, e impede apagar um curso que ainda tenha alunos vinculados sem antes tratar as FKs!</li>\n</ul></li>\n</ul>\n<h4 id=\"2-cardinalidades-e-como-viram-tabelas-reais\">2. Cardinalidades e Como Viram Tabelas Reais</h4>\n<p>Representam quantos registros de uma tabela podem se ligar a quantos da outra:</p>\n<ol>\n<li><strong><code>1:1</code> (Um para Um):</strong> Ex.: <code>PAIS</code> — <code>PRESIDENTE</code> ou <code>FUNCIONARIO</code> — <code>CRACHA</code>. Cada lado liga a no máximo 1 do outro. A FK é colocada em um dos lados (geralmente no lado opcional).</li>\n<li><strong><code>1:N</code> (Um para Muitos):</strong> Ex.: Uma <code>TURMA</code> tem <strong>vários</strong> <code>ALUNOS</code>, e cada <code>ALUNO</code> pertence a <strong>1</strong> <code>TURMA</code>.\n<ul>\n<li><strong>Regra de ouro absoluta:</strong> Na modelagem lógica/SQL, <strong>a Chave Estrangeira (FK) SEMPRE vai para a tabela do lado <code>N</code> (Muitos)</strong>!</li>\n<li>Ou seja: <code>id_turma</code> fica dentro de <strong><code>ALUNO</code></strong> (nunca colocamos 40 colunas <code>id_aluno1, id_aluno2...</code> dentro de <code>TURMA</code>!).</li>\n</ul></li>\n<li><strong><code>N:N</code> (Muitos para Muitos):</strong> Ex.: Um <code>ALUNO</code> cursa <strong>várias</strong> <code>DISCIPLINAS</code> e uma <code>DISCIPLINA</code> tem <strong>vários</strong> <code>ALUNOS</code>.\n<ul>\n<li><strong>Como resolver em bancos relacionais?</strong> Como <code>N:N</code> não cabe diretamente com uma única FK de cada lado, <strong>criamos obrigatoriamente uma 3ª Tabela Associativa (Intermediária)</strong> — ex.: <code>MATRICULA(id_matricula PK, id_aluno FK, id_disciplina FK, media)</code> — que recebe as FKs das duas entidades originais!</li>\n</ul></li>\n<li><strong>Auto-relacionamento (Relacionamento Unário / Recursivo — <em>DS 2019 Q5</em>):</strong> Quando uma <strong>tabela se relaciona com ela mesma</strong>!\n<ul>\n<li>Exemplo clássico: Na tabela <code>FUNCIONARIO(id_func, nome, cargo, id_supervisor)</code>, alguns funcionários são supervisores de outros funcionários! Então a coluna <code>id_supervisor</code> é uma <strong>FK dentro da tabela <code>FUNCIONARIO</code> que aponta para a PK <code>id_func</code> da própria tabela <code>FUNCIONARIO</code></strong>!</li>\n</ul></li>\n</ol>\n<hr />\n<h3 id=\"-parte-4--normalização-passo-a-passo-1fn-2fn-e-3fn-na-prática\">📚 Parte 4 — Normalização Passo a Passo: 1FN, 2FN e 3FN na Prática!</h3>\n<p><strong>Normalizar</strong> é aplicar regras progressivas (Formas Normais) para eliminar redundâncias e anomalias de inserção/atualização/exclusão. Veja uma tabela caótica passar pelas <strong>3 Formas Normais</strong>:</p>\n<h4 id=\"tabela-original-fora-das-formas-normais-pedidos_baguncados\">Tabela Original Fora das Formas Normais (<code>PEDIDOS_BAGUNCADOS</code>)</h4>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: center;\"><code>id_pedido</code></th>\n<th style=\"text-align: center;\"><code>id_cliente</code></th>\n<th style=\"text-align: left;\"><code>nome_cliente</code></th>\n<th style=\"text-align: left;\"><code>telefones_cliente</code> <em>(vários juntos!)</em></th>\n<th style=\"text-align: center;\"><code>id_produto</code></th>\n<th style=\"text-align: left;\"><code>nome_produto</code></th>\n<th style=\"text-align: center;\"><code>qtd</code></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><code>101</code></td>\n<td style=\"text-align: center;\"><code>5</code></td>\n<td style=\"text-align: left;\">Lucas</td>\n<td style=\"text-align: left;\"><code>119999-1111, 118888-2222</code></td>\n<td style=\"text-align: center;\"><code>10</code></td>\n<td style=\"text-align: left;\">Teclado</td>\n<td style=\"text-align: center;\"><code>2</code></td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"-passo-1-primeira-forma-normal-1fn--a-campeã-de-provas-ds-2025-q13--ds-2019-q4\">🔹 Passo 1: Primeira Forma Normal (1FN) — <em>A CAMPEÃ DE PROVAS (DS 2025 Q13 &amp; DS 2019 Q4)</em></h4>\n<ul>\n<li><strong>Regra da 1FN:</strong> Todo atributo deve conter apenas <strong>valores atômicos (indivisíveis)</strong> — é proibido armazenar múltiplos valores separados por vírgula numa célula (atributos multivalorados) ou tabelas aninhadas (<em>grupos repetitivos</em>).</li>\n<li><strong>Como corrigimos na prática:</strong> Retiramos <code>telefones_cliente</code> da tabela e criamos uma nova tabela ligada por FK (<code>CLIENTES_TELEFONES</code>) com <strong>1 único número por linha</strong>:</li>\n</ul>\n<p><code>PEDIDOS_1FN</code>: <code>(id_pedido, id_produto [PK composta], id_cliente, nome_cliente, nome_produto, qtd)</code> <em>(agora todas as células são atômicas!)</em> <code>CLIENTES_TELEFONES</code>:</p>\n<ul>\n<li><code>(id_tel=1, id_cliente=5, numero='119999-1111')</code></li>\n<li><code>(id_tel=2, id_cliente=5, numero='118888-2222')</code></li>\n</ul>\n<h4 id=\"-passo-2-segunda-forma-normal-2fn--elimina-dependência-parcial\">🔹 Passo 2: Segunda Forma Normal (2FN) — <em>Elimina Dependência Parcial</em></h4>\n<ul>\n<li><strong>Regra da 2FN:</strong> Já estar na <strong>1FN</strong> <strong>+</strong> quando a Chave Primária for <strong>composta</strong> (<code>id_pedido + id_produto</code>), nenhuma coluna não-chave pode depender de <strong>apenas metade</strong> da chave!</li>\n<li>Olhe <code>PEDIDOS_1FN</code>: <code>qtd</code> depende do pedido <strong>e</strong> do produto (OK!). Mas <strong><code>nome_produto</code></strong> depende <strong>APENAS de <code>id_produto</code></strong> (não importa qual pedido seja!), e <code>id_cliente/nome_cliente</code> dependem só de <strong><code>id_pedido</code></strong>! Isso é <strong>dependência parcial</strong>!</li>\n<li><strong>Correção para 2FN:</strong> Separamos em 3 tabelas coerentes:\n<ul>\n<li><code>PEDIDO(id_pedido PK, id_cliente, nome_cliente)</code></li>\n<li><code>PRODUTO(id_produto PK, nome_produto)</code></li>\n<li><code>ITEM_PEDIDO(id_pedido FK, id_produto FK, qtd)</code> <em>(agora sim na 2FN!)</em></li>\n</ul></li>\n</ul>\n<h4 id=\"-passo-3-terceira-forma-normal-3fn--elimina-dependência-transitiva\">🔹 Passo 3: Terceira Forma Normal (3FN) — <em>Elimina Dependência Transitiva</em></h4>\n<ul>\n<li><strong>Regra da 3FN:</strong> Já estar na <strong>2FN</strong> <strong>+</strong> nenhuma coluna não-chave pode depender de <strong>outra coluna não-chave</strong> (tudo depende <em>\"da chave, apenas da chave e nada além da chave\"</em>).</li>\n<li>Olhe <code>PEDIDO(id_pedido PK, id_cliente, nome_cliente)</code>: <code>id_cliente</code> depende de <code>id_pedido</code>, mas <strong><code>nome_cliente</code> depende de <code>id_cliente</code></strong>, que NÃO é a chave primária da tabela <code>PEDIDO</code>! (Se Lucas casar e mudar de nome, teríamos que atualizar 50 pedidos dele!).</li>\n<li><strong>Correção para 3FN:</strong> Criamos a tabela <code>CLIENTE(id_cliente PK, nome_cliente)</code> e deixamos em <code>PEDIDO(id_pedido PK, id_cliente FK)</code>! <strong>Banco 100% normalizado, limpo e sem redundâncias!</strong></li>\n</ul>\n<hr />\n<h3 id=\"️️-dissecando-questões-no-estilo-exato-da-prova\">🕵️‍♂️ Dissecando Questões no Estilo Exato da Prova</h3>\n<h4 id=\"questão-resolvida-1-baseada-em-ds-2025-q13--ds-2019-q4--1fn\">Questão Resolvida 1 (Baseada em DS 2025 Q13 &amp; DS 2019 Q4 — 1FN)</h4>\n<p><em>Uma tabela <code>FORNECEDORES(cnpj, razao_social, telefones_contato)</code> armazena na coluna <code>telefones_contato</code> o texto <code>\"(11) 3333-1111; (11) 99999-2222\"</code>. Qual forma normal foi diretamente violada e como corrigir?</em> <strong>Análise:</strong> Uma célula contém dois valores (atributo multivalorado/não atômico). Isso viola diretamente a <strong>1ª Forma Normal (1FN)</strong>. Correção: criar tabela separada <code>TELEFONES_FORNECEDOR</code> referenciando <code>cnpj</code> por Chave Estrangeira, com apenas 1 telefone por registro/linha.</p>\n<h4 id=\"questão-resolvida-2-baseada-em-ds-2019-q5--apostas-q15--auto-relacionamento-e-atributo-derivado\">Questão Resolvida 2 (Baseada em DS 2019 Q5 &amp; Apostas Q15 — Auto-relacionamento e Atributo Derivado)</h4>\n<p><em>I. Em uma tabela <code>COLABORADOR</code>, o campo <code>id_lider</code> aponta para <code>id_colaborador</code> da própria tabela, configurando auto-relacionamento. II. O campo <code>valor_total</code> calculado multiplicando <code>quantidade * preco</code> no momento da consulta é um atributo derivado.</em> <strong>Análise:</strong> Ambos os itens são <strong>VERDADEIROS</strong>! Esse é o exemplo clássico de auto-relacionamento <code>1:N</code> e atributo derivado no DER.</p>\n"}, {"id": "mod3", "title": "Módulo 3 • Design Digital, Cores, Vetor vs. Bitmap, Gestalt & UX (Dia 8)", "html": "<h2 id=\"dia-8--design-digital-teoria-das-cores-vetor-vs-bitmap-bancos-de-imagens-gestalt-tipografia-e-ux\">Dia 8 — Design Digital, Teoria das Cores, Vetor vs. Bitmap, Bancos de Imagens, Gestalt, Tipografia e UX</h2>\n<h3 id=\"-contexto-no-mundo-real-por-que-sistemas-técnicos-precisam-de-bom-design\">🎯 Contexto no Mundo Real: Por que Sistemas Técnicos Precisam de Bom Design?</h3>\n<p>Você já entrou em um site onde a letra cinza clara quase some no fundo branco, os botões ficam todos espremidos sem saber qual confirma a compra, ou a logomarca da empresa aparece toda quadriculada (\"pixelada\") quando você dá zoom no celular? Mesmo que o back-end SQL e o código JavaScript funcionem perfeitamente, um design errado faz o usuário abandonar o sistema em segundos — e pior, se mandar uma arte digital em <strong>RGB</strong> para a gráfica imprimir um banner, as cores saem escuras e erradas porque impressoras usam <strong>CMYK</strong>!</p>\n<p>A Fundação FAT dedica cerca de <strong>4 a 5 questões por prova</strong> diretamente a <strong>Design Digital, Cores, Gestalt, Tipografia e Experiência do Usuário (UX)</strong>.</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Todo setup de PC e todo jogo que você abre ilustra perfeitamente o módulo de Design Digital:</p>\n<ul>\n<li><strong>RGB vs. CMYK:</strong> Os LEDs do seu teclado/gabinete <strong>RGB</strong> e o monitor do seu PC funcionam emitindo <strong>LUZ</strong> (<code>Red, Green, Blue</code> de <code>0</code> a <code>255</code> — somou tudo dá luz <strong>branca</strong>!). Já se você imprimir um pôster físico do seu jogo favorito numa gráfica, a impressora usa cartuchos de <strong>TINTA CMYK</strong> (<em>Ciano, Magenta, Amarelo e Preto</em>).</li>\n<li><strong>Hexadecimal <code>#RRGGBB</code>:</strong> Sabe quando você escolhe a cor do cargo no Discord digitando <code>#5865F2</code> (Blurple do Discord) ou <code>#FF0000</code>? Aquilo é literalmente o <strong>RGB escrito em Hexadecimal</strong>!</li>\n<li><strong>Vetor (<code>.SVG</code>) vs. Bitmap (<code>.PNG</code>, <code>.JPG</code>):</strong> Já chegou com a câmera bem colada numa parede ou placa num jogo e percebeu os <strong>quadradinhos borrados (pixels)</strong>? Isso é imagem <strong>Bitmap / Raster</strong>! Já o ícone de mira, logos em <strong><code>.SVG</code></strong> ou fontes do jogo continuam <strong>100% lisos e nítidos</strong> seja em 720p ou dando zoom de 800% em 4K porque são feitos por <strong>fórmulas matemáticas (Vetor)</strong>!</li>\n<li><strong>Gestalt e Nielsen na HUD:</strong> No Discord, todos os canais de texto têm <code>#</code> e os de voz têm um alto-falante (Lei da <strong>Semelhança</strong>); os canais ficam agrupados debaixo da categoria certa (Lei da <strong>Proximidade</strong>); e o ícone de lixeira para deletar mensagem é <strong>Equivalência com o Mundo Real (Nielsen)</strong>!</li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--teoria-das-cores-rgb-hexadecimal-cmyk-e-círculo-cromático\">📚 Parte 1 — Teoria das Cores: RGB, Hexadecimal, CMYK e Círculo Cromático</h3>\n<h4 id=\"1-síntese-aditiva-rgb-vs-síntese-subtrativa-cmyk\">1. Síntese Aditiva (RGB) vs. Síntese Subtrativa (CMYK)</h4>\n<p>Por que existem dois sistemas principais de cores? Porque <strong>emissores de luz (telas)</strong> funcionam de forma oposta a <strong>pigmentos em papel (tintas)</strong>!</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Sistema</th>\n<th style=\"text-align: left;\">Nome e Canais</th>\n<th style=\"text-align: left;\">Natureza Física</th>\n<th style=\"text-align: left;\">Onde é usado</th>\n<th style=\"text-align: left;\">Mistura Máxima vs. Zero</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>RGB</strong></td>\n<td style=\"text-align: left;\"><strong>R</strong>ed (Vermelho), <strong>G</strong>reen (Verde), <strong>B</strong>lue (Azul)<br>Valores de <strong><code>0</code> a <code>255</code></strong> por canal (256³ = 16,7 milhões de cores)</td>\n<td style=\"text-align: left;\"><strong>Síntese Aditiva (LUZ)</strong> — quanto mais luz soma, mais claro fica!</td>\n<td style=\"text-align: left;\"><strong>Telas digitais</strong> (monitores, TVs, celulares, Web, Photoshop web)</td>\n<td style=\"text-align: left;\"><code>rgb(255, 255, 255)</code> = <strong>BRANCO</strong> (luz total)<br><code>rgb(0, 0, 0)</code> = <strong>PRETO</strong> (ausência de luz)</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Hexadecimal</strong></td>\n<td style=\"text-align: left;\"><code>#RRGGBB</code> — usando base 16 (<code>0–9</code> e <code>A–F</code>)</td>\n<td style=\"text-align: left;\">É o <strong>mesmo RGB traduzido para Hexadecimal!</strong></td>\n<td style=\"text-align: left;\"><strong>Código CSS / HTML</strong> e seletores de cor de UI</td>\n<td style=\"text-align: left;\"><code>#FFFFFF</code> = <strong>BRANCO</strong> (<code>255,255,255</code>)<br><code>#000000</code> = <strong>PRETO</strong> (<code>0,0,0</code>)<br><code>#FF0000</code> = Vermelho puro; <code>#2563EB</code> = Azul</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>CMYK</strong></td>\n<td style=\"text-align: left;\"><strong>C</strong>yan (Ciano), <strong>M</strong>agenta, <strong>Y</strong>ellow (Amarelo), blac<strong>K</strong> (Preto)<br>Valores de <strong><code>0%</code> a <code>100%</code></strong></td>\n<td style=\"text-align: left;\"><strong>Síntese Subtrativa (TINTA)</strong> — a tinta absorve luz refletida do papel branco.</td>\n<td style=\"text-align: left;\"><strong>Impressão gráfica</strong> (revistas, cartões de visita, banners, apostilas)</td>\n<td style=\"text-align: left;\"><code>0%, 0%, 0%, 0%</code> = papel branco<br>O <strong>K (Preto)</strong> existe porque misturar só C+M+Y gera marrom escuro impuro e gasta muita tinta.</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Como ler qualquer código Hexadecimal em 3 segundos:</strong> Divida <code>#RRGGBB</code> em 3 pares: os 2 primeiros dígitos são <strong>Vermelho (<code>RR</code>)</strong>, os 2 do meio são <strong>Verde (<code>GG</code>)</strong>, os 2 últimos são <strong>Azul (<code>BB</code>)</strong>. Como <code>00</code> = zero e <code>FF</code> = <code>255</code> (máximo):</p>\n<ul>\n<li><code>#00FF00</code> → zero vermelho, máximo verde, zero azul = <strong>Verde puro</strong>.</li>\n<li><code>#FFFF00</code> → máximo vermelho + máximo verde = na luz RGB dá <strong>Amarelo</strong>!</li>\n<li><code>#CCCCCC</code> ou <code>#808080</code> → os três canais com valor igual produzem sempre <strong>tons de Cinza</strong>!</li>\n</ul>\n<h4 id=\"2-círculo-cromático-e-harmonias-info-2025-q9--ds-2019-q13\">2. Círculo Cromático e Harmonias <em>(INFO 2025 Q9 &amp; DS 2019 Q13)</em></h4>\n<ul>\n<li><strong>Cores Primárias (Modelo RBY tradicional / arte):</strong> <strong>Vermelho, Amarelo e Azul</strong>. (Misturando duas primárias nascem as <strong>Secundárias</strong>: Laranja, Verde e Roxo; misturando primária + secundária nascem as <strong>Terciárias</strong>).</li>\n<li><strong>Cores Análogas:</strong> Ficam <strong>lado a lado</strong> no círculo cromático (ex.: verde + verde-amarelado + amarelo) → visual calmo e harmônico.</li>\n<li><strong>Cores Complementares:</strong> Ficam em <strong>lados diretamente opostos</strong> (180°) no círculo (ex.: azul × laranja; roxo × amarelo; vermelho × verde) → geram <strong>máximo contraste</strong> para chamar atenção em botões <em>Call-to-Action</em>!</li>\n<li><strong>Harmonia em Tríade <em>(DS 2019 Q13)</em>:</strong> Conjunto de <strong>3 cores equidistantes</strong> no círculo cromático (formam um triângulo equilátero de 120°, como Vermelho + Amarelo + Azul).</li>\n</ul>\n<div class=\"callout callout-caution\">\n\n<p><strong>Pegadinha da DS 2025 Q15 (Molde 2):</strong> A banca pede a alternativa com <em>\"exclusivamente padrões de representação de cores\"</em> e coloca como intrusos palavras como <strong>\"CSS\"</strong>, <strong>\"HTML\"</strong>, <strong>\"Primária\"</strong> ou <strong>\"Bitmap\"</strong> no meio de <code>RGB</code>, <code>CMYK</code> e <code>Hexadecimal</code>! Só são sistemas de cores: <strong><code>RGB</code></strong>, <strong><code>CMYK</code></strong>, <strong><code>Hexadecimal</code></strong> (e eventualmente <code>HSL</code>/<code>HSB</code>).</p>\n</div>\n\n<hr />\n<h3 id=\"-parte-2--imagem-vetorial-vs-bitmap-raster-rasterização-e-bancos-de-imagens\">📚 Parte 2 — Imagem Vetorial vs. Bitmap (Raster), Rasterização e Bancos de Imagens</h3>\n<p>Essa é uma das diferenças técnicas mais fáceis de visualizar e mais cobradas pela banca (<strong>DS 2025 Q18</strong> &amp; <strong>INFO 2025 Q10</strong>):</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Característica</th>\n<th style=\"text-align: left;\">Imagem Vetorial</th>\n<th style=\"text-align: left;\">Imagem Bitmap (Matricial / Raster)</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Como é formada</strong></td>\n<td style=\"text-align: left;\"><strong>Fórmulas e equações matemáticas</strong> (coordenadas de pontos, linhas, polígonos e curvas de Bézier)</td>\n<td style=\"text-align: left;\"><strong>Grade (matriz) fixa de pixels</strong> (milhares de quadradinhos coloridos)</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Quando dá zoom (800%)</strong></td>\n<td style=\"text-align: left;\"><strong>Recalcula a matemática na hora:</strong> bordas permanecem <strong>100% nítidas e lisas</strong>, sem jamais perder qualidade!</td>\n<td style=\"text-align: left;\"><strong>Pixela / serrilha:</strong> os quadrados individuais aumentam e a imagem fica <strong>borrada / quadriculada</strong>!</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Para que serve</strong></td>\n<td style=\"text-align: left;\"><strong>Logotipos, ícones, tipografia, ilustrações planas, gráficos técnicos</strong></td>\n<td style=\"text-align: left;\"><strong>Fotografias reais</strong> (onde milhões de variações de luz/pele não cabem em formas geométricas simples)</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Formatos na prova</strong></td>\n<td style=\"text-align: left;\"><strong><code>.SVG</code></strong> (web/HTML), <strong><code>.PDF</code></strong> (quando salva vetores), <strong><code>.AI</code></strong> (Illustrator), <strong><code>.CDR</code></strong> (CorelDraw), <strong><code>.EPS</code></strong></td>\n<td style=\"text-align: left;\"><strong><code>.JPEG</code>/<code>.JPG</code></strong> (compressão c/ perda para fotos, <strong>sem transparência</strong>), <strong><code>.PNG</code></strong> (compressão sem perda + <strong>suporta fundo transparente</strong>), <strong><code>.BMP</code></strong>, <strong><code>.GIF</code></strong>, <strong><code>.WEBP</code></strong></td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li><strong>O que é Rasterização? <em>(INFO 2025 Q10)</em>:</strong> É o processo de <strong>converter uma imagem vetorial em bitmap (grade de pixels)</strong> para ser exibida numa tela ou impressa (ex.: exportar um logo <code>.SVG</code> para <code>.PNG</code> em <code>1024×1024 px</code>).</li>\n<li><strong>Resolução: PPI vs. DPI:</strong> <strong>PPI</strong> (<em>Pixels Per Inch</em>) refere-se à densidade da tela digital; <strong>DPI</strong> (<em>Dots Per Inch</em>) refere-se aos pontos de tinta da impressora (<code>300 DPI</code> é o padrão de alta qualidade para impressão gráfica, enquanto <code>72–96 PPI</code> bastava para monitores antigos).</li>\n</ul>\n<h4 id=\"bancos-de-imagens-e-direitos-autorais-ds-2025-q16\">Bancos de Imagens e Direitos Autorais <em>(DS 2025 Q16)</em></h4>\n<p>Achar uma imagem no Google Imagens <strong>NÃO</strong> dá direito de uso comercial nem escolar livre!</p>\n<ul>\n<li><strong>Domínio Público / <code>CC0</code>:</strong> Autor liberou direitos ou prazo legal expirou — uso 100% livre até comercialmente.</li>\n<li><strong><em>Creative Commons</em> (<code>CC</code>):</strong> Licença padronizada gratuita onde o autor escolhe condições: <strong><code>BY</code></strong> (exige dar crédito ao autor), <strong><code>NC</code></strong> (proíbe uso comercial), <strong><code>ND</code></strong> (proíbe modificar/derivar).</li>\n<li><strong><em>Royalty-Free</em> (Livre de Royalties):</strong> Significa que você paga <strong>uma única vez</strong> (ou assina um banco como Shutterstock/Adobe Stock) e pode usar a foto várias vezes sem pagar taxa adicional por cada cópia impressa ou visualização. (<strong>Atenção:</strong> <em>\"Royalty-Free\"</em> NÃO significa necessariamente <em>\"de graça\"</em>, e sim <em>\"sem royalties recorrentes por tiragem\"</em>!).</li>\n</ul>\n<hr />\n<h3 id=\"-parte-3--princípios-da-gestalt-na-design--interfaces-ds-2025-q17\">📚 Parte 3 — Princípios da Gestalt na Design &amp; Interfaces <em>(DS 2025 Q17)</em></h3>\n<p>A <strong>Gestalt</strong> é uma escola da psicologia alemã que mostra como o cérebro humano <strong>organiza visualmente o todo antes das partes</strong>. Designers usam essas leis para deixar telas intuitivas:</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Lei da Gestalt</th>\n<th style=\"text-align: left;\">O que o cérebro faz</th>\n<th style=\"text-align: left;\">Exemplo real em Aplicativos / Interfaces Web</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>1. Proximidade</strong></td>\n<td style=\"text-align: left;\">Elementos <strong>fisicamente próximos</strong> são percebidos como pertencentes ao <strong>mesmo grupo</strong>.</td>\n<td style=\"text-align: left;\">Num formulário de cadastro, o texto <em>\"CPF:\"</em> fica bem colado à sua caixinha e mais afastado do campo <em>\"Senha:\"</em> abaixo — você não precisa de linha separando para saber qual rótulo pertence a qual caixa! <em>(Apostas Q21)</em></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>2. Semelhança</strong></td>\n<td style=\"text-align: left;\">Elementos com <strong>mesma cor, forma ou tamanho</strong> são interpretados como tendo a mesma função.</td>\n<td style=\"text-align: left;\">Todos os links clicáveis num texto são sublinhados e azuis; todos os botões principais do site têm o mesmo formato arredondado verde.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>3. Fechamento</strong></td>\n<td style=\"text-align: left;\">Quando uma figura tem traços interrompidos ou falhas, o cérebro <strong>completa os espaços vazios mentalmente</strong> para enxergar a forma fechada inteira.</td>\n<td style=\"text-align: left;\">Logotipo do panda da <strong>WWF</strong>, logo da <strong>IBM</strong> feito só com listras horizontais ou ícone de carregamento tracejado.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>4. Continuidade</strong></td>\n<td style=\"text-align: left;\">O olhar segue naturalmente o alinhamento contínuo de curvas ou linhas retas sem quebras bruscas.</td>\n<td style=\"text-align: left;\">Barra de progresso horizontal, carrossel de cards ou alinhamento de ícones em coluna numa barra lateral.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>5. Figura e Fundo</strong></td>\n<td style=\"text-align: left;\">O cérebro separa o <strong>objeto de foco (figura)</strong> do <strong>cenário (fundo)</strong>.</td>\n<td style=\"text-align: left;\">Modal de alerta escurecendo o resto do site atrás; alto contraste entre texto escuro e fundo claro garante legibilidade rápida.</td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h3 id=\"-parte-4--tipografia-google-fonts-e-heurísticas-de-nielsen-ux\">📚 Parte 4 — Tipografia, Google Fonts e Heurísticas de Nielsen (UX)</h3>\n<h4 id=\"1-classificação-tipográfica-ds-2019-q14--info-2025-q15\">1. Classificação Tipográfica <em>(DS 2019 Q14 &amp; INFO 2025 Q15)</em></h4>\n<ul>\n<li><strong>Fontes Serifadas</strong> (<em>Times New Roman</em>, <em>Georgia</em>): Possuem pequenos traços de acabamento (\"pezinhos\"/serifas) nas pontas das hastes, ajudando a guiar o olho em <strong>textos impressos longos</strong> (livros, jornais).</li>\n<li><strong>Fontes Sem Serifa (<em>Sans-Serif</em>)</strong> (<em>Arial</em>, <em>Roboto</em>, <em>Inter</em>, <em>Helvetica</em>): Hastes limpas e geométricas sem enfeites — padrão ouro para <strong>telas digitais, menus e apps</strong> pela nitidez mesmo em pixels pequenos.</li>\n<li><strong>Fontes <em>Script</em> / Caligráficas <em>(DS 2019 Q14)</em>:</strong> Imitam <strong>escrita à mão / letra cursiva fluida</strong>. São excelentes para convites elegantes, logotipos ou títulos decorativos, mas <strong>péssimas para parágrafos longos</strong> por cansarem a leitura!</li>\n<li><strong>Fontes Monoespaçadas</strong> (<em>Consolas</em>, <em>Fira Code</em>, <em>Courier New</em>): Cada letra ocupa exatamente a mesma largura — padrão em <strong>editores de código-fonte e terminais</strong> para alinhar indentação!</li>\n<li><strong>Google Fonts <em>(INFO 2025 Q15)</em>:</strong> Biblioteca online gratuita de fontes web que você importa com <code>&lt;link&gt;</code> no <code>&lt;head&gt;</code> do HTML (e usa no CSS via <code>font-family</code>), garantindo que o site exiba exatamente aquela fonte em qualquer PC/celular sem depender das fontes já instaladas no Windows do usuário!</li>\n</ul>\n<h4 id=\"2-ux--heurísticas-de-usabilidade-de-jakob-nielsen-ds-2019-q15\">2. UX &amp; Heurísticas de Usabilidade de Jakob Nielsen <em>(DS 2019 Q15)</em></h4>\n<p><strong>UI (<em>User Interface</em>)</strong> cuida da aparência visual (botões, cores, fontes); <strong>UX (<em>User Experience</em>)</strong> cuida de toda a jornada de satisfação, facilidade e eficiência do usuário ao resolver seu problema. As heurísticas de Nielsen mais cobradas:</p>\n<ol>\n<li><strong>Equivalência entre o sistema e o mundo real <em>(DS 2019 Q15)</em>:</strong> O sistema deve <strong>falar a linguagem e usar conceitos familiares do usuário</strong>, com metáforas reais e ordem lógica natural — ex.: usar o ícone de <strong>lixeira</strong> para apagar, <strong>carrinho de compras</strong> no e-commerce e texto <em>\"Sem conexão com a internet\"</em> em vez de <code>\"ERR_NETWORK_RESET_0x8004\"</code>.</li>\n<li><strong>Visibilidade do status do sistema:</strong> Manter o usuário informado do que está acontecendo em tempo hábil (barra de carregamento <code>%</code>, mensagem <em>\"Salvando...\"</em>, alerta <em>\"E-mail enviado!\"</em>).</li>\n<li><strong>Prevenção de erros:</strong> Mais vale impedir o erro do que exibir mensagem bonita depois — ex.: pedir confirmação <em>\"Tem certeza que deseja excluir sua conta permanentemente?\"</em> antes de apagar.</li>\n<li><strong>Consistência e padrões:</strong> Não mudar o significado de cores/ícones (botão vermelho normalmente é cancelar/excluir; disquete/nuvem é salvar).</li>\n</ol>\n<hr />\n<h3 id=\"️️-dissecando-questões-no-estilo-exato-da-prova\">🕵️‍♂️ Dissecando Questões no Estilo Exato da Prova</h3>\n<h4 id=\"questão-resolvida-1-baseada-em-ds-2025-q17--q18--vetor-e-gestalt\">Questão Resolvida 1 (Baseada em DS 2025 Q17 &amp; Q18 — Vetor e Gestalt)</h4>\n<p><em>Um designer criou um logotipo em SVG e precisou aplicá-lo tanto no ícone do app (48px) quanto num painel de 4 metros de altura sem serrilhamento. No layout da tela de login, colocou cada rótulo encostado em seu respectivo campo de texto e usou ícones vermelhos em todas as mensagens de erro. Identifique os conceitos aplicados:</em> <strong>Análise:</strong></p>\n<ul>\n<li>Logo em <strong><code>.SVG</code></strong> ampliado sem serrilhar = <strong>Imagem Vetorial</strong> (baseada em equações matemáticas, não pixels).</li>\n<li>Rótulo próximo ao campo formando unidade visual = Lei da <strong>Proximidade</strong> (Gestalt).</li>\n<li>Todos os erros com a mesma cor vermelha agrupados visualmente = Lei da <strong>Semelhança</strong> (Gestalt).</li>\n</ul>\n<h4 id=\"questão-resolvida-2-baseada-em-ds-2019-q15--info-2025-q9\">Questão Resolvida 2 (Baseada em DS 2019 Q15 &amp; INFO 2025 Q9)</h4>\n<p><em>Sobre Harmonia Cromática e UX: I. Cores análogas ficam frente a frente no círculo cromático buscando contraste máximo. II. Usar um ícone de carrinho de supermercado num site de vendas exemplifica a heurística de \"equivalência entre o sistema e o mundo real\" de Nielsen.</em> <strong>Análise:</strong> <strong>Item I é FALSO</strong> — quem fica em lados opostos buscando máximo contraste são as <strong>Complementares</strong> (Análogas ficam <em>lado a lado</em>). <strong>Item II é VERDADEIRO</strong>.</p>\n"}, {"id": "mod4a", "title": "Módulo 4A • Web HTML5/CSS3/DOM/Cookies, Binário & Linux (Dias 9–10)", "html": "<h2 id=\"dia-9--desenvolvimento-web-front-end-html5-semântico-links-tabelas-formulários-css-box-model-dom-e-cookies\">Dia 9 — Desenvolvimento Web Front-end: HTML5 Semântico, Links, Tabelas, Formulários, CSS Box Model, DOM e Cookies</h2>\n<h3 id=\"-contexto-no-mundo-real-o-que-acontece-quando-você-abre-um-site-no-navegador\">🎯 Contexto no Mundo Real: O que Acontece Quando Você Abre um Site no Navegador?</h3>\n<p>Quando você digita <code>www.etec.sp.gov.br</code> ou abre sua conta na Shopee pelo Chrome/Edge, seu navegador recebe arquivos de texto puro vindos de um servidor e precisa transformá-los em milissegundos numa tela interativa. Para fazer isso sem virar bagunça, toda página web moderna trabalha em <strong>3 camadas separadas</strong> (a <strong>Tríade da Web</strong>), além de contar com pequenos arquivos locais no navegador (<strong>Cookies</strong>) para lembrar que você já fez login ou que há 2 produtos no seu carrinho!</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Já apertou <strong><code>F12</code> (Inspecionar Elemento)</strong> no Chrome para ver ou zoar o texto de uma página no navegador (só na sua tela!)? Aquilo funciona porque você está manipulando o <strong>DOM</strong> ao vivo na sua memória!</p>\n<ul>\n<li><strong>HTML / CSS / JS no Discord Web / Twitch:</strong> O <strong>HTML</strong> monta as caixinhas de chat e lista de membros; o <strong>CSS Box Model</strong> dá o espaçamento interno dos balões de mensagem (<code>padding</code>), borda e distância entre usuários (<code>margin</code>); e o <strong>JavaScript + DOM</strong> faz aparecer uma mensagem nova no chat instantaneamente sem recarregar a aba inteira (<code>F5</code>)!</li>\n<li><strong>Cookies (~4 KB) no seu PC:</strong> Como o <strong>Discord Web</strong>, o YouTube e a Twitch lembram que você já está logado com autenticação em 2 fatores sem pedir senha toda vez que abre o Chrome? Através de um <strong>Cookie</strong> — um arquivinho de texto minúsculo (<strong>~4 KB</strong>) salvo <strong>LOCALMENTE dentro da pasta do navegador no SEU PC Windows 11</strong> (e <strong>NUNCA \"na nuvem\"</strong>!). Se você apagar os cookies do navegador, desloga na hora!</li>\n<li><strong><code>GET</code> vs. <code>POST</code>:</strong> Quando você pesquisa <code>?search_query=minecraft</code> no YouTube, vai pela URL (<strong><code>GET</code></strong>); quando digita senha para logar na Steam, vai escondido no corpo da requisição (<strong><code>POST</code></strong>)!</li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--a-tríade-da-web--anatomia-completa-de-uma-página-html5\">📚 Parte 1 — A Tríade da Web &amp; Anatomia Completa de uma Página HTML5</h3>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Camada</th>\n<th style=\"text-align: left;\">Papel Exato</th>\n<th style=\"text-align: left;\">Analogia da Construção de uma Casa</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>HTML5</strong> (<em>HyperText Markup Language</em>)</td>\n<td style=\"text-align: left;\"><strong>Estrutura e Conteúdo Semântico</strong> — diz o que cada elemento <em>é</em> (título, menu, parágrafo, tabela, botão). <em>(<strong>Atenção:</strong> HTML <strong>NÃO</strong> é linguagem de programação, é linguagem de <strong>marcação</strong>!)</em></td>\n<td style=\"text-align: left;\"><strong>Paredes, colunas, portas e janelas</strong> (estrutura bruta)</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>CSS3</strong> (<em>Cascading Style Sheets</em>)</td>\n<td style=\"text-align: left;\"><strong>Estilo Visual e Layout</strong> — cores, fontes, tamanhos, espaçamentos, grid, responsividade e animações.</td>\n<td style=\"text-align: left;\"><strong>Pintura, iluminação, decoração e móveis</strong></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>JavaScript (JS)</strong></td>\n<td style=\"text-align: left;\"><strong>Comportamento e Interatividade</strong> — validar senhas no clique, abrir menus, calcular carrinho e manipular o <strong>DOM</strong> sem recarregar a página.</td>\n<td style=\"text-align: left;\"><strong>Eletricidade, portão automático e automação</strong></td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"-código-real-comentado-página-html5-semântica-completa-m-tec-q3840--ds-2019-q16\">💻 Código Real Comentado: Página HTML5 Semântica Completa <em>(M-Tec Q38–40 &amp; DS 2019 Q16)</em></h4>\n<div class=\"sourceCode\" id=\"cb1\"><pre class=\"sourceCode html\"><code class=\"sourceCode html\"><span id=\"cb1-1\"><a href=\"#cb1-1\" aria-hidden=\"true\"></a><span class=\"dt\">&lt;!DOCTYPE </span>html<span class=\"dt\">&gt;</span>                    <span class=\"co\">&lt;!-- Declara ao navegador que o documento segue o padrão HTML5 --&gt;</span></span>\n<span id=\"cb1-2\"><a href=\"#cb1-2\" aria-hidden=\"true\"></a><span class=\"kw\">&lt;html</span><span class=\"ot\"> lang=</span><span class=\"st\">&quot;pt-BR&quot;</span><span class=\"kw\">&gt;</span>                <span class=\"co\">&lt;!-- Tag raiz: document.documentElement no DOM! --&gt;</span></span>\n<span id=\"cb1-3\"><a href=\"#cb1-3\" aria-hidden=\"true\"></a><span class=\"kw\">&lt;head&gt;</span>                             <span class=\"co\">&lt;!-- Cabeçalho INVISÍVEL: metadados, encoding, título da aba e links CSS --&gt;</span></span>\n<span id=\"cb1-4\"><a href=\"#cb1-4\" aria-hidden=\"true\"></a>    <span class=\"kw\">&lt;meta</span><span class=\"ot\"> charset=</span><span class=\"st\">&quot;UTF-8&quot;</span><span class=\"kw\">&gt;</span>         <span class=\"co\">&lt;!-- Garante acentos (ç, ã, é) corretos --&gt;</span></span>\n<span id=\"cb1-5\"><a href=\"#cb1-5\" aria-hidden=\"true\"></a>    <span class=\"kw\">&lt;title&gt;</span>Portal Etec DS<span class=\"kw\">&lt;/title&gt;</span>  <span class=\"co\">&lt;!-- Texto exibido na aba do navegador --&gt;</span></span>\n<span id=\"cb1-6\"><a href=\"#cb1-6\" aria-hidden=\"true\"></a>    <span class=\"kw\">&lt;link</span><span class=\"ot\"> rel=</span><span class=\"st\">&quot;stylesheet&quot;</span><span class=\"ot\"> href=</span><span class=\"st\">&quot;estilos.css&quot;</span><span class=\"kw\">&gt;</span></span>\n<span id=\"cb1-7\"><a href=\"#cb1-7\" aria-hidden=\"true\"></a><span class=\"kw\">&lt;/head&gt;</span></span>\n<span id=\"cb1-8\"><a href=\"#cb1-8\" aria-hidden=\"true\"></a><span class=\"kw\">&lt;body&gt;</span>                             <span class=\"co\">&lt;!-- CORPO VISÍVEL: tudo que o usuário enxerga na janela --&gt;</span></span>\n<span id=\"cb1-9\"><a href=\"#cb1-9\" aria-hidden=\"true\"></a>    <span class=\"kw\">&lt;header&gt;</span>                       <span class=\"co\">&lt;!-- Tag semântica: cabeçalho do site ou seção --&gt;</span></span>\n<span id=\"cb1-10\"><a href=\"#cb1-10\" aria-hidden=\"true\"></a>        <span class=\"kw\">&lt;h1&gt;</span>Desenvolvimento de Sistemas<span class=\"kw\">&lt;/h1&gt;</span></span>\n<span id=\"cb1-11\"><a href=\"#cb1-11\" aria-hidden=\"true\"></a>        <span class=\"kw\">&lt;nav&gt;</span>                      <span class=\"co\">&lt;!-- Tag semântica: barra de menu com links de navegação --&gt;</span></span>\n<span id=\"cb1-12\"><a href=\"#cb1-12\" aria-hidden=\"true\"></a>            <span class=\"kw\">&lt;a</span><span class=\"ot\"> href=</span><span class=\"st\">&quot;horarios.html&quot;</span><span class=\"kw\">&gt;</span>Mesma Aba (_self padrão)<span class=\"kw\">&lt;/a&gt;</span></span>\n<span id=\"cb1-13\"><a href=\"#cb1-13\" aria-hidden=\"true\"></a>            <span class=\"kw\">&lt;a</span><span class=\"ot\"> href=</span><span class=\"st\">&quot;https://cps.sp.gov.br&quot;</span><span class=\"ot\"> target=</span><span class=\"st\">&quot;_blank&quot;</span><span class=\"ot\"> rel=</span><span class=\"st\">&quot;noopener&quot;</span><span class=\"kw\">&gt;</span>Site CPS (Nova Aba)<span class=\"kw\">&lt;/a&gt;</span></span>\n<span id=\"cb1-14\"><a href=\"#cb1-14\" aria-hidden=\"true\"></a>        <span class=\"kw\">&lt;/nav&gt;</span></span>\n<span id=\"cb1-15\"><a href=\"#cb1-15\" aria-hidden=\"true\"></a>    <span class=\"kw\">&lt;/header&gt;</span></span>\n<span id=\"cb1-16\"><a href=\"#cb1-16\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-17\"><a href=\"#cb1-17\" aria-hidden=\"true\"></a>    <span class=\"kw\">&lt;main&gt;</span>                         <span class=\"co\">&lt;!-- Tag semântica: conteúdo principal único da página --&gt;</span></span>\n<span id=\"cb1-18\"><a href=\"#cb1-18\" aria-hidden=\"true\"></a>        <span class=\"kw\">&lt;section&gt;</span>                  <span class=\"co\">&lt;!-- Seção temática dentro do conteúdo --&gt;</span></span>\n<span id=\"cb1-19\"><a href=\"#cb1-19\" aria-hidden=\"true\"></a>            <span class=\"kw\">&lt;article&gt;</span>              <span class=\"co\">&lt;!-- Conteúdo independente reutilizável (notícia, post, card) --&gt;</span></span>\n<span id=\"cb1-20\"><a href=\"#cb1-20\" aria-hidden=\"true\"></a>                <span class=\"kw\">&lt;h2&gt;</span>Edital de Vagas Remanescentes<span class=\"kw\">&lt;/h2&gt;</span></span>\n<span id=\"cb1-21\"><a href=\"#cb1-21\" aria-hidden=\"true\"></a>                <span class=\"kw\">&lt;p&gt;</span>Prova em <span class=\"kw\">&lt;span</span><span class=\"ot\"> class=</span><span class=\"st\">&quot;destaque&quot;</span><span class=\"kw\">&gt;</span>04 de dezembro<span class=\"kw\">&lt;/span&gt;</span>.<span class=\"kw\">&lt;/p&gt;</span></span>\n<span id=\"cb1-22\"><a href=\"#cb1-22\" aria-hidden=\"true\"></a>            <span class=\"kw\">&lt;/article&gt;</span></span>\n<span id=\"cb1-23\"><a href=\"#cb1-23\" aria-hidden=\"true\"></a>        <span class=\"kw\">&lt;/section&gt;</span></span>\n<span id=\"cb1-24\"><a href=\"#cb1-24\" aria-hidden=\"true\"></a>        <span class=\"kw\">&lt;div</span><span class=\"ot\"> class=</span><span class=\"st\">&quot;caixa-visual&quot;</span><span class=\"kw\">&gt;</span> <span class=\"co\">&lt;!-- DIV: contêiner GENÉRICO em bloco SEM valor semântico! --&gt;</span></span>\n<span id=\"cb1-25\"><a href=\"#cb1-25\" aria-hidden=\"true\"></a>            Aviso em bloco genérico.</span>\n<span id=\"cb1-26\"><a href=\"#cb1-26\" aria-hidden=\"true\"></a>        <span class=\"kw\">&lt;/div&gt;</span></span>\n<span id=\"cb1-27\"><a href=\"#cb1-27\" aria-hidden=\"true\"></a>    <span class=\"kw\">&lt;/main&gt;</span></span>\n<span id=\"cb1-28\"><a href=\"#cb1-28\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-29\"><a href=\"#cb1-29\" aria-hidden=\"true\"></a>    <span class=\"kw\">&lt;footer&gt;</span>                       <span class=\"co\">&lt;!-- Tag semântica: rodapé da página --&gt;</span></span>\n<span id=\"cb1-30\"><a href=\"#cb1-30\" aria-hidden=\"true\"></a>        <span class=\"kw\">&lt;p&gt;</span>© 2026 Etec M-Tec<span class=\"kw\">&lt;/p&gt;</span></span>\n<span id=\"cb1-31\"><a href=\"#cb1-31\" aria-hidden=\"true\"></a>    <span class=\"kw\">&lt;/footer&gt;</span></span>\n<span id=\"cb1-32\"><a href=\"#cb1-32\" aria-hidden=\"true\"></a><span class=\"kw\">&lt;/body&gt;</span></span>\n<span id=\"cb1-33\"><a href=\"#cb1-33\" aria-hidden=\"true\"></a><span class=\"kw\">&lt;/html&gt;</span></span></code></pre></div>\n<div class=\"callout callout-warning\">\n\n<p><strong>Pegadinhas clássicas de HTML5 na Banca:</strong></p>\n<ol>\n<li><strong><code>&lt;div&gt;</code> e <code>&lt;span&gt;</code> NÃO são tags semânticas!</strong> Elas servem apenas como caixas genéricas (<code>&lt;div&gt;</code> ocupa a largura inteira em bloco; <code>&lt;span&gt;</code> fica na mesma linha) quando nenhuma tag semântica faz sentido <em>(M-Tec 2022 Q38)</em>. Tags semânticas reais introduzidas no HTML5 incluem <code>&lt;header&gt;</code>, <code>&lt;nav&gt;</code>, <code>&lt;main&gt;</code>, <code>&lt;section&gt;</code>, <code>&lt;article&gt;</code>, <code>&lt;aside&gt;</code> e <code>&lt;footer&gt;</code> <em>(DS 2019 Q16)</em>.</li>\n<li><strong>Tag <code>&lt;a&gt;</code> e <code>target=\"_blank\"</code> <em>(DS 2025 Q20)</em>:</strong> O atributo <code>href</code> define o endereço de destino e <strong><code>target=\"_blank\"</code> força o link a abrir em uma NOVA ABA (ou nova janela)</strong>. O comportamento padrão (<code>target=\"_self\"</code>) abre na mesma aba atual.</li>\n<li><strong>Visível x Metadados:</strong> Tudo o que aparece na tela vai dentro de <strong><code>&lt;body&gt;</code></strong>, nunca dentro de <code>&lt;head&gt;</code> <em>(M-Tec 2022 Q40)</em>.</li>\n</ol>\n</div>\n\n<hr />\n<h3 id=\"-parte-2--listas-tabelas-html-e-formulários-http-get-vs-post\">📚 Parte 2 — Listas, Tabelas HTML e Formulários HTTP (<code>GET</code> vs. <code>POST</code>)</h3>\n<h4 id=\"1-listas-ol-vs-ul-m-tec-2022-q39\">1. Listas (<code>&lt;ol&gt;</code> vs. <code>&lt;ul&gt;</code>) <em>(M-Tec 2022 Q39)</em></h4>\n<ul>\n<li><strong><code>&lt;ol&gt;</code> (<em>Ordered List</em>):</strong> Lista <strong>ordenada / numerada</strong> (<code>1., 2., 3.</code> ou <code>a., b., c.</code>) — usada quando a sequência importa (ex.: receita passo a passo).</li>\n<li><strong><code>&lt;ul&gt;</code> (<em>Unordered List</em>):</strong> Lista <strong>não ordenada</strong> (marcadores <code>•</code>, quadradinhos) — usada para itens sem ordem fixa (ex.: menu de links, lista de compras).</li>\n<li>Dentro de <strong>ambas</strong>, cada item individual é envolvido pela tag <strong><code>&lt;li&gt;</code></strong> (<em>List Item</em>).</li>\n</ul>\n<h4 id=\"2-tabelas-html-table-tr-th-td-apostas-q24\">2. Tabelas HTML (<code>&lt;table&gt;</code>, <code>&lt;tr&gt;</code>, <code>&lt;th&gt;</code>, <code>&lt;td&gt;</code>) <em>(Apostas Q24)</em></h4>\n<div class=\"sourceCode\" id=\"cb2\"><pre class=\"sourceCode html\"><code class=\"sourceCode html\"><span id=\"cb2-1\"><a href=\"#cb2-1\" aria-hidden=\"true\"></a><span class=\"kw\">&lt;table&gt;</span></span>\n<span id=\"cb2-2\"><a href=\"#cb2-2\" aria-hidden=\"true\"></a>    <span class=\"kw\">&lt;thead&gt;</span></span>\n<span id=\"cb2-3\"><a href=\"#cb2-3\" aria-hidden=\"true\"></a>        <span class=\"kw\">&lt;tr&gt;</span>                        <span class=\"co\">&lt;!-- TR = Table Row: representa UMA LINHA inteira! --&gt;</span></span>\n<span id=\"cb2-4\"><a href=\"#cb2-4\" aria-hidden=\"true\"></a>            <span class=\"kw\">&lt;th&gt;</span>Matéria<span class=\"kw\">&lt;/th&gt;</span>        <span class=\"co\">&lt;!-- TH = Table Header: célula de cabeçalho (negrito/centralizada) --&gt;</span></span>\n<span id=\"cb2-5\"><a href=\"#cb2-5\" aria-hidden=\"true\"></a>            <span class=\"kw\">&lt;th&gt;</span>Nota<span class=\"kw\">&lt;/th&gt;</span></span>\n<span id=\"cb2-6\"><a href=\"#cb2-6\" aria-hidden=\"true\"></a>        <span class=\"kw\">&lt;/tr&gt;</span></span>\n<span id=\"cb2-7\"><a href=\"#cb2-7\" aria-hidden=\"true\"></a>    <span class=\"kw\">&lt;/thead&gt;</span></span>\n<span id=\"cb2-8\"><a href=\"#cb2-8\" aria-hidden=\"true\"></a>    <span class=\"kw\">&lt;tbody&gt;</span></span>\n<span id=\"cb2-9\"><a href=\"#cb2-9\" aria-hidden=\"true\"></a>        <span class=\"kw\">&lt;tr&gt;</span></span>\n<span id=\"cb2-10\"><a href=\"#cb2-10\" aria-hidden=\"true\"></a>            <span class=\"kw\">&lt;td&gt;</span>Banco de Dados<span class=\"kw\">&lt;/td&gt;</span> <span class=\"co\">&lt;!-- TD = Table Data: célula comum com dado --&gt;</span></span>\n<span id=\"cb2-11\"><a href=\"#cb2-11\" aria-hidden=\"true\"></a>            <span class=\"kw\">&lt;td&gt;</span>9.5<span class=\"kw\">&lt;/td&gt;</span></span>\n<span id=\"cb2-12\"><a href=\"#cb2-12\" aria-hidden=\"true\"></a>        <span class=\"kw\">&lt;/tr&gt;</span></span>\n<span id=\"cb2-13\"><a href=\"#cb2-13\" aria-hidden=\"true\"></a>    <span class=\"kw\">&lt;/tbody&gt;</span></span>\n<span id=\"cb2-14\"><a href=\"#cb2-14\" aria-hidden=\"true\"></a><span class=\"kw\">&lt;/table&gt;</span></span></code></pre></div>\n<p><strong>Pegadinha fatal:</strong> <strong><code>&lt;tr&gt;</code> cria uma LINHA</strong>; <strong><code>&lt;td&gt;</code> cria a CÉLULA (dado)</strong>! Nunca confunda <code>&lt;tr&gt;</code> com célula nem <code>&lt;td&gt;</code> com título!</p>\n<h4 id=\"3-formulários-html-methodget-vs-methodpost-apostas-q24\">3. Formulários HTML: <code>method=\"GET\"</code> vs. <code>method=\"POST\"</code> <em>(Apostas Q24)</em></h4>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Critério</th>\n<th style=\"text-align: left;\"><code>method=\"GET\"</code></th>\n<th style=\"text-align: left;\"><code>method=\"POST\"</code></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Onde os dados viajam?</strong></td>\n<td style=\"text-align: left;\">Anexados diretamente ao <strong>final da URL</strong> após <code>?</code> (ex.: <code>busca.php?termo=sql&amp;pag=2</code>).</td>\n<td style=\"text-align: left;\">Enviados ocultos no <strong>corpo (<em>body</em>) da requisição HTTP</strong>.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Segurança e Limite</strong></td>\n<td style=\"text-align: left;\">Expostos na barra de endereços e no histórico do navegador! Tamanho limitado pelo navegador.</td>\n<td style=\"text-align: left;\"><strong>Não ficam expostos na URL!</strong> Suporta grandes volumes e upload de arquivos/imagens.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Quando usar na prática</strong></td>\n<td style=\"text-align: left;\">Pesquisas, filtros de busca, links compartilháveis.</td>\n<td style=\"text-align: left;\"><strong>Login (usuário e senha!), cadastros, pagamentos, envio de dados sensíveis.</strong></td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h3 id=\"-parte-3--css3-seletores-anatomia-da-regra-box-model-e-transform\">📚 Parte 3 — CSS3: Seletores, Anatomia da Regra, Box Model e <code>transform</code></h3>\n<h4 id=\"1-anatomia-da-regra-css-e-seletores-info-2025-q14\">1. Anatomia da Regra CSS e Seletores <em>(INFO 2025 Q14)</em></h4>\n<div class=\"sourceCode\" id=\"cb3\"><pre class=\"sourceCode css\"><code class=\"sourceCode css\"><span id=\"cb3-1\"><a href=\"#cb3-1\" aria-hidden=\"true\"></a><span class=\"co\">/* Seletor { propriedade: valor; } */</span></span>\n<span id=\"cb3-2\"><a href=\"#cb3-2\" aria-hidden=\"true\"></a>p { <span class=\"kw\">color</span>: <span class=\"cn\">#1e293b</span><span class=\"op\">;</span> }           <span class=\"co\">/* Seletor de TAG/ELEMENTO: atinge todos os &lt;p&gt; */</span></span>\n<span id=\"cb3-3\"><a href=\"#cb3-3\" aria-hidden=\"true\"></a><span class=\"fu\">.cartao</span> { <span class=\"kw\">padding</span>: <span class=\"dv\">16</span><span class=\"dt\">px</span><span class=\"op\">;</span> }      <span class=\"co\">/* Seletor de CLASSE (.): pode repetir em vários elementos */</span></span>\n<span id=\"cb3-4\"><a href=\"#cb3-4\" aria-hidden=\"true\"></a><span class=\"pp\">#menu-topo</span> { <span class=\"kw\">height</span>: <span class=\"dv\">60</span><span class=\"dt\">px</span><span class=\"op\">;</span> }    <span class=\"co\">/* Seletor de ID (#): identificador ÚNICO na página! */</span></span></code></pre></div>\n<p><em>(Lembre da especificidade: um seletor <code>#id</code> é mais forte que uma <code>.classe</code>, que é mais forte que uma <code>tag</code>!).</em></p>\n<h4 id=\"2-css-box-model-modelo-de-caixa--apostas-q25\">2. CSS Box Model (<em>Modelo de Caixa</em> — <em>Apostas Q25</em>)</h4>\n<p>Para o CSS, <strong>todo elemento HTML é uma caixa retangular</strong> formada por <strong>4 camadas concêntricas (de dentro para fora)</strong>:</p>\n<pre class=\"text\"><code>┌─────────────── MARGIN (espaço EXTERNO entre caixas vizinhas) ───────────────┐\n│ ┌───────────── BORDER (linha/borda visível da caixa) ───────────────────────┐ │\n│ │ ┌─────────── PADDING (acolchoamento INTERNO entre conteúdo e borda) ────┐ │ │\n│ │ │           CONTENT (texto, imagem: width x height)                     │ │ │\n│ │ └───────────────────────────────────────────────────────────────────────┘ │ │\n│ └───────────────────────────────────────────────────────────────────────────┘ │\n└───────────────────────────────────────────────────────────────────────────────┘\n</code></pre>\n<ul>\n<li><strong>Troca clássica na prova:</strong> Confundir <strong><code>padding</code></strong> (espaço <strong>entre o texto/conteúdo e a borda</strong>, dentro do fundo colorido do botão) com <strong><code>margin</code></strong> (espaço <strong>para fora da borda</strong>, empurrando outros elementos distantes).</li>\n</ul>\n<h4 id=\"3-propriedade-css3-transform-ds-2019-q17\">3. Propriedade CSS3 <code>transform</code> <em>(DS 2019 Q17)</em></h4>\n<p>Permite mover, girar, inclinar e redimensionar elementos 2D/3D sem quebrar o fluxo da página:</p>\n<ul>\n<li><code>transform: scale(1.3);</code> → <strong>Aumenta ou diminui proporcionalmente</strong> o tamanho (<code>1.3</code> = 130%).</li>\n<li><code>transform: rotate(45deg);</code> → <strong>Gira/rotaciona</strong> o elemento em graus.</li>\n<li><code>transform: translate(20px, -10px);</code> → <strong>Desloca/move</strong> horizontal e verticalmente.</li>\n<li><code>transform: skew(15deg, 5deg);</code> → <strong>Inclina/distorce</strong> o ângulo dos eixos.</li>\n</ul>\n<hr />\n<h3 id=\"-parte-4--a-árvore-dom-no-javascript-e-cookies-http\">📚 Parte 4 — A Árvore DOM no JavaScript e Cookies HTTP</h3>\n<h4 id=\"1-como-o-javascript-enxerga-a-página-dom-document-object-model--ds-2019-q19\">1. Como o JavaScript Enxerga a Página: DOM <em>(Document Object Model — DS 2019 Q19)</em></h4>\n<p>Quando o navegador lê o HTML, ele transforma cada tag em um <strong>nó de uma árvore hierárquica na memória RAM</strong> chamada <strong>DOM</strong>:</p>\n<ul>\n<li>Raiz da árvore: <code>document.documentElement</code> (o elemento <code>&lt;html&gt;</code>).</li>\n<li>Métodos clássicos cobrados pela banca FAT:\n<ul>\n<li><code>document.getElementById(\"aviso\")</code> → Captura o elemento que possui <code>id=\"aviso\"</code>.</li>\n<li><code>document.querySelector(\".card\")</code> → Captura usando qualquer seletor CSS.</li>\n<li><code>document.createElement(\"li\")</code> / <code>document.createTextNode(\"Novo item\")</code> → Cria novos nós HTML ou de texto em memória.</li>\n<li><code>pai.appendChild(filho)</code> → Encaixa o novo nó dentro da página viva.</li>\n<li><code>elemento.parentNode</code> → Sobe um degrau acessando o <strong>nó pai</strong> daquele elemento na árvore!</li>\n</ul></li>\n</ul>\n<h4 id=\"2-cookies-no-navegador-a-verdade-contra-a-pegadinha-ds-2025-q21\">2. Cookies no Navegador: A Verdade Contra a Pegadinha! <em>(DS 2025 Q21)</em></h4>\n<p>O protocolo HTTP é <em>stateless</em> (sem memória): por padrão, a cada clique num link, o servidor esquece quem você é! Para resolver isso, quando você faz login, o servidor pede ao seu navegador para gravar um <strong>Cookie</strong>.</p>\n<p><strong>Fatos oficiais sobre Cookies (decore cada um deles):</strong></p>\n<ol>\n<li><strong>O que são?</strong> Pequenos <strong>arquivos de texto simples</strong> (par <code>chave=valor</code>, ex.: <code>tema=escuro</code>).</li>\n<li><strong>Onde ficam armazenados?</strong> <strong>EXCLUSIVAMENTE NO NAVEGADOR / COMPUTADOR LOCAL DO USUÁRIO (CLIENTE)</strong>! Eles trafegam nos cabeçalhos HTTP entre cliente e servidor, mas <strong>NUNCA moram \"na nuvem\"</strong> como um banco remoto!</li>\n<li><strong>Qual o limite tradicional?</strong> Cerca de <strong>4 KB (~4.096 bytes)</strong> por cookie! Não servem para guardar vídeos, fotos ou bancos pesados.</li>\n<li><strong>Os 2 tipos quanto à validade:</strong>\n<ul>\n<li><strong>Cookie de Sessão (<em>Session Cookie</em>):</strong> Não define prazo de expiração (<code>Expires</code> / <code>Max-Age</code>). <strong>Apaga-se automaticamente assim que o navegador é fechado</strong>.</li>\n<li><strong>Cookie Persistente / Permanente:</strong> Tem data/tempo de expiração (<code>max-age=604800</code> para 7 dias). Continua salvo no disco do seu navegador mesmo após desligar e religar o PC!</li>\n</ul></li>\n<li><strong>Manipulação:</strong> Em JS lê/escreve via <code>document.cookie</code> (exceto quando o servidor ativa a flag de segurança <strong><code>HttpOnly</code></strong>, impedindo scripts maliciosos XSS de roubarem o cookie de sessão!).</li>\n<li><strong>Comparação rápida com Web Storage:</strong> Diferente de cookies (~4 KB enviados em toda requisição HTTP), <strong><code>localStorage</code></strong> e <strong><code>sessionStorage</code></strong> permitem guardar ~5–10 MB apenas localmente no navegador sem viajar em todo cabeçalho HTTP.</li>\n</ol>\n<hr />\n<h3 id=\"️️-dissecando-questões-no-estilo-exato-da-prova\">🕵️‍♂️ Dissecando Questões no Estilo Exato da Prova</h3>\n<h4 id=\"questão-resolvida-1-baseada-em-ds-2025-q21--cookies\">Questão Resolvida 1 (Baseada em DS 2025 Q21 — Cookies)</h4>\n<p><em>Analise as afirmativas sobre Cookies Web: I. Cookies são grandes arquivos multimídia armazenados diretamente nos servidores em nuvem da hospedagem. II. Cookies possuem tamanho pequeno (~4 KB) e ficam armazenados no navegador do usuário. III. Cookies podem ser temporários (de sessão, apagados ao fechar o browser) ou permanentes (com data de validade).</em></p>\n<ul>\n<li><strong>Item I é FALSO:</strong> Cookies são arquivos de <strong>texto pequenos (~4 KB)</strong> e ficam <strong>no navegador local do cliente</strong>, jamais na nuvem!</li>\n<li><strong>Itens II e III são VERDADEIROS.</strong></li>\n</ul>\n<h4 id=\"questão-resolvida-2-baseada-em-m-tec-q3839--apostas-q2425\">Questão Resolvida 2 (Baseada em M-Tec Q38–39 &amp; Apostas Q24–25)</h4>\n<p><em>Sobre HTML5 e CSS3: I. A tag <code>&lt;tr&gt;</code> representa uma célula de conteúdo na tabela e <code>&lt;td&gt;</code> cria uma linha. II. Formulários com senha devem usar <code>method=\"POST\"</code> em vez de <code>GET</code> para não expor os campos na URL. III. No CSS Box Model, <code>padding</code> é o espaçamento interno entre conteúdo e borda.</em></p>\n<ul>\n<li><strong>Item I é FALSO:</strong> É exatamente o contrário (<code>&lt;tr&gt;</code> = linha / <em>table row</em>; <code>&lt;td&gt;</code> = célula / <em>table data</em>).</li>\n<li><strong>Itens II e III são VERDADEIROS.</strong></li>\n</ul>\n<hr><h2 id=\"dia-10--sistemas-numéricos-bináriohexadecimal-hardware-memórias-so-vmsdocker-e-linux\">Dia 10 — Sistemas Numéricos (Binário/Hexadecimal), Hardware, Memórias, SO, VMs/Docker e Linux</h2>\n<h3 id=\"-contexto-no-mundo-real-de-bits-0-e-1-até-servidores-linux-na-nuvem\">🎯 Contexto no Mundo Real: De Bits <code>0 e 1</code> até Servidores Linux na Nuvem</h3>\n<p>Dentro do chip do seu celular ou notebook não existem letras <code>'A'</code>, números <code>255</code> nem cores azuis <code>#2563EB</code> flutuando soltos. Tudo — cada pixel da tela, cada música MP3 e cada comando Python — é convertido para sequências elétricas binárias (<strong><code>0</code></strong> sem tensão / <strong><code>1</code></strong> com tensão). Para economizar espaço ao exibir longas sequências de 8, 16 ou 32 bits em endereços de memória e cores CSS, engenheiros agrupam bits em <strong>Hexadecimal</strong>.</p>\n<p>Ao mesmo tempo, quando você abre o Windows ou roda servidores <strong>Linux</strong> usando <strong>Máquinas Virtuais</strong> ou <strong>Contêineres Docker</strong>, o <strong>Sistema Operacional</strong> precisa decidir o que fica na rápida <strong>Memória RAM</strong>, o que vai para o <strong>SSD</strong> e como organizar pastas do sistema sem deixar programas invadirem a memória uns dos outros.</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Se você já comparou placas/memórias, mexeu em pasta de jogo no Windows ou tentou hospedar um servidor de Minecraft/bot de Discord, você já conhece na prática o Dia 10:</p>\n<ul>\n<li><strong>SSD (Flash NAND) vs. HDD vs. RAM:</strong> Por que instalar GTA/Valorant no <strong>SSD</strong> carrega o mapa em 3 segundos enquanto no <strong>HD antigo (disco girando com agulha)</strong> trava por 1 minuto? Porque o SSD usa chips <strong>Flash NAND sem partes móveis</strong>. E a <strong>RAM</strong> guarda só o que está <strong>rodando aberto agora</strong> (desligou o PC da tomada, zera na hora!).</li>\n<li><strong>Por que o jogo dá <em>stuttering</em> quando falta RAM?</strong> Você abre Jogo pesado + Discord + 15 abas do Chrome numa máquina com pouca RAM. A RAM lota! Aí o <strong>Sistema Operacional</strong> usa <strong>Memória Virtual (Arquivo de Paginação / <em>Swap</em>)</strong>: pega partes da RAM e joga no <strong>SSD/HD</strong> para o PC não fechar os programas à força — como o SSD é bem mais lento que a RAM, o FPS cai na hora!</li>\n<li><strong>VM vs. Contêiner Docker:</strong> Subir um servidor dedicado de Minecraft ou bot de Discord dentro de uma <strong>VM</strong> (VirtualBox) é instalar um Windows/Linux inteiro virtualizado só pra isso (come GBs de RAM!). Subir via <strong>Contêiner Docker</strong> isola só o app e suas libs <strong>compartilhando o mesmo Kernel</strong> do servidor — inicia em segundos!</li>\n<li><strong>Binário &amp; Hex:</strong> Aquele clássico código de erro/cor <strong><code>255</code></strong> (ex.: <code>255.255.255.0</code> no roteador ou <code>rgb(255,0,0)</code>) existe porque <code>255</code> é exatamente <strong>1 Byte inteiro ligado (<code>11111111₂ = FF₁₆</code>)</strong>!</li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--conversão-passo-a-passo-decimal--binário-base-2--hexadecimal-base-16\">📚 Parte 1 — Conversão Passo a Passo: Decimal ↔︎ Binário (Base 2) ↔︎ Hexadecimal (Base 16)</h3>\n<h4 id=\"vocabulário-de-capacidade\">Vocabulário de Capacidade</h4>\n<ul>\n<li><strong>1 Bit (<em>Binary Digit</em>):</strong> Menor unidade de informação (<code>0</code> ou <code>1</code>).</li>\n<li><strong>1 Byte = 8 bits:</strong> Consegue representar <strong><code>2⁸ = 256</code> valores diferentes</strong> — em inteiros sem sinal, vai de <strong><code>0</code> (<code>00000000</code>) até <code>255</code> (<code>11111111</code>)</strong>! <em>(É por isso que IPs <code>192.168.0.255</code> e cores RGB <code>rgb(255, 255, 255)</code> param exatamente em <code>255</code>!)</em></li>\n</ul>\n<h4 id=\"a-como-converter-decimal--binário-2-métodos-para-conferir-na-prova\">A. Como Converter Decimal → Binário (2 Métodos para Conferir na Prova!)</h4>\n<p><strong>Método 1 — Régua das 8 Potências de 2 (o mais rápido na hora da prova!):</strong> Escreva as potências de 2 da direita para a esquerda em 8 casas: <code>128 | 64 | 32 | 16 | 8 | 4 | 2 | 1</code></p>\n<p>Vamos converter <strong><code>100₁₀</code></strong> <em>(DS 2019 Q20)</em>:</p>\n<ul>\n<li><code>128</code> cabe em 100? Não → bit <code>0</code></li>\n<li><strong><code>64</code></strong> cabe em 100? <strong>Sim</strong> → bit <strong><code>1</code></strong> (sobra <code>100 - 64 = 36</code>)</li>\n<li><strong><code>32</code></strong> cabe em 36? <strong>Sim</strong> → bit <strong><code>1</code></strong> (sobra <code>36 - 32 = 4</code>)</li>\n<li><code>16</code> cabe em 4? Não → bit <code>0</code></li>\n<li><code>8</code> cabe em 4? Não → bit <code>0</code></li>\n<li><strong><code>4</code></strong> cabe em 4? <strong>Sim</strong> → bit <strong><code>1</code></strong> (sobra <code>4 - 4 = 0</code>)</li>\n<li><code>2</code> → <code>0</code>, <code>1</code> → <code>0</code>. Resultado: <strong><code>01100100₂</code></strong> (ou <code>1100100₂</code>). Conferência: <code>64 + 32 + 4 = 100</code>!</li>\n</ul>\n<p><strong>Método 2 — Divisões Sucessivas por 2 (<code>DIV 2</code> e <code>MOD 2</code>):</strong> Para <strong><code>250₁₀</code></strong>:</p>\n<ul>\n<li><code>250 ÷ 2 = 125</code>, resto <strong><code>0</code></strong></li>\n<li><code>125 ÷ 2 = 62</code>, resto <strong><code>1</code></strong></li>\n<li><code>62 ÷ 2 = 31</code>, resto <strong><code>0</code></strong></li>\n<li><code>31 ÷ 2 = 15</code>, resto <strong><code>1</code></strong></li>\n<li><code>15 ÷ 2 = 7</code>, resto <strong><code>1</code></strong></li>\n<li><code>7 ÷ 2 = 3</code>, resto <strong><code>1</code></strong></li>\n<li><code>3 ÷ 2 = 1</code>, resto <strong><code>1</code></strong></li>\n<li><code>1 ÷ 2 = 0</code>, resto <strong><code>1</code></strong> Lendo os restos <strong>de baixo para cima</strong>: <strong><code>11111010₂</code></strong> (<code>128+64+32+16+8+2 = 250</code>)!</li>\n</ul>\n<h4 id=\"b-como-converter-decimal--binário--hexadecimal-base-16\">B. Como Converter Decimal / Binário ↔︎ Hexadecimal (Base 16)</h4>\n<p>Como só temos 10 algarismos (<code>0</code> a <code>9</code>), a Base 16 usa <strong>letras para representar de 10 a 15</strong>: <code>0..9</code> normal | <strong><code>A = 10</code></strong> | <strong><code>B = 11</code></strong> | <strong><code>C = 12</code></strong> | <strong><code>D = 13</code></strong> | <strong><code>E = 14</code></strong> | <strong><code>F = 15</code></strong>.</p>\n<p><strong>Regra direta:</strong> Divida por <strong><code>16</code></strong> ou separe o byte binário em <strong>dois blocos de 4 bits</strong> (cada grupo de 4 bits vale exatamente 1 dígito Hexadecimal, de <code>0</code> a <code>15</code>!):</p>\n<p>Veja dois exemplos reais da <strong>DS 2019 Q20</strong>:</p>\n<ol>\n<li><strong>Converter <code>100₁₀</code> para Hexadecimal:</strong>\n<ul>\n<li>Divisão por 16: <code>100 ÷ 16</code> = quociente <strong><code>6</code></strong> (<code>6 × 16 = 96</code>), resto <strong><code>4</code></strong>. Logo, <strong><code>64₁₆</code></strong>!</li>\n<li><em>(Conferindo pelos 4 bits: <code>0110 | 0100</code> → esquerda <code>4+2 = 6</code>, direita <code>4</code> → <code>64₁₆</code>!)</em></li>\n</ul></li>\n<li><strong>Converter <code>250₁₀</code> para Hexadecimal:</strong>\n<ul>\n<li>Divisão por 16: <code>250 ÷ 16</code> = quociente <strong><code>15</code></strong> (<code>15 × 16 = 240</code>), resto <strong><code>10</code></strong>.</li>\n<li>Troca números $\\ge 10$ pelas letras: <code>15 = F</code>, <code>10 = A</code>. Logo, <strong><code>FA₁₆</code></strong>!</li>\n<li><em>(Conferindo pelos 4 bits: <code>1111 | 1010</code> → esquerda <code>8+4+2+1 = 15 (F)</code>, direita <code>8+2 = 10 (A)</code> → <code>FA₁₆</code>!)</em></li>\n</ul></li>\n<li><strong>E <code>255₁₀</code> <em>(INFO 2025 Q4)</em>?</strong> <code>1111 1111₂</code> = <strong><code>FF₁₆</code></strong> (o máximo de <code>#RRGGBB</code> no CSS!).</li>\n</ol>\n<hr />\n<h3 id=\"-parte-2--arquitetura-de-hardware--hierarquia-de-memórias\">📚 Parte 2 — Arquitetura de Hardware &amp; Hierarquia de Memórias</h3>\n<p>Na arquitetura clássica de <strong>Von Neumann</strong>, o computador integra <strong>CPU</strong> (Processador: <strong>ULA</strong> faz cálculos/lógica, <strong>UC</strong> coordena o fluxo e <strong>Registradores</strong> guardam dados imediatos), <strong>Memória</strong> e <strong>Dispositivos de Entrada/Saída (E/S)</strong> interligados por barramentos.</p>\n<h4 id=\"hierarquia-de-memórias-quanto-mais-perto-da-cpu--mais-rápida-menor-capacidade-maior-custogb\">Hierarquia de Memórias (Quanto mais perto da CPU → Mais rápida, Menor capacidade, Maior custo/GB)</h4>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Memória</th>\n<th style=\"text-align: center;\">Volátil? (Apaga sem energia?)</th>\n<th style=\"text-align: left;\">Tecnologia / Papel Oficial</th>\n<th style=\"text-align: left;\">Detalhe Cobrado pela FAT</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Registradores &amp; Cache (L1/L2/L3)</strong></td>\n<td style=\"text-align: center;\"><strong>Sim (Volátil)</strong></td>\n<td style=\"text-align: left;\">Estática (<code>SRAM</code>) dentro do próprio chip do processador.</td>\n<td style=\"text-align: left;\">Velocidade máxima; evita que a CPU espere a RAM ler dados repetidos.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Memória RAM</strong> <em>(Principal)</em></td>\n<td style=\"text-align: center;\"><strong>Sim (Volátil)</strong></td>\n<td style=\"text-align: left;\">Dinâmica (<code>DRAM</code> / DDR4, DDR5).</td>\n<td style=\"text-align: left;\">Carrega o Sistema Operacional e todos os programas/dados <strong>em execução no momento</strong>. Desligou o PC, zera!</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Memória ROM</strong> <em>(BIOS / UEFI)</em></td>\n<td style=\"text-align: center;\"><strong>Não (Não volátil)</strong></td>\n<td style=\"text-align: left;\">Chips de leitura gravados com firmware de inicialização.</td>\n<td style=\"text-align: left;\">Executa o <strong>POST</strong> (autoteste de hardware ao ligar) e encontra o SSD/HD para iniciar o <em>boot</em>.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>SSD</strong> <em>(Solid State Drive)</em></td>\n<td style=\"text-align: center;\"><strong>Não (Não volátil)</strong></td>\n<td style=\"text-align: left;\">Armazenamento secundário sólido usando <strong>chips de memória Flash NAND</strong>.</td>\n<td style=\"text-align: left;\"><strong>Sem partes mecânicas móveis!</strong> Muito mais rápido, silencioso e resistente a quedas/vibrações do que HDD. <em>(DS 2019 Q21)</em></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>HDD</strong> <em>(Hard Disk Drive)</em></td>\n<td style=\"text-align: center;\"><strong>Não (Não volátil)</strong></td>\n<td style=\"text-align: left;\">Discos magnéticos giratórios com cabeça mecânica de leitura/escrita.</td>\n<td style=\"text-align: left;\">Barato por TB para guardar arquivos grandes/backups, porém mais lento e sensível a choques físicos.</td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h3 id=\"-parte-3--sistema-operacional-gerenciamento-de-memória-vms-vs-contêineres-docker\">📚 Parte 3 — Sistema Operacional: Gerenciamento de Memória, VMs vs. Contêineres (Docker)</h3>\n<p>Um <strong>Sistema Operacional (SO)</strong> — como Windows, Linux, macOS ou Android — atua como o <strong>intermediário</strong> entre o hardware físico e o usuário/softwares (<em>M-Tec 2022 Q35</em>). Sua parte central chama-se <strong>Kernel (Núcleo)</strong>.</p>\n<h4 id=\"1-gerenciamento-de-memória-e-memória-virtual-ds-2025-q27\">1. Gerenciamento de Memória e Memória Virtual (<em>DS 2025 Q27</em>)</h4>\n<p>Quando você abre o Chrome (com 20 abas), VS Code e Spotify ao mesmo tempo, o SO é o gerente que garante que:</p>\n<ul>\n<li><strong>Proteção/Isolamento:</strong> Um programa travado não consiga ler ou sobrescrever a memória RAM de outro processo nem do Kernel.</li>\n<li><strong>Alocação e Desalocação:</strong> Entrega blocos de RAM para quem abre e recolhe de volta ao fechar (evitando vazamentos globais).</li>\n<li><strong>Memória Virtual (<em>Paginação / Swap</em>):</strong> Se a RAM física de 8 GB encher, o SO pega blocos (\"páginas\") pouco usados no momento e move temporariamente para uma área reservada no <strong>SSD/HD</strong> (<em>arquivo de paginação / partição swap</em>). Isso impede o computador de fechar apps à força, <strong>mas deixa o sistema lento</strong> porque SSD/HDD é muito mais lento que a RAM!</li>\n</ul>\n<h4 id=\"2-virtualização-tradicional-vm-vs-contêineres-docker-info-2025-q5-e-q16\">2. Virtualização Tradicional (VM) vs. Contêineres (Docker) <em>(INFO 2025 Q5 e Q16)</em></h4>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Critério</th>\n<th style=\"text-align: left;\">Máquina Virtual (VM — VirtualBox, VMware)</th>\n<th style=\"text-align: left;\">Contêiner (Docker / Podman)</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Como isola</strong></td>\n<td style=\"text-align: left;\">Um <strong>Hypervisor</strong> virtualiza hardware completo e roda <strong>um Sistema Operacional convidado (<em>Guest OS</em>) inteiro</strong> para cada VM.</td>\n<td style=\"text-align: left;\">Isola processos, arquivos e rede usando recursos nativos do kernel (<em>namespaces</em> e <em>cgroups</em>), <strong>COMPARTILHANDO o mesmo Kernel do SO hospedeiro</strong>!</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Peso e Velocidade</strong></td>\n<td style=\"text-align: left;\"><strong>Pesada</strong> (gigabytes por VM; demora minutos para ligar porque dá <em>boot</em> completo em outro Windows/Linux).</td>\n<td style=\"text-align: left;\"><strong>Ultraleve</strong> (megabytes; inicia em frações de segundo porque não carrega outro kernel!).</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Ideal para</strong></td>\n<td style=\"text-align: left;\">Rodar um Windows completo dentro de um Mac/Linux, isolamento máximo de hardware.</td>\n<td style=\"text-align: left;\">Empacotar aplicações web + dependências (<em>\"funciona igual na minha máquina e no servidor\"</em>). <em>(INFO 2025 Q16)</em></td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h3 id=\"-parte-4--sistema-de-arquivos-linux-fhs-comandos-e-produtividade-windowsword\">📚 Parte 4 — Sistema de Arquivos Linux (FHS), Comandos e Produtividade Windows/Word</h3>\n<h4 id=\"1-diretórios-oficiais-do-linux-fhs--filesystem-hierarchy-standard-info-2025-q18\">1. Diretórios Oficiais do Linux (FHS — <em>Filesystem Hierarchy Standard</em>) <em>(INFO 2025 Q18)</em></h4>\n<p>No Linux não existem unidades <code>C:\\</code> ou <code>D:\\</code>! Tudo nasce de uma única árvore começando na <strong>raiz <code>/</code></strong>. Memorize os 7 diretórios campeões de prova:</p>\n<ul>\n<li><strong><code>/</code></strong>: Raiz absoluta do sistema de arquivos.</li>\n<li><strong><code>/bin</code></strong> (e <code>/usr/bin</code>): Arquivos <strong>binários executáveis</strong> dos comandos essenciais do sistema (<code>ls</code>, <code>cp</code>, <code>cat</code>).</li>\n<li><strong><code>/etc</code></strong>: Arquivos de <strong>configuração</strong> do sistema e servidores (<code>passwd</code>, <code>hosts</code>, configs do Apache/Nginx).</li>\n<li><strong><code>/home</code></strong>: Pastas pessoais dos <strong>usuários comuns</strong> (ex.: <code>/home/lucas</code>).</li>\n<li><strong><code>/root</code></strong>: Pasta pessoal exclusiva do <strong>superusuário administrador (<code>root</code>)</strong>. <strong>Pegadinha:</strong> <code>/root</code> NÃO é a raiz <code>/</code>, é apenas a pasta home do admin!</li>\n<li><strong><code>/lib</code></strong>: <strong>Bibliotecas</strong> compartilhadas necessárias pelos binários.</li>\n<li><strong><code>/usr</code></strong>: Softwares e utilitários instalados para uso dos usuários.</li>\n<li><strong><code>/var</code></strong>: Dados <strong>variáveis</strong> que crescem com o tempo (especialmente <strong>logs</strong> em <code>/var/log</code>, filas de impressão/e-mail e caches).</li>\n<li><strong><code>/tmp</code></strong>: Arquivos <strong>temporários</strong> (frequentemente apagados ao reiniciar).</li>\n</ul>\n<div class=\"callout callout-caution\">\n\n<p><strong>Pegadinha famosa (INFO 2025 Q18 — Lista com Intruso):</strong> A banca pergunta qual alternativa contém <strong>APENAS diretórios padrão Linux</strong> e enfia no meio <code>/mkdir</code>, <code>/ls</code>, <code>/rm</code>, <code>/cd</code>, <code>/cat</code> ou <code>/apt</code>! <strong><code>mkdir</code>, <code>ls</code>, <code>rm</code>, <code>cd</code>, <code>cat</code> são COMANDOS executados no terminal</strong>, <strong>NÃO são pastas do sistema!</strong></p>\n</div>\n\n<h4 id=\"2-comandos-essenciais-de-terminal-linux-ds-2019-q22\">2. Comandos Essenciais de Terminal Linux <em>(DS 2019 Q22)</em></h4>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Comando</th>\n<th style=\"text-align: left;\">Significado e Ação</th>\n<th style=\"text-align: left;\">Exemplo prático</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong><code>pwd</code></strong></td>\n<td style=\"text-align: left;\"><em>Print Working Directory</em>: mostra em qual pasta você está agora</td>\n<td style=\"text-align: left;\"><code>pwd</code> → <code>/home/lucas/projeto</code></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong><code>ls</code></strong></td>\n<td style=\"text-align: left;\"><em>List</em>: lista arquivos e subpastas (<code>ls -la</code> mostra detalhado + ocultos iniciados por <code>.</code>)</td>\n<td style=\"text-align: left;\"><code>ls -l</code></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong><code>cd</code></strong></td>\n<td style=\"text-align: left;\"><em>Change Directory</em>: entra ou volta de pasta (<code>cd ..</code> sobe um nível)</td>\n<td style=\"text-align: left;\"><code>cd /etc</code></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong><code>mkdir</code></strong></td>\n<td style=\"text-align: left;\"><em>Make Directory</em>: cria uma nova pasta vazia</td>\n<td style=\"text-align: left;\"><code>mkdir fotos</code></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong><code>cp</code> / <code>mv</code></strong></td>\n<td style=\"text-align: left;\"><strong><code>cp</code></strong> copia arquivo/pasta (<code>cp -r</code>); <strong><code>mv</code></strong> <strong>move OU renomeia</strong> arquivo!</td>\n<td style=\"text-align: left;\"><code>mv antigo.txt novo.txt</code></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong><code>rm</code></strong></td>\n<td style=\"text-align: left;\"><em>Remove</em>: apaga arquivos (<code>rm -rf</code> apaga pastas recursivamente — cuidado!)</td>\n<td style=\"text-align: left;\"><code>rm teste.txt</code></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong><code>chmod</code></strong></td>\n<td style=\"text-align: left;\"><em>Change Mode</em>: altera <strong>permissões</strong> de leitura (<code>r=4</code>), escrita (<code>w=2</code>), execução (<code>x=1</code>)</td>\n<td style=\"text-align: left;\"><code>chmod 755 script.sh</code></td>\n</tr>\n</tbody>\n</table>\n<p><em>(No ambiente Microsoft Office / Windows — INFO 2025 Q6 &amp; Apostas Q30: no Word, listas com marcadores/numeração ficam na guia <strong>Página Inicial</strong>, e <strong>Mala Direta</strong> automatiza cartas personalizadas a partir de uma lista Excel; no Windows, <code>Ctrl+C</code>/<code>Ctrl+V</code>/<code>Ctrl+Z</code> e Gerenciador de Tarefas <code>Ctrl+Shift+Esc</code> encerram travamentos).</em></p>\n<hr />\n<h3 id=\"️️-dissecando-questões-no-estilo-exato-da-prova\">🕵️‍♂️ Dissecando Questões no Estilo Exato da Prova</h3>\n<h4 id=\"questão-resolvida-1-baseada-em-ds-2019-q20--info-2025-q4--conversões\">Questão Resolvida 1 (Baseada em DS 2019 Q20 &amp; INFO 2025 Q4 — Conversões)</h4>\n<p><em>Converta os valores decimais <code>255</code>, <code>100</code> e <code>250</code> para binário (8 bits) e hexadecimal.</em></p>\n<ul>\n<li><code>255</code> = <code>128+64+32+16+8+4+2+1</code> = <strong><code>11111111₂</code></strong> = <strong><code>FF₁₆</code></strong>.</li>\n<li><code>100</code> = <code>64+32+4</code> = <strong><code>01100100₂</code></strong>; <code>100 ÷ 16</code> = <code>6</code> resto <code>4</code> = <strong><code>64₁₆</code></strong>.</li>\n<li><code>250</code> = <code>128+64+32+16+8+2</code> = <strong><code>11111010₂</code></strong>; <code>250 ÷ 16</code> = <code>15(F)</code> resto <code>10(A)</code> = <strong><code>FA₁₆</code></strong>.</li>\n</ul>\n<h4 id=\"questão-resolvida-2-baseada-em-info-2025-q16--q18--contêineres-e-linux\">Questão Resolvida 2 (Baseada em INFO 2025 Q16 &amp; Q18 — Contêineres e Linux)</h4>\n<p><em>I. Contêineres Docker são idênticos a Máquinas Virtuais porque cada contêiner emula um hardware separado e instala um kernel Linux completo dentro dele. II. No Linux, <code>/etc</code> armazena configurações do sistema e <code>/var</code> guarda logs variáveis.</em></p>\n<ul>\n<li><strong>Item I é FALSO:</strong> Contêineres <strong>compartilham o mesmo kernel</strong> do SO hospedeiro (não instalam kernel/SO inteiro por dentro como VMs).</li>\n<li><strong>Item II é VERDADEIRO.</strong></li>\n</ul>\n"}, {"id": "mod4b", "title": "Módulo 4B • Redes TCP/IP, E-mail, Cloud, IoT, Inglês & Ética (Dia 11)", "html": "<h2 id=\"dia-11--redes-de-computadores-tcpip-e-mail-topologias-cloud-iot-inglês-técnico-e-ética-cps\">Dia 11 — Redes de Computadores (TCP/IP, E-mail, Topologias), Cloud, IoT, Inglês Técnico e Ética CPS</h2>\n<h3 id=\"-contexto-no-mundo-real-a-viagem-de-um-clique-até-outro-continente\">🎯 Contexto no Mundo Real: A Viagem de um Clique até Outro Continente</h3>\n<p>Quando você envia uma mensagem pelo WhatsApp, lê um e-mail no celular ou acessa um site seguro com cadeado (<code>https://</code>), seus dados não viajam \"por mágica\" em um único bloco gigante. Eles são picotados em <strong>pacotes</strong>, endereçados por <strong>IP</strong>, protegidos por criptografia <strong>SSL/TLS</strong>, atravessam <strong>cabos submarinos ou Wi-Fi</strong> ligados por switches e roteadores, chegam a servidores na <strong>Nuvem (Cloud)</strong> e retornam reconstruídos na sua tela! Além disso, esse módulo fecha <strong>Inglês Técnico e Ética/LGPD</strong>, garantindo <strong>10 a 12 questões certeiras</strong> numa prova de 30!</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Tudo sobre <strong>Ping, Redes, Discord e Cloud</strong> fica muito mais claro pensando num PC Gamer conectado à internet:</p>\n<ul>\n<li><strong>TCP vs. UDP na Call do Discord e nos Jogos Online:</strong>\n<ul>\n<li>Quando você baixa um jogo na Steam, cada byte precisa chegar inteirinho sem arquivo corrompido (mesmo que espere reenvio) → usa <strong>TCP (confiável)</strong>.</li>\n<li>Quando você está em <strong>call de voz no Discord</strong> ou dando flick no CS2/Valorant, <strong>velocidade em tempo real importa mais que recuperar pacote velho de 2 segundos atrás!</strong> Por isso voz e movimento usam <strong>UDP (rápido, sem confirmação)</strong>.</li>\n</ul></li>\n<li><strong>DNS e DHCP do seu Roteador:</strong> O <strong>DHCP</strong> entrega seu IP local (<code>192.168.1.X</code>) automaticamente quando o PC ou celular conecta no Wi-Fi. Já o <strong>DNS</strong> traduz <code>discord.com</code> no IP real do servidor (<em>colocar DNS <code>1.1.1.1</code> ou <code>8.8.8.8</code> às vezes melhora rotas exatamente por isso!</em>).</li>\n<li><strong>Topologia Estrela vs. Barramento em LAN House:</strong> Numa <strong>LAN House moderna (Estrela)</strong>, todos os PCs ligam por cabo próprio num <strong>Switch</strong> no rack: se o cabo do PC-3 arrebentar, só o PC-3 cai; já numa rede antiga em <strong>Barramento (<em>Bus</em>)</strong>, se o cabo central partir, a LAN inteira cai junto!</li>\n<li><strong>Cloud nos Games (IaaS / PaaS / SaaS):</strong>\n<ul>\n<li><strong>SaaS:</strong> Discord Web, <strong>GeForce NOW / Xbox Cloud Gaming</strong> — você só entra e usa/joga pronto no navegador!</li>\n<li><strong>PaaS:</strong> Subir o código JS/Python do <strong>seu Bot de Discord</strong> na nuvem sem configurar sistema operacional.</li>\n<li><strong>IaaS:</strong> Alugar uma máquina virtual Linux crua (VPS) para configurar servidor de jogos/site do zero.</li>\n</ul></li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--arquitetura-tcpip-e-principais-protocolos-da-internet-ds-2025-q25--info-2025-q25\">📚 Parte 1 — Arquitetura TCP/IP e Principais Protocolos da Internet <em>(DS 2025 Q25 &amp; INFO 2025 Q25)</em></h3>\n<p>Um <strong>protocolo</strong> é um conjunto formal de regras e formatos para que máquinas diferentes (um iPhone e um servidor Linux) consigam conversar no mesmo idioma. A Internet opera sobre a pilha <strong>TCP/IP</strong>, organizada classicamente em <strong>4 camadas</strong> (da mais próxima do usuário até o cabo/onda):</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Camada TCP/IP</th>\n<th style=\"text-align: left;\">Função Principal</th>\n<th style=\"text-align: left;\">Protocolos &amp; Equipamentos Típicos</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>4. Aplicação</strong></td>\n<td style=\"text-align: left;\">Onde os aplicativos conversam na rede (web, e-mail, arquivos, nomes).</td>\n<td style=\"text-align: left;\"><strong>HTTP, HTTPS, FTP, SFTP, SMTP, POP3, IMAP, DNS, DHCP, SSH, RDP</strong></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>3. Transporte</strong></td>\n<td style=\"text-align: left;\">Garante a comunicação ponta a ponta entre processos (portas), controle de fluxo e integridade.</td>\n<td style=\"text-align: left;\"><strong>TCP</strong> (confiável, exige confirmação/ACK — Web, E-mail, Bancos) vs. <strong>UDP</strong> (rápido sem confirmação — Vídeos ao vivo, Jogos online, VoIP, DNS)</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>2. Internet (Rede)</strong></td>\n<td style=\"text-align: left;\">Endereçamento lógico global (<strong>IP</strong>) e escolha da melhor rota entre redes diferentes (<strong>Roteamento</strong>).</td>\n<td style=\"text-align: left;\"><strong>IP (IPv4 32 bits / IPv6 128 bits)</strong>, ICMP (<code>ping</code>), <strong>Roteadores</strong></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>1. Acesso à Rede (Enlace + Física)</strong></td>\n<td style=\"text-align: left;\">Transforma pacotes em quadros locais (endereço físico <strong>MAC</strong>) e transmite em sinais elétricos/luz/rádio.</td>\n<td style=\"text-align: left;\"><strong>Ethernet</strong> (cabos UTP/fibra), <strong>Wi-Fi</strong>, Placa de Rede, <strong>Switch</strong> (Camada 2)</td>\n</tr>\n</tbody>\n</table>\n<p><em>(Atenção: Alguns materiais acadêmicos detalham o <strong>Modelo OSI de 7 camadas</strong> — Física, Enlace, Rede, Transporte, Sessão, Apresentação, Aplicação — mas na prova prática da FAT o padrão da Internet cobrado é o <strong>TCP/IP em 4 camadas</strong>!)</em></p>\n<h4 id=\"protocolos-que-mais-caem-na-fat\">Protocolos que Mais Caem na FAT:</h4>\n<ul>\n<li><strong>HTTP vs. HTTPS <em>(INFO 2025 Q27)</em>:</strong> HTTP (<em>HyperText Transfer Protocol</em>) trafega páginas web em texto aberto; <strong>HTTPS</strong> encapsula o HTTP dentro de criptografia <strong>SSL/TLS</strong> (cadeado no navegador), garantindo <strong>confidencialidade e autenticidade</strong> contra interceptação!</li>\n<li><strong>DNS (<em>Domain Name System</em>):</strong> A \"agenda telefônica\" da internet — traduz nomes legíveis (<code>www.google.com</code>) em <strong>endereços IP</strong> numéricos (<code>142.250...</code>).</li>\n<li><strong>DHCP:</strong> Atribui <strong>endereços IP automaticamente</strong> aos dispositivos que entram na rede Wi-Fi/cabo (sem precisar digitar IP manual).</li>\n<li><strong>FTP / SFTP:</strong> Protocolos específicos para <strong>transferência de arquivos</strong> cliente ↔︎ servidor (<code>SFTP</code> com segurança SSH).</li>\n<li><strong>SSH vs. RDP <em>(INFO 2025 Q17)</em>:</strong> Acesso remoto! <strong>SSH</strong> abre terminal de comandos criptografado (padrão Linux/servidores); <strong>RDP (<em>Remote Desktop Protocol</em>)</strong> da Microsoft acessa a <strong>área de trabalho gráfica</strong> remota do Windows.</li>\n</ul>\n<hr />\n<h3 id=\"-parte-2--protocolos-de-e-mail-a-trinca-de-ouro-smtp-pop3-imap--webmail\">📚 Parte 2 — Protocolos de E-mail: A Trinca de Ouro (SMTP, POP3, IMAP) + Webmail</h3>\n<p>Esse assunto caiu literalmente igual na <strong>DS 2025 Q28</strong> e na <strong>INFO 2025 Q7 e Q26</strong>! Nunca confunda os 3 papéis:</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Ferramenta / Protocolo</th>\n<th style=\"text-align: center;\">Direção</th>\n<th style=\"text-align: left;\">O que acontece na prática passo a passo</th>\n<th style=\"text-align: left;\">Cenário real</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>SMTP</strong> <em>(Simple Mail Transfer Protocol)</em></td>\n<td style=\"text-align: center;\"><strong>ENVIO / SAÍDA</strong></td>\n<td style=\"text-align: left;\">Envia a mensagem do seu aplicativo até seu servidor e transporta entre servidores de e-mail (<code>@etec</code> → <code>@gmail</code>).</td>\n<td style=\"text-align: left;\">Você clica em <strong>Enviar</strong> e a carta sai da sua caixa de saída. <strong>SMTP NÃO serve para ler sua caixa de entrada!</strong></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>POP3</strong> <em>(Post Office Protocol v3)</em></td>\n<td style=\"text-align: center;\"><strong>RECEBIMENTO (Baixa)</strong></td>\n<td style=\"text-align: left;\">Conecta ao servidor, <strong>faz o download das mensagens para o dispositivo local e, por padrão, APAGA do servidor</strong>.</td>\n<td style=\"text-align: left;\">Se você baixar no notebook de casa via POP3, ao abrir o celular na rua os e-mails antigos <strong>não estarão mais lá</strong>!</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>IMAP</strong> <em>(Internet Message Access Protocol)</em></td>\n<td style=\"text-align: center;\"><strong>RECEBIMENTO (Sincroniza)</strong></td>\n<td style=\"text-align: left;\"><strong>Mantém todos os e-mails e pastas no servidor remoto</strong>, sincronizando o status (<em>lido/não lido/apagado</em>) em tempo real em todos os aparelhos.</td>\n<td style=\"text-align: left;\">Você lê um e-mail no celular e, quando abre o PC ou tablet, ele já aparece sincronizado como lido!</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Webmail</strong></td>\n<td style=\"text-align: center;\">Acesso via <strong>Browser</strong></td>\n<td style=\"text-align: left;\">Interface acessada diretamente pelo navegador via <strong>HTTP/HTTPS</strong> (ex.: Gmail Web, Outlook.com), sem instalar cliente desktop (como Mozilla Thunderbird).</td>\n<td style=\"text-align: left;\">Abrir seu e-mail no Chrome em qualquer computador.</td>\n</tr>\n</tbody>\n</table>\n<div class=\"callout callout-caution\">\n\n<p><strong>Pegadinha clássica da DS 2025 Q28:</strong> A banca cria uma tabela de itens I, II e III dizendo que <em>\"SMTP sincroniza mensagens no servidor\"</em> e <em>\"IMAP apenas envia e-mails\"</em>. Lembre sempre do macete: <strong>S</strong>MTP = <strong>S</strong>ubir / <strong>S</strong>air (Envio); <strong>POP3</strong> = <strong>P</strong>uxa para o PC e apaga; <strong>IMAP</strong> = espelho sincronizado no servidor!</p>\n</div>\n\n<hr />\n<h3 id=\"-parte-3--topologias-de-rede-cloud-computing-iot-e-navegadores\">📚 Parte 3 — Topologias de Rede, Cloud Computing, IoT e Navegadores</h3>\n<h4 id=\"1-topologias-de-rede-ds-2025-q26--ds-2019-q23\">1. Topologias de Rede <em>(DS 2025 Q26 &amp; DS 2019 Q23)</em></h4>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Topologia</th>\n<th style=\"text-align: left;\">Desenho Físico / Como Liga</th>\n<th style=\"text-align: left;\">Ponto Forte</th>\n<th style=\"text-align: left;\">Ponto Fraco / Pegadinha de Prova</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Barramento (<em>Bus</em>)</strong> <em>(DS 2025 Q26)</em></td>\n<td style=\"text-align: left;\">Todos os computadores compartilham <strong>UM ÚNICO cabo central (<em>backbone</em>)</strong> com terminadores nas duas pontas.</td>\n<td style=\"text-align: left;\">Barata e usa pouco cabo.</td>\n<td style=\"text-align: left;\"><strong>Ponto único de falha no cabo:</strong> se o cabo principal romper em qualquer lugar, <strong>A REDE INTEIRA CAI!</strong> Além disso, só um transmite por vez (colisões).</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Estrela (<em>Star</em>)</strong> <em>(DS 2019 Q23)</em></td>\n<td style=\"text-align: left;\">Cada PC tem um cabo exclusivo indo até um <strong>nó central concentrador (Switch ou Hub)</strong>.</td>\n<td style=\"text-align: left;\">Se <strong>o cabo de 1 PC romper, só ele para</strong> — o resto da rede continua intacto! Fácil de dar manutenção.</td>\n<td style=\"text-align: left;\">Depende do nó central: se o <strong>Switch</strong> queimar ou desligar, a rede para. (Padrão moderno das redes cabeadas).</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Anel (<em>Ring</em>)</strong></td>\n<td style=\"text-align: left;\">Cada computador liga-se ao vizinho formando um circuito fechado; um sinal (<em>Token</em>) dá a volta dando vez de falar.</td>\n<td style=\"text-align: left;\">Fluxo ordenado sem colisões aleatórias.</td>\n<td style=\"text-align: left;\">Em anel simples sem redundância, se um nó falha, interrompe o ciclo.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Malha (<em>Mesh</em>)</strong></td>\n<td style=\"text-align: left;\">Cada nó se conecta diretamente a <strong>vários ou todos os outros nós</strong> (múltiplos caminhos alternativos).</td>\n<td style=\"text-align: left;\"><strong>Tolerância máxima a falhas!</strong> Se um cabo cair, o tráfego desvia por outra rota.</td>\n<td style=\"text-align: left;\">Caríssima e complexa em cabeamento se tiver muitas máquinas.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Híbrida</strong></td>\n<td style=\"text-align: left;\">Combina duas ou mais topologias (ex.: várias Estrelas ligadas em Barramento ou Malha).</td>\n<td style=\"text-align: left;\">Flexibilidade para grandes prédios e campi.</td>\n<td style=\"text-align: left;\">Maior complexidade de projeto e gerenciamento.</td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"2-computação-em-nuvem-cloud-computing--analogia-da-pizzaria-apostas-q26\">2. Computação em Nuvem (<em>Cloud Computing</em>) — Analogia da Pizzaria <em>(Apostas Q26)</em></h4>\n<p>Imagine a diferença entre fazer tudo em casa e pedir delivery pronto para entender os <strong>3 Modelos de Serviço Cloud</strong>:</p>\n<ul>\n<li><strong>IaaS (<em>Infraestrutura como Serviço</em> — ex.: AWS EC2, Azure VMs, Google Compute Engine):</strong> Você aluga hardware virtual na nuvem (CPU, RAM, disco, rede). É como <strong>alugar a cozinha e o forno</strong> — você mesmo instala o Sistema Operacional, banco, patches e sobe seu app!</li>\n<li><strong>PaaS (<em>Plataforma como Serviço</em> — ex.: Heroku, Vercel, Azure App Service):</strong> O provedor já gerencia hardware, SO, firewall e runtime (Node/Python/Java). É como <strong>comprar a massa e os ingredientes prontos</strong> — o desenvolvedor só faz o deploy do <strong>próprio código</strong>!</li>\n<li><strong>SaaS (<em>Software como Serviço</em> — ex.: Google Docs, Gmail, Microsoft 365, Canva, Figma):</strong> Software 100% pronto usado no navegador/app por assinatura ou grátis. É como <strong>sentar na pizzaria e comer a pizza pronta</strong> — você não instala nem programa nada!</li>\n</ul>\n<h4 id=\"3-internet-das-coisas-iot-navegadores-e-suítes-ds-2025-q24-q29-e-q30\">3. Internet das Coisas (IoT), Navegadores e Suítes <em>(DS 2025 Q24, Q29 e Q30)</em></h4>\n<ul>\n<li><strong>IoT (<em>Internet of Things</em>):</strong> Conecta objetos físicos do cotidiano à rede usando <strong>sensores</strong> (leem temperatura, umidade, batimentos), <strong>atuadores</strong> e conectividade para trocar dados e agir automaticamente (ex.: semáforos inteligentes, sensores agrícolas, fechaduras e relógios smart).</li>\n<li><strong>Navegadores (<em>Browsers</em>)</strong> <em>(DS 2025 Q29)</em>: Softwares clientes que interpretam HTML/CSS/JS — <strong>Google Chrome, Mozilla Firefox, Microsoft Edge, Apple Safari, Opera, Brave</strong>. <strong>Intrusos clássicos da prova:</strong> <em>Google Search</em> (é <strong>buscador</strong>, não navegador!), <em>Outlook</em>, <em>Excel</em> e <em>VS Code</em>.</li>\n<li><strong>Suítes de Produtividade</strong> <em>(DS 2025 Q30)</em>: Conjuntos integrados de escritório (Editor de Texto + Planilha + Apresentações) como <strong>Microsoft 365 / Office</strong> (Word, Excel, PowerPoint), <strong>LibreOffice</strong> (Writer, Calc, Impress) e <strong>Google Workspace</strong> (Docs, Sheets, Slides).</li>\n</ul>\n<hr />\n<h3 id=\"-parte-4--inglês-técnico--ética-socioambiental-cps\">📚 Parte 4 — Inglês Técnico &amp; Ética Socioambiental CPS</h3>\n<p>Quase toda prova DS/Info começa com <strong>Q1 a Q3 de Inglês</strong> e <strong>Q4 a Q6 de Ética/Cidadania</strong>!</p>\n<h4 id=\"1-técnicas-rápidas-e-vocabulário-obrigatório-de-inglês-técnico-ds-2025-q1q3--m-tec-q7q9\">1. Técnicas Rápidas e Vocabulário Obrigatório de Inglês Técnico <em>(DS 2025 Q1–Q3 &amp; M-Tec Q7–Q9)</em></h4>\n<ul>\n<li><strong>Técnicas de leitura:</strong>\n<ul>\n<li><em>Skimming:</em> leitura panorâmica rápida no título e primeira frase de cada parágrafo para pegar a <strong>ideia central</strong>.</li>\n<li><em>Scanning:</em> busca dirigida de datas, números, siglas ou palavras específicas pedidas na questão.</li>\n</ul></li>\n<li><strong>Gramática que já caiu:</strong>\n<ul>\n<li><strong>Comparativo / Superlativo irregular <em>(M-Tec 2022 Q7)</em>:</strong> <code>bad → worse (pior que) → the worst (o pior)</code>; <code>good → better → the best</code>.</li>\n<li><strong>Formação de palavras com prefixos/sufixos <em>(M-Tec 2022 Q9)</em>:</strong> <code>-able / -ible</code> formam <strong>adjetivos</strong> indicando possibilidade (<em>debatable</em>, <em>scalable</em>, <em>readable</em>); <code>-ive</code> forma <strong>adjetivos</strong> (<em>positive</em>, <em>interactive</em>); <code>-tion / -ment / -ness</code> formam <strong>substantivos</strong>; <code>-ly</code> forma <strong>advérbios</strong>.</li>\n</ul></li>\n<li><strong>Falsos Cognatos (parecem português, mas significam outra coisa!):</strong>\n<ul>\n<li><code>data</code> = <strong>dados</strong> (NÃO é \"datas\" — data de calendário é <em>date</em>!).</li>\n<li><code>actually</code> = <strong>na verdade</strong> (NÃO é \"atualmente\" = <em>currently</em>).</li>\n<li><code>pretend</code> = <strong>fingir</strong> (NÃO é \"pretender\" = <em>intend</em>).</li>\n<li><code>library</code> = <strong>biblioteca / biblioteca de código</strong> (NÃO é \"livraria\" = <em>bookstore</em>).</li>\n<li><code>support</code> = <strong>apoiar / dar suporte</strong> (NÃO é \"aguentar/suportar dor\" = <em>bear/stand</em>).</li>\n</ul></li>\n<li><strong>Termos recorrentes de Soft Skills &amp; TI:</strong> <code>outcomes</code> (resultados/desfechos) • <code>troubleshooting</code> (diagnóstico e solução de falhas) • <code>critical thinking</code> (pensamento crítico) • <code>inference</code> (inferência/dedução implícita nas entrelinhas) • <code>daunting</code> (intimidante/assustador) • <code>bias</code> (viés/parcialidade algorítmica) • <code>awareness</code> (consciência).</li>\n</ul>\n<h4 id=\"2-ética-em-ti-direitos-trabalhistas-lixo-eletrônico-e-lgpd-ds-2025-q4q6\">2. Ética em TI, Direitos Trabalhistas, Lixo Eletrônico e LGPD <em>(DS 2025 Q4–Q6)</em></h4>\n<ul>\n<li><strong>Ética para o Bem Comum:</strong> Ações verdadeiramente éticas visam o impacto coletivo, transparência e respeito aos direitos humanos — rejeitando alternativas baseadas em <em>vaidade pessoal, autopromoção em redes sociais ou lucro acima da segurança</em>.</li>\n<li><strong>Sustentabilidade &amp; Lixo Eletrônico (<em>e-waste</em>):</strong> Baterias, placas e monitores contêm metais pesados (chumbo, mercúrio, cádmio). Nunca devem ir para o lixo comum! A postura ética correta exige <strong>logística reversa / descarte em pontos de coleta recicladora certificados</strong> e desenvolvimento de sistemas eficientes (TI Verde) sem induzir <strong>obsolescência programada</strong>.</li>\n<li><strong>LGPD (Lei Geral de Proteção de Dados):</strong> Coleta mínima necessária de dados pessoais, finalidade explícita, consentimento do titular e proteção contra vazamentos.</li>\n</ul>\n<hr />\n<h3 id=\"️️-dissecando-questões-no-estilo-exato-da-prova\">🕵️‍♂️ Dissecando Questões no Estilo Exato da Prova</h3>\n<h4 id=\"questão-resolvida-1-baseada-em-ds-2025-q26--q28--topologias-e-e-mail\">Questão Resolvida 1 (Baseada em DS 2025 Q26 &amp; Q28 — Topologias e E-mail)</h4>\n<p><em>Analise: I. Na topologia em Barramento, o rompimento do cabo backbone interrompe a comunicação de toda a rede. II. O protocolo POP3 envia mensagens do aplicativo cliente para o servidor de saída. III. O protocolo IMAP mantém os e-mails sincronizados no servidor para acesso em vários aparelhos.</em></p>\n<ul>\n<li><strong>Item I:</strong> VERDADEIRO.</li>\n<li><strong>Item II:</strong> <strong>FALSO</strong> (quem envia é o <strong>SMTP</strong>; POP3 baixa e apaga).</li>\n<li><strong>Item III:</strong> VERDADEIRO.</li>\n</ul>\n<h4 id=\"questão-resolvida-2-baseada-em-ds-2025-q1--m-tec-q7--inglês-técnico\">Questão Resolvida 2 (Baseada em DS 2025 Q1 &amp; M-Tec Q7 — Inglês Técnico)</h4>\n<p><em>No trecho \"Effective troubleshooting produces reliable outcomes, even when legacy bugs feel daunting and represent the worst scenario\", as palavras destacadas significam respectivamente:</em></p>\n<ul>\n<li><code>troubleshooting</code> = <strong>solução/diagnóstico de problemas</strong>; <code>outcomes</code> = <strong>resultados</strong>; <code>daunting</code> = <strong>intimidante</strong>; <code>worst</code> = <strong>pior</strong> (superlativo de <em>bad</em>).</li>\n</ul>\n"}, {"id": "mtec_base", "title": "🎓 Base Comum M-Tec Completa (Português, História, Mat, Quím, Fís/Bio • Dias 12–13)", "html": "<h2 id=\"dia-12--base-comum-m-tec-i-português-interpretação-literatura-e-história-1º-ano-em\">Dia 12 — Base Comum M-Tec I: Português, Interpretação, Literatura e História (1º Ano EM)</h2>\n<h3 id=\"-contexto-no-mundo-real-por-que-português-e-história-decidem-vagas-no-m-tec\">🎯 Contexto no Mundo Real: Por que Português e História Decidem Vagas no M-Tec?</h3>\n<p>Na prova de <strong>Vagas Remanescentes do 2º Ano M-Tec (Ensino Médio Integrado ao Técnico)</strong>, você não disputa apenas com quem decorou tags HTML: cerca de metade da prova oficial (<em>como vimos na prova real M-Tec 2022, questões Q1–Q6 e Q24–Q27</em>) cobra matérias da <strong>Base Nacional Comum da 1ª Série do Ensino Médio</strong>!</p>\n<p>E tem mais um detalhe estratégico: saber <strong>interpretar textos com precisão</strong>, distinguir um <strong>Paradoxo</strong> de uma <strong>Antítese</strong>, separar <strong>Cultismo</strong> de <strong>Conceptismo</strong> e dominar a passagem do <strong>Paleolítico ao Neolítico</strong> também afia diretamente seu olhar para as pegadinhas verbais das questões de programação e engenharia!</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Português, Literatura e História ficam mil vezes mais fáceis quando comparamos com jogos e internet:</p>\n<ul>\n<li><strong>Tipos Textuais nos Games:</strong>\n<ul>\n<li><strong>Narração:</strong> A <em>lore</em> / cutscene contando a história do personagem (<em>\"Kratos atravessou os reinos buscando...\"</em>).</li>\n<li><strong>Descrição:</strong> O texto da ficha de um item (<em>\"Armadura pesada de aço escovado, escura e rachada nas bordas\"</em>).</li>\n<li><strong>Injunção (Instrucional):</strong> O <strong>tutorial</strong> no começo do jogo (<em>\"Pressione <code>Espaço</code> para pular; aperte <code>R</code> para recarregar\"</em> — verbos no <strong>imperativo</strong>!).</li>\n<li><strong>Exposição vs. Argumentação:</strong> A <strong>wiki</strong> explica neutro como o item funciona (Expositivo); um vídeo/artigo dizendo <em>\"Por que tal arma deveria ser nerfada\"</em> defende opinião com provas (Argumentativo).</li>\n</ul></li>\n<li><strong>Variação Linguística:</strong> Falar <em>\"Mano, dropa a spike no B e dá call no Disc\"</em> com seu duo é perfeito para a partida (<strong>Diafásica/Situacional</strong> e <strong>Diastrática/Jargão</strong>); já numa redação ou entrevista de estágio você muda para a norma padrão — não existe \"falar errado\", existe <strong>adequação ao contexto</strong>!</li>\n<li><strong>História Estilo <em>Age of Empires / Civilization</em>:</strong>\n<ul>\n<li><strong>Paleolítico:</strong> Fase inicial <strong>nômade</strong> — você anda pelo mapa caçando cervo e colhendo fruta até acabar o recurso da área.</li>\n<li><strong>Revolução Neolítica:</strong> Desbloqueou a tecnologia de <strong>Fazenda (Agricultura) e Pecuária</strong> → você para de andar, funda uma aldeia fixa perto do rio (<strong>Sedentarismo</strong>), estoca comida e cresce a cidade!</li>\n<li><strong>Feudalismo:</strong> Mapa cheio de <strong>castelos isolados (feudos)</strong>, quase sem comércio/ouro circulando, <strong>servos</strong> plantando na terra do senhor em troca de proteção e contratos de lealdade (<strong>Suserania e Vassalagem</strong>).</li>\n</ul></li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--tipologia-textual-vs-gêneros-textuais-m-tec-2022-q3\">📚 Parte 1 — Tipologia Textual vs. Gêneros Textuais <em>(M-Tec 2022 Q3)</em></h3>\n<p><strong>Atenção à distinção conceitual:</strong></p>\n<ul>\n<li><strong>Gênero Textual</strong> é o formato concreto que circula na sociedade (são dezenas: <em>notícia, crônica, receita de bolo, bula de remédio, contrato, e-mail, artigo de opinião, tutorial</em>).</li>\n<li><strong>Tipo Textual (Tipologia)</strong> refere-se à <strong>estrutura e objetivo predominante</strong> dentro do texto — são apenas <strong>5 tipos oficiais</strong>:</li>\n</ul>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Tipo Textual</th>\n<th style=\"text-align: left;\">Objetivo Central</th>\n<th style=\"text-align: left;\">Pistas Gramaticais na Prova</th>\n<th style=\"text-align: left;\">Exemplo Real de Trecho</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>1. Narração</strong></td>\n<td style=\"text-align: left;\">Contar fatos/ações vividos por personagens em <strong>tempo e espaço</strong></td>\n<td style=\"text-align: left;\">Verbos de ação no pretérito (<em>chegou, programou</em>), marcadores temporais (<em>ontem, depois</em>).</td>\n<td style=\"text-align: left;\"><em>\"Ontem à noite, Lucas abriu o notebook, corrigiu o bug do login e enviou o código antes do prazo.\"</em></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>2. Descrição</strong></td>\n<td style=\"text-align: left;\">Retratar características físicas ou psicológicas (<strong>\"fotografia em palavras\"</strong>, sem avanço temporal)</td>\n<td style=\"text-align: left;\">Adjetivos, verbos de estado/ligação (<em>é, estava, parecia</em>), detalhes sensoriais.</td>\n<td style=\"text-align: left;\"><em>\"O laboratório tinha vinte monitores largos, cadeiras ergonômicas pretas e iluminação fria e silenciosa.\"</em></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>3. Exposição (Dissertativo-Expositivo)</strong></td>\n<td style=\"text-align: left;\"><strong>Explicar, informar e esclarecer</strong> um assunto de forma clara e <strong>impessoal</strong>, sem tentar convencer de uma opinião polêmica</td>\n<td style=\"text-align: left;\">Linguagem objetiva, 3ª pessoa, definições e exemplos didáticos (apostilas, enciclopédias, notícias neutras).</td>\n<td style=\"text-align: left;\"><em>\"O protocolo HTTPS adiciona a camada criptográfica SSL/TLS sobre o HTTP para proteger os dados em trânsito.\"</em></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>4. Dissertação Argumentativa</strong></td>\n<td style=\"text-align: left;\"><strong>Defender uma tese / ponto de vista</strong> usando provas, dados e argumentos para <strong>persuadir</strong> o leitor</td>\n<td style=\"text-align: left;\">Tese clara, conectivos lógicos (<em>portanto, contudo, logo</em>), juízo de valor fundamentado (editoriais, redação ENEM).</td>\n<td style=\"text-align: left;\"><em>\"O ensino técnico integrado é indispensável pois une formação cidadã e prática profissional real.\"</em></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>5. Injunção / Instrucional</strong></td>\n<td style=\"text-align: left;\"><strong>Instruir, orientar, dar ordens ou conselhos</strong> passo a passo sobre como fazer algo</td>\n<td style=\"text-align: left;\">Verbos no <strong>imperativo</strong> (<em>clique, abra, adicione</em>) ou infinitivo instrucional (<em>manter em local seco</em>).</td>\n<td style=\"text-align: left;\"><em>\"1. Extraia o arquivo ZIP. 2. Clique duas vezes em COMECE_AQUI.html. 3. Responda ao simulado.\"</em></td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h3 id=\"-parte-2--figuras-de-linguagem-semântica-e-variações-linguísticas\">📚 Parte 2 — Figuras de Linguagem, Semântica e Variações Linguísticas</h3>\n<h4 id=\"1-figuras-de-linguagem-campeãs-de-prova-m-tec-2022-q4\">1. Figuras de Linguagem Campeãs de Prova <em>(M-Tec 2022 Q4)</em></h4>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Figura</th>\n<th style=\"text-align: left;\">Como funciona na prática</th>\n<th style=\"text-align: left;\">Exemplo Real Comentado</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Antítese</strong></td>\n<td style=\"text-align: left;\">Apenas <strong>aproxima palavras ou ideias de sentidos opostos</strong> na frase, <strong>SEM contradição lógica impossível</strong>.</td>\n<td style=\"text-align: left;\"><em>\"Entre o <strong>claro</strong> e o <strong>escuro</strong>, entre a <strong>alegria</strong> e a <strong>tristeza</strong>, o dia seguiu.\"</em> (Dia e noite existem naturalmente, apenas estão contrastando!)</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Paradoxo (Oxímoro)</strong></td>\n<td style=\"text-align: left;\">Une ideias contraditórias que <strong>se anulam logicamente numa mesma afirmação</strong> para causar reflexão profunda! <em>(M-Tec Q4)</em></td>\n<td style=\"text-align: left;\"><em>\"É ferida que <strong>dói e não se sente</strong>\"</em> (Camões) / <em>\"Quanto mais estudo, menos entendo\"</em> / <em>\"Silêncio ensurdecedor\"</em>.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Metáfora vs. Comparação</strong></td>\n<td style=\"text-align: left;\"><strong>Comparação (Símile)</strong> usa conectivo explícito (<em>\"como, tal qual\"</em>). <strong>Metáfora</strong> transfere o sentido <strong>diretamente, sem conectivo</strong>.</td>\n<td style=\"text-align: left;\">Comparação: <em>\"O banco de dados é <strong>como</strong> um cofre.\"</em> <br>Metáfora: <em>\"O banco de dados <strong>é</strong> um cofre.\"</em></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Metonímia</strong></td>\n<td style=\"text-align: left;\">Substitui uma palavra por outra com relação lógica real (autor pela obra, continente pelo conteúdo, parte pelo todo).</td>\n<td style=\"text-align: left;\"><em>\"Passei a tarde lendo <strong>Machado de Assis</strong>\"</em> (os livros dele) / <em>\"Comi <strong>dois pratos</strong> hoje.\"</em></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Ironia</strong></td>\n<td style=\"text-align: left;\">Dizer exatamente o <strong>oposto</strong> do que se pensa, com intenção crítica ou humorística.</td>\n<td style=\"text-align: left;\"><em>\"Que código maravilhoso e limpo — levou só 4 horas para travar na tela de login!\"</em></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Hipérbole</strong></td>\n<td style=\"text-align: left;\"><strong>Exagero</strong> intencional para dar ênfase expressiva.</td>\n<td style=\"text-align: left;\"><em>\"Já compilei esse projeto <strong>um milhão de vezes</strong> hoje!\"</em></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Hipérbato</strong></td>\n<td style=\"text-align: left;\"><strong>Inversão brusca da ordem natural</strong> da frase (sujeito + verbo + complemento), muito comum no Barroco e no Hino Nacional.</td>\n<td style=\"text-align: left;\"><em>\"Ouviram do Ipiranga as margens plácidas de um povo heroico o brado retumbante...\"</em></td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"2-semântica-denotação-conotação-polissemia-e-hipônimohiperônimo-m-tec-2022-q5\">2. Semântica: Denotação, Conotação, Polissemia e Hipônimo/Hiperônimo <em>(M-Tec 2022 Q5)</em></h4>\n<ul>\n<li><strong>Denotação (D = Dicionário):</strong> Sentido <strong>literal, exato</strong> da palavra (<em>\"O servidor usa memória física de <strong>pedra</strong> de silício\"</em> / <em>\"Quebrou a <strong>pedra</strong>\"</em>).</li>\n<li><strong>Conotação:</strong> Sentido <strong>figurado, poético ou contextual</strong> (<em>\"Ele tem um coração de <strong>pedra</strong>\"</em> = insensível).</li>\n<li><strong>Polissemia:</strong> Quando uma única palavra possui <strong>vários significados diferentes</strong> dependendo da frase (<em>\"a <strong>cabeça</strong> do aluno\"</em>, <em>\"a <strong>cabeça</strong> do prego\"</em>, <em>\"a <strong>cabeça</strong> da fila\"</em>).</li>\n<li><strong>Hiperônimo vs. Hipônimo <em>(caiu em M-Tec Q5!)</em>:</strong>\n<ul>\n<li><strong>Hiperônimo</strong> = termo <strong>mais amplo / categoria geral</strong> (<em>\"pensador\"</em>, <em>\"animal\"</em>, <em>\"linguagem de programação\"</em>).</li>\n<li><strong>Hipônimo</strong> = termo <strong>mais específico</strong> contido dentro da categoria (<em>\"Aristóteles\"</em>, <em>\"cachorro\"</em>, <em>\"Python\"</em>).</li>\n<li>Exemplo real de coesão num texto: <em>\"A França convocou <strong>Aristóteles</strong> na homenagem. O <strong>pensador</strong> grego...\"</em> → substituir <em>Aristóteles</em> (hipônimo) por <em>pensador</em> (hiperônimo) evita repetição!</li>\n</ul></li>\n</ul>\n<h4 id=\"3-variações-linguísticas-m-tec-2022-q2\">3. Variações Linguísticas <em>(M-Tec 2022 Q2)</em></h4>\n<p>A Sociolinguística moderna ensina que a língua é viva e não existe <em>\"falar errado\"</em> de modo absoluto — o que existe é <strong>adequação ou inadequação ao contexto comunicativo</strong> (ninguém fala igual numa entrevista de emprego e num grupo de WhatsApp com amigos!).</p>\n<ul>\n<li><strong>Variação Diatópica (Geográfica/Regional):</strong> Muda conforme o lugar (<em>\"aipim\" / \"macaxeira\" / \"mandioca\"</em>; <em>\"trem\"</em> em MG; <em>\"guri\"</em> no RS).</li>\n<li><strong>Variação Diacrônica (Histórica):</strong> Muda com o passar do tempo (<em>\"Vossa Mercê\" → \"Vosmicê\" → \"Você\" → \"Vc\"</em>).</li>\n<li><strong>Variação Diastrática (Social / Profissional):</strong> Muda conforme grupo social ou profissão (jargão de TI: <em>\"fazer deploy de um container\"</em>; gírias juvenis).</li>\n<li><strong>Variação Diafásica (Situacional / Registro):</strong> Grau de formalidade entre falar com um juiz vs. conversar em casa.</li>\n</ul>\n<hr />\n<h3 id=\"-parte-3--escolas-literárias-do-1º-ano-do-ensino-médio-m-tec-q1--q6\">📚 Parte 3 — Escolas Literárias do 1º Ano do Ensino Médio <em>(M-Tec Q1 &amp; Q6)</em></h3>\n<h4 id=\"1-trovadorismo-idade-média--sécs-xii-a-xiv-m-tec-q6\">1. Trovadorismo (Idade Média — sécs. XII a XIV, <em>M-Tec Q6</em>)</h4>\n<p>Primeira manifestação literária em língua galego-portuguesa, nascida nos castelos feudais como <strong>cantigas</strong> acompanhadas de música (trovadores + jograis):</p>\n<ul>\n<li><strong>Cantigas Líricas (Amorosas):</strong>\n<ul>\n<li><strong>Cantiga de Amor:</strong> Eu lírico <strong>MASCULINO</strong> sofre por uma dama nobre distante e inatingível (<em>\"minha senhor\"</em>). Reflete a <strong>vassalagem feudal</strong> trazida para o amor (o homem serve humildemente à mulher superior).</li>\n<li><strong>Cantiga de Amigo:</strong> Eu lírico <strong>FEMININO</strong> (mesmo tendo sido escrita por homens!) expressa saudade do seu namorado (<em>\"amigo\"</em>) conversando com a mãe, amigas ou elementos da natureza (mar, ondas, pinheiros). Origem popular/rural.</li>\n</ul></li>\n<li><strong>Cantigas Satíricas (Críticas):</strong>\n<ul>\n<li><strong>Escárnio:</strong> Crítica <strong>indireta, irônica, ambígua</strong>, <strong>sem</strong> citar o nome da pessoa diretamente.</li>\n<li><strong>Maldizer:</strong> Crítica <strong>direta, agressiva, explícita</strong>, citando o nome do alvo e usando palavras de baixo calão.</li>\n</ul></li>\n</ul>\n<h4 id=\"2-humanismo-séc-xv-classicismo-séc-xvi-e-quinhentismo-no-brasil\">2. Humanismo (séc. XV), Classicismo (séc. XVI) e Quinhentismo no Brasil</h4>\n<ul>\n<li><strong>Humanismo:</strong> Transição da Idade Média para o Renascimento (<strong>Gil Vicente</strong>, teatro crítico em <em>O Auto da Barca do Inferno</em>).</li>\n<li><strong>Classicismo:</strong> Renascimento pleno, equilíbrio, razão, imitação dos clássicos greco-romanos (<strong>Luís de Camões</strong> — <em>Os Lusíadas</em> e sonetos equilibrados).</li>\n<li><strong>Quinhentismo no Brasil (1500 — <em>M-Tec Cards</em>):</strong> Duas frentes no primeiro século após 1500:\n<ol>\n<li><strong>Literatura Informativa / de Viagens:</strong> Descrevia e catalogava a nova terra, fauna, flora e indígenas para a Coroa Portuguesa (<strong>Carta de Pero Vaz de Caminha</strong>, 1500).</li>\n<li><strong>Literatura Jesuítica / Catequética:</strong> Textos, poesias e autos teatrais de caráter religioso e pedagógico para <strong>catequizar</strong> os indígenas e educar colonos (<strong>Padre José de Anchieta</strong>).</li>\n</ol></li>\n</ul>\n<h4 id=\"3-barroco-sécs-xviixviii--campeão-de-pegadinha-m-tec-q1\">3. Barroco (sécs. XVII–XVIII — <em>Campeão de Pegadinha: M-Tec Q1!</em>)</h4>\n<p>Nascido no clima tenso da <strong>Contrarreforma Católica</strong>, o Barroco expressa o <strong>conflito dramático humano (dualismo)</strong>: espírito × carne, céu × inferno, efemeridade da vida × busca pelo eterno. Usa muitas antíteses e paradoxos!</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Estilo Barroco</th>\n<th style=\"text-align: left;\">Foco Principal</th>\n<th style=\"text-align: left;\">Características &amp; Recursos</th>\n<th style=\"text-align: left;\">Grande Autor</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Cultismo (Gongorismo)</strong></td>\n<td style=\"text-align: left;\"><strong>Jogo de PALAVRAS</strong> e forma</td>\n<td style=\"text-align: left;\">Linguagem rebuscada, exuberante, vocabulário raro, metáforas complexas, hipérboles e imagens sensoriais (<em>cores, brilho, sons</em>).</td>\n<td style=\"text-align: left;\"><strong>Gregório de Matos</strong> (<em>\"Boca do Inferno\"</em>) na poesia ornamentada</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Conceptismo (Quevedismo)</strong></td>\n<td style=\"text-align: left;\"><strong>Jogo de IDEIAS</strong> e lógica</td>\n<td style=\"text-align: left;\">Raciocínio lógico rigoroso, argumentação persuasiva, <strong>silogismos</strong> e encadeamento intelectual para provar teses morais/religiosas.</td>\n<td style=\"text-align: left;\"><strong>Padre Antônio Vieira</strong> (nos <em>Sermões</em>, ex.: <em>Sermão da Sexagésima</em>)</td>\n</tr>\n</tbody>\n</table>\n<div class=\"callout callout-caution\">\n\n<p><strong>Pegadinha clássica da M-Tec Q1:</strong> A banca define perfeitamente o que é <strong>Cultismo</strong> (jogo de palavras/linguagem sensorial rebuscada) e <strong>Conceptismo</strong> (jogo de ideias/raciocínio lógico), e simplesmente <strong>troca um nome pelo outro</strong> nas alternativas! Associe sempre: <strong>Con</strong>ceptismo = <strong>Con</strong>ceito / <strong>Ideia</strong>; <strong>Cul</strong>tismo = <strong>Cul</strong>tura da palavra / <strong>Forma</strong>!</p>\n</div>\n\n<hr />\n<h3 id=\"-parte-4--história-geral-do-1º-ano-pré-história-antiguidade-e-feudalismo-m-tec-q24q27\">📚 Parte 4 — História Geral do 1º Ano: Pré-História, Antiguidade e Feudalismo <em>(M-Tec Q24–Q27)</em></h3>\n<h4 id=\"1-pré-história-paleolítico-vs-revolução-neolítica-m-tec-q24q25\">1. Pré-História: Paleolítico vs. Revolução Neolítica <em>(M-Tec Q24–Q25)</em></h4>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Período</th>\n<th style=\"text-align: left;\">Estilo de Vida</th>\n<th style=\"text-align: left;\">Como Conseguia Alimento e Tecnologia</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Paleolítico</strong> <em>(Idade da Pedra Lascada)</em></td>\n<td style=\"text-align: left;\"><strong>Nomadismo:</strong> bandos mudavam constantemente de região assim que caça/frutos esgotavam-se.</td>\n<td style=\"text-align: left;\"><strong>Caça, pesca e coleta</strong>; ferramentas rústicas de pedra lascada e ossos; <strong>domínio do fogo</strong>; arte rupestre nas cavernas.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Neolítico</strong> <em>(Idade da Pedra Polida — Revolução Neolítica)</em></td>\n<td style=\"text-align: left;\"><strong>Sedentarismo:</strong> fixaram moradia permanente em aldeias próximas a grandes rios.</td>\n<td style=\"text-align: left;\">Descoberta da <strong>agricultura</strong> e <strong>domesticação de animais</strong>! Produção de <strong>excedentes</strong>, cerâmica, tecelagem, crescimento populacional e surgimento da propriedade privada/Estado.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Idade dos Metais</strong></td>\n<td style=\"text-align: left;\">Cidades organizadas e comércio</td>\n<td style=\"text-align: left;\">Fundição de cobre, bronze e ferro; invenção da roda e dos primeiros sistemas de escrita (fim da Pré-História!).</td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li><strong>Conceitos de Migração <em>(M-Tec Q24)</em>:</strong> <strong>Nomadismo</strong> (deslocamento constante sem residência fixa para sobreviver); <strong>Sedentarismo</strong> (fixação num território por meio da agricultura/moradia); <strong>Êxodo Rural</strong> (migração em massa de trabalhadores do campo para as cidades em busca de emprego urbano/industrial).</li>\n</ul>\n<h4 id=\"2-antiguidade-oriental-primeiras-civilizações-e-clássica-m-tec-q26\">2. Antiguidade Oriental (Primeiras Civilizações) e Clássica <em>(M-Tec Q26)</em></h4>\n<p>As primeiras civilizações urbanas surgiram no <strong>Crescente Fértil</strong> (<em>Mesopotâmia</em> — sumérios, babilônios entre os rios <strong>Tigre e Eufrates</strong>; <em>Egito</em> no <strong>Rio Nilo</strong>), caracterizadas como <strong>sociedades hidráulicas</strong> (agricultura de irrigação controlada pelo Estado), governo <strong>teocrático</strong> (rei visto como deus ou representante divino), leis escritas (<strong>Código de Hamurabi</strong> — <em>\"olho por olho, dente por dente\"</em>) e sistemas de escrita (cuneiforme/hieróglifos). Na sequência, <strong>Grécia</strong> (democracia ateniense, filosofia) e <strong>Roma</strong> (direito romano, república, império, cristianismo).</p>\n<h4 id=\"3-idade-média-ocidental--feudalismo-sécs-v-ao-xv--m-tec-q27\">3. Idade Média Ocidental &amp; Feudalismo (sécs. V ao XV — <em>M-Tec Q27</em>)</h4>\n<p>Após a queda de Roma Ocidental (476 d.C.) e invasões germânicas, a Europa ruralizou-se:</p>\n<ul>\n<li><strong>Economia Feudal:</strong> Essencialmente <strong>agrária, rural, autossuficiente (de subsistência)</strong>, com escambo e baixíssima circulação monetária dentro do feudo (<em>manso senhorial, manso servil e terras comunais</em>).</li>\n<li><strong>Sociedade Estamental (sem mobilidade social — \"nasceu servo, morre servo\"):</strong>\n<ol>\n<li><strong>Clero</strong> (<em>oratores</em> — os que rezam/dominam o saber);</li>\n<li><strong>Nobreza</strong> (<em>bellatores</em> — os senhores feudais guerreiros donos das terras);</li>\n<li><strong>Servos</strong> (<em>laboratores</em> — camponeses presos à terra, não eram escravos comprados/vendidos, mas pagavam pesados tributos como <strong>corveia</strong> [trabalho gratuito nas terras do senhor], <strong>talha</strong> [parte da produção] e <strong>banalidades</strong> [uso de forno/moinho]).</li>\n</ol></li>\n<li><strong>Política Descentralizada:</strong> O poder real enfraqueceu e pulverizou-se entre os senhores locais ligados pelo contrato de <strong>Suserania e Vassalagem</strong> (o <strong>suserano</strong> doava um <strong>feudo/terra</strong> ao <strong>vassalo</strong>, que jurava lealdade e apoio militar). A única instituição centralizadora unindo a Europa era a <strong>Igreja Católica (Teocentrismo)</strong>.</li>\n</ul>\n<hr />\n<h3 id=\"️️-dissecando-questões-reais-da-prova-m-tec\">🕵️‍♂️ Dissecando Questões Reais da Prova M-Tec</h3>\n<h4 id=\"questão-resolvida-1-baseada-em-m-tec-2022-q1--barroco\">Questão Resolvida 1 (Baseada em M-Tec 2022 Q1 — Barroco)</h4>\n<p><em>No Barroco brasileiro e português, a tendência marcada pelo jogo lógico de ideias, silogismos e raciocínio argumentativo, presente nos sermões de Padre Antônio Vieira, denomina-se _____; enquanto o rebuscamento formal com jogo de palavras e metáforas sensoriais denomina-se _____.</em></p>\n<ul>\n<li><strong>Gabarito:</strong> <strong>Conceptismo</strong> (ideias/lógica) e <strong>Cultismo</strong> (palavras/forma).</li>\n</ul>\n<h4 id=\"questão-resolvida-2-baseada-em-m-tec-2022-q4--figuras-de-linguagem\">Questão Resolvida 2 (Baseada em M-Tec 2022 Q4 — Figuras de Linguagem)</h4>\n<p><em>\"Vivemos em uma época em que estar hiperconectado no celular nos deixa cada vez mais solitários.\" A figura de linguagem dominante na contradição lógica entre estar \"hiperconectado\" e \"mais solitário\" numa mesma ideia é:</em></p>\n<ul>\n<li><strong>Gabarito:</strong> <strong>Paradoxo</strong> (ideias logicamente excludentes unidas numa mesma afirmação crítica).</li>\n</ul>\n<h4 id=\"questão-resolvida-3-baseada-em-m-tec-2022-q25--q27--neolítico-e-feudalismo\">Questão Resolvida 3 (Baseada em M-Tec 2022 Q25 &amp; Q27 — Neolítico e Feudalismo)</h4>\n<p><em>Sobre a Revolução Neolítica e o Feudalismo: I. A domesticação de plantas e animais no Neolítico permitiu a sedentarização humana. II. A economia feudal europeia era predominantemente industrial e centrada no comércio marítimo assalariado.</em></p>\n<ul>\n<li><strong>Item I:</strong> VERDADEIRO.</li>\n<li><strong>Item II:</strong> <strong>FALSO!</strong> O feudalismo era agrário, rural, de subsistência e baseado no trabalho <strong>servil</strong> (não assalariado industrial!).</li>\n</ul>\n<hr><h2 id=\"dia-13--base-comum-m-tec-ii-matemática-química-física-e-biologiameio-ambiente-1º-ano-em\">Dia 13 — Base Comum M-Tec II: Matemática, Química, Física e Biologia/Meio Ambiente (1º Ano EM)</h2>\n<h3 id=\"-contexto-no-mundo-real-pontos-decisivos-que-diferenciam-quem-passa\">🎯 Contexto no Mundo Real: Pontos Decisivos que Diferenciam Quem Passa</h3>\n<p>Em provas do <strong>M-Tec 2º Ano</strong> (como vimos nas questões reais <strong>M-Tec 2022 Q10–Q23 e Q33</strong>), quem estuda só informática costuma deixar pontos valiosos na mesa em <strong>Conjuntos Numéricos, Contagem, Função Quadrática, Áreas com Pitágoras, Massa Molar, Condutividade de Ligações Químicas e Óptica das Cores</strong>. A excelente notícia é que os problemas cobrados pela banca seguem <strong>fórmulas diretas e limpas</strong>, fáceis de dominar quando entendemos o raciocínio por trás de cada conta!</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Você encontra Matemática, Química e Física do 1º ano funcionando dentro dos próprios jogos e do seu PC:</p>\n<ul>\n<li><strong>Contagem (Combinações de PIN / Senha / Tag):</strong> Quer criar uma senha/código numérico de 3 dígitos distintos sem começar com <code>0</code>? Você calcula passo a passo quantas opções existem em cada slot — começando sempre pela casa que tem restrição (<code>0</code> proibido na frente!).</li>\n<li><strong>Função do 2º Grau (<code>ax² + bx + c</code>) = Trajetória de Granada / Flecha / Bola:</strong> Quando você joga uma granada para cima, ela sobe até o <strong>ponto máximo (Vértice <code>y_v</code>)</strong> e cai formando uma <strong>parábola com concavidade para baixo (<code>a &lt; 0</code>)</strong>! E quando cai numa conta de lucro mínimo, <code>a &gt; 0</code>.</li>\n<li><strong>Geometria <code>3-4-5</code> = Distância em Diagonal / Hitbox no Mapa:</strong> Se um player andou <code>30m</code> para o Norte e <code>40m</code> para o Leste, a distância em linha reta (<em>Pitágoras</em>) fecha exatamente <strong><code>50m</code></strong> sem precisar sofrer na raiz quadrada!</li>\n<li><strong>Química nos Cabos e Bateria do PC:</strong>\n<ul>\n<li>Os fios de <strong>Cobre (<code>Cu</code>)</strong> dentro do seu PC e USB conduzem eletricidade direto no <strong>estado SÓLIDO</strong> porque são <strong>Metais</strong> (mar de elétrons livres).</li>\n<li>Água pura (destilada) ou plástico isolante da capa do fio é <strong>Molecular/Covalente</strong> (não conduz!), mas se cair sal (<code>NaCl</code>, <strong>Iônico</strong>) dissolvido na água, libera íons e <strong>conduz corrente na hora</strong>!</li>\n</ul></li>\n<li><strong>Óptica das Cores na Tela/Iluminação:</strong> Quando uma lâmpada RGB verde ilumina um objeto vermelho opaco, ele não tem luz vermelha para refletir de volta — absorve o verde e fica <strong>PRETO</strong>!</li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--matemática-do-1º-ano-passo-a-passo-m-tec-q19q23\">📚 Parte 1 — Matemática do 1º Ano Passo a Passo <em>(M-Tec Q19–Q23)</em></h3>\n<h4 id=\"1-os-conjuntos-numéricos-ℕ-ℤ-ℚ-𝕀-ℝ-m-tec-q19\">1. Os Conjuntos Numéricos (<code>ℕ, ℤ, ℚ, 𝕀, ℝ</code>) <em>(M-Tec Q19)</em></h4>\n<p>Entenda onde cada número \"mora\" para nunca errar dízimas periódicas nem raízes:</p>\n<ul>\n<li><strong><code>ℕ</code> (Naturais):</strong> Inteiros de contagem não negativos <code>{0, 1, 2, 3, 4, ...}</code>.</li>\n<li><strong><code>ℤ</code> (Inteiros):</strong> Acrescenta os negativos exatos <code>{..., -3, -2, -1, 0, 1, 2, ...}</code>. Logo, todo Natural é Inteiro (<code>ℕ ⊂ ℤ</code>).</li>\n<li><strong><code>ℚ</code> (Racionais):</strong> Qualquer número que <strong>pode ser escrito em forma de fração <code>a / b</code></strong> (<code>b ≠ 0</code>). Isso inclui:\n<ul>\n<li>Todos os inteiros (<code>5 = 5/1</code>);</li>\n<li>Decimais exatos/finitos (<code>0,25 = 1/4</code>; <code>1,75 = 7/4</code>);</li>\n<li><strong>Todas as DÍZIMAS PERIÓDICAS (infinitas com repetição padrão)!</strong> Ex.: <code>0,333... = 1/3</code>, <code>0,454545... = 45/99 = 5/11</code> → Logo, <strong>dízima periódica é RACIONAL (<code>ℚ</code>)!</strong></li>\n</ul></li>\n<li><strong><code>𝕀</code> (Irracionais):</strong> Números decimais <strong>infinitos e NÃO periódicos</strong> que <strong>jamais viram fração exata</strong>: <code>π ≈ 3,14159265...</code>, <code>e ≈ 2,71828...</code>, raízes não exatas (<code>√2 ≈ 1,41421...</code>, <code>√3</code>, <code>√5</code>). <em>(Atenção: <code>√9 = 3</code>, logo <code>√9</code> é Natural/Racional, NÃO irracional!)</em></li>\n<li><strong><code>ℝ</code> (Reais):</strong> A união dos Racionais + Irracionais (<code>ℝ = ℚ ∪ 𝕀</code>). Importante: <code>ℚ ∩ 𝕀 = ∅</code> (nenhum número pertence aos dois ao mesmo tempo!).</li>\n</ul>\n<h4 id=\"2-operações-entre-conjuntos-e-diagrama-de-venn-m-tec-q22\">2. Operações entre Conjuntos e Diagrama de Venn <em>(M-Tec Q22)</em></h4>\n<p>Dados dois ou três conjuntos finitos:</p>\n<ul>\n<li><strong>Interseção (<code>A ∩ B</code>):</strong> Pega <strong>apenas os elementos em comum</strong> (que aparecem dentro de <code>A</code> <strong>E</strong> dentro de <code>B</code>).</li>\n<li><strong>União (<code>A ∪ B</code>):</strong> Junta <strong>todos</strong> os elementos de <code>A</code> e de <code>B</code> num conjunto só, <strong>sem repetir duplicatas</strong>.</li>\n<li><strong>Diferença (<code>A - B</code>):</strong> Pega os elementos de <code>A</code>, <strong>removendo</strong> qualquer um que também pertença a <code>B</code>.</li>\n</ul>\n<p><strong>💻 Exemplo Resolvido Passo a Passo (estilo M-Tec Q22):</strong> Se <code>A = {1, 2, 4, 6}</code>, <code>B = {2, 3, 6, 8}</code> e <code>C = {3, 9}</code>, quanto vale <strong><code>(A ∩ B) ∪ C</code></strong>?</p>\n<ol>\n<li><strong>Regra dos parênteses primeiro:</strong> <code>A ∩ B</code> = o que existe em <code>A</code> e em <code>B</code> ao mesmo tempo → <strong><code>{2, 6}</code></strong>.</li>\n<li>Agora fazemos a união com <code>C</code>: <code>{2, 6} ∪ {3, 9}</code> → juntando e ordenando: <strong><code>{2, 3, 6, 9}</code></strong>! <em>(Nota: em problemas de pesquisa — \"80 gostam de Python, 50 de JS e 20 de ambos\" — lembre-se sempre de <strong>começar preenchendo o centro da interseção (<code>20</code>)</strong> no diagrama e descontar <code>80 - 20 = 60 só Python</code> e <code>50 - 20 = 30 só JS</code>, evitando contar os 20 alunos duas vezes!)</em></li>\n</ol>\n<h4 id=\"3-princípio-fundamental-da-contagem-com-o-dígito-zero-m-tec-q23\">3. Princípio Fundamental da Contagem com o Dígito Zero <em>(M-Tec Q23)</em></h4>\n<p><strong>Pergunta clássica:</strong> <em>Quantos números naturais de <strong>3 algarismos distintos</strong> podemos formar usando o conjunto <code>{0, 1, 2, 3, 4, 5}</code>?</em></p>\n<ol>\n<li>Desenhe 3 tracinhos para as casas: <code>[ Centena ] × [ Dezena ] × [ Unidade ]</code>.</li>\n<li><strong>A Pegadinha Fatal do Zero:</strong> Um número natural de 3 algarismos <strong>NUNCA pode começar com <code>0</code></strong> (pois <code>045</code> equivale a <code>45</code>, que só tem 2 algarismos!).</li>\n<li>Preenchendo <strong>da esquerda para a direita (começando pela restrição!)</strong>:\n<ul>\n<li><strong>1ª casa (Centena):</strong> Dos 6 dígitos <code>{0,1,2,3,4,5}</code>, o <code>0</code> está proibido! Sobram <strong>5 opções</strong> (<code>1, 2, 3, 4</code> ou <code>5</code>).</li>\n<li><strong>2ª casa (Dezena):</strong> Já usamos 1 dígito na centena (digamos o <code>3</code>), mas <strong>agora o <code>0</code> está liberado</strong>! Dos 6 originais menos o <code>3</code> já gasto, restam <strong>5 opções</strong> (<code>0, 1, 2, 4, 5</code>)!</li>\n<li><strong>3ª casa (Unidade):</strong> Dos 6 dígitos, já gastamos 2 distintos. Restam <strong>4 opções</strong>!</li>\n</ul></li>\n<li>Multiplicamos tudo: <strong><code>5 × 5 × 4 = 100 números distintos</code></strong>! <em>(E se permitisse repetição? Seria <code>5 × 6 × 6 = 180</code>!).</em></li>\n</ol>\n<h4 id=\"4-função-afim-1º-grau-e-função-quadrática-2º-grau-m-tec-q20\">4. Função Afim (1º Grau) e Função Quadrática (2º Grau) <em>(M-Tec Q20)</em></h4>\n<ul>\n<li><strong>Função Afim (<code>f(x) = ax + b</code>):</strong> Gráfico é uma reta. <code>a</code> é a taxa de variação (inclinação: se <code>a &gt; 0</code> crescente; <code>a &lt; 0</code> decrescente); <code>b</code> é o valor fixo inicial onde a reta corta o eixo Y (<code>x = 0</code>).</li>\n<li><strong>Função Quadrática (<code>f(x) = ax² + bx + c</code>, com <code>a ≠ 0</code>):</strong> Gráfico é uma <strong>parábola</strong>:\n<ul>\n<li>Se <strong><code>a &gt; 0</code></strong>: concavidade voltada para <strong>CIMA</strong> (tem <strong>ponto de MÍNIMO</strong>).</li>\n<li>Se <strong><code>a &lt; 0</code></strong>: concavidade voltada para <strong>BAIXO</strong> (tem <strong>ponto de MÁXIMO</strong> — ótimo para lucro/altura máxima!).</li>\n<li><strong>Raízes (zeros da função, <code>ax² + bx + c = 0</code>):</strong>\n<ol>\n<li>Discriminante: <strong><code>Δ = b² - 4 · a · c</code></strong>\n<ul>\n<li><code>Δ &gt; 0</code> → <strong>duas raízes reais distintas</strong>;</li>\n<li><code>Δ = 0</code> → <strong>uma única raiz real dupla</strong> (toca o eixo X num ponto);</li>\n<li><code>Δ &lt; 0</code> → <strong>não possui raízes reais</strong> (não toca o eixo X).</li>\n</ul></li>\n<li>Bhaskara: <strong><code>x = (-b ± √Δ) / (2a)</code></strong>.</li>\n</ol></li>\n<li><strong>Vértice da Parábola (Máximo ou Mínimo):</strong> <strong><code>x_v = -b / (2a)</code></strong> e <strong><code>y_v = -Δ / (4a)</code></strong> (ou apenas substitua o valor achado de <code>x_v</code> na própria função <code>f(x)</code>!).</li>\n</ul></li>\n</ul>\n<p><strong>💻 Exemplo Resolvido:</strong> Para <code>f(x) = x² - 5x + 6</code>:</p>\n<ul>\n<li><code>a = 1 (&gt; 0 → concavidade p/ cima)</code>, <code>b = -5</code>, <code>c = 6</code>.</li>\n<li><code>Δ = (-5)² - 4(1)(6) = 25 - 24 = 1 (&gt; 0 → 2 raízes reais distintas!)</code>.</li>\n<li><code>x = (5 ± √1) / 2</code> → <strong><code>x₁ = 3</code></strong> e <strong><code>x₂ = 2</code></strong>. Vértice: <code>x_v = 5/2 = 2,5</code> e <code>y_v = (2,5)² - 5(2,5) + 6 = -0,25</code>.</li>\n</ul>\n<h4 id=\"5-geometria-plana-triângulo-3-4-5-e-decomposição-de-áreas-m-tec-q21\">5. Geometria Plana, Triângulo 3-4-5 e Decomposição de Áreas <em>(M-Tec Q21)</em></h4>\n<ul>\n<li><strong>Fórmulas essenciais:</strong>\n<ul>\n<li>Retângulo / Paralelogramo: <code>A = base × altura</code></li>\n<li>Triângulo: <code>A = (base × altura) / 2</code></li>\n<li>Trapézio: <code>A = ((B + b) × h) / 2</code></li>\n<li>Círculo: <code>A = π · r²</code> e Comprimento: <code>C = 2 · π · r</code></li>\n</ul></li>\n<li><strong>Teorema de Pitágoras &amp; Triângulo 3-4-5:</strong> Num triângulo retângulo, <code>hipotenusa² = cateto₁² + cateto₂²</code>.\n<ul>\n<li>Sempre que você vir catetos múltiplos de <strong>3 e 4</strong>, a hipotenusa é múltiplo de <strong>5</strong> sem precisar fazer conta gigante! Ex.: <strong><code>30m</code> e <code>40m</code> → hipotenusa <code>50m</code></strong> (<code>30² + 40² = 900 + 1600 = 2500 = 50²</code>), e área = <code>(30 × 40) / 2 = 600 m²</code>!</li>\n</ul></li>\n<li><strong>Resolvendo terreno composto <em>(M-Tec Q21)</em>:</strong> Divida figuras em L ou chanfradas em um retângulo + um triângulo retângulo (ou trapézio + retângulo) e <strong>some as áreas individuais</strong>. Exemplo da prova: terreno composto formado por retângulo + trapézio/triângulo totalizando <strong><code>2.320 m²</code></strong> (como <code>40m × 58m = 2.320 m²</code> ou retângulo <code>40 × 43 = 1.720 m²</code> + triângulo <code>30×40/2 = 600 m²</code> → <strong><code>1.720 + 600 = 2.320 m²</code></strong>!).</li>\n</ul>\n<hr />\n<h3 id=\"-parte-2--química-do-1º-ano-ligações-condutividade-e-massa-molar-m-tec-q17q18\">📚 Parte 2 — Química do 1º Ano: Ligações, Condutividade e Massa Molar <em>(M-Tec Q17–Q18)</em></h3>\n<h4 id=\"1-ligações-químicas--condutividade-elétrica-m-tec-q18--quase-100-de-chance-na-prova\">1. Ligações Químicas &amp; Condutividade Elétrica <em>(M-Tec Q18 — Quase 100% de chance na prova!)</em></h4>\n<p>Para haver corrente elétrica, é obrigatório existir <strong>cargas elétricas livres para se movimentar</strong> (elétrons livres ou íons soltos):</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Tipo de Ligação</th>\n<th style=\"text-align: left;\">Como os átomos se unem</th>\n<th style=\"text-align: left;\">Exemplos Reais</th>\n<th style=\"text-align: left;\">Conduz Eletricidade? (DECORE ISSO!)</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>1. Ligação Metálica</strong> <em>(Metal + Metal)</em></td>\n<td style=\"text-align: left;\">Átomos doam elétrons externos formando um <strong>\"mar de elétrons\" móveis</strong> ao redor dos cátions.</td>\n<td style=\"text-align: left;\">Ferro (<code>Fe</code>), Cobre (<code>Cu</code>), Alumínio (<code>Al</code>), Ouro (<code>Au</code>)</td>\n<td style=\"text-align: left;\"><strong>CONDUZ no estado SÓLIDO</strong> e no líquido! (Por isso fios elétricos são de cobre sólido!).</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>2. Ligação Iônica</strong> <em>(Metal + Ametal/H)</em></td>\n<td style=\"text-align: left;\"><strong>Transferência definitiva</strong> de elétrons formando <strong>íons</strong> positivos (<code>+</code>) e negativos (<code>-</code>) presos num cristal rígido.</td>\n<td style=\"text-align: left;\">Sal de cozinha (<code>NaCl</code>), Fluoreto (<code>NaF</code>), Óxidos metálicos (<code>CaO</code>)</td>\n<td style=\"text-align: left;\"><strong>NÃO conduz no estado SÓLIDO</strong> (íons presos na rede cristalina), mas <strong>CONDUZ quando LÍQUIDO/FUNDIDO (derretido) ou DISSOLVIDO EM ÁGUA</strong> (pois os íons ficam livres!).</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>3. Ligação Covalente (Molecular)</strong> <em>(Ametal + Ametal / Hidrogênio)</em></td>\n<td style=\"text-align: left;\">Átomos <strong>compartilham pares de elétrons</strong> formando moléculas eletricamente neutras, sem íons!</td>\n<td style=\"text-align: left;\">Açúcar (<code>C₁₂H₂₂O₁₁</code>), Álcool (<code>C₂H₅OH</code>), Água pura (<code>H₂O</code>), Oxigênio (<code>O₂</code>)</td>\n<td style=\"text-align: left;\"><strong>NÃO conduz eletricidade NEM no estado SÓLIDO, NEM puro/líquido!</strong></td>\n</tr>\n</tbody>\n</table>\n<div class=\"callout callout-tip\">\n\n<p><strong>Resumo instantâneo da Tabela de Condutividade <em>(M-Tec Q18)</em>:</strong></p>\n<ul>\n<li>Conduz sólido <strong>E</strong> líquido? → <strong>Metal (Ligação Metálica)</strong>.</li>\n<li>Não conduz sólido, mas conduz líquido/aquoso? → <strong>Composto Iônico</strong>.</li>\n<li>Não conduz em nenhum estado? → <strong>Composto Molecular / Covalente</strong>.</li>\n</ul>\n</div>\n\n<h4 id=\"2-cálculo-de-massa-molecular-u--massa-molar-gmol-m-tec-q17\">2. Cálculo de Massa Molecular (<code>u</code>) / Massa Molar (<code>g/mol</code>) <em>(M-Tec Q17)</em></h4>\n<p>Basta multiplicar a massa atômica de cada elemento (dada no enunciado: geralmente <strong><code>H = 1</code>, <code>C = 12</code>, <code>N = 14</code>, <code>O = 16</code></strong>) pela quantidade de átomos que aparecem na fórmula:</p>\n<ol>\n<li><strong>Etanol / Álcool Etílico (<code>C₂H₅OH</code> ou <code>C₂H₆O</code>):</strong>\n<ul>\n<li><code>C</code>: <code>2 átomos × 12 = 24</code></li>\n<li><code>H</code>: <code>5 + 1 = 6 átomos × 1 = 6</code> <em>(Cuidado para não esquecer o <code>H</code> que fica depois do <code>O</code>!)</em></li>\n<li><code>O</code>: <code>1 átomo × 16 = 16</code></li>\n<li><strong>Total:</strong> <code>24 + 6 + 16 =</code> <strong><code>46 u</code> (<code>46 g/mol</code>)</strong>!</li>\n</ul></li>\n<li><strong>Ácido Acético / Vinagre (<code>C₂H₄O₂</code>):</strong>\n<ul>\n<li><code>C</code>: <code>2 × 12 = 24</code> | <code>H</code>: <code>4 × 1 = 4</code> | <code>O</code>: <code>2 × 16 = 32</code></li>\n<li><strong>Total:</strong> <code>24 + 4 + 32 =</code> <strong><code>60 u</code> (<code>60 g/mol</code>)</strong>!</li>\n</ul></li>\n<li><strong>Dióxido de Carbono (<code>CO₂</code>):</strong> <code>12 + 2×16 =</code> <strong><code>44 u</code></strong> | <strong>Glicose (<code>C₆H₁₂O₆</code>):</strong> <code>6×12 + 12×1 + 6×16 = 72 + 12 + 96 =</code> <strong><code>180 u</code></strong>.</li>\n</ol>\n<hr />\n<h3 id=\"-parte-3--física-óptica-das-cores--biologia--meio-ambiente-m-tec-q10q16--q33\">📚 Parte 3 — Física (Óptica das Cores) &amp; Biologia / Meio Ambiente <em>(M-Tec Q10–Q16 &amp; Q33)</em></h3>\n<h4 id=\"1-física--óptica-das-cores-por-reflexão-seletiva-m-tec-q33\">1. Física — Óptica das Cores por Reflexão Seletiva <em>(M-Tec Q33)</em></h4>\n<p>A luz solar (branca) é <strong>policromática</strong>, contendo todas as cores do espectro visível juntas (vermelho, laranja, amarelo, verde, azul, anil, violeta). A cor que enxergamos em um objeto opaco depende exclusivamente de <strong>qual cor da luz ele REFLETE</strong> até os nossos olhos (as demais são absorvidas em forma de calor):</p>\n<ul>\n<li><strong>Tomate maduro sob luz branca (Sol):</strong> Absorve azul, verde, amarelo etc., e <strong>REFLETE a luz vermelha</strong> → vemos <strong>vermelho</strong>!</li>\n<li><strong>Tomate vermelho dentro de uma sala iluminada APENAS com luz VERDE pura (monocromática):</strong> Como só chega luz verde, e o pigmento vermelho do tomate <strong>absorve</strong> a luz verde sem ter nenhuma luz vermelha para refletir, não volta luz alguma para nossos olhos → <strong>enxergamos o tomate PRETO!</strong></li>\n<li><strong>Camisa branca sob luz verde:</strong> O branco reflete <strong>todas</strong> as cores que chegam — se só chega luz verde, ele reflete verde → vemos <strong>verde</strong>!</li>\n<li><strong>Objeto preto:</strong> Absorve praticamente <strong>todas</strong> as cores (por isso esquenta rápido no Sol).</li>\n</ul>\n<h4 id=\"2-método-científico-m-tec-q10\">2. Método Científico <em>(M-Tec Q10)</em></h4>\n<p>Ordem lógica rigorosa da investigação científica:</p>\n<ol>\n<li><strong>Observação</strong> cuidadosa do fenômeno natural + <strong>Questionamento</strong>;</li>\n<li>Formulação de <strong>Hipótese</strong> (uma explicação provisória e <strong>testável</strong>);</li>\n<li><strong>Experimentação controlada</strong> (grupo teste × grupo controle) para testar a hipótese;</li>\n<li><strong>Coleta e Análise de Dados</strong>;</li>\n<li><strong>Conclusão</strong> (confirma, ajusta ou refuta a hipótese — conhecimento científico não é dogma imutável!).</li>\n</ol>\n<h4 id=\"3-sustentabilidade-poluentes-e-protocolo-de-kyoto-m-tec-q13q16\">3. Sustentabilidade, Poluentes e Protocolo de Kyoto <em>(M-Tec Q13–Q16)</em></h4>\n<ul>\n<li><strong>Desenvolvimento Sustentável:</strong> Atender às necessidades da geração atual <strong>sem comprometer</strong> a capacidade das gerações futuras (equilíbrio ambiental, social e econômico).</li>\n<li><strong>Efeito Estufa vs. Aquecimento Global:</strong> O Efeito Estufa <em>natural</em> é vital (retém calor na Terra evitando congelamento). O problema atual é a <strong>intensificação antrópica</strong> pelo excesso de gases como <strong><code>CO₂</code></strong> (queima de combustíveis fósseis, desmatamento) e <strong><code>CH₄</code> (metano)</strong>, gerando <strong>Aquecimento Global</strong> e derretimento de geleiras/eventos extremos.</li>\n<li><strong>Protocolo de Kyoto (1997):</strong> Tratado internacional pioneiro que estabeleceu metas obrigatórias para países desenvolvidos <strong>reduzirem emissões de gases do efeito estufa</strong>, criando o mecanismo de <strong>créditos de carbono</strong> (Mecanismo de Desenvolvimento Limpo).</li>\n<li><strong>Chuva Ácida &amp; Tabelas CETESB (<code>SO₂</code>):</strong> O dióxido de enxofre (<strong><code>SO₂</code></strong>) e óxidos de nitrogênio (<code>NOₓ</code>) liberados por indústrias/escapamentos reagem com a umidade do ar formando <strong>chuva ácida</strong> (danifica solos, lagos e monumentos). Em questões com tabela da <strong>CETESB</strong>, leia atentamente o cabeçalho da coluna, o ano pedido e confira a unidade (<code>µg/m³</code>).</li>\n</ul>\n<hr />\n<h3 id=\"️️-dissecando-questões-reais-da-prova-m-tec\">🕵️‍♂️ Dissecando Questões Reais da Prova M-Tec</h3>\n<h4 id=\"questão-resolvida-1-baseada-em-m-tec-2022-q18--q17--química\">Questão Resolvida 1 (Baseada em M-Tec 2022 Q18 &amp; Q17 — Química)</h4>\n<p><em>Três substâncias sólidas desconhecidas X, Y e Z foram testadas no laboratório:</em></p>\n<ul>\n<li><em>X não conduz corrente sólido, mas conduz muito bem quando fundido/líquido.</em></li>\n<li><em>Y conduz corrente elétrica já no estado sólido.</em></li>\n<li><em>Z não conduz nem sólido nem dissolvido em água.</em> <em>Classifique as ligações de X, Y e Z:</em></li>\n<li><strong>X</strong> = Composto <strong>Iônico</strong>; <strong>Y</strong> = <strong>Metálico</strong>; <strong>Z</strong> = <strong>Covalente / Molecular</strong>.</li>\n</ul>\n<h4 id=\"questão-resolvida-2-baseada-em-m-tec-2022-q23--contagem\">Questão Resolvida 2 (Baseada em M-Tec 2022 Q23 — Contagem)</h4>\n<p><em>Quantos números de 3 algarismos distintos podem ser formados com <code>{0, 2, 4, 6, 8}</code>?</em></p>\n<ul>\n<li>Cuidado com o <code>0</code> na centena!</li>\n<li>1ª casa (sem <code>0</code>): <strong>4 opções</strong> (<code>2, 4, 6, 8</code>).</li>\n<li>2ª casa (entra o <code>0</code>, sai a usada na 1ª): <strong>4 opções</strong>.</li>\n<li>3ª casa: <strong>3 opções</strong>.</li>\n<li>Total: <code>4 × 4 × 3 =</code> <strong><code>48 números</code></strong>!</li>\n</ul>\n<h4 id=\"questão-resolvida-3-baseada-em-m-tec-2022-q33--física-óptica\">Questão Resolvida 3 (Baseada em M-Tec 2022 Q33 — Física Óptica)</h4>\n<p><em>Num palco iluminado exclusivamente por refletores monocromáticos azuis, um artista entra vestindo uma camisa amarela pura e uma calça branca. Como o público enxergará a camisa e a calça?</em></p>\n<ul>\n<li><strong>Camisa amarela</strong> absorve luz azul (só refletiria amarelo/vermelho/verde) → parece <strong>PRETA</strong>.</li>\n<li><strong>Calça branca</strong> reflete todas as cores incidentes → parece <strong>AZUL</strong>!</li>\n</ul>\n<hr>\n<h2>Guia Especial M-Tec — Base Nacional Comum (1º Ano do Ensino Médio)</h2>\n<p>Nas provas de Vagas Remanescentes para o <strong>2º Ano M-Tec (Ensino Médio Integrado ao Técnico)</strong>, além das questões técnicas de Desenvolvimento de Sistemas, podem cair questões essenciais da 1ª série do Ensino Médio. Abaixo está o resumo exato do que já caiu na prova oficial M-Tec da Etec:</p>\n\n<h3>1. Língua Portuguesa, Literatura e Inglês</h3>\n<ul>\n  <li><strong>Quinhentismo (Século XVI):</strong> <em>Literatura Informativa</em> (cataloga e descreve as novas terras — ex.: Carta de Caminha) e <em>Literatura Jesuítica</em> (poesias e teatro de José de Anchieta para catequizar os indígenas).</li>\n  <li><strong>Barroco:</strong> Expressa contradições humanas (matéria x espírito, vida x morte, pecado x perdão) usando antíteses e paradoxos.\n    <ul>\n      <li><strong>Cultismo:</strong> Linguagem rebuscada, jogo de <strong>palavras</strong> e imagens sensoriais.</li>\n      <li><strong>Conceptismo:</strong> Jogo de <strong>ideias</strong>, argumentação e raciocínio lógico. <em>(Pegadinha da prova: inverter os dois!)</em></li>\n    </ul>\n  </li>\n  <li><strong>Trovadorismo (Idade Média):</strong> Traduz os valores do <strong>Feudalismo</strong> (vassalagem amorosa).</li>\n  <li><strong>Variação Linguística:</strong> Não existe \"português certo ou errado\", mas comunicação <strong>adequada ou inadequada ao contexto</strong>. <em>Diatópica</em> = varia por região; <em>Diacrônica</em> = varia ao longo do tempo.</li>\n  <li><strong>5 Tipos Textuais:</strong> <strong>Injunção</strong> (instruções/conselhos com verbos no imperativo), <strong>Exposição</strong> (apresenta ideias/explicações de forma clara e impessoal), <strong>Narração</strong> (fatos no tempo e espaço com personagens), <strong>Descrição</strong> (retrata com adjetivos, sem temporalidade) e <strong>Dissertação</strong> (defende ponto de vista com argumentos e conclusão).</li>\n  <li><strong>Figuras e Semântica:</strong> <strong>Paradoxo</strong> = contradição lógica na mesma ideia (<em>\"Quanto mais estudo, menos entendo\"</em>). <strong>Hipônimo/Hiperônimo</strong> = específico/geral (<em>Aristóteles / pensador</em>).</li>\n  <li><strong>Inglês Gramatical:</strong> Superlativo irregular de <em>bad</em> é <strong>worst</strong> (e de <em>good</em> é <em>best</em>); <em>daunting</em> = intimidador (<em>intimidating</em>); sufixos <code>-able</code> e <code>-ive</code> (<em>debatable, positive</em>) formam <strong>adjetivos</strong>.</li>\n</ul>\n\n<h3>2. Matemática (1º Ano EM)</h3>\n<ul>\n  <li><strong>Conjuntos Numéricos:</strong> Naturais (ℕ = {0,1,2...}), Inteiros (ℤ), Racionais (ℚ = frações e <strong>dízimas periódicas</strong>!), Irracionais (𝕀 = raízes não exatas e decimais infinitos <em>não periódicos</em> como π) e Reais (ℝ = ℚ ∪ 𝕀).</li>\n  <li><strong>Operações entre Conjuntos:</strong> Interseção (<code>A ∩ B</code> = o que tem nos dois) e União (<code>∪ C</code> = junta tudo sem repetir).</li>\n  <li><strong>Princípio da Contagem (Permutação com 0):</strong> Quantos números de 3 algarismos distintos com <code>{0,1,2,3,4,5}</code>? Como <strong>não pode começar com zero</strong>, a 1ª casa tem <strong>5 opções</strong>, a 2ª tem <strong>5</strong> (volta o 0) e a 3ª tem <strong>4</strong> &rarr; <code>5 × 5 × 4 = 100</code>.</li>\n  <li><strong>Função Quadrática <code>f(x) = ax² + bx + c</code>:</strong> Se <code>a &gt; 0</code>, concavidade para cima (ponto de mínimo). Calcule <code>Δ = b² - 4ac</code>: se <code>Δ &gt; 0</code> há <strong>duas raízes reais distintas</strong>.</li>\n  <li><strong>Geometria Plana:</strong> Área do Triângulo = <code>(base × altura) / 2</code>; Área do Trapézio = <code>[(B + b) × h] / 2</code>; macete do triângulo retângulo <strong>30 - 40 - 50</strong> (<code>30² + 40² = 50²</code>).</li>\n</ul>\n\n<h3>3. Ciências da Natureza (Química, Física e Biologia)</h3>\n<ul>\n  <li><strong>Método Científico:</strong> 1. Observação &rarr; 2. Hipótese &rarr; 3. Planejamento do experimento &rarr; 4. Análise de dados &rarr; 5. Conclusão.</li>\n  <li><strong>Meio Ambiente e Sustentabilidade:</strong> Satisfazer necessidades atuais sem comprometer gerações futuras; aquecimento global agravado por emissão de poluentes; <strong>Protocolo de Kyoto</strong> regulamentou limites de emissão e <strong>créditos de carbono</strong>.</li>\n  <li><strong>Massa Molecular (Química):</strong> Some as massas atômicas (<code>C=12, H=1, O=16</code>). Ex.: Álcool etílico <code>C₂H₅OH = 2(12)+6(1)+16 = 46 u</code>; Ácido acético <code>C₂H₄O₂ = 2(12)+4(1)+2(16) = 60 u</code>.</li>\n  <li><strong>Condutividade Elétrica dos Materiais:</strong>\n    <ul>\n      <li><strong>Metal:</strong> conduz eletricidade no estado <strong>sólido</strong> (e líquido).</li>\n      <li><strong>Composto Iônico:</strong> <strong>não conduz</strong> no estado sólido, mas <strong>conduz no estado líquido/fundido</strong> ou dissolvido em água.</li>\n      <li><strong>Composto Molecular:</strong> <strong>não conduz</strong> nem sólido nem líquido.</li>\n    </ul>\n  </li>\n  <li><strong>Óptica das Cores (Física):</strong> Enxergamos um objeto como vermelho porque ele absorve as demais cores e ocorre <strong>reflexão da cor vermelha</strong>.</li>\n</ul>\n\n<h3>4. Ciências Humanas (História e Geografia)</h3>\n<ul>\n  <li><strong>Movimentos Migratórios:</strong> <strong>Nomadismo</strong> (mudar de lugar quando esgotam alimentos da caça/coleta), <strong>Sedentarismo</strong> (fixação com agricultura), <strong>Êxodo Rural</strong> (campo &rarr; cidade), <strong>Pendularismo</strong> (ir e voltar todo dia para trabalhar/estudar), <strong>Transumância</strong> (migração sazonal).</li>\n  <li><strong>Pré-História:</strong> <strong>Paleolítico</strong> (nômades, caça/coleta, pedra lascada, descoberta de produzir fogo) vs. <strong>Neolítico</strong> (sedentarismo, agricultura, domesticação de animais).</li>\n  <li><strong>Feudalismo:</strong> Economia agrária, poder descentralizado nos feudos, trabalho servil e <strong>diminuição do uso da moeda</strong>.</li>\n</ul>\n"}, {"id": "mod5", "title": "Módulo 5 • Revisão Geral, 25 Pegadinhas & Estratégia 04/12 (Dia 14)", "html": "<h2 id=\"dia-14--revisão-integrada-final-as-25-pegadinhas-da-banca-fat-e-estratégia-para-a-prova-de-0412\">Dia 14 — Revisão Integrada Final, as 25 Pegadinhas da Banca FAT e Estratégia para a Prova de 04/12</h2>\n<h3 id=\"-contexto-no-mundo-real-juntando-todas-as-peças-no-sistema-completo\">🎯 Contexto no Mundo Real: Juntando Todas as Peças no Sistema Completo</h3>\n<p>Pare por 30 segundos e enxergue como tudo o que você estudou nestes <strong>14 dias</strong> trabalha junto num único sistema real — por exemplo, quando você abre o navegador no PC da Etec para responder a uma prova online:</p>\n<ol>\n<li>No <strong>Design (Dia 8)</strong>, a interface usou cores <strong>RGB / <code>#Hexadecimal</code></strong>, logo vetorial <strong><code>.SVG</code></strong>, fonte sem serifa do <strong>Google Fonts</strong>, espaçamento por <strong>Proximidade (Gestalt)</strong> e respeitou a <strong>Equivalência com o Mundo Real (Nielsen)</strong>.</li>\n<li>No <strong>Front-end Web (Dia 9)</strong>, a tela foi montada com <strong>HTML5 Semântico</strong> (<code>&lt;header&gt;</code>, <code>&lt;main&gt;</code>, <code>&lt;form method=\"POST\"&gt;</code>), estilizada com <strong>CSS3 Box Model</strong> (<code>padding</code>/<code>margin</code>), alterada dinamicamente via árvore <strong>DOM</strong> em JavaScript (construído com <strong>Frameworks</strong> e empacotado por <strong>Build/Bundling</strong> do <strong>Dia 4</strong> sob <strong>Git</strong> e licença <strong>MIT/GPL</strong>) e manteve sua sessão em um <strong>Cookie local (~4 KB)</strong>.</li>\n<li>Na <strong>Rede (Dia 11)</strong>, seu pedido viajou pela pilha <strong>TCP/IP</strong>, traduzido pelo <strong>DNS</strong>, criptografado via <strong>HTTPS (SSL/TLS)</strong>, através da rede local <strong>Estrela (Switch)</strong> até servidores <strong>Linux</strong> (<code>/etc</code>, <code>/var/log</code> — <strong>Dia 10</strong>) rodando em <strong>Contêineres Docker</strong> na nuvem <strong>PaaS/IaaS</strong>.</li>\n<li>No <strong>Back-end e Banco de Dados (Dias 1–7)</strong>, o servidor recebeu dados tipados/convertidos (<strong>Casting</strong>, <strong>POO</strong>, <strong>Scrum</strong>), consultou um banco relacional normalizado na <strong>1FN</strong> (sem múltiplos telefones na célula!) usando <strong>DQL (<code>SELECT COUNT(*) WHERE...</code>)</strong> e <strong>DML (<code>INSERT</code>/<code>UPDATE</code>)</strong>, e devolveu sua nota!</li>\n</ol>\n<p>Você agora não sabe só \"dicas soltas\" — você entende a arquitetura completa de sistemas!</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Encare a prova de <strong>04/12</strong> como uma <strong>Speedrun estratégica em 3 fases</strong>, igual zerar um jogo no modo ranqueado sem tiltar numa fase difícil no meio:</p>\n<ul>\n<li><strong>Fase 1 (1ª Passada — <em>Loot Rápido</em>):</strong> Garante primeiro todas as questões fáceis e diretas (E-mail, Cookies, Tags HTML, Frameworks, Licenças, Inglês, Barroco, Paleolítico/Neolítico). Questão grande que pede conta? Dá <em>skip</em> marcado e volta já com pontos garantidos no bolso!</li>\n<li><strong>Fase 2 (2ª Passada — <em>Chefões de Cálculo e I-II-III</em>):</strong> Resolve com calma os Testes de Mesa, Matrizes, Binário/Hex, Matemática e Química desenhando passo a passo no rascunho — sem \"olhômetro\".</li>\n<li><strong>Fase 3 (3ª Passada — <em>Save Final / Gabarito</em>):</strong> Confere cada marcação no cartão-resposta sem pressa e nunca entrega bolinha em branco.</li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--dicionário-das-25-pegadinhas-mais-recorrentes-da-fundação-fat\">📚 Parte 1 — Dicionário das 25 Pegadinhas Mais Recorrentes da Fundação FAT</h3>\n<p>Leia com muita atenção esta tabela antes da prova. Quase todo erro em questões I, II e III acontece exatamente por uma destas <strong>25 armadilhas verbais</strong>:</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: center;\">Nº</th>\n<th style=\"text-align: left;\">Assunto</th>\n<th style=\"text-align: left;\">Frase FALSA que a banca inventa (NÃO CAIA!)</th>\n<th style=\"text-align: left;\">Verdade Oficial da Prova</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>1</strong></td>\n<td style=\"text-align: left;\"><strong>Casting</strong></td>\n<td style=\"text-align: left;\"><code>(int) 7.99</code> converte para <code>8</code> arredondando.</td>\n<td style=\"text-align: left;\"><strong>TRUNCA (corta)</strong> a parte decimal → <strong><code>7</code></strong>! E só se chama <strong>explícita/casting</strong> (nunca \"conversão normal\").</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>2</strong></td>\n<td style=\"text-align: left;\"><strong>Tipos</strong></td>\n<td style=\"text-align: left;\"><code>'A'</code> ou <code>12</code> usa tipo booleano (<code>bool</code>).</td>\n<td style=\"text-align: left;\"><code>'A'</code> usa <strong><code>char</code></strong>; <code>\"texto\"</code> usa <strong><code>string</code></strong>; <code>bool</code> guarda <strong>exclusivamente <code>true</code>/<code>false</code></strong>.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>3</strong></td>\n<td style=\"text-align: left;\"><strong>DIV / MOD</strong></td>\n<td style=\"text-align: left;\"><code>17 MOD 5</code> vale <code>3</code> e <code>17 DIV 5</code> vale <code>2</code>.</td>\n<td style=\"text-align: left;\"><strong><code>DIV</code></strong> = quociente inteiro (<strong><code>3</code></strong>); <strong><code>MOD</code></strong> = <strong>resto</strong> da divisão (<strong><code>2</code></strong>).</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>4</strong></td>\n<td style=\"text-align: left;\"><strong>Teste de Mesa</strong></td>\n<td style=\"text-align: left;\">No <code>enquanto (x &lt;= 6)</code>, ao sair <code>x</code> ainda vale <code>6</code>.</td>\n<td style=\"text-align: left;\">O último incremento ainda acontece na última volta! Confira a tabela até a condição dar <strong>Falso</strong>.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>5</strong></td>\n<td style=\"text-align: left;\"><strong>Matrizes</strong></td>\n<td style=\"text-align: left;\">Somar diagonal secundária achando que é a principal.</td>\n<td style=\"text-align: left;\">Diagonal <strong>Principal</strong> é <strong><code>i == j</code></strong> (<code>[0][0], [1][1], [2][2]</code>). Secundária é <code>i + j == N - 1</code>.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>6</strong></td>\n<td style=\"text-align: left;\"><strong>Pilha vs Fila</strong></td>\n<td style=\"text-align: left;\">Em Pilha (<code>LIFO</code>), <code>POP</code> remove o primeiro que entrou.</td>\n<td style=\"text-align: left;\">Pilha = <strong>LIFO</strong> (<code>POP</code> remove o <strong>ÚLTIMO</strong> que entrou, do topo). Fila = <strong>FIFO</strong> (sai o primeiro).</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>7</strong></td>\n<td style=\"text-align: left;\"><strong>Frameworks</strong></td>\n<td style=\"text-align: left;\"><em>Creative Commons</em> ou <em>Adobe Creative Cloud</em> são frameworks.</td>\n<td style=\"text-align: left;\"><strong>Frameworks reais:</strong> Bootstrap, Angular, Laravel (PHP), React Native (Mobile). Os outros são licença/suíte design!</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>8</strong></td>\n<td style=\"text-align: left;\"><strong>Editores</strong></td>\n<td style=\"text-align: left;\">Bloco de Notas (Notepad) é uma IDE completa.</td>\n<td style=\"text-align: left;\">Bloco de Notas = <strong>editor de texto puro</strong>; <strong>VS Code</strong> = editor de código; <strong>Visual Studio / Eclipse</strong> = IDE; <strong>Dreamweaver/Wix</strong> = WYSIWYG.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>9</strong></td>\n<td style=\"text-align: left;\"><strong>Licenças</strong></td>\n<td style=\"text-align: left;\">Software Livre significa necessariamente gratuito (<code>R$ 0</code>).</td>\n<td style=\"text-align: left;\"><strong>Software Livre</strong> garante <strong>4 liberdades de código aberto</strong> (pode ser vendido!). Já <strong>Freeware</strong> é grátis, mas de <strong>código fechado</strong>!</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>10</strong></td>\n<td style=\"text-align: left;\"><strong>Scrum &amp; XP</strong></td>\n<td style=\"text-align: left;\">Scrum Master chefia tarefas; Pair Programming = cada dev em uma sala.</td>\n<td style=\"text-align: left;\"><strong>SM</strong> facilita/remove impedimentos; <strong>PO</strong> prioriza backlog; <strong>Daily</strong> &lt;= 15 min; <strong>Pair Programming</strong> = <strong>2 devs no mesmo PC</strong>.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>11</strong></td>\n<td style=\"text-align: left;\"><strong>POO</strong></td>\n<td style=\"text-align: left;\">Classe, Atributo e Método são os pilares da POO.</td>\n<td style=\"text-align: left;\">Os <strong>4 Pilares</strong> oficiais são: <strong>Abstração, Encapsulamento, Herança e Polimorfismo</strong>.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>12</strong></td>\n<td style=\"text-align: left;\"><strong>SQL DDL/DML/DQL</strong></td>\n<td style=\"text-align: left;\"><code>DROP</code> é DML; <code>SELECT</code> é DDL; <code>COUNT(*)</code> vai no <code>WHERE</code>.</td>\n<td style=\"text-align: left;\"><strong>DDL</strong> = <code>CREATE/ALTER/DROP</code> (estrutura); <strong>DML</strong> = <code>INSERT/UPDATE/DELETE</code> (dados); <strong>DQL</strong> = <code>SELECT</code> (<code>COUNT(*)</code> vai no <code>SELECT</code>!).</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>13</strong></td>\n<td style=\"text-align: left;\"><strong>1FN &amp; DER</strong></td>\n<td style=\"text-align: left;\">Vários telefones na mesma célula (<code>\"111, 222\"</code>) atende à 1FN.</td>\n<td style=\"text-align: left;\">Viola a <strong>1ª Forma Normal (1FN)</strong> (exige valores <strong>atômicos</strong>)! E <strong><code>idade</code></strong> via <code>data_nasc</code> é atributo <strong>derivado</strong>.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>14</strong></td>\n<td style=\"text-align: left;\"><strong>Cores</strong></td>\n<td style=\"text-align: left;\">RGB é para gráfica/papel; \"CSS\" ou \"Primária\" é padrão de cor.</td>\n<td style=\"text-align: left;\"><strong>RGB</strong> / <strong>Hex</strong> = telas (luz aditiva); <strong>CMYK</strong> = impressão (tinta).</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>15</strong></td>\n<td style=\"text-align: left;\"><strong>Vetor vs Bitmap</strong></td>\n<td style=\"text-align: left;\"><code>.JPEG</code> e <code>.PNG</code> são formatos vetoriais sem pixelação.</td>\n<td style=\"text-align: left;\"><strong>Vetorial</strong> = <strong><code>.SVG</code> / <code>.PDF</code></strong> (equações matemáticas, zoom sem perda). <strong>Bitmap</strong> = <code>.JPEG</code>, <code>.PNG</code>, <code>.BMP</code>.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>16</strong></td>\n<td style=\"text-align: left;\"><strong>Gestalt &amp; UX</strong></td>\n<td style=\"text-align: left;\">Rótulo colado ao campo é Fechamento; fonte <em>Script</em> serve para texto longo.</td>\n<td style=\"text-align: left;\">Perto = <strong>Proximidade</strong>; mesmo estilo = <strong>Semelhança</strong>. Fonte <strong>Script</strong> imita letra cursiva (só títulos/convites!).</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>17</strong></td>\n<td style=\"text-align: left;\"><strong>Cookies</strong></td>\n<td style=\"text-align: left;\">Cookies são pesados e armazenados nos servidores em nuvem.</td>\n<td style=\"text-align: left;\">Cookies são <strong>texto pequeno (~4 KB) salvos LOCALMENTE no navegador do cliente</strong> (sessão ou persistente)!</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>18</strong></td>\n<td style=\"text-align: left;\"><strong>HTML &amp; CSS</strong></td>\n<td style=\"text-align: left;\"><code>&lt;div&gt;</code> é tag semântica; <code>&lt;tr&gt;</code> é célula; <code>GET</code> esconde senha.</td>\n<td style=\"text-align: left;\"><strong><code>&lt;div&gt;</code> é genérica</strong> (<code>&lt;header&gt;/&lt;nav&gt;/&lt;main&gt;/&lt;article&gt;/&lt;footer&gt;</code> são semânticas); <code>&lt;tr&gt;</code> = linha, <code>&lt;td&gt;</code> = célula; senha vai no <strong><code>POST</code></strong>; <code>padding</code> = interno, <code>margin</code> = externo.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>19</strong></td>\n<td style=\"text-align: left;\"><strong>Binário &amp; Hex</strong></td>\n<td style=\"text-align: left;\"><code>250</code> em hexadecimal é <code>250</code> ou <code>F0</code>.</td>\n<td style=\"text-align: left;\"><code>250 ÷ 16</code> = <code>15(F)</code> resto <code>10(A)</code> = <strong><code>FA₁₆</code></strong> (<code>100</code> = <code>64₁₆</code>; <code>255</code> = <code>11111111₂</code> = <code>FF₁₆</code>).</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>20</strong></td>\n<td style=\"text-align: left;\"><strong>Linux Pastas</strong></td>\n<td style=\"text-align: left;\"><code>/mkdir</code>, <code>/ls</code>, <code>/rm</code>, <code>/cd</code> são diretórios do Linux.</td>\n<td style=\"text-align: left;\">São <strong>COMANDOS</strong>, não pastas! Pastas reais FHS: <strong><code>/bin, /etc, /home, /lib, /root, /usr, /var, /tmp</code></strong>.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>21</strong></td>\n<td style=\"text-align: left;\"><strong>Contêiner vs VM</strong></td>\n<td style=\"text-align: left;\">Contêiner Docker instala um Kernel completo novo por dentro.</td>\n<td style=\"text-align: left;\">Contêiner <strong>compartilha o Kernel</strong> do hospedeiro (leve); quem virtualiza SO inteiro é <strong>VM + Hypervisor</strong>.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>22</strong></td>\n<td style=\"text-align: left;\"><strong>E-mail</strong></td>\n<td style=\"text-align: left;\">SMTP recebe/sincroniza e IMAP ou POP3 envia.</td>\n<td style=\"text-align: left;\"><strong>SMTP</strong> = <strong>Envia</strong>; <strong>POP3</strong> = Baixa e apaga do servidor; <strong>IMAP</strong> = Sincroniza no servidor.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>23</strong></td>\n<td style=\"text-align: left;\"><strong>Topologias</strong></td>\n<td style=\"text-align: left;\">Na topologia Estrela, romper 1 cabo derruba toda a rede.</td>\n<td style=\"text-align: left;\">Na <strong>Estrela (Switch)</strong> cai só aquele PC; quem derruba tudo ao romper cabo único é <strong>Barramento (<em>Bus</em>)</strong>.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>24</strong></td>\n<td style=\"text-align: left;\"><strong>Português/História</strong></td>\n<td style=\"text-align: left;\">Cultismo = jogo de ideias; Neolítico = nômade sem agricultura.</td>\n<td style=\"text-align: left;\"><strong>Cultismo</strong> = palavras/forma; <strong>Conceptismo</strong> = ideias/lógica; <strong>Neolítico</strong> = agricultura + sedentário; <strong>Paleolítico</strong> = nômade.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>25</strong></td>\n<td style=\"text-align: left;\"><strong>Mat/Quím/Física</strong></td>\n<td style=\"text-align: left;\">Dízima periódica é Irracional; composto iônico conduz sólido; nº de 3 dígitos começa com <code>0</code>.</td>\n<td style=\"text-align: left;\">Dízima é <strong>Racional (<code>ℚ</code>)</strong>; <strong>Metal</strong> conduz sólido, <strong>Iônico</strong> só líquido/aquoso; <code>0</code> proibido na 1ª casa; tomate vermelho sob luz verde parece <strong>PRETO</strong>!</td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h3 id=\"-parte-2--método-cirúrgico-para-questões-i-ii-e-iii--revisão-comentada\">📚 Parte 2 — Método Cirúrgico para Questões I, II e III + Revisão Comentada</h3>\n<h4 id=\"técnica-de-eliminação-em-15-segundos\">Técnica de Eliminação em 15 Segundos</h4>\n<p>Quando enfrentar qualquer questão longa com afirmativas <strong>I, II e III</strong>:</p>\n<ol>\n<li>Leia buscando <strong>palavras absolutas perigosas</strong>: <em>\"sempre\", \"nunca\", \"exclusivamente\", \"unicamente\"</em> — costumam esconder erro!</li>\n<li>Ache <strong>1 único item que você tem 100% de certeza que é FALSO</strong> e risque todas as letras (A–E) que contenham esse número. Na maioria das provas da FAT, eliminar 1 item errado já elimina <strong>3 alternativas de uma vez</strong>, deixando você entre duas!</li>\n<li>Compare apenas o item restante que desempata as duas opções!</li>\n</ol>\n<h4 id=\"️️-3-questões-finais-dissecadas-integrando-tudo\">🕵️‍♂️ 3 Questões Finais Dissecadas (Integrando Tudo)</h4>\n<p><strong>Desafio Final 1 (Estilo Molde 1 — Integração SQL + Web + Redes):</strong> <em>Analise: I. <code>ALTER TABLE usuarios ADD telefone VARCHAR(20)</code> pertence à DDL. II. <code>&lt;a href=\"pagina.html\" target=\"_blank\"&gt;</code> abre o link em uma nova aba, mantendo a atual aberta. III. O protocolo IMAP baixa os e-mails e os apaga imediatamente do servidor remoto para economizar espaço.</em></p>\n<ul>\n<li><strong>Análise:</strong> I é V (ALTER é estrutura = DDL). II é V (<code>_blank</code> = nova aba). <strong>III é F</strong> (quem apaga por padrão após baixar é o <strong>POP3</strong>; IMAP mantém sincronizado no servidor). <strong>Gabarito: I e II corretas.</strong></li>\n</ul>\n<p><strong>Desafio Final 2 (Estilo Molde 4 — Integração Matriz + Lógica + Casting):</strong> <em>Dada <code>M = [[4, 2], [9, 6]]</code> e o código: <code>double media = (M[0][0] + M[1][1]) / 3.0; int final = (int) media;</code>. Qual o valor de <code>final</code> e o nome do processo que gerou <code>final</code>?</em></p>\n<ul>\n<li><strong>Passo a passo:</strong> <code>M[0][0] + M[1][1]</code> (diagonal principal!) = <code>4 + 6 = 10</code>. Divisão real: <code>10 / 3.0 = 3.333...</code>. <code>(int) 3.333...</code> trunca para <strong><code>3</code></strong>, através de <strong>Conversão Explícita (<em>Type Casting</em>)</strong>.</li>\n</ul>\n<p><strong>Desafio Final 3 (Estilo M-Tec Base Comum — Matemática + Química):</strong> <em>Considerando <code>H=1, C=12, O=16</code>, calcule a massa molar de <code>CH₃COOH</code> (<code>C₂H₄O₂</code>) e determine quantos números ímpares de 2 algarismos distintos existem usando <code>{0, 1, 2, 3}</code>.</em></p>\n<ul>\n<li><strong>Química:</strong> <code>C₂H₄O₂</code> = <code>2(12) + 4(1) + 2(16) = 24 + 4 + 32 =</code> <strong><code>60 g/mol</code></strong>.</li>\n<li><strong>Matemática:</strong> Queremos número <strong>ímpar</strong> de 2 dígitos distintos com <code>{0, 1, 2, 3}</code>. Começamos pela restrição mais forte (<strong>unidade</strong> tem que ser ímpar → <code>1</code> ou <code>3</code> = <strong>2 opções</strong>). Depois na <strong>dezena</strong>, não pode <code>0</code> nem o ímpar já gasto na unidade (ex.: se gastou <code>1</code>, sobram <code>{2, 3}</code> = <strong>2 opções</strong>). Total = <code>2 × 2 =</code> <strong><code>4 números</code></strong> (<code>13, 21, 23, 31</code> — batendo exatamente!).</li>\n</ul>\n<hr />\n<h3 id=\"-parte-3--estratégia-de-execução-no-dia-da-prova-sexta-04122026\">📚 Parte 3 — Estratégia de Execução no Dia da Prova (Sexta, 04/12/2026)</h3>\n<ol>\n<li><strong>Regra das 3 Passadas (Gestão de Tempo):</strong>\n<ul>\n<li><strong>1ª Passada (45–60 min) — \"Colheita Rápida\":</strong> Responda primeiro tudo que for definição direta e reconhecimento rápido (Inglês, Ética, SQL sublinguagens, E-mail, Cookies, Cores/Vetor, História/Literatura). Viu teste de mesa grande ou conta longa de geometria? Faça um círculo no número e <strong>pule temporariamente</strong> — todas as questões têm o mesmo peso!</li>\n<li><strong>2ª Passada (60 min) — \"Contas &amp; I-II-III\":</strong> Resolva com calma os <strong>Testes de Mesa</strong>, <strong>Matrizes</strong>, <strong>Binário/Hex</strong>, <strong>Conjuntos</strong>, <strong>Contagem</strong> e <strong>Química</strong>, <strong>sempre escrevendo o passo a passo no rascunho da prova</strong>!</li>\n<li><strong>3ª Passada (últimos 30 min) — \"Conferência &amp; Gabarito\":</strong> Ataque as 2 ou 3 difíceis restantes, preencha o <strong>cartão-resposta</strong> conferindo questão por questão em voz mental baixa (<em>\"Questão 14... letra C!\"</em>) e <strong>nunca deixe nenhuma questão em branco</strong>.</li>\n</ul></li>\n<li><strong>Checklist de Véspera (Quinta, 03/12):</strong>\n<ul>\n<li>Separe <strong>RG/documento oficial original com foto</strong>, comprovante/local de prova, <strong>2 canetas esferográficas pretas/azuis de corpo transparente</strong> e garrafa de água sem rótulo;</li>\n<li>Releia apenas a <strong>Cola de Bolso</strong> (aba <em>Apostila &amp; Cola</em>) por 15 minutos e <strong>durma pelo menos 8 horas</strong> — o cérebro consolida memórias e fica afiado contra pegadinhas quando está descansado. <strong>Você cobriu 100% da prova — confie no seu preparo e arrebente!</strong></li>\n</ul></li>\n</ol>\n"}], "chapters": [{"day": 1, "title": "Moldes FAT, Tipos Primitivos, Casting, DIV/MOD e Tabela Verdade", "weight": "Alta", "storyIntro": "Capítulo 1: Entenda como a Fundação FAT escreve as questões, domine os tipos primitivos, conversão implícita vs. casting, DIV/MOD e Tabela Verdade passo a passo.", "lessonHtml": "<h2 id=\"dia-1--raio-x-da-banca-fundação-fat-memória-ram-tipos-primitivos-casting-divmod-e-lógica-proposicional\">Dia 1 — Raio-X da Banca Fundação FAT, Memória RAM, Tipos Primitivos, Casting, DIV/MOD e Lógica Proposicional</h2>\n<h3 id=\"-contexto-no-mundo-real-por-que-você-precisa-dominar-isso\">🎯 Contexto no Mundo Real: Por que você precisa dominar isso?</h3>\n<p>Imagine que você abre o sistema <strong>NSA da Etec</strong> ou faz um <strong>Pix</strong> no aplicativo do banco. Na tela do Pix aparece: nome do recebedor (<code>\"Maria Oliveira\"</code>), valor (<code>R$ 150.75</code>), chave (<code>11988887777</code>), tipo de conta (<code>'C'</code> para Corrente) e uma pergunta de confirmação (<code>temSaldoSuficiente = verdadeiro</code>).</p>\n<p>Por trás dos panos, o computador <strong>não enxerga \"um recibo de Pix\"</strong> como um humano enxerga. Ele enxerga bilhões de interruptores microscópicos (<code>0</code> e <code>1</code>) na <strong>memória RAM</strong>. Para que o celular não tente \"multiplicar o nome da Maria por 2\" nem apague os centavos <code>0.75</code> na hora de transferir o dinheiro, o programador precisa ensinar à máquina <strong>qual é o formato exato de cada informação</strong> e <strong>como tomar decisões lógicas</strong> com segurança. É exatamente isso que a <strong>Fundação FAT</strong> cobra na abertura das provas de Desenvolvimento de Sistemas!</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Se você já jogou algo online, olhou uma HUD no cantinho da tela ou configurou um bot no Discord, você já usou tudo o que cai no Dia 1 sem nem perceber:</p>\n<ul>\n<li><strong>Os 5 Tipos Primitivos na HUD de um Jogo:</strong>\n<ul>\n<li><code>hp = 100</code> → <strong><code>int</code></strong> (vida inteira, sem vírgula).</li>\n<li><code>kda = 2.45</code> → <strong><code>float</code> / <code>double</code></strong> (taxa de abates/mortes ou precisão com casas decimais).</li>\n<li><code>nick = \"Henrique_BR\"</code> → <strong><code>string</code></strong> (texto completo; se colocar <code>\"100\"</code> entre aspas, vira texto e <strong>não</strong> soma dano!).</li>\n<li><code>rank = 'S'</code> ou <code>time = 'A'</code> → <strong><code>char</code></strong> (uma única letra/símbolo sozinho).</li>\n<li><code>estaVivo = true</code> / <code>mutadoNoDiscord = false</code> → <strong><code>bool</code></strong> (liga/desliga: verdadeiro ou falso).</li>\n</ul></li>\n<li><strong>Casting no XP / Dano (<code>(int) 99.9</code>):</strong> Se o jogo calcula dano crítico <code>99.9</code> e faz <code>(int) dano</code> para exibir na barra inteira, ele <strong>corta o <code>.9</code> fora e mostra <code>99</code></strong> (trunca, não arredonda pra 100!).</li>\n<li><strong><code>DIV</code> e <code>MOD</code> no Minecraft:</strong> Você tem <strong>150 blocos de ferro</strong> e um pack fecha em <strong>64</strong>. Quantos packs cheios dá? <code>150 DIV 64 =</code> <strong><code>2 packs</code></strong>! E quantos blocos ficam soltos no último slot? <code>150 MOD 64 =</code> <strong><code>22 itens</code></strong>!</li>\n<li><strong>Tabela Verdade na Fila Ranqueada:</strong> Regra do servidor para puxar Ranked: <code>(nivel &gt;= 20) E (ping &lt; 60 OU servidor == \"BR\") E NAO estaBanido</code>. Basta você estar banido (<code>NAO true = false</code>) para o <strong><code>E</code></strong> bloquear sua entrada na partida inteira!</li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--os-4-moldes-secretos-da-banca-fundação-fat\">📚 Parte 1 — Os 4 Moldes Secretos da Banca Fundação FAT</h3>\n<p>Antes de estudar os conteúdos técnicos, você precisa conhecer o <strong>estilo da banca examinadora</strong> (Fundação FAT / CPS). Analisando provas oficiais anteriores (DS 2025, Info 2025, DS 2019 e M-Tec 2022), praticamente 100% das questões técnicas caem em apenas <strong>4 moldes previsíveis</strong>:</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Molde da Banca</th>\n<th style=\"text-align: left;\">Como a Questão Aparece</th>\n<th style=\"text-align: left;\">Estratégia de Resolução em Segundos</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Molde 1 — Afirmativas I, II e III</strong></td>\n<td style=\"text-align: left;\">Apresenta 3 frases (frequentemente ligadas a uma tabela de termos) e pergunta quais estão corretas.</td>\n<td style=\"text-align: left;\"><strong>9 em cada 10 vezes</strong>, a banca pega duas definições e <strong>troca uma pela outra</strong> (ex.: diz que DDL faz <code>SELECT</code> e DQL faz <code>CREATE</code>, ou diz que Cookie fica na nuvem). Ache uma falsa e elimine 2 ou 3 alternativas (A–E) logo de cara!</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Molde 2 — Lista com Intruso</strong></td>\n<td style=\"text-align: left;\"><em>\"Assinale a alternativa que apresenta APENAS [frameworks / navegadores / pastas Linux / padrões de cores].\"</em></td>\n<td style=\"text-align: left;\">Todas as 4 alternativas erradas têm <strong>1 único item intruso</strong> escondido no meio de itens verdadeiros (ex.: pôr <code>Creative Commons</code> entre frameworks, ou <code>/mkdir</code> entre diretórios Linux).</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Molde 3 — Definição Direta / Cenário</strong></td>\n<td style=\"text-align: left;\">Descreve um problema real de projeto e pede o termo oficial da engenharia/SQL/rede.</td>\n<td style=\"text-align: left;\">Busque palavras-gatilho no enunciado: <em>\"sem perder nitidez no zoom\"</em> = SVG/Vetor; <em>\"forçada manualmente pelo dev\"</em> = Casting explícito; <em>\"sincroniza no servidor\"</em> = IMAP.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Molde 4 — Micro-Execução (Na Mão)</strong></td>\n<td style=\"text-align: left;\">Mostra 5 a 10 linhas de Portugol/JS/SQL/Binário ou uma Matriz 3×3 e pede a saída final.</td>\n<td style=\"text-align: left;\">Nunca tente fazer de cabeça! Desenhe a tabela de <strong>teste de mesa</strong> no rascunho e acompanhe linha por linha até o fim do laço.</td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h3 id=\"-parte-2--como-variáveis-vivem-na-memória-ram-e-os-5-tipos-primitivos\">📚 Parte 2 — Como Variáveis Vivem na Memória RAM e os 5 Tipos Primitivos</h3>\n<p>Quando um programa está rodando, a <strong>Memória RAM (<em>Random Access Memory</em>)</strong> funciona como um armário gigante cheio de gavetas numeradas (endereços de memória). Criar uma <strong>variável</strong> significa <strong>reservar uma gaveta</strong>, dar a ela um <strong>rótulo (identificador)</strong> — por exemplo <code>idade</code> — e colar nela uma <strong>etiqueta de tipo</strong>.</p>\n<p><strong>Por que a etiqueta de tipo existe?</strong></p>\n<ol>\n<li><strong>Tamanho em bytes:</strong> Um número inteiro comum costuma ocupar 4 bytes (32 bits), enquanto um número decimal de dupla precisão (<code>double</code>) ocupa 8 bytes (64 bits), e um único caractere (<code>char</code>) ocupa apenas 1 ou 2 bytes.</li>\n<li><strong>Significado dos zeros e uns:</strong> A mesma sequência binária na RAM pode significar o número <code>65</code> (se a etiqueta for <code>int</code>) ou a letra <code>'A'</code> na tabela <strong>ASCII</strong> (se a etiqueta for <code>char</code>)!</li>\n<li><strong>Operações permitidas:</strong> Só faz sentido calcular raiz quadrada em números, e só faz sentido transformar em maiúsculas em textos.</li>\n</ol>\n<p>Conheça os <strong>5 Tipos Primitivos Oficiais</strong> exigidos pela Etec:</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Tipo Técnico</th>\n<th style=\"text-align: left;\">Outros nomes na prova</th>\n<th style=\"text-align: left;\">O que armazena na memória</th>\n<th style=\"text-align: left;\">Exemplos válidos</th>\n<th style=\"text-align: left;\">Armadilha comum</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Inteiro (<code>int</code>)</strong></td>\n<td style=\"text-align: left;\"><code>integer</code>, <code>Inteiro</code> (Portugol)</td>\n<td style=\"text-align: left;\">Apenas números sem parte fracionária (positivos, negativos ou <code>0</code>).</td>\n<td style=\"text-align: left;\"><code>0</code>, <code>16</code>, <code>-2026</code>, <code>4096</code></td>\n<td style=\"text-align: left;\">Divisão inteira entre dois <code>int</code> em C/Java (<code>5 / 2</code>) resulta em <strong><code>2</code></strong>, descartando o <code>.5</code>!</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Real (<code>float</code> / <code>double</code>)</strong></td>\n<td style=\"text-align: left;\">Ponto Flutuante, <code>Real</code> (Portugol)</td>\n<td style=\"text-align: left;\">Números com casas decimais (precisão simples <code>float</code> ou dupla <code>double</code>).</td>\n<td style=\"text-align: left;\"><code>3.14</code>, <code>7.5</code>, <code>-0.001</code>, <code>10.0</code></td>\n<td style=\"text-align: left;\">Em programação usa-se <strong>ponto (<code>.</code>)</strong>, nunca vírgula (<code>,</code>). <code>10.0</code> ocupa memória como decimal, mesmo sendo redondo!</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Caractere (<code>char</code>)</strong></td>\n<td style=\"text-align: left;\"><code>Caractere</code> (um único símbolo)</td>\n<td style=\"text-align: left;\"><strong>Exatamente 1 único caractere</strong> (uma letra, um dígito isolado ou um símbolo de pontuação).</td>\n<td style=\"text-align: left;\"><code>'A'</code>, <code>'m'</code>, <code>'7'</code>, <code>'@'</code>, <code>' '</code></td>\n<td style=\"text-align: left;\">Em C/Java vem entre <strong>aspas simples (<code>'A'</code>)</strong>. A banca FAT adora perguntar qual tipo guarda uma alternativa <code>'A'</code>–<code>'E'</code> ou <code>'M'</code>/<code>'F'</code>!</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Texto (<code>string</code>)</strong></td>\n<td style=\"text-align: left;\"><code>Cadeia</code>, <code>Literal</code>, <code>varchar</code> (SQL)</td>\n<td style=\"text-align: left;\">Sequência de <strong>0, 1 ou muitos caracteres</strong> juntos em cadeia.</td>\n<td style=\"text-align: left;\"><code>\"Etec DS\"</code>, <code>\"12345\"</code>, <code>\"\"</code> (vazia)</td>\n<td style=\"text-align: left;\"><code>\"123\"</code> entre aspas é <strong>TEXTO (<code>string</code>)</strong>, NÃO número! Se somar <code>\"10\" + \"20\"</code>, vira <code>\"1020\"</code> (<strong>concatenação</strong>).</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Booleano (<code>bool</code>)</strong></td>\n<td style=\"text-align: left;\"><code>Lógico</code> (Portugol), <code>boolean</code></td>\n<td style=\"text-align: left;\">Exclusivamente dois estados lógicos binários.</td>\n<td style=\"text-align: left;\"><code>true</code> (<code>Verdadeiro</code>) ou <code>false</code> (<code>Falso</code>)</td>\n<td style=\"text-align: left;\">Não usa aspas! <code>\"true\"</code> entre aspas é uma <code>string</code> de 4 letras, não um booleano!</td>\n</tr>\n</tbody>\n</table>\n<div class=\"callout callout-warning\">\n\n<p><strong>Pegadinha clássica da FAT (INFO 2025 Q19):</strong> A questão pergunta qual tipo primitivo armazena adequadamente um caractere isolado (como <code>'S'</code> ou <code>'N'</code>, ou uma letra <code>'B'</code>). Resposta oficial: <strong><code>char</code> / Caractere</strong> (e <strong>NUNCA</strong> <code>boolean</code>, que só guarda <code>true</code>/<code>false</code>, nem <code>float</code>, que guarda decimais!).</p>\n</div>\n\n<hr />\n<h3 id=\"-parte-3--conversão-implícita-coerção-vs-conversão-explícita-type-casting\">📚 Parte 3 — Conversão Implícita (<em>Coerção</em>) vs. Conversão Explícita (<em>Type Casting</em>)</h3>\n<p>Na vida real de um sistema, frequentemente temos um dado em um tipo e precisamos dele em outro. Por exemplo: o usuário digita a idade no formulário HTML (tudo que vem do teclado na web chega como <strong>texto <code>string</code></strong> <code>\"16\"</code>), mas o sistema precisa somar <code>+ 1</code> matematicamente. Como os tipos são convertidos? Existem <strong>dois mecanismos oficiais</strong>:</p>\n<h4 id=\"1-conversão-implícita-coerção-automática\">1. Conversão Implícita (<em>Coerção Automática</em>)</h4>\n<p>Acontece <strong>sozinha nos bastidores</strong>, feita automaticamente pelo compilador ou interpretador <strong>sem que o programador escreva comando de conversão</strong>.</p>\n<ul>\n<li><strong>Regra em linguagens tipadas (C, Java, C#):</strong> Ocorre na <strong>promoção de um tipo menor para um tipo maior</strong>, onde <strong>não existe risco de perder dados</strong>. Um <code>int</code> cabe confortavelmente dentro de um <code>double</code>.\n<ul>\n<li><code>int pontos = 10;</code></li>\n<li><code>double bonus = pontos;</code> → O computador converte <code>10</code> para <code>10.0</code> automaticamente! Ninguém precisou mandar.</li>\n</ul></li>\n<li><strong>Em linguagens dinâmicas (JavaScript):</strong> Se você soma número com string (<code>\"Nota: \" + 9</code>), o JS converte <code>9</code> em <code>\"9\"</code> implicitamente e junta tudo em <code>\"Nota: 9\"</code>.</li>\n</ul>\n<h4 id=\"2-conversão-explícita-type-casting\">2. Conversão Explícita (<em>Type Casting</em>)</h4>\n<p>Acontece quando <strong>o programador escreve explicitamente uma instrução no código forçando a mudança de tipo</strong>. Ela é obrigatória sempre que houver <strong>risco de perda de informação</strong> (por exemplo, transformar um número com casas decimais em inteiro) ou conversão texto ↔︎ número.</p>\n<ul>\n<li><strong>Em C / Java / C#:</strong> Coloca-se o tipo desejado entre parênteses antes da variável: <code>(int) valor</code>.</li>\n<li><strong>Em Python / JavaScript:</strong> Usam-se funções de conversão explícita como <code>int(\"16\")</code>, <code>float(\"7.5\")</code>, <code>Number(\"42\")</code>, <code>parseInt(\"42\")</code>, <code>String(100)</code>.</li>\n</ul>\n<h4 id=\"-exemplo-real-comentado-linha-a-linha-o-perigo-do-truncamento\">💻 Exemplo Real Comentado Linha a Linha (O Perigo do Truncamento!)</h4>\n<p>Veja este trecho clássico estilo prova em C/Java:</p>\n<div class=\"sourceCode\" id=\"cb1\"><pre class=\"sourceCode java\"><code class=\"sourceCode java\"><span id=\"cb1-1\"><a href=\"#cb1-1\" aria-hidden=\"true\"></a><span class=\"dt\">double</span> mediaOriginal = <span class=\"fl\">8.</span><span class=\"dv\">95</span>;          <span class=\"co\">// Linha 1: guarda exatamente 8.95 na RAM (8 bytes)</span></span>\n<span id=\"cb1-2\"><a href=\"#cb1-2\" aria-hidden=\"true\"></a><span class=\"dt\">int</span> notaInteira = (<span class=\"dt\">int</span>) mediaOriginal;<span class=\"co\">// Linha 2: CASTING EXPLÍCITO! O dev forçou virar int</span></span>\n<span id=\"cb1-3\"><a href=\"#cb1-3\" aria-hidden=\"true\"></a><span class=\"dt\">double</span> notaPromovida = notaInteira;   <span class=\"co\">// Linha 3: CONVERSÃO IMPLÍCITA! int -&gt; double automático</span></span>\n<span id=\"cb1-4\"><a href=\"#cb1-4\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-5\"><a href=\"#cb1-5\" aria-hidden=\"true\"></a><span class=\"bu\">System</span>.<span class=\"fu\">out</span>.<span class=\"fu\">println</span>(notaInteira);      <span class=\"co\">// Imprime: 8</span></span>\n<span id=\"cb1-6\"><a href=\"#cb1-6\" aria-hidden=\"true\"></a><span class=\"bu\">System</span>.<span class=\"fu\">out</span>.<span class=\"fu\">println</span>(notaPromovida);    <span class=\"co\">// Imprime: 8.0</span></span></code></pre></div>\n<div class=\"callout callout-caution\">\n\n<p><strong>PEGADINHA MORTAL DA PROVA (DS 2025 Q8):</strong></p>\n<ol>\n<li><code>(int) 8.95</code> <strong>TRUNCA (corta fora)</strong> a parte decimal <code>.95</code>, resultando em <strong><code>8</code></strong>, e <strong>JAMAIS arredonda para <code>9</code></strong>! Mesmo que seja <code>9.999</code>, <code>(int) 9.999</code> vira <strong><code>9</code></strong>.</li>\n<li>A banca inventa nomes falsos como <em>\"Conversão Normal\"</em>, <em>\"Conversão Indireta\"</em> ou <em>\"Conversão Manual Automática\"</em>. Os únicos nomes oficiais são <strong>Implícita</strong> (feita pelo compilador sem perda) e <strong>Explícita / Casting</strong> (forçada pelo programador)!</li>\n</ol>\n</div>\n\n<hr />\n<h3 id=\"-parte-4--operadores-aritméticos-div-quociente-e-mod-resto\">📚 Parte 4 — Operadores Aritméticos, <code>DIV</code> (Quociente) e <code>MOD</code> (Resto)</h3>\n<p>Além das 4 operações tradicionais (<code>+</code>, <code>-</code>, <code>*</code>, <code>/</code>), provas técnicas adoram testar dois irmãos inseparáveis da divisão inteira:</p>\n<ul>\n<li><strong><code>DIV</code> (em Portugol/Pascal) ou <code>//</code> (em Python):</strong> Devolve <strong>apenas a parte inteira do quociente</strong> (quantas vezes o divisor cabe inteiro dentro do dividendo).</li>\n<li><strong><code>MOD</code> (em Portugol/SQL) ou <code>%</code> (em C/Java/JS/Python):</strong> Devolve <strong>apenas o resto inteiro</strong> da divisão que sobrou sem conseguir formar mais um grupo inteiro.</li>\n</ul>\n<h4 id=\"-exemplo-real-1-caixa-eletrônico-distribuindo-notas\">💻 Exemplo Real #1: Caixa Eletrônico Distribuindo Notas</h4>\n<p>Suponha que um estudante saque <strong><code>R$ 137</code></strong> e o caixa tenha notas de <code>R$ 50</code>, <code>R$ 20</code> e moedas de <code>R$ 1</code>:</p>\n<pre class=\"portugol\"><code>valor &lt;- 137\nnotas50 &lt;- valor DIV 50      // 137 / 50 dá 2 e sobra 37 -&gt; notas50 = 2\nsobra   &lt;- valor MOD 50      // O que sobrou após tirar as notas de 50 -&gt; sobra = 37\n\nnotas20 &lt;- sobra DIV 20      // 37 / 20 dá 1 e sobra 17 -&gt; notas20 = 1\nsobra   &lt;- sobra MOD 20      // O resto agora é 17 -&gt; sobra = 17\n</code></pre>\n<h4 id=\"-exemplo-real-2-convertendo-segundos-em-horas-e-minutos-3665-segundos\">💻 Exemplo Real #2: Convertendo Segundos em Horas e Minutos (<code>3665</code> segundos)</h4>\n<ul>\n<li><code>horas &lt;- 3665 DIV 3600</code> → <strong><code>1</code> hora</strong> (<code>1 × 3600 = 3600</code>).</li>\n<li><code>restoSeg &lt;- 3665 MOD 3600</code> → sobram <strong><code>65</code> segundos</strong>.</li>\n<li><code>minutos &lt;- 65 DIV 60</code> → <strong><code>1</code> minuto</strong>.</li>\n<li><code>segFinais &lt;- 65 MOD 60</code> → <strong><code>5</code> segundos</strong>! (<code>01h 01m 05s</code>).</li>\n</ul>\n<h4 id=\"aplicações-favoritas-da-banca-fat-com-mod\">Aplicações Favoritas da Banca FAT com <code>MOD</code>:</h4>\n<ol>\n<li><strong>Teste de Par ou Ímpar:</strong> Todo número par dividido por <code>2</code> deixa resto <code>0</code> (<code>N MOD 2 == 0</code>). Todo ímpar deixa resto <code>1</code> (<code>N MOD 2 == 1</code>).</li>\n<li><strong>Teste de Múltiplo / Ano Bissexto:</strong> <code>numero MOD 5 == 0</code> verifica se é múltiplo de 5.</li>\n<li><strong>Conversão Decimal → Binário (DS 2019 Q2):</strong> Dividir sucessivamente por <code>2</code> pegando <code>n MOD 2</code> (o dígito binário <code>0</code> ou <code>1</code>) e atualizando <code>n &lt;- n DIV 2</code> até <code>n</code> chegar a <code>0</code>!</li>\n</ol>\n<p><strong>Ordem de Precedência Matemática (quem calcula antes de quem):</strong> 1º Parênteses <code>()</code> (de dentro para fora) → 2º Potenciação/Raiz → 3º Multiplicação (<code>*</code>), Divisão (<code>/</code>), <code>DIV</code> e <code>MOD</code> (da esquerda para a direita) → 4º Soma (<code>+</code>) e Subtração (<code>-</code>) → 5º Relacionais (<code>&gt;</code>, <code>&gt;=</code>, <code>&lt;</code>, <code>&lt;=</code>, <code>==</code>, <code>!=</code>) → 6º Lógicos (<code>NÃO</code> → <code>E</code> → <code>OU</code>).</p>\n<hr />\n<h3 id=\"-parte-5--lógica-proposicional-operadores-lógicos-e-tabela-verdade\">📚 Parte 5 — Lógica Proposicional, Operadores Lógicos e Tabela Verdade</h3>\n<p>Uma <strong>proposição lógica</strong> é uma afirmação que pode ser julgada exclusivamente como <strong>Verdadeira (<code>V</code> / <code>true</code>)</strong> ou <strong>Falsa (<code>F</code> / <code>false</code>)</strong>. Conectamos proposições com 3 operadores fundamentais:</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Operador</th>\n<th style=\"text-align: center;\">Símbolo Matemático</th>\n<th style=\"text-align: center;\">Símbolo em Código (C/Java/JS)</th>\n<th style=\"text-align: left;\">Regra de Funcionamento Real</th>\n<th style=\"text-align: left;\">Analogia Prática</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>NÃO (Negação)</strong></td>\n<td style=\"text-align: center;\"><code>¬P</code></td>\n<td style=\"text-align: center;\"><code>!P</code> / <code>not P</code></td>\n<td style=\"text-align: left;\"><strong>Inverte</strong> o valor lógico (<code>V</code> vira <code>F</code>; <code>F</code> vira <code>V</code>).</td>\n<td style=\"text-align: left;\">Interruptor inversor</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>E (Conjunção)</strong></td>\n<td style=\"text-align: center;\"><code>P ∧ Q</code></td>\n<td style=\"text-align: center;\"><code>P &amp;&amp; Q</code> / <code>and</code></td>\n<td style=\"text-align: left;\"><strong>Exigente:</strong> Só resulta em <strong><code>V</code></strong> se <strong>AMBOS</strong> forem <strong><code>V</code></strong>. Um único <code>F</code> derruba tudo para <code>F</code>!</td>\n<td style=\"text-align: left;\"><strong>Porta com 2 cadeados em série:</strong> precisa das <strong>2 chaves</strong> para abrir</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>OU (Disjunção)</strong></td>\n<td style=\"text-align: center;\"><code>P ∨ Q</code></td>\n<td style=\"text-align: center;\"><code>P || Q</code> / <code>or</code></td>\n<td style=\"text-align: left;\"><strong>Flexível:</strong> Resulta em <strong><code>V</code></strong> se <strong>PELO MENOS UM</strong> for <strong><code>V</code></strong>. Só dá <code>F</code> se <strong>TODOS</strong> forem <code>F</code>!</td>\n<td style=\"text-align: left;\"><strong>Casa com 2 portas (frente e fundos):</strong> se pelo menos 1 destrancar, você entra</td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"tabela-verdade-completa-memorize-visualmente\">Tabela Verdade Completa (Memorize visualmente!)</h4>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: center;\"><code>P</code></th>\n<th style=\"text-align: center;\"><code>Q</code></th>\n<th style=\"text-align: center;\"><code>¬P</code> (<code>NÃO P</code>)</th>\n<th style=\"text-align: center;\"><code>P ∧ Q</code> (<code>P E Q</code>)</th>\n<th style=\"text-align: center;\"><code>P ∨ Q</code> (<code>P OU Q</code>)</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>V</strong></td>\n<td style=\"text-align: center;\"><strong>V</strong></td>\n<td style=\"text-align: center;\">F</td>\n<td style=\"text-align: center;\"><strong>V</strong></td>\n<td style=\"text-align: center;\"><strong>V</strong></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>V</strong></td>\n<td style=\"text-align: center;\"><strong>F</strong></td>\n<td style=\"text-align: center;\">F</td>\n<td style=\"text-align: center;\"><strong>F</strong></td>\n<td style=\"text-align: center;\"><strong>V</strong></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>F</strong></td>\n<td style=\"text-align: center;\"><strong>V</strong></td>\n<td style=\"text-align: center;\">V</td>\n<td style=\"text-align: center;\"><strong>F</strong></td>\n<td style=\"text-align: center;\"><strong>V</strong></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>F</strong></td>\n<td style=\"text-align: center;\"><strong>F</strong></td>\n<td style=\"text-align: center;\">V</td>\n<td style=\"text-align: center;\"><strong>F</strong></td>\n<td style=\"text-align: center;\"><strong>F</strong></td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"-exemplo-real-de-regra-de-negócio-na-etec\">💻 Exemplo Real de Regra de Negócio na Etec</h4>\n<p>Para passar direto de ano na Etec sem recuperação, o aluno precisa ter <strong>nota maior ou igual a 6</strong> <strong>E</strong> <strong>não</strong> ter mais que 25% de faltas (<code>faltas &lt;= 25</code>), <strong>OU</strong> ganhar aprovação especial do conselho (<code>conselho == true</code>). Suponha um aluno com <code>nota = 7.5</code>, <code>faltas = 30</code>, <code>conselho = false</code>: Expressão: <code>((nota &gt;= 6) E NAO (faltas &gt; 25)) OU conselho</code></p>\n<ol>\n<li><code>nota &gt;= 6</code> → <code>7.5 &gt;= 6</code> → <strong><code>V</code></strong></li>\n<li><code>faltas &gt; 25</code> → <code>30 &gt; 25</code> → <strong><code>V</code></strong></li>\n<li><code>NAO (faltas &gt; 25)</code> → <code>NAO V</code> → <strong><code>F</code></strong> <em>(lembre: <code>NÃO</code> executa antes do <code>E</code>!)</em></li>\n<li><code>V E F</code> → <strong><code>F</code></strong> <em>(reprovou no critério principal por causa das faltas!)</em></li>\n<li><code>F OU conselho</code> → <code>F OU F</code> → <strong><code>F</code></strong> (Reprovado).</li>\n</ol>\n<div class=\"callout callout-tip\">\n\n<p><strong>Leis de De Morgan (bônus para pegadinhas de negação):</strong></p>\n<ul>\n<li>Negar \"<code>P E Q</code>\" não é \"<code>não P E não Q</code>\"! É <strong><code>(não P) OU (não Q)</code></strong>! <em>(Ex.: negar \"fui à escola E fiz a prova\" significa \"NÃO fui à escola OU NÃO fiz a prova\")</em>.</li>\n<li>Negar \"<code>P OU Q</code>\" resulta em <strong><code>(não P) E (não Q)</code></strong>.</li>\n</ul>\n</div>\n\n<hr />\n<h3 id=\"️️-dissecando-questões-no-estilo-exato-da-prova\">🕵️‍♂️ Dissecando Questões no Estilo Exato da Prova</h3>\n<h4 id=\"questão-resolvida-1-baseada-em-ds-2025-q8--conversão-de-tipos\">Questão Resolvida 1 (Baseada em DS 2025 Q8 — Conversão de Tipos)</h4>\n<p><em>Um desenvolvedor Java escreveu <code>double preco = 49.99; int inteiro = (int) preco;</code> e, em seguida, <code>double copia = inteiro;</code>. Sobre essas operações, avalie:</em></p>\n<ul>\n<li><em>I. Na segunda instrução ocorreu uma conversão implícita com arredondamento para 50.</em></li>\n<li><em>II. Na segunda instrução ocorreu um type casting explícito que truncou o valor para 49.</em></li>\n<li><em>III. Na terceira instrução (<code>double copia = inteiro;</code>) o compilador realizou conversão implícita sem perda de dados.</em></li>\n</ul>\n<p><strong>Análise:</strong></p>\n<ul>\n<li><strong>Item I é FALSO:</strong> Há duas inverdades! Primeiro, <code>(int) preco</code> não é implícita (o dev escreveu <code>(int)</code>, logo é explícita/casting); segundo, <em>casting</em> <strong>trunca</strong> para <code>49</code>, nunca arredonda para <code>50</code>.</li>\n<li><strong>Item II é VERDADEIRO:</strong> <code>(int) preco</code> é explícito (<em>type casting</em>) e descarta a fração <code>.99</code>, deixando <code>49</code>.</li>\n<li><strong>Item III é VERDADEIRO:</strong> Passar <code>int</code> para <code>double</code> amplia a capacidade sem perda; o compilador converte <code>49</code> para <code>49.0</code> automaticamente (implícita). <strong>Resposta:</strong> Apenas <strong>II e III</strong> estão corretas.</li>\n</ul>\n<h4 id=\"questão-resolvida-2-baseada-em-info-2025-q20--ds-2019-q1--tabela-verdade\">Questão Resolvida 2 (Baseada em INFO 2025 Q20 &amp; DS 2019 Q1 — Tabela Verdade)</h4>\n<p><em>Considere <code>P = Verdadeiro</code>, <code>Q = Falso</code> e <code>R = Verdadeiro</code>. Qual é o resultado lógico da expressão <code>(P E Q) OU (NAO Q E R)</code>?</em></p>\n<p><strong>Passo a passo:</strong></p>\n<ol>\n<li>Primeiro os parênteses da esquerda: <code>P E Q</code> = <code>V E F</code> = <strong><code>F</code></strong>.</li>\n<li>Agora o parêntese da direita: <code>NAO Q</code> = <code>NAO F</code> = <strong><code>V</code></strong>. Em seguida <code>V E R</code> = <code>V E V</code> = <strong><code>V</code></strong>.</li>\n<li>Por último o <code>OU</code> externo ligando os dois resultados: <code>F OU V</code> = <strong><code>V</code> (Verdadeiro)</strong>!</li>\n</ol>\n", "practiceType": "lab_tipos", "practiceTag": "00_Moldes_FAT", "videoClips": [{"title": "Variáveis e Tipos Primitivos de Dados", "channel": "Curso em Vídeo • Gustavo Guanabara", "videoId": "N91jAze53uA", "startSec": 65, "endSec": 345, "tip": "Foco: como variáveis ficam na memória RAM e a diferença exata entre inteiro, real, caractere e lógico."}], "challengeRefs": [{"examId": "ds2025", "qNum": 8}, {"examId": "info2025", "qNum": 19}, {"examId": "info2025", "qNum": 20}, {"examId": "ds2019", "qNum": 1}, {"examId": "ds2019", "qNum": 2}, {"examId": "sim1", "qNum": 8}, {"examId": "sim2", "qNum": 1}, {"examId": "sim2", "qNum": 2}, {"examId": "sim2", "qNum": 5}]}, {"day": 2, "title": "Algoritmos, Fluxogramas, Laços de Repetição e Teste de Mesa", "weight": "Máxima", "storyIntro": "Capítulo 2: Aprenda os símbolos oficiais de fluxograma, diferencie while / do-while / for e faça o teste de mesa linha a linha sem cair em pegadinhas.", "lessonHtml": "<h2 id=\"dia-2--algoritmos-fluxogramas-oficiais-decisão-encadeada-laços-de-repetição-e-teste-de-mesa\">Dia 2 — Algoritmos, Fluxogramas Oficiais, Decisão Encadeada, Laços de Repetição e Teste de Mesa</h2>\n<h3 id=\"-contexto-no-mundo-real-o-raciocínio-antes-do-código\">🎯 Contexto no Mundo Real: O Raciocínio Antes do Código</h3>\n<p>Antes de um arquiteto erguer um prédio de 20 andares, ele desenha a planta baixa. Na computação, antes de escrever centenas de linhas de Python, JavaScript ou C#, nós desenhamos a lógica da solução usando um <strong>Algoritmo</strong>.</p>\n<p>Pense no GPS do celular calculando uma rota até a Etec, ou no aplicativo do iFood conferindo se há entregador disponível, aplicando cupom de desconto, somando o frete e repetindo a verificação de estoque para cada item do carrinho. Tudo isso é formado por <strong>sequência, decisão (\"se/senão\") e repetição (\"enquanto houver itens\")</strong>. Se você não dominar a ordem em que a CPU percorre essas linhas, vai cair nas armadilhas do <strong>Teste de Mesa</strong>, que sempre aparece nas provas da Fundação FAT!</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Todo jogo que você abre roda um laço de repetição gigante nos bastidores (o famoso <em><strong>Game Loop</strong></em>):</p>\n<ul>\n<li><strong>Fluxograma = Árvore de Diálogo de RPG / Missão:</strong> O Losango ◇ é aquela encruzilhada de diálogo (<em>\"Você tem a chave da masmorra? Sim → abre o baú / Não → volta para o NPC\"</em>); o Retângulo ▭ é o cálculo de dano; o Paralelogramo ▱ é ler sua tecla <code>WASD</code> e desenhar os frames na tela.</li>\n<li><strong><code>while</code> (Pré-teste) = <code>while (hp &gt; 0)</code>:</strong> Enquanto tiver vida, você continua jogando. Se já entrar na arena com <code>hp == 0</code>, o laço roda <strong>0 vezes</strong> (nem começa!).</li>\n<li><strong><code>do...while</code> (Pós-teste) = Tela de <em>Respawn / Continue?</em>:</strong> Primeiro você vê o menu <em>\"Jogar Novamente? (S/N)\"</em> <strong>pelo menos 1 vez garantida</strong>, e só no final o programa checa se você clicou em Não para sair.</li>\n<li><strong><code>for</code> = Varrer os <em>slots</em> da mochila:</strong> Quando você sabe que o inventário tem exatamente <code>10</code> espaços (<code>i</code> de <code>0</code> até <code>9</code>), usa o <code>para/for</code> para checar item por item.</li>\n<li><strong>Teste de Mesa = Reconstruir uma luta de Boss turno a turno:</strong> Em vez de tentar adivinhar quanto de HP sobrou de cabeça, você anota <code>turno 1</code>, <code>turno 2</code>, <code>turno 3</code> numa tabelinha no papel até o boss cair — impossível errar conta simples assim!</li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--o-que-é-um-algoritmo-e-os-símbolos-do-fluxograma\">📚 Parte 1 — O que é um Algoritmo e os Símbolos do Fluxograma</h3>\n<p>Um <strong>algoritmo</strong> é uma sequência <strong>finita, ordenada e não ambígua</strong> de instruções lógicas para transformar entradas em saídas esperadas. Todo programa segue a tríade clássica <strong>E → P → S</strong>:</p>\n<ol>\n<li><strong>Entrada (<em>Input</em>):</strong> Receber dados externos (teclado, mouse, sensor, banco de dados).</li>\n<li><strong>Processamento (<em>Processing</em>):</strong> Calcular, comparar, ordenar e transformar dados na CPU/RAM.</li>\n<li><strong>Saída (<em>Output</em>):</strong> Devolver o resultado ao usuário ou a outro sistema (tela, impressora, arquivo).</li>\n</ol>\n<p>Podemos escrever um algoritmo de três formas: <strong>Descrição Narrativa</strong> (português comum), <strong>Pseudocódigo / Portugol</strong> (parecido com código) e <strong>Fluxograma</strong> (diagrama gráfico padrão ANSI/ISO).</p>\n<h4 id=\"os-4-símbolos-geométricos-que-a-banca-cobra-literalmente\">Os 4 Símbolos Geométricos que a Banca Cobra Literalmente</h4>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Desenho / Símbolo</th>\n<th style=\"text-align: left;\">Nome Oficial</th>\n<th style=\"text-align: left;\">Função Exata no Fluxograma</th>\n<th style=\"text-align: left;\">Exemplo Real dentro da Caixa</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>⬭ Oval / Elipse / Cápsula</strong></td>\n<td style=\"text-align: left;\"><strong>Terminal</strong></td>\n<td style=\"text-align: left;\">Marca obrigatoriamente apenas o <strong><code>Início</code></strong> e o <strong><code>Fim</code></strong> do algoritmo.</td>\n<td style=\"text-align: left;\"><code>Início</code> ou <code>Fim</code></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>▱ Paralelogramo</strong></td>\n<td style=\"text-align: left;\"><strong>Entrada / Saída (E/S)</strong></td>\n<td style=\"text-align: left;\">Interação externa: <strong>ler</strong> dados do teclado ou <strong>exibir</strong> resultados na tela.</td>\n<td style=\"text-align: left;\"><code>Ler nota1, nota2</code> / <code>Escrever media</code></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>▭ Retângulo</strong></td>\n<td style=\"text-align: left;\"><strong>Processamento</strong></td>\n<td style=\"text-align: left;\"><strong>Contas matemáticas, atribuições de variáveis</strong> e ações internas da máquina.</td>\n<td style=\"text-align: left;\"><code>media &lt;- (nota1 + nota2) / 2</code></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>◇ Losango</strong></td>\n<td style=\"text-align: left;\"><strong>Decisão / Condicional</strong></td>\n<td style=\"text-align: left;\">Avalia uma condição booleana (<code>V</code> ou <code>F</code>). <strong>Sempre tem 1 seta entrando e 2 setas saindo (<code>Sim</code> / <code>Não</code>).</strong></td>\n<td style=\"text-align: left;\"><code>media &gt;= 6.0?</code></td>\n</tr>\n</tbody>\n</table>\n<p><em>(Obs.: Pequenos círculos chamam-se <strong>conectores</strong> e setas indicam o <strong>fluxo de execução</strong>).</em></p>\n<h4 id=\"-exemplo-real-de-fluxograma-completo-aprovação-de-empréstimo\">💻 Exemplo Real de Fluxograma Completo (Aprovação de Empréstimo)</h4>\n<pre class=\"text\"><code>[ ⬭ Início ]\n     ↓\n[ ▱ Ler renda, parcela ]\n     ↓\n[ ▭ limite &lt;- renda * 0.30 ]\n     ↓\n[ ◇ parcela &lt;= limite? ] ──(NÃO)──→ [ ▱ Escrever &quot;Crédito Negado&quot; ] ──┐\n     │ (SIM)                                                           │\n     ↓                                                                 ↓\n[ ▱ Escrever &quot;Crédito Aprovado&quot; ] ────────────────────────────────→ [ ⬭ Fim ]\n</code></pre>\n<div class=\"callout callout-warning\">\n\n<p><strong>Pegadinha clássica:</strong> Nunca marque que <strong>Retângulo</strong> serve para decidir (<code>se/senão</code>), nem que <strong>Losango</strong> faz cálculos (<code>soma = a + b</code>). <strong>Processamento/Atribuição = Retângulo</strong>; <strong>Condicional/Decisão = Losango</strong>; <strong>Ler/Imprimir = Paralelogramo</strong>.</p>\n</div>\n\n<hr />\n<h3 id=\"-parte-2--estruturas-de-decisão-simples-composta-e-encadeada\">📚 Parte 2 — Estruturas de Decisão: Simples, Composta e Encadeada</h3>\n<h4 id=\"1-decisão-simples-se-vs-composta-se--senao\">1. Decisão Simples (<code>se</code>) vs. Composta (<code>se ... senao</code>)</h4>\n<ul>\n<li><strong>Simples:</strong> Executa um bloco apenas se for verdadeiro; se falso, não faz nada e segue em frente (<code>se saldo &lt; 0 entao avisar()</code>).</li>\n<li><strong>Composta:</strong> Oferece dois caminhos excludentes: se <code>V</code>, executa o bloco do <code>se</code>; se <code>F</code>, obrigatoriamente executa o bloco do <code>senao</code>. <strong>Nunca os dois juntos!</strong></li>\n</ul>\n<h4 id=\"2-a-pegadinha-do-encadeamento-se--senao-se-vs-vários-se-seguidos\">2. A Pegadinha do Encadeamento (<code>se ... senao se</code> vs. Vários <code>se</code> Seguidos!)</h4>\n<p>Compare estes dois códigos reais supondo <code>nota = 9.0</code>:</p>\n<p><strong>Código A — Condicional Encadeado (<code>else if</code>):</strong></p>\n<div class=\"sourceCode\" id=\"cb2\"><pre class=\"sourceCode javascript\"><code class=\"sourceCode javascript\"><span id=\"cb2-1\"><a href=\"#cb2-1\" aria-hidden=\"true\"></a><span class=\"cf\">if</span> (nota <span class=\"op\">&gt;=</span> <span class=\"fl\">9.0</span>) {</span>\n<span id=\"cb2-2\"><a href=\"#cb2-2\" aria-hidden=\"true\"></a>    conceito <span class=\"op\">=</span> <span class=\"st\">&quot;MB (Muito Bom)&quot;</span><span class=\"op\">;</span></span>\n<span id=\"cb2-3\"><a href=\"#cb2-3\" aria-hidden=\"true\"></a>} <span class=\"cf\">else</span> <span class=\"cf\">if</span> (nota <span class=\"op\">&gt;=</span> <span class=\"fl\">7.0</span>) {</span>\n<span id=\"cb2-4\"><a href=\"#cb2-4\" aria-hidden=\"true\"></a>    conceito <span class=\"op\">=</span> <span class=\"st\">&quot;B (Bom)&quot;</span><span class=\"op\">;</span></span>\n<span id=\"cb2-5\"><a href=\"#cb2-5\" aria-hidden=\"true\"></a>} <span class=\"cf\">else</span> <span class=\"cf\">if</span> (nota <span class=\"op\">&gt;=</span> <span class=\"fl\">5.0</span>) {</span>\n<span id=\"cb2-6\"><a href=\"#cb2-6\" aria-hidden=\"true\"></a>    conceito <span class=\"op\">=</span> <span class=\"st\">&quot;R (Regular)&quot;</span><span class=\"op\">;</span></span>\n<span id=\"cb2-7\"><a href=\"#cb2-7\" aria-hidden=\"true\"></a>} <span class=\"cf\">else</span> {</span>\n<span id=\"cb2-8\"><a href=\"#cb2-8\" aria-hidden=\"true\"></a>    conceito <span class=\"op\">=</span> <span class=\"st\">&quot;I (Insatisfatório)&quot;</span><span class=\"op\">;</span></span>\n<span id=\"cb2-9\"><a href=\"#cb2-9\" aria-hidden=\"true\"></a>}</span></code></pre></div>\n<p>Como <code>9.0 &gt;= 9.0</code> dá <strong>Verdadeiro</strong> no primeiro <code>if</code>, <code>conceito</code> vira <strong><code>\"MB\"</code></strong> e o programa <strong>PULA</strong> todos os <code>else if</code> abaixo! Mesmo <code>9.0</code> sendo <code>&gt;= 7.0</code> e <code>&gt;= 5.0</code>, eles nem são testados!</p>\n<p><strong>Código B — Múltiplos <code>if</code> Independentes (Erro clássico de iniciante!):</strong></p>\n<div class=\"sourceCode\" id=\"cb3\"><pre class=\"sourceCode javascript\"><code class=\"sourceCode javascript\"><span id=\"cb3-1\"><a href=\"#cb3-1\" aria-hidden=\"true\"></a><span class=\"cf\">if</span> (nota <span class=\"op\">&gt;=</span> <span class=\"fl\">9.0</span>) { conceito <span class=\"op\">=</span> <span class=\"st\">&quot;MB&quot;</span><span class=\"op\">;</span> }   <span class=\"co\">// Testa -&gt; V! conceito = &quot;MB&quot;</span></span>\n<span id=\"cb3-2\"><a href=\"#cb3-2\" aria-hidden=\"true\"></a><span class=\"cf\">if</span> (nota <span class=\"op\">&gt;=</span> <span class=\"fl\">7.0</span>) { conceito <span class=\"op\">=</span> <span class=\"st\">&quot;B&quot;</span><span class=\"op\">;</span> }    <span class=\"co\">// Testa de novo -&gt; V! SOBRESCREVE para &quot;B&quot;!</span></span>\n<span id=\"cb3-3\"><a href=\"#cb3-3\" aria-hidden=\"true\"></a><span class=\"cf\">if</span> (nota <span class=\"op\">&gt;=</span> <span class=\"fl\">5.0</span>) { conceito <span class=\"op\">=</span> <span class=\"st\">&quot;R&quot;</span><span class=\"op\">;</span> }    <span class=\"co\">// Testa de novo -&gt; V! SOBRESCREVE para &quot;R&quot;!</span></span></code></pre></div>\n<p>No Código B, um aluno nota 9 receberia <code>\"R\"</code> porque os três <code>if</code> são independentes e cada um foi apagando a variável! <strong>A banca adora colocar dois ou três <code>if</code> sem <code>else</code> em questões de saída na tela!</strong></p>\n<hr />\n<h3 id=\"-parte-3--estruturas-de-repetição-laços--loops-sem-confusão\">📚 Parte 3 — Estruturas de Repetição (Laços / <em>Loops</em>) Sem Confusão</h3>\n<p>Quase todo laço funcional precisa de <strong>3 pilares</strong> (se esquecer o 3º, o programa trava em <strong>loop infinito</strong>!):</p>\n<ol>\n<li><strong>Inicialização</strong> da variável de controle antes ou no cabeçalho (<code>i &lt;- 1</code>);</li>\n<li><strong>Condição de continuação ou parada</strong> (<code>enquanto i &lt;= 5</code>);</li>\n<li><strong>Atualização / Incremento</strong> dentro do corpo (<code>i &lt;- i + 1</code>).</li>\n</ol>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Estrutura</th>\n<th style=\"text-align: left;\">Momento do Teste</th>\n<th style=\"text-align: center;\">Mínimo de Execuções</th>\n<th style=\"text-align: left;\">Regra Lógica / Idioma</th>\n<th style=\"text-align: left;\">Caso de uso real</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong><code>enquanto ... faca</code> / <code>while</code></strong></td>\n<td style=\"text-align: left;\"><strong>Pré-teste</strong> (testa <strong>antes</strong> de entrar)</td>\n<td style=\"text-align: center;\"><strong>0 vezes</strong> (se já começar falsa, nem entra no bloco!)</td>\n<td style=\"text-align: left;\">Repete <strong>ENQUANTO</strong> a condição for <strong>VERDADEIRA</strong>.</td>\n<td style=\"text-align: left;\">Ler registros enquanto não chegar ao fim do arquivo; validar senha.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong><code>do ... while</code></strong> (C, Java, JS, PHP)</td>\n<td style=\"text-align: left;\"><strong>Pós-teste</strong> (executa primeiro, testa <strong>no final</strong>)</td>\n<td style=\"text-align: center;\"><strong>Pelo menos 1 vez garantida!</strong></td>\n<td style=\"text-align: left;\">Repete <strong>ENQUANTO</strong> a condição final for <strong>VERDADEIRA</strong>.</td>\n<td style=\"text-align: left;\">Menu interativo que precisa aparecer ao menos 1 vez na tela.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong><code>repita ... ate</code></strong> (Portugol / Pascal)</td>\n<td style=\"text-align: left;\"><strong>Pós-teste</strong> (executa primeiro, testa <strong>no final</strong>)</td>\n<td style=\"text-align: center;\"><strong>Pelo menos 1 vez garantida!</strong></td>\n<td style=\"text-align: left;\"><strong>Atenção:</strong> Repete <strong>ATÉ QUE</strong> a condição fique <strong>VERDADEIRA</strong> (ou seja, <strong>repete enquanto for FALSA e PARA quando der <code>V</code></strong>!).</td>\n<td style=\"text-align: left;\">Pedir idade até que digite um valor <code>&gt; 0</code>.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong><code>para ... de ... ate ... faca</code> / <code>for</code></strong></td>\n<td style=\"text-align: left;\"><strong>Pré-teste contado</strong></td>\n<td style=\"text-align: center;\"><strong>0 ou N vezes</strong></td>\n<td style=\"text-align: left;\">Contador automático (<code>inicio</code>, <code>fim</code>, <code>passo</code>).</td>\n<td style=\"text-align: left;\">Percorrer vetores e matrizes de tamanho conhecido.</td>\n</tr>\n</tbody>\n</table>\n<div class=\"callout callout-caution\">\n\n<p><strong>Pegadinha de Ouro (Apostas Q9 &amp; Portugol):</strong></p>\n<ul>\n<li>No <code>while (x &lt; 0)</code>, se <code>x = 5</code>, o bloco roda <strong>0 vezes</strong>.</li>\n<li>No <code>do { ... } while (x &lt; 0)</code>, se <code>x = 5</code>, o bloco roda <strong>1 vez inteira</strong> antes de testar <code>5 &lt; 0</code> e parar!</li>\n<li>E no Portugol <strong><code>repita ... ate (x == 5)</code></strong>: ele <strong>continua</strong> quando <code>x != 5</code> e <strong>sai</strong> quando <code>x</code> vira <code>5</code> (exatamente o inverso do <code>do...while</code>!).</li>\n</ul>\n</div>\n\n<hr />\n<h3 id=\"-parte-4--teste-de-mesa-passo-a-passo-o-método-anti-erro\">📚 Parte 4 — Teste de Mesa Passo a Passo (O Método Anti-Erro)</h3>\n<p><strong>Teste de Mesa</strong> (<em>Trace</em> ou <em>Dry Run</em>) é a técnica de simular o processador manualmente executando cada instrução e preenchendo uma tabela com uma coluna para cada variável e uma coluna para a condição/saída.</p>\n<p><strong>Regras sagradas para fazer no rascunho da prova:</strong></p>\n<ol>\n<li>Nunca confie na memória: <strong>risque</strong> o valor antigo quando uma variável for atualizada (<code>x &lt;- 2</code> → risca o <code>2</code> e escreve <code>4</code>).</li>\n<li>Na troca de valores entre duas variáveis (<code>A</code> e <code>B</code>), é <strong>obrigatório</strong> usar uma 3ª variável auxiliar:\n<ul>\n<li><code>aux &lt;- A; A &lt;- B; B &lt;- aux;</code></li>\n<li>Se fizer <code>A &lt;- B; B &lt;- A;</code> sem <code>aux</code>, o valor original de <code>A</code> é perdido para sempre e ambos ficam iguais a <code>B</code>!</li>\n</ul></li>\n<li>Fique atento ao <strong>último incremento</strong> antes de o laço terminar!</li>\n</ol>\n<h4 id=\"-exemplo-real-comentado-1-acumulador--filtro--contador\">💻 Exemplo Real Comentado #1: Acumulador + Filtro + Contador</h4>\n<p>Veja o algoritmo em Portugol que calcula a soma dos múltiplos de 3 entre 1 e 10 e conta quantos laços foram rodados:</p>\n<pre class=\"portugol\"><code>cont &lt;- 1\nsoma &lt;- 0\nachados &lt;- 0\nenquanto (cont &lt;= 7) faca\n    se (cont MOD 3 == 0) entao\n        soma &lt;- soma + cont\n        achados &lt;- achados + 1\n    fimse\n    cont &lt;- cont + 2\nfimenquanto\nescreva(soma, achados, cont)\n</code></pre>\n<p><strong>Tabela do Teste de Mesa Linha por Linha:</strong></p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Momento / Passo</th>\n<th style=\"text-align: center;\">Teste <code>cont &lt;= 7</code>?</th>\n<th style=\"text-align: center;\">Teste <code>cont MOD 3 == 0</code>?</th>\n<th style=\"text-align: center;\"><code>soma</code></th>\n<th style=\"text-align: center;\"><code>achados</code></th>\n<th style=\"text-align: center;\"><code>cont</code> (após <code>cont + 2</code>)</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Inicialização</strong></td>\n<td style=\"text-align: center;\">—</td>\n<td style=\"text-align: center;\">—</td>\n<td style=\"text-align: center;\"><code>0</code></td>\n<td style=\"text-align: center;\"><code>0</code></td>\n<td style=\"text-align: center;\"><code>1</code></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Volta 1 (<code>cont=1</code>)</strong></td>\n<td style=\"text-align: center;\"><code>1 &lt;= 7</code> (<strong>V</strong> entra)</td>\n<td style=\"text-align: center;\"><code>1 % 3 = 1</code> (<strong>F</strong> pula <code>se</code>)</td>\n<td style=\"text-align: center;\"><code>0</code></td>\n<td style=\"text-align: center;\"><code>0</code></td>\n<td style=\"text-align: center;\"><code>1 + 2 = 3</code></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Volta 2 (<code>cont=3</code>)</strong></td>\n<td style=\"text-align: center;\"><code>3 &lt;= 7</code> (<strong>V</strong> entra)</td>\n<td style=\"text-align: center;\"><code>3 % 3 = 0</code> (<strong>V</strong> entra <code>se</code>!)</td>\n<td style=\"text-align: center;\"><code>0 + 3 = 3</code></td>\n<td style=\"text-align: center;\"><code>1</code></td>\n<td style=\"text-align: center;\"><code>3 + 2 = 5</code></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Volta 3 (<code>cont=5</code>)</strong></td>\n<td style=\"text-align: center;\"><code>5 &lt;= 7</code> (<strong>V</strong> entra)</td>\n<td style=\"text-align: center;\"><code>5 % 3 = 2</code> (<strong>F</strong> pula <code>se</code>)</td>\n<td style=\"text-align: center;\"><code>3</code></td>\n<td style=\"text-align: center;\"><code>1</code></td>\n<td style=\"text-align: center;\"><code>5 + 2 = 7</code></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Volta 4 (<code>cont=7</code>)</strong></td>\n<td style=\"text-align: center;\"><code>7 &lt;= 7</code> (<strong>V</strong> entra)</td>\n<td style=\"text-align: center;\"><code>7 % 3 = 1</code> (<strong>F</strong> pula <code>se</code>)</td>\n<td style=\"text-align: center;\"><code>3</code></td>\n<td style=\"text-align: center;\"><code>1</code></td>\n<td style=\"text-align: center;\"><code>7 + 2 = 9</code></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Volta 5 (<code>cont=9</code>)</strong></td>\n<td style=\"text-align: center;\"><code>9 &lt;= 7</code> (<strong>F</strong> SAI!)</td>\n<td style=\"text-align: center;\"><em>(não executa)</em></td>\n<td style=\"text-align: center;\"><strong><code>3</code></strong></td>\n<td style=\"text-align: center;\"><strong><code>1</code></strong></td>\n<td style=\"text-align: center;\"><strong><code>9</code></strong></td>\n</tr>\n</tbody>\n</table>\n<p><strong>Saída impressa:</strong> <code>soma = 3</code>, <code>achados = 1</code>, <strong><code>cont = 9</code></strong>! Perceba como <code>cont</code> virou <strong><code>9</code></strong> no final da Volta 4 antes de falhar no teste <code>9 &lt;= 7</code>. Quem para no <code>7</code> cai no distrator clássico da banca!</p>\n<h4 id=\"-exemplo-real-comentado-2-teste-de-mesa-com-para-for--variável-auxiliar\">💻 Exemplo Real Comentado #2: Teste de Mesa com <code>para</code> (<em>for</em>) + Variável Auxiliar</h4>\n<div class=\"sourceCode\" id=\"cb5\"><pre class=\"sourceCode javascript\"><code class=\"sourceCode javascript\"><span id=\"cb5-1\"><a href=\"#cb5-1\" aria-hidden=\"true\"></a><span class=\"kw\">let</span> a <span class=\"op\">=</span> <span class=\"dv\">1</span><span class=\"op\">,</span> b <span class=\"op\">=</span> <span class=\"dv\">1</span><span class=\"op\">;</span></span>\n<span id=\"cb5-2\"><a href=\"#cb5-2\" aria-hidden=\"true\"></a><span class=\"cf\">for</span> (<span class=\"kw\">let</span> i <span class=\"op\">=</span> <span class=\"dv\">1</span><span class=\"op\">;</span> i <span class=\"op\">&lt;=</span> <span class=\"dv\">4</span><span class=\"op\">;</span> i<span class=\"op\">++</span>) {</span>\n<span id=\"cb5-3\"><a href=\"#cb5-3\" aria-hidden=\"true\"></a>    <span class=\"kw\">let</span> prox <span class=\"op\">=</span> a <span class=\"op\">+</span> b<span class=\"op\">;</span></span>\n<span id=\"cb5-4\"><a href=\"#cb5-4\" aria-hidden=\"true\"></a>    a <span class=\"op\">=</span> b<span class=\"op\">;</span></span>\n<span id=\"cb5-5\"><a href=\"#cb5-5\" aria-hidden=\"true\"></a>    b <span class=\"op\">=</span> prox<span class=\"op\">;</span></span>\n<span id=\"cb5-6\"><a href=\"#cb5-6\" aria-hidden=\"true\"></a>}</span>\n<span id=\"cb5-7\"><a href=\"#cb5-7\" aria-hidden=\"true\"></a><span class=\"bu\">console</span><span class=\"op\">.</span><span class=\"fu\">log</span>(a<span class=\"op\">,</span> b)<span class=\"op\">;</span></span></code></pre></div>\n<ul>\n<li><strong>Início:</strong> <code>a = 1</code>, <code>b = 1</code></li>\n<li><strong><code>i = 1</code> (<code>1 &lt;= 4</code> V):</strong> <code>prox = 2</code>, <code>a = 1</code>, <code>b = 2</code> → depois <code>i</code> vira <code>2</code></li>\n<li><strong><code>i = 2</code> (<code>2 &lt;= 4</code> V):</strong> <code>prox = 1 + 2 = 3</code>, <code>a = 2</code>, <code>b = 3</code> → <code>i</code> vira <code>3</code></li>\n<li><strong><code>i = 3</code> (<code>3 &lt;= 4</code> V):</strong> <code>prox = 2 + 3 = 5</code>, <code>a = 3</code>, <code>b = 5</code> → <code>i</code> vira <code>4</code></li>\n<li><strong><code>i = 4</code> (<code>4 &lt;= 4</code> V):</strong> <code>prox = 3 + 5 = 8</code>, <code>a = 5</code>, <code>b = 8</code> → <code>i</code> vira <code>5</code> (sai!)</li>\n<li><strong>Saída:</strong> <code>a = 5</code>, <code>b = 8</code> (sequência de Fibonacci!).</li>\n</ul>\n<hr />\n<h3 id=\"️️-dissecando-questões-no-estilo-exato-da-prova\">🕵️‍♂️ Dissecando Questões no Estilo Exato da Prova</h3>\n<h4 id=\"questão-resolvida-1-estilo-molde-4--teste-de-mesa-com-ds-2025-q9\">Questão Resolvida 1 (Estilo Molde 4 — Teste de Mesa com <code>DS 2025 Q9</code>)</h4>\n<p><em>Analise o algoritmo:</em> <code>x &lt;- 10; y &lt;- 4; enquanto (x &gt; y) faca { x &lt;- x - 2; y &lt;- y + 1; } escreva(x, y);</code> <em>Quais valores serão impressos?</em></p>\n<p><strong>Tabela rápida:</strong></p>\n<ul>\n<li>Início: <code>x = 10</code>, <code>y = 4</code>.</li>\n<li>Volta 1: <code>10 &gt; 4</code> (V) → <code>x</code> vira <code>8</code>, <code>y</code> vira <code>5</code>.</li>\n<li>Volta 2: <code>8 &gt; 5</code> (V) → <code>x</code> vira <code>6</code>, <code>y</code> vira <code>6</code>.</li>\n<li>Volta 3: <code>6 &gt; 6</code> (<strong>F!</strong> Pois é estritamente <code>&gt;</code>, não <code>&gt;=</code>!) → <strong>SAI DO LAÇO!</strong> <strong>Gabarito:</strong> Imprime <strong><code>x = 6</code> e <code>y = 6</code></strong>. <em>(Pegadinha: muita gente acha que <code>6 &gt; 6</code> ainda entra e marca <code>x = 4, y = 7</code>!).</em></li>\n</ul>\n<h4 id=\"questão-resolvida-2-estilo-molde-1--símbolos-de-fluxograma--laços\">Questão Resolvida 2 (Estilo Molde 1 — Símbolos de Fluxograma &amp; Laços)</h4>\n<p><em>Julgue os itens:</em></p>\n<ul>\n<li><em>I. No fluxograma padrão, o retângulo representa entrada e saída de dados via teclado/tela.</em></li>\n<li><em>II. A estrutura <code>do...while</code> garante que o bloco interno será executado pelo menos uma vez, pois o teste ocorre ao final.</em></li>\n<li><em>III. Se a condição inicial de um laço <code>while</code> for falsa desde a primeira leitura, suas instruções internas nunca serão executadas.</em></li>\n</ul>\n<p><strong>Análise:</strong></p>\n<ul>\n<li><strong>Item I é FALSO:</strong> Entrada e saída usam o <strong>paralelogramo</strong>; o retângulo representa <strong>processamento/atribuições</strong>.</li>\n<li><strong>Item II é VERDADEIRO:</strong> Pós-teste sempre roda ao menos 1 vez.</li>\n<li><strong>Item III é VERDADEIRO:</strong> Pré-teste barra na entrada se já nascer falso. <strong>Gabarito:</strong> Apenas <strong>II e III</strong>.</li>\n</ul>\n", "practiceType": "lab02", "practiceTag": "01_Programacao", "videoClips": [{"title": "Estruturas de Repetição 1: Enquanto (While)", "channel": "Curso em Vídeo • Gustavo Guanabara", "videoId": "U5PnCt58Q68", "startSec": 150, "endSec": 510, "tip": "Foco: fluxograma de repetição pré-teste e rastreamento passo a passo (Teste de Mesa)."}, {"title": "Estruturas de Repetição 2: Repita... Até (Do-While)", "channel": "Curso em Vídeo • Gustavo Guanabara", "videoId": "fP49L1i_-HU", "startSec": 100, "endSec": 390, "tip": "Foco: diferença entre testar a condição no início vs. testar no final (executa pelo menos 1 vez)."}], "challengeRefs": [{"examId": "ds2025", "qNum": 9}, {"examId": "ds2025", "qNum": 10}, {"examId": "apostas", "qNum": 7}, {"examId": "apostas", "qNum": 8}, {"examId": "apostas", "qNum": 9}, {"examId": "apostas", "qNum": 10}, {"examId": "sim1", "qNum": 9}, {"examId": "sim1", "qNum": 10}]}, {"day": 3, "title": "Vetores, Matrizes [i][j], Pilha (LIFO) e Recursividade", "weight": "Máxima", "storyIntro": "Capítulo 3: Domine índices base 0, soma da diagonal principal vs. secundária, Pilha LIFO (PUSH/POP) vs. Fila FIFO e fatorial recursivo.", "lessonHtml": "<h2 id=\"dia-3--vetores-1d-matrizes-bidimensionais-ij-pilha-lifo-fila-fifo-e-recursividade\">Dia 3 — Vetores (1D), Matrizes Bidimensionais <code>[i][j]</code>, Pilha (LIFO), Fila (FIFO) e Recursividade</h2>\n<h3 id=\"-contexto-no-mundo-real-tabuleiros-carrinhos-e-a-pilha-do-ctrlz\">🎯 Contexto no Mundo Real: Tabuleiros, Carrinhos e a Pilha do \"Ctrl+Z\"</h3>\n<p>Imagine fazer um sistema para guardar as 40 notas de uma turma da Etec criando 40 variáveis chamadas <code>nota1</code>, <code>nota2</code>, ..., <code>nota40</code>. Além de trabalhoso, seria impossível usar um laço <code>for</code> para calcular a média! Ou imagine representar uma planilha do Excel, uma imagem digital em pixels ou o tabuleiro de um jogo da velha <code>3 × 3</code>. Para isso existem as <strong>estruturas de dados indexadas homogêneas</strong> (Vetores e Matrizes), capazes de armazenar dezenas ou milhões de valores sob um único nome na memória.</p>\n<p>Além delas, softwares reais dependem de regras rígidas sobre <strong>quem sai primeiro</strong>: quando você aperta <strong><code>Ctrl+Z</code></strong> no VS Code ou clica em <strong>Voltar</strong> no navegador, o sistema desfaz a <strong>última</strong> ação que você fez (uma <strong>Pilha</strong>). Já quando cinco pessoas mandam imprimir PDFs na impressora da escola, quem enviou <strong>primeiro</strong> imprime <strong>primeiro</strong> (uma <strong>Fila</strong>). Ambas caem com enorme frequência nas provas da FAT!</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Você já usa vetores, matrizes, filas e pilhas toda vez que abre o PC:</p>\n<ul>\n<li><strong>Vetor 1D (Base <code>0</code>) = Barra de Atalhos (<em>Hotbar</em>) numerada no inventário:</strong> Imagine 5 slots chamados <code>hotbar</code>: em programação, o primeiro slot é <code>hotbar[0]</code> (Espada), depois <code>[1]</code> (Arco), <code>[2]</code> (Picareta), <code>[3]</code> (Bloco) e o último é <code>hotbar[4]</code> (Poção). Se tentar acessar <code>hotbar[5]</code>, dá erro porque foi de <code>0</code> a <code>N-1</code>!</li>\n<li><strong>Matriz 2D <code>M[linha][coluna]</code> = Minimapa / Tabuleiro / Inventário em Grade:</strong> Cada quadradinho tem 2 coordenadas: primeiro qual <strong>fileira de cima pra baixo (<code>i</code>)</strong>, depois qual <strong>coluna da esquerda pra direita (<code>j</code>)</strong>. Na <strong>Diagonal Principal (<code>i == j</code>)</strong>, você anda na diagonal certinha <code>[0][0] → [1][1] → [2][2]</code>.</li>\n<li><strong>Fila (<code>FIFO</code>) vs. Pilha (<code>LIFO</code>) no Discord e no Matchmaking:</strong>\n<ul>\n<li><strong>Fila (<code>FIFO</code> — <em>First In, First Out</em>):</strong> É a <strong>fila do Matchmaking</strong> no Valorant/LoL/CS2 — o primeiro squad que clicou em \"Jogar\" é o primeiro que o servidor coloca na sala.</li>\n<li><strong>Pilha (<code>LIFO</code> — <em>Last In, First Out</em>):</strong> É o <strong><code>Ctrl+Z</code></strong> ou a pilha de <em>buffs/menus</em> abertos — se você abriu <code>Configurações → Áudio → Microfone</code>, ao apertar <code>ESC</code> você fecha <strong>o último menu que abriu (<code>Microfone</code>)</strong> primeiro!</li>\n</ul></li>\n<li><strong>Recursividade = Boneca Russa / <em>Call Stack</em>:</strong> Uma função que chama uma versão menor dela mesma até bater no <strong>Caso Base</strong> (o momento em que ela para de chamar e devolve os resultados de volta!).</li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--vetores-arrays-1d-e-indexação-base-zero\">📚 Parte 1 — Vetores (Arrays 1D) e Indexação Base Zero</h3>\n<p>Um <strong>vetor</strong> (<em>array</em> unidimensional) é uma estrutura composta <strong>homogênea</strong> — todas as posições guardam dados do <strong>mesmo tipo</strong> (ex.: só inteiros ou só strings) — disposta em posições contíguas na memória RAM e acessada por um <strong>índice numérico</strong>.</p>\n<h4 id=\"a-regra-de-ouro-dos-índices-base-0\">A Regra de Ouro dos Índices (Base <code>0</code>)</h4>\n<p>Em C, C++, Java, JavaScript, Python e PHP, a contagem das gavetas <strong>começa no índice <code>0</code></strong>, e <strong>NÃO no <code>1</code>!</strong> Logo, um vetor <code>notas</code> de tamanho <code>N = 5</code>:</p>\n<ul>\n<li>Possui índices válidos <strong><code>0, 1, 2, 3, 4</code></strong> (isto é, de <strong><code>0</code> até <code>N - 1</code></strong>!).</li>\n<li>Visualização na memória:</li>\n</ul>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Índice</th>\n<th style=\"text-align: center;\"><code>notas[0]</code></th>\n<th style=\"text-align: center;\"><code>notas[1]</code></th>\n<th style=\"text-align: center;\"><code>notas[2]</code></th>\n<th style=\"text-align: center;\"><code>notas[3]</code></th>\n<th style=\"text-align: center;\"><code>notas[4]</code></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Valor armazenado</strong></td>\n<td style=\"text-align: center;\"><code>8.5</code></td>\n<td style=\"text-align: center;\"><code>6.0</code></td>\n<td style=\"text-align: center;\"><code>9.0</code></td>\n<td style=\"text-align: center;\"><code>7.5</code></td>\n<td style=\"text-align: center;\"><code>10.0</code></td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li>Quanto vale <code>notas[2]</code>? Vale <strong><code>9.0</code></strong> (é o <strong>3º</strong> elemento, não o 2º!).</li>\n<li>O que acontece se você tentar acessar <code>notas[5]</code>? <strong>Erro fatal (<em>Index Out of Bounds</em> / estouro de limite)</strong> porque só vai até <code>4</code>!</li>\n</ul>\n<h4 id=\"-exemplo-real-comentado-varredura-com-laço-for-apostas-q10\">💻 Exemplo Real Comentado: Varredura com Laço <code>for</code> (Apostas Q10)</h4>\n<div class=\"sourceCode\" id=\"cb1\"><pre class=\"sourceCode javascript\"><code class=\"sourceCode javascript\"><span id=\"cb1-1\"><a href=\"#cb1-1\" aria-hidden=\"true\"></a><span class=\"kw\">let</span> v <span class=\"op\">=</span> [<span class=\"dv\">10</span><span class=\"op\">,</span> <span class=\"dv\">15</span><span class=\"op\">,</span> <span class=\"dv\">20</span><span class=\"op\">,</span> <span class=\"dv\">25</span>]<span class=\"op\">;</span></span>\n<span id=\"cb1-2\"><a href=\"#cb1-2\" aria-hidden=\"true\"></a><span class=\"kw\">let</span> soma <span class=\"op\">=</span> <span class=\"dv\">0</span><span class=\"op\">;</span></span>\n<span id=\"cb1-3\"><a href=\"#cb1-3\" aria-hidden=\"true\"></a><span class=\"cf\">for</span> (<span class=\"kw\">let</span> i <span class=\"op\">=</span> <span class=\"dv\">0</span><span class=\"op\">;</span> i <span class=\"op\">&lt;</span> v<span class=\"op\">.</span><span class=\"at\">length</span><span class=\"op\">;</span> i<span class=\"op\">++</span>) {</span>\n<span id=\"cb1-4\"><a href=\"#cb1-4\" aria-hidden=\"true\"></a>    <span class=\"cf\">if</span> (v[i] <span class=\"op\">%</span> <span class=\"dv\">2</span> <span class=\"op\">===</span> <span class=\"dv\">0</span>) {</span>\n<span id=\"cb1-5\"><a href=\"#cb1-5\" aria-hidden=\"true\"></a>        soma <span class=\"op\">=</span> soma <span class=\"op\">+</span> v[i]<span class=\"op\">;</span></span>\n<span id=\"cb1-6\"><a href=\"#cb1-6\" aria-hidden=\"true\"></a>    }</span>\n<span id=\"cb1-7\"><a href=\"#cb1-7\" aria-hidden=\"true\"></a>}</span>\n<span id=\"cb1-8\"><a href=\"#cb1-8\" aria-hidden=\"true\"></a><span class=\"co\">// i=0: v[0]=10 (par!) -&gt; soma = 10</span></span>\n<span id=\"cb1-9\"><a href=\"#cb1-9\" aria-hidden=\"true\"></a><span class=\"co\">// i=1: v[1]=15 (ímpar, ignora)</span></span>\n<span id=\"cb1-10\"><a href=\"#cb1-10\" aria-hidden=\"true\"></a><span class=\"co\">// i=2: v[2]=20 (par!) -&gt; soma = 30</span></span>\n<span id=\"cb1-11\"><a href=\"#cb1-11\" aria-hidden=\"true\"></a><span class=\"co\">// i=3: v[3]=25 (ímpar, ignora)</span></span>\n<span id=\"cb1-12\"><a href=\"#cb1-12\" aria-hidden=\"true\"></a><span class=\"co\">// Resultado final: soma = 30</span></span></code></pre></div>\n<div class=\"callout callout-warning\">\n\n<p><strong>Pegadinha de linguagem:</strong> Algumas provas em <strong>Portugol acadêmico (VisuAlg)</strong> declaram explicitamente <code>vetor[1..5] de inteiro</code> (começando em <code>1</code>). Leia sempre o cabeçalho da questão! Se estiver em JS, C, Java, Python ou PHP — ou se não disser <code>1..N</code> — a indexação começa obrigatoriamente em <strong><code>0</code></strong>.</p>\n</div>\n\n<hr />\n<h3 id=\"-parte-2--matrizes-bidimensionais-mij-e-diagonais\">📚 Parte 2 — Matrizes Bidimensionais (<code>M[i][j]</code>) e Diagonais</h3>\n<p>Uma <strong>matriz bidimensional</strong> é um \"vetor de vetores\" organizado como uma tabela de <strong>linhas (<code>i</code>)</strong> e <strong>colunas (<code>j</code>)</strong>. Convenção universal em computação: <strong><code>M[i][j]</code></strong> lê-se <strong>PRIMEIRO a linha <code>i</code></strong>, <strong>DEPOIS a coluna <code>j</code></strong>!</p>\n<p>Considere esta <strong>Matriz <code>M</code> de ordem <code>3 × 3</code></strong> (3 linhas e 3 colunas, base <code>0</code>):</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: center;\"><code>Linha (i) \\ Coluna (j)</code></th>\n<th style=\"text-align: center;\">Coluna <code>j = 0</code></th>\n<th style=\"text-align: center;\">Coluna <code>j = 1</code></th>\n<th style=\"text-align: center;\">Coluna <code>j = 2</code></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>Linha <code>i = 0</code></strong></td>\n<td style=\"text-align: center;\"><strong><code>5</code></strong> (<code>[0][0]</code>)</td>\n<td style=\"text-align: center;\"><code>8</code> (<code>[0][1]</code>)</td>\n<td style=\"text-align: center;\"><strong><code>2</code></strong> (<code>[0][2]</code>)</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>Linha <code>i = 1</code></strong></td>\n<td style=\"text-align: center;\"><code>4</code> (<code>[1][0]</code>)</td>\n<td style=\"text-align: center;\"><strong><code>7</code></strong> (<code>[1][1]</code>)</td>\n<td style=\"text-align: center;\"><code>9</code> (<code>[1][2]</code>)</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>Linha <code>i = 2</code></strong></td>\n<td style=\"text-align: center;\"><strong><code>6</code></strong> (<code>[2][0]</code>)</td>\n<td style=\"text-align: center;\"><code>1</code> (<code>[2][1]</code>)</td>\n<td style=\"text-align: center;\"><strong><code>3</code></strong> (<code>[2][2]</code>)</td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"as-4-regiões-clássicas-da-matriz-quadrada-de-ordem-n-aqui-n--3\">As 4 Regiões Clássicas da Matriz Quadrada de Ordem <code>N</code> (aqui <code>N = 3</code>)</h4>\n<ol>\n<li><strong>Diagonal Principal:</strong> Formada pelos elementos que descem do <strong>canto superior esquerdo ao canto inferior direito</strong>.\n<ul>\n<li><strong>Condição matemática exata:</strong> <strong><code>i == j</code></strong> (índice da linha igual ao da coluna!).</li>\n<li>Na matriz acima: <code>M[0][0] = 5</code>, <code>M[1][1] = 7</code>, <code>M[2][2] = 3</code>.</li>\n<li><strong>Soma da Diagonal Principal</strong> = <code>5 + 7 + 3 =</code> <strong><code>15</code></strong>.</li>\n</ul></li>\n<li><strong>Diagonal Secundária:</strong> Formada pelos elementos que descem do <strong>canto superior direito ao canto inferior esquerdo</strong>.\n<ul>\n<li><strong>Condição matemática exata:</strong> <strong><code>i + j == N - 1</code></strong> (aqui <code>i + j == 2</code>!).</li>\n<li>Na matriz acima: <code>M[0][2] = 2</code> (<code>0+2=2</code>), <code>M[1][1] = 7</code> (<code>1+1=2</code>), <code>M[2][0] = 6</code> (<code>2+0=2</code>).</li>\n<li><strong>Soma da Diagonal Secundária</strong> = <code>2 + 7 + 6 = 15</code>. <em>(Note que em DS 2025 Q10 a matriz tinha diagonais com valores diferentes justamente para pegar quem confundiu principal com secundária!)</em></li>\n</ul></li>\n<li><strong>Acima da Diagonal Principal:</strong> <code>j &gt; i</code> (<code>M[0][1], M[0][2], M[1][2]</code>).</li>\n<li><strong>Abaixo da Diagonal Principal:</strong> <code>i &gt; j</code> (<code>M[1][0], M[2][0], M[2][1]</code>).</li>\n</ol>\n<h4 id=\"-exemplo-real-comentado-laço-aninhado-for-dentro-de-for\">💻 Exemplo Real Comentado: Laço Aninhado (<code>for</code> dentro de <code>for</code>)</h4>\n<p>Observe como dois laços percorrem uma matriz inteira somando <strong>apenas</strong> a diagonal principal:</p>\n<div class=\"sourceCode\" id=\"cb2\"><pre class=\"sourceCode python\"><code class=\"sourceCode python\"><span id=\"cb2-1\"><a href=\"#cb2-1\" aria-hidden=\"true\"></a>M <span class=\"op\">=</span> [</span>\n<span id=\"cb2-2\"><a href=\"#cb2-2\" aria-hidden=\"true\"></a>    [<span class=\"dv\">1</span>, <span class=\"dv\">3</span>, <span class=\"dv\">5</span>],   <span class=\"co\"># linha i = 0</span></span>\n<span id=\"cb2-3\"><a href=\"#cb2-3\" aria-hidden=\"true\"></a>    [<span class=\"dv\">2</span>, <span class=\"dv\">4</span>, <span class=\"dv\">8</span>],   <span class=\"co\"># linha i = 1</span></span>\n<span id=\"cb2-4\"><a href=\"#cb2-4\" aria-hidden=\"true\"></a>    [<span class=\"dv\">1</span>, <span class=\"dv\">1</span>, <span class=\"dv\">1</span>]    <span class=\"co\"># linha i = 2</span></span>\n<span id=\"cb2-5\"><a href=\"#cb2-5\" aria-hidden=\"true\"></a>]</span>\n<span id=\"cb2-6\"><a href=\"#cb2-6\" aria-hidden=\"true\"></a>soma_dp <span class=\"op\">=</span> <span class=\"dv\">0</span></span>\n<span id=\"cb2-7\"><a href=\"#cb2-7\" aria-hidden=\"true\"></a><span class=\"cf\">for</span> i <span class=\"kw\">in</span> <span class=\"bu\">range</span>(<span class=\"dv\">3</span>):          <span class=\"co\"># i assume 0, 1, 2</span></span>\n<span id=\"cb2-8\"><a href=\"#cb2-8\" aria-hidden=\"true\"></a>    <span class=\"cf\">for</span> j <span class=\"kw\">in</span> <span class=\"bu\">range</span>(<span class=\"dv\">3</span>):      <span class=\"co\"># para cada i, j assume 0, 1, 2</span></span>\n<span id=\"cb2-9\"><a href=\"#cb2-9\" aria-hidden=\"true\"></a>        <span class=\"cf\">if</span> i <span class=\"op\">==</span> j:          <span class=\"co\"># só entra em [0][0], [1][1], [2][2]</span></span>\n<span id=\"cb2-10\"><a href=\"#cb2-10\" aria-hidden=\"true\"></a>            soma_dp <span class=\"op\">+=</span> M[i][j]</span>\n<span id=\"cb2-11\"><a href=\"#cb2-11\" aria-hidden=\"true\"></a></span>\n<span id=\"cb2-12\"><a href=\"#cb2-12\" aria-hidden=\"true\"></a><span class=\"bu\">print</span>(soma_dp)  <span class=\"co\"># 1 + 4 + 1 = 6!</span></span></code></pre></div>\n<div class=\"callout callout-caution\">\n\n<p><strong>Pegadinha da DS 2025 Q10:</strong> A banca perguntou a soma da <strong>diagonal principal</strong> da matriz <code>[[1,3,5],[2,4,8],[1,1,1]]</code> e colocou <strong><code>10</code></strong> nas alternativas (que é a soma da diagonal <strong>secundária</strong>: <code>5 + 4 + 1 = 10</code>). Desenhe sempre os índices <code>[0][0]</code>, <code>[1][1]</code>, <code>[2][2]</code> no rascunho antes de somar!</p>\n</div>\n\n<hr />\n<h3 id=\"-parte-3--estruturas-lineares-pilha-lifo-vs-fila-fifo\">📚 Parte 3 — Estruturas Lineares: Pilha (LIFO) vs. Fila (FIFO)</h3>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Critério</th>\n<th style=\"text-align: left;\">Pilha (<em>Stack</em>)</th>\n<th style=\"text-align: left;\">Fila (<em>Queue</em>)</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Princípio Oficial</strong></td>\n<td style=\"text-align: left;\"><strong>LIFO</strong> (<em>Last In, First Out</em> — <strong>Último</strong> a entrar, <strong>Primeiro</strong> a sair) ou <strong>FILO</strong></td>\n<td style=\"text-align: left;\"><strong>FIFO</strong> (<em>First In, First Out</em> — <strong>Primeiro</strong> a entrar, <strong>Primeiro</strong> a sair)</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Operação de Inserção</strong></td>\n<td style=\"text-align: left;\"><strong><code>PUSH</code></strong> (empilha no <strong>topo</strong>)</td>\n<td style=\"text-align: left;\"><strong><code>Enqueue</code></strong> / Inserir (entra no <strong>fim/cauda</strong>)</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Operação de Remoção</strong></td>\n<td style=\"text-align: left;\"><strong><code>POP</code></strong> (remove sempre do <strong>topo</strong>)</td>\n<td style=\"text-align: left;\"><strong><code>Dequeue</code></strong> / Remover (sai sempre da <strong>frente/cabeça</strong>)</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Exemplos Reais em TI</strong></td>\n<td style=\"text-align: left;\">Botão <strong>Voltar</strong> do navegador, <strong>Desfazer (<code>Ctrl+Z</code>)</strong>, <strong>Pilha de Chamadas (<em>Call Stack</em>)</strong> de funções</td>\n<td style=\"text-align: left;\"><strong>Fila de impressão (<em>Spooler</em>)</strong>, <strong>fila de mensagens/tickets</strong>, buffer de teclado</td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"-rastreamento-completo-de-pilha-baseado-em-ds-2019-q3\">💻 Rastreamento Completo de Pilha (Baseado em DS 2019 Q3)</h4>\n<p>Partindo de uma pilha vazia, execute:</p>\n<ol>\n<li><code>push(\"A\")</code> → Pilha: <code>[\"A\"]</code> <em>(Topo = A)</em></li>\n<li><code>push(\"B\")</code> → Pilha: <code>[\"A\", \"B\"]</code> <em>(Topo = B)</em></li>\n<li><code>push(\"C\")</code> → Pilha: <code>[\"A\", \"B\", \"C\"]</code> <em>(Topo = C)</em></li>\n<li><code>pop()</code> → Remove o <strong>último que entrou (<code>C</code>)</strong>! Sobra <code>[\"A\", \"B\"]</code> <em>(Topo = B)</em></li>\n<li><code>push(\"D\")</code> → Entra no topo: <code>[\"A\", \"B\", \"D\"]</code> <em>(Topo = D)</em></li>\n<li><code>pop()</code> → Remove o topo (<code>D</code>): Sobra <code>[\"A\", \"B\"]</code> <em>(Topo = B, Base = A)</em>.</li>\n</ol>\n<hr />\n<h3 id=\"-parte-4--funções-parâmetros-e-recursividade\">📚 Parte 4 — Funções, Parâmetros e Recursividade</h3>\n<p>Uma <strong>função</strong> (ou sub-rotina) é um bloco de código reutilizável com um nome que recebe <strong>parâmetros</strong> de entrada e devolve um valor (<code>return</code>). Uma função é chamada <strong>recursiva</strong> quando ela <strong>chama a si mesma dentro do próprio corpo</strong>, reduzindo um problema grande a versões menores dele mesmo.</p>\n<p>Toda função recursiva bem escrita possui <strong>duas partes obrigatórias</strong>:</p>\n<ol>\n<li><strong>Caso Base (Critério de Parada):</strong> A versão mais simples que tem resposta direta sem chamar a função novamente. <em>(Sem caso base, ocorre recursão infinita até estourar a memória RAM: erro <strong><code>Stack Overflow</code></strong>!)</em></li>\n<li><strong>Passo Recursivo:</strong> A função chama a si mesma aproximando o argumento do Caso Base.</li>\n</ol>\n<h4 id=\"-exemplo-real-comentado-fatorial-recursivo-fatorial4-info-2025-q21\">💻 Exemplo Real Comentado: Fatorial Recursivo <code>fatorial(4)</code> (INFO 2025 Q21)</h4>\n<p>Definição matemática: <strong><code>0! = 1</code></strong> e <strong><code>n! = n × (n - 1)!</code></strong>.</p>\n<div class=\"sourceCode\" id=\"cb3\"><pre class=\"sourceCode javascript\"><code class=\"sourceCode javascript\"><span id=\"cb3-1\"><a href=\"#cb3-1\" aria-hidden=\"true\"></a><span class=\"kw\">function</span> <span class=\"fu\">fat</span>(n) {</span>\n<span id=\"cb3-2\"><a href=\"#cb3-2\" aria-hidden=\"true\"></a>    <span class=\"cf\">if</span> (n <span class=\"op\">&lt;=</span> <span class=\"dv\">1</span>) <span class=\"cf\">return</span> <span class=\"dv\">1</span><span class=\"op\">;</span>        <span class=\"co\">// CASO BASE (0! = 1 e 1! = 1)</span></span>\n<span id=\"cb3-3\"><a href=\"#cb3-3\" aria-hidden=\"true\"></a>    <span class=\"cf\">return</span> n <span class=\"op\">*</span> <span class=\"fu\">fat</span>(n <span class=\"op\">-</span> <span class=\"dv\">1</span>)<span class=\"op\">;</span>       <span class=\"co\">// PASSO RECURSIVO (empilha chamadas na Call Stack!)</span></span>\n<span id=\"cb3-4\"><a href=\"#cb3-4\" aria-hidden=\"true\"></a>}</span>\n<span id=\"cb3-5\"><a href=\"#cb3-5\" aria-hidden=\"true\"></a><span class=\"bu\">console</span><span class=\"op\">.</span><span class=\"fu\">log</span>(<span class=\"fu\">fat</span>(<span class=\"dv\">4</span>))<span class=\"op\">;</span></span></code></pre></div>\n<p><strong>Como a Pilha de Chamadas (<em>Call Stack</em>) da CPU executa <code>fat(4)</code> (LIFO na veia!):</strong></p>\n<ul>\n<li><strong>Descida (empilhando <em>PUSH</em>):</strong>\n<ol>\n<li><code>fat(4)</code> precisa saber <code>4 * fat(3)</code> → pausa e chama <code>fat(3)</code></li>\n<li><code>fat(3)</code> precisa saber <code>3 * fat(2)</code> → pausa e chama <code>fat(2)</code></li>\n<li><code>fat(2)</code> precisa saber <code>2 * fat(1)</code> → pausa e chama <code>fat(1)</code></li>\n<li><code>fat(1)</code> bate no <strong>Caso Base</strong> → retorna <strong><code>1</code></strong>!</li>\n</ol></li>\n<li><strong>Subida (desempilhando <em>POP</em> e calculando):</strong> 5. <code>fat(2)</code> calcula <code>2 * 1 =</code> <strong><code>2</code></strong> 6. <code>fat(3)</code> calcula <code>3 * 2 =</code> <strong><code>6</code></strong> 7. <code>fat(4)</code> calcula <code>4 * 6 =</code> <strong><code>24</code></strong>!</li>\n</ul>\n<div class=\"callout callout-tip\">\n\n<p><strong>Lembrete matemático importante:</strong> <strong><code>0! = 1</code></strong> (por definição combinatória, existe 1 forma de organizar zero elementos) e acumulador de multiplicação/fatorial em laço deve começar com <strong><code>1</code></strong>, nunca <code>0</code>!</p>\n</div>\n\n<hr />\n<h3 id=\"️️-dissecando-questões-no-estilo-exato-da-prova\">🕵️‍♂️ Dissecando Questões no Estilo Exato da Prova</h3>\n<h4 id=\"questão-resolvida-1-baseada-em-ds-2019-q3--pilha-lifo\">Questão Resolvida 1 (Baseada em DS 2019 Q3 — Pilha LIFO)</h4>\n<p><em>Em uma estrutura do tipo Pilha vazia, inseriram-se os números 5, 10 e 15 (nessa ordem). Em seguida, aplicou-se uma operação de remoção (POP), inseriu-se o 20 e aplicou-se outro POP. Qual o elemento no TOPO e qual é a BASE restante?</em></p>\n<ul>\n<li>Passo a passo: <code>[]</code> → <code>[5]</code> → <code>[5,10]</code> → <code>[5,10,15]</code> → <code>POP</code> tira <code>15</code> (<code>[5,10]</code>) → <code>PUSH 20</code> (<code>[5,10,20]</code>) → <code>POP</code> tira <code>20</code> (<strong><code>[5,10]</code></strong>).</li>\n<li><strong>Resposta:</strong> Base = <strong><code>5</code></strong>, Topo = <strong><code>10</code></strong>. <em>(Se fosse uma <strong>Fila FIFO</strong>, o 1º <code>Dequeue</code> teria tirado o <code>5</code> em vez do <code>15</code>!)</em></li>\n</ul>\n<h4 id=\"questão-resolvida-2-baseada-em-matriz--índices\">Questão Resolvida 2 (Baseada em Matriz + Índices)</h4>\n<p><em>Considere a matriz quadrada <code>A</code> 3×3 preenchida pela regra <code>se (i + j == 2) entao A[i][j] &lt;- 10 senao A[i][j] &lt;- i * 2</code>. Qual o valor de <code>A[2][1]</code> e qual diagonal recebeu o valor 10?</em></p>\n<ul>\n<li>Em <code>A[2][1]</code>: <code>i = 2, j = 1</code>. Soma <code>2 + 1 = 3 != 2</code> (cai no <code>senao</code>!). Logo <code>A[2][1] = 2 * 2 =</code> <strong><code>4</code></strong>.</li>\n<li>Como <code>N = 3</code>, <code>i + j == N - 1</code> (<code>i + j == 2</code>) é exatamente a <strong>Diagonal Secundária</strong>!</li>\n</ul>\n", "practiceType": "lab02", "practiceTag": "01_Programacao", "videoClips": [{"title": "Vetores — Curso de Algoritmos #14", "channel": "Curso em Vídeo • Gustavo Guanabara", "videoId": "j9473xQ39vY", "startSec": 120, "endSec": 480, "tip": "Foco: variáveis compostas homogêneas unidimensionais e navegação por índices."}, {"title": "Matrizes — Curso de Algoritmos #15", "channel": "Curso em Vídeo • Gustavo Guanabara", "videoId": "hkE9WrjpAAk", "startSec": 105, "endSec": 495, "tip": "Foco: matrizes bidimensionais [linha][coluna] e diagonais na prática."}], "challengeRefs": [{"examId": "ds2025", "qNum": 10}, {"examId": "info2025", "qNum": 21}, {"examId": "ds2019", "qNum": 3}, {"examId": "ds2019", "qNum": 6}, {"examId": "sim1", "qNum": 10}, {"examId": "sim2", "qNum": 3}, {"examId": "sim2", "qNum": 4}, {"examId": "apostas", "qNum": 10}]}, {"day": 4, "title": "Frameworks, Editores/WYSIWYG, Build/Bundling, Git e Licenças", "weight": "Alta", "storyIntro": "Capítulo 4: Compare Laravel, Angular, React Native e Bootstrap, entenda compilação/bundling, Git (branch/diff/merge) e Software Livre vs. Freeware/EULA.", "lessonHtml": "<h2 id=\"dia-4--ecossistema-de-desenvolvimento-frameworks-editoresideswysiwyg-compilaçãobuildbundling-git-e-licenças\">Dia 4 — Ecossistema de Desenvolvimento: Frameworks, Editores/IDEs/WYSIWYG, Compilação/Build/Bundling, Git e Licenças</h2>\n<h3 id=\"-contexto-no-mundo-real-construindo-uma-casa-sem-fabricar-tijolo-por-tijolo\">🎯 Contexto no Mundo Real: Construindo uma Casa sem Fabricar Tijolo por Tijolo</h3>\n<p>Se uma equipe precisasse inventar toda vez o sistema de rotas URL, autenticação de login, layout responsivo de botões para celular e minificação de scripts do zero, criar um simples site de escola levaria meses. Por isso existem os <strong>frameworks</strong>, as <strong>IDEs</strong>, as ferramentas de <strong>build/bundling</strong>, o controle de versão <strong>Git</strong> e as <strong>licenças legais</strong> que dizem o que uma empresa pode ou não usar comercialmente sem ser processada. Esse módulo é puro <strong>Molde 1 (I, II, III)</strong> e <strong>Molde 2 (Lista com Intruso)</strong> na prova!</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Para conectar esse módulo técnico com o mundo de jogos, mods e Discord:</p>\n<ul>\n<li><strong>Framework vs. Biblioteca = Game Engine / Mod Loader:</strong> Uma biblioteca é igual baixar só um pacote de texturas — você usa se quiser. Um <strong>Framework</strong> (Laravel, Angular, React Native, Bootstrap) é tipo usar uma <strong>Engine</strong> (ou Forge/Fabric no Minecraft): já vem com o esqueleto pronto e você só encaixa o seu código nos lugares certos!</li>\n<li><strong>Compilação + <em>Build</em> + <em>Bundling</em>:</strong> Quando você cria mods ou um jogo, são dezenas de arquivos separados <code>.js</code>/<code>.cs</code> + texturas. O <em><strong>Build / Bundling</strong></em> empacota tudo num <code>.exe</code> ou <code>.pak</code> otimizado e minificado para abrir rápido sem fazer 200 carregamentos na internet.</li>\n<li><strong>Git (<code>branch</code>, <code>diff</code>, <code>merge</code>) = Save Slots antes de testar Mod arriscado:</strong> Em vez de editar o save oficial (<code>main</code>) e correr o risco de corromper tudo, você cria uma cópia paralela (<strong><code>git branch</code></strong>), compara exatamente o que mudou linha por linha (<strong><code>git diff</code></strong>) e, só quando tiver certeza de que não deu bug, junta de volta no save oficial (<strong><code>git merge</code></strong>)!</li>\n<li><strong>Licenças na vida real:</strong>\n<ul>\n<li><strong>Discord / Valorant / Spotify:</strong> São <em><strong>Freeware</strong></em> (grátis para baixar e usar, mas <strong>código-fonte 100% fechado</strong>, NÃO são Software Livre!).</li>\n<li><strong>OBS Studio / Godot Engine / Linux:</strong> São <strong>Software Livre / Open Source</strong> — você pode baixar o código no GitHub, estudar, modificar e recompilar legalmente!</li>\n<li><strong>EULA:</strong> Aquele textão jurídico de contrato que todo mundo aceita na Steam/Windows dizendo <em>\"não tente piratear, fazer engenharia reversa ou revender este jogo\"</em>.</li>\n</ul></li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--frameworks-web--mobile-o-que-são-e-onde-cada-um-atua\">📚 Parte 1 — Frameworks Web &amp; Mobile (O que São e Onde Cada Um Atua)</h3>\n<h4 id=\"biblioteca-vs-framework-qual-a-diferença-conceitual\">Biblioteca vs. Framework (Qual a diferença conceitual?)</h4>\n<ul>\n<li><strong>Biblioteca (<em>Library</em>):</strong> Uma caixa de ferramentas — <strong>você chama</strong> a função dela quando quiser (ex.: uma biblioteca de PDF ou matemática).</li>\n<li><strong>Framework:</strong> Um <strong>esqueleto arquitetural completo</strong> com regras prontas — ele segue a <strong>Inversão de Controle</strong> (o framework organiza o ciclo do app e chama o seu código nos pontos certos).</li>\n</ul>\n<p>Os <strong>4 Frameworks campeões</strong> nas provas da Fundação FAT:</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Tecnologia</th>\n<th style=\"text-align: left;\">Linguagem / Stack</th>\n<th style=\"text-align: left;\">Camada / Finalidade Oficial</th>\n<th style=\"text-align: left;\">Arquitetura &amp; Detalhes que Caem</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Bootstrap</strong></td>\n<td style=\"text-align: left;\">HTML + CSS + JS</td>\n<td style=\"text-align: left;\"><strong>Front-end Web Responsivo</strong> (<em>mobile-first</em>)</td>\n<td style=\"text-align: left;\">Sistema de <strong>Grid de 12 colunas</strong> (<code>container</code>, <code>row</code>, <code>col-md-6</code>), botões prontos (<code>btn btn-primary</code>), alertas (<code>alert alert-success</code>), navbar adaptável ao celular. <em>(DS 2019 Q18)</em></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Angular</strong></td>\n<td style=\"text-align: left;\"><strong>TypeScript</strong> / JS (Google)</td>\n<td style=\"text-align: left;\"><strong>Front-end Web SPA</strong> (<em>Single Page Application</em>)</td>\n<td style=\"text-align: left;\">Interfaces dinâmicas modulares baseadas em componentes, <em>data-binding</em> bidirecional e injeção de dependência.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Laravel</strong></td>\n<td style=\"text-align: left;\"><strong>PHP</strong></td>\n<td style=\"text-align: left;\"><strong>Back-end Web (Servidor)</strong></td>\n<td style=\"text-align: left;\">Segue o padrão <strong>MVC</strong> (<em>Model-View-Controller</em>): <code>Model</code> cuida dos dados/banco (ORM Eloquent), <code>View</code> exibe as telas (Blade), <code>Controller</code> recebe requisições HTTP e decide regras de negócio.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>React Native</strong></td>\n<td style=\"text-align: left;\">JavaScript / React (Meta)</td>\n<td style=\"text-align: left;\"><strong>Aplicativos Mobile Nativos (Android + iOS)</strong></td>\n<td style=\"text-align: left;\">Você escreve uma única base em JS/React e ele <strong>renderiza componentes nativos reais</strong> do Android/iOS (não é só um site dentro de navegador!).</td>\n</tr>\n</tbody>\n</table>\n<div class=\"callout callout-caution\">\n\n<p><strong>Pegadinha da DS 2025 Q7 (Molde 2 — Lista com Intruso):</strong> A banca listou frameworks válidos e misturou intrusos como <strong>Creative Commons</strong> (que é uma <strong>licença</strong> de direitos autorais!) e <strong>Adobe Creative Cloud</strong> (suíte de edição de imagem/vídeo como Photoshop/Illustrator). Também costuma inverter <strong>Laravel (back-end PHP)</strong> dizendo que é \"para interfaces móveis\".</p>\n</div>\n\n<hr />\n<h3 id=\"-parte-2--bloco-de-notas-vs-editor-de-código-vs-ide-vs-wysiwyg\">📚 Parte 2 — Bloco de Notas vs. Editor de Código vs. IDE vs. WYSIWYG</h3>\n<p>A Fundação FAT cobra literalmente a distinção entre as ferramentas onde programadores digitam e montam interfaces:</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Categoria</th>\n<th style=\"text-align: left;\">Recursos Incluídos</th>\n<th style=\"text-align: left;\">Exemplos Oficiais da Prova</th>\n<th style=\"text-align: left;\">NÃO confunda!</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Editor de Texto Simples</strong></td>\n<td style=\"text-align: left;\">Digita texto puro sem formatação (<code>UTF-8</code>), <strong>SEM</strong> destaque de sintaxe, autocompletar ou compilador.</td>\n<td style=\"text-align: left;\"><strong>Bloco de Notas (Notepad)</strong> do Windows, <code>TextEdit</code> simples</td>\n<td style=\"text-align: left;\">Embora dê para digitar HTML nele e salvar como <code>.html</code>, <strong>ele NÃO é uma IDE nem editor de código avançado</strong>!</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Editor de Código-Fonte</strong></td>\n<td style=\"text-align: left;\">Leve, rápido, oferece <strong>realce de sintaxe</strong> (colorir tags/comandos), numeração de linhas, indentação automática e <strong>extensões/plugins</strong>.</td>\n<td style=\"text-align: left;\"><strong>VS Code</strong> (<em>Visual Studio Code</em>), Sublime Text, Notepad++, Atom</td>\n<td style=\"text-align: left;\">VS Code puro, recém-instalado, é oficialmente classificado como <strong>Editor de Código</strong> (embora com plugins chegue perto de uma IDE).</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>IDE</strong> (<em>Integrated Development Environment</em>)</td>\n<td style=\"text-align: left;\"><strong>Ambiente Integrado de Desenvolvimento:</strong> junta em um só software Editor + <strong>Compilador/Interpretador + Depurador (<em>Debugger</em> c/ breakpoints) + Gerenciador de Projeto</strong>.</td>\n<td style=\"text-align: left;\"><strong>Visual Studio</strong> (Microsoft), <strong>Eclipse</strong>, <strong>IntelliJ IDEA</strong>, <strong>NetBeans</strong>, <strong>PyCharm</strong>, <strong>Android Studio</strong></td>\n<td style=\"text-align: left;\">Não confunda <em>Visual Studio</em> (IDE completa pesada) com <em>Visual Studio Code</em> (editor leve)!</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Editor WYSIWYG</strong> (<em>What You See Is What You Get</em>)</td>\n<td style=\"text-align: left;\"><em>\"O que você vê é o que você obtém\"</em>: criação visual <strong>arrastar-e-soltar</strong> que mostra o layout pronto ao vivo enquanto gera HTML/CSS nos bastidores.</td>\n<td style=\"text-align: left;\"><strong>Adobe Dreamweaver</strong> (modo Design), <strong>Wix</strong>, <strong>WordPress Gutenberg/Elementor</strong>, Google Sites</td>\n<td style=\"text-align: left;\">Foca em design visual sem precisar digitar toda tag HTML na mão.</td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h3 id=\"-parte-3--compilação-interpretação-build-e-bundling-ds-2025-q22--apostas-q8\">📚 Parte 3 — Compilação, Interpretação, <em>Build</em> e <em>Bundling</em> (DS 2025 Q22 &amp; Apostas Q8)</h3>\n<h4 id=\"1-compilador-vs-interpretador-vs-híbrido\">1. Compilador vs. Interpretador vs. Híbrido</h4>\n<ul>\n<li><strong>Compilador (ex.: C, C++, Go, Rust):</strong> Traduz <strong>todo o código-fonte de uma só vez</strong> antes da execução: <code>Código-Fonte (.c)</code> → <strong>Compilador</strong> → <code>Código-Objeto (.o/.obj, binário parcial)</code> → <strong>Linker (Ligador)</strong> (junta bibliotecas do sistema) → <code>Arquivo Executável (.exe / ELF)</code>.\n<ul>\n<li>Resultado: executa muito rápido sem precisar do código-fonte original no PC do cliente.</li>\n</ul></li>\n<li><strong>Interpretador (ex.: Python, JavaScript, PHP):</strong> Lê, traduz e executa o código <strong>linha por linha em tempo de execução</strong>. Mais portável e rápido de testar, porém exige o interpretador instalado.</li>\n<li><strong>Modelo Híbrido (Java / C#):</strong> Compila o fonte para um código intermediário chamado <em><strong>Bytecode</strong></em> (<code>.class</code> em Java), que depois roda na <strong>JVM (<em>Java Virtual Machine</em>)</strong>, garantindo alta portabilidade (<em>\"Write Once, Run Anywhere\"</em>).</li>\n</ul>\n<h4 id=\"2-o-que-são-build-bundling-minificação-e-tree-shaking-na-web-moderna\">2. O que são <em>Build</em>, <em>Bundling</em>, <em>Minificação</em> e <em>Tree Shaking</em> na Web Moderna?</h4>\n<p>Quando você faz um site grande em React ou Angular, você tem <strong>150 arquivos <code>.js</code> e <code>.css</code> separados</strong>. Se o navegador do usuário tivesse que fazer 150 downloads separados ao abrir a página, o site ficaria lentíssimo!</p>\n<ul>\n<li><strong><em>Build</em> (Construção):</strong> Processo automatizado completo que prepara o projeto para entrar no ar (produção): compila/transpila código moderno (ex.: TypeScript → JS), roda testes, otimiza imagens e gera a pasta final de distribuição (<code>dist/</code>).</li>\n<li><strong><em>Bundling</em> (Empacotamento):</strong> Realizado por <em>bundlers</em> (<strong>Webpack, Vite, Parcel</strong>). Consiste em <strong>agrupar dezenas de módulos/arquivos JS e CSS espalhados em poucos arquivos consolidados (<em>bundles</em>)</strong> para reduzir requisições HTTP na rede.</li>\n<li><strong>Minificação (<em>Minification</em>):</strong> Remove comentários, espaços em branco, quebras de linha e encurta nomes de variáveis internas (<code>contadorDeAlunos</code> vira <code>a</code>) apenas para o arquivo pesar menos KB na internet.</li>\n<li><strong><em>Tree Shaking</em>:</strong> Técnica em que o <em>bundler</em> detecta funções importadas que <strong>nunca foram usadas</strong> no projeto e as <strong>exclui do bundle final</strong> para economizar tamanho.</li>\n</ul>\n<hr />\n<h3 id=\"-parte-4--controle-de-versão-git-em-equipe-ds-2019-q26\">📚 Parte 4 — Controle de Versão Git em Equipe (DS 2019 Q26)</h3>\n<p>Imagine dois desenvolvedores editando <code>sistema.js</code> ao mesmo tempo: sem controle de versão, um sobrescreve o trabalho do outro ou perde tudo num erro! O <strong>Git</strong> é um <strong>sistema de controle de versão distribuído</strong> (cada dev tem o histórico completo na sua máquina; o <strong>GitHub/GitLab/Azure DevOps</strong> é a nuvem que hospeda repositórios Git).</p>\n<p><strong>Ciclo real e comandos obrigatórios para a prova:</strong></p>\n<ul>\n<li><code>git init</code> / <code>git clone &lt;url&gt;</code>: Inicia repositório novo na pasta / Baixa cópia completa de um remoto.</li>\n<li><code>git status</code>: Mostra em tempo real quais arquivos foram modificados ou estão aguardando <em>commit</em>.</li>\n<li><code>git add arquivo.js</code> (ou <code>git add .</code>): Envia as mudanças selecionadas para a <strong>Staging Area</strong> (área de preparação).</li>\n<li><code>git commit -m \"Corrige cálculo de média\"</code>: Grava um ponto definitivo no histórico (<strong>snapshot</strong>) com identificador único (hash).</li>\n<li><strong><code>git branch nova-tela</code></strong>: Cria uma <strong>ramificação paralela e isolada</strong> do código principal (<code>main</code>) para desenvolver uma novidade sem quebrar o sistema em produção! <em>(DS 2019 Q26)</em></li>\n<li><strong><code>git diff</code></strong>: <strong>Compara</strong> e exibe linha por linha as <strong>diferenças</strong> entre arquivos, commits ou branches.</li>\n<li><strong><code>git merge nova-tela</code></strong>: <strong>Funde (mescla)</strong> o trabalho pronto de uma <em>branch</em> dentro de outra (ex.: traz <code>nova-tela</code> para dentro da <code>main</code>).</li>\n<li><code>git push</code> / <code>git pull</code>: <strong>Envia</strong> seus commits para o servidor remoto / <strong>Baixa e mescla</strong> commits dos colegas do remoto para o seu PC.</li>\n</ul>\n<hr />\n<h3 id=\"-parte-5--licenças-de-software-software-livre-open-source-proprietário-freeware-eula\">📚 Parte 5 — Licenças de Software (Software Livre, Open Source, Proprietário, Freeware, EULA)</h3>\n<p>A Fundação FAT e o M-Tec cobram esse tema quase todo ano (<strong>DS 2025 Q23</strong>, <strong>M-Tec 2022 Q36</strong>)! Entenda a diferença jurídica real:</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Licença / Modelo</th>\n<th style=\"text-align: center;\">Código-Fonte é Aberto?</th>\n<th style=\"text-align: center;\">Pode Alterar e Redistribuir?</th>\n<th style=\"text-align: center;\">Precisa ser Grátis (<code>R$ 0</code>)?</th>\n<th style=\"text-align: left;\">Essência e Exemplos</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Software Livre (<em>Free Software</em> — FSF)</strong></td>\n<td style=\"text-align: center;\"><strong>SIM</strong></td>\n<td style=\"text-align: center;\"><strong>SIM</strong></td>\n<td style=\"text-align: center;\"><strong>NÃO obrigatoriamente!</strong> (<em>\"Free as in freedom, not free beer\"</em>)</td>\n<td style=\"text-align: left;\">Defende <strong>4 Liberdades Fundamentais</strong> (usar p/ qualquer fim, estudar/modificar, redistribuir cópias, distribuir modificações). Pode ser vendido por mídia ou suporte! Ex.: Linux (GPL), LibreOffice, GIMP.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Open Source (Código Aberto — OSI)</strong></td>\n<td style=\"text-align: center;\"><strong>SIM</strong></td>\n<td style=\"text-align: center;\"><strong>SIM</strong></td>\n<td style=\"text-align: center;\">Geralmente sim (alguns com modelo comercial em cima)</td>\n<td style=\"text-align: left;\">Foco prático/empresarial em desenvolvimento colaborativo, transparência e qualidade técnica. Principais licenças: <strong>MIT, Apache 2.0, BSD</strong> (permissivas) e <strong>GPL</strong> (<em>copyleft</em> — exige que derivados continuem livres).</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Proprietário / Comercial</strong></td>\n<td style=\"text-align: center;\"><strong>NÃO (Fechado)</strong></td>\n<td style=\"text-align: center;\"><strong>PROIBIDO</strong> (restringido por lei)</td>\n<td style=\"text-align: center;\">Pago (ou assinatura)</td>\n<td style=\"text-align: left;\">O dono retém todos os direitos autorais e entrega só o binário executável. O usuário aceita um <strong>EULA (<em>End User License Agreement</em>)</strong> proibindo engenharia reversa e cópia. Ex.: Windows, Photoshop, MS Office.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><em><strong>Freeware</strong></em></td>\n<td style=\"text-align: center;\"><strong>NÃO (Fechado)</strong></td>\n<td style=\"text-align: center;\"><strong>PROIBIDO modificar</strong></td>\n<td style=\"text-align: center;\"><strong>SIM (<code>R$ 0</code>)</strong></td>\n<td style=\"text-align: left;\">Distribui gratuitamente o executável, <strong>mas esconde o código-fonte</strong>! Ex.: Skype, WinRAR antigo/Adobe Reader. <strong>NÃO é Software Livre!</strong></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong><em>Shareware</em> / Trial</strong></td>\n<td style=\"text-align: center;\"><strong>NÃO</strong></td>\n<td style=\"text-align: center;\"><strong>PROIBIDO</strong></td>\n<td style=\"text-align: center;\">Grátis por tempo limitado (ex.: 30 dias)</td>\n<td style=\"text-align: left;\">Teste temporário antes de exigir compra da licença.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Assinatura / SaaS</strong></td>\n<td style=\"text-align: center;\">Geralmente fechado</td>\n<td style=\"text-align: center;\"><strong>PROIBIDO</strong></td>\n<td style=\"text-align: center;\">Mensalidade/anuidade contínua</td>\n<td style=\"text-align: left;\">Acesso ao software e atualizações enquanto pagar (ex.: Microsoft 365, Adobe Creative Cloud, Netflix).</td>\n</tr>\n</tbody>\n</table>\n<div class=\"callout callout-caution\">\n\n<p><strong>Pegadinha clássica (DS 2025 Q23 &amp; M-Tec 2022 Q36):</strong></p>\n<ol>\n<li><em>\"Todo Software Livre é necessariamente gratuito e nunca pode ser comercializado.\"</em> → <strong>FALSO!</strong> Você pode vender distribuição ou suporte de Software Livre; a liberdade é sobre <strong>acessar e modificar o código-fonte</strong>.</li>\n<li><em>\"Todo software gratuito (Freeware) é Open Source.\"</em> → <strong>FALSO!</strong> Se o código é fechado, é proprietário gratuito (<em>Freeware</em>), jamais Open Source ou Software Livre!</li>\n<li><strong>EULA</strong> (<em>End User License Agreement</em>) é o contrato de usuário final típico de software <strong>proprietário</strong>, definindo limites de instalação e proibindo redistribuição.</li>\n</ol>\n</div>\n\n<hr />\n<h3 id=\"️️-dissecando-questões-no-estilo-exato-da-prova\">🕵️‍♂️ Dissecando Questões no Estilo Exato da Prova</h3>\n<h4 id=\"questão-resolvida-1-baseada-em-ds-2019-q26--ds-2025-q19--git-e-editores\">Questão Resolvida 1 (Baseada em DS 2019 Q26 &amp; DS 2025 Q19 — Git e Editores)</h4>\n<p><em>Analise: I. O Bloco de Notas (Notepad) é classificado como IDE por permitir salvar arquivos <code>.html</code>. II. No Git, <code>git branch</code> cria linha paralela de desenvolvimento, <code>git diff</code> mostra diferenças entre versões e <code>git merge</code> une ramificações. III. Bundlers como Webpack agrupam vários módulos JS/CSS para diminuir requisições HTTP.</em></p>\n<ul>\n<li><strong>Item I é FALSO:</strong> Bloco de Notas é editor de texto simples (não possui compilador/depurador integrados).</li>\n<li><strong>Item II é VERDADEIRO:</strong> Definições exatas dos três comandos Git.</li>\n<li><strong>Item III é VERDADEIRO:</strong> Função exata de <em>bundling</em>. <strong>Gabarito:</strong> <strong>II e III corretas</strong>.</li>\n</ul>\n<h4 id=\"questão-resolvida-2-baseada-em-ds-2025-q23--licenças\">Questão Resolvida 2 (Baseada em DS 2025 Q23 — Licenças)</h4>\n<p><em>Qual alternativa está INCORRETA sobre licenciamento de software?</em></p>\n<ul>\n<li><em>A) Open Source exige acesso ao código-fonte para inspeção e melhoria.</em> (Verdadeira)</li>\n<li><em>B) Um software proprietário costuma ser distribuído sob um EULA restringindo cópia e modificação.</em> (Verdadeira)</li>\n<li><em>C) Software Livre proíbe cobrança financeira e exige distribuição de binários sem código-fonte.</em> (<strong>FALSA!</strong> Tanto permite venda quanto <strong>exige</strong> acesso ao código-fonte!). <strong>Gabarito:</strong> <strong>C</strong>.</li>\n</ul>\n", "practiceType": "pairs", "practiceTag": "01_Programacao", "videoClips": [{"title": "Git // Dicionário do Programador", "channel": "Código Fonte TV", "videoId": "za5KWZ5pRag", "startSec": 70, "endSec": 400, "tip": "Foco: como funcionam commit, branch, diff e merge no controle de versão em equipe."}], "challengeRefs": [{"examId": "ds2025", "qNum": 7}, {"examId": "ds2025", "qNum": 19}, {"examId": "ds2025", "qNum": 22}, {"examId": "ds2025", "qNum": 23}, {"examId": "ds2019", "qNum": 18}, {"examId": "ds2019", "qNum": 26}, {"examId": "mtec2022", "qNum": 36}, {"examId": "sim1", "qNum": 12}, {"examId": "sim2", "qNum": 6}]}, {"day": 5, "title": "Engenharia de Software, Requisitos, UML, Scrum, XP e POO", "weight": "Alta", "storyIntro": "Capítulo 5: Domine Cascata vs. Ágil, Requisitos Funcionais/Não Funcionais, UML, papéis do Scrum, Pair Programming, Testes e os 4 pilares da POO.", "lessonHtml": "<h2 id=\"dia-5--engenharia-de-software-ciclos-de-vida-requisitos-swot-uml-scrumxp-testes-e-poo\">Dia 5 — Engenharia de Software, Ciclos de Vida, Requisitos, SWOT, UML, Scrum/XP, Testes e POO</h2>\n<h3 id=\"-contexto-no-mundo-real-por-que-só-sair-digitando-código-quebra-empresas\">🎯 Contexto no Mundo Real: Por que \"Só Sair Digitando Código\" Quebra Empresas?</h3>\n<p>Imagine construir um prédio de 15 andares sem engenheiro: você começa a empilhar tijolos no primeiro dia e, no quinto andar, descobre que esqueceu o poço do elevador e que o solo não aguenta o peso. Na década de 1960 ocorreu a chamada <strong>Crise do Software</strong> — projetos estouravam orçamentos em 300%, entregavam atrasados e cheios de falhas críticas porque programadores escreviam código direto sem planejar requisitos, arquitetura ou testes.</p>\n<p>É daí que nasce a <strong>Engenharia de Software</strong>: um conjunto sistemático de métodos, processos e boas práticas para entregar sistemas como <strong>Spotify, Nubank ou o NSA da Etec</strong> no prazo, dentro do orçamento, fáceis de manter e fiéis ao que o cliente realmente precisa.</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Você já viu na prática por que grandes estúdios de games falham ou acertam dependendo do jeito que desenvolvem o software:</p>\n<ul>\n<li><strong>Cascata vs. Ágil/Scrum (Atualizações de Jogos):</strong>\n<ul>\n<li>Fazer um jogo em <strong>Cascata</strong> é passar 5 anos desenvolvendo escondido sem testar com ninguém e lançar tudo de uma vez (e se os jogadores odiarem a mecânica, já era!).</li>\n<li>Usar <strong>Scrum (Ágil)</strong> é lançar uma base jogável rápido e ir soltando <em>Patches / Seasons</em> a cada <strong>Sprint</strong> de 2 semanas, fazendo a <strong>Daily de 15 min</strong> na call do Discord só para alinhar quem tá fazendo o quê e tirar bloqueios (<em>Scrum Master</em>) enquanto o <em>Product Owner</em> prioriza o que dá mais valor pro jogador!</li>\n</ul></li>\n<li><strong>Requisitos Funcionais (RF) vs. Não Funcionais (RNF) num Jogo Online:</strong>\n<ul>\n<li><strong>RF (\"O QUÊ faz\"):</strong> <em>\"O personagem pula, atira, recarrega e abre loja de skins.\"</em></li>\n<li><strong>RNF (\"COMO se comporta\"):</strong> <em>\"Rodar a <strong>120 FPS</strong>, ping abaixo de <strong>30 ms</strong>, anti-cheat ativo e ter <strong>Portabilidade</strong> para rodar tanto no Windows 11 quanto no Steam Deck (Linux)!\"</em></li>\n</ul></li>\n<li><strong>Os 4 Pilares da POO na Prática:</strong> Você cria um molde geral chamado classe <strong><code>Personagem</code> (Abstração)</strong>. Dele nascem <code>Mago</code> e <code>Guerreiro</code> aproveitando vida/nome/mover (<strong>Herança</strong>). A variável interna <code>hp</code> fica bloqueada como <code>private</code> pra ninguém editar com cheat (<strong>Encapsulamento</strong>). E quando os dois apertam <code>Q</code> (<code>usarHabilidade()</code>), cada classe solta um poder diferente com o mesmo comando (<strong>Polimorfismo</strong>)!</li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--modelos-de-ciclo-de-vida-cascata-vs-prototipação-vs-espiral-vs-ágil\">📚 Parte 1 — Modelos de Ciclo de Vida: Cascata vs. Prototipação vs. Espiral vs. Ágil</h3>\n<p>Todo software passa por fases: <strong>Levantamento de Requisitos → Projeto/Arquitetura → Implementação (Código) → Testes/Validação → Implantação → Manutenção</strong>. A forma como organizamos essas fases define o <strong>Modelo de Processo</strong>:</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Modelo</th>\n<th style=\"text-align: left;\">Como funciona passo a passo</th>\n<th style=\"text-align: left;\">Quando brilha</th>\n<th style=\"text-align: left;\">Onde costuma falhar</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Cascata (<em>Waterfall</em>)</strong> <em>(DS 2019 Q8)</em></td>\n<td style=\"text-align: left;\"><strong>Sequencial e rígido:</strong> uma fase só inicia quando a anterior for 100% encerrada e assinada (<em>Requisitos → Design → Código → Testes → Uso</em>).</td>\n<td style=\"text-align: left;\">Requisitos totalmente estáveis desde o dia 1 (ex.: software médico/aviação regulado).</td>\n<td style=\"text-align: left;\">Se o cliente mudar de ideia na metade, voltar fases é caríssimo; <strong>cliente só vê software pronto no final!</strong></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Prototipação</strong></td>\n<td style=\"text-align: left;\">Constrói rapidamente um <strong>protótipo</strong> (tela simulada ou rascunho) para o cliente testar, validar a ideia e corrigir cedo.</td>\n<td style=\"text-align: left;\">Quando o cliente não sabe explicar direito o que quer.</td>\n<td style=\"text-align: left;\">Risco de o cliente achar que o rascunho já é o sistema pronto.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Espiral (Boehm)</strong></td>\n<td style=\"text-align: left;\">Ciclos repetidos (<em>espiral</em>) onde <strong>cada volta começa com Análise de Riscos</strong>, protótipo, engenharia e avaliação.</td>\n<td style=\"text-align: left;\">Sistemas gigantes de alto risco financeiro ou técnico.</td>\n<td style=\"text-align: left;\">Complexo e caro gerenciar a análise de riscos em projetos pequenos.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Metodologias Ágeis</strong> <em>(Scrum, Kanban, XP)</em></td>\n<td style=\"text-align: left;\">Desenvolvimento <strong>iterativo e incremental</strong> em ciclos curtos (<em>Sprints</em> de 1–4 semanas). Entrega software funcionando rápido e <strong>abraça mudanças</strong>.</td>\n<td style=\"text-align: left;\">90% dos projetos modernos (apps, web, startups) onde o mercado muda toda hora.</td>\n<td style=\"text-align: left;\">Exige participação próxima do cliente e equipe madura/auto-organizável.</td>\n</tr>\n</tbody>\n</table>\n<div class=\"callout callout-warning\">\n\n<p><strong>Pegadinha clássica (DS 2019 Q8):</strong> No <strong>Modelo em Cascata</strong>, as fases avançam de forma <strong>sequencial descendente</strong> e cada etapa deve ser concluída antes de passar para a próxima — o erro nas alternativas é afirmar que <em>\"o modelo Cascata entrega incrementos semanais ao cliente sem documentação prévia\"</em> (isso é Ágil!).</p>\n</div>\n\n<hr />\n<h3 id=\"-parte-2--engenharia-de-requisitos-estudo-de-viabilidade-e-análise-swot\">📚 Parte 2 — Engenharia de Requisitos, Estudo de Viabilidade e Análise SWOT</h3>\n<p>Antes de escrever código, o Analista de Sistemas conversa com os <em>stakeholders</em> (partes interessadas: clientes, usuários, diretoria) para levantar os <strong>Requisitos</strong> e realizar o <strong>Estudo de Viabilidade</strong>.</p>\n<h4 id=\"1-estudo-de-viabilidade-info-2025-q23--apostas-q12\">1. Estudo de Viabilidade (<em>INFO 2025 Q23 &amp; Apostas Q12</em>)</h4>\n<p>Responde à pergunta: <em>\"Vale a pena e é possível fazer este sistema?\"</em> Analisa 3 frentes:</p>\n<ul>\n<li><strong>Viabilidade Técnica:</strong> Temos tecnologia, servidores, APIs e equipe capaz de construir?</li>\n<li><strong>Viabilidade Econômica / Financeira:</strong> O benefício/lucro (<em>ROI</em>) compensa o custo de desenvolvimento e manutenção?</li>\n<li><strong>Viabilidade Operacional:</strong> Os funcionários e usuários reais vão conseguir e querer operar o sistema no dia a dia?</li>\n</ul>\n<h4 id=\"2-requisitos-funcionais-rf-vs-requisitos-não-funcionais-rnf\">2. Requisitos Funcionais (RF) vs. Requisitos Não Funcionais (RNF)</h4>\n<p>Vamos aplicar ao exemplo real de um <strong>aplicativo de delivery (tipo iFood)</strong>:</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Tipo</th>\n<th style=\"text-align: left;\">O que descreve</th>\n<th style=\"text-align: left;\">Exemplos reais no App de Delivery</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Requisito Funcional (RF)</strong></td>\n<td style=\"text-align: left;\"><strong>O QUE</strong> o sistema faz — ações, serviços, regras de cálculo e telas visíveis.</td>\n<td style=\"text-align: left;\"><strong>RF01:</strong> Permitir cadastro de cliente com CPF.<br><strong>RF02:</strong> Calcular taxa de entrega por distância.<br><strong>RF03:</strong> Permitir pagamento via Pix ou cartão.<br><strong>RF04:</strong> Cancelar pedido em até 2 minutos.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Requisito Não Funcional (RNF)</strong></td>\n<td style=\"text-align: left;\"><strong>COMO</strong> o sistema se comporta — restrições de qualidade, desempenho, segurança, <strong>portabilidade</strong>, usabilidade e normas.</td>\n<td style=\"text-align: left;\"><strong>RNF01 (Desempenho):</strong> Carregar cardápio em <strong>menos de 2 segundos</strong>.<br><strong>RNF02 (Segurança):</strong> Senhas criptografadas com BCrypt e tráfego <strong>HTTPS</strong>.<br><strong>RNF03 (Disponibilidade):</strong> Funcionar 99,9% do tempo na Black Friday.<br><strong>RNF04 (Portabilidade):</strong> <em>(DS 2019 Q10)</em> Poder ser instalado/transferido entre <strong>Android, iOS e Windows/Linux</strong> facilmente!</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Critérios de um Bom Requisito <em>(INFO 2025 Q22)</em>:</strong> Um requisito bem escrito nunca pode dizer <em>\"O sistema deve ser rápido e bonito\"</em> (vago!). Ele deve ser <strong>Claro, Não Ambíguo, Verificável/Testável</strong> (<em>\"responder em até 2 segundos\"</em>), <strong>Consistente</strong> (não contradizer outro RF) e <strong>Rastreável</strong>.</p>\n<h4 id=\"3-análise-swot--fofa-m-tec-2022-q29--sim2-q30\">3. Análise SWOT / FOFA <em>(M-Tec 2022 Q29 &amp; Sim2 Q30)</em></h4>\n<p>Ferramenta de planejamento estratégico para avaliar negócios/projetos em 4 quadrantes:</p>\n<ul>\n<li><strong>Ambiente Interno (controlável pela empresa):</strong>\n<ul>\n<li><strong>S — <em>Strengths</em> (Forças):</strong> Vantagens internas (ex.: equipe sênior experiente, marca forte).</li>\n<li><strong>W — <em>Weaknesses</em> (Fraquezas):</strong> Pontos fracos internos (ex.: servidor antigo, falta de suporte 24h).</li>\n</ul></li>\n<li><strong>Ambiente Externo (mercado/governo — fora do controle direto):</strong>\n<ul>\n<li><strong>O — <em>Opportunities</em> (Oportunidades):</strong> Cenários externos favoráveis (ex.: lei incentivando digitalização, concorrente faliu).</li>\n<li><strong>T — <em>Threats</em> (Ameaças):</strong> Riscos externos (ex.: entrada de gigante estrangeiro no mercado, alta do dólar).</li>\n</ul></li>\n</ul>\n<hr />\n<h3 id=\"-parte-3--uml-linguagem-de-modelagem-unificada-e-dicionário-de-dados\">📚 Parte 3 — UML (Linguagem de Modelagem Unificada) e Dicionário de Dados</h3>\n<p>A <strong>UML</strong> não é uma linguagem de programação — é a <strong>notação visual padrão</strong> usada mundialmente para desenhar sistemas orientados a objetos <em>(M-Tec 2022 Q30 &amp; INFO 2025 Q24)</em>.</p>\n<ol>\n<li><strong>Diagrama de Casos de Uso (<em>Use Case Diagram</em> — Comportamental):</strong>\n<ul>\n<li>Mostra <strong>quem</strong> usa o sistema e <strong>o que</strong> faz, visto pelo olhar do usuário externo.</li>\n<li><strong>Elementos principais:</strong> <strong>Ator</strong> (bonequinho — pode ser humano <em>Aluno</em> ou outro sistema externo <em>Banco</em>), <strong>Caso de Uso</strong> (elipse com verbo no infinitivo: <em>\"Realizar Matrícula\"</em>) e linhas de associação.</li>\n<li><strong>Relacionamentos especiais:</strong> <code>&lt;&lt;include&gt;&gt;</code> (obrigatório sempre, ex.: <em>Fazer Transferência</em> sempre inclui <em>Validar Senha</em>) e <code>&lt;&lt;extend&gt;&gt;</code> (opcional sob condição, ex.: <em>Solicitar Comprovante PDF</em>).</li>\n</ul></li>\n<li><strong>Diagrama de Classes (Estrutural / Estático):</strong>\n<ul>\n<li>Cada classe é um retângulo com 3 partes: <strong>Nome da Classe</strong> (ex.: <code>Aluno</code>), <strong>Atributos</strong> (<code>- nome: string</code>, <code>+ ra: int</code>) e <strong>Métodos</strong> (<code>+ calcularMedia(): float</code>).</li>\n<li>Símbolos de visibilidade: <strong><code>+</code> Público (<code>public</code>)</strong>, <strong><code>-</code> Privado (<code>private</code>)</strong>, <strong><code>#</code> Protegido (<code>protected</code>)</strong>.</li>\n</ul></li>\n<li><strong>Dicionário de Dados <em>(M-Tec 2022 Q32)</em>:</strong>\n<ul>\n<li>Documento/catálogo complementar onde cada dado do sistema é detalhado com precisão:</li>\n</ul></li>\n</ol>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Nome do Campo</th>\n<th style=\"text-align: left;\">Tipo &amp; Tamanho</th>\n<th style=\"text-align: center;\">Obrigatório?</th>\n<th style=\"text-align: left;\">Domínio / Regra de Validação</th>\n<th style=\"text-align: left;\">Descrição</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><code>cpf_aluno</code></td>\n<td style=\"text-align: left;\"><code>CHAR(11)</code></td>\n<td style=\"text-align: center;\">Sim (<code>NOT NULL</code>)</td>\n<td style=\"text-align: left;\">Apenas dígitos <code>0–9</code>, único (<code>UNIQUE</code>)</td>\n<td style=\"text-align: left;\">CPF do estudante sem pontos/traços</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><code>nota_final</code></td>\n<td style=\"text-align: left;\"><code>DECIMAL(4,2)</code></td>\n<td style=\"text-align: center;\">Não</td>\n<td style=\"text-align: left;\">De <code>0.00</code> até <code>10.00</code></td>\n<td style=\"text-align: left;\">Média calculada do módulo</td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h3 id=\"-parte-4--scrum-kanban-xp-extreme-programming-e-pirâmide-de-testes\">📚 Parte 4 — Scrum, Kanban, XP (<em>Extreme Programming</em>) e Pirâmide de Testes</h3>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Framework / Prática</th>\n<th style=\"text-align: left;\">Componentes e Definições Exatas para a Prova</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Scrum — Os 3 Papéis</strong></td>\n<td style=\"text-align: left;\"><strong>Product Owner (PO):</strong> Representa cliente/negócio; <strong>dono do <em>Product Backlog</em></strong>; define <strong>O QUÊ</strong> construir e em que ordem de prioridade de valor.<br><strong>Scrum Master (SM):</strong> <strong>Líder servidor/facilitador</strong>; garante o uso correto do Scrum e <strong>remove impedimentos</strong> do time. <em>(NÃO é chefe tradicional que distribui ordens nem arquiteto de código!)</em><br><strong>Time de Desenvolvimento (<em>Developers</em>):</strong> Equipe técnica multidisciplinar e <strong>auto-organizável</strong> que decide <strong>COMO</strong> implementar e estima as tarefas.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Scrum — Eventos (<em>Timeboxes</em>)</strong></td>\n<td style=\"text-align: left;\"><strong>Sprint:</strong> Ciclo curto e fixo (geralmente 1 a 4 semanas) que entrega Incremento pronto.<br><strong>Daily Scrum:</strong> Reunião diária curta de <strong>no máximo 15 minutos</strong>, em pé, para sincronizar o trabalho das próximas 24h e apontar impedimentos. <em>(DS 2019 Q12)</em><br><strong>Sprint Review</strong> (mostra software funcionando aos clientes) e <strong>Sprint Retrospective</strong> (melhoria interna do processo do time).</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Kanban</strong></td>\n<td style=\"text-align: left;\">Sistema visual com <strong>quadro de cartões e colunas</strong> (<em>Backlog → Fazendo → Em Teste → Feito</em>) focado em fluxo contínuo e <strong>limitação do trabalho em progresso (WIP — <em>Work In Progress</em>)</strong> para evitar gargalos.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>XP — <em>Pair Programming</em></strong> <em>(DS 2019 Q24)</em></td>\n<td style=\"text-align: left;\"><strong>Programação em Par:</strong> <strong>Dois programadores compartilham o mesmo computador</strong> — o <strong>Piloto (<em>Driver</em>)</strong> digita o código focado na linha atual, enquanto o <strong>Copiloto (<em>Navigator</em>)</strong> revisa erros em tempo real e pensa na estratégia/arquitetura, alternando papéis!</td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"os-4-níveis-oficiais-de-teste-de-software-ds-2019-q25\">Os 4 Níveis Oficiais de Teste de Software <em>(DS 2019 Q25)</em></h4>\n<ol>\n<li><strong>Teste de Unidade (Unitário):</strong> Verifica a <strong>menor unidade isolada</strong> do software (uma única função ou método, ex.: testar <code>calcularFrete(10)</code> sem acessar banco de dados real).</li>\n<li><strong>Teste de Integração:</strong> Verifica se <strong>módulos combinados</strong> conversam corretamente (ex.: Controller + Banco MySQL + Gateway de pagamento).</li>\n<li><strong>Teste de Sistema:</strong> Testa a aplicação inteira integrada de ponta a ponta simulando um ambiente de produção.</li>\n<li><strong>Teste de Aceitação (UAT):</strong> Validação final junto ao cliente/PO confirmando se os requisitos do contrato foram atendidos.</li>\n</ol>\n<hr />\n<h3 id=\"-parte-5--programação-orientada-a-objetos-poo-classes-objetos-e-os-4-pilares\">📚 Parte 5 — Programação Orientada a Objetos (POO): Classes, Objetos e os 4 Pilares</h3>\n<p>Na POO, trazemos coisas do mundo real para dentro do código usando dois conceitos base:</p>\n<ul>\n<li><strong>Classe:</strong> É o <strong>molde / projeto</strong> (ex.: a planta de um carro ou o formulário em branco de <code>ContaBancaria</code>, definindo <strong>Atributos</strong> = características/dados e <strong>Métodos</strong> = ações/comportamentos).</li>\n<li><strong>Objeto:</strong> É uma <strong>instância concreta criada em memória RAM</strong> a partir da classe (ex.: a conta real nº <code>1020-5</code> da <code>Ana</code>, com saldo <code>R$ 500</code>, e outra conta <code>9988-1</code> do <code>João</code>, com saldo <code>R$ 1200</code>).</li>\n</ul>\n<h4 id=\"-exemplo-real-comentado-com-os-4-pilares-da-poo-ds-2019-q27\">💻 Exemplo Real Comentado com os 4 Pilares da POO <em>(DS 2019 Q27)</em></h4>\n<div class=\"sourceCode\" id=\"cb1\"><pre class=\"sourceCode python\"><code class=\"sourceCode python\"><span id=\"cb1-1\"><a href=\"#cb1-1\" aria-hidden=\"true\"></a><span class=\"kw\">class</span> Animal:                           <span class=\"co\"># ABSTRAÇÃO: só atributos/métodos essenciais ao sistema</span></span>\n<span id=\"cb1-2\"><a href=\"#cb1-2\" aria-hidden=\"true\"></a>    <span class=\"kw\">def</span> <span class=\"fu\">__init__</span>(<span class=\"va\">self</span>, nome, peso):</span>\n<span id=\"cb1-3\"><a href=\"#cb1-3\" aria-hidden=\"true\"></a>        <span class=\"va\">self</span>.__nome <span class=\"op\">=</span> nome              <span class=\"co\"># ENCAPSULAMENTO: __ privado! Protegido de acesso direto externo</span></span>\n<span id=\"cb1-4\"><a href=\"#cb1-4\" aria-hidden=\"true\"></a>        <span class=\"va\">self</span>.__peso <span class=\"op\">=</span> peso</span>\n<span id=\"cb1-5\"><a href=\"#cb1-5\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-6\"><a href=\"#cb1-6\" aria-hidden=\"true\"></a>    <span class=\"kw\">def</span> get_nome(<span class=\"va\">self</span>):                 <span class=\"co\"># Interface pública segura para leitura controlada</span></span>\n<span id=\"cb1-7\"><a href=\"#cb1-7\" aria-hidden=\"true\"></a>        <span class=\"cf\">return</span> <span class=\"va\">self</span>.__nome</span>\n<span id=\"cb1-8\"><a href=\"#cb1-8\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-9\"><a href=\"#cb1-9\" aria-hidden=\"true\"></a>    <span class=\"kw\">def</span> emitir_som(<span class=\"va\">self</span>):               <span class=\"co\"># Método base</span></span>\n<span id=\"cb1-10\"><a href=\"#cb1-10\" aria-hidden=\"true\"></a>        <span class=\"cf\">return</span> <span class=\"st\">&quot;...&quot;</span></span>\n<span id=\"cb1-11\"><a href=\"#cb1-11\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-12\"><a href=\"#cb1-12\" aria-hidden=\"true\"></a><span class=\"kw\">class</span> Cachorro(Animal):                 <span class=\"co\"># HERANÇA: Cachorro herda nome, peso e get_nome() de Animal!</span></span>\n<span id=\"cb1-13\"><a href=\"#cb1-13\" aria-hidden=\"true\"></a>    <span class=\"kw\">def</span> emitir_som(<span class=\"va\">self</span>):               <span class=\"co\"># POLIMORFISMO: sobrescreve emitir_som() com comportamento próprio!</span></span>\n<span id=\"cb1-14\"><a href=\"#cb1-14\" aria-hidden=\"true\"></a>        <span class=\"cf\">return</span> <span class=\"st\">&quot;Au au!&quot;</span></span>\n<span id=\"cb1-15\"><a href=\"#cb1-15\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-16\"><a href=\"#cb1-16\" aria-hidden=\"true\"></a><span class=\"kw\">class</span> Gato(Animal):                     <span class=\"co\"># HERANÇA</span></span>\n<span id=\"cb1-17\"><a href=\"#cb1-17\" aria-hidden=\"true\"></a>    <span class=\"kw\">def</span> emitir_som(<span class=\"va\">self</span>):               <span class=\"co\"># POLIMORFISMO: mesmo nome de método, resposta diferente!</span></span>\n<span id=\"cb1-18\"><a href=\"#cb1-18\" aria-hidden=\"true\"></a>        <span class=\"cf\">return</span> <span class=\"st\">&quot;Miau!&quot;</span></span></code></pre></div>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Os 4 Pilares Oficiais da POO</th>\n<th style=\"text-align: left;\">Significado exato que cai na prova</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>1. Abstração</strong></td>\n<td style=\"text-align: left;\">Focar apenas nos atributos e comportamentos essenciais do problema real, ignorando detalhes irrelevantes.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>2. Encapsulamento</strong></td>\n<td style=\"text-align: left;\"><strong>Ocultar e proteger dados internos</strong> (<code>private</code>) para evitar alterações inválidas (ex.: <code>saldo = -99999</code>), liberando acesso controlado via métodos públicos (<code>depositar()</code>, <code>getSaldo()</code>).</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>3. Herança</strong></td>\n<td style=\"text-align: left;\">Uma classe filha (<strong>subclasse</strong>) reaproveita atributos e métodos de uma classe mãe (<strong>superclasse</strong>), criando especializações (<code>Gerente</code> herda de <code>Funcionario</code>).</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>4. Polimorfismo</strong></td>\n<td style=\"text-align: left;\"><em>\"Muitas formas\"</em>: objetos de classes diferentes respondem de maneira própria à mesma chamada de método (<code>emitir_som()</code> ou <code>calcularSalario()</code>).</td>\n</tr>\n</tbody>\n</table>\n<div class=\"callout callout-caution\">\n\n<p><strong>Pegadinha clássica (DS 2019 Q27):</strong> A banca pergunta quais são os <strong>4 Pilares da POO</strong> e coloca no meio palavras como <em>\"Atributo, Método, Classe, Compilação, Recursividade\"</em>. <strong>Classe, Objeto, Atributo e Método são ELEMENTOS básicos</strong>, mas os <strong>4 PILARES</strong> são exclusivamente <strong>Abstração, Encapsulamento, Herança e Polimorfismo</strong>!</p>\n</div>\n\n<hr />\n<h3 id=\"️️-dissecando-questões-no-estilo-exato-da-prova\">🕵️‍♂️ Dissecando Questões no Estilo Exato da Prova</h3>\n<h4 id=\"questão-resolvida-1-baseada-em-ds-2019-q12--apostas-q13--scrum\">Questão Resolvida 1 (Baseada em DS 2019 Q12 &amp; Apostas Q13 — Scrum)</h4>\n<p><em>Sobre o framework Scrum, julgue:</em></p>\n<ul>\n<li><em>I. O Scrum Master atua como gerente tradicional que atribui linhas de código e impõe prazos diários ao time.</em></li>\n<li><em>II. O Product Owner é o responsável por maximizar o valor do produto e priorizar o Product Backlog.</em></li>\n<li><em>III. A Daily Scrum é uma reunião diária de sincronização limitada a no máximo 15 minutos.</em> <strong>Análise:</strong> <strong>I é FALSO</strong> (Scrum Master é facilitador que remove impedimentos; o time é auto-organizável). <strong>II e III são VERDADEIROS</strong>.</li>\n</ul>\n<h4 id=\"questão-resolvida-2-baseada-em-ds-2019-q10--info-2025-q22--requisitos\">Questão Resolvida 2 (Baseada em DS 2019 Q10 &amp; INFO 2025 Q22 — Requisitos)</h4>\n<p><em>Um cliente exige que o sistema funcione sem modificações nos navegadores Chrome, Edge e Safari, e que responda em até 1,5 segundo com 1.000 usuários simultâneos. Essas exigências classificam-se, respectivamente, como:</em> <strong>Análise:</strong> Compatibilidade entre diferentes ambientes/plataformas é <strong>Portabilidade</strong>; limite de 1,5s é <strong>Desempenho</strong>. Ambos descrevem <em>como</em> o sistema se comporta, portanto são <strong>Requisitos Não Funcionais</strong>!</p>\n", "practiceType": "pairs", "practiceTag": "01_Programacao", "videoClips": [{"title": "Scrum // Dicionário do Programador", "channel": "Código Fonte TV", "videoId": "3aCww_1RnL0", "startSec": 120, "endSec": 500, "tip": "Foco: papéis (Product Owner, Scrum Master, Time), Sprints e Daily Scrum de 15 minutos."}, {"title": "Pilares da POO: Encapsulamento e Visão Geral", "channel": "Curso em Vídeo • Gustavo Guanabara", "videoId": "1wYRGFXpVlg", "startSec": 150, "endSec": 480, "tip": "Foco: visão geral dos 4 Pilares da POO e proteção interna de dados no Encapsulamento."}], "challengeRefs": [{"examId": "info2025", "qNum": 22}, {"examId": "info2025", "qNum": 23}, {"examId": "info2025", "qNum": 24}, {"examId": "ds2019", "qNum": 8}, {"examId": "ds2019", "qNum": 10}, {"examId": "ds2019", "qNum": 12}, {"examId": "ds2019", "qNum": 24}, {"examId": "ds2019", "qNum": 25}, {"examId": "ds2019", "qNum": 27}, {"examId": "mtec2022", "qNum": 30}]}, {"day": 6, "title": "Banco de Dados & SQL (DDL, DML, DQL, DCL, TCL, COUNT) + NoSQL", "weight": "Máxima", "storyIntro": "Capítulo 6: Aprenda na prática a separar DDL (estrutura), DML (dados) e DQL (SELECT), além de COUNT(*), WHERE e bancos NoSQL.", "lessonHtml": "<h2 id=\"dia-6--banco-de-dados-relacional-sgbds-as-5-sublinguagens-sql-e-bancos-nosql\">Dia 6 — Banco de Dados Relacional, SGBDs, as 5 Sublinguagens SQL e Bancos NoSQL</h2>\n<h3 id=\"-contexto-no-mundo-real-por-que-sistemas-sérios-não-salvam-dados-em-arquivos-de-texto-ou-planilhas\">🎯 Contexto no Mundo Real: Por que Sistemas Sérios Não Salvam Dados em Arquivos de Texto ou Planilhas?</h3>\n<p>Imagine uma loja virtual vendendo o <strong>último iPhone do estoque</strong> para duas pessoas clicando em \"Comprar\" no mesmo milissegundo em São Paulo e em Campinas. Se os dados ficassem numa planilha do Excel compartilhada, os dois pedidos poderiam gravar \"estoque = 0\" vendendo 2 aparelhos onde só havia 1, sem falar na lentidão com 5 milhões de clientes cadastrados ou no risco de alguém abrir o arquivo e apagar tudo!</p>\n<p>Para resolver concorrência, velocidade de busca, permissões de usuários e integridade financeira, usamos um <strong>SGBD (<em>Sistema Gerenciador de Banco de Dados</em>)</strong> — como <strong>MySQL, PostgreSQL, Oracle Database, Microsoft SQL Server ou SQLite</strong> — conversando através da linguagem padrão <strong>SQL (<em>Structured Query Language</em>)</strong>. E quando precisamos armazenar catálogos gigantes e flexíveis estilo JSON de redes sociais ou cache em milissegundos, entra em cena o universo <strong>NoSQL</strong>.</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Onde ficam salvas todas as mensagens de um servidor do Discord, sua lista de amigos da Steam ou o ranking mundial do Fortnite? Dentro de <strong>Bancos de Dados (SQL e NoSQL)</strong>! Olha como as <strong>5 sublinguagens SQL</strong> aparecem nisso:</p>\n<ul>\n<li><strong>DDL (<code>CREATE</code>, <code>ALTER</code>, <code>DROP</code>):</strong> Mexe na <strong>estrutura</strong> — cria a tabela <code>jogadores</code>, adiciona a coluna <code>elo</code>, ou apaga a tabela inteira!</li>\n<li><strong>DML (<code>INSERT</code>, <code>UPDATE</code>, <code>DELETE</code>):</strong> Mexe nos <strong>registros dentro da tabela</strong> — grava uma nova partida (<code>INSERT</code>), sobe seu XP (<code>UPDATE</code>) ou apaga uma mensagem enviada no chat (<code>DELETE</code>).</li>\n<li><strong>DQL (<code>SELECT</code> + <code>COUNT(*)</code>):</strong> Faz a <strong>consulta</strong> — <em>\"Quantos jogadores têm elo Diamante (<code>SELECT COUNT(*) WHERE elo = 'Diamante'</code>)?\"</em>.</li>\n<li><strong>DCL (<code>GRANT</code>, <code>REVOKE</code>):</strong> É exatamente <strong>dar ou tirar cargo de Admin / Moderador</strong> no Discord para um usuário poder ler ou mexer nos registros!</li>\n<li><strong>TCL (<code>COMMIT</code>, <code>ROLLBACK</code>):</strong> É o sistema anti-golpe de <strong>Trade de Skins na Steam</strong>! Quando você troca uma faca por 3 skins com outro player, ou os dois itens trocam de dono ao mesmo tempo (<strong><code>COMMIT</code></strong>), ou se a internet cair no meio o banco desfaz tudo e ninguém é roubado (<strong><code>ROLLBACK</code></strong>)!</li>\n<li><strong>NoSQL (MongoDB / Redis):</strong> Guarda coisas flexíveis em JSON (cada personagem tem atributos diferentes no inventário sem coluna fixa) e status instantâneo na RAM (<em>\"Fulano está online jogando Valorant\"</em>).</li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--o-papel-do-sgbd-e-transações-acid\">📚 Parte 1 — O Papel do SGBD e Transações ACID</h3>\n<p>Um <strong>SGBD</strong> fica entre o seu programa (back-end PHP/Node/Java/Python) e os arquivos físicos no SSD/HD. Ele garante as propriedades <strong>ACID</strong> em transações bancárias e comerciais:</p>\n<ul>\n<li><strong>A — Atomicidade:</strong> \"Tudo ou nada\" (num Pix, ou tira do saldo de João <strong>e</strong> entra no saldo de Maria, ou desfaz ambos — nunca some no meio!).</li>\n<li><strong>C — Consistência:</strong> O banco nunca viola regras/chaves (<code>NOT NULL</code>, chaves estrangeiras).</li>\n<li><strong>I — Isolamento:</strong> Milhares de usuários consultando e comprando simultaneamente não corrompem uns aos outros.</li>\n<li><strong>D — Durabilidade:</strong> Confirmado com <code>COMMIT</code>, os dados sobrevivem mesmo se faltar energia elétrica 1 segundo depois.</li>\n</ul>\n<hr />\n<h3 id=\"-parte-2--as-5-sublinguagens-oficiais-da-sql-questão-garantida-na-prova\">📚 Parte 2 — As 5 Sublinguagens Oficiais da SQL (Questão Garantida na Prova!)</h3>\n<p>A <strong>SQL</strong> é dividida em <strong>5 subconjuntos especializados de comandos</strong>. A Fundação FAT adora criar tabelas misturando <strong>DDL</strong>, <strong>DML</strong> e <strong>DQL</strong> para confundir o candidato (<strong>DS 2025 Q11</strong>, <strong>DS 2019 Q7</strong>, <strong>Apostas Q16</strong>):</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: center;\">Sublinguagem</th>\n<th style=\"text-align: left;\">Sigla em Inglês</th>\n<th style=\"text-align: left;\">Comandos Principais</th>\n<th style=\"text-align: left;\">Onde atua? (Macete definitivo)</th>\n<th style=\"text-align: left;\">Analogia de uma Pasta/Tabela Excel</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>DDL</strong></td>\n<td style=\"text-align: left;\"><em>Data Definition Language</em> (Definição)</td>\n<td style=\"text-align: left;\"><strong><code>CREATE</code></strong>, <strong><code>ALTER</code></strong>, <strong><code>DROP</code></strong>, <code>TRUNCATE</code></td>\n<td style=\"text-align: left;\">Atua na <strong>ESTRUTURA (esqueleto)</strong> do banco: cria tabela, adiciona coluna, muda tipo de coluna, apaga a tabela inteira!</td>\n<td style=\"text-align: left;\"><strong>Construir, reformar ou demolir</strong> a estante de aço.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>DML</strong></td>\n<td style=\"text-align: left;\"><em>Data Manipulation Language</em> (Manipulação)</td>\n<td style=\"text-align: left;\"><strong><code>INSERT</code></strong>, <strong><code>UPDATE</code></strong>, <strong><code>DELETE</code></strong></td>\n<td style=\"text-align: left;\">Atua nos <strong>DADOS (linhas/registros)</strong> dentro da tabela já existente.</td>\n<td style=\"text-align: left;\"><strong>Colocar, trocar ou retirar</strong> pastas de dentro da estante.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>DQL</strong></td>\n<td style=\"text-align: left;\"><em>Data Query Language</em> (Consulta)</td>\n<td style=\"text-align: left;\"><strong><code>SELECT</code></strong> <em>(com <code>FROM</code>, <code>WHERE</code>, <code>JOIN</code>, <code>ORDER BY</code>)</em></td>\n<td style=\"text-align: left;\">Apenas <strong>CONSULTA / LÊ</strong> os dados sem alterá-los. <em>(Nota: alguns autores antigos põem dentro de DML, mas a <strong>FAT cobra separadamente como DQL</strong>!)</em></td>\n<td style=\"text-align: left;\"><strong>Procurar e ler</strong> uma pasta sem modificá-la.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>DCL</strong></td>\n<td style=\"text-align: left;\"><em>Data Control Language</em> (Controle)</td>\n<td style=\"text-align: left;\"><strong><code>GRANT</code></strong>, <strong><code>REVOKE</code></strong></td>\n<td style=\"text-align: left;\">Gerencia <strong>PERMISSÕES e SEGURANÇA</strong> de acesso de usuários.</td>\n<td style=\"text-align: left;\"><strong>Dar ou tomar a chave</strong> do arquivo de um funcionário.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>TCL</strong></td>\n<td style=\"text-align: left;\"><em>Transaction Control Language</em> (Transação)</td>\n<td style=\"text-align: left;\"><strong><code>BEGIN</code></strong>, <strong><code>COMMIT</code></strong>, <strong><code>ROLLBACK</code></strong>, <code>SAVEPOINT</code></td>\n<td style=\"text-align: left;\">Controla <strong>TRANSAÇÕES</strong>: confirma definitivamente (<code>COMMIT</code>) ou desfaz alterações (<code>ROLLBACK</code>) em caso de erro.</td>\n<td style=\"text-align: left;\"><strong>Carimbar \"Aprovado\"</strong> no Pix ou <strong>cancelar tudo</strong> se falhou.</td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"-script-sql-completo-comentado-linha-por-linha-do-zero-até-consultas-e-transações\">💻 Script SQL Completo Comentado Linha por Linha (Do Zero até Consultas e Transações)</h4>\n<div class=\"sourceCode\" id=\"cb1\"><pre class=\"sourceCode sql\"><code class=\"sourceCode sql\"><span id=\"cb1-1\"><a href=\"#cb1-1\" aria-hidden=\"true\"></a><span class=\"co\">-- ==================== 1. DDL (ESTRUTURA) ====================</span></span>\n<span id=\"cb1-2\"><a href=\"#cb1-2\" aria-hidden=\"true\"></a><span class=\"kw\">CREATE</span> <span class=\"kw\">TABLE</span> alunos (</span>\n<span id=\"cb1-3\"><a href=\"#cb1-3\" aria-hidden=\"true\"></a>    <span class=\"kw\">id</span> <span class=\"dt\">INT</span> <span class=\"kw\">PRIMARY</span> <span class=\"kw\">KEY</span> AUTO_INCREMENT,   <span class=\"co\">-- Identificador único obrigatório</span></span>\n<span id=\"cb1-4\"><a href=\"#cb1-4\" aria-hidden=\"true\"></a>    nome <span class=\"dt\">VARCHAR</span>(<span class=\"dv\">100</span>) <span class=\"kw\">NOT</span> <span class=\"kw\">NULL</span>,          <span class=\"co\">-- Texto variável até 100 letras</span></span>\n<span id=\"cb1-5\"><a href=\"#cb1-5\" aria-hidden=\"true\"></a>    turma <span class=\"dt\">VARCHAR</span>(<span class=\"dv\">10</span>),</span>\n<span id=\"cb1-6\"><a href=\"#cb1-6\" aria-hidden=\"true\"></a>    nota <span class=\"dt\">DECIMAL</span>(<span class=\"dv\">4</span>,<span class=\"dv\">2</span>)</span>\n<span id=\"cb1-7\"><a href=\"#cb1-7\" aria-hidden=\"true\"></a>);</span>\n<span id=\"cb1-8\"><a href=\"#cb1-8\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-9\"><a href=\"#cb1-9\" aria-hidden=\"true\"></a><span class=\"co\">-- Esqueci a coluna de email! Uso ALTER TABLE (DDL) para modificar a estrutura:</span></span>\n<span id=\"cb1-10\"><a href=\"#cb1-10\" aria-hidden=\"true\"></a><span class=\"kw\">ALTER</span> <span class=\"kw\">TABLE</span> alunos <span class=\"kw\">ADD</span> email <span class=\"dt\">VARCHAR</span>(<span class=\"dv\">120</span>);</span>\n<span id=\"cb1-11\"><a href=\"#cb1-11\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-12\"><a href=\"#cb1-12\" aria-hidden=\"true\"></a><span class=\"co\">-- ==================== 2. DML (REGISTROS / LINHAS) ====================</span></span>\n<span id=\"cb1-13\"><a href=\"#cb1-13\" aria-hidden=\"true\"></a><span class=\"kw\">INSERT</span> <span class=\"kw\">INTO</span> alunos (nome, turma, nota, email)</span>\n<span id=\"cb1-14\"><a href=\"#cb1-14\" aria-hidden=\"true\"></a><span class=\"kw\">VALUES</span></span>\n<span id=\"cb1-15\"><a href=\"#cb1-15\" aria-hidden=\"true\"></a>    (<span class=\"st\">&#39;Lucas Ferreira&#39;</span>, <span class=\"st\">&#39;2MTEC&#39;</span>, <span class=\"fl\">8.50</span>, <span class=\"st\">&#39;lucas@etec.sp.gov.br&#39;</span>),</span>\n<span id=\"cb1-16\"><a href=\"#cb1-16\" aria-hidden=\"true\"></a>    (<span class=\"st\">&#39;Ana Beatriz&#39;</span>,    <span class=\"st\">&#39;2MTEC&#39;</span>, <span class=\"fl\">9.20</span>, <span class=\"st\">&#39;ana@etec.sp.gov.br&#39;</span>),</span>\n<span id=\"cb1-17\"><a href=\"#cb1-17\" aria-hidden=\"true\"></a>    (<span class=\"st\">&#39;Bruno Costa&#39;</span>,    <span class=\"st\">&#39;1MTEC&#39;</span>, <span class=\"fl\">5.80</span>, <span class=\"st\">&#39;bruno@etec.sp.gov.br&#39;</span>),</span>\n<span id=\"cb1-18\"><a href=\"#cb1-18\" aria-hidden=\"true\"></a>    (<span class=\"st\">&#39;Carla Dias&#39;</span>,     <span class=\"st\">&#39;2MTEC&#39;</span>, <span class=\"fl\">7.00</span>, <span class=\"st\">&#39;carla@etec.sp.gov.br&#39;</span>);</span>\n<span id=\"cb1-19\"><a href=\"#cb1-19\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-20\"><a href=\"#cb1-20\" aria-hidden=\"true\"></a><span class=\"co\">-- Bruno fez recuperação e foi para 6.50. ATENÇÃO AO WHERE!!</span></span>\n<span id=\"cb1-21\"><a href=\"#cb1-21\" aria-hidden=\"true\"></a><span class=\"kw\">UPDATE</span> alunos <span class=\"kw\">SET</span> nota <span class=\"op\">=</span> <span class=\"fl\">6.50</span> <span class=\"kw\">WHERE</span> <span class=\"kw\">id</span> <span class=\"op\">=</span> <span class=\"dv\">3</span>;</span>\n<span id=\"cb1-22\"><a href=\"#cb1-22\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-23\"><a href=\"#cb1-23\" aria-hidden=\"true\"></a><span class=\"co\">-- Se quiser remover apenas o aluno de id = 3 (tabela continua existindo!):</span></span>\n<span id=\"cb1-24\"><a href=\"#cb1-24\" aria-hidden=\"true\"></a><span class=\"kw\">DELETE</span> <span class=\"kw\">FROM</span> alunos <span class=\"kw\">WHERE</span> <span class=\"kw\">id</span> <span class=\"op\">=</span> <span class=\"dv\">3</span>;</span>\n<span id=\"cb1-25\"><a href=\"#cb1-25\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-26\"><a href=\"#cb1-26\" aria-hidden=\"true\"></a><span class=\"co\">-- ==================== 3. DQL (CONSULTAS / LEITURA) ====================</span></span>\n<span id=\"cb1-27\"><a href=\"#cb1-27\" aria-hidden=\"true\"></a><span class=\"co\">-- Listar nome e nota dos aprovados do 2MTEC ordenados da maior nota para a menor:</span></span>\n<span id=\"cb1-28\"><a href=\"#cb1-28\" aria-hidden=\"true\"></a><span class=\"kw\">SELECT</span> nome, nota</span>\n<span id=\"cb1-29\"><a href=\"#cb1-29\" aria-hidden=\"true\"></a><span class=\"kw\">FROM</span> alunos</span>\n<span id=\"cb1-30\"><a href=\"#cb1-30\" aria-hidden=\"true\"></a><span class=\"kw\">WHERE</span> turma <span class=\"op\">=</span> <span class=\"st\">&#39;2MTEC&#39;</span> <span class=\"kw\">AND</span> nota <span class=\"op\">&gt;=</span> <span class=\"fl\">6.0</span></span>\n<span id=\"cb1-31\"><a href=\"#cb1-31\" aria-hidden=\"true\"></a><span class=\"kw\">ORDER</span> <span class=\"kw\">BY</span> nota <span class=\"kw\">DESC</span>;</span>\n<span id=\"cb1-32\"><a href=\"#cb1-32\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-33\"><a href=\"#cb1-33\" aria-hidden=\"true\"></a><span class=\"co\">-- ==================== 4. DCL &amp; 5. TCL ====================</span></span>\n<span id=\"cb1-34\"><a href=\"#cb1-34\" aria-hidden=\"true\"></a><span class=\"kw\">GRANT</span> <span class=\"kw\">SELECT</span> <span class=\"kw\">ON</span> alunos <span class=\"kw\">TO</span> professor_estagiario;  <span class=\"co\">-- DCL: dá permissão apenas de leitura</span></span>\n<span id=\"cb1-35\"><a href=\"#cb1-35\" aria-hidden=\"true\"></a><span class=\"kw\">REVOKE</span> <span class=\"kw\">SELECT</span> <span class=\"kw\">ON</span> alunos <span class=\"kw\">FROM</span> professor_estagiario; <span class=\"co\">-- DCL: retira a permissão</span></span>\n<span id=\"cb1-36\"><a href=\"#cb1-36\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-37\"><a href=\"#cb1-37\" aria-hidden=\"true\"></a><span class=\"cf\">BEGIN</span>;                                           <span class=\"co\">-- TCL: inicia bloco transacional seguro</span></span>\n<span id=\"cb1-38\"><a href=\"#cb1-38\" aria-hidden=\"true\"></a><span class=\"kw\">UPDATE</span> contas <span class=\"kw\">SET</span> saldo <span class=\"op\">=</span> saldo <span class=\"op\">-</span> <span class=\"dv\">100</span> <span class=\"kw\">WHERE</span> <span class=\"kw\">id</span> <span class=\"op\">=</span> <span class=\"dv\">1</span>;</span>\n<span id=\"cb1-39\"><a href=\"#cb1-39\" aria-hidden=\"true\"></a><span class=\"kw\">UPDATE</span> contas <span class=\"kw\">SET</span> saldo <span class=\"op\">=</span> saldo <span class=\"op\">+</span> <span class=\"dv\">100</span> <span class=\"kw\">WHERE</span> <span class=\"kw\">id</span> <span class=\"op\">=</span> <span class=\"dv\">2</span>;</span>\n<span id=\"cb1-40\"><a href=\"#cb1-40\" aria-hidden=\"true\"></a><span class=\"kw\">COMMIT</span>;                                          <span class=\"co\">-- TCL: grava os dois juntos! (Se desse erro, usaria ROLLBACK)</span></span></code></pre></div>\n<div class=\"callout callout-caution\">\n\n<p><strong>PEGADINHA Nº 1 (<code>DROP</code> vs <code>DELETE</code> — DS 2025 Q11):</strong></p>\n<ul>\n<li><code>DROP TABLE alunos;</code> é <strong>DDL</strong>: <strong>destrói a tabela inteira e seu desenho</strong>. Se rodar <code>SELECT * FROM alunos</code> depois, dá erro <em>\"Tabela não existe\"</em>.</li>\n<li><code>DELETE FROM alunos WHERE ...;</code> é <strong>DML</strong>: apaga <strong>linhas/registros</strong>, mas a estrutura da tabela continua viva!</li>\n<li>E <strong>esquecer o <code>WHERE</code></strong> num <code>UPDATE</code> ou <code>DELETE</code> altera ou apaga <strong>TODAS as linhas da tabela</strong>!</li>\n</ul>\n</div>\n\n<hr />\n<h3 id=\"-parte-3--dominando-where-operadores-lógicos-e-funções-de-agregação-count\">📚 Parte 3 — Dominando <code>WHERE</code>, Operadores Lógicos e Funções de Agregação (<code>COUNT(*)</code>)</h3>\n<h4 id=\"1-ordem-mental-de-execução-do-select-info-2025-q28\">1. Ordem Mental de Execução do <code>SELECT</code> <em>(INFO 2025 Q28)</em></h4>\n<p>A cláusula <strong><code>WHERE</code></strong> serve exclusivamente para <strong>filtrar registros</strong> segundo condições verdadeiras ou falsas:</p>\n<ul>\n<li><code>WHERE cidade = 'São Paulo' AND idade &gt;= 18</code>: só traz se <strong>ambas</strong> forem verdadeiras.</li>\n<li><code>WHERE turma = 'A' OR turma = 'B'</code>: basta <strong>uma</strong> ser verdadeira.</li>\n<li><code>WHERE nome LIKE 'An%'</code>: começa com <code>\"An\"</code> (<code>%</code> substitui qualquer sequência de caracteres).</li>\n<li><code>WHERE nota BETWEEN 6 AND 10</code>: intervalo fechado de 6 a 10.</li>\n<li><code>ORDER BY nome ASC</code> (crescente A–Z, padrão) ou <code>DESC</code> (decrescente Z–A / maior para menor).</li>\n</ul>\n<h4 id=\"2-count-sum-avg-max-e-min-ds-2025-q14\">2. <code>COUNT(*)</code>, <code>SUM()</code>, <code>AVG()</code>, <code>MAX()</code> e <code>MIN()</code> <em>(DS 2025 Q14)</em></h4>\n<p>Observe a diferença entre <strong>contar linhas</strong> e <strong>somar valores</strong> na tabela <code>vendas</code>:</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: center;\"><code>id_venda</code></th>\n<th style=\"text-align: left;\"><code>vendedor</code></th>\n<th style=\"text-align: left;\"><code>cidade</code></th>\n<th style=\"text-align: center;\"><code>valor</code></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><code>1</code></td>\n<td style=\"text-align: left;\">João</td>\n<td style=\"text-align: left;\">São Paulo</td>\n<td style=\"text-align: center;\"><code>200</code></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><code>2</code></td>\n<td style=\"text-align: left;\">Maria</td>\n<td style=\"text-align: left;\">Campinas</td>\n<td style=\"text-align: center;\"><code>500</code></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><code>3</code></td>\n<td style=\"text-align: left;\">Pedro</td>\n<td style=\"text-align: left;\">São Paulo</td>\n<td style=\"text-align: center;\"><code>150</code></td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li><code>SELECT COUNT(*) FROM vendas WHERE cidade = 'São Paulo';</code> → Retorna <strong><code>2</code></strong>! <em>(Existem <strong>2 linhas/vendas</strong> em São Paulo — <code>COUNT(*)</code> conta linhas, <strong>NÃO</strong> soma <code>200 + 150</code>!)</em></li>\n<li><code>SELECT SUM(valor) FROM vendas WHERE cidade = 'São Paulo';</code> → Retorna <strong><code>350</code></strong> (<code>200 + 150</code>, soma valores numéricos).</li>\n<li><code>SELECT AVG(valor) FROM vendas WHERE cidade = 'São Paulo';</code> → Retorna <strong><code>175</code></strong> (média aritmética: <code>350 / 2</code>).</li>\n<li><code>SELECT MAX(valor) FROM vendas;</code> → Retorna <strong><code>500</code></strong> | <code>MIN(valor)</code> → <strong><code>150</code></strong>.</li>\n</ul>\n<div class=\"callout callout-caution\">\n\n<p><strong>Pegadinha clássica da DS 2025 Q14:</strong> A banca escreve comandos SQL errados como <code>SELECT * FROM clientes WHERE COUNT(cidade) = 'São Paulo';</code> ou coloca <code>FROM</code> depois do <code>WHERE</code>. <strong>Regra inviolável da sintaxe SQL:</strong> <strong><code>COUNT(*)</code> fica SEMPRE na cláusula <code>SELECT</code></strong> (entre <code>SELECT</code> e <code>FROM</code>), e <strong>JAMAIS</strong> dentro do <code>WHERE</code>! A ordem fixa sempre é <strong><code>SELECT ... FROM ... WHERE ... ORDER BY ...</code></strong>.</p>\n</div>\n\n<hr />\n<h3 id=\"-parte-4--bancos-nosql-not-only-sql--info-2025-q29--apostas-q18\">📚 Parte 4 — Bancos NoSQL (<em>Not Only SQL</em> — INFO 2025 Q29 &amp; Apostas Q18)</h3>\n<p>O modelo relacional (SQL) exige tabelas rígidas com colunas pré-definidas (<em>schema</em> fixo) e cresce principalmente <strong>verticalmente</strong> (colocando um servidor mais caro/potente). Quando empresas como Netflix, Instagram e Amazon passaram a lidar com <strong>terabytes por dia de dados variados (Big Data)</strong> espalhados em milhares de servidores comuns (<strong>escalabilidade horizontal</strong>), popularizaram-se os bancos <strong>NoSQL</strong> (<em>\"Não Apenas SQL\"</em>).</p>\n<h4 id=\"características-centrais-do-nosql\">Características Centrais do NoSQL</h4>\n<ol>\n<li><strong>Esquema Flexível (<em>Schema-less</em>):</strong> Na mesma coleção de produtos, o tênis pode ter campo <code>numeracao: 41</code> e o notebook pode ter <code>ram_gb: 16</code>, sem precisar de <code>ALTER TABLE</code> nem deixar colunas cheias de <code>NULL</code>!</li>\n<li><strong>Escalabilidade Horizontal (<em>Sharding</em>):</strong> Fácil de dividir os dados entre dezenas/centenas de máquinas em rede.</li>\n<li><strong>Sem JOINs complexos:</strong> Prioriza velocidade de leitura armazenando objetos relacionados já aninhados juntos.</li>\n</ol>\n<h4 id=\"as-4-famílias-famosas-de-nosql\">As 4 Famílias Famosas de NoSQL</h4>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Família NoSQL</th>\n<th style=\"text-align: left;\">Como guarda os dados</th>\n<th style=\"text-align: left;\">Exemplos famosos</th>\n<th style=\"text-align: left;\">Caso de uso real</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>1. Documentos</strong></td>\n<td style=\"text-align: left;\">Objetos <strong>JSON / BSON</strong> flexíveis agrupados em coleções</td>\n<td style=\"text-align: left;\"><strong>MongoDB</strong>, CouchDB, Firebase Firestore</td>\n<td style=\"text-align: left;\">Catálogos de e-commerce, perfis de usuários, apps móveis</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>2. Chave-Valor (<em>Key-Value</em>)</strong></td>\n<td style=\"text-align: left;\">Dicionário gigante ultrarrápido na memória RAM (<code>chave -&gt; valor</code>)</td>\n<td style=\"text-align: left;\"><strong>Redis</strong>, Amazon DynamoDB</td>\n<td style=\"text-align: left;\">Cache de páginas, carrinhos temporários, tokens de sessão</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>3. Colunar (<em>Wide-Column</em>)</strong></td>\n<td style=\"text-align: left;\">Famílias de colunas esparsas otimizadas para escrita massiva</td>\n<td style=\"text-align: left;\">Apache <strong>Cassandra</strong>, HBase</td>\n<td style=\"text-align: left;\">Telemetria IoT de milhões de sensores, histórico de logs</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>4. Grafos (<em>Graph</em>)</strong></td>\n<td style=\"text-align: left;\">Nós (entidades) e arestas (conexões diretas)</td>\n<td style=\"text-align: left;\"><strong>Neo4j</strong></td>\n<td style=\"text-align: left;\">Redes sociais (<em>\"amigos de amigos\"</em>), detecção de fraudes, recomendações</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Exemplo real de Documento JSON no MongoDB (note como telefones e endereço moram aninhados sem precisar de JOIN!):</strong></p>\n<div class=\"sourceCode\" id=\"cb2\"><pre class=\"sourceCode json\"><code class=\"sourceCode json\"><span id=\"cb2-1\"><a href=\"#cb2-1\" aria-hidden=\"true\"></a><span class=\"fu\">{</span></span>\n<span id=\"cb2-2\"><a href=\"#cb2-2\" aria-hidden=\"true\"></a>  <span class=\"dt\">&quot;_id&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;user_901&quot;</span><span class=\"fu\">,</span></span>\n<span id=\"cb2-3\"><a href=\"#cb2-3\" aria-hidden=\"true\"></a>  <span class=\"dt\">&quot;nome&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;Henrique Silva&quot;</span><span class=\"fu\">,</span></span>\n<span id=\"cb2-4\"><a href=\"#cb2-4\" aria-hidden=\"true\"></a>  <span class=\"dt\">&quot;curso&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;DS M-Tec&quot;</span><span class=\"fu\">,</span></span>\n<span id=\"cb2-5\"><a href=\"#cb2-5\" aria-hidden=\"true\"></a>  <span class=\"dt\">&quot;telefones&quot;</span><span class=\"fu\">:</span> <span class=\"ot\">[</span><span class=\"st\">&quot;1199999-0001&quot;</span><span class=\"ot\">,</span> <span class=\"st\">&quot;1198888-0002&quot;</span><span class=\"ot\">]</span><span class=\"fu\">,</span></span>\n<span id=\"cb2-6\"><a href=\"#cb2-6\" aria-hidden=\"true\"></a>  <span class=\"dt\">&quot;endereco&quot;</span><span class=\"fu\">:</span> <span class=\"fu\">{</span> <span class=\"dt\">&quot;cidade&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;São Paulo&quot;</span><span class=\"fu\">,</span> <span class=\"dt\">&quot;uf&quot;</span><span class=\"fu\">:</span> <span class=\"st\">&quot;SP&quot;</span> <span class=\"fu\">}</span></span>\n<span id=\"cb2-7\"><a href=\"#cb2-7\" aria-hidden=\"true\"></a><span class=\"fu\">}</span></span></code></pre></div>\n<hr />\n<h3 id=\"️️-dissecando-questões-no-estilo-exato-da-prova\">🕵️‍♂️ Dissecando Questões no Estilo Exato da Prova</h3>\n<h4 id=\"questão-resolvida-1-baseada-em-ds-2025-q11--ds-2019-q7--sublinguagens-sql\">Questão Resolvida 1 (Baseada em DS 2025 Q11 &amp; DS 2019 Q7 — Sublinguagens SQL)</h4>\n<p><em>Considere as afirmações: I. Os comandos <code>CREATE</code>, <code>ALTER</code> e <code>DROP</code> fazem parte da DDL, responsável pela estrutura do banco. II. <code>SELECT</code> pertence à DQL, permitindo consultar registros sem modificar tabelas. III. <code>INSERT</code>, <code>UPDATE</code> e <code>DELETE</code> pertencem à TCL, pois salvam ou desfazem transações.</em></p>\n<ul>\n<li><strong>Item I:</strong> VERDADEIRO.</li>\n<li><strong>Item II:</strong> VERDADEIRO.</li>\n<li><strong>Item III:</strong> <strong>FALSO</strong>! <code>INSERT</code>, <code>UPDATE</code> e <code>DELETE</code> são <strong>DML</strong> (manipulação de dados). Quem pertence à <strong>TCL</strong> são <code>COMMIT</code>, <code>ROLLBACK</code> e <code>SAVEPOINT</code>.</li>\n</ul>\n<h4 id=\"questão-resolvida-2-baseada-em-ds-2025-q14--info-2025-q28\">Questão Resolvida 2 (Baseada em DS 2025 Q14 &amp; INFO 2025 Q28)</h4>\n<p><em>Para descobrir quantos alunos têm nota maior ou igual a 7 na tabela <code>notas</code>, qual comando SQL é sintaticamente e logicamente correto?</em></p>\n<ul>\n<li><code>A) SELECT COUNT(*) FROM notas WHERE nota &gt;= 7;</code> → <strong>CORRETA!</strong> Ordem exata <code>SELECT ... FROM ... WHERE ...</code> e <code>COUNT(*)</code> contando as linhas filtradas.</li>\n<li><em>B) SELECT * FROM notas WHERE COUNT(nota) &gt;= 7;</em> → <strong>ERRADA!</strong> <code>COUNT</code> jamais entra direto dentro do <code>WHERE</code>.</li>\n</ul>\n", "practiceType": "lab03", "practiceTag": "02_Banco_Dados", "videoClips": [{"title": "Criando o Primeiro Banco de Dados SQL (DDL)", "channel": "Curso em Vídeo • Gustavo Guanabara", "videoId": "m9YPlX0fcJk", "startSec": 180, "endSec": 570, "tip": "Foco: comandos DDL (CREATE DATABASE / CREATE TABLE) e tipos de dados SQL."}, {"title": "NoSQL // Dicionário do Programador", "channel": "Código Fonte TV", "videoId": "1B64oqE8PLs", "startSec": 60, "endSec": 350, "tip": "Foco: diferença entre SQL e NoSQL (Documentos JSON, Chave-Valor, Colunar e Grafos)."}], "challengeRefs": [{"examId": "ds2025", "qNum": 11}, {"examId": "ds2025", "qNum": 14}, {"examId": "info2025", "qNum": 28}, {"examId": "info2025", "qNum": 29}, {"examId": "info2025", "qNum": 30}, {"examId": "ds2019", "qNum": 7}, {"examId": "apostas", "qNum": 16}, {"examId": "apostas", "qNum": 18}, {"examId": "sim1", "qNum": 16}]}, {"day": 7, "title": "Modelagem (Conceitual/Lógico/Físico), DER, Chaves e Normalização 1FN–3FN", "weight": "Máxima", "storyIntro": "Capítulo 7: Entenda relação/tupla/atributo, PK vs. FK, atributo derivado, auto-relacionamento N:N e elimine células multivaloradas com a 1ª Forma Normal.", "lessonHtml": "<h2 id=\"dia-7--modelagem-de-dados-conceitual-lógico-físico-der-chaves-cardinalidades-e-normalização-1fn3fn\">Dia 7 — Modelagem de Dados (Conceitual, Lógico, Físico), DER, Chaves, Cardinalidades e Normalização (1FN–3FN)</h2>\n<h3 id=\"-contexto-no-mundo-real-por-que-bancos-mal-projetados-perdem-dados\">🎯 Contexto no Mundo Real: Por que Bancos Mal Projetados Perdem Dados?</h3>\n<p>Imagine uma escola que cria uma única planilhona gigante chamada <code>MATRICULAS</code> onde cada linha repete: nome do aluno, CPF, três telefones colados juntos na mesma célula (<code>\"11999-1111, 11888-2222\"</code>), nome do curso e telefone da coordenação do curso. Veja os <strong>3 pesadelos</strong> que acontecem nessa tabela não normalizada:</p>\n<ol>\n<li>Se 500 alunos cursarem <em>Desenvolvimento de Sistemas</em> e o telefone da coordenação mudar, você terá que atualizar 500 linhas (e se esquecer 1 linha, o banco fica inconsistente!).</li>\n<li>Se um professor criar um curso novo que ainda não tem nenhum aluno matriculado, você <strong>nem consegue cadastrar o curso</strong> porque precisa inventar um aluno para preencher a linha (<strong>anomalia de inserção</strong>)!</li>\n<li>Se o único aluno de um curso trancar a matrícula e for deletado, você <strong>perde para sempre o cadastro do curso</strong> (<strong>anomalia de exclusão</strong>)!</li>\n</ol>\n<p>Para evitar esses desastres reais, usamos a <strong>Modelagem em 3 Níveis</strong> e a <strong>Normalização (1FN, 2FN e 3FN)</strong>!</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Pensa no <strong>Discord</strong>: você pode mudar seu <em>username</em> e apelido no servidor toda semana, mas por trás existe um <strong><code>User ID</code> numérico único</strong> (<code>18 dígitos</code>) que <strong>nunca muda e nunca se repete</strong> — essa é sua <strong>Chave Primária (PK)</strong>!</p>\n<ul>\n<li><strong>Chave Estrangeira (FK) e <code>1:N</code>:</strong> Um servidor tem <strong>muitos</strong> canais de texto, mas cada canal pertence a <strong>um único</strong> servidor. A FK <code>id_servidor</code> sempre vai dentro da tabela <code>CANAIS</code> (lado <code>N</code>!).</li>\n<li><strong><code>N:N</code> (Muitos para Muitos):</strong> Um usuário entra em <strong>vários</strong> servidores do Discord, e um servidor tem <strong>vários</strong> usuários. Para ligar os dois no banco relacional, cria-se a <strong>3ª Tabela Associativa <code>MEMBROS_SERVIDOR</code></strong> (guardando <code>id_usuario FK</code> + <code>id_servidor FK</code> + cargos!).</li>\n<li><strong>Atributo Derivado:</strong> O texto <em>\"Conta criada há 3 anos\"</em> ou <em>\"Winrate: 58%\"</em> não precisa ficar salvo fixo — o sistema calcula na hora usando <code>data_criacao</code> ou <code>vitorias / partidas</code>!</li>\n<li><strong>1ª Forma Normal (1FN):</strong> Imagina salvar o inventário inteiro num texto só: <code>itens = \"Espada, Escudo, Poção\"</code>! Fica horrível para buscar ou dropar só a poção. Colocar na <strong>1FN</strong> significa ter <strong>apenas 1 valor atômico por célula</strong> (uma tabela separada <code>INVENTARIO</code> com 1 linha para cada item)!</li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--as-3-etapas-da-modelagem-de-dados-apostas-q14\">📚 Parte 1 — As 3 Etapas da Modelagem de Dados <em>(Apostas Q14)</em></h3>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Etapa</th>\n<th style=\"text-align: left;\">Nível de Abstração</th>\n<th style=\"text-align: left;\">Como é representada e para que serve</th>\n<th style=\"text-align: left;\">Exemplo na Etec</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>1. Modelo Conceitual</strong></td>\n<td style=\"text-align: left;\">Mais alto nível (próximo ao usuário/negócio)</td>\n<td style=\"text-align: left;\">Feito com <strong>DER (Diagrama Entidade-Relacionamento, notação de Peter Chen)</strong>. Mostra entidades, relacionamentos e atributos principais, <strong>100% independente de software/SGBD</strong>.</td>\n<td style=\"text-align: left;\">Retângulo <code>ALUNO</code> conectado pelo losango <code>CURSA</code> ao retângulo <code>DISCIPLINA</code> (<code>N:N</code>).</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>2. Modelo Lógico</strong></td>\n<td style=\"text-align: left;\">Intermediário (estrutural)</td>\n<td style=\"text-align: left;\">Converte o DER em <strong>Tabelas do Modelo Relacional</strong>, define <strong>Chaves Primárias (PK)</strong>, <strong>Chaves Estrangeiras (FK)</strong> e resolve relacionamentos <code>N:N</code> criando tabelas intermediárias. Ainda independe do fornecedor específico.</td>\n<td style=\"text-align: left;\"><code>ALUNO(id_aluno PK, nome)</code> / <code>DISCIPLINA(id_disc PK, titulo)</code> / <code>MATRICULA(id_aluno FK, id_disc FK, ano)</code>.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>3. Modelo Físico</strong></td>\n<td style=\"text-align: left;\">Mais próximo da máquina (implementação real)</td>\n<td style=\"text-align: left;\">Script <strong><code>CREATE TABLE</code></strong> escrito no dialeto exato do SGBD escolhido (MySQL, PostgreSQL, SQL Server), definindo tipos exatos (<code>INT</code>, <code>VARCHAR(80)</code>), índices, <em>constraints</em> e armazenamento.</td>\n<td style=\"text-align: left;\"><code>CREATE TABLE aluno (id_aluno INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(80) NOT NULL);</code></td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h3 id=\"-parte-2--vocabulário-formal-relacional--tipos-de-atributos-no-der\">📚 Parte 2 — Vocabulário Formal Relacional &amp; Tipos de Atributos no DER</h3>\n<p>Na prova teórica, a Fundação FAT exige a correspondência entre os nomes acadêmicos do <strong>Modelo Relacional (Edgar Codd)</strong> e os nomes práticos <em>(DS 2025 Q12)</em>:</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Nome Formal na Prova</th>\n<th style=\"text-align: left;\">Equivalente Prático</th>\n<th style=\"text-align: left;\">Exemplo</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Relação (<em>Relation</em>)</strong></td>\n<td style=\"text-align: left;\"><strong>Tabela</strong></td>\n<td style=\"text-align: left;\">A grade inteira <code>ALUNOS</code></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Tupla (<em>Tuple</em>)</strong></td>\n<td style=\"text-align: left;\"><strong>Linha / Registro</strong></td>\n<td style=\"text-align: left;\"><code>(1, 'Henrique', '2DS', '2010-05-14')</code> — representa um objeto/aluno completo</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Atributo (<em>Attribute</em>)</strong></td>\n<td style=\"text-align: left;\"><strong>Coluna / Campo</strong></td>\n<td style=\"text-align: left;\">A coluna <code>nome</code> ou <code>data_nascimento</code></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Domínio (<em>Domain</em>)</strong></td>\n<td style=\"text-align: left;\"><strong>Tipo e faixa de valores válidos</strong></td>\n<td style=\"text-align: left;\">Para <code>nota</code>, apenas decimais de <code>0.0</code> a <code>10.0</code></td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"os-4-tipos-de-atributos-no-der-apostas-q15\">Os 4 Tipos de Atributos no DER <em>(Apostas Q15)</em></h4>\n<ul>\n<li><strong>Atributo Simples (Atômico):</strong> Indivisível em partes menores com sentido próprio (ex.: <code>cpf</code>, <code>sexo</code>, <code>nota</code>).</li>\n<li><strong>Atributo Composto:</strong> Pode ser subdividido em vários sub-atributos menores (ex.: <code>Endereco</code> se divide em <code>logradouro</code>, <code>numero</code>, <code>bairro</code>, <code>cidade</code>, <code>cep</code>).</li>\n<li><strong>Atributo Multivalorado:</strong> Pode armazenar <strong>vários valores para uma mesma ocorrência</strong> da entidade (ex.: uma pessoa pode ter vários <code>telefones</code> ou vários <code>idiomas</code>; desenhado com elipse dupla no DER — na hora de ir para a 1FN no banco relacional, vira uma nova tabela!).</li>\n<li><strong>Atributo Derivado (Calculado):</strong> Seu valor <strong>não precisa ser armazenado fisicamente</strong>, pois é <strong>calculado em tempo real</strong> a partir de outros atributos guardados (ex.: <strong><code>idade</code></strong> calculada a partir da <code>data_nascimento</code>; <strong><code>valor_total</code></strong> = <code>quantidade * preco_unitario</code>; <strong><code>tempo_de_casa</code></strong> a partir de <code>data_admissao</code>). Desenhado com <strong>elipse pontilhada/tracejada</strong> no DER!</li>\n</ul>\n<hr />\n<h3 id=\"-parte-3--chaves-pk-fk-candidataalternativa-e-cardinalidades-ds-2019-q5-e-q9\">📚 Parte 3 — Chaves (<code>PK</code>, <code>FK</code>, Candidata/Alternativa) e Cardinalidades (<code>DS 2019 Q5 e Q9</code>)</h3>\n<h4 id=\"1-os-tipos-de-chaves\">1. Os Tipos de Chaves</h4>\n<ul>\n<li><strong>Chave Primária (<em>Primary Key</em> — <code>PK</code>):</strong> Atributo (ou conjunto mínimo de atributos — <em>PK Composta</em>) escolhido para <strong>identificar de forma única cada linha</strong> da tabela.\n<ul>\n<li><strong>Duas regras sagradas da PK:</strong> <strong>NUNCA pode ter valor repetido</strong> e <strong>NUNCA pode ser nula (<code>NULL</code>)</strong>!</li>\n</ul></li>\n<li><strong>Chave Candidata &amp; Chave Alternativa <em>(DS 2019 Q9)</em>:</strong> Suponha a tabela <code>FUNCIONARIO(id_func, cpf, rg, email, nome)</code>. Tanto <code>id_func</code>, quanto <code>cpf</code> e <code>email</code> identificam uma pessoa sem repetir — logo, todos são <strong>Chaves Candidatas</strong>. Escolhemos <code>id_func</code> como <strong>Chave Primária (PK)</strong>. Os outros candidatos únicos que sobraram (<code>cpf</code>, <code>email</code>) chamam-se <strong>Chaves Alternativas (<em>Alternate Keys</em>)</strong>!</li>\n<li><strong>Chave Estrangeira (<em>Foreign Key</em> — <code>FK</code>):</strong> É uma coluna em uma tabela B que armazena o valor da <strong>Chave Primária da tabela A</strong>, criando o vínculo entre as duas.\n<ul>\n<li><strong>Integridade Referencial:</strong> O SGBD impede gravar um <code>id_aluno = 999</code> numa tabela de <code>NOTAS</code> se não existir aluno <code>999</code> na tabela <code>ALUNOS</code>, e impede apagar um curso que ainda tenha alunos vinculados sem antes tratar as FKs!</li>\n</ul></li>\n</ul>\n<h4 id=\"2-cardinalidades-e-como-viram-tabelas-reais\">2. Cardinalidades e Como Viram Tabelas Reais</h4>\n<p>Representam quantos registros de uma tabela podem se ligar a quantos da outra:</p>\n<ol>\n<li><strong><code>1:1</code> (Um para Um):</strong> Ex.: <code>PAIS</code> — <code>PRESIDENTE</code> ou <code>FUNCIONARIO</code> — <code>CRACHA</code>. Cada lado liga a no máximo 1 do outro. A FK é colocada em um dos lados (geralmente no lado opcional).</li>\n<li><strong><code>1:N</code> (Um para Muitos):</strong> Ex.: Uma <code>TURMA</code> tem <strong>vários</strong> <code>ALUNOS</code>, e cada <code>ALUNO</code> pertence a <strong>1</strong> <code>TURMA</code>.\n<ul>\n<li><strong>Regra de ouro absoluta:</strong> Na modelagem lógica/SQL, <strong>a Chave Estrangeira (FK) SEMPRE vai para a tabela do lado <code>N</code> (Muitos)</strong>!</li>\n<li>Ou seja: <code>id_turma</code> fica dentro de <strong><code>ALUNO</code></strong> (nunca colocamos 40 colunas <code>id_aluno1, id_aluno2...</code> dentro de <code>TURMA</code>!).</li>\n</ul></li>\n<li><strong><code>N:N</code> (Muitos para Muitos):</strong> Ex.: Um <code>ALUNO</code> cursa <strong>várias</strong> <code>DISCIPLINAS</code> e uma <code>DISCIPLINA</code> tem <strong>vários</strong> <code>ALUNOS</code>.\n<ul>\n<li><strong>Como resolver em bancos relacionais?</strong> Como <code>N:N</code> não cabe diretamente com uma única FK de cada lado, <strong>criamos obrigatoriamente uma 3ª Tabela Associativa (Intermediária)</strong> — ex.: <code>MATRICULA(id_matricula PK, id_aluno FK, id_disciplina FK, media)</code> — que recebe as FKs das duas entidades originais!</li>\n</ul></li>\n<li><strong>Auto-relacionamento (Relacionamento Unário / Recursivo — <em>DS 2019 Q5</em>):</strong> Quando uma <strong>tabela se relaciona com ela mesma</strong>!\n<ul>\n<li>Exemplo clássico: Na tabela <code>FUNCIONARIO(id_func, nome, cargo, id_supervisor)</code>, alguns funcionários são supervisores de outros funcionários! Então a coluna <code>id_supervisor</code> é uma <strong>FK dentro da tabela <code>FUNCIONARIO</code> que aponta para a PK <code>id_func</code> da própria tabela <code>FUNCIONARIO</code></strong>!</li>\n</ul></li>\n</ol>\n<hr />\n<h3 id=\"-parte-4--normalização-passo-a-passo-1fn-2fn-e-3fn-na-prática\">📚 Parte 4 — Normalização Passo a Passo: 1FN, 2FN e 3FN na Prática!</h3>\n<p><strong>Normalizar</strong> é aplicar regras progressivas (Formas Normais) para eliminar redundâncias e anomalias de inserção/atualização/exclusão. Veja uma tabela caótica passar pelas <strong>3 Formas Normais</strong>:</p>\n<h4 id=\"tabela-original-fora-das-formas-normais-pedidos_baguncados\">Tabela Original Fora das Formas Normais (<code>PEDIDOS_BAGUNCADOS</code>)</h4>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: center;\"><code>id_pedido</code></th>\n<th style=\"text-align: center;\"><code>id_cliente</code></th>\n<th style=\"text-align: left;\"><code>nome_cliente</code></th>\n<th style=\"text-align: left;\"><code>telefones_cliente</code> <em>(vários juntos!)</em></th>\n<th style=\"text-align: center;\"><code>id_produto</code></th>\n<th style=\"text-align: left;\"><code>nome_produto</code></th>\n<th style=\"text-align: center;\"><code>qtd</code></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><code>101</code></td>\n<td style=\"text-align: center;\"><code>5</code></td>\n<td style=\"text-align: left;\">Lucas</td>\n<td style=\"text-align: left;\"><code>119999-1111, 118888-2222</code></td>\n<td style=\"text-align: center;\"><code>10</code></td>\n<td style=\"text-align: left;\">Teclado</td>\n<td style=\"text-align: center;\"><code>2</code></td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"-passo-1-primeira-forma-normal-1fn--a-campeã-de-provas-ds-2025-q13--ds-2019-q4\">🔹 Passo 1: Primeira Forma Normal (1FN) — <em>A CAMPEÃ DE PROVAS (DS 2025 Q13 &amp; DS 2019 Q4)</em></h4>\n<ul>\n<li><strong>Regra da 1FN:</strong> Todo atributo deve conter apenas <strong>valores atômicos (indivisíveis)</strong> — é proibido armazenar múltiplos valores separados por vírgula numa célula (atributos multivalorados) ou tabelas aninhadas (<em>grupos repetitivos</em>).</li>\n<li><strong>Como corrigimos na prática:</strong> Retiramos <code>telefones_cliente</code> da tabela e criamos uma nova tabela ligada por FK (<code>CLIENTES_TELEFONES</code>) com <strong>1 único número por linha</strong>:</li>\n</ul>\n<p><code>PEDIDOS_1FN</code>: <code>(id_pedido, id_produto [PK composta], id_cliente, nome_cliente, nome_produto, qtd)</code> <em>(agora todas as células são atômicas!)</em> <code>CLIENTES_TELEFONES</code>:</p>\n<ul>\n<li><code>(id_tel=1, id_cliente=5, numero='119999-1111')</code></li>\n<li><code>(id_tel=2, id_cliente=5, numero='118888-2222')</code></li>\n</ul>\n<h4 id=\"-passo-2-segunda-forma-normal-2fn--elimina-dependência-parcial\">🔹 Passo 2: Segunda Forma Normal (2FN) — <em>Elimina Dependência Parcial</em></h4>\n<ul>\n<li><strong>Regra da 2FN:</strong> Já estar na <strong>1FN</strong> <strong>+</strong> quando a Chave Primária for <strong>composta</strong> (<code>id_pedido + id_produto</code>), nenhuma coluna não-chave pode depender de <strong>apenas metade</strong> da chave!</li>\n<li>Olhe <code>PEDIDOS_1FN</code>: <code>qtd</code> depende do pedido <strong>e</strong> do produto (OK!). Mas <strong><code>nome_produto</code></strong> depende <strong>APENAS de <code>id_produto</code></strong> (não importa qual pedido seja!), e <code>id_cliente/nome_cliente</code> dependem só de <strong><code>id_pedido</code></strong>! Isso é <strong>dependência parcial</strong>!</li>\n<li><strong>Correção para 2FN:</strong> Separamos em 3 tabelas coerentes:\n<ul>\n<li><code>PEDIDO(id_pedido PK, id_cliente, nome_cliente)</code></li>\n<li><code>PRODUTO(id_produto PK, nome_produto)</code></li>\n<li><code>ITEM_PEDIDO(id_pedido FK, id_produto FK, qtd)</code> <em>(agora sim na 2FN!)</em></li>\n</ul></li>\n</ul>\n<h4 id=\"-passo-3-terceira-forma-normal-3fn--elimina-dependência-transitiva\">🔹 Passo 3: Terceira Forma Normal (3FN) — <em>Elimina Dependência Transitiva</em></h4>\n<ul>\n<li><strong>Regra da 3FN:</strong> Já estar na <strong>2FN</strong> <strong>+</strong> nenhuma coluna não-chave pode depender de <strong>outra coluna não-chave</strong> (tudo depende <em>\"da chave, apenas da chave e nada além da chave\"</em>).</li>\n<li>Olhe <code>PEDIDO(id_pedido PK, id_cliente, nome_cliente)</code>: <code>id_cliente</code> depende de <code>id_pedido</code>, mas <strong><code>nome_cliente</code> depende de <code>id_cliente</code></strong>, que NÃO é a chave primária da tabela <code>PEDIDO</code>! (Se Lucas casar e mudar de nome, teríamos que atualizar 50 pedidos dele!).</li>\n<li><strong>Correção para 3FN:</strong> Criamos a tabela <code>CLIENTE(id_cliente PK, nome_cliente)</code> e deixamos em <code>PEDIDO(id_pedido PK, id_cliente FK)</code>! <strong>Banco 100% normalizado, limpo e sem redundâncias!</strong></li>\n</ul>\n<hr />\n<h3 id=\"️️-dissecando-questões-no-estilo-exato-da-prova\">🕵️‍♂️ Dissecando Questões no Estilo Exato da Prova</h3>\n<h4 id=\"questão-resolvida-1-baseada-em-ds-2025-q13--ds-2019-q4--1fn\">Questão Resolvida 1 (Baseada em DS 2025 Q13 &amp; DS 2019 Q4 — 1FN)</h4>\n<p><em>Uma tabela <code>FORNECEDORES(cnpj, razao_social, telefones_contato)</code> armazena na coluna <code>telefones_contato</code> o texto <code>\"(11) 3333-1111; (11) 99999-2222\"</code>. Qual forma normal foi diretamente violada e como corrigir?</em> <strong>Análise:</strong> Uma célula contém dois valores (atributo multivalorado/não atômico). Isso viola diretamente a <strong>1ª Forma Normal (1FN)</strong>. Correção: criar tabela separada <code>TELEFONES_FORNECEDOR</code> referenciando <code>cnpj</code> por Chave Estrangeira, com apenas 1 telefone por registro/linha.</p>\n<h4 id=\"questão-resolvida-2-baseada-em-ds-2019-q5--apostas-q15--auto-relacionamento-e-atributo-derivado\">Questão Resolvida 2 (Baseada em DS 2019 Q5 &amp; Apostas Q15 — Auto-relacionamento e Atributo Derivado)</h4>\n<p><em>I. Em uma tabela <code>COLABORADOR</code>, o campo <code>id_lider</code> aponta para <code>id_colaborador</code> da própria tabela, configurando auto-relacionamento. II. O campo <code>valor_total</code> calculado multiplicando <code>quantidade * preco</code> no momento da consulta é um atributo derivado.</em> <strong>Análise:</strong> Ambos os itens são <strong>VERDADEIROS</strong>! Esse é o exemplo clássico de auto-relacionamento <code>1:N</code> e atributo derivado no DER.</p>\n", "practiceType": "lab03", "practiceTag": "02_Banco_Dados", "videoClips": [{"title": "Modelagem de Dados: Normalização e 1ª Forma Normal (1FN)", "channel": "Bóson Treinamentos", "videoId": "eRaAMNjCFYw", "startSec": 60, "endSec": 450, "tip": "Foco: como detectar células com múltiplos telefones e corrigir para a 1FN com tabela separada."}], "challengeRefs": [{"examId": "ds2025", "qNum": 12}, {"examId": "ds2025", "qNum": 13}, {"examId": "ds2019", "qNum": 4}, {"examId": "ds2019", "qNum": 5}, {"examId": "ds2019", "qNum": 9}, {"examId": "mtec2022", "qNum": 32}, {"examId": "apostas", "qNum": 14}, {"examId": "apostas", "qNum": 15}, {"examId": "sim1", "qNum": 15}]}, {"day": 8, "title": "Design Digital: Cores RGB/CMYK/Hex, Vetor vs. Bitmap, Gestalt e UX", "weight": "Alta", "storyIntro": "Capítulo 8: Veja ao vivo o zoom de 800% entre SVG vetorial e Bitmap raster, entenda Gestalt, Círculo Cromático, Tipografia Script e Heurísticas de Nielsen.", "lessonHtml": "<h2 id=\"dia-8--design-digital-teoria-das-cores-vetor-vs-bitmap-bancos-de-imagens-gestalt-tipografia-e-ux\">Dia 8 — Design Digital, Teoria das Cores, Vetor vs. Bitmap, Bancos de Imagens, Gestalt, Tipografia e UX</h2>\n<h3 id=\"-contexto-no-mundo-real-por-que-sistemas-técnicos-precisam-de-bom-design\">🎯 Contexto no Mundo Real: Por que Sistemas Técnicos Precisam de Bom Design?</h3>\n<p>Você já entrou em um site onde a letra cinza clara quase some no fundo branco, os botões ficam todos espremidos sem saber qual confirma a compra, ou a logomarca da empresa aparece toda quadriculada (\"pixelada\") quando você dá zoom no celular? Mesmo que o back-end SQL e o código JavaScript funcionem perfeitamente, um design errado faz o usuário abandonar o sistema em segundos — e pior, se mandar uma arte digital em <strong>RGB</strong> para a gráfica imprimir um banner, as cores saem escuras e erradas porque impressoras usam <strong>CMYK</strong>!</p>\n<p>A Fundação FAT dedica cerca de <strong>4 a 5 questões por prova</strong> diretamente a <strong>Design Digital, Cores, Gestalt, Tipografia e Experiência do Usuário (UX)</strong>.</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Todo setup de PC e todo jogo que você abre ilustra perfeitamente o módulo de Design Digital:</p>\n<ul>\n<li><strong>RGB vs. CMYK:</strong> Os LEDs do seu teclado/gabinete <strong>RGB</strong> e o monitor do seu PC funcionam emitindo <strong>LUZ</strong> (<code>Red, Green, Blue</code> de <code>0</code> a <code>255</code> — somou tudo dá luz <strong>branca</strong>!). Já se você imprimir um pôster físico do seu jogo favorito numa gráfica, a impressora usa cartuchos de <strong>TINTA CMYK</strong> (<em>Ciano, Magenta, Amarelo e Preto</em>).</li>\n<li><strong>Hexadecimal <code>#RRGGBB</code>:</strong> Sabe quando você escolhe a cor do cargo no Discord digitando <code>#5865F2</code> (Blurple do Discord) ou <code>#FF0000</code>? Aquilo é literalmente o <strong>RGB escrito em Hexadecimal</strong>!</li>\n<li><strong>Vetor (<code>.SVG</code>) vs. Bitmap (<code>.PNG</code>, <code>.JPG</code>):</strong> Já chegou com a câmera bem colada numa parede ou placa num jogo e percebeu os <strong>quadradinhos borrados (pixels)</strong>? Isso é imagem <strong>Bitmap / Raster</strong>! Já o ícone de mira, logos em <strong><code>.SVG</code></strong> ou fontes do jogo continuam <strong>100% lisos e nítidos</strong> seja em 720p ou dando zoom de 800% em 4K porque são feitos por <strong>fórmulas matemáticas (Vetor)</strong>!</li>\n<li><strong>Gestalt e Nielsen na HUD:</strong> No Discord, todos os canais de texto têm <code>#</code> e os de voz têm um alto-falante (Lei da <strong>Semelhança</strong>); os canais ficam agrupados debaixo da categoria certa (Lei da <strong>Proximidade</strong>); e o ícone de lixeira para deletar mensagem é <strong>Equivalência com o Mundo Real (Nielsen)</strong>!</li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--teoria-das-cores-rgb-hexadecimal-cmyk-e-círculo-cromático\">📚 Parte 1 — Teoria das Cores: RGB, Hexadecimal, CMYK e Círculo Cromático</h3>\n<h4 id=\"1-síntese-aditiva-rgb-vs-síntese-subtrativa-cmyk\">1. Síntese Aditiva (RGB) vs. Síntese Subtrativa (CMYK)</h4>\n<p>Por que existem dois sistemas principais de cores? Porque <strong>emissores de luz (telas)</strong> funcionam de forma oposta a <strong>pigmentos em papel (tintas)</strong>!</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Sistema</th>\n<th style=\"text-align: left;\">Nome e Canais</th>\n<th style=\"text-align: left;\">Natureza Física</th>\n<th style=\"text-align: left;\">Onde é usado</th>\n<th style=\"text-align: left;\">Mistura Máxima vs. Zero</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>RGB</strong></td>\n<td style=\"text-align: left;\"><strong>R</strong>ed (Vermelho), <strong>G</strong>reen (Verde), <strong>B</strong>lue (Azul)<br>Valores de <strong><code>0</code> a <code>255</code></strong> por canal (256³ = 16,7 milhões de cores)</td>\n<td style=\"text-align: left;\"><strong>Síntese Aditiva (LUZ)</strong> — quanto mais luz soma, mais claro fica!</td>\n<td style=\"text-align: left;\"><strong>Telas digitais</strong> (monitores, TVs, celulares, Web, Photoshop web)</td>\n<td style=\"text-align: left;\"><code>rgb(255, 255, 255)</code> = <strong>BRANCO</strong> (luz total)<br><code>rgb(0, 0, 0)</code> = <strong>PRETO</strong> (ausência de luz)</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Hexadecimal</strong></td>\n<td style=\"text-align: left;\"><code>#RRGGBB</code> — usando base 16 (<code>0–9</code> e <code>A–F</code>)</td>\n<td style=\"text-align: left;\">É o <strong>mesmo RGB traduzido para Hexadecimal!</strong></td>\n<td style=\"text-align: left;\"><strong>Código CSS / HTML</strong> e seletores de cor de UI</td>\n<td style=\"text-align: left;\"><code>#FFFFFF</code> = <strong>BRANCO</strong> (<code>255,255,255</code>)<br><code>#000000</code> = <strong>PRETO</strong> (<code>0,0,0</code>)<br><code>#FF0000</code> = Vermelho puro; <code>#2563EB</code> = Azul</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>CMYK</strong></td>\n<td style=\"text-align: left;\"><strong>C</strong>yan (Ciano), <strong>M</strong>agenta, <strong>Y</strong>ellow (Amarelo), blac<strong>K</strong> (Preto)<br>Valores de <strong><code>0%</code> a <code>100%</code></strong></td>\n<td style=\"text-align: left;\"><strong>Síntese Subtrativa (TINTA)</strong> — a tinta absorve luz refletida do papel branco.</td>\n<td style=\"text-align: left;\"><strong>Impressão gráfica</strong> (revistas, cartões de visita, banners, apostilas)</td>\n<td style=\"text-align: left;\"><code>0%, 0%, 0%, 0%</code> = papel branco<br>O <strong>K (Preto)</strong> existe porque misturar só C+M+Y gera marrom escuro impuro e gasta muita tinta.</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Como ler qualquer código Hexadecimal em 3 segundos:</strong> Divida <code>#RRGGBB</code> em 3 pares: os 2 primeiros dígitos são <strong>Vermelho (<code>RR</code>)</strong>, os 2 do meio são <strong>Verde (<code>GG</code>)</strong>, os 2 últimos são <strong>Azul (<code>BB</code>)</strong>. Como <code>00</code> = zero e <code>FF</code> = <code>255</code> (máximo):</p>\n<ul>\n<li><code>#00FF00</code> → zero vermelho, máximo verde, zero azul = <strong>Verde puro</strong>.</li>\n<li><code>#FFFF00</code> → máximo vermelho + máximo verde = na luz RGB dá <strong>Amarelo</strong>!</li>\n<li><code>#CCCCCC</code> ou <code>#808080</code> → os três canais com valor igual produzem sempre <strong>tons de Cinza</strong>!</li>\n</ul>\n<h4 id=\"2-círculo-cromático-e-harmonias-info-2025-q9--ds-2019-q13\">2. Círculo Cromático e Harmonias <em>(INFO 2025 Q9 &amp; DS 2019 Q13)</em></h4>\n<ul>\n<li><strong>Cores Primárias (Modelo RBY tradicional / arte):</strong> <strong>Vermelho, Amarelo e Azul</strong>. (Misturando duas primárias nascem as <strong>Secundárias</strong>: Laranja, Verde e Roxo; misturando primária + secundária nascem as <strong>Terciárias</strong>).</li>\n<li><strong>Cores Análogas:</strong> Ficam <strong>lado a lado</strong> no círculo cromático (ex.: verde + verde-amarelado + amarelo) → visual calmo e harmônico.</li>\n<li><strong>Cores Complementares:</strong> Ficam em <strong>lados diretamente opostos</strong> (180°) no círculo (ex.: azul × laranja; roxo × amarelo; vermelho × verde) → geram <strong>máximo contraste</strong> para chamar atenção em botões <em>Call-to-Action</em>!</li>\n<li><strong>Harmonia em Tríade <em>(DS 2019 Q13)</em>:</strong> Conjunto de <strong>3 cores equidistantes</strong> no círculo cromático (formam um triângulo equilátero de 120°, como Vermelho + Amarelo + Azul).</li>\n</ul>\n<div class=\"callout callout-caution\">\n\n<p><strong>Pegadinha da DS 2025 Q15 (Molde 2):</strong> A banca pede a alternativa com <em>\"exclusivamente padrões de representação de cores\"</em> e coloca como intrusos palavras como <strong>\"CSS\"</strong>, <strong>\"HTML\"</strong>, <strong>\"Primária\"</strong> ou <strong>\"Bitmap\"</strong> no meio de <code>RGB</code>, <code>CMYK</code> e <code>Hexadecimal</code>! Só são sistemas de cores: <strong><code>RGB</code></strong>, <strong><code>CMYK</code></strong>, <strong><code>Hexadecimal</code></strong> (e eventualmente <code>HSL</code>/<code>HSB</code>).</p>\n</div>\n\n<hr />\n<h3 id=\"-parte-2--imagem-vetorial-vs-bitmap-raster-rasterização-e-bancos-de-imagens\">📚 Parte 2 — Imagem Vetorial vs. Bitmap (Raster), Rasterização e Bancos de Imagens</h3>\n<p>Essa é uma das diferenças técnicas mais fáceis de visualizar e mais cobradas pela banca (<strong>DS 2025 Q18</strong> &amp; <strong>INFO 2025 Q10</strong>):</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Característica</th>\n<th style=\"text-align: left;\">Imagem Vetorial</th>\n<th style=\"text-align: left;\">Imagem Bitmap (Matricial / Raster)</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Como é formada</strong></td>\n<td style=\"text-align: left;\"><strong>Fórmulas e equações matemáticas</strong> (coordenadas de pontos, linhas, polígonos e curvas de Bézier)</td>\n<td style=\"text-align: left;\"><strong>Grade (matriz) fixa de pixels</strong> (milhares de quadradinhos coloridos)</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Quando dá zoom (800%)</strong></td>\n<td style=\"text-align: left;\"><strong>Recalcula a matemática na hora:</strong> bordas permanecem <strong>100% nítidas e lisas</strong>, sem jamais perder qualidade!</td>\n<td style=\"text-align: left;\"><strong>Pixela / serrilha:</strong> os quadrados individuais aumentam e a imagem fica <strong>borrada / quadriculada</strong>!</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Para que serve</strong></td>\n<td style=\"text-align: left;\"><strong>Logotipos, ícones, tipografia, ilustrações planas, gráficos técnicos</strong></td>\n<td style=\"text-align: left;\"><strong>Fotografias reais</strong> (onde milhões de variações de luz/pele não cabem em formas geométricas simples)</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Formatos na prova</strong></td>\n<td style=\"text-align: left;\"><strong><code>.SVG</code></strong> (web/HTML), <strong><code>.PDF</code></strong> (quando salva vetores), <strong><code>.AI</code></strong> (Illustrator), <strong><code>.CDR</code></strong> (CorelDraw), <strong><code>.EPS</code></strong></td>\n<td style=\"text-align: left;\"><strong><code>.JPEG</code>/<code>.JPG</code></strong> (compressão c/ perda para fotos, <strong>sem transparência</strong>), <strong><code>.PNG</code></strong> (compressão sem perda + <strong>suporta fundo transparente</strong>), <strong><code>.BMP</code></strong>, <strong><code>.GIF</code></strong>, <strong><code>.WEBP</code></strong></td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li><strong>O que é Rasterização? <em>(INFO 2025 Q10)</em>:</strong> É o processo de <strong>converter uma imagem vetorial em bitmap (grade de pixels)</strong> para ser exibida numa tela ou impressa (ex.: exportar um logo <code>.SVG</code> para <code>.PNG</code> em <code>1024×1024 px</code>).</li>\n<li><strong>Resolução: PPI vs. DPI:</strong> <strong>PPI</strong> (<em>Pixels Per Inch</em>) refere-se à densidade da tela digital; <strong>DPI</strong> (<em>Dots Per Inch</em>) refere-se aos pontos de tinta da impressora (<code>300 DPI</code> é o padrão de alta qualidade para impressão gráfica, enquanto <code>72–96 PPI</code> bastava para monitores antigos).</li>\n</ul>\n<h4 id=\"bancos-de-imagens-e-direitos-autorais-ds-2025-q16\">Bancos de Imagens e Direitos Autorais <em>(DS 2025 Q16)</em></h4>\n<p>Achar uma imagem no Google Imagens <strong>NÃO</strong> dá direito de uso comercial nem escolar livre!</p>\n<ul>\n<li><strong>Domínio Público / <code>CC0</code>:</strong> Autor liberou direitos ou prazo legal expirou — uso 100% livre até comercialmente.</li>\n<li><strong><em>Creative Commons</em> (<code>CC</code>):</strong> Licença padronizada gratuita onde o autor escolhe condições: <strong><code>BY</code></strong> (exige dar crédito ao autor), <strong><code>NC</code></strong> (proíbe uso comercial), <strong><code>ND</code></strong> (proíbe modificar/derivar).</li>\n<li><strong><em>Royalty-Free</em> (Livre de Royalties):</strong> Significa que você paga <strong>uma única vez</strong> (ou assina um banco como Shutterstock/Adobe Stock) e pode usar a foto várias vezes sem pagar taxa adicional por cada cópia impressa ou visualização. (<strong>Atenção:</strong> <em>\"Royalty-Free\"</em> NÃO significa necessariamente <em>\"de graça\"</em>, e sim <em>\"sem royalties recorrentes por tiragem\"</em>!).</li>\n</ul>\n<hr />\n<h3 id=\"-parte-3--princípios-da-gestalt-na-design--interfaces-ds-2025-q17\">📚 Parte 3 — Princípios da Gestalt na Design &amp; Interfaces <em>(DS 2025 Q17)</em></h3>\n<p>A <strong>Gestalt</strong> é uma escola da psicologia alemã que mostra como o cérebro humano <strong>organiza visualmente o todo antes das partes</strong>. Designers usam essas leis para deixar telas intuitivas:</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Lei da Gestalt</th>\n<th style=\"text-align: left;\">O que o cérebro faz</th>\n<th style=\"text-align: left;\">Exemplo real em Aplicativos / Interfaces Web</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>1. Proximidade</strong></td>\n<td style=\"text-align: left;\">Elementos <strong>fisicamente próximos</strong> são percebidos como pertencentes ao <strong>mesmo grupo</strong>.</td>\n<td style=\"text-align: left;\">Num formulário de cadastro, o texto <em>\"CPF:\"</em> fica bem colado à sua caixinha e mais afastado do campo <em>\"Senha:\"</em> abaixo — você não precisa de linha separando para saber qual rótulo pertence a qual caixa! <em>(Apostas Q21)</em></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>2. Semelhança</strong></td>\n<td style=\"text-align: left;\">Elementos com <strong>mesma cor, forma ou tamanho</strong> são interpretados como tendo a mesma função.</td>\n<td style=\"text-align: left;\">Todos os links clicáveis num texto são sublinhados e azuis; todos os botões principais do site têm o mesmo formato arredondado verde.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>3. Fechamento</strong></td>\n<td style=\"text-align: left;\">Quando uma figura tem traços interrompidos ou falhas, o cérebro <strong>completa os espaços vazios mentalmente</strong> para enxergar a forma fechada inteira.</td>\n<td style=\"text-align: left;\">Logotipo do panda da <strong>WWF</strong>, logo da <strong>IBM</strong> feito só com listras horizontais ou ícone de carregamento tracejado.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>4. Continuidade</strong></td>\n<td style=\"text-align: left;\">O olhar segue naturalmente o alinhamento contínuo de curvas ou linhas retas sem quebras bruscas.</td>\n<td style=\"text-align: left;\">Barra de progresso horizontal, carrossel de cards ou alinhamento de ícones em coluna numa barra lateral.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>5. Figura e Fundo</strong></td>\n<td style=\"text-align: left;\">O cérebro separa o <strong>objeto de foco (figura)</strong> do <strong>cenário (fundo)</strong>.</td>\n<td style=\"text-align: left;\">Modal de alerta escurecendo o resto do site atrás; alto contraste entre texto escuro e fundo claro garante legibilidade rápida.</td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h3 id=\"-parte-4--tipografia-google-fonts-e-heurísticas-de-nielsen-ux\">📚 Parte 4 — Tipografia, Google Fonts e Heurísticas de Nielsen (UX)</h3>\n<h4 id=\"1-classificação-tipográfica-ds-2019-q14--info-2025-q15\">1. Classificação Tipográfica <em>(DS 2019 Q14 &amp; INFO 2025 Q15)</em></h4>\n<ul>\n<li><strong>Fontes Serifadas</strong> (<em>Times New Roman</em>, <em>Georgia</em>): Possuem pequenos traços de acabamento (\"pezinhos\"/serifas) nas pontas das hastes, ajudando a guiar o olho em <strong>textos impressos longos</strong> (livros, jornais).</li>\n<li><strong>Fontes Sem Serifa (<em>Sans-Serif</em>)</strong> (<em>Arial</em>, <em>Roboto</em>, <em>Inter</em>, <em>Helvetica</em>): Hastes limpas e geométricas sem enfeites — padrão ouro para <strong>telas digitais, menus e apps</strong> pela nitidez mesmo em pixels pequenos.</li>\n<li><strong>Fontes <em>Script</em> / Caligráficas <em>(DS 2019 Q14)</em>:</strong> Imitam <strong>escrita à mão / letra cursiva fluida</strong>. São excelentes para convites elegantes, logotipos ou títulos decorativos, mas <strong>péssimas para parágrafos longos</strong> por cansarem a leitura!</li>\n<li><strong>Fontes Monoespaçadas</strong> (<em>Consolas</em>, <em>Fira Code</em>, <em>Courier New</em>): Cada letra ocupa exatamente a mesma largura — padrão em <strong>editores de código-fonte e terminais</strong> para alinhar indentação!</li>\n<li><strong>Google Fonts <em>(INFO 2025 Q15)</em>:</strong> Biblioteca online gratuita de fontes web que você importa com <code>&lt;link&gt;</code> no <code>&lt;head&gt;</code> do HTML (e usa no CSS via <code>font-family</code>), garantindo que o site exiba exatamente aquela fonte em qualquer PC/celular sem depender das fontes já instaladas no Windows do usuário!</li>\n</ul>\n<h4 id=\"2-ux--heurísticas-de-usabilidade-de-jakob-nielsen-ds-2019-q15\">2. UX &amp; Heurísticas de Usabilidade de Jakob Nielsen <em>(DS 2019 Q15)</em></h4>\n<p><strong>UI (<em>User Interface</em>)</strong> cuida da aparência visual (botões, cores, fontes); <strong>UX (<em>User Experience</em>)</strong> cuida de toda a jornada de satisfação, facilidade e eficiência do usuário ao resolver seu problema. As heurísticas de Nielsen mais cobradas:</p>\n<ol>\n<li><strong>Equivalência entre o sistema e o mundo real <em>(DS 2019 Q15)</em>:</strong> O sistema deve <strong>falar a linguagem e usar conceitos familiares do usuário</strong>, com metáforas reais e ordem lógica natural — ex.: usar o ícone de <strong>lixeira</strong> para apagar, <strong>carrinho de compras</strong> no e-commerce e texto <em>\"Sem conexão com a internet\"</em> em vez de <code>\"ERR_NETWORK_RESET_0x8004\"</code>.</li>\n<li><strong>Visibilidade do status do sistema:</strong> Manter o usuário informado do que está acontecendo em tempo hábil (barra de carregamento <code>%</code>, mensagem <em>\"Salvando...\"</em>, alerta <em>\"E-mail enviado!\"</em>).</li>\n<li><strong>Prevenção de erros:</strong> Mais vale impedir o erro do que exibir mensagem bonita depois — ex.: pedir confirmação <em>\"Tem certeza que deseja excluir sua conta permanentemente?\"</em> antes de apagar.</li>\n<li><strong>Consistência e padrões:</strong> Não mudar o significado de cores/ícones (botão vermelho normalmente é cancelar/excluir; disquete/nuvem é salvar).</li>\n</ol>\n<hr />\n<h3 id=\"️️-dissecando-questões-no-estilo-exato-da-prova\">🕵️‍♂️ Dissecando Questões no Estilo Exato da Prova</h3>\n<h4 id=\"questão-resolvida-1-baseada-em-ds-2025-q17--q18--vetor-e-gestalt\">Questão Resolvida 1 (Baseada em DS 2025 Q17 &amp; Q18 — Vetor e Gestalt)</h4>\n<p><em>Um designer criou um logotipo em SVG e precisou aplicá-lo tanto no ícone do app (48px) quanto num painel de 4 metros de altura sem serrilhamento. No layout da tela de login, colocou cada rótulo encostado em seu respectivo campo de texto e usou ícones vermelhos em todas as mensagens de erro. Identifique os conceitos aplicados:</em> <strong>Análise:</strong></p>\n<ul>\n<li>Logo em <strong><code>.SVG</code></strong> ampliado sem serrilhar = <strong>Imagem Vetorial</strong> (baseada em equações matemáticas, não pixels).</li>\n<li>Rótulo próximo ao campo formando unidade visual = Lei da <strong>Proximidade</strong> (Gestalt).</li>\n<li>Todos os erros com a mesma cor vermelha agrupados visualmente = Lei da <strong>Semelhança</strong> (Gestalt).</li>\n</ul>\n<h4 id=\"questão-resolvida-2-baseada-em-ds-2019-q15--info-2025-q9\">Questão Resolvida 2 (Baseada em DS 2019 Q15 &amp; INFO 2025 Q9)</h4>\n<p><em>Sobre Harmonia Cromática e UX: I. Cores análogas ficam frente a frente no círculo cromático buscando contraste máximo. II. Usar um ícone de carrinho de supermercado num site de vendas exemplifica a heurística de \"equivalência entre o sistema e o mundo real\" de Nielsen.</em> <strong>Análise:</strong> <strong>Item I é FALSO</strong> — quem fica em lados opostos buscando máximo contraste são as <strong>Complementares</strong> (Análogas ficam <em>lado a lado</em>). <strong>Item II é VERDADEIRO</strong>.</p>\n", "practiceType": "lab04", "practiceTag": "03_Design_Digital", "videoClips": [{"title": "RGB vs. CMYK e Vetor vs. Bitmap no Design", "channel": "Curso de Design Digital", "videoId": "wU6rwo-SeIw", "startSec": 15, "endSec": 215, "tip": "Foco: diferença visual rápida entre luz (RGB) vs. tinta (CMYK) e pixels vs. vetor no zoom."}], "challengeRefs": [{"examId": "ds2025", "qNum": 15}, {"examId": "ds2025", "qNum": 16}, {"examId": "ds2025", "qNum": 17}, {"examId": "ds2025", "qNum": 18}, {"examId": "info2025", "qNum": 9}, {"examId": "info2025", "qNum": 10}, {"examId": "info2025", "qNum": 15}, {"examId": "ds2019", "qNum": 13}, {"examId": "ds2019", "qNum": 14}, {"examId": "ds2019", "qNum": 15}]}, {"day": 9, "title": "Web Front-end: HTML5 Semântico, Links _blank, CSS Box Model, DOM e Cookies", "weight": "Máxima", "storyIntro": "Capítulo 9: Teste cookies locais (~4 KB, nunca na nuvem!), navegue na árvore DOM, domine tags HTML5, GET vs. POST e CSS Box Model / transform.", "lessonHtml": "<h2 id=\"dia-9--desenvolvimento-web-front-end-html5-semântico-links-tabelas-formulários-css-box-model-dom-e-cookies\">Dia 9 — Desenvolvimento Web Front-end: HTML5 Semântico, Links, Tabelas, Formulários, CSS Box Model, DOM e Cookies</h2>\n<h3 id=\"-contexto-no-mundo-real-o-que-acontece-quando-você-abre-um-site-no-navegador\">🎯 Contexto no Mundo Real: O que Acontece Quando Você Abre um Site no Navegador?</h3>\n<p>Quando você digita <code>www.etec.sp.gov.br</code> ou abre sua conta na Shopee pelo Chrome/Edge, seu navegador recebe arquivos de texto puro vindos de um servidor e precisa transformá-los em milissegundos numa tela interativa. Para fazer isso sem virar bagunça, toda página web moderna trabalha em <strong>3 camadas separadas</strong> (a <strong>Tríade da Web</strong>), além de contar com pequenos arquivos locais no navegador (<strong>Cookies</strong>) para lembrar que você já fez login ou que há 2 produtos no seu carrinho!</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Já apertou <strong><code>F12</code> (Inspecionar Elemento)</strong> no Chrome para ver ou zoar o texto de uma página no navegador (só na sua tela!)? Aquilo funciona porque você está manipulando o <strong>DOM</strong> ao vivo na sua memória!</p>\n<ul>\n<li><strong>HTML / CSS / JS no Discord Web / Twitch:</strong> O <strong>HTML</strong> monta as caixinhas de chat e lista de membros; o <strong>CSS Box Model</strong> dá o espaçamento interno dos balões de mensagem (<code>padding</code>), borda e distância entre usuários (<code>margin</code>); e o <strong>JavaScript + DOM</strong> faz aparecer uma mensagem nova no chat instantaneamente sem recarregar a aba inteira (<code>F5</code>)!</li>\n<li><strong>Cookies (~4 KB) no seu PC:</strong> Como o <strong>Discord Web</strong>, o YouTube e a Twitch lembram que você já está logado com autenticação em 2 fatores sem pedir senha toda vez que abre o Chrome? Através de um <strong>Cookie</strong> — um arquivinho de texto minúsculo (<strong>~4 KB</strong>) salvo <strong>LOCALMENTE dentro da pasta do navegador no SEU PC Windows 11</strong> (e <strong>NUNCA \"na nuvem\"</strong>!). Se você apagar os cookies do navegador, desloga na hora!</li>\n<li><strong><code>GET</code> vs. <code>POST</code>:</strong> Quando você pesquisa <code>?search_query=minecraft</code> no YouTube, vai pela URL (<strong><code>GET</code></strong>); quando digita senha para logar na Steam, vai escondido no corpo da requisição (<strong><code>POST</code></strong>)!</li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--a-tríade-da-web--anatomia-completa-de-uma-página-html5\">📚 Parte 1 — A Tríade da Web &amp; Anatomia Completa de uma Página HTML5</h3>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Camada</th>\n<th style=\"text-align: left;\">Papel Exato</th>\n<th style=\"text-align: left;\">Analogia da Construção de uma Casa</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>HTML5</strong> (<em>HyperText Markup Language</em>)</td>\n<td style=\"text-align: left;\"><strong>Estrutura e Conteúdo Semântico</strong> — diz o que cada elemento <em>é</em> (título, menu, parágrafo, tabela, botão). <em>(<strong>Atenção:</strong> HTML <strong>NÃO</strong> é linguagem de programação, é linguagem de <strong>marcação</strong>!)</em></td>\n<td style=\"text-align: left;\"><strong>Paredes, colunas, portas e janelas</strong> (estrutura bruta)</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>CSS3</strong> (<em>Cascading Style Sheets</em>)</td>\n<td style=\"text-align: left;\"><strong>Estilo Visual e Layout</strong> — cores, fontes, tamanhos, espaçamentos, grid, responsividade e animações.</td>\n<td style=\"text-align: left;\"><strong>Pintura, iluminação, decoração e móveis</strong></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>JavaScript (JS)</strong></td>\n<td style=\"text-align: left;\"><strong>Comportamento e Interatividade</strong> — validar senhas no clique, abrir menus, calcular carrinho e manipular o <strong>DOM</strong> sem recarregar a página.</td>\n<td style=\"text-align: left;\"><strong>Eletricidade, portão automático e automação</strong></td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"-código-real-comentado-página-html5-semântica-completa-m-tec-q3840--ds-2019-q16\">💻 Código Real Comentado: Página HTML5 Semântica Completa <em>(M-Tec Q38–40 &amp; DS 2019 Q16)</em></h4>\n<div class=\"sourceCode\" id=\"cb1\"><pre class=\"sourceCode html\"><code class=\"sourceCode html\"><span id=\"cb1-1\"><a href=\"#cb1-1\" aria-hidden=\"true\"></a><span class=\"dt\">&lt;!DOCTYPE </span>html<span class=\"dt\">&gt;</span>                    <span class=\"co\">&lt;!-- Declara ao navegador que o documento segue o padrão HTML5 --&gt;</span></span>\n<span id=\"cb1-2\"><a href=\"#cb1-2\" aria-hidden=\"true\"></a><span class=\"kw\">&lt;html</span><span class=\"ot\"> lang=</span><span class=\"st\">&quot;pt-BR&quot;</span><span class=\"kw\">&gt;</span>                <span class=\"co\">&lt;!-- Tag raiz: document.documentElement no DOM! --&gt;</span></span>\n<span id=\"cb1-3\"><a href=\"#cb1-3\" aria-hidden=\"true\"></a><span class=\"kw\">&lt;head&gt;</span>                             <span class=\"co\">&lt;!-- Cabeçalho INVISÍVEL: metadados, encoding, título da aba e links CSS --&gt;</span></span>\n<span id=\"cb1-4\"><a href=\"#cb1-4\" aria-hidden=\"true\"></a>    <span class=\"kw\">&lt;meta</span><span class=\"ot\"> charset=</span><span class=\"st\">&quot;UTF-8&quot;</span><span class=\"kw\">&gt;</span>         <span class=\"co\">&lt;!-- Garante acentos (ç, ã, é) corretos --&gt;</span></span>\n<span id=\"cb1-5\"><a href=\"#cb1-5\" aria-hidden=\"true\"></a>    <span class=\"kw\">&lt;title&gt;</span>Portal Etec DS<span class=\"kw\">&lt;/title&gt;</span>  <span class=\"co\">&lt;!-- Texto exibido na aba do navegador --&gt;</span></span>\n<span id=\"cb1-6\"><a href=\"#cb1-6\" aria-hidden=\"true\"></a>    <span class=\"kw\">&lt;link</span><span class=\"ot\"> rel=</span><span class=\"st\">&quot;stylesheet&quot;</span><span class=\"ot\"> href=</span><span class=\"st\">&quot;estilos.css&quot;</span><span class=\"kw\">&gt;</span></span>\n<span id=\"cb1-7\"><a href=\"#cb1-7\" aria-hidden=\"true\"></a><span class=\"kw\">&lt;/head&gt;</span></span>\n<span id=\"cb1-8\"><a href=\"#cb1-8\" aria-hidden=\"true\"></a><span class=\"kw\">&lt;body&gt;</span>                             <span class=\"co\">&lt;!-- CORPO VISÍVEL: tudo que o usuário enxerga na janela --&gt;</span></span>\n<span id=\"cb1-9\"><a href=\"#cb1-9\" aria-hidden=\"true\"></a>    <span class=\"kw\">&lt;header&gt;</span>                       <span class=\"co\">&lt;!-- Tag semântica: cabeçalho do site ou seção --&gt;</span></span>\n<span id=\"cb1-10\"><a href=\"#cb1-10\" aria-hidden=\"true\"></a>        <span class=\"kw\">&lt;h1&gt;</span>Desenvolvimento de Sistemas<span class=\"kw\">&lt;/h1&gt;</span></span>\n<span id=\"cb1-11\"><a href=\"#cb1-11\" aria-hidden=\"true\"></a>        <span class=\"kw\">&lt;nav&gt;</span>                      <span class=\"co\">&lt;!-- Tag semântica: barra de menu com links de navegação --&gt;</span></span>\n<span id=\"cb1-12\"><a href=\"#cb1-12\" aria-hidden=\"true\"></a>            <span class=\"kw\">&lt;a</span><span class=\"ot\"> href=</span><span class=\"st\">&quot;horarios.html&quot;</span><span class=\"kw\">&gt;</span>Mesma Aba (_self padrão)<span class=\"kw\">&lt;/a&gt;</span></span>\n<span id=\"cb1-13\"><a href=\"#cb1-13\" aria-hidden=\"true\"></a>            <span class=\"kw\">&lt;a</span><span class=\"ot\"> href=</span><span class=\"st\">&quot;https://cps.sp.gov.br&quot;</span><span class=\"ot\"> target=</span><span class=\"st\">&quot;_blank&quot;</span><span class=\"ot\"> rel=</span><span class=\"st\">&quot;noopener&quot;</span><span class=\"kw\">&gt;</span>Site CPS (Nova Aba)<span class=\"kw\">&lt;/a&gt;</span></span>\n<span id=\"cb1-14\"><a href=\"#cb1-14\" aria-hidden=\"true\"></a>        <span class=\"kw\">&lt;/nav&gt;</span></span>\n<span id=\"cb1-15\"><a href=\"#cb1-15\" aria-hidden=\"true\"></a>    <span class=\"kw\">&lt;/header&gt;</span></span>\n<span id=\"cb1-16\"><a href=\"#cb1-16\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-17\"><a href=\"#cb1-17\" aria-hidden=\"true\"></a>    <span class=\"kw\">&lt;main&gt;</span>                         <span class=\"co\">&lt;!-- Tag semântica: conteúdo principal único da página --&gt;</span></span>\n<span id=\"cb1-18\"><a href=\"#cb1-18\" aria-hidden=\"true\"></a>        <span class=\"kw\">&lt;section&gt;</span>                  <span class=\"co\">&lt;!-- Seção temática dentro do conteúdo --&gt;</span></span>\n<span id=\"cb1-19\"><a href=\"#cb1-19\" aria-hidden=\"true\"></a>            <span class=\"kw\">&lt;article&gt;</span>              <span class=\"co\">&lt;!-- Conteúdo independente reutilizável (notícia, post, card) --&gt;</span></span>\n<span id=\"cb1-20\"><a href=\"#cb1-20\" aria-hidden=\"true\"></a>                <span class=\"kw\">&lt;h2&gt;</span>Edital de Vagas Remanescentes<span class=\"kw\">&lt;/h2&gt;</span></span>\n<span id=\"cb1-21\"><a href=\"#cb1-21\" aria-hidden=\"true\"></a>                <span class=\"kw\">&lt;p&gt;</span>Prova em <span class=\"kw\">&lt;span</span><span class=\"ot\"> class=</span><span class=\"st\">&quot;destaque&quot;</span><span class=\"kw\">&gt;</span>04 de dezembro<span class=\"kw\">&lt;/span&gt;</span>.<span class=\"kw\">&lt;/p&gt;</span></span>\n<span id=\"cb1-22\"><a href=\"#cb1-22\" aria-hidden=\"true\"></a>            <span class=\"kw\">&lt;/article&gt;</span></span>\n<span id=\"cb1-23\"><a href=\"#cb1-23\" aria-hidden=\"true\"></a>        <span class=\"kw\">&lt;/section&gt;</span></span>\n<span id=\"cb1-24\"><a href=\"#cb1-24\" aria-hidden=\"true\"></a>        <span class=\"kw\">&lt;div</span><span class=\"ot\"> class=</span><span class=\"st\">&quot;caixa-visual&quot;</span><span class=\"kw\">&gt;</span> <span class=\"co\">&lt;!-- DIV: contêiner GENÉRICO em bloco SEM valor semântico! --&gt;</span></span>\n<span id=\"cb1-25\"><a href=\"#cb1-25\" aria-hidden=\"true\"></a>            Aviso em bloco genérico.</span>\n<span id=\"cb1-26\"><a href=\"#cb1-26\" aria-hidden=\"true\"></a>        <span class=\"kw\">&lt;/div&gt;</span></span>\n<span id=\"cb1-27\"><a href=\"#cb1-27\" aria-hidden=\"true\"></a>    <span class=\"kw\">&lt;/main&gt;</span></span>\n<span id=\"cb1-28\"><a href=\"#cb1-28\" aria-hidden=\"true\"></a></span>\n<span id=\"cb1-29\"><a href=\"#cb1-29\" aria-hidden=\"true\"></a>    <span class=\"kw\">&lt;footer&gt;</span>                       <span class=\"co\">&lt;!-- Tag semântica: rodapé da página --&gt;</span></span>\n<span id=\"cb1-30\"><a href=\"#cb1-30\" aria-hidden=\"true\"></a>        <span class=\"kw\">&lt;p&gt;</span>© 2026 Etec M-Tec<span class=\"kw\">&lt;/p&gt;</span></span>\n<span id=\"cb1-31\"><a href=\"#cb1-31\" aria-hidden=\"true\"></a>    <span class=\"kw\">&lt;/footer&gt;</span></span>\n<span id=\"cb1-32\"><a href=\"#cb1-32\" aria-hidden=\"true\"></a><span class=\"kw\">&lt;/body&gt;</span></span>\n<span id=\"cb1-33\"><a href=\"#cb1-33\" aria-hidden=\"true\"></a><span class=\"kw\">&lt;/html&gt;</span></span></code></pre></div>\n<div class=\"callout callout-warning\">\n\n<p><strong>Pegadinhas clássicas de HTML5 na Banca:</strong></p>\n<ol>\n<li><strong><code>&lt;div&gt;</code> e <code>&lt;span&gt;</code> NÃO são tags semânticas!</strong> Elas servem apenas como caixas genéricas (<code>&lt;div&gt;</code> ocupa a largura inteira em bloco; <code>&lt;span&gt;</code> fica na mesma linha) quando nenhuma tag semântica faz sentido <em>(M-Tec 2022 Q38)</em>. Tags semânticas reais introduzidas no HTML5 incluem <code>&lt;header&gt;</code>, <code>&lt;nav&gt;</code>, <code>&lt;main&gt;</code>, <code>&lt;section&gt;</code>, <code>&lt;article&gt;</code>, <code>&lt;aside&gt;</code> e <code>&lt;footer&gt;</code> <em>(DS 2019 Q16)</em>.</li>\n<li><strong>Tag <code>&lt;a&gt;</code> e <code>target=\"_blank\"</code> <em>(DS 2025 Q20)</em>:</strong> O atributo <code>href</code> define o endereço de destino e <strong><code>target=\"_blank\"</code> força o link a abrir em uma NOVA ABA (ou nova janela)</strong>. O comportamento padrão (<code>target=\"_self\"</code>) abre na mesma aba atual.</li>\n<li><strong>Visível x Metadados:</strong> Tudo o que aparece na tela vai dentro de <strong><code>&lt;body&gt;</code></strong>, nunca dentro de <code>&lt;head&gt;</code> <em>(M-Tec 2022 Q40)</em>.</li>\n</ol>\n</div>\n\n<hr />\n<h3 id=\"-parte-2--listas-tabelas-html-e-formulários-http-get-vs-post\">📚 Parte 2 — Listas, Tabelas HTML e Formulários HTTP (<code>GET</code> vs. <code>POST</code>)</h3>\n<h4 id=\"1-listas-ol-vs-ul-m-tec-2022-q39\">1. Listas (<code>&lt;ol&gt;</code> vs. <code>&lt;ul&gt;</code>) <em>(M-Tec 2022 Q39)</em></h4>\n<ul>\n<li><strong><code>&lt;ol&gt;</code> (<em>Ordered List</em>):</strong> Lista <strong>ordenada / numerada</strong> (<code>1., 2., 3.</code> ou <code>a., b., c.</code>) — usada quando a sequência importa (ex.: receita passo a passo).</li>\n<li><strong><code>&lt;ul&gt;</code> (<em>Unordered List</em>):</strong> Lista <strong>não ordenada</strong> (marcadores <code>•</code>, quadradinhos) — usada para itens sem ordem fixa (ex.: menu de links, lista de compras).</li>\n<li>Dentro de <strong>ambas</strong>, cada item individual é envolvido pela tag <strong><code>&lt;li&gt;</code></strong> (<em>List Item</em>).</li>\n</ul>\n<h4 id=\"2-tabelas-html-table-tr-th-td-apostas-q24\">2. Tabelas HTML (<code>&lt;table&gt;</code>, <code>&lt;tr&gt;</code>, <code>&lt;th&gt;</code>, <code>&lt;td&gt;</code>) <em>(Apostas Q24)</em></h4>\n<div class=\"sourceCode\" id=\"cb2\"><pre class=\"sourceCode html\"><code class=\"sourceCode html\"><span id=\"cb2-1\"><a href=\"#cb2-1\" aria-hidden=\"true\"></a><span class=\"kw\">&lt;table&gt;</span></span>\n<span id=\"cb2-2\"><a href=\"#cb2-2\" aria-hidden=\"true\"></a>    <span class=\"kw\">&lt;thead&gt;</span></span>\n<span id=\"cb2-3\"><a href=\"#cb2-3\" aria-hidden=\"true\"></a>        <span class=\"kw\">&lt;tr&gt;</span>                        <span class=\"co\">&lt;!-- TR = Table Row: representa UMA LINHA inteira! --&gt;</span></span>\n<span id=\"cb2-4\"><a href=\"#cb2-4\" aria-hidden=\"true\"></a>            <span class=\"kw\">&lt;th&gt;</span>Matéria<span class=\"kw\">&lt;/th&gt;</span>        <span class=\"co\">&lt;!-- TH = Table Header: célula de cabeçalho (negrito/centralizada) --&gt;</span></span>\n<span id=\"cb2-5\"><a href=\"#cb2-5\" aria-hidden=\"true\"></a>            <span class=\"kw\">&lt;th&gt;</span>Nota<span class=\"kw\">&lt;/th&gt;</span></span>\n<span id=\"cb2-6\"><a href=\"#cb2-6\" aria-hidden=\"true\"></a>        <span class=\"kw\">&lt;/tr&gt;</span></span>\n<span id=\"cb2-7\"><a href=\"#cb2-7\" aria-hidden=\"true\"></a>    <span class=\"kw\">&lt;/thead&gt;</span></span>\n<span id=\"cb2-8\"><a href=\"#cb2-8\" aria-hidden=\"true\"></a>    <span class=\"kw\">&lt;tbody&gt;</span></span>\n<span id=\"cb2-9\"><a href=\"#cb2-9\" aria-hidden=\"true\"></a>        <span class=\"kw\">&lt;tr&gt;</span></span>\n<span id=\"cb2-10\"><a href=\"#cb2-10\" aria-hidden=\"true\"></a>            <span class=\"kw\">&lt;td&gt;</span>Banco de Dados<span class=\"kw\">&lt;/td&gt;</span> <span class=\"co\">&lt;!-- TD = Table Data: célula comum com dado --&gt;</span></span>\n<span id=\"cb2-11\"><a href=\"#cb2-11\" aria-hidden=\"true\"></a>            <span class=\"kw\">&lt;td&gt;</span>9.5<span class=\"kw\">&lt;/td&gt;</span></span>\n<span id=\"cb2-12\"><a href=\"#cb2-12\" aria-hidden=\"true\"></a>        <span class=\"kw\">&lt;/tr&gt;</span></span>\n<span id=\"cb2-13\"><a href=\"#cb2-13\" aria-hidden=\"true\"></a>    <span class=\"kw\">&lt;/tbody&gt;</span></span>\n<span id=\"cb2-14\"><a href=\"#cb2-14\" aria-hidden=\"true\"></a><span class=\"kw\">&lt;/table&gt;</span></span></code></pre></div>\n<p><strong>Pegadinha fatal:</strong> <strong><code>&lt;tr&gt;</code> cria uma LINHA</strong>; <strong><code>&lt;td&gt;</code> cria a CÉLULA (dado)</strong>! Nunca confunda <code>&lt;tr&gt;</code> com célula nem <code>&lt;td&gt;</code> com título!</p>\n<h4 id=\"3-formulários-html-methodget-vs-methodpost-apostas-q24\">3. Formulários HTML: <code>method=\"GET\"</code> vs. <code>method=\"POST\"</code> <em>(Apostas Q24)</em></h4>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Critério</th>\n<th style=\"text-align: left;\"><code>method=\"GET\"</code></th>\n<th style=\"text-align: left;\"><code>method=\"POST\"</code></th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Onde os dados viajam?</strong></td>\n<td style=\"text-align: left;\">Anexados diretamente ao <strong>final da URL</strong> após <code>?</code> (ex.: <code>busca.php?termo=sql&amp;pag=2</code>).</td>\n<td style=\"text-align: left;\">Enviados ocultos no <strong>corpo (<em>body</em>) da requisição HTTP</strong>.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Segurança e Limite</strong></td>\n<td style=\"text-align: left;\">Expostos na barra de endereços e no histórico do navegador! Tamanho limitado pelo navegador.</td>\n<td style=\"text-align: left;\"><strong>Não ficam expostos na URL!</strong> Suporta grandes volumes e upload de arquivos/imagens.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Quando usar na prática</strong></td>\n<td style=\"text-align: left;\">Pesquisas, filtros de busca, links compartilháveis.</td>\n<td style=\"text-align: left;\"><strong>Login (usuário e senha!), cadastros, pagamentos, envio de dados sensíveis.</strong></td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h3 id=\"-parte-3--css3-seletores-anatomia-da-regra-box-model-e-transform\">📚 Parte 3 — CSS3: Seletores, Anatomia da Regra, Box Model e <code>transform</code></h3>\n<h4 id=\"1-anatomia-da-regra-css-e-seletores-info-2025-q14\">1. Anatomia da Regra CSS e Seletores <em>(INFO 2025 Q14)</em></h4>\n<div class=\"sourceCode\" id=\"cb3\"><pre class=\"sourceCode css\"><code class=\"sourceCode css\"><span id=\"cb3-1\"><a href=\"#cb3-1\" aria-hidden=\"true\"></a><span class=\"co\">/* Seletor { propriedade: valor; } */</span></span>\n<span id=\"cb3-2\"><a href=\"#cb3-2\" aria-hidden=\"true\"></a>p { <span class=\"kw\">color</span>: <span class=\"cn\">#1e293b</span><span class=\"op\">;</span> }           <span class=\"co\">/* Seletor de TAG/ELEMENTO: atinge todos os &lt;p&gt; */</span></span>\n<span id=\"cb3-3\"><a href=\"#cb3-3\" aria-hidden=\"true\"></a><span class=\"fu\">.cartao</span> { <span class=\"kw\">padding</span>: <span class=\"dv\">16</span><span class=\"dt\">px</span><span class=\"op\">;</span> }      <span class=\"co\">/* Seletor de CLASSE (.): pode repetir em vários elementos */</span></span>\n<span id=\"cb3-4\"><a href=\"#cb3-4\" aria-hidden=\"true\"></a><span class=\"pp\">#menu-topo</span> { <span class=\"kw\">height</span>: <span class=\"dv\">60</span><span class=\"dt\">px</span><span class=\"op\">;</span> }    <span class=\"co\">/* Seletor de ID (#): identificador ÚNICO na página! */</span></span></code></pre></div>\n<p><em>(Lembre da especificidade: um seletor <code>#id</code> é mais forte que uma <code>.classe</code>, que é mais forte que uma <code>tag</code>!).</em></p>\n<h4 id=\"2-css-box-model-modelo-de-caixa--apostas-q25\">2. CSS Box Model (<em>Modelo de Caixa</em> — <em>Apostas Q25</em>)</h4>\n<p>Para o CSS, <strong>todo elemento HTML é uma caixa retangular</strong> formada por <strong>4 camadas concêntricas (de dentro para fora)</strong>:</p>\n<pre class=\"text\"><code>┌─────────────── MARGIN (espaço EXTERNO entre caixas vizinhas) ───────────────┐\n│ ┌───────────── BORDER (linha/borda visível da caixa) ───────────────────────┐ │\n│ │ ┌─────────── PADDING (acolchoamento INTERNO entre conteúdo e borda) ────┐ │ │\n│ │ │           CONTENT (texto, imagem: width x height)                     │ │ │\n│ │ └───────────────────────────────────────────────────────────────────────┘ │ │\n│ └───────────────────────────────────────────────────────────────────────────┘ │\n└───────────────────────────────────────────────────────────────────────────────┘\n</code></pre>\n<ul>\n<li><strong>Troca clássica na prova:</strong> Confundir <strong><code>padding</code></strong> (espaço <strong>entre o texto/conteúdo e a borda</strong>, dentro do fundo colorido do botão) com <strong><code>margin</code></strong> (espaço <strong>para fora da borda</strong>, empurrando outros elementos distantes).</li>\n</ul>\n<h4 id=\"3-propriedade-css3-transform-ds-2019-q17\">3. Propriedade CSS3 <code>transform</code> <em>(DS 2019 Q17)</em></h4>\n<p>Permite mover, girar, inclinar e redimensionar elementos 2D/3D sem quebrar o fluxo da página:</p>\n<ul>\n<li><code>transform: scale(1.3);</code> → <strong>Aumenta ou diminui proporcionalmente</strong> o tamanho (<code>1.3</code> = 130%).</li>\n<li><code>transform: rotate(45deg);</code> → <strong>Gira/rotaciona</strong> o elemento em graus.</li>\n<li><code>transform: translate(20px, -10px);</code> → <strong>Desloca/move</strong> horizontal e verticalmente.</li>\n<li><code>transform: skew(15deg, 5deg);</code> → <strong>Inclina/distorce</strong> o ângulo dos eixos.</li>\n</ul>\n<hr />\n<h3 id=\"-parte-4--a-árvore-dom-no-javascript-e-cookies-http\">📚 Parte 4 — A Árvore DOM no JavaScript e Cookies HTTP</h3>\n<h4 id=\"1-como-o-javascript-enxerga-a-página-dom-document-object-model--ds-2019-q19\">1. Como o JavaScript Enxerga a Página: DOM <em>(Document Object Model — DS 2019 Q19)</em></h4>\n<p>Quando o navegador lê o HTML, ele transforma cada tag em um <strong>nó de uma árvore hierárquica na memória RAM</strong> chamada <strong>DOM</strong>:</p>\n<ul>\n<li>Raiz da árvore: <code>document.documentElement</code> (o elemento <code>&lt;html&gt;</code>).</li>\n<li>Métodos clássicos cobrados pela banca FAT:\n<ul>\n<li><code>document.getElementById(\"aviso\")</code> → Captura o elemento que possui <code>id=\"aviso\"</code>.</li>\n<li><code>document.querySelector(\".card\")</code> → Captura usando qualquer seletor CSS.</li>\n<li><code>document.createElement(\"li\")</code> / <code>document.createTextNode(\"Novo item\")</code> → Cria novos nós HTML ou de texto em memória.</li>\n<li><code>pai.appendChild(filho)</code> → Encaixa o novo nó dentro da página viva.</li>\n<li><code>elemento.parentNode</code> → Sobe um degrau acessando o <strong>nó pai</strong> daquele elemento na árvore!</li>\n</ul></li>\n</ul>\n<h4 id=\"2-cookies-no-navegador-a-verdade-contra-a-pegadinha-ds-2025-q21\">2. Cookies no Navegador: A Verdade Contra a Pegadinha! <em>(DS 2025 Q21)</em></h4>\n<p>O protocolo HTTP é <em>stateless</em> (sem memória): por padrão, a cada clique num link, o servidor esquece quem você é! Para resolver isso, quando você faz login, o servidor pede ao seu navegador para gravar um <strong>Cookie</strong>.</p>\n<p><strong>Fatos oficiais sobre Cookies (decore cada um deles):</strong></p>\n<ol>\n<li><strong>O que são?</strong> Pequenos <strong>arquivos de texto simples</strong> (par <code>chave=valor</code>, ex.: <code>tema=escuro</code>).</li>\n<li><strong>Onde ficam armazenados?</strong> <strong>EXCLUSIVAMENTE NO NAVEGADOR / COMPUTADOR LOCAL DO USUÁRIO (CLIENTE)</strong>! Eles trafegam nos cabeçalhos HTTP entre cliente e servidor, mas <strong>NUNCA moram \"na nuvem\"</strong> como um banco remoto!</li>\n<li><strong>Qual o limite tradicional?</strong> Cerca de <strong>4 KB (~4.096 bytes)</strong> por cookie! Não servem para guardar vídeos, fotos ou bancos pesados.</li>\n<li><strong>Os 2 tipos quanto à validade:</strong>\n<ul>\n<li><strong>Cookie de Sessão (<em>Session Cookie</em>):</strong> Não define prazo de expiração (<code>Expires</code> / <code>Max-Age</code>). <strong>Apaga-se automaticamente assim que o navegador é fechado</strong>.</li>\n<li><strong>Cookie Persistente / Permanente:</strong> Tem data/tempo de expiração (<code>max-age=604800</code> para 7 dias). Continua salvo no disco do seu navegador mesmo após desligar e religar o PC!</li>\n</ul></li>\n<li><strong>Manipulação:</strong> Em JS lê/escreve via <code>document.cookie</code> (exceto quando o servidor ativa a flag de segurança <strong><code>HttpOnly</code></strong>, impedindo scripts maliciosos XSS de roubarem o cookie de sessão!).</li>\n<li><strong>Comparação rápida com Web Storage:</strong> Diferente de cookies (~4 KB enviados em toda requisição HTTP), <strong><code>localStorage</code></strong> e <strong><code>sessionStorage</code></strong> permitem guardar ~5–10 MB apenas localmente no navegador sem viajar em todo cabeçalho HTTP.</li>\n</ol>\n<hr />\n<h3 id=\"️️-dissecando-questões-no-estilo-exato-da-prova\">🕵️‍♂️ Dissecando Questões no Estilo Exato da Prova</h3>\n<h4 id=\"questão-resolvida-1-baseada-em-ds-2025-q21--cookies\">Questão Resolvida 1 (Baseada em DS 2025 Q21 — Cookies)</h4>\n<p><em>Analise as afirmativas sobre Cookies Web: I. Cookies são grandes arquivos multimídia armazenados diretamente nos servidores em nuvem da hospedagem. II. Cookies possuem tamanho pequeno (~4 KB) e ficam armazenados no navegador do usuário. III. Cookies podem ser temporários (de sessão, apagados ao fechar o browser) ou permanentes (com data de validade).</em></p>\n<ul>\n<li><strong>Item I é FALSO:</strong> Cookies são arquivos de <strong>texto pequenos (~4 KB)</strong> e ficam <strong>no navegador local do cliente</strong>, jamais na nuvem!</li>\n<li><strong>Itens II e III são VERDADEIROS.</strong></li>\n</ul>\n<h4 id=\"questão-resolvida-2-baseada-em-m-tec-q3839--apostas-q2425\">Questão Resolvida 2 (Baseada em M-Tec Q38–39 &amp; Apostas Q24–25)</h4>\n<p><em>Sobre HTML5 e CSS3: I. A tag <code>&lt;tr&gt;</code> representa uma célula de conteúdo na tabela e <code>&lt;td&gt;</code> cria uma linha. II. Formulários com senha devem usar <code>method=\"POST\"</code> em vez de <code>GET</code> para não expor os campos na URL. III. No CSS Box Model, <code>padding</code> é o espaçamento interno entre conteúdo e borda.</em></p>\n<ul>\n<li><strong>Item I é FALSO:</strong> É exatamente o contrário (<code>&lt;tr&gt;</code> = linha / <em>table row</em>; <code>&lt;td&gt;</code> = célula / <em>table data</em>).</li>\n<li><strong>Itens II e III são VERDADEIROS.</strong></li>\n</ul>\n", "practiceType": "lab01", "practiceTag": "04_Web_Redes_SO", "videoClips": [{"title": "Semântica na HTML5 é Importante", "channel": "Curso em Vídeo • Gustavo Guanabara", "videoId": "HaSgt1hK2Fs", "startSec": 180, "endSec": 570, "tip": "Foco: por que tags semânticas (<header>, <nav>, <main>, <footer>) substituíram o abuso de <div>."}, {"title": "Modelo de Caixas (Box Model): Primeiros Passos", "channel": "Curso em Vídeo • Gustavo Guanabara", "videoId": "3ZFYXkzXhqE", "startSec": 120, "endSec": 510, "tip": "Foco: diferença visual entre content, padding (interno), border e margin (externo)."}], "challengeRefs": [{"examId": "ds2025", "qNum": 20}, {"examId": "ds2025", "qNum": 21}, {"examId": "info2025", "qNum": 13}, {"examId": "info2025", "qNum": 14}, {"examId": "ds2019", "qNum": 16}, {"examId": "ds2019", "qNum": 17}, {"examId": "ds2019", "qNum": 19}, {"examId": "mtec2022", "qNum": 38}, {"examId": "apostas", "qNum": 24}, {"examId": "apostas", "qNum": 25}]}, {"day": 10, "title": "Binário/Hexadecimal, Hardware (RAM/SSD), SO, VMs/Docker e Linux", "weight": "Alta", "storyIntro": "Capítulo 10: Converta Decimal ↔ Binário/Hex interativamente, domine RAM vs. SSD, gerenciamento de memória/swap, Contêineres Docker vs. VM e comandos Linux.", "lessonHtml": "<h2 id=\"dia-10--sistemas-numéricos-bináriohexadecimal-hardware-memórias-so-vmsdocker-e-linux\">Dia 10 — Sistemas Numéricos (Binário/Hexadecimal), Hardware, Memórias, SO, VMs/Docker e Linux</h2>\n<h3 id=\"-contexto-no-mundo-real-de-bits-0-e-1-até-servidores-linux-na-nuvem\">🎯 Contexto no Mundo Real: De Bits <code>0 e 1</code> até Servidores Linux na Nuvem</h3>\n<p>Dentro do chip do seu celular ou notebook não existem letras <code>'A'</code>, números <code>255</code> nem cores azuis <code>#2563EB</code> flutuando soltos. Tudo — cada pixel da tela, cada música MP3 e cada comando Python — é convertido para sequências elétricas binárias (<strong><code>0</code></strong> sem tensão / <strong><code>1</code></strong> com tensão). Para economizar espaço ao exibir longas sequências de 8, 16 ou 32 bits em endereços de memória e cores CSS, engenheiros agrupam bits em <strong>Hexadecimal</strong>.</p>\n<p>Ao mesmo tempo, quando você abre o Windows ou roda servidores <strong>Linux</strong> usando <strong>Máquinas Virtuais</strong> ou <strong>Contêineres Docker</strong>, o <strong>Sistema Operacional</strong> precisa decidir o que fica na rápida <strong>Memória RAM</strong>, o que vai para o <strong>SSD</strong> e como organizar pastas do sistema sem deixar programas invadirem a memória uns dos outros.</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Se você já comparou placas/memórias, mexeu em pasta de jogo no Windows ou tentou hospedar um servidor de Minecraft/bot de Discord, você já conhece na prática o Dia 10:</p>\n<ul>\n<li><strong>SSD (Flash NAND) vs. HDD vs. RAM:</strong> Por que instalar GTA/Valorant no <strong>SSD</strong> carrega o mapa em 3 segundos enquanto no <strong>HD antigo (disco girando com agulha)</strong> trava por 1 minuto? Porque o SSD usa chips <strong>Flash NAND sem partes móveis</strong>. E a <strong>RAM</strong> guarda só o que está <strong>rodando aberto agora</strong> (desligou o PC da tomada, zera na hora!).</li>\n<li><strong>Por que o jogo dá <em>stuttering</em> quando falta RAM?</strong> Você abre Jogo pesado + Discord + 15 abas do Chrome numa máquina com pouca RAM. A RAM lota! Aí o <strong>Sistema Operacional</strong> usa <strong>Memória Virtual (Arquivo de Paginação / <em>Swap</em>)</strong>: pega partes da RAM e joga no <strong>SSD/HD</strong> para o PC não fechar os programas à força — como o SSD é bem mais lento que a RAM, o FPS cai na hora!</li>\n<li><strong>VM vs. Contêiner Docker:</strong> Subir um servidor dedicado de Minecraft ou bot de Discord dentro de uma <strong>VM</strong> (VirtualBox) é instalar um Windows/Linux inteiro virtualizado só pra isso (come GBs de RAM!). Subir via <strong>Contêiner Docker</strong> isola só o app e suas libs <strong>compartilhando o mesmo Kernel</strong> do servidor — inicia em segundos!</li>\n<li><strong>Binário &amp; Hex:</strong> Aquele clássico código de erro/cor <strong><code>255</code></strong> (ex.: <code>255.255.255.0</code> no roteador ou <code>rgb(255,0,0)</code>) existe porque <code>255</code> é exatamente <strong>1 Byte inteiro ligado (<code>11111111₂ = FF₁₆</code>)</strong>!</li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--conversão-passo-a-passo-decimal--binário-base-2--hexadecimal-base-16\">📚 Parte 1 — Conversão Passo a Passo: Decimal ↔︎ Binário (Base 2) ↔︎ Hexadecimal (Base 16)</h3>\n<h4 id=\"vocabulário-de-capacidade\">Vocabulário de Capacidade</h4>\n<ul>\n<li><strong>1 Bit (<em>Binary Digit</em>):</strong> Menor unidade de informação (<code>0</code> ou <code>1</code>).</li>\n<li><strong>1 Byte = 8 bits:</strong> Consegue representar <strong><code>2⁸ = 256</code> valores diferentes</strong> — em inteiros sem sinal, vai de <strong><code>0</code> (<code>00000000</code>) até <code>255</code> (<code>11111111</code>)</strong>! <em>(É por isso que IPs <code>192.168.0.255</code> e cores RGB <code>rgb(255, 255, 255)</code> param exatamente em <code>255</code>!)</em></li>\n</ul>\n<h4 id=\"a-como-converter-decimal--binário-2-métodos-para-conferir-na-prova\">A. Como Converter Decimal → Binário (2 Métodos para Conferir na Prova!)</h4>\n<p><strong>Método 1 — Régua das 8 Potências de 2 (o mais rápido na hora da prova!):</strong> Escreva as potências de 2 da direita para a esquerda em 8 casas: <code>128 | 64 | 32 | 16 | 8 | 4 | 2 | 1</code></p>\n<p>Vamos converter <strong><code>100₁₀</code></strong> <em>(DS 2019 Q20)</em>:</p>\n<ul>\n<li><code>128</code> cabe em 100? Não → bit <code>0</code></li>\n<li><strong><code>64</code></strong> cabe em 100? <strong>Sim</strong> → bit <strong><code>1</code></strong> (sobra <code>100 - 64 = 36</code>)</li>\n<li><strong><code>32</code></strong> cabe em 36? <strong>Sim</strong> → bit <strong><code>1</code></strong> (sobra <code>36 - 32 = 4</code>)</li>\n<li><code>16</code> cabe em 4? Não → bit <code>0</code></li>\n<li><code>8</code> cabe em 4? Não → bit <code>0</code></li>\n<li><strong><code>4</code></strong> cabe em 4? <strong>Sim</strong> → bit <strong><code>1</code></strong> (sobra <code>4 - 4 = 0</code>)</li>\n<li><code>2</code> → <code>0</code>, <code>1</code> → <code>0</code>. Resultado: <strong><code>01100100₂</code></strong> (ou <code>1100100₂</code>). Conferência: <code>64 + 32 + 4 = 100</code>!</li>\n</ul>\n<p><strong>Método 2 — Divisões Sucessivas por 2 (<code>DIV 2</code> e <code>MOD 2</code>):</strong> Para <strong><code>250₁₀</code></strong>:</p>\n<ul>\n<li><code>250 ÷ 2 = 125</code>, resto <strong><code>0</code></strong></li>\n<li><code>125 ÷ 2 = 62</code>, resto <strong><code>1</code></strong></li>\n<li><code>62 ÷ 2 = 31</code>, resto <strong><code>0</code></strong></li>\n<li><code>31 ÷ 2 = 15</code>, resto <strong><code>1</code></strong></li>\n<li><code>15 ÷ 2 = 7</code>, resto <strong><code>1</code></strong></li>\n<li><code>7 ÷ 2 = 3</code>, resto <strong><code>1</code></strong></li>\n<li><code>3 ÷ 2 = 1</code>, resto <strong><code>1</code></strong></li>\n<li><code>1 ÷ 2 = 0</code>, resto <strong><code>1</code></strong> Lendo os restos <strong>de baixo para cima</strong>: <strong><code>11111010₂</code></strong> (<code>128+64+32+16+8+2 = 250</code>)!</li>\n</ul>\n<h4 id=\"b-como-converter-decimal--binário--hexadecimal-base-16\">B. Como Converter Decimal / Binário ↔︎ Hexadecimal (Base 16)</h4>\n<p>Como só temos 10 algarismos (<code>0</code> a <code>9</code>), a Base 16 usa <strong>letras para representar de 10 a 15</strong>: <code>0..9</code> normal | <strong><code>A = 10</code></strong> | <strong><code>B = 11</code></strong> | <strong><code>C = 12</code></strong> | <strong><code>D = 13</code></strong> | <strong><code>E = 14</code></strong> | <strong><code>F = 15</code></strong>.</p>\n<p><strong>Regra direta:</strong> Divida por <strong><code>16</code></strong> ou separe o byte binário em <strong>dois blocos de 4 bits</strong> (cada grupo de 4 bits vale exatamente 1 dígito Hexadecimal, de <code>0</code> a <code>15</code>!):</p>\n<p>Veja dois exemplos reais da <strong>DS 2019 Q20</strong>:</p>\n<ol>\n<li><strong>Converter <code>100₁₀</code> para Hexadecimal:</strong>\n<ul>\n<li>Divisão por 16: <code>100 ÷ 16</code> = quociente <strong><code>6</code></strong> (<code>6 × 16 = 96</code>), resto <strong><code>4</code></strong>. Logo, <strong><code>64₁₆</code></strong>!</li>\n<li><em>(Conferindo pelos 4 bits: <code>0110 | 0100</code> → esquerda <code>4+2 = 6</code>, direita <code>4</code> → <code>64₁₆</code>!)</em></li>\n</ul></li>\n<li><strong>Converter <code>250₁₀</code> para Hexadecimal:</strong>\n<ul>\n<li>Divisão por 16: <code>250 ÷ 16</code> = quociente <strong><code>15</code></strong> (<code>15 × 16 = 240</code>), resto <strong><code>10</code></strong>.</li>\n<li>Troca números $\\ge 10$ pelas letras: <code>15 = F</code>, <code>10 = A</code>. Logo, <strong><code>FA₁₆</code></strong>!</li>\n<li><em>(Conferindo pelos 4 bits: <code>1111 | 1010</code> → esquerda <code>8+4+2+1 = 15 (F)</code>, direita <code>8+2 = 10 (A)</code> → <code>FA₁₆</code>!)</em></li>\n</ul></li>\n<li><strong>E <code>255₁₀</code> <em>(INFO 2025 Q4)</em>?</strong> <code>1111 1111₂</code> = <strong><code>FF₁₆</code></strong> (o máximo de <code>#RRGGBB</code> no CSS!).</li>\n</ol>\n<hr />\n<h3 id=\"-parte-2--arquitetura-de-hardware--hierarquia-de-memórias\">📚 Parte 2 — Arquitetura de Hardware &amp; Hierarquia de Memórias</h3>\n<p>Na arquitetura clássica de <strong>Von Neumann</strong>, o computador integra <strong>CPU</strong> (Processador: <strong>ULA</strong> faz cálculos/lógica, <strong>UC</strong> coordena o fluxo e <strong>Registradores</strong> guardam dados imediatos), <strong>Memória</strong> e <strong>Dispositivos de Entrada/Saída (E/S)</strong> interligados por barramentos.</p>\n<h4 id=\"hierarquia-de-memórias-quanto-mais-perto-da-cpu--mais-rápida-menor-capacidade-maior-custogb\">Hierarquia de Memórias (Quanto mais perto da CPU → Mais rápida, Menor capacidade, Maior custo/GB)</h4>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Memória</th>\n<th style=\"text-align: center;\">Volátil? (Apaga sem energia?)</th>\n<th style=\"text-align: left;\">Tecnologia / Papel Oficial</th>\n<th style=\"text-align: left;\">Detalhe Cobrado pela FAT</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Registradores &amp; Cache (L1/L2/L3)</strong></td>\n<td style=\"text-align: center;\"><strong>Sim (Volátil)</strong></td>\n<td style=\"text-align: left;\">Estática (<code>SRAM</code>) dentro do próprio chip do processador.</td>\n<td style=\"text-align: left;\">Velocidade máxima; evita que a CPU espere a RAM ler dados repetidos.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Memória RAM</strong> <em>(Principal)</em></td>\n<td style=\"text-align: center;\"><strong>Sim (Volátil)</strong></td>\n<td style=\"text-align: left;\">Dinâmica (<code>DRAM</code> / DDR4, DDR5).</td>\n<td style=\"text-align: left;\">Carrega o Sistema Operacional e todos os programas/dados <strong>em execução no momento</strong>. Desligou o PC, zera!</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Memória ROM</strong> <em>(BIOS / UEFI)</em></td>\n<td style=\"text-align: center;\"><strong>Não (Não volátil)</strong></td>\n<td style=\"text-align: left;\">Chips de leitura gravados com firmware de inicialização.</td>\n<td style=\"text-align: left;\">Executa o <strong>POST</strong> (autoteste de hardware ao ligar) e encontra o SSD/HD para iniciar o <em>boot</em>.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>SSD</strong> <em>(Solid State Drive)</em></td>\n<td style=\"text-align: center;\"><strong>Não (Não volátil)</strong></td>\n<td style=\"text-align: left;\">Armazenamento secundário sólido usando <strong>chips de memória Flash NAND</strong>.</td>\n<td style=\"text-align: left;\"><strong>Sem partes mecânicas móveis!</strong> Muito mais rápido, silencioso e resistente a quedas/vibrações do que HDD. <em>(DS 2019 Q21)</em></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>HDD</strong> <em>(Hard Disk Drive)</em></td>\n<td style=\"text-align: center;\"><strong>Não (Não volátil)</strong></td>\n<td style=\"text-align: left;\">Discos magnéticos giratórios com cabeça mecânica de leitura/escrita.</td>\n<td style=\"text-align: left;\">Barato por TB para guardar arquivos grandes/backups, porém mais lento e sensível a choques físicos.</td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h3 id=\"-parte-3--sistema-operacional-gerenciamento-de-memória-vms-vs-contêineres-docker\">📚 Parte 3 — Sistema Operacional: Gerenciamento de Memória, VMs vs. Contêineres (Docker)</h3>\n<p>Um <strong>Sistema Operacional (SO)</strong> — como Windows, Linux, macOS ou Android — atua como o <strong>intermediário</strong> entre o hardware físico e o usuário/softwares (<em>M-Tec 2022 Q35</em>). Sua parte central chama-se <strong>Kernel (Núcleo)</strong>.</p>\n<h4 id=\"1-gerenciamento-de-memória-e-memória-virtual-ds-2025-q27\">1. Gerenciamento de Memória e Memória Virtual (<em>DS 2025 Q27</em>)</h4>\n<p>Quando você abre o Chrome (com 20 abas), VS Code e Spotify ao mesmo tempo, o SO é o gerente que garante que:</p>\n<ul>\n<li><strong>Proteção/Isolamento:</strong> Um programa travado não consiga ler ou sobrescrever a memória RAM de outro processo nem do Kernel.</li>\n<li><strong>Alocação e Desalocação:</strong> Entrega blocos de RAM para quem abre e recolhe de volta ao fechar (evitando vazamentos globais).</li>\n<li><strong>Memória Virtual (<em>Paginação / Swap</em>):</strong> Se a RAM física de 8 GB encher, o SO pega blocos (\"páginas\") pouco usados no momento e move temporariamente para uma área reservada no <strong>SSD/HD</strong> (<em>arquivo de paginação / partição swap</em>). Isso impede o computador de fechar apps à força, <strong>mas deixa o sistema lento</strong> porque SSD/HDD é muito mais lento que a RAM!</li>\n</ul>\n<h4 id=\"2-virtualização-tradicional-vm-vs-contêineres-docker-info-2025-q5-e-q16\">2. Virtualização Tradicional (VM) vs. Contêineres (Docker) <em>(INFO 2025 Q5 e Q16)</em></h4>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Critério</th>\n<th style=\"text-align: left;\">Máquina Virtual (VM — VirtualBox, VMware)</th>\n<th style=\"text-align: left;\">Contêiner (Docker / Podman)</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Como isola</strong></td>\n<td style=\"text-align: left;\">Um <strong>Hypervisor</strong> virtualiza hardware completo e roda <strong>um Sistema Operacional convidado (<em>Guest OS</em>) inteiro</strong> para cada VM.</td>\n<td style=\"text-align: left;\">Isola processos, arquivos e rede usando recursos nativos do kernel (<em>namespaces</em> e <em>cgroups</em>), <strong>COMPARTILHANDO o mesmo Kernel do SO hospedeiro</strong>!</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Peso e Velocidade</strong></td>\n<td style=\"text-align: left;\"><strong>Pesada</strong> (gigabytes por VM; demora minutos para ligar porque dá <em>boot</em> completo em outro Windows/Linux).</td>\n<td style=\"text-align: left;\"><strong>Ultraleve</strong> (megabytes; inicia em frações de segundo porque não carrega outro kernel!).</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Ideal para</strong></td>\n<td style=\"text-align: left;\">Rodar um Windows completo dentro de um Mac/Linux, isolamento máximo de hardware.</td>\n<td style=\"text-align: left;\">Empacotar aplicações web + dependências (<em>\"funciona igual na minha máquina e no servidor\"</em>). <em>(INFO 2025 Q16)</em></td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h3 id=\"-parte-4--sistema-de-arquivos-linux-fhs-comandos-e-produtividade-windowsword\">📚 Parte 4 — Sistema de Arquivos Linux (FHS), Comandos e Produtividade Windows/Word</h3>\n<h4 id=\"1-diretórios-oficiais-do-linux-fhs--filesystem-hierarchy-standard-info-2025-q18\">1. Diretórios Oficiais do Linux (FHS — <em>Filesystem Hierarchy Standard</em>) <em>(INFO 2025 Q18)</em></h4>\n<p>No Linux não existem unidades <code>C:\\</code> ou <code>D:\\</code>! Tudo nasce de uma única árvore começando na <strong>raiz <code>/</code></strong>. Memorize os 7 diretórios campeões de prova:</p>\n<ul>\n<li><strong><code>/</code></strong>: Raiz absoluta do sistema de arquivos.</li>\n<li><strong><code>/bin</code></strong> (e <code>/usr/bin</code>): Arquivos <strong>binários executáveis</strong> dos comandos essenciais do sistema (<code>ls</code>, <code>cp</code>, <code>cat</code>).</li>\n<li><strong><code>/etc</code></strong>: Arquivos de <strong>configuração</strong> do sistema e servidores (<code>passwd</code>, <code>hosts</code>, configs do Apache/Nginx).</li>\n<li><strong><code>/home</code></strong>: Pastas pessoais dos <strong>usuários comuns</strong> (ex.: <code>/home/lucas</code>).</li>\n<li><strong><code>/root</code></strong>: Pasta pessoal exclusiva do <strong>superusuário administrador (<code>root</code>)</strong>. <strong>Pegadinha:</strong> <code>/root</code> NÃO é a raiz <code>/</code>, é apenas a pasta home do admin!</li>\n<li><strong><code>/lib</code></strong>: <strong>Bibliotecas</strong> compartilhadas necessárias pelos binários.</li>\n<li><strong><code>/usr</code></strong>: Softwares e utilitários instalados para uso dos usuários.</li>\n<li><strong><code>/var</code></strong>: Dados <strong>variáveis</strong> que crescem com o tempo (especialmente <strong>logs</strong> em <code>/var/log</code>, filas de impressão/e-mail e caches).</li>\n<li><strong><code>/tmp</code></strong>: Arquivos <strong>temporários</strong> (frequentemente apagados ao reiniciar).</li>\n</ul>\n<div class=\"callout callout-caution\">\n\n<p><strong>Pegadinha famosa (INFO 2025 Q18 — Lista com Intruso):</strong> A banca pergunta qual alternativa contém <strong>APENAS diretórios padrão Linux</strong> e enfia no meio <code>/mkdir</code>, <code>/ls</code>, <code>/rm</code>, <code>/cd</code>, <code>/cat</code> ou <code>/apt</code>! <strong><code>mkdir</code>, <code>ls</code>, <code>rm</code>, <code>cd</code>, <code>cat</code> são COMANDOS executados no terminal</strong>, <strong>NÃO são pastas do sistema!</strong></p>\n</div>\n\n<h4 id=\"2-comandos-essenciais-de-terminal-linux-ds-2019-q22\">2. Comandos Essenciais de Terminal Linux <em>(DS 2019 Q22)</em></h4>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Comando</th>\n<th style=\"text-align: left;\">Significado e Ação</th>\n<th style=\"text-align: left;\">Exemplo prático</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong><code>pwd</code></strong></td>\n<td style=\"text-align: left;\"><em>Print Working Directory</em>: mostra em qual pasta você está agora</td>\n<td style=\"text-align: left;\"><code>pwd</code> → <code>/home/lucas/projeto</code></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong><code>ls</code></strong></td>\n<td style=\"text-align: left;\"><em>List</em>: lista arquivos e subpastas (<code>ls -la</code> mostra detalhado + ocultos iniciados por <code>.</code>)</td>\n<td style=\"text-align: left;\"><code>ls -l</code></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong><code>cd</code></strong></td>\n<td style=\"text-align: left;\"><em>Change Directory</em>: entra ou volta de pasta (<code>cd ..</code> sobe um nível)</td>\n<td style=\"text-align: left;\"><code>cd /etc</code></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong><code>mkdir</code></strong></td>\n<td style=\"text-align: left;\"><em>Make Directory</em>: cria uma nova pasta vazia</td>\n<td style=\"text-align: left;\"><code>mkdir fotos</code></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong><code>cp</code> / <code>mv</code></strong></td>\n<td style=\"text-align: left;\"><strong><code>cp</code></strong> copia arquivo/pasta (<code>cp -r</code>); <strong><code>mv</code></strong> <strong>move OU renomeia</strong> arquivo!</td>\n<td style=\"text-align: left;\"><code>mv antigo.txt novo.txt</code></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong><code>rm</code></strong></td>\n<td style=\"text-align: left;\"><em>Remove</em>: apaga arquivos (<code>rm -rf</code> apaga pastas recursivamente — cuidado!)</td>\n<td style=\"text-align: left;\"><code>rm teste.txt</code></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong><code>chmod</code></strong></td>\n<td style=\"text-align: left;\"><em>Change Mode</em>: altera <strong>permissões</strong> de leitura (<code>r=4</code>), escrita (<code>w=2</code>), execução (<code>x=1</code>)</td>\n<td style=\"text-align: left;\"><code>chmod 755 script.sh</code></td>\n</tr>\n</tbody>\n</table>\n<p><em>(No ambiente Microsoft Office / Windows — INFO 2025 Q6 &amp; Apostas Q30: no Word, listas com marcadores/numeração ficam na guia <strong>Página Inicial</strong>, e <strong>Mala Direta</strong> automatiza cartas personalizadas a partir de uma lista Excel; no Windows, <code>Ctrl+C</code>/<code>Ctrl+V</code>/<code>Ctrl+Z</code> e Gerenciador de Tarefas <code>Ctrl+Shift+Esc</code> encerram travamentos).</em></p>\n<hr />\n<h3 id=\"️️-dissecando-questões-no-estilo-exato-da-prova\">🕵️‍♂️ Dissecando Questões no Estilo Exato da Prova</h3>\n<h4 id=\"questão-resolvida-1-baseada-em-ds-2019-q20--info-2025-q4--conversões\">Questão Resolvida 1 (Baseada em DS 2019 Q20 &amp; INFO 2025 Q4 — Conversões)</h4>\n<p><em>Converta os valores decimais <code>255</code>, <code>100</code> e <code>250</code> para binário (8 bits) e hexadecimal.</em></p>\n<ul>\n<li><code>255</code> = <code>128+64+32+16+8+4+2+1</code> = <strong><code>11111111₂</code></strong> = <strong><code>FF₁₆</code></strong>.</li>\n<li><code>100</code> = <code>64+32+4</code> = <strong><code>01100100₂</code></strong>; <code>100 ÷ 16</code> = <code>6</code> resto <code>4</code> = <strong><code>64₁₆</code></strong>.</li>\n<li><code>250</code> = <code>128+64+32+16+8+2</code> = <strong><code>11111010₂</code></strong>; <code>250 ÷ 16</code> = <code>15(F)</code> resto <code>10(A)</code> = <strong><code>FA₁₆</code></strong>.</li>\n</ul>\n<h4 id=\"questão-resolvida-2-baseada-em-info-2025-q16--q18--contêineres-e-linux\">Questão Resolvida 2 (Baseada em INFO 2025 Q16 &amp; Q18 — Contêineres e Linux)</h4>\n<p><em>I. Contêineres Docker são idênticos a Máquinas Virtuais porque cada contêiner emula um hardware separado e instala um kernel Linux completo dentro dele. II. No Linux, <code>/etc</code> armazena configurações do sistema e <code>/var</code> guarda logs variáveis.</em></p>\n<ul>\n<li><strong>Item I é FALSO:</strong> Contêineres <strong>compartilham o mesmo kernel</strong> do SO hospedeiro (não instalam kernel/SO inteiro por dentro como VMs).</li>\n<li><strong>Item II é VERDADEIRO.</strong></li>\n</ul>\n", "practiceType": "lab_bin", "practiceTag": "04_Web_Redes_SO", "videoClips": [{"title": "Números Binários — Bases Numéricas #02", "channel": "Curso em Vídeo • Gustavo Guanabara", "videoId": "eD56zn5kYfU", "startSec": 120, "endSec": 510, "tip": "Foco: conversão Decimal ↔ Binário passo a passo (por divisões e potências de 2)."}, {"title": "Números Octais e Hexadecimais — Bases Numéricas #03", "channel": "Curso em Vídeo • Gustavo Guanabara", "videoId": "gIXiFhEA-Qw", "startSec": 150, "endSec": 540, "tip": "Foco: conversão para Hexadecimal (0–9 e A–F) usada em cores e endereços."}], "challengeRefs": [{"examId": "ds2025", "qNum": 27}, {"examId": "info2025", "qNum": 4}, {"examId": "info2025", "qNum": 5}, {"examId": "info2025", "qNum": 16}, {"examId": "info2025", "qNum": 18}, {"examId": "ds2019", "qNum": 20}, {"examId": "ds2019", "qNum": 21}, {"examId": "ds2019", "qNum": 22}, {"examId": "mtec2022", "qNum": 34}]}, {"day": 11, "title": "Redes (TCP/IP, E-mail, Topologias), Cloud, IoT, Inglês Técnico e Ética", "weight": "Máxima", "storyIntro": "Capítulo 11: Separe SMTP/POP3/IMAP, TCP/IP, Barramento vs. Estrela, IaaS/PaaS/SaaS, IoT e acerte em cheio as questões de Inglês Técnico e Ética.", "lessonHtml": "<h2 id=\"dia-11--redes-de-computadores-tcpip-e-mail-topologias-cloud-iot-inglês-técnico-e-ética-cps\">Dia 11 — Redes de Computadores (TCP/IP, E-mail, Topologias), Cloud, IoT, Inglês Técnico e Ética CPS</h2>\n<h3 id=\"-contexto-no-mundo-real-a-viagem-de-um-clique-até-outro-continente\">🎯 Contexto no Mundo Real: A Viagem de um Clique até Outro Continente</h3>\n<p>Quando você envia uma mensagem pelo WhatsApp, lê um e-mail no celular ou acessa um site seguro com cadeado (<code>https://</code>), seus dados não viajam \"por mágica\" em um único bloco gigante. Eles são picotados em <strong>pacotes</strong>, endereçados por <strong>IP</strong>, protegidos por criptografia <strong>SSL/TLS</strong>, atravessam <strong>cabos submarinos ou Wi-Fi</strong> ligados por switches e roteadores, chegam a servidores na <strong>Nuvem (Cloud)</strong> e retornam reconstruídos na sua tela! Além disso, esse módulo fecha <strong>Inglês Técnico e Ética/LGPD</strong>, garantindo <strong>10 a 12 questões certeiras</strong> numa prova de 30!</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Tudo sobre <strong>Ping, Redes, Discord e Cloud</strong> fica muito mais claro pensando num PC Gamer conectado à internet:</p>\n<ul>\n<li><strong>TCP vs. UDP na Call do Discord e nos Jogos Online:</strong>\n<ul>\n<li>Quando você baixa um jogo na Steam, cada byte precisa chegar inteirinho sem arquivo corrompido (mesmo que espere reenvio) → usa <strong>TCP (confiável)</strong>.</li>\n<li>Quando você está em <strong>call de voz no Discord</strong> ou dando flick no CS2/Valorant, <strong>velocidade em tempo real importa mais que recuperar pacote velho de 2 segundos atrás!</strong> Por isso voz e movimento usam <strong>UDP (rápido, sem confirmação)</strong>.</li>\n</ul></li>\n<li><strong>DNS e DHCP do seu Roteador:</strong> O <strong>DHCP</strong> entrega seu IP local (<code>192.168.1.X</code>) automaticamente quando o PC ou celular conecta no Wi-Fi. Já o <strong>DNS</strong> traduz <code>discord.com</code> no IP real do servidor (<em>colocar DNS <code>1.1.1.1</code> ou <code>8.8.8.8</code> às vezes melhora rotas exatamente por isso!</em>).</li>\n<li><strong>Topologia Estrela vs. Barramento em LAN House:</strong> Numa <strong>LAN House moderna (Estrela)</strong>, todos os PCs ligam por cabo próprio num <strong>Switch</strong> no rack: se o cabo do PC-3 arrebentar, só o PC-3 cai; já numa rede antiga em <strong>Barramento (<em>Bus</em>)</strong>, se o cabo central partir, a LAN inteira cai junto!</li>\n<li><strong>Cloud nos Games (IaaS / PaaS / SaaS):</strong>\n<ul>\n<li><strong>SaaS:</strong> Discord Web, <strong>GeForce NOW / Xbox Cloud Gaming</strong> — você só entra e usa/joga pronto no navegador!</li>\n<li><strong>PaaS:</strong> Subir o código JS/Python do <strong>seu Bot de Discord</strong> na nuvem sem configurar sistema operacional.</li>\n<li><strong>IaaS:</strong> Alugar uma máquina virtual Linux crua (VPS) para configurar servidor de jogos/site do zero.</li>\n</ul></li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--arquitetura-tcpip-e-principais-protocolos-da-internet-ds-2025-q25--info-2025-q25\">📚 Parte 1 — Arquitetura TCP/IP e Principais Protocolos da Internet <em>(DS 2025 Q25 &amp; INFO 2025 Q25)</em></h3>\n<p>Um <strong>protocolo</strong> é um conjunto formal de regras e formatos para que máquinas diferentes (um iPhone e um servidor Linux) consigam conversar no mesmo idioma. A Internet opera sobre a pilha <strong>TCP/IP</strong>, organizada classicamente em <strong>4 camadas</strong> (da mais próxima do usuário até o cabo/onda):</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Camada TCP/IP</th>\n<th style=\"text-align: left;\">Função Principal</th>\n<th style=\"text-align: left;\">Protocolos &amp; Equipamentos Típicos</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>4. Aplicação</strong></td>\n<td style=\"text-align: left;\">Onde os aplicativos conversam na rede (web, e-mail, arquivos, nomes).</td>\n<td style=\"text-align: left;\"><strong>HTTP, HTTPS, FTP, SFTP, SMTP, POP3, IMAP, DNS, DHCP, SSH, RDP</strong></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>3. Transporte</strong></td>\n<td style=\"text-align: left;\">Garante a comunicação ponta a ponta entre processos (portas), controle de fluxo e integridade.</td>\n<td style=\"text-align: left;\"><strong>TCP</strong> (confiável, exige confirmação/ACK — Web, E-mail, Bancos) vs. <strong>UDP</strong> (rápido sem confirmação — Vídeos ao vivo, Jogos online, VoIP, DNS)</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>2. Internet (Rede)</strong></td>\n<td style=\"text-align: left;\">Endereçamento lógico global (<strong>IP</strong>) e escolha da melhor rota entre redes diferentes (<strong>Roteamento</strong>).</td>\n<td style=\"text-align: left;\"><strong>IP (IPv4 32 bits / IPv6 128 bits)</strong>, ICMP (<code>ping</code>), <strong>Roteadores</strong></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>1. Acesso à Rede (Enlace + Física)</strong></td>\n<td style=\"text-align: left;\">Transforma pacotes em quadros locais (endereço físico <strong>MAC</strong>) e transmite em sinais elétricos/luz/rádio.</td>\n<td style=\"text-align: left;\"><strong>Ethernet</strong> (cabos UTP/fibra), <strong>Wi-Fi</strong>, Placa de Rede, <strong>Switch</strong> (Camada 2)</td>\n</tr>\n</tbody>\n</table>\n<p><em>(Atenção: Alguns materiais acadêmicos detalham o <strong>Modelo OSI de 7 camadas</strong> — Física, Enlace, Rede, Transporte, Sessão, Apresentação, Aplicação — mas na prova prática da FAT o padrão da Internet cobrado é o <strong>TCP/IP em 4 camadas</strong>!)</em></p>\n<h4 id=\"protocolos-que-mais-caem-na-fat\">Protocolos que Mais Caem na FAT:</h4>\n<ul>\n<li><strong>HTTP vs. HTTPS <em>(INFO 2025 Q27)</em>:</strong> HTTP (<em>HyperText Transfer Protocol</em>) trafega páginas web em texto aberto; <strong>HTTPS</strong> encapsula o HTTP dentro de criptografia <strong>SSL/TLS</strong> (cadeado no navegador), garantindo <strong>confidencialidade e autenticidade</strong> contra interceptação!</li>\n<li><strong>DNS (<em>Domain Name System</em>):</strong> A \"agenda telefônica\" da internet — traduz nomes legíveis (<code>www.google.com</code>) em <strong>endereços IP</strong> numéricos (<code>142.250...</code>).</li>\n<li><strong>DHCP:</strong> Atribui <strong>endereços IP automaticamente</strong> aos dispositivos que entram na rede Wi-Fi/cabo (sem precisar digitar IP manual).</li>\n<li><strong>FTP / SFTP:</strong> Protocolos específicos para <strong>transferência de arquivos</strong> cliente ↔︎ servidor (<code>SFTP</code> com segurança SSH).</li>\n<li><strong>SSH vs. RDP <em>(INFO 2025 Q17)</em>:</strong> Acesso remoto! <strong>SSH</strong> abre terminal de comandos criptografado (padrão Linux/servidores); <strong>RDP (<em>Remote Desktop Protocol</em>)</strong> da Microsoft acessa a <strong>área de trabalho gráfica</strong> remota do Windows.</li>\n</ul>\n<hr />\n<h3 id=\"-parte-2--protocolos-de-e-mail-a-trinca-de-ouro-smtp-pop3-imap--webmail\">📚 Parte 2 — Protocolos de E-mail: A Trinca de Ouro (SMTP, POP3, IMAP) + Webmail</h3>\n<p>Esse assunto caiu literalmente igual na <strong>DS 2025 Q28</strong> e na <strong>INFO 2025 Q7 e Q26</strong>! Nunca confunda os 3 papéis:</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Ferramenta / Protocolo</th>\n<th style=\"text-align: center;\">Direção</th>\n<th style=\"text-align: left;\">O que acontece na prática passo a passo</th>\n<th style=\"text-align: left;\">Cenário real</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>SMTP</strong> <em>(Simple Mail Transfer Protocol)</em></td>\n<td style=\"text-align: center;\"><strong>ENVIO / SAÍDA</strong></td>\n<td style=\"text-align: left;\">Envia a mensagem do seu aplicativo até seu servidor e transporta entre servidores de e-mail (<code>@etec</code> → <code>@gmail</code>).</td>\n<td style=\"text-align: left;\">Você clica em <strong>Enviar</strong> e a carta sai da sua caixa de saída. <strong>SMTP NÃO serve para ler sua caixa de entrada!</strong></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>POP3</strong> <em>(Post Office Protocol v3)</em></td>\n<td style=\"text-align: center;\"><strong>RECEBIMENTO (Baixa)</strong></td>\n<td style=\"text-align: left;\">Conecta ao servidor, <strong>faz o download das mensagens para o dispositivo local e, por padrão, APAGA do servidor</strong>.</td>\n<td style=\"text-align: left;\">Se você baixar no notebook de casa via POP3, ao abrir o celular na rua os e-mails antigos <strong>não estarão mais lá</strong>!</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>IMAP</strong> <em>(Internet Message Access Protocol)</em></td>\n<td style=\"text-align: center;\"><strong>RECEBIMENTO (Sincroniza)</strong></td>\n<td style=\"text-align: left;\"><strong>Mantém todos os e-mails e pastas no servidor remoto</strong>, sincronizando o status (<em>lido/não lido/apagado</em>) em tempo real em todos os aparelhos.</td>\n<td style=\"text-align: left;\">Você lê um e-mail no celular e, quando abre o PC ou tablet, ele já aparece sincronizado como lido!</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Webmail</strong></td>\n<td style=\"text-align: center;\">Acesso via <strong>Browser</strong></td>\n<td style=\"text-align: left;\">Interface acessada diretamente pelo navegador via <strong>HTTP/HTTPS</strong> (ex.: Gmail Web, Outlook.com), sem instalar cliente desktop (como Mozilla Thunderbird).</td>\n<td style=\"text-align: left;\">Abrir seu e-mail no Chrome em qualquer computador.</td>\n</tr>\n</tbody>\n</table>\n<div class=\"callout callout-caution\">\n\n<p><strong>Pegadinha clássica da DS 2025 Q28:</strong> A banca cria uma tabela de itens I, II e III dizendo que <em>\"SMTP sincroniza mensagens no servidor\"</em> e <em>\"IMAP apenas envia e-mails\"</em>. Lembre sempre do macete: <strong>S</strong>MTP = <strong>S</strong>ubir / <strong>S</strong>air (Envio); <strong>POP3</strong> = <strong>P</strong>uxa para o PC e apaga; <strong>IMAP</strong> = espelho sincronizado no servidor!</p>\n</div>\n\n<hr />\n<h3 id=\"-parte-3--topologias-de-rede-cloud-computing-iot-e-navegadores\">📚 Parte 3 — Topologias de Rede, Cloud Computing, IoT e Navegadores</h3>\n<h4 id=\"1-topologias-de-rede-ds-2025-q26--ds-2019-q23\">1. Topologias de Rede <em>(DS 2025 Q26 &amp; DS 2019 Q23)</em></h4>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Topologia</th>\n<th style=\"text-align: left;\">Desenho Físico / Como Liga</th>\n<th style=\"text-align: left;\">Ponto Forte</th>\n<th style=\"text-align: left;\">Ponto Fraco / Pegadinha de Prova</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Barramento (<em>Bus</em>)</strong> <em>(DS 2025 Q26)</em></td>\n<td style=\"text-align: left;\">Todos os computadores compartilham <strong>UM ÚNICO cabo central (<em>backbone</em>)</strong> com terminadores nas duas pontas.</td>\n<td style=\"text-align: left;\">Barata e usa pouco cabo.</td>\n<td style=\"text-align: left;\"><strong>Ponto único de falha no cabo:</strong> se o cabo principal romper em qualquer lugar, <strong>A REDE INTEIRA CAI!</strong> Além disso, só um transmite por vez (colisões).</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Estrela (<em>Star</em>)</strong> <em>(DS 2019 Q23)</em></td>\n<td style=\"text-align: left;\">Cada PC tem um cabo exclusivo indo até um <strong>nó central concentrador (Switch ou Hub)</strong>.</td>\n<td style=\"text-align: left;\">Se <strong>o cabo de 1 PC romper, só ele para</strong> — o resto da rede continua intacto! Fácil de dar manutenção.</td>\n<td style=\"text-align: left;\">Depende do nó central: se o <strong>Switch</strong> queimar ou desligar, a rede para. (Padrão moderno das redes cabeadas).</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Anel (<em>Ring</em>)</strong></td>\n<td style=\"text-align: left;\">Cada computador liga-se ao vizinho formando um circuito fechado; um sinal (<em>Token</em>) dá a volta dando vez de falar.</td>\n<td style=\"text-align: left;\">Fluxo ordenado sem colisões aleatórias.</td>\n<td style=\"text-align: left;\">Em anel simples sem redundância, se um nó falha, interrompe o ciclo.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Malha (<em>Mesh</em>)</strong></td>\n<td style=\"text-align: left;\">Cada nó se conecta diretamente a <strong>vários ou todos os outros nós</strong> (múltiplos caminhos alternativos).</td>\n<td style=\"text-align: left;\"><strong>Tolerância máxima a falhas!</strong> Se um cabo cair, o tráfego desvia por outra rota.</td>\n<td style=\"text-align: left;\">Caríssima e complexa em cabeamento se tiver muitas máquinas.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Híbrida</strong></td>\n<td style=\"text-align: left;\">Combina duas ou mais topologias (ex.: várias Estrelas ligadas em Barramento ou Malha).</td>\n<td style=\"text-align: left;\">Flexibilidade para grandes prédios e campi.</td>\n<td style=\"text-align: left;\">Maior complexidade de projeto e gerenciamento.</td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"2-computação-em-nuvem-cloud-computing--analogia-da-pizzaria-apostas-q26\">2. Computação em Nuvem (<em>Cloud Computing</em>) — Analogia da Pizzaria <em>(Apostas Q26)</em></h4>\n<p>Imagine a diferença entre fazer tudo em casa e pedir delivery pronto para entender os <strong>3 Modelos de Serviço Cloud</strong>:</p>\n<ul>\n<li><strong>IaaS (<em>Infraestrutura como Serviço</em> — ex.: AWS EC2, Azure VMs, Google Compute Engine):</strong> Você aluga hardware virtual na nuvem (CPU, RAM, disco, rede). É como <strong>alugar a cozinha e o forno</strong> — você mesmo instala o Sistema Operacional, banco, patches e sobe seu app!</li>\n<li><strong>PaaS (<em>Plataforma como Serviço</em> — ex.: Heroku, Vercel, Azure App Service):</strong> O provedor já gerencia hardware, SO, firewall e runtime (Node/Python/Java). É como <strong>comprar a massa e os ingredientes prontos</strong> — o desenvolvedor só faz o deploy do <strong>próprio código</strong>!</li>\n<li><strong>SaaS (<em>Software como Serviço</em> — ex.: Google Docs, Gmail, Microsoft 365, Canva, Figma):</strong> Software 100% pronto usado no navegador/app por assinatura ou grátis. É como <strong>sentar na pizzaria e comer a pizza pronta</strong> — você não instala nem programa nada!</li>\n</ul>\n<h4 id=\"3-internet-das-coisas-iot-navegadores-e-suítes-ds-2025-q24-q29-e-q30\">3. Internet das Coisas (IoT), Navegadores e Suítes <em>(DS 2025 Q24, Q29 e Q30)</em></h4>\n<ul>\n<li><strong>IoT (<em>Internet of Things</em>):</strong> Conecta objetos físicos do cotidiano à rede usando <strong>sensores</strong> (leem temperatura, umidade, batimentos), <strong>atuadores</strong> e conectividade para trocar dados e agir automaticamente (ex.: semáforos inteligentes, sensores agrícolas, fechaduras e relógios smart).</li>\n<li><strong>Navegadores (<em>Browsers</em>)</strong> <em>(DS 2025 Q29)</em>: Softwares clientes que interpretam HTML/CSS/JS — <strong>Google Chrome, Mozilla Firefox, Microsoft Edge, Apple Safari, Opera, Brave</strong>. <strong>Intrusos clássicos da prova:</strong> <em>Google Search</em> (é <strong>buscador</strong>, não navegador!), <em>Outlook</em>, <em>Excel</em> e <em>VS Code</em>.</li>\n<li><strong>Suítes de Produtividade</strong> <em>(DS 2025 Q30)</em>: Conjuntos integrados de escritório (Editor de Texto + Planilha + Apresentações) como <strong>Microsoft 365 / Office</strong> (Word, Excel, PowerPoint), <strong>LibreOffice</strong> (Writer, Calc, Impress) e <strong>Google Workspace</strong> (Docs, Sheets, Slides).</li>\n</ul>\n<hr />\n<h3 id=\"-parte-4--inglês-técnico--ética-socioambiental-cps\">📚 Parte 4 — Inglês Técnico &amp; Ética Socioambiental CPS</h3>\n<p>Quase toda prova DS/Info começa com <strong>Q1 a Q3 de Inglês</strong> e <strong>Q4 a Q6 de Ética/Cidadania</strong>!</p>\n<h4 id=\"1-técnicas-rápidas-e-vocabulário-obrigatório-de-inglês-técnico-ds-2025-q1q3--m-tec-q7q9\">1. Técnicas Rápidas e Vocabulário Obrigatório de Inglês Técnico <em>(DS 2025 Q1–Q3 &amp; M-Tec Q7–Q9)</em></h4>\n<ul>\n<li><strong>Técnicas de leitura:</strong>\n<ul>\n<li><em>Skimming:</em> leitura panorâmica rápida no título e primeira frase de cada parágrafo para pegar a <strong>ideia central</strong>.</li>\n<li><em>Scanning:</em> busca dirigida de datas, números, siglas ou palavras específicas pedidas na questão.</li>\n</ul></li>\n<li><strong>Gramática que já caiu:</strong>\n<ul>\n<li><strong>Comparativo / Superlativo irregular <em>(M-Tec 2022 Q7)</em>:</strong> <code>bad → worse (pior que) → the worst (o pior)</code>; <code>good → better → the best</code>.</li>\n<li><strong>Formação de palavras com prefixos/sufixos <em>(M-Tec 2022 Q9)</em>:</strong> <code>-able / -ible</code> formam <strong>adjetivos</strong> indicando possibilidade (<em>debatable</em>, <em>scalable</em>, <em>readable</em>); <code>-ive</code> forma <strong>adjetivos</strong> (<em>positive</em>, <em>interactive</em>); <code>-tion / -ment / -ness</code> formam <strong>substantivos</strong>; <code>-ly</code> forma <strong>advérbios</strong>.</li>\n</ul></li>\n<li><strong>Falsos Cognatos (parecem português, mas significam outra coisa!):</strong>\n<ul>\n<li><code>data</code> = <strong>dados</strong> (NÃO é \"datas\" — data de calendário é <em>date</em>!).</li>\n<li><code>actually</code> = <strong>na verdade</strong> (NÃO é \"atualmente\" = <em>currently</em>).</li>\n<li><code>pretend</code> = <strong>fingir</strong> (NÃO é \"pretender\" = <em>intend</em>).</li>\n<li><code>library</code> = <strong>biblioteca / biblioteca de código</strong> (NÃO é \"livraria\" = <em>bookstore</em>).</li>\n<li><code>support</code> = <strong>apoiar / dar suporte</strong> (NÃO é \"aguentar/suportar dor\" = <em>bear/stand</em>).</li>\n</ul></li>\n<li><strong>Termos recorrentes de Soft Skills &amp; TI:</strong> <code>outcomes</code> (resultados/desfechos) • <code>troubleshooting</code> (diagnóstico e solução de falhas) • <code>critical thinking</code> (pensamento crítico) • <code>inference</code> (inferência/dedução implícita nas entrelinhas) • <code>daunting</code> (intimidante/assustador) • <code>bias</code> (viés/parcialidade algorítmica) • <code>awareness</code> (consciência).</li>\n</ul>\n<h4 id=\"2-ética-em-ti-direitos-trabalhistas-lixo-eletrônico-e-lgpd-ds-2025-q4q6\">2. Ética em TI, Direitos Trabalhistas, Lixo Eletrônico e LGPD <em>(DS 2025 Q4–Q6)</em></h4>\n<ul>\n<li><strong>Ética para o Bem Comum:</strong> Ações verdadeiramente éticas visam o impacto coletivo, transparência e respeito aos direitos humanos — rejeitando alternativas baseadas em <em>vaidade pessoal, autopromoção em redes sociais ou lucro acima da segurança</em>.</li>\n<li><strong>Sustentabilidade &amp; Lixo Eletrônico (<em>e-waste</em>):</strong> Baterias, placas e monitores contêm metais pesados (chumbo, mercúrio, cádmio). Nunca devem ir para o lixo comum! A postura ética correta exige <strong>logística reversa / descarte em pontos de coleta recicladora certificados</strong> e desenvolvimento de sistemas eficientes (TI Verde) sem induzir <strong>obsolescência programada</strong>.</li>\n<li><strong>LGPD (Lei Geral de Proteção de Dados):</strong> Coleta mínima necessária de dados pessoais, finalidade explícita, consentimento do titular e proteção contra vazamentos.</li>\n</ul>\n<hr />\n<h3 id=\"️️-dissecando-questões-no-estilo-exato-da-prova\">🕵️‍♂️ Dissecando Questões no Estilo Exato da Prova</h3>\n<h4 id=\"questão-resolvida-1-baseada-em-ds-2025-q26--q28--topologias-e-e-mail\">Questão Resolvida 1 (Baseada em DS 2025 Q26 &amp; Q28 — Topologias e E-mail)</h4>\n<p><em>Analise: I. Na topologia em Barramento, o rompimento do cabo backbone interrompe a comunicação de toda a rede. II. O protocolo POP3 envia mensagens do aplicativo cliente para o servidor de saída. III. O protocolo IMAP mantém os e-mails sincronizados no servidor para acesso em vários aparelhos.</em></p>\n<ul>\n<li><strong>Item I:</strong> VERDADEIRO.</li>\n<li><strong>Item II:</strong> <strong>FALSO</strong> (quem envia é o <strong>SMTP</strong>; POP3 baixa e apaga).</li>\n<li><strong>Item III:</strong> VERDADEIRO.</li>\n</ul>\n<h4 id=\"questão-resolvida-2-baseada-em-ds-2025-q1--m-tec-q7--inglês-técnico\">Questão Resolvida 2 (Baseada em DS 2025 Q1 &amp; M-Tec Q7 — Inglês Técnico)</h4>\n<p><em>No trecho \"Effective troubleshooting produces reliable outcomes, even when legacy bugs feel daunting and represent the worst scenario\", as palavras destacadas significam respectivamente:</em></p>\n<ul>\n<li><code>troubleshooting</code> = <strong>solução/diagnóstico de problemas</strong>; <code>outcomes</code> = <strong>resultados</strong>; <code>daunting</code> = <strong>intimidante</strong>; <code>worst</code> = <strong>pior</strong> (superlativo de <em>bad</em>).</li>\n</ul>\n", "practiceType": "pairs", "practiceTag": "05_Ingles_Etica", "videoClips": [{"title": "Topologias de Rede: Barramento, Estrela, Anel e Malha", "channel": "Bóson Treinamentos", "videoId": "1hJaTQIT2HQ", "startSec": 45, "endSec": 405, "tip": "Foco: desenho físico de cada topologia e impacto de rompimento de cabo."}, {"title": "Funcionamento do TCP/IP e Endereçamento IP", "channel": "Curso em Vídeo • Gustavo Guanabara", "videoId": "q65kHIvtWxg", "startSec": 120, "endSec": 480, "tip": "Foco: como funcionam IPs e o papel dos protocolos TCP/IP na Internet."}], "challengeRefs": [{"examId": "ds2025", "qNum": 1}, {"examId": "ds2025", "qNum": 4}, {"examId": "ds2025", "qNum": 24}, {"examId": "ds2025", "qNum": 25}, {"examId": "ds2025", "qNum": 26}, {"examId": "ds2025", "qNum": 28}, {"examId": "info2025", "qNum": 25}, {"examId": "info2025", "qNum": 27}, {"examId": "ds2019", "qNum": 23}, {"examId": "apostas", "qNum": 26}]}, {"day": 12, "title": "Base Comum M-Tec: Português, Literatura, Interpretação e História", "weight": "Máxima", "storyIntro": "Capítulo 12 (Especial M-Tec): Domine Tipologia Textual, Paradoxo, Semântica, Trovadorismo, Barroco (Cultismo × Conceptismo) e História (Paleolítico/Neolítico/Feudalismo).", "lessonHtml": "<h2 id=\"dia-12--base-comum-m-tec-i-português-interpretação-literatura-e-história-1º-ano-em\">Dia 12 — Base Comum M-Tec I: Português, Interpretação, Literatura e História (1º Ano EM)</h2>\n<h3 id=\"-contexto-no-mundo-real-por-que-português-e-história-decidem-vagas-no-m-tec\">🎯 Contexto no Mundo Real: Por que Português e História Decidem Vagas no M-Tec?</h3>\n<p>Na prova de <strong>Vagas Remanescentes do 2º Ano M-Tec (Ensino Médio Integrado ao Técnico)</strong>, você não disputa apenas com quem decorou tags HTML: cerca de metade da prova oficial (<em>como vimos na prova real M-Tec 2022, questões Q1–Q6 e Q24–Q27</em>) cobra matérias da <strong>Base Nacional Comum da 1ª Série do Ensino Médio</strong>!</p>\n<p>E tem mais um detalhe estratégico: saber <strong>interpretar textos com precisão</strong>, distinguir um <strong>Paradoxo</strong> de uma <strong>Antítese</strong>, separar <strong>Cultismo</strong> de <strong>Conceptismo</strong> e dominar a passagem do <strong>Paleolítico ao Neolítico</strong> também afia diretamente seu olhar para as pegadinhas verbais das questões de programação e engenharia!</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Português, Literatura e História ficam mil vezes mais fáceis quando comparamos com jogos e internet:</p>\n<ul>\n<li><strong>Tipos Textuais nos Games:</strong>\n<ul>\n<li><strong>Narração:</strong> A <em>lore</em> / cutscene contando a história do personagem (<em>\"Kratos atravessou os reinos buscando...\"</em>).</li>\n<li><strong>Descrição:</strong> O texto da ficha de um item (<em>\"Armadura pesada de aço escovado, escura e rachada nas bordas\"</em>).</li>\n<li><strong>Injunção (Instrucional):</strong> O <strong>tutorial</strong> no começo do jogo (<em>\"Pressione <code>Espaço</code> para pular; aperte <code>R</code> para recarregar\"</em> — verbos no <strong>imperativo</strong>!).</li>\n<li><strong>Exposição vs. Argumentação:</strong> A <strong>wiki</strong> explica neutro como o item funciona (Expositivo); um vídeo/artigo dizendo <em>\"Por que tal arma deveria ser nerfada\"</em> defende opinião com provas (Argumentativo).</li>\n</ul></li>\n<li><strong>Variação Linguística:</strong> Falar <em>\"Mano, dropa a spike no B e dá call no Disc\"</em> com seu duo é perfeito para a partida (<strong>Diafásica/Situacional</strong> e <strong>Diastrática/Jargão</strong>); já numa redação ou entrevista de estágio você muda para a norma padrão — não existe \"falar errado\", existe <strong>adequação ao contexto</strong>!</li>\n<li><strong>História Estilo <em>Age of Empires / Civilization</em>:</strong>\n<ul>\n<li><strong>Paleolítico:</strong> Fase inicial <strong>nômade</strong> — você anda pelo mapa caçando cervo e colhendo fruta até acabar o recurso da área.</li>\n<li><strong>Revolução Neolítica:</strong> Desbloqueou a tecnologia de <strong>Fazenda (Agricultura) e Pecuária</strong> → você para de andar, funda uma aldeia fixa perto do rio (<strong>Sedentarismo</strong>), estoca comida e cresce a cidade!</li>\n<li><strong>Feudalismo:</strong> Mapa cheio de <strong>castelos isolados (feudos)</strong>, quase sem comércio/ouro circulando, <strong>servos</strong> plantando na terra do senhor em troca de proteção e contratos de lealdade (<strong>Suserania e Vassalagem</strong>).</li>\n</ul></li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--tipologia-textual-vs-gêneros-textuais-m-tec-2022-q3\">📚 Parte 1 — Tipologia Textual vs. Gêneros Textuais <em>(M-Tec 2022 Q3)</em></h3>\n<p><strong>Atenção à distinção conceitual:</strong></p>\n<ul>\n<li><strong>Gênero Textual</strong> é o formato concreto que circula na sociedade (são dezenas: <em>notícia, crônica, receita de bolo, bula de remédio, contrato, e-mail, artigo de opinião, tutorial</em>).</li>\n<li><strong>Tipo Textual (Tipologia)</strong> refere-se à <strong>estrutura e objetivo predominante</strong> dentro do texto — são apenas <strong>5 tipos oficiais</strong>:</li>\n</ul>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Tipo Textual</th>\n<th style=\"text-align: left;\">Objetivo Central</th>\n<th style=\"text-align: left;\">Pistas Gramaticais na Prova</th>\n<th style=\"text-align: left;\">Exemplo Real de Trecho</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>1. Narração</strong></td>\n<td style=\"text-align: left;\">Contar fatos/ações vividos por personagens em <strong>tempo e espaço</strong></td>\n<td style=\"text-align: left;\">Verbos de ação no pretérito (<em>chegou, programou</em>), marcadores temporais (<em>ontem, depois</em>).</td>\n<td style=\"text-align: left;\"><em>\"Ontem à noite, Lucas abriu o notebook, corrigiu o bug do login e enviou o código antes do prazo.\"</em></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>2. Descrição</strong></td>\n<td style=\"text-align: left;\">Retratar características físicas ou psicológicas (<strong>\"fotografia em palavras\"</strong>, sem avanço temporal)</td>\n<td style=\"text-align: left;\">Adjetivos, verbos de estado/ligação (<em>é, estava, parecia</em>), detalhes sensoriais.</td>\n<td style=\"text-align: left;\"><em>\"O laboratório tinha vinte monitores largos, cadeiras ergonômicas pretas e iluminação fria e silenciosa.\"</em></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>3. Exposição (Dissertativo-Expositivo)</strong></td>\n<td style=\"text-align: left;\"><strong>Explicar, informar e esclarecer</strong> um assunto de forma clara e <strong>impessoal</strong>, sem tentar convencer de uma opinião polêmica</td>\n<td style=\"text-align: left;\">Linguagem objetiva, 3ª pessoa, definições e exemplos didáticos (apostilas, enciclopédias, notícias neutras).</td>\n<td style=\"text-align: left;\"><em>\"O protocolo HTTPS adiciona a camada criptográfica SSL/TLS sobre o HTTP para proteger os dados em trânsito.\"</em></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>4. Dissertação Argumentativa</strong></td>\n<td style=\"text-align: left;\"><strong>Defender uma tese / ponto de vista</strong> usando provas, dados e argumentos para <strong>persuadir</strong> o leitor</td>\n<td style=\"text-align: left;\">Tese clara, conectivos lógicos (<em>portanto, contudo, logo</em>), juízo de valor fundamentado (editoriais, redação ENEM).</td>\n<td style=\"text-align: left;\"><em>\"O ensino técnico integrado é indispensável pois une formação cidadã e prática profissional real.\"</em></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>5. Injunção / Instrucional</strong></td>\n<td style=\"text-align: left;\"><strong>Instruir, orientar, dar ordens ou conselhos</strong> passo a passo sobre como fazer algo</td>\n<td style=\"text-align: left;\">Verbos no <strong>imperativo</strong> (<em>clique, abra, adicione</em>) ou infinitivo instrucional (<em>manter em local seco</em>).</td>\n<td style=\"text-align: left;\"><em>\"1. Extraia o arquivo ZIP. 2. Clique duas vezes em COMECE_AQUI.html. 3. Responda ao simulado.\"</em></td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h3 id=\"-parte-2--figuras-de-linguagem-semântica-e-variações-linguísticas\">📚 Parte 2 — Figuras de Linguagem, Semântica e Variações Linguísticas</h3>\n<h4 id=\"1-figuras-de-linguagem-campeãs-de-prova-m-tec-2022-q4\">1. Figuras de Linguagem Campeãs de Prova <em>(M-Tec 2022 Q4)</em></h4>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Figura</th>\n<th style=\"text-align: left;\">Como funciona na prática</th>\n<th style=\"text-align: left;\">Exemplo Real Comentado</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Antítese</strong></td>\n<td style=\"text-align: left;\">Apenas <strong>aproxima palavras ou ideias de sentidos opostos</strong> na frase, <strong>SEM contradição lógica impossível</strong>.</td>\n<td style=\"text-align: left;\"><em>\"Entre o <strong>claro</strong> e o <strong>escuro</strong>, entre a <strong>alegria</strong> e a <strong>tristeza</strong>, o dia seguiu.\"</em> (Dia e noite existem naturalmente, apenas estão contrastando!)</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Paradoxo (Oxímoro)</strong></td>\n<td style=\"text-align: left;\">Une ideias contraditórias que <strong>se anulam logicamente numa mesma afirmação</strong> para causar reflexão profunda! <em>(M-Tec Q4)</em></td>\n<td style=\"text-align: left;\"><em>\"É ferida que <strong>dói e não se sente</strong>\"</em> (Camões) / <em>\"Quanto mais estudo, menos entendo\"</em> / <em>\"Silêncio ensurdecedor\"</em>.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Metáfora vs. Comparação</strong></td>\n<td style=\"text-align: left;\"><strong>Comparação (Símile)</strong> usa conectivo explícito (<em>\"como, tal qual\"</em>). <strong>Metáfora</strong> transfere o sentido <strong>diretamente, sem conectivo</strong>.</td>\n<td style=\"text-align: left;\">Comparação: <em>\"O banco de dados é <strong>como</strong> um cofre.\"</em> <br>Metáfora: <em>\"O banco de dados <strong>é</strong> um cofre.\"</em></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Metonímia</strong></td>\n<td style=\"text-align: left;\">Substitui uma palavra por outra com relação lógica real (autor pela obra, continente pelo conteúdo, parte pelo todo).</td>\n<td style=\"text-align: left;\"><em>\"Passei a tarde lendo <strong>Machado de Assis</strong>\"</em> (os livros dele) / <em>\"Comi <strong>dois pratos</strong> hoje.\"</em></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Ironia</strong></td>\n<td style=\"text-align: left;\">Dizer exatamente o <strong>oposto</strong> do que se pensa, com intenção crítica ou humorística.</td>\n<td style=\"text-align: left;\"><em>\"Que código maravilhoso e limpo — levou só 4 horas para travar na tela de login!\"</em></td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Hipérbole</strong></td>\n<td style=\"text-align: left;\"><strong>Exagero</strong> intencional para dar ênfase expressiva.</td>\n<td style=\"text-align: left;\"><em>\"Já compilei esse projeto <strong>um milhão de vezes</strong> hoje!\"</em></td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Hipérbato</strong></td>\n<td style=\"text-align: left;\"><strong>Inversão brusca da ordem natural</strong> da frase (sujeito + verbo + complemento), muito comum no Barroco e no Hino Nacional.</td>\n<td style=\"text-align: left;\"><em>\"Ouviram do Ipiranga as margens plácidas de um povo heroico o brado retumbante...\"</em></td>\n</tr>\n</tbody>\n</table>\n<h4 id=\"2-semântica-denotação-conotação-polissemia-e-hipônimohiperônimo-m-tec-2022-q5\">2. Semântica: Denotação, Conotação, Polissemia e Hipônimo/Hiperônimo <em>(M-Tec 2022 Q5)</em></h4>\n<ul>\n<li><strong>Denotação (D = Dicionário):</strong> Sentido <strong>literal, exato</strong> da palavra (<em>\"O servidor usa memória física de <strong>pedra</strong> de silício\"</em> / <em>\"Quebrou a <strong>pedra</strong>\"</em>).</li>\n<li><strong>Conotação:</strong> Sentido <strong>figurado, poético ou contextual</strong> (<em>\"Ele tem um coração de <strong>pedra</strong>\"</em> = insensível).</li>\n<li><strong>Polissemia:</strong> Quando uma única palavra possui <strong>vários significados diferentes</strong> dependendo da frase (<em>\"a <strong>cabeça</strong> do aluno\"</em>, <em>\"a <strong>cabeça</strong> do prego\"</em>, <em>\"a <strong>cabeça</strong> da fila\"</em>).</li>\n<li><strong>Hiperônimo vs. Hipônimo <em>(caiu em M-Tec Q5!)</em>:</strong>\n<ul>\n<li><strong>Hiperônimo</strong> = termo <strong>mais amplo / categoria geral</strong> (<em>\"pensador\"</em>, <em>\"animal\"</em>, <em>\"linguagem de programação\"</em>).</li>\n<li><strong>Hipônimo</strong> = termo <strong>mais específico</strong> contido dentro da categoria (<em>\"Aristóteles\"</em>, <em>\"cachorro\"</em>, <em>\"Python\"</em>).</li>\n<li>Exemplo real de coesão num texto: <em>\"A França convocou <strong>Aristóteles</strong> na homenagem. O <strong>pensador</strong> grego...\"</em> → substituir <em>Aristóteles</em> (hipônimo) por <em>pensador</em> (hiperônimo) evita repetição!</li>\n</ul></li>\n</ul>\n<h4 id=\"3-variações-linguísticas-m-tec-2022-q2\">3. Variações Linguísticas <em>(M-Tec 2022 Q2)</em></h4>\n<p>A Sociolinguística moderna ensina que a língua é viva e não existe <em>\"falar errado\"</em> de modo absoluto — o que existe é <strong>adequação ou inadequação ao contexto comunicativo</strong> (ninguém fala igual numa entrevista de emprego e num grupo de WhatsApp com amigos!).</p>\n<ul>\n<li><strong>Variação Diatópica (Geográfica/Regional):</strong> Muda conforme o lugar (<em>\"aipim\" / \"macaxeira\" / \"mandioca\"</em>; <em>\"trem\"</em> em MG; <em>\"guri\"</em> no RS).</li>\n<li><strong>Variação Diacrônica (Histórica):</strong> Muda com o passar do tempo (<em>\"Vossa Mercê\" → \"Vosmicê\" → \"Você\" → \"Vc\"</em>).</li>\n<li><strong>Variação Diastrática (Social / Profissional):</strong> Muda conforme grupo social ou profissão (jargão de TI: <em>\"fazer deploy de um container\"</em>; gírias juvenis).</li>\n<li><strong>Variação Diafásica (Situacional / Registro):</strong> Grau de formalidade entre falar com um juiz vs. conversar em casa.</li>\n</ul>\n<hr />\n<h3 id=\"-parte-3--escolas-literárias-do-1º-ano-do-ensino-médio-m-tec-q1--q6\">📚 Parte 3 — Escolas Literárias do 1º Ano do Ensino Médio <em>(M-Tec Q1 &amp; Q6)</em></h3>\n<h4 id=\"1-trovadorismo-idade-média--sécs-xii-a-xiv-m-tec-q6\">1. Trovadorismo (Idade Média — sécs. XII a XIV, <em>M-Tec Q6</em>)</h4>\n<p>Primeira manifestação literária em língua galego-portuguesa, nascida nos castelos feudais como <strong>cantigas</strong> acompanhadas de música (trovadores + jograis):</p>\n<ul>\n<li><strong>Cantigas Líricas (Amorosas):</strong>\n<ul>\n<li><strong>Cantiga de Amor:</strong> Eu lírico <strong>MASCULINO</strong> sofre por uma dama nobre distante e inatingível (<em>\"minha senhor\"</em>). Reflete a <strong>vassalagem feudal</strong> trazida para o amor (o homem serve humildemente à mulher superior).</li>\n<li><strong>Cantiga de Amigo:</strong> Eu lírico <strong>FEMININO</strong> (mesmo tendo sido escrita por homens!) expressa saudade do seu namorado (<em>\"amigo\"</em>) conversando com a mãe, amigas ou elementos da natureza (mar, ondas, pinheiros). Origem popular/rural.</li>\n</ul></li>\n<li><strong>Cantigas Satíricas (Críticas):</strong>\n<ul>\n<li><strong>Escárnio:</strong> Crítica <strong>indireta, irônica, ambígua</strong>, <strong>sem</strong> citar o nome da pessoa diretamente.</li>\n<li><strong>Maldizer:</strong> Crítica <strong>direta, agressiva, explícita</strong>, citando o nome do alvo e usando palavras de baixo calão.</li>\n</ul></li>\n</ul>\n<h4 id=\"2-humanismo-séc-xv-classicismo-séc-xvi-e-quinhentismo-no-brasil\">2. Humanismo (séc. XV), Classicismo (séc. XVI) e Quinhentismo no Brasil</h4>\n<ul>\n<li><strong>Humanismo:</strong> Transição da Idade Média para o Renascimento (<strong>Gil Vicente</strong>, teatro crítico em <em>O Auto da Barca do Inferno</em>).</li>\n<li><strong>Classicismo:</strong> Renascimento pleno, equilíbrio, razão, imitação dos clássicos greco-romanos (<strong>Luís de Camões</strong> — <em>Os Lusíadas</em> e sonetos equilibrados).</li>\n<li><strong>Quinhentismo no Brasil (1500 — <em>M-Tec Cards</em>):</strong> Duas frentes no primeiro século após 1500:\n<ol>\n<li><strong>Literatura Informativa / de Viagens:</strong> Descrevia e catalogava a nova terra, fauna, flora e indígenas para a Coroa Portuguesa (<strong>Carta de Pero Vaz de Caminha</strong>, 1500).</li>\n<li><strong>Literatura Jesuítica / Catequética:</strong> Textos, poesias e autos teatrais de caráter religioso e pedagógico para <strong>catequizar</strong> os indígenas e educar colonos (<strong>Padre José de Anchieta</strong>).</li>\n</ol></li>\n</ul>\n<h4 id=\"3-barroco-sécs-xviixviii--campeão-de-pegadinha-m-tec-q1\">3. Barroco (sécs. XVII–XVIII — <em>Campeão de Pegadinha: M-Tec Q1!</em>)</h4>\n<p>Nascido no clima tenso da <strong>Contrarreforma Católica</strong>, o Barroco expressa o <strong>conflito dramático humano (dualismo)</strong>: espírito × carne, céu × inferno, efemeridade da vida × busca pelo eterno. Usa muitas antíteses e paradoxos!</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Estilo Barroco</th>\n<th style=\"text-align: left;\">Foco Principal</th>\n<th style=\"text-align: left;\">Características &amp; Recursos</th>\n<th style=\"text-align: left;\">Grande Autor</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Cultismo (Gongorismo)</strong></td>\n<td style=\"text-align: left;\"><strong>Jogo de PALAVRAS</strong> e forma</td>\n<td style=\"text-align: left;\">Linguagem rebuscada, exuberante, vocabulário raro, metáforas complexas, hipérboles e imagens sensoriais (<em>cores, brilho, sons</em>).</td>\n<td style=\"text-align: left;\"><strong>Gregório de Matos</strong> (<em>\"Boca do Inferno\"</em>) na poesia ornamentada</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Conceptismo (Quevedismo)</strong></td>\n<td style=\"text-align: left;\"><strong>Jogo de IDEIAS</strong> e lógica</td>\n<td style=\"text-align: left;\">Raciocínio lógico rigoroso, argumentação persuasiva, <strong>silogismos</strong> e encadeamento intelectual para provar teses morais/religiosas.</td>\n<td style=\"text-align: left;\"><strong>Padre Antônio Vieira</strong> (nos <em>Sermões</em>, ex.: <em>Sermão da Sexagésima</em>)</td>\n</tr>\n</tbody>\n</table>\n<div class=\"callout callout-caution\">\n\n<p><strong>Pegadinha clássica da M-Tec Q1:</strong> A banca define perfeitamente o que é <strong>Cultismo</strong> (jogo de palavras/linguagem sensorial rebuscada) e <strong>Conceptismo</strong> (jogo de ideias/raciocínio lógico), e simplesmente <strong>troca um nome pelo outro</strong> nas alternativas! Associe sempre: <strong>Con</strong>ceptismo = <strong>Con</strong>ceito / <strong>Ideia</strong>; <strong>Cul</strong>tismo = <strong>Cul</strong>tura da palavra / <strong>Forma</strong>!</p>\n</div>\n\n<hr />\n<h3 id=\"-parte-4--história-geral-do-1º-ano-pré-história-antiguidade-e-feudalismo-m-tec-q24q27\">📚 Parte 4 — História Geral do 1º Ano: Pré-História, Antiguidade e Feudalismo <em>(M-Tec Q24–Q27)</em></h3>\n<h4 id=\"1-pré-história-paleolítico-vs-revolução-neolítica-m-tec-q24q25\">1. Pré-História: Paleolítico vs. Revolução Neolítica <em>(M-Tec Q24–Q25)</em></h4>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Período</th>\n<th style=\"text-align: left;\">Estilo de Vida</th>\n<th style=\"text-align: left;\">Como Conseguia Alimento e Tecnologia</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Paleolítico</strong> <em>(Idade da Pedra Lascada)</em></td>\n<td style=\"text-align: left;\"><strong>Nomadismo:</strong> bandos mudavam constantemente de região assim que caça/frutos esgotavam-se.</td>\n<td style=\"text-align: left;\"><strong>Caça, pesca e coleta</strong>; ferramentas rústicas de pedra lascada e ossos; <strong>domínio do fogo</strong>; arte rupestre nas cavernas.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>Neolítico</strong> <em>(Idade da Pedra Polida — Revolução Neolítica)</em></td>\n<td style=\"text-align: left;\"><strong>Sedentarismo:</strong> fixaram moradia permanente em aldeias próximas a grandes rios.</td>\n<td style=\"text-align: left;\">Descoberta da <strong>agricultura</strong> e <strong>domesticação de animais</strong>! Produção de <strong>excedentes</strong>, cerâmica, tecelagem, crescimento populacional e surgimento da propriedade privada/Estado.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>Idade dos Metais</strong></td>\n<td style=\"text-align: left;\">Cidades organizadas e comércio</td>\n<td style=\"text-align: left;\">Fundição de cobre, bronze e ferro; invenção da roda e dos primeiros sistemas de escrita (fim da Pré-História!).</td>\n</tr>\n</tbody>\n</table>\n<ul>\n<li><strong>Conceitos de Migração <em>(M-Tec Q24)</em>:</strong> <strong>Nomadismo</strong> (deslocamento constante sem residência fixa para sobreviver); <strong>Sedentarismo</strong> (fixação num território por meio da agricultura/moradia); <strong>Êxodo Rural</strong> (migração em massa de trabalhadores do campo para as cidades em busca de emprego urbano/industrial).</li>\n</ul>\n<h4 id=\"2-antiguidade-oriental-primeiras-civilizações-e-clássica-m-tec-q26\">2. Antiguidade Oriental (Primeiras Civilizações) e Clássica <em>(M-Tec Q26)</em></h4>\n<p>As primeiras civilizações urbanas surgiram no <strong>Crescente Fértil</strong> (<em>Mesopotâmia</em> — sumérios, babilônios entre os rios <strong>Tigre e Eufrates</strong>; <em>Egito</em> no <strong>Rio Nilo</strong>), caracterizadas como <strong>sociedades hidráulicas</strong> (agricultura de irrigação controlada pelo Estado), governo <strong>teocrático</strong> (rei visto como deus ou representante divino), leis escritas (<strong>Código de Hamurabi</strong> — <em>\"olho por olho, dente por dente\"</em>) e sistemas de escrita (cuneiforme/hieróglifos). Na sequência, <strong>Grécia</strong> (democracia ateniense, filosofia) e <strong>Roma</strong> (direito romano, república, império, cristianismo).</p>\n<h4 id=\"3-idade-média-ocidental--feudalismo-sécs-v-ao-xv--m-tec-q27\">3. Idade Média Ocidental &amp; Feudalismo (sécs. V ao XV — <em>M-Tec Q27</em>)</h4>\n<p>Após a queda de Roma Ocidental (476 d.C.) e invasões germânicas, a Europa ruralizou-se:</p>\n<ul>\n<li><strong>Economia Feudal:</strong> Essencialmente <strong>agrária, rural, autossuficiente (de subsistência)</strong>, com escambo e baixíssima circulação monetária dentro do feudo (<em>manso senhorial, manso servil e terras comunais</em>).</li>\n<li><strong>Sociedade Estamental (sem mobilidade social — \"nasceu servo, morre servo\"):</strong>\n<ol>\n<li><strong>Clero</strong> (<em>oratores</em> — os que rezam/dominam o saber);</li>\n<li><strong>Nobreza</strong> (<em>bellatores</em> — os senhores feudais guerreiros donos das terras);</li>\n<li><strong>Servos</strong> (<em>laboratores</em> — camponeses presos à terra, não eram escravos comprados/vendidos, mas pagavam pesados tributos como <strong>corveia</strong> [trabalho gratuito nas terras do senhor], <strong>talha</strong> [parte da produção] e <strong>banalidades</strong> [uso de forno/moinho]).</li>\n</ol></li>\n<li><strong>Política Descentralizada:</strong> O poder real enfraqueceu e pulverizou-se entre os senhores locais ligados pelo contrato de <strong>Suserania e Vassalagem</strong> (o <strong>suserano</strong> doava um <strong>feudo/terra</strong> ao <strong>vassalo</strong>, que jurava lealdade e apoio militar). A única instituição centralizadora unindo a Europa era a <strong>Igreja Católica (Teocentrismo)</strong>.</li>\n</ul>\n<hr />\n<h3 id=\"️️-dissecando-questões-reais-da-prova-m-tec\">🕵️‍♂️ Dissecando Questões Reais da Prova M-Tec</h3>\n<h4 id=\"questão-resolvida-1-baseada-em-m-tec-2022-q1--barroco\">Questão Resolvida 1 (Baseada em M-Tec 2022 Q1 — Barroco)</h4>\n<p><em>No Barroco brasileiro e português, a tendência marcada pelo jogo lógico de ideias, silogismos e raciocínio argumentativo, presente nos sermões de Padre Antônio Vieira, denomina-se _____; enquanto o rebuscamento formal com jogo de palavras e metáforas sensoriais denomina-se _____.</em></p>\n<ul>\n<li><strong>Gabarito:</strong> <strong>Conceptismo</strong> (ideias/lógica) e <strong>Cultismo</strong> (palavras/forma).</li>\n</ul>\n<h4 id=\"questão-resolvida-2-baseada-em-m-tec-2022-q4--figuras-de-linguagem\">Questão Resolvida 2 (Baseada em M-Tec 2022 Q4 — Figuras de Linguagem)</h4>\n<p><em>\"Vivemos em uma época em que estar hiperconectado no celular nos deixa cada vez mais solitários.\" A figura de linguagem dominante na contradição lógica entre estar \"hiperconectado\" e \"mais solitário\" numa mesma ideia é:</em></p>\n<ul>\n<li><strong>Gabarito:</strong> <strong>Paradoxo</strong> (ideias logicamente excludentes unidas numa mesma afirmação crítica).</li>\n</ul>\n<h4 id=\"questão-resolvida-3-baseada-em-m-tec-2022-q25--q27--neolítico-e-feudalismo\">Questão Resolvida 3 (Baseada em M-Tec 2022 Q25 &amp; Q27 — Neolítico e Feudalismo)</h4>\n<p><em>Sobre a Revolução Neolítica e o Feudalismo: I. A domesticação de plantas e animais no Neolítico permitiu a sedentarização humana. II. A economia feudal europeia era predominantemente industrial e centrada no comércio marítimo assalariado.</em></p>\n<ul>\n<li><strong>Item I:</strong> VERDADEIRO.</li>\n<li><strong>Item II:</strong> <strong>FALSO!</strong> O feudalismo era agrário, rural, de subsistência e baseado no trabalho <strong>servil</strong> (não assalariado industrial!).</li>\n</ul>\n", "practiceType": "cards", "practiceTag": "06_MTec_Base_Comum", "videoClips": [{"title": "Barroco no Brasil: Cultismo vs. Conceptismo", "channel": "Professor Noslen", "videoId": "1FN2jCxgnt0", "startSec": 190, "endSec": 520, "tip": "Foco: diferença direta entre Cultismo (jogo de palavras) e Conceptismo (jogo de ideias)."}, {"title": "Passo a Passo para Entender as Figuras de Linguagem", "channel": "Professor Noslen", "videoId": "n0e75nRstcU", "startSec": 90, "endSec": 450, "tip": "Foco: Metáfora, Antítese e Paradoxo com exemplos rápidos e fáceis."}], "challengeRefs": [{"examId": "mtec2022", "qNum": 1}, {"examId": "mtec2022", "qNum": 2}, {"examId": "mtec2022", "qNum": 3}, {"examId": "mtec2022", "qNum": 4}, {"examId": "mtec2022", "qNum": 5}, {"examId": "mtec2022", "qNum": 6}, {"examId": "mtec2022", "qNum": 24}, {"examId": "mtec2022", "qNum": 25}, {"examId": "mtec2022", "qNum": 26}, {"examId": "mtec2022", "qNum": 27}]}, {"day": 13, "title": "Base Comum M-Tec: Matemática, Química, Física e Biologia/Ambiental", "weight": "Máxima", "storyIntro": "Capítulo 13 (Especial M-Tec): Calcule conjuntos (A∩B∪C), Bhaskara/vértice, geometria 3-4-5, contagem sem zero à esquerda, massa molar, condutividade e óptica das cores.", "lessonHtml": "<h2 id=\"dia-13--base-comum-m-tec-ii-matemática-química-física-e-biologiameio-ambiente-1º-ano-em\">Dia 13 — Base Comum M-Tec II: Matemática, Química, Física e Biologia/Meio Ambiente (1º Ano EM)</h2>\n<h3 id=\"-contexto-no-mundo-real-pontos-decisivos-que-diferenciam-quem-passa\">🎯 Contexto no Mundo Real: Pontos Decisivos que Diferenciam Quem Passa</h3>\n<p>Em provas do <strong>M-Tec 2º Ano</strong> (como vimos nas questões reais <strong>M-Tec 2022 Q10–Q23 e Q33</strong>), quem estuda só informática costuma deixar pontos valiosos na mesa em <strong>Conjuntos Numéricos, Contagem, Função Quadrática, Áreas com Pitágoras, Massa Molar, Condutividade de Ligações Químicas e Óptica das Cores</strong>. A excelente notícia é que os problemas cobrados pela banca seguem <strong>fórmulas diretas e limpas</strong>, fáceis de dominar quando entendemos o raciocínio por trás de cada conta!</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Você encontra Matemática, Química e Física do 1º ano funcionando dentro dos próprios jogos e do seu PC:</p>\n<ul>\n<li><strong>Contagem (Combinações de PIN / Senha / Tag):</strong> Quer criar uma senha/código numérico de 3 dígitos distintos sem começar com <code>0</code>? Você calcula passo a passo quantas opções existem em cada slot — começando sempre pela casa que tem restrição (<code>0</code> proibido na frente!).</li>\n<li><strong>Função do 2º Grau (<code>ax² + bx + c</code>) = Trajetória de Granada / Flecha / Bola:</strong> Quando você joga uma granada para cima, ela sobe até o <strong>ponto máximo (Vértice <code>y_v</code>)</strong> e cai formando uma <strong>parábola com concavidade para baixo (<code>a &lt; 0</code>)</strong>! E quando cai numa conta de lucro mínimo, <code>a &gt; 0</code>.</li>\n<li><strong>Geometria <code>3-4-5</code> = Distância em Diagonal / Hitbox no Mapa:</strong> Se um player andou <code>30m</code> para o Norte e <code>40m</code> para o Leste, a distância em linha reta (<em>Pitágoras</em>) fecha exatamente <strong><code>50m</code></strong> sem precisar sofrer na raiz quadrada!</li>\n<li><strong>Química nos Cabos e Bateria do PC:</strong>\n<ul>\n<li>Os fios de <strong>Cobre (<code>Cu</code>)</strong> dentro do seu PC e USB conduzem eletricidade direto no <strong>estado SÓLIDO</strong> porque são <strong>Metais</strong> (mar de elétrons livres).</li>\n<li>Água pura (destilada) ou plástico isolante da capa do fio é <strong>Molecular/Covalente</strong> (não conduz!), mas se cair sal (<code>NaCl</code>, <strong>Iônico</strong>) dissolvido na água, libera íons e <strong>conduz corrente na hora</strong>!</li>\n</ul></li>\n<li><strong>Óptica das Cores na Tela/Iluminação:</strong> Quando uma lâmpada RGB verde ilumina um objeto vermelho opaco, ele não tem luz vermelha para refletir de volta — absorve o verde e fica <strong>PRETO</strong>!</li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--matemática-do-1º-ano-passo-a-passo-m-tec-q19q23\">📚 Parte 1 — Matemática do 1º Ano Passo a Passo <em>(M-Tec Q19–Q23)</em></h3>\n<h4 id=\"1-os-conjuntos-numéricos-ℕ-ℤ-ℚ-𝕀-ℝ-m-tec-q19\">1. Os Conjuntos Numéricos (<code>ℕ, ℤ, ℚ, 𝕀, ℝ</code>) <em>(M-Tec Q19)</em></h4>\n<p>Entenda onde cada número \"mora\" para nunca errar dízimas periódicas nem raízes:</p>\n<ul>\n<li><strong><code>ℕ</code> (Naturais):</strong> Inteiros de contagem não negativos <code>{0, 1, 2, 3, 4, ...}</code>.</li>\n<li><strong><code>ℤ</code> (Inteiros):</strong> Acrescenta os negativos exatos <code>{..., -3, -2, -1, 0, 1, 2, ...}</code>. Logo, todo Natural é Inteiro (<code>ℕ ⊂ ℤ</code>).</li>\n<li><strong><code>ℚ</code> (Racionais):</strong> Qualquer número que <strong>pode ser escrito em forma de fração <code>a / b</code></strong> (<code>b ≠ 0</code>). Isso inclui:\n<ul>\n<li>Todos os inteiros (<code>5 = 5/1</code>);</li>\n<li>Decimais exatos/finitos (<code>0,25 = 1/4</code>; <code>1,75 = 7/4</code>);</li>\n<li><strong>Todas as DÍZIMAS PERIÓDICAS (infinitas com repetição padrão)!</strong> Ex.: <code>0,333... = 1/3</code>, <code>0,454545... = 45/99 = 5/11</code> → Logo, <strong>dízima periódica é RACIONAL (<code>ℚ</code>)!</strong></li>\n</ul></li>\n<li><strong><code>𝕀</code> (Irracionais):</strong> Números decimais <strong>infinitos e NÃO periódicos</strong> que <strong>jamais viram fração exata</strong>: <code>π ≈ 3,14159265...</code>, <code>e ≈ 2,71828...</code>, raízes não exatas (<code>√2 ≈ 1,41421...</code>, <code>√3</code>, <code>√5</code>). <em>(Atenção: <code>√9 = 3</code>, logo <code>√9</code> é Natural/Racional, NÃO irracional!)</em></li>\n<li><strong><code>ℝ</code> (Reais):</strong> A união dos Racionais + Irracionais (<code>ℝ = ℚ ∪ 𝕀</code>). Importante: <code>ℚ ∩ 𝕀 = ∅</code> (nenhum número pertence aos dois ao mesmo tempo!).</li>\n</ul>\n<h4 id=\"2-operações-entre-conjuntos-e-diagrama-de-venn-m-tec-q22\">2. Operações entre Conjuntos e Diagrama de Venn <em>(M-Tec Q22)</em></h4>\n<p>Dados dois ou três conjuntos finitos:</p>\n<ul>\n<li><strong>Interseção (<code>A ∩ B</code>):</strong> Pega <strong>apenas os elementos em comum</strong> (que aparecem dentro de <code>A</code> <strong>E</strong> dentro de <code>B</code>).</li>\n<li><strong>União (<code>A ∪ B</code>):</strong> Junta <strong>todos</strong> os elementos de <code>A</code> e de <code>B</code> num conjunto só, <strong>sem repetir duplicatas</strong>.</li>\n<li><strong>Diferença (<code>A - B</code>):</strong> Pega os elementos de <code>A</code>, <strong>removendo</strong> qualquer um que também pertença a <code>B</code>.</li>\n</ul>\n<p><strong>💻 Exemplo Resolvido Passo a Passo (estilo M-Tec Q22):</strong> Se <code>A = {1, 2, 4, 6}</code>, <code>B = {2, 3, 6, 8}</code> e <code>C = {3, 9}</code>, quanto vale <strong><code>(A ∩ B) ∪ C</code></strong>?</p>\n<ol>\n<li><strong>Regra dos parênteses primeiro:</strong> <code>A ∩ B</code> = o que existe em <code>A</code> e em <code>B</code> ao mesmo tempo → <strong><code>{2, 6}</code></strong>.</li>\n<li>Agora fazemos a união com <code>C</code>: <code>{2, 6} ∪ {3, 9}</code> → juntando e ordenando: <strong><code>{2, 3, 6, 9}</code></strong>! <em>(Nota: em problemas de pesquisa — \"80 gostam de Python, 50 de JS e 20 de ambos\" — lembre-se sempre de <strong>começar preenchendo o centro da interseção (<code>20</code>)</strong> no diagrama e descontar <code>80 - 20 = 60 só Python</code> e <code>50 - 20 = 30 só JS</code>, evitando contar os 20 alunos duas vezes!)</em></li>\n</ol>\n<h4 id=\"3-princípio-fundamental-da-contagem-com-o-dígito-zero-m-tec-q23\">3. Princípio Fundamental da Contagem com o Dígito Zero <em>(M-Tec Q23)</em></h4>\n<p><strong>Pergunta clássica:</strong> <em>Quantos números naturais de <strong>3 algarismos distintos</strong> podemos formar usando o conjunto <code>{0, 1, 2, 3, 4, 5}</code>?</em></p>\n<ol>\n<li>Desenhe 3 tracinhos para as casas: <code>[ Centena ] × [ Dezena ] × [ Unidade ]</code>.</li>\n<li><strong>A Pegadinha Fatal do Zero:</strong> Um número natural de 3 algarismos <strong>NUNCA pode começar com <code>0</code></strong> (pois <code>045</code> equivale a <code>45</code>, que só tem 2 algarismos!).</li>\n<li>Preenchendo <strong>da esquerda para a direita (começando pela restrição!)</strong>:\n<ul>\n<li><strong>1ª casa (Centena):</strong> Dos 6 dígitos <code>{0,1,2,3,4,5}</code>, o <code>0</code> está proibido! Sobram <strong>5 opções</strong> (<code>1, 2, 3, 4</code> ou <code>5</code>).</li>\n<li><strong>2ª casa (Dezena):</strong> Já usamos 1 dígito na centena (digamos o <code>3</code>), mas <strong>agora o <code>0</code> está liberado</strong>! Dos 6 originais menos o <code>3</code> já gasto, restam <strong>5 opções</strong> (<code>0, 1, 2, 4, 5</code>)!</li>\n<li><strong>3ª casa (Unidade):</strong> Dos 6 dígitos, já gastamos 2 distintos. Restam <strong>4 opções</strong>!</li>\n</ul></li>\n<li>Multiplicamos tudo: <strong><code>5 × 5 × 4 = 100 números distintos</code></strong>! <em>(E se permitisse repetição? Seria <code>5 × 6 × 6 = 180</code>!).</em></li>\n</ol>\n<h4 id=\"4-função-afim-1º-grau-e-função-quadrática-2º-grau-m-tec-q20\">4. Função Afim (1º Grau) e Função Quadrática (2º Grau) <em>(M-Tec Q20)</em></h4>\n<ul>\n<li><strong>Função Afim (<code>f(x) = ax + b</code>):</strong> Gráfico é uma reta. <code>a</code> é a taxa de variação (inclinação: se <code>a &gt; 0</code> crescente; <code>a &lt; 0</code> decrescente); <code>b</code> é o valor fixo inicial onde a reta corta o eixo Y (<code>x = 0</code>).</li>\n<li><strong>Função Quadrática (<code>f(x) = ax² + bx + c</code>, com <code>a ≠ 0</code>):</strong> Gráfico é uma <strong>parábola</strong>:\n<ul>\n<li>Se <strong><code>a &gt; 0</code></strong>: concavidade voltada para <strong>CIMA</strong> (tem <strong>ponto de MÍNIMO</strong>).</li>\n<li>Se <strong><code>a &lt; 0</code></strong>: concavidade voltada para <strong>BAIXO</strong> (tem <strong>ponto de MÁXIMO</strong> — ótimo para lucro/altura máxima!).</li>\n<li><strong>Raízes (zeros da função, <code>ax² + bx + c = 0</code>):</strong>\n<ol>\n<li>Discriminante: <strong><code>Δ = b² - 4 · a · c</code></strong>\n<ul>\n<li><code>Δ &gt; 0</code> → <strong>duas raízes reais distintas</strong>;</li>\n<li><code>Δ = 0</code> → <strong>uma única raiz real dupla</strong> (toca o eixo X num ponto);</li>\n<li><code>Δ &lt; 0</code> → <strong>não possui raízes reais</strong> (não toca o eixo X).</li>\n</ul></li>\n<li>Bhaskara: <strong><code>x = (-b ± √Δ) / (2a)</code></strong>.</li>\n</ol></li>\n<li><strong>Vértice da Parábola (Máximo ou Mínimo):</strong> <strong><code>x_v = -b / (2a)</code></strong> e <strong><code>y_v = -Δ / (4a)</code></strong> (ou apenas substitua o valor achado de <code>x_v</code> na própria função <code>f(x)</code>!).</li>\n</ul></li>\n</ul>\n<p><strong>💻 Exemplo Resolvido:</strong> Para <code>f(x) = x² - 5x + 6</code>:</p>\n<ul>\n<li><code>a = 1 (&gt; 0 → concavidade p/ cima)</code>, <code>b = -5</code>, <code>c = 6</code>.</li>\n<li><code>Δ = (-5)² - 4(1)(6) = 25 - 24 = 1 (&gt; 0 → 2 raízes reais distintas!)</code>.</li>\n<li><code>x = (5 ± √1) / 2</code> → <strong><code>x₁ = 3</code></strong> e <strong><code>x₂ = 2</code></strong>. Vértice: <code>x_v = 5/2 = 2,5</code> e <code>y_v = (2,5)² - 5(2,5) + 6 = -0,25</code>.</li>\n</ul>\n<h4 id=\"5-geometria-plana-triângulo-3-4-5-e-decomposição-de-áreas-m-tec-q21\">5. Geometria Plana, Triângulo 3-4-5 e Decomposição de Áreas <em>(M-Tec Q21)</em></h4>\n<ul>\n<li><strong>Fórmulas essenciais:</strong>\n<ul>\n<li>Retângulo / Paralelogramo: <code>A = base × altura</code></li>\n<li>Triângulo: <code>A = (base × altura) / 2</code></li>\n<li>Trapézio: <code>A = ((B + b) × h) / 2</code></li>\n<li>Círculo: <code>A = π · r²</code> e Comprimento: <code>C = 2 · π · r</code></li>\n</ul></li>\n<li><strong>Teorema de Pitágoras &amp; Triângulo 3-4-5:</strong> Num triângulo retângulo, <code>hipotenusa² = cateto₁² + cateto₂²</code>.\n<ul>\n<li>Sempre que você vir catetos múltiplos de <strong>3 e 4</strong>, a hipotenusa é múltiplo de <strong>5</strong> sem precisar fazer conta gigante! Ex.: <strong><code>30m</code> e <code>40m</code> → hipotenusa <code>50m</code></strong> (<code>30² + 40² = 900 + 1600 = 2500 = 50²</code>), e área = <code>(30 × 40) / 2 = 600 m²</code>!</li>\n</ul></li>\n<li><strong>Resolvendo terreno composto <em>(M-Tec Q21)</em>:</strong> Divida figuras em L ou chanfradas em um retângulo + um triângulo retângulo (ou trapézio + retângulo) e <strong>some as áreas individuais</strong>. Exemplo da prova: terreno composto formado por retângulo + trapézio/triângulo totalizando <strong><code>2.320 m²</code></strong> (como <code>40m × 58m = 2.320 m²</code> ou retângulo <code>40 × 43 = 1.720 m²</code> + triângulo <code>30×40/2 = 600 m²</code> → <strong><code>1.720 + 600 = 2.320 m²</code></strong>!).</li>\n</ul>\n<hr />\n<h3 id=\"-parte-2--química-do-1º-ano-ligações-condutividade-e-massa-molar-m-tec-q17q18\">📚 Parte 2 — Química do 1º Ano: Ligações, Condutividade e Massa Molar <em>(M-Tec Q17–Q18)</em></h3>\n<h4 id=\"1-ligações-químicas--condutividade-elétrica-m-tec-q18--quase-100-de-chance-na-prova\">1. Ligações Químicas &amp; Condutividade Elétrica <em>(M-Tec Q18 — Quase 100% de chance na prova!)</em></h4>\n<p>Para haver corrente elétrica, é obrigatório existir <strong>cargas elétricas livres para se movimentar</strong> (elétrons livres ou íons soltos):</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: left;\">Tipo de Ligação</th>\n<th style=\"text-align: left;\">Como os átomos se unem</th>\n<th style=\"text-align: left;\">Exemplos Reais</th>\n<th style=\"text-align: left;\">Conduz Eletricidade? (DECORE ISSO!)</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>1. Ligação Metálica</strong> <em>(Metal + Metal)</em></td>\n<td style=\"text-align: left;\">Átomos doam elétrons externos formando um <strong>\"mar de elétrons\" móveis</strong> ao redor dos cátions.</td>\n<td style=\"text-align: left;\">Ferro (<code>Fe</code>), Cobre (<code>Cu</code>), Alumínio (<code>Al</code>), Ouro (<code>Au</code>)</td>\n<td style=\"text-align: left;\"><strong>CONDUZ no estado SÓLIDO</strong> e no líquido! (Por isso fios elétricos são de cobre sólido!).</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: left;\"><strong>2. Ligação Iônica</strong> <em>(Metal + Ametal/H)</em></td>\n<td style=\"text-align: left;\"><strong>Transferência definitiva</strong> de elétrons formando <strong>íons</strong> positivos (<code>+</code>) e negativos (<code>-</code>) presos num cristal rígido.</td>\n<td style=\"text-align: left;\">Sal de cozinha (<code>NaCl</code>), Fluoreto (<code>NaF</code>), Óxidos metálicos (<code>CaO</code>)</td>\n<td style=\"text-align: left;\"><strong>NÃO conduz no estado SÓLIDO</strong> (íons presos na rede cristalina), mas <strong>CONDUZ quando LÍQUIDO/FUNDIDO (derretido) ou DISSOLVIDO EM ÁGUA</strong> (pois os íons ficam livres!).</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: left;\"><strong>3. Ligação Covalente (Molecular)</strong> <em>(Ametal + Ametal / Hidrogênio)</em></td>\n<td style=\"text-align: left;\">Átomos <strong>compartilham pares de elétrons</strong> formando moléculas eletricamente neutras, sem íons!</td>\n<td style=\"text-align: left;\">Açúcar (<code>C₁₂H₂₂O₁₁</code>), Álcool (<code>C₂H₅OH</code>), Água pura (<code>H₂O</code>), Oxigênio (<code>O₂</code>)</td>\n<td style=\"text-align: left;\"><strong>NÃO conduz eletricidade NEM no estado SÓLIDO, NEM puro/líquido!</strong></td>\n</tr>\n</tbody>\n</table>\n<div class=\"callout callout-tip\">\n\n<p><strong>Resumo instantâneo da Tabela de Condutividade <em>(M-Tec Q18)</em>:</strong></p>\n<ul>\n<li>Conduz sólido <strong>E</strong> líquido? → <strong>Metal (Ligação Metálica)</strong>.</li>\n<li>Não conduz sólido, mas conduz líquido/aquoso? → <strong>Composto Iônico</strong>.</li>\n<li>Não conduz em nenhum estado? → <strong>Composto Molecular / Covalente</strong>.</li>\n</ul>\n</div>\n\n<h4 id=\"2-cálculo-de-massa-molecular-u--massa-molar-gmol-m-tec-q17\">2. Cálculo de Massa Molecular (<code>u</code>) / Massa Molar (<code>g/mol</code>) <em>(M-Tec Q17)</em></h4>\n<p>Basta multiplicar a massa atômica de cada elemento (dada no enunciado: geralmente <strong><code>H = 1</code>, <code>C = 12</code>, <code>N = 14</code>, <code>O = 16</code></strong>) pela quantidade de átomos que aparecem na fórmula:</p>\n<ol>\n<li><strong>Etanol / Álcool Etílico (<code>C₂H₅OH</code> ou <code>C₂H₆O</code>):</strong>\n<ul>\n<li><code>C</code>: <code>2 átomos × 12 = 24</code></li>\n<li><code>H</code>: <code>5 + 1 = 6 átomos × 1 = 6</code> <em>(Cuidado para não esquecer o <code>H</code> que fica depois do <code>O</code>!)</em></li>\n<li><code>O</code>: <code>1 átomo × 16 = 16</code></li>\n<li><strong>Total:</strong> <code>24 + 6 + 16 =</code> <strong><code>46 u</code> (<code>46 g/mol</code>)</strong>!</li>\n</ul></li>\n<li><strong>Ácido Acético / Vinagre (<code>C₂H₄O₂</code>):</strong>\n<ul>\n<li><code>C</code>: <code>2 × 12 = 24</code> | <code>H</code>: <code>4 × 1 = 4</code> | <code>O</code>: <code>2 × 16 = 32</code></li>\n<li><strong>Total:</strong> <code>24 + 4 + 32 =</code> <strong><code>60 u</code> (<code>60 g/mol</code>)</strong>!</li>\n</ul></li>\n<li><strong>Dióxido de Carbono (<code>CO₂</code>):</strong> <code>12 + 2×16 =</code> <strong><code>44 u</code></strong> | <strong>Glicose (<code>C₆H₁₂O₆</code>):</strong> <code>6×12 + 12×1 + 6×16 = 72 + 12 + 96 =</code> <strong><code>180 u</code></strong>.</li>\n</ol>\n<hr />\n<h3 id=\"-parte-3--física-óptica-das-cores--biologia--meio-ambiente-m-tec-q10q16--q33\">📚 Parte 3 — Física (Óptica das Cores) &amp; Biologia / Meio Ambiente <em>(M-Tec Q10–Q16 &amp; Q33)</em></h3>\n<h4 id=\"1-física--óptica-das-cores-por-reflexão-seletiva-m-tec-q33\">1. Física — Óptica das Cores por Reflexão Seletiva <em>(M-Tec Q33)</em></h4>\n<p>A luz solar (branca) é <strong>policromática</strong>, contendo todas as cores do espectro visível juntas (vermelho, laranja, amarelo, verde, azul, anil, violeta). A cor que enxergamos em um objeto opaco depende exclusivamente de <strong>qual cor da luz ele REFLETE</strong> até os nossos olhos (as demais são absorvidas em forma de calor):</p>\n<ul>\n<li><strong>Tomate maduro sob luz branca (Sol):</strong> Absorve azul, verde, amarelo etc., e <strong>REFLETE a luz vermelha</strong> → vemos <strong>vermelho</strong>!</li>\n<li><strong>Tomate vermelho dentro de uma sala iluminada APENAS com luz VERDE pura (monocromática):</strong> Como só chega luz verde, e o pigmento vermelho do tomate <strong>absorve</strong> a luz verde sem ter nenhuma luz vermelha para refletir, não volta luz alguma para nossos olhos → <strong>enxergamos o tomate PRETO!</strong></li>\n<li><strong>Camisa branca sob luz verde:</strong> O branco reflete <strong>todas</strong> as cores que chegam — se só chega luz verde, ele reflete verde → vemos <strong>verde</strong>!</li>\n<li><strong>Objeto preto:</strong> Absorve praticamente <strong>todas</strong> as cores (por isso esquenta rápido no Sol).</li>\n</ul>\n<h4 id=\"2-método-científico-m-tec-q10\">2. Método Científico <em>(M-Tec Q10)</em></h4>\n<p>Ordem lógica rigorosa da investigação científica:</p>\n<ol>\n<li><strong>Observação</strong> cuidadosa do fenômeno natural + <strong>Questionamento</strong>;</li>\n<li>Formulação de <strong>Hipótese</strong> (uma explicação provisória e <strong>testável</strong>);</li>\n<li><strong>Experimentação controlada</strong> (grupo teste × grupo controle) para testar a hipótese;</li>\n<li><strong>Coleta e Análise de Dados</strong>;</li>\n<li><strong>Conclusão</strong> (confirma, ajusta ou refuta a hipótese — conhecimento científico não é dogma imutável!).</li>\n</ol>\n<h4 id=\"3-sustentabilidade-poluentes-e-protocolo-de-kyoto-m-tec-q13q16\">3. Sustentabilidade, Poluentes e Protocolo de Kyoto <em>(M-Tec Q13–Q16)</em></h4>\n<ul>\n<li><strong>Desenvolvimento Sustentável:</strong> Atender às necessidades da geração atual <strong>sem comprometer</strong> a capacidade das gerações futuras (equilíbrio ambiental, social e econômico).</li>\n<li><strong>Efeito Estufa vs. Aquecimento Global:</strong> O Efeito Estufa <em>natural</em> é vital (retém calor na Terra evitando congelamento). O problema atual é a <strong>intensificação antrópica</strong> pelo excesso de gases como <strong><code>CO₂</code></strong> (queima de combustíveis fósseis, desmatamento) e <strong><code>CH₄</code> (metano)</strong>, gerando <strong>Aquecimento Global</strong> e derretimento de geleiras/eventos extremos.</li>\n<li><strong>Protocolo de Kyoto (1997):</strong> Tratado internacional pioneiro que estabeleceu metas obrigatórias para países desenvolvidos <strong>reduzirem emissões de gases do efeito estufa</strong>, criando o mecanismo de <strong>créditos de carbono</strong> (Mecanismo de Desenvolvimento Limpo).</li>\n<li><strong>Chuva Ácida &amp; Tabelas CETESB (<code>SO₂</code>):</strong> O dióxido de enxofre (<strong><code>SO₂</code></strong>) e óxidos de nitrogênio (<code>NOₓ</code>) liberados por indústrias/escapamentos reagem com a umidade do ar formando <strong>chuva ácida</strong> (danifica solos, lagos e monumentos). Em questões com tabela da <strong>CETESB</strong>, leia atentamente o cabeçalho da coluna, o ano pedido e confira a unidade (<code>µg/m³</code>).</li>\n</ul>\n<hr />\n<h3 id=\"️️-dissecando-questões-reais-da-prova-m-tec\">🕵️‍♂️ Dissecando Questões Reais da Prova M-Tec</h3>\n<h4 id=\"questão-resolvida-1-baseada-em-m-tec-2022-q18--q17--química\">Questão Resolvida 1 (Baseada em M-Tec 2022 Q18 &amp; Q17 — Química)</h4>\n<p><em>Três substâncias sólidas desconhecidas X, Y e Z foram testadas no laboratório:</em></p>\n<ul>\n<li><em>X não conduz corrente sólido, mas conduz muito bem quando fundido/líquido.</em></li>\n<li><em>Y conduz corrente elétrica já no estado sólido.</em></li>\n<li><em>Z não conduz nem sólido nem dissolvido em água.</em> <em>Classifique as ligações de X, Y e Z:</em></li>\n<li><strong>X</strong> = Composto <strong>Iônico</strong>; <strong>Y</strong> = <strong>Metálico</strong>; <strong>Z</strong> = <strong>Covalente / Molecular</strong>.</li>\n</ul>\n<h4 id=\"questão-resolvida-2-baseada-em-m-tec-2022-q23--contagem\">Questão Resolvida 2 (Baseada em M-Tec 2022 Q23 — Contagem)</h4>\n<p><em>Quantos números de 3 algarismos distintos podem ser formados com <code>{0, 2, 4, 6, 8}</code>?</em></p>\n<ul>\n<li>Cuidado com o <code>0</code> na centena!</li>\n<li>1ª casa (sem <code>0</code>): <strong>4 opções</strong> (<code>2, 4, 6, 8</code>).</li>\n<li>2ª casa (entra o <code>0</code>, sai a usada na 1ª): <strong>4 opções</strong>.</li>\n<li>3ª casa: <strong>3 opções</strong>.</li>\n<li>Total: <code>4 × 4 × 3 =</code> <strong><code>48 números</code></strong>!</li>\n</ul>\n<h4 id=\"questão-resolvida-3-baseada-em-m-tec-2022-q33--física-óptica\">Questão Resolvida 3 (Baseada em M-Tec 2022 Q33 — Física Óptica)</h4>\n<p><em>Num palco iluminado exclusivamente por refletores monocromáticos azuis, um artista entra vestindo uma camisa amarela pura e uma calça branca. Como o público enxergará a camisa e a calça?</em></p>\n<ul>\n<li><strong>Camisa amarela</strong> absorve luz azul (só refletiria amarelo/vermelho/verde) → parece <strong>PRETA</strong>.</li>\n<li><strong>Calça branca</strong> reflete todas as cores incidentes → parece <strong>AZUL</strong>!</li>\n</ul>\n", "practiceType": "lab_mtec", "practiceTag": "06_MTec_Base_Comum", "videoClips": [{"title": "Conjuntos Numéricos: Naturais, Inteiros, Racionais e Irracionais", "channel": "Professor Ferretto", "videoId": "Bq5XYZKXk-Q", "startSec": 30, "endSec": 390, "tip": "Foco: por que dízimas periódicas são Racionais (ℚ) vs. Irracionais (𝕀) e diagramas."}, {"title": "Ligações Químicas: Iônica, Covalente e Metálica", "channel": "Brasil Escola", "videoId": "FDnxddw0P1g", "startSec": 45, "endSec": 375, "tip": "Foco: estrutura e por que Metal conduz sólido enquanto Iônico só conduz líquido/aquoso."}], "challengeRefs": [{"examId": "mtec2022", "qNum": 10}, {"examId": "mtec2022", "qNum": 13}, {"examId": "mtec2022", "qNum": 14}, {"examId": "mtec2022", "qNum": 17}, {"examId": "mtec2022", "qNum": 18}, {"examId": "mtec2022", "qNum": 19}, {"examId": "mtec2022", "qNum": 21}, {"examId": "mtec2022", "qNum": 22}, {"examId": "mtec2022", "qNum": 23}, {"examId": "mtec2022", "qNum": 33}]}, {"day": 14, "title": "Revisão Final 'Cola de Bolso' & Estratégia para o Dia da Prova (04/12)", "weight": "Essencial", "storyIntro": "Capítulo Final: Revise os 15 pontos de ouro que somam ~90% da prova, aplique a estratégia das 3 passadas e enfrente um teste misto final sem estresse!", "lessonHtml": "<h2 id=\"dia-14--revisão-integrada-final-as-25-pegadinhas-da-banca-fat-e-estratégia-para-a-prova-de-0412\">Dia 14 — Revisão Integrada Final, as 25 Pegadinhas da Banca FAT e Estratégia para a Prova de 04/12</h2>\n<h3 id=\"-contexto-no-mundo-real-juntando-todas-as-peças-no-sistema-completo\">🎯 Contexto no Mundo Real: Juntando Todas as Peças no Sistema Completo</h3>\n<p>Pare por 30 segundos e enxergue como tudo o que você estudou nestes <strong>14 dias</strong> trabalha junto num único sistema real — por exemplo, quando você abre o navegador no PC da Etec para responder a uma prova online:</p>\n<ol>\n<li>No <strong>Design (Dia 8)</strong>, a interface usou cores <strong>RGB / <code>#Hexadecimal</code></strong>, logo vetorial <strong><code>.SVG</code></strong>, fonte sem serifa do <strong>Google Fonts</strong>, espaçamento por <strong>Proximidade (Gestalt)</strong> e respeitou a <strong>Equivalência com o Mundo Real (Nielsen)</strong>.</li>\n<li>No <strong>Front-end Web (Dia 9)</strong>, a tela foi montada com <strong>HTML5 Semântico</strong> (<code>&lt;header&gt;</code>, <code>&lt;main&gt;</code>, <code>&lt;form method=\"POST\"&gt;</code>), estilizada com <strong>CSS3 Box Model</strong> (<code>padding</code>/<code>margin</code>), alterada dinamicamente via árvore <strong>DOM</strong> em JavaScript (construído com <strong>Frameworks</strong> e empacotado por <strong>Build/Bundling</strong> do <strong>Dia 4</strong> sob <strong>Git</strong> e licença <strong>MIT/GPL</strong>) e manteve sua sessão em um <strong>Cookie local (~4 KB)</strong>.</li>\n<li>Na <strong>Rede (Dia 11)</strong>, seu pedido viajou pela pilha <strong>TCP/IP</strong>, traduzido pelo <strong>DNS</strong>, criptografado via <strong>HTTPS (SSL/TLS)</strong>, através da rede local <strong>Estrela (Switch)</strong> até servidores <strong>Linux</strong> (<code>/etc</code>, <code>/var/log</code> — <strong>Dia 10</strong>) rodando em <strong>Contêineres Docker</strong> na nuvem <strong>PaaS/IaaS</strong>.</li>\n<li>No <strong>Back-end e Banco de Dados (Dias 1–7)</strong>, o servidor recebeu dados tipados/convertidos (<strong>Casting</strong>, <strong>POO</strong>, <strong>Scrum</strong>), consultou um banco relacional normalizado na <strong>1FN</strong> (sem múltiplos telefones na célula!) usando <strong>DQL (<code>SELECT COUNT(*) WHERE...</code>)</strong> e <strong>DML (<code>INSERT</code>/<code>UPDATE</code>)</strong>, e devolveu sua nota!</li>\n</ol>\n<p>Você agora não sabe só \"dicas soltas\" — você entende a arquitetura completa de sistemas!</p>\n<hr />\n<h3 id=\"-conexão-gamer--discord-pra-entender-de-primeira\">🎮 Conexão Gamer &amp; Discord (Pra Entender de Primeira!)</h3>\n<p>Encare a prova de <strong>04/12</strong> como uma <strong>Speedrun estratégica em 3 fases</strong>, igual zerar um jogo no modo ranqueado sem tiltar numa fase difícil no meio:</p>\n<ul>\n<li><strong>Fase 1 (1ª Passada — <em>Loot Rápido</em>):</strong> Garante primeiro todas as questões fáceis e diretas (E-mail, Cookies, Tags HTML, Frameworks, Licenças, Inglês, Barroco, Paleolítico/Neolítico). Questão grande que pede conta? Dá <em>skip</em> marcado e volta já com pontos garantidos no bolso!</li>\n<li><strong>Fase 2 (2ª Passada — <em>Chefões de Cálculo e I-II-III</em>):</strong> Resolve com calma os Testes de Mesa, Matrizes, Binário/Hex, Matemática e Química desenhando passo a passo no rascunho — sem \"olhômetro\".</li>\n<li><strong>Fase 3 (3ª Passada — <em>Save Final / Gabarito</em>):</strong> Confere cada marcação no cartão-resposta sem pressa e nunca entrega bolinha em branco.</li>\n</ul>\n<hr />\n<h3 id=\"-parte-1--dicionário-das-25-pegadinhas-mais-recorrentes-da-fundação-fat\">📚 Parte 1 — Dicionário das 25 Pegadinhas Mais Recorrentes da Fundação FAT</h3>\n<p>Leia com muita atenção esta tabela antes da prova. Quase todo erro em questões I, II e III acontece exatamente por uma destas <strong>25 armadilhas verbais</strong>:</p>\n<table class=\"q-table\">\n<thead>\n<tr class=\"header\">\n<th style=\"text-align: center;\">Nº</th>\n<th style=\"text-align: left;\">Assunto</th>\n<th style=\"text-align: left;\">Frase FALSA que a banca inventa (NÃO CAIA!)</th>\n<th style=\"text-align: left;\">Verdade Oficial da Prova</th>\n</tr>\n</thead>\n<tbody>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>1</strong></td>\n<td style=\"text-align: left;\"><strong>Casting</strong></td>\n<td style=\"text-align: left;\"><code>(int) 7.99</code> converte para <code>8</code> arredondando.</td>\n<td style=\"text-align: left;\"><strong>TRUNCA (corta)</strong> a parte decimal → <strong><code>7</code></strong>! E só se chama <strong>explícita/casting</strong> (nunca \"conversão normal\").</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>2</strong></td>\n<td style=\"text-align: left;\"><strong>Tipos</strong></td>\n<td style=\"text-align: left;\"><code>'A'</code> ou <code>12</code> usa tipo booleano (<code>bool</code>).</td>\n<td style=\"text-align: left;\"><code>'A'</code> usa <strong><code>char</code></strong>; <code>\"texto\"</code> usa <strong><code>string</code></strong>; <code>bool</code> guarda <strong>exclusivamente <code>true</code>/<code>false</code></strong>.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>3</strong></td>\n<td style=\"text-align: left;\"><strong>DIV / MOD</strong></td>\n<td style=\"text-align: left;\"><code>17 MOD 5</code> vale <code>3</code> e <code>17 DIV 5</code> vale <code>2</code>.</td>\n<td style=\"text-align: left;\"><strong><code>DIV</code></strong> = quociente inteiro (<strong><code>3</code></strong>); <strong><code>MOD</code></strong> = <strong>resto</strong> da divisão (<strong><code>2</code></strong>).</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>4</strong></td>\n<td style=\"text-align: left;\"><strong>Teste de Mesa</strong></td>\n<td style=\"text-align: left;\">No <code>enquanto (x &lt;= 6)</code>, ao sair <code>x</code> ainda vale <code>6</code>.</td>\n<td style=\"text-align: left;\">O último incremento ainda acontece na última volta! Confira a tabela até a condição dar <strong>Falso</strong>.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>5</strong></td>\n<td style=\"text-align: left;\"><strong>Matrizes</strong></td>\n<td style=\"text-align: left;\">Somar diagonal secundária achando que é a principal.</td>\n<td style=\"text-align: left;\">Diagonal <strong>Principal</strong> é <strong><code>i == j</code></strong> (<code>[0][0], [1][1], [2][2]</code>). Secundária é <code>i + j == N - 1</code>.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>6</strong></td>\n<td style=\"text-align: left;\"><strong>Pilha vs Fila</strong></td>\n<td style=\"text-align: left;\">Em Pilha (<code>LIFO</code>), <code>POP</code> remove o primeiro que entrou.</td>\n<td style=\"text-align: left;\">Pilha = <strong>LIFO</strong> (<code>POP</code> remove o <strong>ÚLTIMO</strong> que entrou, do topo). Fila = <strong>FIFO</strong> (sai o primeiro).</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>7</strong></td>\n<td style=\"text-align: left;\"><strong>Frameworks</strong></td>\n<td style=\"text-align: left;\"><em>Creative Commons</em> ou <em>Adobe Creative Cloud</em> são frameworks.</td>\n<td style=\"text-align: left;\"><strong>Frameworks reais:</strong> Bootstrap, Angular, Laravel (PHP), React Native (Mobile). Os outros são licença/suíte design!</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>8</strong></td>\n<td style=\"text-align: left;\"><strong>Editores</strong></td>\n<td style=\"text-align: left;\">Bloco de Notas (Notepad) é uma IDE completa.</td>\n<td style=\"text-align: left;\">Bloco de Notas = <strong>editor de texto puro</strong>; <strong>VS Code</strong> = editor de código; <strong>Visual Studio / Eclipse</strong> = IDE; <strong>Dreamweaver/Wix</strong> = WYSIWYG.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>9</strong></td>\n<td style=\"text-align: left;\"><strong>Licenças</strong></td>\n<td style=\"text-align: left;\">Software Livre significa necessariamente gratuito (<code>R$ 0</code>).</td>\n<td style=\"text-align: left;\"><strong>Software Livre</strong> garante <strong>4 liberdades de código aberto</strong> (pode ser vendido!). Já <strong>Freeware</strong> é grátis, mas de <strong>código fechado</strong>!</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>10</strong></td>\n<td style=\"text-align: left;\"><strong>Scrum &amp; XP</strong></td>\n<td style=\"text-align: left;\">Scrum Master chefia tarefas; Pair Programming = cada dev em uma sala.</td>\n<td style=\"text-align: left;\"><strong>SM</strong> facilita/remove impedimentos; <strong>PO</strong> prioriza backlog; <strong>Daily</strong> &lt;= 15 min; <strong>Pair Programming</strong> = <strong>2 devs no mesmo PC</strong>.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>11</strong></td>\n<td style=\"text-align: left;\"><strong>POO</strong></td>\n<td style=\"text-align: left;\">Classe, Atributo e Método são os pilares da POO.</td>\n<td style=\"text-align: left;\">Os <strong>4 Pilares</strong> oficiais são: <strong>Abstração, Encapsulamento, Herança e Polimorfismo</strong>.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>12</strong></td>\n<td style=\"text-align: left;\"><strong>SQL DDL/DML/DQL</strong></td>\n<td style=\"text-align: left;\"><code>DROP</code> é DML; <code>SELECT</code> é DDL; <code>COUNT(*)</code> vai no <code>WHERE</code>.</td>\n<td style=\"text-align: left;\"><strong>DDL</strong> = <code>CREATE/ALTER/DROP</code> (estrutura); <strong>DML</strong> = <code>INSERT/UPDATE/DELETE</code> (dados); <strong>DQL</strong> = <code>SELECT</code> (<code>COUNT(*)</code> vai no <code>SELECT</code>!).</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>13</strong></td>\n<td style=\"text-align: left;\"><strong>1FN &amp; DER</strong></td>\n<td style=\"text-align: left;\">Vários telefones na mesma célula (<code>\"111, 222\"</code>) atende à 1FN.</td>\n<td style=\"text-align: left;\">Viola a <strong>1ª Forma Normal (1FN)</strong> (exige valores <strong>atômicos</strong>)! E <strong><code>idade</code></strong> via <code>data_nasc</code> é atributo <strong>derivado</strong>.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>14</strong></td>\n<td style=\"text-align: left;\"><strong>Cores</strong></td>\n<td style=\"text-align: left;\">RGB é para gráfica/papel; \"CSS\" ou \"Primária\" é padrão de cor.</td>\n<td style=\"text-align: left;\"><strong>RGB</strong> / <strong>Hex</strong> = telas (luz aditiva); <strong>CMYK</strong> = impressão (tinta).</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>15</strong></td>\n<td style=\"text-align: left;\"><strong>Vetor vs Bitmap</strong></td>\n<td style=\"text-align: left;\"><code>.JPEG</code> e <code>.PNG</code> são formatos vetoriais sem pixelação.</td>\n<td style=\"text-align: left;\"><strong>Vetorial</strong> = <strong><code>.SVG</code> / <code>.PDF</code></strong> (equações matemáticas, zoom sem perda). <strong>Bitmap</strong> = <code>.JPEG</code>, <code>.PNG</code>, <code>.BMP</code>.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>16</strong></td>\n<td style=\"text-align: left;\"><strong>Gestalt &amp; UX</strong></td>\n<td style=\"text-align: left;\">Rótulo colado ao campo é Fechamento; fonte <em>Script</em> serve para texto longo.</td>\n<td style=\"text-align: left;\">Perto = <strong>Proximidade</strong>; mesmo estilo = <strong>Semelhança</strong>. Fonte <strong>Script</strong> imita letra cursiva (só títulos/convites!).</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>17</strong></td>\n<td style=\"text-align: left;\"><strong>Cookies</strong></td>\n<td style=\"text-align: left;\">Cookies são pesados e armazenados nos servidores em nuvem.</td>\n<td style=\"text-align: left;\">Cookies são <strong>texto pequeno (~4 KB) salvos LOCALMENTE no navegador do cliente</strong> (sessão ou persistente)!</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>18</strong></td>\n<td style=\"text-align: left;\"><strong>HTML &amp; CSS</strong></td>\n<td style=\"text-align: left;\"><code>&lt;div&gt;</code> é tag semântica; <code>&lt;tr&gt;</code> é célula; <code>GET</code> esconde senha.</td>\n<td style=\"text-align: left;\"><strong><code>&lt;div&gt;</code> é genérica</strong> (<code>&lt;header&gt;/&lt;nav&gt;/&lt;main&gt;/&lt;article&gt;/&lt;footer&gt;</code> são semânticas); <code>&lt;tr&gt;</code> = linha, <code>&lt;td&gt;</code> = célula; senha vai no <strong><code>POST</code></strong>; <code>padding</code> = interno, <code>margin</code> = externo.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>19</strong></td>\n<td style=\"text-align: left;\"><strong>Binário &amp; Hex</strong></td>\n<td style=\"text-align: left;\"><code>250</code> em hexadecimal é <code>250</code> ou <code>F0</code>.</td>\n<td style=\"text-align: left;\"><code>250 ÷ 16</code> = <code>15(F)</code> resto <code>10(A)</code> = <strong><code>FA₁₆</code></strong> (<code>100</code> = <code>64₁₆</code>; <code>255</code> = <code>11111111₂</code> = <code>FF₁₆</code>).</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>20</strong></td>\n<td style=\"text-align: left;\"><strong>Linux Pastas</strong></td>\n<td style=\"text-align: left;\"><code>/mkdir</code>, <code>/ls</code>, <code>/rm</code>, <code>/cd</code> são diretórios do Linux.</td>\n<td style=\"text-align: left;\">São <strong>COMANDOS</strong>, não pastas! Pastas reais FHS: <strong><code>/bin, /etc, /home, /lib, /root, /usr, /var, /tmp</code></strong>.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>21</strong></td>\n<td style=\"text-align: left;\"><strong>Contêiner vs VM</strong></td>\n<td style=\"text-align: left;\">Contêiner Docker instala um Kernel completo novo por dentro.</td>\n<td style=\"text-align: left;\">Contêiner <strong>compartilha o Kernel</strong> do hospedeiro (leve); quem virtualiza SO inteiro é <strong>VM + Hypervisor</strong>.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>22</strong></td>\n<td style=\"text-align: left;\"><strong>E-mail</strong></td>\n<td style=\"text-align: left;\">SMTP recebe/sincroniza e IMAP ou POP3 envia.</td>\n<td style=\"text-align: left;\"><strong>SMTP</strong> = <strong>Envia</strong>; <strong>POP3</strong> = Baixa e apaga do servidor; <strong>IMAP</strong> = Sincroniza no servidor.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>23</strong></td>\n<td style=\"text-align: left;\"><strong>Topologias</strong></td>\n<td style=\"text-align: left;\">Na topologia Estrela, romper 1 cabo derruba toda a rede.</td>\n<td style=\"text-align: left;\">Na <strong>Estrela (Switch)</strong> cai só aquele PC; quem derruba tudo ao romper cabo único é <strong>Barramento (<em>Bus</em>)</strong>.</td>\n</tr>\n<tr class=\"even\">\n<td style=\"text-align: center;\"><strong>24</strong></td>\n<td style=\"text-align: left;\"><strong>Português/História</strong></td>\n<td style=\"text-align: left;\">Cultismo = jogo de ideias; Neolítico = nômade sem agricultura.</td>\n<td style=\"text-align: left;\"><strong>Cultismo</strong> = palavras/forma; <strong>Conceptismo</strong> = ideias/lógica; <strong>Neolítico</strong> = agricultura + sedentário; <strong>Paleolítico</strong> = nômade.</td>\n</tr>\n<tr class=\"odd\">\n<td style=\"text-align: center;\"><strong>25</strong></td>\n<td style=\"text-align: left;\"><strong>Mat/Quím/Física</strong></td>\n<td style=\"text-align: left;\">Dízima periódica é Irracional; composto iônico conduz sólido; nº de 3 dígitos começa com <code>0</code>.</td>\n<td style=\"text-align: left;\">Dízima é <strong>Racional (<code>ℚ</code>)</strong>; <strong>Metal</strong> conduz sólido, <strong>Iônico</strong> só líquido/aquoso; <code>0</code> proibido na 1ª casa; tomate vermelho sob luz verde parece <strong>PRETO</strong>!</td>\n</tr>\n</tbody>\n</table>\n<hr />\n<h3 id=\"-parte-2--método-cirúrgico-para-questões-i-ii-e-iii--revisão-comentada\">📚 Parte 2 — Método Cirúrgico para Questões I, II e III + Revisão Comentada</h3>\n<h4 id=\"técnica-de-eliminação-em-15-segundos\">Técnica de Eliminação em 15 Segundos</h4>\n<p>Quando enfrentar qualquer questão longa com afirmativas <strong>I, II e III</strong>:</p>\n<ol>\n<li>Leia buscando <strong>palavras absolutas perigosas</strong>: <em>\"sempre\", \"nunca\", \"exclusivamente\", \"unicamente\"</em> — costumam esconder erro!</li>\n<li>Ache <strong>1 único item que você tem 100% de certeza que é FALSO</strong> e risque todas as letras (A–E) que contenham esse número. Na maioria das provas da FAT, eliminar 1 item errado já elimina <strong>3 alternativas de uma vez</strong>, deixando você entre duas!</li>\n<li>Compare apenas o item restante que desempata as duas opções!</li>\n</ol>\n<h4 id=\"️️-3-questões-finais-dissecadas-integrando-tudo\">🕵️‍♂️ 3 Questões Finais Dissecadas (Integrando Tudo)</h4>\n<p><strong>Desafio Final 1 (Estilo Molde 1 — Integração SQL + Web + Redes):</strong> <em>Analise: I. <code>ALTER TABLE usuarios ADD telefone VARCHAR(20)</code> pertence à DDL. II. <code>&lt;a href=\"pagina.html\" target=\"_blank\"&gt;</code> abre o link em uma nova aba, mantendo a atual aberta. III. O protocolo IMAP baixa os e-mails e os apaga imediatamente do servidor remoto para economizar espaço.</em></p>\n<ul>\n<li><strong>Análise:</strong> I é V (ALTER é estrutura = DDL). II é V (<code>_blank</code> = nova aba). <strong>III é F</strong> (quem apaga por padrão após baixar é o <strong>POP3</strong>; IMAP mantém sincronizado no servidor). <strong>Gabarito: I e II corretas.</strong></li>\n</ul>\n<p><strong>Desafio Final 2 (Estilo Molde 4 — Integração Matriz + Lógica + Casting):</strong> <em>Dada <code>M = [[4, 2], [9, 6]]</code> e o código: <code>double media = (M[0][0] + M[1][1]) / 3.0; int final = (int) media;</code>. Qual o valor de <code>final</code> e o nome do processo que gerou <code>final</code>?</em></p>\n<ul>\n<li><strong>Passo a passo:</strong> <code>M[0][0] + M[1][1]</code> (diagonal principal!) = <code>4 + 6 = 10</code>. Divisão real: <code>10 / 3.0 = 3.333...</code>. <code>(int) 3.333...</code> trunca para <strong><code>3</code></strong>, através de <strong>Conversão Explícita (<em>Type Casting</em>)</strong>.</li>\n</ul>\n<p><strong>Desafio Final 3 (Estilo M-Tec Base Comum — Matemática + Química):</strong> <em>Considerando <code>H=1, C=12, O=16</code>, calcule a massa molar de <code>CH₃COOH</code> (<code>C₂H₄O₂</code>) e determine quantos números ímpares de 2 algarismos distintos existem usando <code>{0, 1, 2, 3}</code>.</em></p>\n<ul>\n<li><strong>Química:</strong> <code>C₂H₄O₂</code> = <code>2(12) + 4(1) + 2(16) = 24 + 4 + 32 =</code> <strong><code>60 g/mol</code></strong>.</li>\n<li><strong>Matemática:</strong> Queremos número <strong>ímpar</strong> de 2 dígitos distintos com <code>{0, 1, 2, 3}</code>. Começamos pela restrição mais forte (<strong>unidade</strong> tem que ser ímpar → <code>1</code> ou <code>3</code> = <strong>2 opções</strong>). Depois na <strong>dezena</strong>, não pode <code>0</code> nem o ímpar já gasto na unidade (ex.: se gastou <code>1</code>, sobram <code>{2, 3}</code> = <strong>2 opções</strong>). Total = <code>2 × 2 =</code> <strong><code>4 números</code></strong> (<code>13, 21, 23, 31</code> — batendo exatamente!).</li>\n</ul>\n<hr />\n<h3 id=\"-parte-3--estratégia-de-execução-no-dia-da-prova-sexta-04122026\">📚 Parte 3 — Estratégia de Execução no Dia da Prova (Sexta, 04/12/2026)</h3>\n<ol>\n<li><strong>Regra das 3 Passadas (Gestão de Tempo):</strong>\n<ul>\n<li><strong>1ª Passada (45–60 min) — \"Colheita Rápida\":</strong> Responda primeiro tudo que for definição direta e reconhecimento rápido (Inglês, Ética, SQL sublinguagens, E-mail, Cookies, Cores/Vetor, História/Literatura). Viu teste de mesa grande ou conta longa de geometria? Faça um círculo no número e <strong>pule temporariamente</strong> — todas as questões têm o mesmo peso!</li>\n<li><strong>2ª Passada (60 min) — \"Contas &amp; I-II-III\":</strong> Resolva com calma os <strong>Testes de Mesa</strong>, <strong>Matrizes</strong>, <strong>Binário/Hex</strong>, <strong>Conjuntos</strong>, <strong>Contagem</strong> e <strong>Química</strong>, <strong>sempre escrevendo o passo a passo no rascunho da prova</strong>!</li>\n<li><strong>3ª Passada (últimos 30 min) — \"Conferência &amp; Gabarito\":</strong> Ataque as 2 ou 3 difíceis restantes, preencha o <strong>cartão-resposta</strong> conferindo questão por questão em voz mental baixa (<em>\"Questão 14... letra C!\"</em>) e <strong>nunca deixe nenhuma questão em branco</strong>.</li>\n</ul></li>\n<li><strong>Checklist de Véspera (Quinta, 03/12):</strong>\n<ul>\n<li>Separe <strong>RG/documento oficial original com foto</strong>, comprovante/local de prova, <strong>2 canetas esferográficas pretas/azuis de corpo transparente</strong> e garrafa de água sem rótulo;</li>\n<li>Releia apenas a <strong>Cola de Bolso</strong> (aba <em>Apostila &amp; Cola</em>) por 15 minutos e <strong>durma pelo menos 8 horas</strong> — o cérebro consolida memórias e fica afiado contra pegadinhas quando está descansado. <strong>Você cobriu 100% da prova — confie no seu preparo e arrebente!</strong></li>\n</ul></li>\n</ol>\n", "practiceType": "cards", "practiceTag": "REVIEW", "videoClips": [{"title": "Revisão Turbo 3 min: Normalização 1ª Forma Normal (1FN)", "channel": "Bóson Treinamentos", "videoId": "eRaAMNjCFYw", "startSec": 90, "endSec": 270, "tip": "Foco: revisão relâmpago do conceito mais cobrado em Banco de Dados na FAT."}, {"title": "Revisão Turbo 2 min: RGB vs. CMYK e Vetor vs. Bitmap", "channel": "Curso de Design Digital", "videoId": "wU6rwo-SeIw", "startSec": 20, "endSec": 150, "tip": "Foco: revisão relâmpago de Design Digital para não errar pegadinha boba na véspera."}], "challengeRefs": [{"examId": "sim1", "qNum": 13}, {"examId": "sim1", "qNum": 19}, {"examId": "sim1", "qNum": 23}, {"examId": "apostas", "qNum": 1}, {"examId": "apostas", "qNum": 17}, {"examId": "apostas", "qNum": 21}, {"examId": "apostas", "qNum": 27}, {"examId": "apostas", "qNum": 29}, {"examId": "mtec2022", "qNum": 20}, {"examId": "mtec2022", "qNum": 40}]}]};
